-- 성경 본문(public.bible)을 원본(goodtvbible.goodtv.co.kr)과 일치시킨다
--
-- 배경: 최초 적재분이 100자 근처에서 잘려 있었고, 일부 문자가 깨졌으며(누가복음 라벨 포함),
--       구역 제목으로 쪼개진 하반절이 paragraph=0 행으로 중복 저장돼 있었다.
-- 목표 형식: (구역 시작 절이면) "<구역제목> " + 원본 본문. 원본의 ○(문단 표시)는 보존하고,
--            표시 시 제거는 프론트가 담당한다.
-- 검증: 1,189개 장 전수 대조 (docs/bible-sync-plan.md)

-- 1) 본문 교정 5538행 (잘림·문자 깨짐·구역제목/○ 복원)
update "public"."bible" b
set "sentence" = v.sentence
from (values
    (143::bigint, '○여호와께서 사람의 죄악이 세상에 가득함과 그의 마음으로 생각하는 모든 계획이 항상 악할 뿐임을 보시고'),
    (147, '<노아의 족보> ○이것이 노아의 족보니라 노아는 의인이요 당대에 완전한 자라 그는 하나님과 동행하였으며'),
    (151, '○하나님이 노아에게 이르시되 모든 혈육 있는 자의 포악함이 땅에 가득하므로 그 끝 날이 내 앞에 이르렀으니 내가 그들을 땅과 함께 멸하리라'),
    (112, '○셋은 백오 세에 에노스를 낳았고'),
    (115, '○에노스는 구십 세에 게난을 낳았고'),
    (118, '○게난은 칠십 세에 마할랄렐을 낳았고'),
    (121, '○마할랄렐은 육십오 세에 야렛을 낳았고'),
    (124, '○야렛은 백육십이 세에 에녹을 낳았고'),
    (127, '○에녹은 육십오 세에 므두셀라를 낳았고'),
    (131, '○므두셀라는 백팔십칠 세에 라멕을 낳았고'),
    (134, '○라멕은 백팔십이 세에 아들을 낳고'),
    (138, '○노아는 오백 세 된 후에 셈과 함과 야벳을 낳았더라'),
    (6, '○하나님이 이르시되 물 가운데에 궁창이 있어 물과 물로 나뉘라 하시고'),
    (9, '○하나님이 이르시되 천하의 물이 한 곳으로 모이고 뭍이 드러나라 하시니 그대로 되니라'),
    (14, '○하나님이 이르시되 하늘의 궁창에 광명체들이 있어 낮과 밤을 나뉘게 하고 그것들로 징조와 계절과 날과 해를 이루게 하라'),
    (20, '○하나님이 이르시되 물들은 생물을 번성하게 하라 땅 위 하늘의 궁창에는 새가 날으라 하시고'),
    (24, '○하나님이 이르시되 땅은 생물을 그 종류대로 내되 가축과 기는 것과 땅의 짐승을 종류대로 내라 하시니 그대로 되니라'),
    (93, '가인이 여호와께 아뢰되 내 죄벌이 지기가 너무 무거우니이다'),
    (96, '<가인의 자손> ○가인이 여호와 앞을 떠나서 에덴 동쪽 놋 땅에 거주하더니'),
    (105, '<셋과 에노스> ○아담이 다시 자기 아내와 동침하매 그가 아들을 낳아 그의 이름을 셋이라 하였으니 이는 하나님이 내게 가인이 죽인 아벨 대신에 다른 씨를 주셨다 함이며'),
    (35, '<에덴 동산> ○이것이 천지가 창조될 때에 하늘과 땅의 내력이니 여호와 하나님이 땅과 하늘을 만드시던 날에'),
    (49, '○여호와 하나님이 이르시되 사람이 혼자 사는 것이 좋지 아니하니 내가 그를 위하여 돕는 배필을 지으리라 하시니라'),
    (50, '여호와 하나님이 흙으로 각종 들짐승과 공중의 각종 새를 지으시고 아담이 무엇이라고 부르나 보시려고 그것들을 그에게로 이끌어 가시니 아담이 각 생물을 부르는 것이 곧 그 이름이 되었더라'),
    (57, '<사람의 불순종과 하나님의 심판 선언> 그런데 뱀은 여호와 하나님이 지으신 들짐승 중에 가장 간교하니라 뱀이 여자에게 물어 이르되 하나님이 참으로 너희에게 동산 모든 나무의 열매를 먹지 말라 하시더냐'),
    (78, '<아담과 하와를 쫓아내시다> ○여호와 하나님이 이르시되 보라 이 사람이 선악을 아는 일에 우리 중 하나 같이 되었으니 그가 그의 손을 들어 생명 나무 열매도 따먹고 영생할까 하노라 하시고'),
    (166, '○홍수가 땅에 있을 때에 노아가 육백 세라'),
    (173, '○곧 그 날에 노아와 그의 아들 셈, 함, 야벳과 노아의 아내와 세 며느리가 다 방주로 들어갔고'),
    (190, '○사십 일을 지나서 노아가 그 방주에 낸 창문을 열고'),
    (197, '○육백일 년 첫째 달 곧 그 달 초하룻날에 땅 위에서 물이 걷힌지라 노아가 방주 뚜껑을 제치고 본즉 지면에서 물이 걷혔더니'),
    (204, '<노아가 번제를 드리다> ○노아가 여호와께 제단을 쌓고 모든 정결한 짐승과 모든 정결한 새 중에서 제물을 취하여 번제로 제단에 드렸더니'),
    (205, '여호와께서 그 향기를 받으시고 그 중심에 이르시되 내가 다시는 사람으로 말미암아 땅을 저주하지 아니하리니 이는 사람의 마음이 계획하는 바가 어려서부터 악함이라 내가 전에 행한 것 같이 모든 생물을 다시 멸하지 아니하리니'),
    (309, '<아브람이 애굽으로 내려가다> ○그 땅에 기근이 들었으므로 아브람이 애굽에 거류하려고 그리로 내려갔으니 이는 그 땅에 기근이 심하였음이라'),
    (273, '여호와께서 이르시되 이 무리가 한 족속이요 언어도 하나이므로 이같이 시작하였으니 이 후로는 그 하고자 하는 일을 막을 수 없으리로다'),
    (277, '<셈의 족보> ○셈의 족보는 이러하니라 셈은 백 세 곧 홍수 후 이 년에 아르박삿을 낳았고'),
    (294, '<데라의 족보> ○데라의 족보는 이러하니라 데라는 아브람과 나홀과 하란을 낳고 하란은 롯을 낳았으며'),
    (236, '<노아의 아들들의 족보> 노아의 아들 셈과 함과 야벳의 족보는 이러하니라 홍수 후에 그들이 아들들을 낳았으니'),
    (241, '○함의 아들은 구스와 미스라임과 붓과 가나안이요'),
    (250, '○가나안은 장자 시돈과 헷을 낳고'),
    (256, '○셈은 에벨 온 자손의 조상이요 야벳의 형이라 그에게도 자녀가 출생하였으니'),
    (261, '욕단은 알모닷과 셀렙과 하살마웻과 예라와'),
    (267, '○이들은 그 백성들의 족보에 따르면 노아 자손의 족속들이요 홍수 후에 이들에게서 그 땅의 백성들이 나뉘었더라'),
    (320, '<아브람과 롯이 서로 떠나다> 아브람이 애굽에서 그와 그의 아내와 모든 소유와 롯과 함께 네게브로 올라가니'),
    (333, '<아브람이 헤브론으로 옮기다> ○롯이 아브람을 떠난 후에 여호와께서 아브람에게 이르시되 너는 눈을 들어 너 있는 곳에서 북쪽과 남쪽 그리고 동쪽과 서쪽을 바라보라'),
    (214, '○하나님이 노아와 그와 함께 한 아들들에게 말씀하여 이르시되'),
    (224, '<노아와 그 아들들> ○방주에서 나온 노아의 아들들은 셈과 함과 야벳이며 함은 가나안의 아버지라'),
    (226, '○노아가 농사를 시작하여 포도나무를 심었더니'),
    (234, '○홍수 후에 노아가 삼백오십 년을 살았고'),
    (345, '소돔 왕과 고모라 왕과 아드마 왕과 스보임 왕과 벨라 곧 소알 왕이 나와서 싯딤 골짜기에서 그들과 전쟁을 하기 위하여 진을 쳤더니'),
    (350, '○도망한 자가 와서 히브리 사람 아브람에게 알리니 그 때에 아브람이 아모리 족속 마므레의 상수리 수풀 근처에 거주하였더라 마므레는 에스골의 형제요 또 아넬의 형제라 이들은 아브람과 동맹한 사람들이더라'),
    (354, '<멜기세덱이 아브람에게 축복하다> ○아브람이 그돌라오멜과 그와 함께 한 왕들을 쳐부수고 돌아올 때에 소돔 왕이 사웨 골짜기 곧 왕의 골짜기로 나와 그를 영접하였고'),
    (373, '○해 질 때에 아브람에게 깊은 잠이 임하고 큰 흑암과 두려움이 그에게 임하였더니'),
    (387, '사래가 아브람에게 이르되 내가 받는 모욕은 당신이 받아야 옳도다 내가 나의 여종을 당신의 품에 두었거늘 그가 자기의 임신함을 알고 나를 멸시하니 당신과 나 사이에 여호와께서 판단하시기를 원하노라'),
    (397, '○하갈이 아브람의 아들을 낳으매 아브람이 하갈이 낳은 그 아들을 이름하여 이스마엘이라 하였더라'),
    (407, '○하나님이 또 아브라함에게 이르시되 그런즉 너는 내 언약을 지키고 네 후손도 대대로 지키라'),
    (413, '○하나님이 또 아브라함에게 이르시되 네 아내 사래는 이름을 사래라 하지 말고 사라라 하라'),
    (421, '○이에 아브라함이 하나님이 자기에게 말씀하신 대로 이 날에 그 아들 이스마엘과 집에서 태어난 모든 자와 돈으로 산 모든 자 곧 아브라함의 집 사람 중 모든 남자를 데려다가 그 포피를 베었으니'),
    (441, '<아브라함이 소돔을 위하여 빌다> ○그 사람들이 거기서 일어나서 소돔으로 향하고 아브라함은 그들을 전송하러 함께 나가니라'),
    (444, '내가 그로 그 자식과 권속에게 명하여 여호와의 도를 지켜 의와 공도를 행하게 하려고 그를 택하였나니 이는 나 여호와가 아브라함에게 대하여 말한 일을 이루려 함이니라'),
    (447, '○그 사람들이 거기서 떠나 소돔으로 향하여 가고 아브라함은 여호와 앞에 그대로 섰더니'),
    (455, '아브라함이 이르되 내 주여 노하지 마시옵고 말씀하게 하옵소서 거기서 삼십 명을 찾으시면 어찌 하려 하시나이까 이르시되 내가 거기서 삼십 명을 찾으면 그리하지 아니하리라'),
    (504, '○아비멜렉이 그 날 아침에 일찍이 일어나 모든 종들을 불러 그 모든 일을 말하여 들려 주니 그들이 심히 두려워하였더라'),
    (505, '아비멜렉이 아브라함을 불러서 그에게 이르되 네가 어찌하여 우리에게 이렇게 하느냐 내가 무슨 죄를 네게 범하였기에 네가 나와 내 나라가 큰 죄에 빠질 뻔하게 하였느냐 네가 합당하지 아니한 일을 내게 행하였도다 하고'),
    (509, '하나님이 나를 내 아버지의 집을 떠나 두루 다니게 하실 때에 내가 아내에게 말하기를 이 후로 우리의 가는 곳마다 그대는 나를 그대의 오라비라 하라 이것이 그대가 내게 베풀 은혜라 하였었노라'),
    (568, '<나홀의 후예> ○이 일 후에 어떤 사람이 아브라함에게 알리어 이르기를 밀가가 당신의 형제 나홀에게 자녀를 낳았다 하였더라'),
    (578, '내 주여 들으소서 당신은 우리 가운데 있는 하나님이 세우신 지도자이시니 우리 묘실 중에서 좋은 것을 택하여 당신의 죽은 자를 장사하소서 우리 중에서 자기 묘실에 당신의 죽은 자 장사함을 금할 자가 없으리이다'),
    (585, '그 땅의 백성이 듣는 데서 에브론에게 말하여 이르되 당신이 합당히 여기면 청하건대 내 말을 들으시오 내가 그 밭 값을 당신에게 주리니 당신은 내게서 받으시오 내가 나의 죽은 자를 거기 장사하겠노라'),
    (466, '내게 남자를 가까이 하지 아니한 두 딸이 있노라 청하건대 내가 그들을 너희에게로 이끌어 내리니 너희 눈에 좋을 대로 그들에게 행하고 이 사람들은 내 집에 들어왔은즉 이 사람들에게는 아무 일도 저지르지 말라'),
    (467, '그들이 이르되 너는 물러나라 또 이르되 이 자가 들어와서 거류하면서 우리의 법관이 되려 하는도다 이제 우리가 그들보다 너를 더 해하리라 하고 롯을 밀치며 가까이 가서 그 문을 부수려고 하는지라'),
    (470, '<롯이 소돔을 떠나다> ○그 사람들이 롯에게 이르되 이 외에 네게 속한 자가 또 있느냐 네 사위나 자녀나 성 중에 네게 속한 자들을 다 성 밖으로 이끌어 내라'),
    (481, '<소돔과 고모라를 멸하시다> ○롯이 소알에 들어갈 때에 해가 돋았더라'),
    (487, '○하나님이 그 지역의 성을 멸하실 때 곧 롯이 거주하는 성을 엎으실 때에 하나님이 아브라함을 생각하사 롯을 그 엎으시는 중에서 내보내셨더라'),
    (488, '<모압과 암몬 자손의 조상> ○롯이 소알에 거주하기를 두려워하여 두 딸과 함께 소알에서 나와 산에 올라가 거주하되 그 두 딸과 함께 굴에 거주하였더니'),
    (492, '이튿날 큰 딸이 작은 딸에게 이르되 어제 밤에는 내가 우리 아버지와 동침하였으니 오늘 밤에도 우리가 아버지에게 술을 마시게 하고 네가 들어가 동침하고 우리가 아버지로 말미암아 후손을 이어가자 하고'),
    (522, '<하갈과 이스마엘을 내쫓다> ○아이가 자라매 젖을 떼고 이삭이 젖을 떼는 날에 아브라함이 큰 잔치를 베풀었더라'),
    (536, '<아브라함과 아비멜렉의 언약> ○그 때에 아비멜렉과 그 군대 장관 비골이 아브라함에게 말하여 이르되 네가 무슨 일을 하든지 하나님이 너와 함께 계시도다'),
    (537, '그런즉 너는 나와 내 아들과 내 손자에게 거짓되이 행하지 아니하기를 이제 여기서 하나님을 가리켜 내게 맹세하라 내가 네게 후대한 대로 너도 나와 네가 머무는 이 땅에 행할 것이니라'),
    (671, '<이스마엘의 후예> ○사라의 여종 애굽인 하갈이 아브라함에게 낳은 아들 이스마엘의 족보는 이러하고'),
    (678, '<에서와 야곱이 태어나다> ○아브라함의 아들 이삭의 족보는 이러하니라 아브라함이 이삭을 낳았고'),
    (686, '<에서가 장자의 명분을 팔다> ○그 아이들이 장성하매 에서는 익숙한 사냥꾼이었으므로 들사람이 되고 야곱은 조용한 사람이었으므로 장막에 거주하니'),
    (733, '○이삭이 그의 아들 에서에게 말할 때에 리브가가 들었더니 에서가 사냥하여 오려고 들로 나가매'),
    (747, '야곱이 아버지에게 대답하되 나는 아버지의 맏아들 에서로소이다 아버지께서 내게 명하신 대로 내가 하였사오니 원하건대 일어나 앉아서 내가 사냥한 고기를 잡수시고 아버지 마음껏 내게 축복하소서'),
    (762, '에서가 그의 아버지의 말을 듣고 소리 질러 슬피 울며 아버지에게 이르되 내 아버지여 내게 축복하소서 내게도 그리하소서'),
    (764, '에서가 이르되 그의 이름을 야곱이라 함이 합당하지 아니하니이까 그가 나를 속임이 이것이 두 번째니이다 전에는 나의 장자의 명분을 빼앗고 이제는 내 복을 빼앗았나이다 또 이르되 아버지께서 나를 위하여 빌 복을 남기지 아니하셨나이까'),
    (774, '<이삭이 야곱을 라반에게 보내다> ○리브가가 이삭에게 이르되 내가 헷 사람의 딸들로 말미암아 내 삶이 싫어졌거늘 야곱이 만일 이 땅의 딸들 곧 그들과 같은 헷 사람의 딸들 중에서 아내를 맞이하면 내 삶이 내게 무슨 재미가 있으리이까'),
    (780, '<에서가 다른 아내를 맞이하다> ○에서가 본즉 이삭이 야곱에게 축복하고 그를 밧단아람으로 보내어 거기서 아내를 맞이하게 하였고 또 그에게 축복하고 명하기를 너는 가나안 사람의 딸들 중에서 아내를 맞이하지 말라 하였고'),
    (784, '<야곱이 벧엘에서 꿈을 꾸다> ○야곱이 브엘세바에서 떠나 하란으로 향하여 가더니'),
    (700, '그 곳 사람들이 그의 아내에 대하여 물으매 그가 말하기를 그는 내 누이라 하였으니 리브가는 보기에 아리따우므로 그 곳 백성이 리브가로 말미암아 자기를 죽일까 하여 그는 내 아내라 하기를 두려워함이었더라'),
    (705, '○이삭이 그 땅에서 농사하여 그 해에 백 배나 얻었고 여호와께서 복을 주시므로'),
    (715, '이삭이 거기서 옮겨 다른 우물을 팠더니 그들이 다투지 아니하였으므로 그 이름을 르호봇이라 하여 이르되 이제는 여호와께서 우리를 위하여 넓게 하셨으니 이 땅에서 우리가 번성하리로다 하였더라'),
    (716, '○이삭이 거기서부터 브엘세바로 올라갔더니'),
    (717, '그 밤에 여호와께서 그에게 나타나 이르시되 나는 네 아버지 아브라함의 하나님이니 두려워하지 말라 내 종 아브라함을 위하여 내가 너와 함께 있어 네게 복을 주어 네 자손이 번성하게 하리라 하신지라'),
    (719, '<이삭과 아비멜렉의 계약> ○아비멜렉이 그 친구 아훗삿과 군대 장관 비골과 더불어 그랄에서부터 이삭에게로 온지라'),
    (727, '<에서의 이방인 아내들> ○에서가 사십 세에 헷 족속 브에리의 딸 유딧과 헷 족속 엘론의 딸 바스맛을 아내로 맞이하였더니'),
    (599, '하늘의 하나님 여호와께서 나를 내 아버지의 집과 내 고향 땅에서 떠나게 하시고 내게 말씀하시며 내게 맹세하여 이르시기를 이 땅을 네 씨에게 주리라 하셨으니 그가 그 사자를 너보다 앞서 보내실지라 네가 거기서 내 아들을 위하여 아내를 택할지니라'),
    (602, '○이에 종이 그 주인의 낙타 중 열 필을 끌고 떠났는데 곧 그의 주인의 모든 좋은 것을 가지고 떠나 메소보다미아로 가서 나홀의 성에 이르러'),
    (606, '한 소녀에게 이르기를 청하건대 너는 물동이를 기울여 나로 마시게 하라 하리니 그의 대답이 마시라 내가 당신의 낙타에게도 마시게 하리라 하면 그는 주께서 주의 종 이삭을 위하여 정하신 자라 이로 말미암아 주께서 내 주인에게 은혜 베푸심을 내가 알겠나이다'),
    (619, '이르되 나의 주인 아브라함의 하나님 여호와를 찬송하나이다 나의 주인에게 주의 사랑과 성실을 그치지 아니하셨사오며 여호와께서 길에서 나를 인도하사 내 주인의 동생 집에 이르게 하셨나이다 하니라'),
    (620, '○소녀가 달려가서 이 일을 어머니 집에 알렸더니'),
    (642, '○라반과 브두엘이 대답하여 이르되 이 일이 여호와께로 말미암았으니 우리는 가부를 말할 수 없노라'),
    (653, '○리브가가 일어나 여자 종들과 함께 낙타를 타고 그 사람을 따라가니 그 종이 리브가를 데리고 가니라'),
    (817, '<야곱이 레아와 라헬을 아내로 맞다> ○야곱이 라반에게 이르되 내 기한이 찼으니 내 아내를 내게 주소서 내가 그에게 들어가겠나이다'),
    (827, '<야곱에게 아이들이 생기다> ○여호와께서 레아가 사랑 받지 못함을 보시고 그의 태를 여셨으나 라헬은 자녀가 없었더라'),
    (840, '○레아가 자기의 출산이 멈춤을 보고 그의 시녀 실바를 데려다가 야곱에게 주어 아내로 삼게 하였더니'),
    (845, '○밀 거둘 때 르우벤이 나가서 들에서 합환채를 얻어 그의 어머니 레아에게 드렸더니 라헬이 레아에게 이르되 언니의 아들의 합환채를 청구하노라'),
    (846, '레아가 그에게 이르되 네가 내 남편을 빼앗은 것이 작은 일이냐 그런데 네가 내 아들의 합환채도 빼앗고자 하느냐 라헬이 이르되 그러면 언니의 아들의 합환채 대신에 오늘 밤에 내 남편이 언니와 동침하리라 하니라'),
    (856, '<야곱이 라반과 품삯을 정하다> ○라헬이 요셉을 낳았을 때에 야곱이 라반에게 이르되 나를 보내어 내 고향 나의 땅으로 가게 하시되'),
    (864, '후일에 외삼촌께서 오셔서 내 품삯을 조사하실 때에 나의 의가 내 대답이 되리이다 내게 혹시 염소 중 아롱지지 아니한 것이나 점이 없는 것이나 양 중에 검지 아니한 것이 있거든 다 도둑질한 것으로 인정하소서'),
    (868, '○야곱이 버드나무와 살구나무와 신풍나무의 푸른 가지를 가져다가 그것들의 껍질을 벗겨 흰 무늬를 내고'),
    (971, '야곱이 이르되 그렇지 아니하니이다 내가 형님의 눈앞에서 은혜를 입었사오면 청하건대 내 손에서 이 예물을 받으소서 내가 형님의 얼굴을 뵈온즉 하나님의 얼굴을 본 것 같사오며 형님도 나를 기뻐하심이니이다'),
    (979, '○야곱이 밧단아람에서부터 평안히 가나안 땅 세겜 성읍에 이르러 그 성읍 앞에 장막을 치고'),
    (891, '○야곱이 일어나 자식들과 아내들을 낙타들에게 태우고'),
    (906, '외삼촌의 신을 누구에게서 찾든지 그는 살지 못할 것이요 우리 형제들 앞에서 무엇이든지 외삼촌의 것이 발견되거든 외삼촌에게로 가져가소서 하니 야곱은 라헬이 그것을 도둑질한 줄을 알지 못함이었더라'),
    (916, '우리 아버지의 하나님, 아브라함의 하나님 곧 이삭이 경외하는 이가 나와 함께 계시지 아니하셨더라면 외삼촌께서 이제 나를 빈손으로 돌려보내셨으리이다마는 하나님이 내 고난과 내 손의 수고를 보시고 어제 밤에 외삼촌을 책망하셨나이다'),
    (917, '<야곱과 라반의 언약> ○라반이 야곱에게 대답하여 이르되 딸들은 내 딸이요 자식들은 내 자식이요 양 떼는 내 양 떼요 네가 보는 것은 다 내 것이라 내가 오늘 내 딸들과 그들이 낳은 자식들에게 무엇을 하겠느냐'),
    (932, '○야곱이 세일 땅 에돔 들에 있는 형 에서에게로 자기보다 앞서 사자들을 보내며'),
    (942, '<야곱이 브니엘에서 씨름을 하다> ○야곱이 거기서 밤을 지내고 그 소유 중에서 형 에서를 위하여 예물을 택하니'),
    (957, '그가 이르되 네 이름을 다시는 야곱이라 부를 것이 아니요 이스라엘이라 부를 것이니 이는 네가 하나님과 및 사람들과 겨루어 이겼음이니라'),
    (1013, '<하나님이 야곱에게 복을 주시다> 하나님이 야곱에게 이르시되 일어나 벧엘로 올라가서 거기 거주하며 네가 네 형 에서의 낯을 피하여 도망하던 때에 네게 나타났던 하나님께 거기서 제단을 쌓으라 하신지라'),
    (1014, '야곱이 이에 자기 집안 사람과 자기와 함께 한 모든 자에게 이르되 너희 중에 있는 이방 신상들을 버리고 자신을 정결하게 하고 너희들의 의복을 바꾸어 입으라'),
    (1021, '○야곱이 밧단아람에서 돌아오매 하나님이 다시 야곱에게 나타나사 그에게 복을 주시고'),
    (1028, '<라헬이 산고로 죽다> ○그들이 벧엘에서 길을 떠나 에브랏에 이르기까지 얼마간 거리를 둔 곳에서 라헬이 해산하게 되어 심히 고생하여'),
    (1034, '<야곱의 아들들> 이스라엘이 그 땅에 거주할 때에 르우벤이 가서 그 아버지의 첩 빌하와 동침하매 이스라엘이 이를 들었더라 ○야곱의 아들은 열둘이라'),
    (1040, '<이삭이 죽다> ○야곱이 기럇아르바의 마므레로 가서 그의 아버지 이삭에게 이르렀으니 기럇아르바는 곧 아브라함과 이삭이 거류하던 헤브론이더라'),
    (999, '○그들의 말을 하몰과 그의 아들 세겜이 좋게 여기므로'),
    (1011, '야곱이 시므온과 레위에게 이르되 너희가 내게 화를 끼쳐 나로 하여금 이 땅의 주민 곧 가나안 족속과 브리스 족속에게 악취를 내게 하였도다 나는 수가 적은즉 그들이 모여 나를 치고 나를 죽이리니 그러면 나와 내 집이 멸망하리라'),
    (1087, '야곱의 족보는 이러하니라 요셉이 십칠 세의 소년으로서 그의 형들과 함께 양을 칠 때에 그의 아버지의 아내들 빌하와 실바의 아들들과 더불어 함께 있었더니 그가 그들의 잘못을 아버지에게 말하더라'),
    (1090, '○요셉이 꿈을 꾸고 자기 형들에게 말하매 그들이 그를 더욱 미워하였더라'),
    (1097, '<요셉이 애굽으로 팔려가다> ○그의 형들이 세겜에 가서 아버지의 양 떼를 칠 때에'),
    (1103, '○요셉이 그들에게 가까이 오기 전에 그들이 요셉을 멀리서 보고 죽이기를 꾀하여'),
    (1107, '르우벤이 또 그들에게 이르되 피를 흘리지 말라 그를 광야 그 구덩이에 던지고 손을 그에게 대지 말라 하니 이는 그가 요셉을 그들의 손에서 구출하여 그의 아버지에게로 돌려보내려 함이었더라'),
    (1110, '○그들이 앉아 음식을 먹다가 눈을 들어 본즉 한 무리의 이스마엘 사람들이 길르앗에서 오는데 그 낙타들에 향품과 유향과 몰약을 싣고 애굽으로 내려가는지라'),
    (1114, '○르우벤이 돌아와 구덩이에 이르러 본즉 거기 요셉이 없는지라 옷을 찢고'),
    (1043, '<에서의 자손> 에서 곧 에돔의 족보는 이러하니라'),
    (1051, '○세일 산에 있는 에돔 족속의 조상 에서의 족보는 이러하고'),
    (1057, '○에서 자손 중 족장은 이러하니라 에서의 장자 엘리바스의 자손으로는 데만 족장, 오말 족장, 스보 족장, 그나스 족장과'),
    (1060, '에서의 아내인 오홀리바마의 아들들은 여우스 족장, 얄람 족장, 고라 족장이니 이들은 아나의 딸이요 에서의 아내인 오홀리바마로 말미암아 나온 족장들이라'),
    (1062, '<세일의 자손> ○그 땅의 주민 호리 족속 세일의 자손은 로단과 소발과 시브온과 아나와'),
    (1073, '<에돔의 왕들> ○이스라엘 자손을 다스리는 왕이 있기 전에 에돔 땅을 다스리던 왕들은 이러하니라'),
    (1082, '○에서에게서 나온 족장들의 이름은 그 종족과 거처와 이름을 따라 나누면 이러하니 딤나 족장, 알와 족장, 여뎃 족장,'),
    (1133, '○얼마 후에 유다의 아내 수아의 딸이 죽은지라 유다가 위로를 받은 후에 그의 친구 아둘람 사람 히라와 함께 딤나로 올라가서 자기의 양털 깎는 자에게 이르렀더니'),
    (1139, '유다가 이르되 무슨 담보물을 네게 주랴 그가 이르되 당신의 도장과 그 끈과 당신의 손에 있는 지팡이로 하라 유다가 그것들을 그에게 주고 그에게로 들어갔더니 그가 유다로 말미암아 임신하였더라'),
    (1158, '○그 후에 그의 주인의 아내가 요셉에게 눈짓하다가 동침하기를 청하니'),
    (1170, '○그의 주인이 자기 아내가 자기에게 이르기를 당신의 종이 내게 이같이 행하였다 하는 말을 듣고 심히 노한지라'),
    (1183, '○술 맡은 관원장이 그의 꿈을 요셉에게 말하여 이르되 내가 꿈에 보니 내 앞에 포도나무가 있는데'),
    (1190, '○떡 굽는 관원장이 그 해석이 좋은 것을 보고 요셉에게 이르되 나도 꿈에 보니 흰 떡 세 광주리가 내 머리에 있고'),
    (1270, '너희 중 하나를 보내어 너희 아우를 데려오게 하고 너희는 갇히어 있으라 내가 너희의 말을 시험하여 너희 중에 진실이 있는지 보리라 바로의 생명으로 맹세하노니 그리하지 아니하면 너희는 과연 정탐꾼이니라 하고'),
    (1272, '○사흘 만에 요셉이 그들에게 이르되 나는 하나님을 경외하노니 너희는 이같이 하여 생명을 보전하라'),
    (1280, '<요셉의 형들이 가나안으로 돌아오다> ○그들이 곡식을 나귀에 싣고 그 곳을 떠났더니'),
    (1292, '야곱이 이르되 내 아들은 너희와 함께 내려가지 못하리니 그의 형은 죽고 그만 남았음이라 만일 너희가 가는 길에서 재난이 그에게 미치면 너희가 내 흰 머리를 슬퍼하며 스올로 내려가게 함이 되리라'),
    (1206, '○술 맡은 관원장이 바로에게 말하여 이르되 내가 오늘 내 죄를 기억하나이다'),
    (1211, '○이에 바로가 사람을 보내어 요셉을 부르매 그들이 급히 그를 옥에서 내 놓은지라 요셉이 곧 수염을 깎고 그의 옷을 갈아 입고 바로에게 들어가니'),
    (1215, '보니 살찌고 아름다운 일곱 암소가 나일 강 가에 올라와 갈밭에서 뜯어먹고'),
    (1222, '○요셉이 바로에게 아뢰되 바로의 꿈은 하나라 하나님이 그가 하실 일을 바로에게 보이심이니이다'),
    (1234, '<요셉이 애굽의 총리가 되다> ○바로와 그의 모든 신하가 이 일을 좋게 여긴지라'),
    (1243, '○요셉이 애굽 왕 바로 앞에 설 때에 삼십 세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니'),
    (1297, '아버지께서 만일 그를 보내지 아니하시면 우리는 내려가지 아니하리니 그 사람이 우리에게 말하기를 너희의 아우가 너희와 함께 오지 아니하면 너희가 내 얼굴을 보지 못하리라 하였음이니이다'),
    (1299, '그들이 이르되 그 사람이 우리와 우리의 친족에 대하여 자세히 질문하여 이르기를 너희 아버지가 아직 살아 계시느냐 너희에게 아우가 있느냐 하기로 그 묻는 말에 따라 그에게 대답한 것이니 그가 너희의 아우를 데리고 내려오라 할 줄을 우리가 어찌 알았으리이까'),
    (1303, '그들의 아버지 이스라엘이 그들에게 이르되 그러할진대 이렇게 하라 너희는 이 땅의 아름다운 소산을 그릇에 담아가지고 내려가서 그 사람에게 예물로 드릴지니 곧 유향 조금과 꿀 조금과 향품과 몰약과 유향나무 열매와 감복숭아이니라'),
    (1308, '○요셉은 베냐민이 그들과 함께 있음을 보고 자기의 청지기에게 이르되 이 사람들을 집으로 인도해 들이고 짐승을 잡고 준비하라 이 사람들이 정오에 나와 함께 먹을 것이니라'),
    (1310, '그 사람들이 요셉의 집으로 인도되매 두려워하여 이르되 전번에 우리 자루에 들어 있던 돈의 일로 우리가 끌려드는도다 이는 우리를 억류하고 달려들어 우리를 잡아 노예로 삼고 우리의 나귀를 빼앗으려 함이로다 하고'),
    (1315, '그가 이르되 너희는 안심하라 두려워하지 말라 너희 하나님, 너희 아버지의 하나님이 재물을 너희 자루에 넣어 너희에게 주신 것이니라 너희 돈은 내가 이미 받았느니라 하고 시므온을 그들에게로 이끌어내고'),
    (1340, '<유다가 베냐민을 위하여 인질을 청하다> ○유다와 그의 형제들이 요셉의 집에 이르니 요셉이 아직 그 곳에 있는지라 그의 앞에서 땅에 엎드리니'),
    (1342, '유다가 말하되 우리가 내 주께 무슨 말을 하오리이까 무슨 설명을 하오리이까 우리가 어떻게 우리의 정직함을 나타내리이까 하나님이 종들의 죄악을 찾아내셨으니 우리와 이 잔이 발견된 자가 다 내 주의 노예가 되겠나이다'),
    (1346, '우리가 내 주께 아뢰되 우리에게 아버지가 있으니 노인이요 또 그가 노년에 얻은 아들 청년이 있으니 그의 형은 죽고 그의 어머니가 남긴 것은 그뿐이므로 그의 아버지가 그를 사랑하나이다 하였더니'),
    (1361, '<요셉이 형제들에게 자기를 밝히다> 요셉이 시종하는 자들 앞에서 그 정을 억제하지 못하여 소리 질러 모든 사람을 자기에게서 물러가라 하고 그 형제들에게 자기를 알리니 그 때에 그와 함께 한 다른 사람이 없었더라'),
    (1376, '○요셉의 형들이 왔다는 소문이 바로의 궁에 들리매 바로와 그의 신하들이 기뻐하고'),
    (1381, '○이스라엘의 아들들이 그대로 할새 요셉이 바로의 명령대로 그들에게 수레를 주고 길 양식을 주며'),
    (1435, '<기근이 더욱 심해지다> ○기근이 더욱 심하여 사방에 먹을 것이 없고 애굽 땅과 가나안 땅이 기근으로 황폐하니'),
    (1436, '요셉이 곡식을 팔아 애굽 땅과 가나안 땅에 있는 돈을 모두 거두어 들이고 그 돈을 바로의 궁으로 가져가니'),
    (1440, '그 해가 다 가고 새 해가 되매 무리가 요셉에게 와서 그에게 말하되 우리가 주께 숨기지 아니하나이다 우리의 돈이 다하였고 우리의 가축 떼가 주께로 돌아갔사오니 주께 낼 것이 아무것도 남지 아니하고 우리의 몸과 토지뿐이라'),
    (1441, '우리가 어찌 우리의 토지와 함께 주의 목전에 죽으리이까 우리 몸과 우리 토지를 먹을 것을 주고 사소서 우리가 토지와 함께 바로의 종이 되리니 우리에게 종자를 주시면 우리가 살고 죽지 아니하며 토지도 황폐하게 되지 아니하리이다'),
    (1442, '○그러므로 요셉이 애굽의 모든 토지를 다 사서 바로에게 바치니 애굽의 모든 사람들이 기근에 시달려 각기 토지를 팔았음이라 땅이 바로의 소유가 되니라'),
    (1449, '<야곱의 마지막 청> ○이스라엘 족속이 애굽 고센 땅에 거주하며 거기서 생업을 얻어 생육하고 번성하였더라'),
    (1451, '이스라엘이 죽을 날이 가까우매 그의 아들 요셉을 불러 그에게 이르되 이제 내가 네게 은혜를 입었거든 청하노니 네 손을 내 허벅지 아래에 넣고 인애와 성실함으로 내게 행하여 애굽에 나를 장사하지 아니하도록 하라'),
    (1396, '○애굽으로 내려간 이스라엘 가족의 이름은 이러하니라 야곱과 그의 아들들 곧 야곱의 맏아들 르우벤과'),
    (1408, '애굽 땅에서 온 제사장 보디베라의 딸 아스낫이 요셉에게 낳은 므낫세와 에브라임이요'),
    (1409, '베냐민의 아들 곧 벨라와 베겔과 아스벨과 게라와 나아만과 에히와 로스와 뭅빔과 훕빔과 아릇이니'),
    (1416, '<야곱 일행이 애굽에 이르다> ○야곱이 유다를 요셉에게 미리 보내어 자기를 고센으로 인도하게 하고 다 고센 땅에 이르니'),
    (1422, '당신들은 이르기를 주의 종들은 어렸을 때부터 지금까지 목축하는 자들이온데 우리와 우리 선조가 다 그러하니이다 하소서 애굽 사람은 다 목축을 가증히 여기나니 당신들이 고센 땅에 살게 되리이다'),
    (1512, '○곡하는 기한이 지나매 요셉이 바로의 궁에 말하여 이르되 내가 너희에게 은혜를 입었으면 원하건대 바로의 귀에 아뢰기를'),
    (1523, '<요셉이 형들을 위로하다> ○요셉의 형제들이 그들의 아버지가 죽었음을 보고 말하되 요셉이 혹시 우리를 미워하여 우리가 그에게 행한 모든 악을 다 갚지나 아니할까 하고'),
    (1525, '너희는 이같이 요셉에게 이르라 네 형들이 네게 악을 행하였을지라도 이제 바라건대 그들의 허물과 죄를 용서하라 하셨나니 당신 아버지의 하나님의 종들인 우리 죄를 이제 용서하소서 하매 요셉이 그들이 그에게 하는 말을 들을 때에 울었더라'),
    (1530, '<요셉이 죽다> ○요셉이 그의 아버지의 가족과 함께 애굽에 거주하여 백십 세를 살며'),
    (1460, '내게 대하여는 내가 이전에 밧단에서 올 때에 라헬이 나를 따르는 도중 가나안 땅에서 죽었는데 그 곳은 에브랏까지 길이 아직도 먼 곳이라 내가 거기서 그를 에브랏 길에 장사하였느니라 (에브랏은 곧 베들레헴이라)'),
    (1461, '○이스라엘이 요셉의 아들들을 보고 이르되 이들은 누구냐'),
    (1469, '나를 모든 환난에서 건지신 여호와의 사자께서 이 아이들에게 복을 주시오며 이들로 내 이름과 내 조상 아브라함과 이삭의 이름으로 칭하게 하시오며 이들이 세상에서 번식되게 하시기를 원하나이다'),
    (1542, '○요셉을 알지 못하는 새 왕이 일어나 애굽을 다스리더니'),
    (1549, '○애굽 왕이 히브리 산파 십브라라 하는 사람과 부아라 하는 사람에게 말하여'),
    (1567, '<모세가 미디안으로 피하다> ○모세가 장성한 후에 한번은 자기 형제들에게 나가서 그들이 고되게 노동하는 것을 보더니 어떤 애굽 사람이 한 히브리 사람 곧 자기 형제를 치는 것을 본지라'),
    (1572, '○미디안 제사장에게 일곱 딸이 있었더니 그들이 와서 물을 길어 구유에 채우고 그들의 아버지의 양 떼에게 먹이려 하는데'),
    (1579, '○여러 해 후에 애굽 왕은 죽었고 이스라엘 자손은 고된 노동으로 말미암아 탄식하며 부르짖으니 그 고된 노동으로 말미암아 부르짖는 소리가 하나님께 상달된지라'),
    (1589, '내가 내려가서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 데려가려 하노라'),
    (1594, '○모세가 하나님께 아뢰되 내가 이스라엘 자손에게 가서 이르기를 너희의 조상의 하나님이 나를 너희에게 보내셨다 하면 그들이 내게 묻기를 그의 이름이 무엇이냐 하리니 내가 무엇이라고 그들에게 말하리이까'),
    (1596, '○하나님이 또 모세에게 이르시되 너는 이스라엘 자손에게 이같이 이르기를 너희 조상의 하나님 여호와 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님께서 나를 너희에게 보내셨다 하라 이는 나의 영원한 이름이요 대대로 기억할 나의 칭호니라'),
    (1597, '너는 가서 이스라엘의 장로들을 모으고 그들에게 이르기를 여호와 너희 조상의 하나님 곧 아브라함과 이삭과 야곱의 하나님이 내게 나타나 이르시되 내가 너희를 돌보아 너희가 애굽에서 당한 일을 확실히 보았노라'),
    (1598, '내가 말하였거니와 내가 너희를 애굽의 고난 중에서 인도하여 내어 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 땅으로 올라가게 하리라 하셨다 하면'),
    (1599, '그들이 네 말을 들으리니 너는 그들의 장로들과 함께 애굽 왕에게 이르기를 히브리 사람의 하나님 여호와께서 우리에게 임하셨은즉 우리가 우리 하나님 여호와께 제사를 드리려 하오니 사흘길쯤 광야로 가도록 허락하소서 하라'),
    (1635, '<모세와 아론이 바로 앞에 서다> 그 후에 모세와 아론이 바로에게 가서 이르되 이스라엘의 하나님 여호와께서 이렇게 말씀하시기를 내 백성을 보내라 그러면 그들이 광야에서 내 앞에 절기를 지킬 것이니라 하셨나이다'),
    (1637, '그들이 이르되 히브리인의 하나님이 우리에게 나타나셨은즉 우리가 광야로 사흘길쯤 가서 우리 하나님 여호와께 제사를 드리려 하오니 가도록 허락하소서 여호와께서 전염병이나 칼로 우리를 치실까 두려워하나이다'),
    (1644, '○백성의 감독들과 기록원들이 나가서 백성에게 말하여 이르되 바로가 이렇게 말하기를 내가 너희에게 짚을 주지 아니하리니'),
    (1649, '○이스라엘 자손의 기록원들이 가서 바로에게 호소하여 이르되 왕은 어찌하여 당신의 종들에게 이같이 하시나이까'),
    (1656, '<모세가 여호와께 아뢰다> ○모세가 여호와께 돌아와서 아뢰되 주여 어찌하여 이 백성이 학대를 당하게 하셨나이까 어찌하여 나를 보내셨나이까'),
    (1613, '○모세가 여호와께 아뢰되 오 주여 나는 본래 말을 잘 하지 못하는 자니이다 주께서 주의 종에게 명령하신 후에도 역시 그러하니 나는 입이 뻣뻣하고 혀가 둔한 자니이다'),
    (1617, '여호와께서 모세를 향하여 노하여 이르시되 레위 사람 네 형 아론이 있지 아니하냐 그가 말 잘 하는 것을 내가 아노라 그가 너를 만나러 나오나니 그가 너를 볼 때에 그의 마음에 기쁨이 있을 것이라'),
    (1621, '<모세가 애굽으로 돌아가다> ○모세가 그의 장인 이드로에게로 돌아가서 그에게 이르되 내가 애굽에 있는 내 형제들에게로 돌아가서 그들이 아직 살아 있는지 알아보려 하오니 나로 가게 하소서 이드로가 모세에게 평안히 가라 하니라'),
    (1630, '○여호와께서 아론에게 이르시되 광야에 가서 모세를 맞으라 하시매 그가 가서 하나님의 산에서 모세를 만나 그에게 입맞추니'),
    (1720, '○바로가 모세와 아론을 불러 이르되 여호와께 구하여 나와 내 백성에게서 개구리를 떠나게 하라 내가 이 백성을 보내리니 그들이 여호와께 제사를 드릴 것이니라'),
    (1728, '<셋째 재앙 : 티끌이 이가 되다> ○여호와께서 모세에게 이르시되 아론에게 명령하기를 네 지팡이를 들어 땅의 티끌을 치라 하라 그것이 애굽 온 땅에서 이가 되리라'),
    (1732, '<넷째 재앙 : 파리가 가득하다> ○여호와께서 모세에게 이르시되 아침에 일찍이 일어나 바로 앞에 서라 그가 물 있는 곳으로 나오리니 그에게 이르기를 여호와께서 이와 같이 말씀하시기를 내 백성을 보내라 그러면 그들이 나를 섬길 것이니라'),
    (1737, '○바로가 모세와 아론을 불러 이르되 너희는 가서 이 땅에서 너희 하나님께 제사를 드리라'),
    (1738, '모세가 이르되 그리함은 부당하니이다 우리가 우리 하나님 여호와께 제사를 드리는 것은 애굽 사람이 싫어하는 바인즉 우리가 만일 애굽 사람의 목전에서 제사를 드리면 그들이 그것을 미워하여 우리를 돌로 치지 아니하리이까'),
    (1741, '모세가 이르되 내가 왕을 떠나가서 여호와께 간구하리니 내일이면 파리 떼가 바로와 바로의 신하와 바로의 백성을 떠나려니와 바로는 이 백성을 보내어 여호와께 제사를 드리는 일에 다시 거짓을 행하지 마소서 하고'),
    (1695, '<뱀이 된 아론의 지팡이> ○여호와께서 모세와 아론에게 말씀하여 이르시되'),
    (1701, '<첫째 재앙 : 물이 피가 되다> ○여호와께서 모세에게 이르시되 바로의 마음이 완강하여 백성 보내기를 거절하는도다'),
    (1706, '여호와께서 또 모세에게 이르시되 아론에게 명령하기를 네 지팡이를 잡고 네 팔을 애굽의 물들과 강들과 운하와 못과 모든 호수 위에 내밀라 하라 그것들이 피가 되리니 애굽 온 땅과 나무 그릇과 돌 그릇 안에 모두 피가 있으리라'),
    (1707, '○모세와 아론이 여호와께서 명령하신 대로 행하여 바로와 그의 신하의 목전에서 지팡이를 들어 나일 강을 치니 그 물이 다 피로 변하고'),
    (1752, '<여섯째 재앙 : 악성 종기가 생기다> ○여호와께서 모세와 아론에게 이르시되 너희는 화덕의 재 두 움큼을 가지고 모세가 바로의 목전에서 하늘을 향하여 날리라'),
    (1757, '<일곱째 재앙 : 우박이 내리다> ○여호와께서 모세에게 이르시되 아침에 일찍이 일어나 바로 앞에 서서 그에게 이르기를 히브리 사람의 하나님 여호와의 말씀에 내 백성을 보내라 그들이 나를 섬길 것이니라'),
    (1763, '이제 사람을 보내어 네 가축과 네 들에 있는 것을 다 모으라 사람이나 짐승이나 무릇 들에 있어서 집에 돌아오지 않는 것들에게는 우박이 그 위에 내리리니 그것들이 죽으리라 하셨다 하라 하시니라'),
    (1766, '○여호와께서 모세에게 이르시되 너는 하늘을 향하여 손을 들어 애굽 전국에 우박이 애굽 땅의 사람과 짐승과 밭의 모든 채소에 내리게 하라'),
    (1771, '○바로가 사람을 보내어 모세와 아론을 불러 그들에게 이르되 이번은 내가 범죄하였노라 여호와는 의로우시고 나와 나의 백성은 악하도다'),
    (1785, '또 네 집들과 네 모든 신하의 집들과 모든 애굽 사람의 집들에 가득하리니 이는 네 아버지와 네 조상이 이 땅에 있었던 그 날로부터 오늘까지 보지 못하였던 것이리라 하셨다 하고 돌이켜 바로에게서 나오니'),
    (1786, '바로의 신하들이 그에게 말하되 어느 때까지 이 사람이 우리의 함정이 되리이까 그 사람들을 보내어 그들의 하나님 여호와를 섬기게 하소서 왕은 아직도 애굽이 망한 줄을 알지 못하시나이까 하고'),
    (1791, '○여호와께서 모세에게 이르시되 애굽 땅 위에 네 손을 내밀어 메뚜기를 애굽 땅에 올라오게 하여 우박에 상하지 아니한 밭의 모든 채소를 먹게 하라'),
    (1800, '<아홉째 재앙 : 흑암이 땅에 있다> ○여호와께서 모세에게 이르시되 하늘을 향하여 네 손을 내밀어 애굽 땅 위에 흑암이 있게 하라 곧 더듬을 만한 흑암이리라'),
    (1805, '우리의 가축도 우리와 함께 가고 한 마리도 남길 수 없으니 이는 우리가 그 중에서 가져다가 우리 하나님 여호와를 섬길 것임이며 또 우리가 거기에 이르기까지는 어떤 것으로 여호와를 섬길는지 알지 못함이니이다 하나'),
    (1809, '<처음 난 것의 죽음을 경고하다> 여호와께서 모세에게 이르시기를 내가 이제 한 가지 재앙을 바로와 애굽에 내린 후에야 그가 너희를 여기서 내보내리라 그가 너희를 내보낼 때에는 여기서 반드시 다 쫓아내리니'),
    (1812, '○모세가 바로에게 이르되 여호와께서 이와 같이 말씀하시기를 밤중에 내가 애굽 가운데로 들어가리니'),
    (1817, '○여호와께서 모세에게 이르시기를 바로가 너희의 말을 듣지 아니하리라 그러므로 내가 애굽 땅에서 나의 기적을 더하리라 하셨고'),
    (1659, '<하나님이 모세를 부르시다> ○하나님이 모세에게 말씀하여 이르시되 나는 여호와이니라'),
    (1667, '○여호와께서 모세에게 말씀하여 이르시되'),
    (1670, '○여호와께서 모세와 아론에게 말씀하사 그들로 이스라엘 자손과 애굽 왕 바로에게 명령을 전하고 이스라엘 자손을 애굽 땅에서 인도하여 내게 하시니라'),
    (1671, '<모세와 아론의 조상> ○그들의 조상을 따라 집의 어른은 이러하니라 이스라엘의 장자 르우벤의 아들은 하녹과 발루와 헤스론과 갈미니 이들은 르우벤의 족장이요'),
    (1685, '<여호와께서 모세와 아론에게 명령하시다> ○여호와께서 애굽 땅에서 모세에게 말씀하시던 날에'),
    (1941, '<미리암의 노래> ○바로의 말과 병거와 마병이 함께 바다에 들어가매 여호와께서 바닷물을 그들 위에 되돌려 흐르게 하셨으나 이스라엘 자손은 바다 가운데서 마른 땅으로 지나간지라'),
    (1944, '<단 물로 변한 마라의 쓴 물> ○모세가 홍해에서 이스라엘을 인도하매 그들이 나와서 수르 광야로 들어가서 거기서 사흘길을 걸었으나 물을 얻지 못하고'),
    (1948, '이르시되 너희가 너희 하나님 나 여호와의 말을 들어 순종하고 내가 보기에 의를 행하며 내 계명에 귀를 기울이며 내 모든 규례를 지키면 내가 애굽 사람에게 내린 모든 질병 중 하나도 너희에게 내리지 아니하리니 나는 너희를 치료하는 여호와임이라'),
    (1949, '○그들이 엘림에 이르니 거기에 물 샘 열둘과 종려나무 일흔 그루가 있는지라 거기서 그들이 그 물 곁에 장막을 치니라'),
    (1874, '여호와께서 너를 인도하여 가나안 사람과 헷 사람과 아모리 사람과 히위 사람과 여부스 사람의 땅 곧 네게 주시려고 네 조상들에게 맹세하신 바 젖과 꿀이 흐르는 땅에 이르게 하시거든 너는 이 달에 이 예식을 지켜'),
    (1880, '<태에서 처음 난 것> ○여호와께서 너와 네 조상에게 맹세하신 대로 너를 가나안 사람의 땅에 인도하시고 그 땅을 네게 주시거든'),
    (1884, '그 때에 바로가 완악하여 우리를 보내지 아니하매 여호와께서 애굽 나라 가운데 처음 난 모든 것은 사람의 장자로부터 가축의 처음 난 것까지 다 죽이셨으므로 태에서 처음 난 모든 수컷들은 내가 여호와께 제사를 드려서 내 아들 중에 모든 처음 난 자를 다 대속하리니'),
    (1886, '<구름 기둥과 불 기둥> ○바로가 백성을 보낸 후에 블레셋 사람의 땅의 길은 가까울지라도 하나님이 그들을 그 길로 인도하지 아니하셨으니 이는 하나님이 말씀하시기를 이 백성이 전쟁을 하게 되면 마음을 돌이켜 애굽으로 돌아갈까 하셨음이라'),
    (1821, '너희는 이스라엘 온 회중에게 말하여 이르라 이 달 열흘에 너희 각자가 어린 양을 취할지니 각 가족대로 그 식구를 위하여 어린 양을 취하되'),
    (1833, '<무교절> ○너희는 이레 동안 무교병을 먹을지니 그 첫날에 누룩을 너희 집에서 제하라 무릇 첫날부터 일곱째 날까지 유교병을 먹는 자는 이스라엘에서 끊어지리라'),
    (1839, '<첫 유월절> ○모세가 이스라엘 모든 장로를 불러서 그들에게 이르되 너희는 나가서 너희의 가족대로 어린 양을 택하여 유월절 양으로 잡고'),
    (1841, '여호와께서 애굽 사람들에게 재앙을 내리려고 지나가실 때에 문 인방과 좌우 문설주의 피를 보시면 여호와께서 그 문을 넘으시고 멸하는 자에게 너희 집에 들어가서 너희를 치지 못하게 하실 것임이니라'),
    (1845, '너희는 이르기를 이는 여호와의 유월절 제사라 여호와께서 애굽 사람에게 재앙을 내리실 때에 애굽에 있는 이스라엘 자손의 집을 넘으사 우리의 집을 구원하셨느니라 하라 하매 백성이 머리 숙여 경배하니라'),
    (1847, '<열째 재앙 : 처음 난 것들의 죽음> ○밤중에 여호와께서 애굽 땅에서 모든 처음 난 것 곧 왕위에 앉은 바로의 장자로부터 옥에 갇힌 사람의 장자까지와 가축의 처음 난 것을 다 치시매'),
    (1855, '<이스라엘이 애굽 땅에서 나오다> ○이스라엘 자손이 라암셋을 떠나서 숙곳에 이르니 유아 외에 보행하는 장정이 육십만 가량이요'),
    (1861, '<유월절 규례> ○여호와께서 모세와 아론에게 이르시되 유월절 규례는 이러하니라 이방 사람은 먹지 못할 것이나'),
    (1866, '너희와 함께 거류하는 타국인이 여호와의 유월절을 지키고자 하거든 그 모든 남자는 할례를 받은 후에야 가까이 하여 지킬지니 곧 그는 본토인과 같이 될 것이나 할례 받지 못한 자는 먹지 못할 것이니라'),
    (1901, '○바로가 가까이 올 때에 이스라엘 자손이 눈을 들어 본즉 애굽 사람들이 자기들 뒤에 이른지라 이스라엘 자손이 심히 두려워하여 여호와께 부르짖고'),
    (1906, '○여호와께서 모세에게 이르시되 너는 어찌하여 내게 부르짖느냐 이스라엘 자손에게 명령하여 앞으로 나아가게 하고'),
    (1912, '○모세가 바다 위로 손을 내밀매 여호와께서 큰 동풍이 밤새도록 바닷물을 물러가게 하시니 물이 갈라져 바다가 마른 땅이 된지라'),
    (1917, '○여호와께서 모세에게 이르시되 네 손을 바다 위로 내밀어 물이 애굽 사람들과 그들의 병거들과 마병들 위에 다시 흐르게 하라 하시니'),
    (1986, '<반석에서 물이 나오다> 이스라엘 자손의 온 회중이 여호와의 명령대로 신 광야에서 떠나 그 노정대로 행하여 르비딤에 장막을 쳤으나 백성이 마실 물이 없는지라'),
    (1993, '<아말렉과 싸우다> ○그 때에 아말렉이 와서 이스라엘과 르비딤에서 싸우니라'),
    (1997, '모세의 팔이 피곤하매 그들이 돌을 가져다가 모세의 아래에 놓아 그가 그 위에 앉게 하고 아론과 훌이 한 사람은 이쪽에서, 한 사람은 저쪽에서 모세의 손을 붙들어 올렸더니 그 손이 해가 지도록 내려오지 아니한지라'),
    (1952, '이스라엘 자손이 그들에게 이르되 우리가 애굽 땅에서 고기 가마 곁에 앉아 있던 때와 떡을 배불리 먹던 때에 여호와의 손에 죽었더라면 좋았을 것을 너희가 이 광야로 우리를 인도해 내어 이 온 회중이 주려 죽게 하는도다'),
    (1953, '○그 때에 여호와께서 모세에게 이르시되 보라 내가 너희를 위하여 하늘에서 양식을 비 같이 내리리니 백성이 나가서 일용할 것을 날마다 거둘 것이라 이같이 하여 그들이 내 율법을 준행하나 아니하나 내가 시험하리라'),
    (1957, '모세가 또 이르되 여호와께서 저녁에는 너희에게 고기를 주어 먹이시고 아침에는 떡으로 배불리시리니 이는 여호와께서 자기를 향하여 너희가 원망하는 그 말을 들으셨음이라 우리가 누구냐 너희의 원망은 우리를 향하여 함이 아니요 여호와를 향하여 함이로다'),
    (1962, '○저녁에는 메추라기가 와서 진에 덮이고 아침에는 이슬이 진 주위에 있더니'),
    (1965, '여호와께서 이같이 명령하시기를 너희 각 사람은 먹을 만큼만 이것을 거둘지니 곧 너희 사람 수효대로 한 사람에 한 오멜씩 거두되 각 사람이 그의 장막에 있는 자들을 위하여 거둘지니라 하셨느니라'),
    (1970, '○무리가 아침마다 각 사람은 먹을 만큼만 거두었고 햇볕이 뜨겁게 쬐면 그것이 스러졌더라'),
    (1972, '모세가 그들에게 이르되 여호와께서 이같이 말씀하셨느니라 내일은 휴일이니 여호와께 거룩한 안식일이라 너희가 구울 것은 굽고 삶을 것은 삶고 그 나머지는 다 너희를 위하여 아침까지 간수하라'),
    (1980, '○이스라엘 족속이 그 이름을 만나라 하였으며 깟씨 같이 희고 맛은 꿀 섞은 과자 같았더라'),
    (1981, '모세가 이르되 여호와께서 이같이 명령하시기를 이것을 오멜에 채워서 너희의 대대 후손을 위하여 간수하라 이는 내가 너희를 애굽 땅에서 인도하여 낼 때에 광야에서 너희에게 먹인 양식을 그들에게 보이기 위함이니라 하셨다 하고'),
    (2002, '<이드로가 모세를 방문하다> 모세의 장인이며 미디안 제사장인 이드로가 하나님이 모세에게와 자기 백성 이스라엘에게 하신 일 곧 여호와께서 이스라엘을 애굽에서 인도하여 내신 모든 일을 들으니라'),
    (2014, '<우두머리를 세워 재판하게 하다> ○이튿날 모세가 백성을 재판하느라고 앉아 있고 백성은 아침부터 저녁까지 모세 곁에 서 있는지라'),
    (2054, '<십계명> 하나님이 이 모든 말씀으로 말씀하여 이르시되'),
    (2056, '○너는 나 외에는 다른 신들을 네게 두지 말라'),
    (2057, '○너를 위하여 새긴 우상을 만들지 말고 또 위로 하늘에 있는 것이나 아래로 땅에 있는 것이나 땅 아래 물 속에 있는 것의 어떤 형상도 만들지 말며'),
    (2060, '○너는 네 하나님 여호와의 이름을 망령되게 부르지 말라 여호와는 그의 이름을 망령되게 부르는 자를 죄 없다 하지 아니하리라'),
    (2061, '○안식일을 기억하여 거룩하게 지키라'),
    (2065, '○네 부모를 공경하라 그리하면 네 하나님 여호와가 네게 준 땅에서 네 생명이 길리라'),
    (2066, '○살인하지 말라'),
    (2067, '○간음하지 말라'),
    (2068, '○도둑질하지 말라'),
    (2069, '○네 이웃에 대하여 거짓 증거하지 말라'),
    (2070, '○네 이웃의 집을 탐내지 말라 네 이웃의 아내나 그의 남종이나 그의 여종이나 그의 소나 그의 나귀나 무릇 네 이웃의 소유를 탐내지 말라'),
    (2071, '<백성이 두려워 떨다> ○뭇 백성이 우레와 번개와 나팔 소리와 산의 연기를 본지라 그들이 볼 때에 떨며 멀리 서서'),
    (2075, '<제단에 관한 법> ○여호와께서 모세에게 이르시되 너는 이스라엘 자손에게 이같이 이르라 내가 하늘로부터 너희에게 말하는 것을 너희 스스로 보았으니'),
    (2080, '<종에 관한 법> 네가 백성 앞에 세울 법규는 이러하니라'),
    (2081, '○네가 히브리 종을 사면 그는 여섯 해 동안 섬길 것이요 일곱째 해에는 몸값을 물지 않고 나가 자유인이 될 것이며'),
    (2086, '○사람이 자기의 딸을 여종으로 팔았으면 그는 남종 같이 나오지 못할지며'),
    (2091, '<폭행에 관한 법> ○사람을 쳐죽인 자는 반드시 죽일 것이나'),
    (2094, '○자기 아버지나 어머니를 치는 자는 반드시 죽일지니라'),
    (2095, '○사람을 납치한 자가 그 사람을 팔았든지 자기 수하에 두었든지 그를 반드시 죽일지니라'),
    (2096, '○자기의 아버지나 어머니를 저주하는 자는 반드시 죽일지니라'),
    (2097, '○사람이 서로 싸우다가 하나가 돌이나 주먹으로 그의 상대방을 쳤으나 그가 죽지 않고 자리에 누웠다가'),
    (2099, '○사람이 매로 그 남종이나 여종을 쳐서 당장에 죽으면 반드시 형벌을 받으려니와'),
    (2101, '○사람이 서로 싸우다가 임신한 여인을 쳐서 낙태하게 하였으나 다른 해가 없으면 그 남편의 청구대로 반드시 벌금을 내되 재판장의 판결을 따라 낼 것이니라'),
    (2105, '○사람이 그 남종의 한 눈이나 여종의 한 눈을 쳐서 상하게 하면 그 눈에 대한 보상으로 그를 놓아 줄 것이며'),
    (2107, '<임자의 책임> ○소가 남자나 여자를 받아서 죽이면 그 소는 반드시 돌로 쳐서 죽일 것이요 그 고기는 먹지 말 것이며 임자는 형벌을 면하려니와'),
    (2112, '○사람이 구덩이를 열어두거나 구덩이를 파고 덮지 아니하므로 소나 나귀가 거기에 빠지면'),
    (2114, '○이 사람의 소가 저 사람의 소를 받아 죽이면 살아 있는 소를 팔아 그 값을 반으로 나누고 또한 죽은 것도 반으로 나누려니와'),
    (2120, '○사람이 밭에서나 포도원에서 짐승을 먹이다가 자기의 짐승을 놓아 남의 밭에서 먹게 하면 자기 밭의 가장 좋은 것과 자기 포도원의 가장 좋은 것으로 배상할지니라'),
    (2121, '○불이 나서 가시나무에 댕겨 낟가리나 거두지 못한 곡식이나 밭을 태우면 불 놓은 자가 반드시 배상할지니라'),
    (2122, '○사람이 돈이나 물품을 이웃에게 맡겨 지키게 하였다가 그 이웃 집에서 도둑을 맞았는데 그 도둑이 잡히면 갑절을 배상할 것이요'),
    (2124, '어떤 잃은 물건 즉 소나 나귀나 양이나 의복이나 또는 다른 잃은 물건에 대하여 어떤 사람이 이르기를 이것이 그것이라 하면 양편이 재판장 앞에 나아갈 것이요 재판장이 죄 있다고 하는 자가 그 상대편에게 갑절을 배상할지니라'),
    (2125, '○사람이 나귀나 소나 양이나 다른 짐승을 이웃에게 맡겨 지키게 하였다가 죽거나 상하거나 끌려가도 본 사람이 없으면'),
    (2129, '○만일 이웃에게 빌려온 것이 그 임자가 함께 있지 아니할 때에 상하거나 죽으면 반드시 배상하려니와'),
    (2131, '<도덕에 관한 법> ○사람이 약혼하지 아니한 처녀를 꾀어 동침하였으면 납폐금을 주고 아내로 삼을 것이요'),
    (2133, '○너는 무당을 살려두지 말라'),
    (2134, '○짐승과 행음하는 자는 반드시 죽일지니라'),
    (2135, '○여호와 외에 다른 신에게 제사를 드리는 자는 멸할지니라'),
    (2140, '○네가 만일 너와 함께 한 내 백성 중에서 가난한 자에게 돈을 꾸어 주면 너는 그에게 채권자 같이 하지 말며 이자를 받지 말 것이며'),
    (2143, '○너는 재판장을 모독하지 말며 백성의 지도자를 저주하지 말지니라'),
    (2150, '○네가 만일 네 원수의 길 잃은 소나 나귀를 보거든 반드시 그 사람에게로 돌릴지며'),
    (2152, '○너는 가난한 자의 송사라고 정의를 굽게 하지 말며'),
    (2156, '<안식년과 안식일에 관한 법> ○너는 여섯 해 동안은 너의 땅에 파종하여 그 소산을 거두고'),
    (2160, '<세 가지 절기에 관한 법> ○너는 매년 세 번 내게 절기를 지킬지니라'),
    (2164, '○너는 네 제물의 피를 유교병과 함께 드리지 말며 내 절기 제물의 기름을 아침까지 남겨두지 말지니라'),
    (2166, '<명령과 약속> ○내가 사자를 네 앞서 보내어 길에서 너를 보호하여 너를 내가 예비한 곳에 이르게 하리니'),
    (2188, '○모세와 아론과 나답과 아비후와 이스라엘 장로 칠십 인이 올라가서'),
    (2191, '<시내 산에서 사십 일을 있다> ○여호와께서 모세에게 이르시되 너는 산에 올라 내게로 와서 거기 있으라 네가 그들을 가르치도록 내가 율법과 계명을 친히 기록한 돌판을 네게 주리라'),
    (2035, '○모세가 내려와서 백성의 장로들을 불러 여호와께서 자기에게 명령하신 그 모든 말씀을 그들 앞에 진술하니'),
    (2037, '여호와께서 모세에게 이르시되 내가 빽빽한 구름 가운데서 네게 임함은 내가 너와 말하는 것을 백성들이 듣게 하며 또한 너를 영영히 믿게 하려 함이니라 모세가 백성의 말을 여호와께 아뢰었으므로'),
    (2044, '○셋째 날 아침에 우레와 번개와 빽빽한 구름이 산 위에 있고 나팔 소리가 매우 크게 들리니 진중에 있는 모든 백성이 다 떨더라'),
    (2238, '<성막> 너는 성막을 만들되 가늘게 꼰 베 실과 청색 자색 홍색 실로 그룹을 정교하게 수 놓은 열 폭의 휘장을 만들지니'),
    (2243, '금 갈고리 쉰 개를 만들고 그 갈고리로 휘장을 연결하여 한 성막을 이룰지며'),
    (2252, '○너는 조각목으로 성막을 위하여 널판을 만들어 세우되'),
    (2268, '○너는 청색 자색 홍색 실과 가늘게 꼰 베 실로 짜서 휘장을 만들고 그 위에 그룹들을 정교하게 수 놓아서'),
    (2207, '<증거궤> ○그들은 조각목으로 궤를 짜되 길이는 두 규빗 반, 너비는 한 규빗 반, 높이는 한 규빗 반이 되게 하고'),
    (2220, '<진설병을 두는 상> ○너는 조각목으로 상을 만들되 길이는 두 규빗, 너비는 한 규빗, 높이는 한 규빗 반이 되게 하고'),
    (2228, '<등잔대와 기구들> ○너는 순금으로 등잔대를 쳐 만들되 그 밑판과 줄기와 잔과 꽃받침과 꽃을 한 덩이로 연결하고'),
    (2232, '등잔대에서 나온 가지 여섯을 위하여 꽃받침이 있게 하되 두 가지 아래에 한 꽃받침이 있어 줄기와 연결하며 또 두 가지 아래에 한 꽃받침이 있어 줄기와 연결하며 또 두 가지 아래에 한 꽃받침이 있어 줄기와 연결하게 하고'),
    (2275, '<제단> 너는 조각목으로 길이가 다섯 규빗, 너비가 다섯 규빗의 제단을 만들되 네모 반듯하게 하며 높이는 삼 규빗으로 하고'),
    (2283, '<성막의 뜰> ○너는 성막의 뜰을 만들지니 남쪽을 향하여 뜰 남쪽에 너비가 백 규빗의 세마포 휘장을 쳐서 그 한 쪽을 당하게 할지니'),
    (2285, '그 북쪽에도 너비가 백 규빗의 포장을 치되 그 기둥이 스물이며 그 기둥의 받침 스물은 놋으로 하고 그 기둥의 갈고리와 가름대는 은으로 할지며'),
    (2294, '<등불 관리> ○너는 또 이스라엘 자손에게 명령하여 감람으로 짠 순수한 기름을 등불을 위하여 네게로 가져오게 하고 끊이지 않게 등불을 켜되'),
    (2339, '<제사장 직분 위임> 네가 그들에게 나를 섬길 제사장 직분을 위임하여 그들을 거룩하게 할 일은 이러하니 곧 어린 수소 하나와 흠 없는 숫양 둘을 택하고'),
    (2348, '○너는 수송아지를 회막 앞으로 끌어오고 아론과 그의 아들들은 그 송아지 머리에 안수할지며'),
    (2353, '○너는 또 숫양 한 마리를 끌어오고 아론과 그의 아들들은 그 숫양의 머리 위에 안수할지며'),
    (2357, '○너는 다른 숫양을 택하고 아론과 그 아들들은 그 숫양의 머리 위에 안수할지며'),
    (2364, '○너는 아론의 위임식 숫양의 가슴을 가져다가 여호와 앞에 흔들어 요제를 삼으라 이것이 네 분깃이니라'),
    (2367, '○아론의 성의는 후에 아론의 아들들에게 돌릴지니 그들이 그것을 입고 기름 부음으로 위임을 받을 것이며'),
    (2369, '○너는 위임식 숫양을 가져다가 거룩한 곳에서 그 고기를 삶고'),
    (2373, '○너는 내가 네게 한 모든 명령대로 아론과 그의 아들들에게 그같이 하여 이레 동안 위임식을 행하되'),
    (2376, '<매일 드릴 번제> ○네가 제단 위에 드릴 것은 이러하니라 매일 일 년 된 어린 양 두 마리니'),
    (2423, '<회막 기구를 만들게 하라> 여호와께서 모세에게 말씀하여 이르시되'),
    (2434, '<안식일> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2440, '<증거판> ○여호와께서 시내 산 위에서 모세에게 이르시기를 마치신 때에 증거판 둘을 모세에게 주시니 이는 돌판이요 하나님이 친히 쓰신 것이더라'),
    (2296, '<제사장의 옷> 너는 이스라엘 자손 중 네 형 아론과 그의 아들들 곧 아론과 아론의 아들들 나답과 아비후와 엘르아살과 이다말을 그와 함께 네게로 나아오게 하여 나를 섬기는 제사장 직분을 행하게 하되'),
    (2301, '○그들이 금 실과 청색 자색 홍색 실과 가늘게 꼰 베 실로 정교하게 짜서 에봇을 짓되'),
    (2310, '<판결 흉패> ○너는 판결 흉패를 에봇 짜는 방법으로 금 실과 청색 자색 홍색 실과 가늘게 꼰 베 실로 정교하게 짜서 만들되'),
    (2326, '<제사장의 또 다른 옷> ○너는 에봇 받침 겉옷을 전부 청색으로 하되'),
    (2331, '○너는 또 순금으로 패를 만들어 도장을 새기는 법으로 그 위에 새기되 ''여호와께 성결''이라 하고'),
    (2335, '○너는 아론의 아들들을 위하여 속옷을 만들며 그들을 위하여 띠를 만들며 그들을 위하여 관을 만들어 영화롭고 아름답게 하되'),
    (2385, '<분향할 제단> 너는 분향할 제단을 만들지니 곧 조각목으로 만들되'),
    (2395, '<회막 봉사에 쓰는 속전> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2396, '네가 이스라엘 자손의 수효를 조사할 때에 조사 받은 각 사람은 그들을 계수할 때에 자기의 생명의 속전을 여호와께 드릴지니 이는 그들을 계수할 때에 그들 중에 질병이 없게 하려 함이라'),
    (2401, '<놋 물두멍> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2406, '<거룩한 향기름> ○여호와께서 모세에게 또 말씀하여 이르시되'),
    (2418, '<거룩한 향> ○여호와께서 모세에게 이르시되 너는 소합향과 나감향과 풍자향의 향품을 가져다가 그 향품을 유향에 섞되 각기 같은 분량으로 하고'),
    (2499, '<두 번째 돌판> 여호와께서 모세에게 이르시되 너는 돌판 둘을 처음 것과 같이 다듬어 만들라 네가 깨뜨린 처음 판에 있던 말을 내가 그 판에 쓰리니'),
    (2508, '<다시 언약을 세우시다> 여호와께서 이르시되 보라 내가 언약을 세우나니 곧 내가 아직 온 땅 아무 국민에게도 행하지 아니한 이적을 너희 전체 백성 앞에 행할 것이라 네가 머무는 나라 백성이 다 여호와의 행하심을 보리니 내가 너를 위하여 행할 일이 두려운 것임이니라'),
    (2516, '○너는 무교절을 지키되 내가 네게 명령한 대로 아빕월 그 절기에 이레 동안 무교병을 먹으라 이는 네가 아빕월에 애굽에서 나왔음이니라'),
    (2519, '○너는 엿새 동안 일하고 일곱째 날에는 쉴지니 밭 갈 때에나 거둘 때에도 쉴지며'),
    (2523, '○너는 내 제물의 피를 유교병과 함께 드리지 말며 유월절 제물을 아침까지 두지 말지며'),
    (2525, '○여호와께서 모세에게 이르시되 너는 이 말들을 기록하라 내가 이 말들의 뜻대로 너와 이스라엘과 언약을 세웠음이니라 하시니라'),
    (2527, '<모세가 시내 산에서 내려오다> ○모세가 그 증거의 두 판을 모세의 손에 들고 시내 산에서 내려오니 그 산에서 내려올 때에 모세는 자기가 여호와와 말하였음으로 말미암아 얼굴 피부에 광채가 나나 깨닫지 못하였더라'),
    (2476, '<시내 산을 떠나라고 명하시다> 여호와께서 모세에게 이르시되 너는 네가 애굽 땅에서 인도하여 낸 백성과 함께 여기를 떠나서 내가 아브라함과 이삭과 야곱에게 맹세하여 네 자손에게 주기로 한 그 땅으로 올라가라'),
    (2480, '여호와께서 모세에게 이르시기를 이스라엘 자손에게 이르라 너희는 목이 곧은 백성인즉 내가 한 순간이라도 너희 가운데에 이르면 너희를 진멸하리니 너희는 장신구를 떼어 내라 그리하면 내가 너희에게 어떻게 할 것인지 정하겠노라 하셨음이라'),
    (2482, '<회막> ○모세가 항상 장막을 취하여 진 밖에 쳐서 진과 멀리 떠나게 하고 회막이라 이름하니 여호와를 앙모하는 자는 다 진 바깥 회막으로 나아가며'),
    (2487, '<여호와께서 친히 가리라 하시다> ○모세가 여호와께 아뢰되 보시옵소서 주께서 내게 이 백성을 인도하여 올라가라 하시면서 나와 함께 보낼 자를 내게 지시하지 아니하시나이다 주께서 전에 말씀하시기를 나는 이름으로도 너를 알고 너도 내 앞에 은총을 입었다 하셨사온즉'),
    (2492, '○여호와께서 모세에게 이르시되 네가 말하는 이 일도 내가 하리니 너는 내 목전에 은총을 입었고 내가 이름으로도 너를 앎이니라'),
    (2607, '<언약궤를 만들다> 브살렐이 조각목으로 궤를 만들었으니 길이가 두 규빗 반, 너비가 한 규빗 반, 높이가 한 규빗 반이며'),
    (2616, '<상을 만들다> ○그가 또 조각목으로 상을 만들었으니 길이가 두 규빗, 너비가 한 규빗, 높이가 한 규빗 반이며'),
    (2623, '<등잔대를 만들다> ○그가 또 순금으로 등잔대를 만들되 그것을 쳐서 만들었으니 그 밑판과 줄기와 잔과 꽃받침과 꽃이 그것과 한 덩이로 되었고'),
    (2627, '등잔대에서 나온 가지 여섯을 위하여는 꽃받침이 있게 하였으되 두 가지 아래에 한 꽃받침이 있어 줄기와 연결하였고 또 두 가지 아래에 한 꽃받침이 있어 줄기와 연결하였고 또 다시 두 가지 아래에 한 꽃받침이 있어 줄기와 연결되게 하였으니'),
    (2631, '<분향할 제단을 만들다> ○그가 또 조각목으로 분향할 제단을 만들었으니 길이는 한 규빗이요 너비도 한 규빗이라 네모가 반듯하고 높이는 두 규빗이며 그 뿔들이 제단과 연결되었으며'),
    (2537, '<여호와께 드릴 것들> ○모세가 이스라엘 자손의 온 회중에게 말하여 이르되 여호와께서 명령하신 일이 이러하니라 이르시기를'),
    (2543, '○무릇 너희 중 마음이 지혜로운 자는 와서 여호와께서 명령하신 것을 다 만들지니'),
    (2553, '<여호와께 자원하여 드린 예물> ○이스라엘 자손의 온 회중이 모세 앞에서 물러갔더니'),
    (2563, '<성막 일꾼> ○모세가 이스라엘 자손에게 이르되 볼지어다 여호와께서 유다 지파 훌의 손자요 우리의 아들인 브살렐을 지명하여 부르시고'),
    (2568, '지혜로운 마음을 그들에게 충만하게 하사 여러 가지 일을 하게 하시되 조각하는 일과 세공하는 일과 청색 자색 홍색 실과 가는 베 실로 수 놓는 일과 짜는 일과 그 외에 여러 가지 일을 하게 하시고 정교한 일을 고안하게 하셨느니라'),
    (2570, '<예물로 드린 재료가 넉넉하다> ○모세가 브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 그 마음에 여호와께로부터 지혜를 얻고 와서 그 일을 하려고 마음에 원하는 모든 자를 부르매'),
    (2576, '<성막을 만들다> ○일하는 사람 중에 마음이 지혜로운 모든 사람이 열 폭 휘장으로 성막을 지었으니 곧 가늘게 꼰 베 실과 청색 자색 홍색 실로 그룹들을 무늬 놓아 짜서 지은 것이라'),
    (2582, '○그 성막을 덮는 막 곧 휘장을 염소 털로 만들되 열한 폭을 만들었으니'),
    (2588, '○그가 또 조각목으로 성막에 세울 널판들을 만들었으니'),
    (2599, '○그가 또 조각목으로 띠를 만들었으니 곧 성막 이쪽 널판을 위하여 다섯 개요'),
    (2603, '○그가 또 청색 자색 홍색 실과 가늘게 꼰 베 실로 휘장을 짜고 그 위에 그룹들을 정교하게 수 놓고'),
    (2636, '<번제단을 만들다> 그가 또 조각목으로 번제단을 만들었으니 길이는 다섯 규빗이요 너비도 다섯 규빗이라 네모가 반듯하고 높이는 세 규빗이며'),
    (2643, '<놋 물두멍을 만들다> ○그가 놋으로 물두멍을 만들고 그 받침도 놋으로 하였으니 곧 회막 문에서 수종드는 여인들의 거울로 만들었더라'),
    (2644, '<성막 울타리를 만들다> ○그가 또 뜰을 만들었으니 남으로 뜰의 남쪽에는 세마포 포장이 백 규빗이라'),
    (2647, '서쪽에 포장은 쉰 규빗이라 그 기둥이 열이요 받침이 열이며 기둥의 갈고리와 가름대는 은이며'),
    (2656, '<성막 재료의 물자 목록> ○성막 곧 증거막을 위하여 레위 사람이 쓴 재료의 물목은 제사장 아론의 아들 이다말이 모세의 명령대로 계산하였으며'),
    (2659, '○성소 건축 비용으로 들인 금은 성소의 세겔로 스물아홉 달란트와 칠백삼십 세겔이며'),
    (2441, '<금 송아지> 백성이 모세가 산에서 내려옴이 더딤을 보고 모여 백성이 아론에게 이르러 말하되 일어나라 우리를 위하여 우리를 인도할 신을 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어찌 되었는지 알지 못함이니라'),
    (2447, '○여호와께서 모세에게 이르시되 너는 내려가라 네가 애굽 땅에서 인도하여 낸 네 백성이 부패하였도다'),
    (2448, '그들이 내가 그들에게 명령한 길을 속히 떠나 자기를 위하여 송아지를 부어 만들고 그것을 예배하며 그것에게 제물을 드리며 말하기를 이스라엘아 이는 너희를 애굽 땅에서 인도하여 낸 너희 신이라 하였도다'),
    (2452, '어찌하여 애굽 사람들이 이르기를 여호와가 자기의 백성을 산에서 죽이고 지면에서 진멸하려는 악한 의도로 인도해 내었다고 말하게 하시려 하나이까 주의 맹렬한 노를 그치시고 뜻을 돌이키사 주의 백성에게 이 화를 내리지 마옵소서'),
    (2453, '주의 종 아브라함과 이삭과 이스라엘을 기억하소서 주께서 그들을 위하여 주를 가리켜 맹세하여 이르시기를 내가 너희의 자손을 하늘의 별처럼 많게 하고 내가 허락한 이 온 땅을 너희의 자손에게 주어 영원한 기업이 되게 하리라 하셨나이다'),
    (2455, '○모세가 돌이켜 산에서 내려오는데 두 증거판이 그의 손에 있고 그 판의 양면 이쪽 저쪽에 글자가 있으니'),
    (2461, '○모세가 아론에게 이르되 이 백성이 당신에게 어떻게 하였기에 당신이 그들을 큰 죄에 빠지게 하였느냐'),
    (2465, '○모세가 본즉 백성이 방자하니 이는 아론이 그들을 방자하게 하여 원수에게 조롱거리가 되게 하였음이라'),
    (2467, '모세가 그들에게 이르되 이스라엘의 하나님 여호와께서 이렇게 말씀하시기를 너희는 각각 허리에 칼을 차고 진 이 문에서 저 문까지 왕래하며 각 사람이 그 형제를, 각 사람이 자기의 친구를, 각 사람이 자기의 이웃을 죽이라 하셨느니라'),
    (2470, '○이튿날 모세가 백성에게 이르되 너희가 큰 죄를 범하였도다 내가 이제 여호와께로 올라가노니 혹 너희를 위하여 속죄가 될까 하노라 하고'),
    (2786, '○만일 여호와께 예물로 드리는 화목제의 제물이 양이면 수컷이나 암컷이나 흠 없는 것으로 드릴지며'),
    (2792, '○만일 그의 예물이 염소면 그것을 여호와 앞으로 끌어다가'),
    (2768, '○네가 화덕에 구운 것으로 소제의 예물을 드리려거든 고운 가루에 기름을 섞어 만든 무교병이나 기름을 바른 무교전병을 드릴 것이요'),
    (2775, '○너희가 여호와께 드리는 모든 소제물에는 누룩을 넣지 말지니 너희가 누룩이나 꿀을 여호와께 화제로 드려 사르지 못할지니라'),
    (2778, '○너는 첫 이삭의 소제를 여호와께 드리거든 첫 이삭을 볶아 찧은 것으로 네 소제를 삼되'),
    (2750, '○그 예물이 소의 번제이면 흠 없는 수컷으로 회막 문에서 여호와 앞에 기쁘게 받으시도록 드릴지니라'),
    (2757, '○만일 그 예물이 가축 떼의 양이나 염소의 번제이면 흠 없는 수컷으로 드릴지니'),
    (2761, '○만일 여호와께 드리는 예물이 새의 번제이면 산비둘기나 집비둘기 새끼로 예물을 드릴 것이요'),
    (2726, '○둘째 해 첫째 달 곧 그 달 초하루에 성막을 세우니라'),
    (2743, '<여호와의 영광이 성막에 충만하다> ○구름이 회막에 덮이고 여호와의 영광이 성막에 충만하매'),
    (2810, '○만일 이스라엘 온 회중이 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있으나 스스로 깨닫지 못하다가'),
    (2819, '○만일 족장이 그의 하나님 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있었는데'),
    (2824, '○만일 평민의 한 사람이 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있었는데'),
    (2829, '○그가 만일 어린 양을 속죄제물로 가져오려거든 흠 없는 암컷을 끌어다가'),
    (2832, '그 모든 기름을 화목제 어린 양의 기름을 떼낸 것 같이 떼내어 제단 위 여호와의 화제물 위에서 불사를지니 이같이 제사장이 그가 범한 죄에 대하여 그를 위하여 속죄한즉 그가 사함을 받으리라'),
    (2834, '만일 누구든지 부정한 것들 곧 부정한 들짐승의 사체나 부정한 가축의 사체나 부정한 곤충의 사체를 만졌으면 부지중이라고 할지라도 그 몸이 더러워져서 허물이 있을 것이요'),
    (2836, '만일 누구든지 입술로 맹세하여 악한 일이든지 선한 일이든지 하리라고 함부로 말하면 그 사람이 함부로 말하여 맹세한 것이 무엇이든지 그가 깨닫지 못하다가 그것을 깨닫게 되었을 때에는 그 중 하나에 그에게 허물이 있을 것이니'),
    (2839, '○만일 그의 힘이 어린 양을 바치는 데에 미치지 못하면 그가 지은 죄를 속죄하기 위하여 산비둘기 두 마리나 집비둘기 새끼 두 마리를 여호와께로 가져가되 하나는 속죄제물을 삼고 하나는 번제물을 삼아'),
    (2843, '○만일 그의 손이 산비둘기 두 마리나 집비둘기 두 마리에도 미치지 못하면 그의 범죄로 말미암아 고운 가루 십분의 일 에바를 예물로 가져다가 속죄제물로 드리되 이는 속죄제인즉 그 위에 기름을 붓지 말며 유향을 놓지 말고'),
    (2846, '<속건제를 드리는 규례> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2847, '누구든지 여호와의 성물에 대하여 부지중에 범죄하였으면 여호와께 속건제를 드리되 네가 지정한 가치를 따라 성소의 세겔로 몇 세겔 은에 상당한 흠 없는 숫양을 양 떼 중에서 끌어다가 속건제로 드려서'),
    (2849, '○만일 누구든지 여호와의 계명 중 하나를 부지중에 범하여도 허물이라 벌을 당할 것이니'),
    (2667, '<제사장의 옷을 만들다> 그들은 여호와께서 모세에게 명령하신 대로 청색 자색 홍색 실로 성소에서 섬길 때 입을 정교한 옷을 만들고 또 아론을 위해 거룩한 옷을 만들었더라'),
    (2668, '○그는 또 금 실과 청색 자색 홍색 실과 가늘게 꼰 베 실로 에봇을 만들었으되'),
    (2672, '○그들은 또 호마노를 깎아 금 테에 물려 도장을 새김 같이 이스라엘의 아들들의 이름을 그것에 새겨'),
    (2674, '<흉패를 짜다> ○그가 또 흉패를 정교하게 짜되 에봇과 같은 모양으로 금 실과 청색 자색 홍색 실과 가늘게 꼰 베 실로 하였으니'),
    (2688, '<제사장의 또 다른 옷을 만들다> ○그가 에봇 받침 긴 옷을 전부 청색으로 짜서 만들되'),
    (2693, '○그들이 또 직조한 가는 베로 아론과 그의 아들들을 위하여 속옷을 짓고'),
    (2696, '○그들이 또 순금으로 거룩한 패를 만들고 도장을 새김 같이 그 위에 ''여호와께 성결''이라 새기고'),
    (2698, '<성막의 모든 역사를 마치다> ○이스라엘 자손이 이와 같이 성막 곧 회막의 모든 역사를 마치되 여호와께서 모세에게 명령하신 대로 다 행하고'),
    (2859, '<번제를 드리는 규례> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2865, '<소제를 드리는 규례> ○소제의 규례는 이러하니라 아론의 자손은 그것을 제단 앞 여호와 앞에 드리되'),
    (2866, '그 소제의 고운 가루 한 움큼과 기름과 소제물 위의 유향을 다 가져다가 기념물로 제단 위에서 불살라 여호와 앞에 향기로운 냄새가 되게 하고'),
    (2870, '○여호와께서 모세에게 말씀하여 이르시되'),
    (2875, '<속죄제를 드리는 규례> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2963, '○이에 아론이 제단에 나아가 자기를 위한 속죄제 송아지를 잡으매'),
    (2967, '○아론이 또 번제물을 잡으매 아론의 아들들이 그 피를 그에게로 가져오니 그가 그 피를 제단 사방에 뿌리고'),
    (2970, '○그가 또 백성의 예물을 드리되 곧 백성을 위한 속죄제의 염소를 가져다가 잡아 전과 같이 죄를 위하여 드리고'),
    (2977, '○아론이 백성을 향하여 손을 들어 축복함으로 속죄제와 번제와 화목제를 마치고 내려오니라'),
    (2892, '<화목제물을 드리는 규례> ○여호와께 드릴 화목제물의 규례는 이러하니라'),
    (2896, '○감사함으로 드리는 화목제물의 고기는 드리는 그 날에 먹을 것이요 조금이라도 이튿날 아침까지 두지 말 것이니라'),
    (2899, '만일 그 화목제물의 고기를 셋째 날에 조금이라도 먹으면 그 제사는 기쁘게 받아들여지지 않을 것이라 드린 자에게도 예물답게 되지 못하고 도리어 가증한 것이 될 것이며 그것을 먹는 자는 그 죄를 짊어지리라'),
    (2900, '○그 고기가 부정한 물건에 접촉되었으면 먹지 말고 불사를 것이라 그 고기는 깨끗한 자만 먹을 것이니'),
    (2903, '<피와 기름은 먹지 말라> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2909, '<화목제물 중에서 제사장이 받을 소득> ○여호와께서 모세에게 말씀하여 이르시되'),
    (2916, '<맺는 말> ○이는 여호와의 화제물 중에서 아론에게 돌릴 것과 그의 아들들에게 돌릴 것이니 그들을 세워 여호와의 제사장의 직분을 행하게 한 날'),
    (2918, '<맺는 말> ○이는 번제와 소제와 속죄제와 속건제와 위임식과 화목제의 규례라'),
    (2985, '모세가 아론과 그의 아들 엘르아살과 이다말에게 이르되 너희는 머리를 풀거나 옷을 찢지 말라 그리하여 너희가 죽음을 면하고 여호와의 진노가 온 회중에게 미침을 면하게 하라 오직 너희 형제 이스라엘 온 족속은 여호와께서 치신 불로 말미암아 슬퍼할 것이니라'),
    (2987, '<제사장이 회막에 들어갈 때의 규례> ○여호와께서 아론에게 말씀하여 이르시되'),
    (2991, '<제사장이 거룩한 곳에서 먹을 제물> ○모세가 아론과 그 남은 아들 엘르아살에게와 이다말에게 이르되 여호와께 드린 화제물 중 소제의 남은 것은 지극히 거룩하니 너희는 그것을 취하여 누룩을 넣지 말고 제단 곁에서 먹되'),
    (2995, '○모세가 속죄제 드린 염소를 찾은즉 이미 불살랐는지라 그가 아론의 남은 아들 엘르아살과 이다말에게 노하여 이르되'),
    (2929, '○모세가 관유를 가져다가 성막과 그 안에 있는 모든 것에 발라 거룩하게 하고'),
    (2933, '○모세가 또 속죄제의 수송아지를 끌어오니 아론과 그의 아들들이 그 속죄제의 수송아지 머리에 안수하매'),
    (2937, '○또 번제의 숫양을 드릴새 아론과 그의 아들들이 그 숫양의 머리에 안수하매'),
    (2941, '○또 다른 숫양 곧 위임식의 숫양을 드릴새 아론과 그의 아들들이 그 숫양의 머리에 안수하매'),
    (2949, '○모세가 관유와 제단 위의 피를 가져다가 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷에 뿌려서 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷을 거룩하게 하고'),
    (3052, '○아들이나 딸이나 정결하게 되는 기한이 차면 그 여인은 번제를 위하여 일 년 된 어린 양을 가져가고 속죄제를 위하여 집비둘기 새끼나 산비둘기를 회막 문 제사장에게로 가져갈 것이요'),
    (3054, '그 여인이 어린 양을 바치기에 힘이 미치지 못하면 산비둘기 두 마리나 집비둘기 새끼 두 마리를 가져다가 하나는 번제물로, 하나는 속죄제물로 삼을 것이요 제사장은 그를 위하여 속죄할지니 그가 정결하리라'),
    (3008, '○물에 있는 모든 것 중에서 너희가 먹을 만한 것은 이것이니 강과 바다와 다른 물에 있는 모든 것 중에서 지느러미와 비늘 있는 것은 너희가 먹되'),
    (3012, '○새 중에 너희가 가증히 여길 것은 이것이라 이것들이 가증한즉 먹지 말지니 곧 독수리와 솔개와 물수리와'),
    (3019, '○날개가 있고 네 발로 기어 다니는 곤충은 너희가 혐오할 것이로되'),
    (3020, '다만 날개가 있고 네 발로 기어 다니는 모든 곤충 중에 그 발에 뛰는 다리가 있어서 땅에서 뛰는 것은 너희가 먹을지니'),
    (3023, '○이런 것은 너희를 부정하게 하나니 누구든지 이것들의 주검을 만지면 저녁까지 부정할 것이며'),
    (3028, '○땅에 기는 길짐승 중에 네게 부정한 것은 이러하니 곧 두더지와 쥐와 큰 도마뱀 종류와'),
    (3038, '○너희가 먹을 만한 짐승이 죽은 때에 그 주검을 만지는 자는 저녁까지 부정할 것이며'),
    (3040, '○땅에 기어 다니는 모든 길짐승은 가증한즉 먹지 못할지니'),
    (3045, '○이는 짐승과 새와 물에서 움직이는 모든 생물과 땅에 기는 모든 길짐승에 대한 규례니'),
    (3183, '○유출병이 있는 자는 그의 유출이 깨끗해지거든 그가 정결하게 되기 위하여 이레를 센 후에 옷을 빨고 흐르는 물에 그의 몸을 씻을 것이라 그러면 그가 정하리니'),
    (3186, '○설정한 자는 전신을 물로 씻을 것이며 저녁까지 부정하리라'),
    (3189, '<여인이 유출을 하면> ○어떤 여인이 유출을 하되 그의 몸에 그의 유출이 피이면 이레 동안 불결하니 그를 만지는 자마다 저녁까지 부정할 것이요'),
    (3195, '○만일 여인의 피의 유출이 그의 불결기가 아닌데도 여러 날이 간다든지 그 유출이 그의 불결기를 지나도 계속되면 그 부정을 유출하는 모든 날 동안은 그 불결한 때와 같이 부정한즉'),
    (3201, '○너희는 이와 같이 이스라엘 자손이 그들의 부정에서 떠나게 하여 그들 가운데에 있는 내 성막을 그들이 더럽히고 그들이 부정한 중에서 죽지 않도록 할지니라'),
    (3202, '○이 규례는 유출병이 있는 자와 설정함으로 부정하게 된 자와'),
    (3063, '○사람에게 나병이 들었거든 그를 제사장에게로 데려갈 것이요'),
    (3072, '○피부에 종기가 생겼다가 나았고'),
    (3078, '○피부가 불에 데었는데 그 덴 곳에 불그스름하고 희거나 순전히 흰 색점이 생기면'),
    (3083, '○남자나 여자의 머리에나 수염에 환부가 있으면'),
    (3092, '○남자나 여자의 피부에 색점 곧 흰 색점이 있으면'),
    (3094, '○누구든지 그 머리털이 빠지면 그는 대머리니 정하고'),
    (3099, '○나병 환자는 옷을 찢고 머리를 풀며 윗입술을 가리고 외치기를 부정하다 부정하다 할 것이요'),
    (3101, '<의복이나 가죽에 생기는 곰팡이> ○만일 의복에 나병 색점이 발생하여 털옷에나 베옷에나'),
    (3107, '○그러나 제사장이 보기에 그 색점이 그 의복의 날에나 씨에나 모든 가죽으로 만든 것에 퍼지지 아니하였으면'),
    (3110, '○빤 후에 제사장이 보기에 그 색점이 엷으면 그 의복에서나 가죽에서나 그 날에서나 씨에서나 그 색점을 찢어 버릴 것이요'),
    (3113, '○이는 털옷에나 베옷에나 그 날에나 씨에나 가죽으로 만든 모든 것에 발생한 나병 색점의 정하고 부정한 것을 진단하는 규례니라'),
    (3245, '○너는 또 그들에게 이르라 이스라엘 집 사람이나 혹은 그들 중에 거류하는 거류민이 번제나 제물을 드리되'),
    (3247, '<피를 먹지 말라> ○이스라엘 집 사람이나 그들 중에 거류하는 거류민 중에 무슨 피든지 먹는 자가 있으면 내가 그 피를 먹는 그 사람에게는 내 얼굴을 대하여 그를 백성 중에서 끊으리니'),
    (3251, '모든 생물은 그 피가 생명과 일체라 그러므로 내가 이스라엘 자손에게 이르기를 너희는 어떤 육체의 피든지 먹지 말라 하였나니 모든 육체의 생명은 그것의 피인즉 그 피를 먹는 모든 자는 끊어지리라'),
    (3123, '○여덟째 날에 그는 흠 없는 어린 숫양 두 마리와 일 년 된 흠 없는 어린 암양 한 마리와 또 고운 가루 십분의 삼 에바에 기름 섞은 소제물과 기름 한 록을 취할 것이요'),
    (3134, '○만일 그가 가난하여 그의 힘이 미치지 못하면 그는 흔들어 자기를 속죄할 속건제를 위하여 어린 숫양 한 마리와 소제를 위하여 고운 가루 십분의 일 에바에 기름 섞은 것과 기름 한 록을 취하고'),
    (3136, '여덟째 날에 그 결례를 위하여 그것들을 회막 문 여호와 앞 제사장에게로 가져갈 것이요'),
    (3146, '<집에 생기는 곰팡이> ○여호와께서 모세와 아론에게 말씀하여 이르시되'),
    (3156, '○돌을 빼내며 집을 긁고 고쳐 바른 후에 색점이 집에 재발하면'),
    (3161, '○그 집을 고쳐 바른 후에 제사장이 들어가 살펴보아서 색점이 집에 퍼지지 아니하였으면 이는 색점이 나은 것이니 제사장은 그 집을 정하다 하고'),
    (3167, '○이는 각종 나병 환부에 대한 규례니 곧 옴과'),
    (3259, '○각 사람은 자기의 살붙이를 가까이 하여 그의 하체를 범하지 말라 나는 여호와이니라'),
    (3272, '○너는 여인이 월경으로 불결한 동안에 그에게 가까이 하여 그의 하체를 범하지 말지니라'),
    (3277, '○너희는 이 모든 일로 스스로 더럽히지 말라 내가 너희 앞에서 쫓아내는 족속들이 이 모든 일로 말미암아 더러워졌고'),
    (3288, '○너희는 화목제물을 여호와께 드릴 때에 기쁘게 받으시도록 드리고'),
    (3292, '○너희가 너희의 땅에서 곡식을 거둘 때에 너는 밭 모퉁이까지 다 거두지 말고 네 떨어진 이삭도 줍지 말며'),
    (3294, '○너희는 도둑질하지 말며 속이지 말며 서로 거짓말하지 말며'),
    (3296, '○너는 네 이웃을 억압하지 말며 착취하지 말며 품꾼의 삯을 아침까지 밤새도록 네게 두지 말며'),
    (3298, '○너희는 재판할 때에 불의를 행하지 말며 가난한 자의 편을 들지 말며 세력 있는 자라고 두둔하지 말고 공의로 사람을 재판할지며'),
    (3300, '○너는 네 형제를 마음으로 미워하지 말며 네 이웃을 반드시 견책하라 그러면 네가 그에 대하여 죄를 담당하지 아니하리라'),
    (3302, '○너희는 내 규례를 지킬지어다 네 가축을 다른 종류와 교미시키지 말며 네 밭에 두 종자를 섞어 뿌리지 말며 두 재료로 직조한 옷을 입지 말지며'),
    (3303, '만일 어떤 사람이 다른 사람과 정혼한 여종 곧 아직 속량되거나 해방되지 못한 여인과 동침하여 설정하면 그것은 책망을 받을 일이니라 그러나 그들은 죽임을 당하지는 아니하리니 그 여인이 해방되지 못하였기 때문이니라'),
    (3306, '○너희가 그 땅에 들어가 각종 과목을 심거든 그 열매는 아직 할례 받지 못한 것으로 여기되 곧 삼 년 동안 너희는 그것을 할례 받지 못한 것으로 여겨 먹지 말 것이요'),
    (3309, '○너희는 무엇이든지 피째 먹지 말며 점을 치지 말며 술법을 행하지 말며'),
    (3312, '○네 딸을 더럽혀 창녀가 되게 하지 말라 음행이 전국에 퍼져 죄악이 가득할까 하노라'),
    (3314, '○너희는 신접한 자와 박수를 믿지 말며 그들을 추종하여 스스로 더럽히지 말라 나는 너희 하나님 여호와이니라'),
    (3315, '○너는 센 머리 앞에서 일어서고 노인의 얼굴을 공경하며 네 하나님을 경외하라 나는 여호와이니라'),
    (3316, '○거류민이 너희의 땅에 거류하여 함께 있거든 너희는 그를 학대하지 말고'),
    (3318, '○너희는 재판할 때나 길이나 무게나 양을 잴 때 불의를 행하지 말고'),
    (3205, '여호와께서 모세에게 이르시되 네 형 아론에게 이르라 성소의 휘장 안 법궤 위 속죄소 앞에 아무 때나 들어오지 말라 그리하여 죽지 않도록 하라 이는 내가 구름 가운데에서 속죄소 위에 나타남이니라'),
    (3209, '○아론은 자기를 위한 속죄제의 수송아지를 드리되 자기와 집안을 위하여 속죄하고'),
    (3214, '○아론은 자기를 위한 속죄제의 수송아지를 드리되 자기와 집안을 위하여 속죄하고 자기를 위한 그 속죄제 수송아지를 잡고'),
    (3217, '그는 또 수송아지의 피를 가져다가 손가락으로 속죄소 동쪽에 뿌리고 또 손가락으로 그 피를 속죄소 앞에 일곱 번 뿌릴 것이며'),
    (3226, '○아론은 회막에 들어가서 지성소에 들어갈 때에 입었던 세마포 옷을 벗어 거기 두고'),
    (3232, '○너희는 영원히 이 규례를 지킬지니라 일곱째 달 곧 그 달 십일에 너희는 스스로 괴롭게 하고 아무 일도 하지 말되 본토인이든지 너희 중에 거류하는 거류민이든지 그리하라'),
    (3326, '○접신한 자와 박수무당을 음란하게 따르는 자에게는 내가 진노하여 그를 그의 백성 중에서 끊으리니'),
    (3330, '○누구든지 남의 아내와 간음하는 자 곧 그의 이웃의 아내와 간음하는 자는 그 간부와 음부를 반드시 죽일지니라'),
    (3337, '○누구든지 그의 자매 곧 그의 아버지의 딸이나 그의 어머니의 딸을 데려다가 그 여자의 하체를 보고 여자는 그 남자의 하체를 보면 부끄러운 일이라 그들의 민족 앞에서 그들이 끊어질지니 그가 자기의 자매의 하체를 범하였은즉 그가 그의 죄를 담당하리라'),
    (3342, '○너희는 나의 모든 규례와 법도를 지켜 행하라 그리하여야 내가 너희를 인도하여 거주하게 하는 땅이 너희를 토하지 아니하리라'),
    (3344, '내가 전에 너희에게 이르기를 너희가 그들의 땅을 기업으로 받을 것이라 내가 그 땅 곧 젖과 꿀이 흐르는 땅을 너희에게 주어 유업을 삼게 하리라 하였노라 나는 너희를 만민 중에서 구별한 너희의 하나님 여호와이니라'),
    (3347, '○남자나 여자가 접신하거나 박수무당이 되거든 반드시 죽일지니 곧 돌로 그를 치라 그들의 피가 자기들에게로 돌아가리라'),
    (3357, '○자기의 형제 중 관유로 부음을 받고 위임되어 그 예복을 입은 대제사장은 그의 머리를 풀지 말며 그의 옷을 찢지 말며'),
    (3363, '○여호와께서 모세에게 말씀하여 이르시되'),
    (3381, '○일반인은 성물을 먹지 못할 것이며 제사장의 객이나 품꾼도 다 성물을 먹지 못할 것이니라'),
    (3388, '<여호와께서 기쁘게 받으시는 제물> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3397, '○여호와께서 모세에게 말씀하여 이르시되'),
    (3453, '<여호와 앞에 진설할 떡> ○너는 고운 가루를 가져다가 떡 열두 개를 굽되 각 덩이를 십분의 이 에바로 하여'),
    (3458, '<여호와의 이름을 모독하면> ○이스라엘 자손 중에 그의 어머니가 이스라엘 여인이요 그의 아버지는 애굽 사람인 어떤 사람이 나가서 한 이스라엘 사람과 진영 중에서 싸우다가'),
    (3465, '사람을 쳐죽인 자는 반드시 죽일 것이요'),
    (3529, '<상과 벌> ○너희가 내 규례와 계명을 준행하면'),
    (3540, '○그러나 너희가 내게 청종하지 아니하여 이 모든 명령을 준행하지 아니하며'),
    (3542, '내가 이같이 너희에게 행하리니 곧 내가 너희에게 놀라운 재앙을 내려 폐병과 열병으로 눈이 어둡고 생명이 쇠약하게 할 것이요 너희가 파종한 것은 헛되리니 너희의 대적이 그것을 먹을 것임이며'),
    (3547, '○너희가 나를 거슬러 내게 청종하지 아니할진대 내가 너희의 죄대로 너희에게 일곱 배나 더 재앙을 내릴 것이라'),
    (3549, '○이런 일을 당하여도 너희가 내게로 돌아오지 아니하고 내게 대항할진대'),
    (3553, '○너희가 이같이 될지라도 내게 청종하지 아니하고 내게 대항할진대'),
    (3560, '○너희가 원수의 땅에 살 동안에 너희의 본토가 황무할 것이므로 땅이 안식을 누릴 것이라 그 때에 땅이 안식을 누리리니'),
    (3562, '너희 남은 자에게는 그 원수들의 땅에서 내가 그들의 마음을 약하게 하리니 그들은 바람에 불린 잎사귀 소리에도 놀라 도망하기를 칼을 피하여 도망하듯 할 것이요 쫓는 자가 없어도 엎드러질 것이라'),
    (3566, '○그들이 나를 거스른 잘못으로 자기의 죄악과 그들의 조상의 죄악을 자복하고 또 그들이 내게 대항하므로'),
    (3570, '그런즉 그들이 그들의 원수들의 땅에 있을 때에 내가 그들을 내버리지 아니하며 미워하지 아니하며 아주 멸하지 아니하고 그들과 맺은 내 언약을 폐하지 아니하리니 나는 여호와 그들의 하나님이 됨이니라'),
    (3572, '○이것은 여호와께서 시내 산에서 자기와 이스라엘 자손 사이에 모세를 통하여 세우신 규례와 법도와 율법이니라'),
    (3581, '○사람이 서원하는 예물로 여호와께 드리는 것이 가축이면 여호와께 드릴 때는 다 거룩하니'),
    (3586, '○만일 어떤 사람이 자기 집을 성별하여 여호와께 드리려하면 제사장이 그 우열간에 값을 정할지니 그 값은 제사장이 정한 대로 될 것이며'),
    (3588, '○만일 어떤 사람이 자기 기업된 밭 얼마를 성별하여 여호와께 드리려하면 마지기 수대로 네가 값을 정하되 보리 한 호멜지기에는 은 오십 세겔로 계산할지며'),
    (3598, '<처음 난 가축> ○오직 가축 중의 처음 난 것은 여호와께 드릴 첫 것이라 소나 양은 여호와의 것이니 누구든지 그것으로는 성별하여 드리지 못할 것이며'),
    (3600, '<여호와께 온전히 바친 것> ○어떤 사람이 자기 소유 중에서 오직 여호와께 온전히 바친 모든 것은 사람이든지 가축이든지 기업의 밭이든지 팔지도 못하고 무르지도 못하나니 바친 것은 다 여호와께 지극히 거룩함이며'),
    (3602, '<십분의 일은 여호와의 것> ○그리고 그 땅의 십분의 일 곧 그 땅의 곡식이나 나무의 열매는 그 십분의 일은 여호와의 것이니 여호와의 성물이라'),
    (3606, '○이것은 여호와께서 시내 산에서 이스라엘 자손을 위하여 모세에게 명령하신 계명이니라'),
    (3408, '<유월절과 무교절> ○이것이 너희가 그 정한 때에 성회로 공포할 여호와의 절기들이니라'),
    (3413, '<첫 이삭 한 단을 바치는 절기> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3419, '<두 번째 거둔 곡식을 바치는 절기> ○안식일 이튿날 곧 너희가 요제로 곡식단을 가져온 날부터 세어서 일곱 안식일의 수효를 채우고'),
    (3422, '너희는 또 이 떡과 함께 일 년 된 흠 없는 어린 양 일곱 마리와 어린 수소 한 마리와 숫양 두 마리를 드리되 이것들을 그 소제와 그 전제제물과 함께 여호와께 드려서 번제로 삼을지니 이는 화제라 여호와께 향기로운 냄새며'),
    (3426, '○너희 땅의 곡물을 벨 때에 밭 모퉁이까지 다 베지 말며 떨어진 것을 줍지 말고 그것을 가난한 자와 거류민을 위하여 남겨두라 나는 너희의 하나님 여호와이니라'),
    (3427, '<일곱째 달 첫 날은 쉬는 날> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3430, '<속죄일> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3437, '<초막절> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3441, '○이것들은 여호와의 절기라 너희는 공포하여 성회를 열고 여호와께 화제를 드릴지니 번제와 소제와 희생제물과 전제를 각각 그 날에 드릴지니'),
    (3443, '○너희가 토지 소산 거두기를 마치거든 일곱째 달 열닷샛날부터 이레 동안 여호와의 절기를 지키되 첫 날에도 안식하고 여덟째 날에도 안식할 것이요'),
    (3479, '<희년> ○너는 일곱 안식년을 계수할지니 이는 칠 년이 일곱 번인즉 안식년 일곱 번 동안 곧 사십구 년이라'),
    (3481, '너희는 오십 년째 해를 거룩하게 하여 그 땅에 있는 모든 주민을 위하여 자유를 공포하라 이 해는 너희에게 희년이니 너희는 각각 자기의 소유지로 돌아가며 각각 자기의 가족에게로 돌아갈지며'),
    (3484, '<부당한 이익을 취하지 말라> ○이 희년에는 너희가 각기 자기의 소유지로 돌아갈지라'),
    (3489, '○너희는 내 규례를 행하며 내 법도를 지켜 행하라 그리하면 너희가 그 땅에 안전하게 거주할 것이라'),
    (3492, '내가 명령하여 여섯째 해에 내 복을 너희에게 주어 그 소출이 삼 년 동안 쓰기에 족하게 하리라'),
    (3494, '○토지를 영구히 팔지 말 것은 토지는 다 내 것임이니라 너희는 거류민이요 동거하는 자로서 나와 함께 있느니라'),
    (3500, '○성벽 있는 성 내의 가옥을 팔았으면 판 지 만 일 년 안에는 무를 수 있나니 곧 그 기한 안에 무르려니와'),
    (3506, '○네 형제가 가난하게 되어 빈 손으로 네 곁에 있거든 너는 그를 도와 거류민이나 동거인처럼 너와 함께 생활하게 하되'),
    (3510, '○너와 함께 있는 네 형제가 가난하게 되어 네게 몸이 팔리거든 너는 그를 종으로 부리지 말고'),
    (3516, '또 너희 중에 거류하는 동거인들의 자녀 중에서도 너희가 사올 수 있고 또 그들이 너희와 함께 있어서 너희 땅에서 가정을 이룬 자들 중에서도 그리 할 수 있은즉 그들이 너희의 소유가 될지니라'),
    (3518, '○만일 너와 함께 있는 거류민이나 동거인은 부유하게 되고 그와 함께 있는 네 형제는 가난하게 되므로 그가 너와 함께 있는 거류민이나 동거인 또는 거류민의 가족의 후손에게 팔리면'),
    (3525, '그가 이같이 속량되지 못하면 희년에 이르러는 그와 그의 자녀가 자유하리니'),
    (3670, '○남쪽에는 르우벤 군대 진영의 군기가 있을 것이라 르우벤 자손의 지휘관은 스데울의 아들 엘리술이요'),
    (3677, '○그 다음에 회막이 레위인의 진영과 함께 모든 진영의 중앙에 있어 행진하되 그들의 진 친 순서대로 각 사람은 자기의 위치에서 자기들의 기를 따라 앞으로 행진할지니라'),
    (3678, '○서쪽에는 에브라임의 군대의 진영의 군기가 있을 것이라 에브라임 자손의 지휘관은 암미훗의 아들 엘리사마요'),
    (3685, '○북쪽에는 단 군대 진영의 군기가 있을 것이라 단 자손의 지휘관은 암미삿대의 아들 아히에셀이요'),
    (3692, '○이상은 이스라엘 자손이 그들의 조상의 가문을 따라 계수된 자니 모든 진영의 군인 곧 계수된 자의 총계는 육십만 삼천오백오십 명이며'),
    (3626, '○이스라엘의 장자 르우벤의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 각 남자를 그 명수대로 다 계수하니'),
    (3628, '○시므온의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 각 남자를 그 명수대로 다 계수하니'),
    (3630, '○갓의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3632, '○유다의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3634, '○잇사갈의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3636, '○스불론의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3638, '○요셉의 아들 에브라임의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3640, '○므낫세의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3642, '○베냐민의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3644, '○단의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3646, '○아셀의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3648, '○납달리의 아들들에게서 난 자를 그들의 종족과 조상의 가문에 따라 이십 세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
    (3650, '○이 계수함을 받은 자는 모세와 아론과 각기 이스라엘 조상의 가문을 대표한 열두 지휘관이 계수하였더라'),
    (3653, '<레위 지파는 계수하지 말라> ○그러나 레위인은 그들의 조상의 지파대로 그 계수에 들지 아니하였으니'),
    (3760, '진영을 떠날 때에 아론과 그의 아들들이 성소와 성소의 모든 기구 덮는 일을 마치거든 고핫 자손들이 와서 멜 것이니라 그러나 성물은 만지지 말라 그들이 죽으리라 회막 물건 중에서 이것들은 고핫 자손이 멜 것이며'),
    (3762, '○여호와께서 또 모세와 아론에게 말씀하여 이르시되'),
    (3766, '<게르손 자손의 임무> ○여호와께서 또 모세에게 말씀하여 이르시되'),
    (3774, '<므라리 자손의 임무> ○너는 므라리 자손도 그 조상의 가문과 종족에 따라 계수하되'),
    (3779, '<레위 사람 인구 조사> ○모세와 아론과 회중의 지도자들이 고핫 자손들을 그 종족과 조상의 가문에 따라 계수하니'),
    (3783, '○게르손 자손 중 그 종족과 조상의 가문을 따라 계수된 자는'),
    (3787, '○므라리 자손의 종족 중 그 종족과 조상의 가문을 따라 계수된 자는'),
    (3791, '○모세와 아론과 이스라엘 지휘관들이 레위인을 그 종족과 조상의 가문에 따라 다 계수하니'),
    (3864, '○첫째 날에 헌물을 드린 자는 유다 지파 암미나답의 아들 나손이라'),
    (3870, '○둘째 날에는 잇사갈의 지휘관 수알의 아들 느다넬이 헌물을 드렸으니'),
    (3876, '○셋째 날에는 스불론 자손의 지휘관 헬론의 아들 엘리압이 헌물을 드렸으니'),
    (3882, '○넷째 날에는 르우벤 자손의 지휘관 스데울의 아들 엘리술이 헌물을 드렸으니'),
    (3888, '○다섯째 날에는 시므온 자손의 지휘관 수리삿대의 아들 슬루미엘이 헌물을 드렸으니'),
    (3894, '○여섯째 날에는 갓 자손의 지휘관 드우엘의 아들 엘리아삽이 헌물을 드렸으니'),
    (3900, '○일곱째 날에는 에브라임 자손의 지휘관 암미훗의 아들 엘리사마가 헌물을 드렸으니'),
    (3906, '○여덟째 날에는 므낫세 자손의 지휘관 브다술의 아들 가말리엘이 헌물을 드렸으니'),
    (3912, '○아홉째 날에는 베냐민 자손의 지휘관 기드오니의 아들 아비단이 헌물을 드렸으니'),
    (3918, '○열째 날에는 단 자손의 지휘관 암미삿대의 아들 아히에셀이 헌물을 드렸으니'),
    (3924, '○열한째 날에는 아셀 자손의 지휘관 오그란의 아들 바기엘이 헌물을 드렸으니'),
    (3930, '○열두째 날에는 납달리 자손의 지휘관 에난의 아들 아히라가 헌물을 드렸으니'),
    (3936, '○이는 곧 제단에 기름 바르던 날에 이스라엘 지휘관들이 드린 바 제단의 봉헌물이라 은 쟁반이 열둘이요 은 바리가 열둘이요 금 그릇이 열둘이니'),
    (3941, '○모세가 회막에 들어가서 여호와께 말하려 할 때에 증거궤 위 속죄소 위의 두 그룹 사이에서 자기에게 말씀하시는 목소리를 들었으니 여호와께서 그에게 말씀하심이었더라'),
    (3838, '○나실인의 법은 이러하니라 자기의 몸을 구별한 날이 차면 그 사람을 회막 문으로 데리고 갈 것이요'),
    (3846, '○이는 곧 서원한 나실인이 자기의 몸을 구별한 일로 말미암아 여호와께 헌물을 드림과 행할 법이며 이외에도 힘이 미치는 대로 하려니와 그가 서원한 대로 자기의 몸을 구별하는 법을 따라 할 것이니라'),
    (3847, '<제사장의 축복> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3852, '○그들은 이같이 내 이름으로 이스라엘 자손에게 축복할지니 내가 그들에게 복을 주리라'),
    (3799, '<죄에 대한 값> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3805, '<아내의 간통을 밝히는 절차> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3809, '그의 아내를 데리고 제사장에게로 가서 그를 위하여 보리 가루 십분의 일 에바를 헌물로 드리되 그것에 기름도 붓지 말고 유향도 두지 말라 이는 의심의 소제요 죄악을 기억나게 하는 기억의 소제라'),
    (3810, '○제사장은 그 여인을 가까이 오게 하여 여호와 앞에 세우고'),
    (3817, '○제사장이 저주의 말을 두루마리에 써서 그 글자를 그 쓴 물에 빨아 넣고'),
    (3821, '그 물을 마시게 한 후에 만일 여인이 몸을 더럽혀서 그 남편에게 범죄하였으면 그 저주가 되게 하는 물이 그의 속에 들어가서 쓰게 되어 그의 배가 부으며 그의 넓적다리가 마르리니 그 여인이 그 백성 중에서 저줏거리가 될 것이니라'),
    (3823, '○이는 의심의 법이니 아내가 그의 남편을 두고 탈선하여 더럽힌 때나'),
    (3946, '<레위인을 요제로 여호와께 드리다> ○여호와께서 모세에게 말씀하여 이르시되'),
    (3955, '○너는 이같이 이스라엘 자손 중에서 레위인을 구별하라 그리하면 그들이 내게 속할 것이라'),
    (3960, '내가 이스라엘 자손 중에서 레위인을 취하여 그들을 아론과 그의 아들들에게 주어 그들로 회막에서 이스라엘 자손을 대신하여 봉사하게 하며 또 이스라엘 자손을 위하여 속죄하게 하였나니 이는 이스라엘 자손이 성소에 가까이 할 때에 그들 중에 재앙이 없게 하려 하였음이니라'),
    (3961, '○모세와 아론과 이스라엘 자손의 온 회중이 여호와께서 레위인에 대하여 모세에게 명령하신 것을 다 따라 레위인에게 행하였으되 곧 이스라엘 자손이 그와 같이 그들에게 행하였더라'),
    (3964, '○여호와께서 또 모세에게 말씀하여 이르시되'),
    (3976, '○여호와께서 모세에게 말씀하여 이르시되'),
    (3980, '그러나 사람이 정결하기도 하고 여행 중에도 있지 아니하면서 유월절을 지키지 아니하는 자는 그 백성 중에서 끊어지리니 이런 사람은 그 정한 기일에 여호와께 헌물을 드리지 아니하였은즉 그의 죄를 담당할지며'),
    (3982, '<길을 안내한 구름> ○성막을 세운 날에 구름이 성막 곧 증거의 성막을 덮었고 저녁이 되면 성막 위에 불 모양 같은 것이 나타나서 아침까지 이르렀으되'),
    (3699, '<제사장을 돕는 레위 사람> ○여호와께서 또 모세에게 말씀하여 이르시되'),
    (3705, '○여호와께서 모세에게 말씀하여 이르시되'),
    (3706, '보라 내가 이스라엘 자손 중에서 레위인을 택하여 이스라엘 자손 중에 태를 열어 태어난 모든 맏이를 대신하게 하였은즉 레위인은 내 것이라'),
    (3707, '처음 태어난 자는 다 내 것임은 내가 애굽 땅에서 그 처음 태어난 자를 다 죽이던 날에 이스라엘의 처음 태어난 자는 사람이나 짐승을 다 거룩하게 구별하였음이니 그들은 내 것이 될 것임이니라 나는 여호와이니라'),
    (3708, '<레위 자손 인구 조사> ○여호와께서 시내 광야에서 모세에게 말씀하여 이르시되'),
    (3715, '○게르손에게서는 립니 종족과 시므이 종족이 났으니 이들이 곧 게르손의 조상의 가문들이라'),
    (3721, '○고핫에게서는 아므람 종족과 이스할 종족과 헤브론 종족과 웃시엘 종족이 났으니 이들은 곧 고핫 종족들이라'),
    (3727, '○므라리에게서는 말리 종족과 무시 종족이 났으니 이들은 곧 므라리 종족들이라'),
    (3732, '○성막 앞 동쪽 곧 회막 앞 해 돋는 쪽에는 모세와 아론과 아론의 아들들이 진을 치고 이스라엘 자손의 직무를 위하여 성소의 직무를 수행할 것이며 외인이 가까이 하면 죽일지니라'),
    (3734, '<레위 사람이 맏아들 구실을 하다> ○여호와께서 또 모세에게 이르시되 이스라엘 자손의 처음 태어난 남자를 일 개월 이상으로 다 계수하여 그 명수를 기록하라'),
    (3738, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4001, '<이스라엘 자손이 진행하기를 시작하다> ○둘째 해 둘째 달 스무날에 구름이 증거의 성막에서 떠오르매'),
    (4007, '○이에 성막을 걷으매 게르손 자손과 므라리 자손이 성막을 메고 출발하였으며'),
    (4011, '○고핫인은 성물을 메고 행진하였고 그들이 이르기 전에 성막을 세웠으며'),
    (4015, '○다음으로 단 자손 진영의 군기에 속한 자들이 그들의 진영별로 행진하였으니 이 군대는 모든 진영의 마지막 진영이었더라 단 군대는 암미삿대의 아들 아히에셀이 이끌었고'),
    (4019, '○모세가 모세의 장인 미디안 사람 르우엘의 아들 호밥에게 이르되 여호와께서 주마 하신 곳으로 우리가 행진하나니 우리와 동행하자 그리하면 선대하리라 여호와께서 이스라엘에게 복을 내리리라 하셨느니라'),
    (4023, '○그들이 여호와의 산에서 떠나 삼 일 길을 갈 때에 여호와의 언약궤가 그 삼 일 길에 앞서 가며 그들의 쉴 곳을 찾았고'),
    (4025, '○궤가 떠날 때에는 모세가 말하되 여호와여 일어나사 주의 대적들을 흩으시고 주를 미워하는 자가 주 앞에서 도망하게 하소서 하였고'),
    (4065, '○여호와께서 갑자기 모세와 아론과 미리암에게 이르시되 너희 세 사람은 회막으로 나아오라 하시니 그 세 사람이 나아가매'),
    (4075, '여호와께서 모세에게 이르시되 그의 아버지가 그의 얼굴에 침을 뱉었을지라도 그가 이레 동안 부끄러워하지 않겠느냐 그런즉 그를 진영 밖에 이레 동안 가두고 그 후에 들어오게 할지니라 하시니'),
    (4030, '<모세가 장로 칠십 인을 뽑다> ○그들 중에 섞여 사는 다른 인종들이 탐욕을 품으매 이스라엘 자손도 다시 울며 이르되 누가 우리에게 고기를 주어 먹게 하랴'),
    (4036, '○백성의 온 종족들이 각기 자기 장막 문에서 우는 것을 모세가 들으니라 이러므로 여호와의 진노가 심히 크고 모세도 기뻐하지 아니하여'),
    (4038, '이 모든 백성을 내가 배었나이까 내가 그들을 낳았나이까 어찌 주께서 내게 양육하는 아버지가 젖 먹는 아이를 품듯 그들을 품에 품고 주께서 그들의 열조에게 맹세하신 땅으로 가라 하시나이까'),
    (4042, '○여호와께서 모세에게 이르시되 이스라엘 노인 중에 네가 알기로 백성의 장로와 지도자가 될 만한 자 칠십 명을 모아 내게 데리고 와 회막에 이르러 거기서 너와 함께 서게 하라'),
    (4044, '또 백성에게 이르기를 너희의 몸을 거룩히 하여 내일 고기 먹기를 기다리라 너희가 울며 이르기를 누가 우리에게 고기를 주어 먹게 하랴 애굽에 있을 때가 우리에게 좋았다 하는 말이 여호와께 들렸으므로 여호와께서 너희에게 고기를 주어 먹게 하실 것이라'),
    (4050, '○모세가 나가서 여호와의 말씀을 백성에게 알리고 백성의 장로 칠십 인을 모아 장막에 둘러 세우매'),
    (4052, '○그 기명된 자 중 엘닷이라 하는 자와 메닷이라 하는 자 두 사람이 진영에 머물고 장막에 나아가지 아니하였으나 그들에게도 영이 임하였으므로 진영에서 예언한지라'),
    (4057, '<여호와께서 메추라기를 보내시다> ○바람이 여호와에게서 나와 바다에서부터 메추라기를 몰아 진영 곁 이쪽 저쪽 곧 진영 사방으로 각기 하룻길 되는 지면 위 두 규빗쯤에 내리게 한지라'),
    (4078, '<가나안 땅 정탐> 여호와께서 모세에게 말씀하여 이르시되'),
    (4094, '○모세가 가나안 땅을 정탐하러 그들을 보내며 이르되 너희는 네겝 길로 행하여 산지로 올라가서'),
    (4098, '○이에 그들이 올라가서 땅을 정탐하되 신 광야에서부터 하맛 어귀 르홉에 이르렀고'),
    (4102, '○사십 일 동안 땅을 정탐하기를 마치고 돌아와'),
    (4107, '○갈렙이 모세 앞에서 백성을 조용하게 하고 이르되 우리가 곧 올라가서 그 땅을 취하자 능히 이기리라 하나'),
    (4114, '○이에 서로 말하되 우리가 한 지휘관을 세우고 애굽으로 돌아가자 하매'),
    (4121, '<모세가 백성을 두고 기도하다> ○여호와께서 모세에게 이르시되 이 백성이 어느 때까지 나를 멸시하겠느냐 내가 그들 중에 많은 이적을 행하였으나 어느 때까지 나를 믿지 않겠느냐'),
    (4123, '○모세가 여호와께 여짜오되 애굽인 중에서 주의 능력으로 이 백성을 인도하여 내셨거늘 그리하시면 그들이 듣고'),
    (4124, '이 땅 거주민에게 전하리이다 주 여호와께서 이 백성 중에 계심을 그들도 들었으니 곧 주 여호와께서 대면하여 보이시며 주의 구름이 그들 위에 섰으며 주께서 낮에는 구름 기둥 가운데에서, 밤에는 불 기둥 가운데에서 그들 앞에 행하시는 것이니이다'),
    (4130, '○여호와께서 이르시되 내가 네 말대로 사하노라'),
    (4136, '<여호와께서 원망하는 백성을 벌하시다> ○여호와께서 모세와 아론에게 말씀하여 이르시되'),
    (4146, '○모세의 보냄을 받고 땅을 정탐하고 돌아와서 그 땅을 악평하여 온 회중이 모세를 원망하게 한 사람'),
    (4149, '<첫번째 점령 시도> ○모세가 이 말로 이스라엘 모든 자손에게 알리매 백성이 크게 슬퍼하여'),
    (4166, '○수송아지나 숫양이나 어린 숫양이나 어린 염소에는 그 마리 수마다 위와 같이 행하되'),
    (4172, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4177, '○너희가 그릇 범죄하여 여호와가 모세에게 말씀하신 이 모든 명령을 지키지 못하되'),
    (4180, '제사장이 이스라엘 자손의 온 회중을 위하여 속죄하면 그들이 사함을 받으리니 이는 그가 부지중에 범죄함이며 또 부지중에 범죄함으로 말미암아 헌물 곧 화제와 속죄제를 여호와께 드렸음이라'),
    (4182, '○만일 한 사람이 부지중에 범죄하면 일 년 된 암염소로 속죄제를 드릴 것이요'),
    (4187, '<안식일에 일을 한 사람> ○이스라엘 자손이 광야에 거류할 때에 안식일에 어떤 사람이 나무하는 것을 발견한지라'),
    (4192, '<옷단 귀에 다는 술> ○여호와께서 모세에게 말씀하여 이르시되'),
    (4248, '너는 이스라엘 자손에게 말하여 그들 중에서 각 조상의 가문을 따라 지팡이 하나씩을 취하되 곧 그들의 조상의 가문대로 그 모든 지휘관에게서 지팡이 열둘을 취하고 그 사람들의 이름을 각각 그 지팡이에 쓰되'),
    (4254, '○이튿날 모세가 증거의 장막에 들어가 본즉 레위 집을 위하여 낸 아론의 지팡이에 움이 돋고 순이 나고 꽃이 피어서 살구 열매가 열렸더라'),
    (4258, '○이스라엘 자손이 모세에게 말하여 이르되 보소서 우리는 죽게 되었나이다 망하게 되었나이다 다 망하게 되었나이다'),
    (4199, '그들이 모여서 모세와 아론을 거슬러 그들에게 이르되 너희가 분수에 지나도다 회중이 다 각각 거룩하고 여호와께서도 그들 중에 계시거늘 너희가 어찌하여 여호와의 총회 위에 스스로 높이느냐'),
    (4200, '○모세가 듣고 엎드렸다가'),
    (4201, '고라와 그의 모든 무리에게 말하여 이르되 아침에 여호와께서 자기에게 속한 자가 누구인지, 거룩한 자가 누구인지 보이시고 그 사람을 자기에게 가까이 나아오게 하시되 곧 그가 택하신 자를 자기에게 가까이 나아오게 하시리니'),
    (4205, '이스라엘의 하나님이 이스라엘 회중에서 너희를 구별하여 자기에게 가까이 하게 하사 여호와의 성막에서 봉사하게 하시며 회중 앞에 서서 그들을 대신하여 섬기게 하심이 너희에게 작은 일이겠느냐'),
    (4208, '○모세가 엘리압의 아들 다단과 아비람을 부르러 사람을 보냈더니 그들이 이르되 우리는 올라가지 않겠노라'),
    (4210, '이뿐 아니라 네가 우리를 젖과 꿀이 흐르는 땅으로 인도하여 들이지도 아니하고 밭도 포도원도 우리에게 기업으로 주지 아니하니 네가 이 사람들의 눈을 빼려느냐 우리는 올라가지 아니하겠노라'),
    (4211, '○모세가 심히 노하여 여호와께 여짜오되 주는 그들의 헌물을 돌아보지 마옵소서 나는 그들의 나귀 한 마리도 빼앗지 아니하였고 그들 중의 한 사람도 해하지 아니하였나이다 하고'),
    (4216, '○여호와께서 모세와 아론에게 말씀하여 이르시되'),
    (4221, '○모세가 일어나 다단과 아비람에게로 가니 이스라엘 장로들이 따랐더라'),
    (4227, '○그가 이 모든 말을 마치자마자 그들이 섰던 땅바닥이 갈라지니라'),
    (4232, '<향로> ○여호와께서 모세에게 말씀하여 이르시되'),
    (4234, '사람들은 범죄하여 그들의 생명을 스스로 해하였거니와 그들이 향로를 여호와 앞에 드렸으므로 그 향로가 거룩하게 되었나니 그 향로를 쳐서 제단을 싸는 철판을 만들라 이스라엘 자손에게 표가 되리라 하신지라'),
    (4236, '이스라엘 자손의 기념물이 되게 하였으니 이는 아론 자손이 아닌 다른 사람은 여호와 앞에 분향하러 가까이 오지 못하게 함이며 또 고라와 그의 무리와 같이 되지 않게 하기 위함이라 여호와께서 모세를 시켜 그에게 명령하신 대로 하였더라'),
    (4237, '<아론이 백성을 구하다> ○이튿날 이스라엘 자손의 온 회중이 모세와 아론을 원망하여 이르되 너희가 여호와의 백성을 죽였도다 하고'),
    (4242, '이에 모세가 아론에게 이르되 너는 향로를 가져다가 제단의 불을 그것에 담고 그 위에 향을 피워 가지고 급히 회중에게로 가서 그들을 위하여 속죄하라 여호와께서 진노하셨으므로 염병이 시작되었음이니라'),
    (4301, '암송아지의 재를 거둔 자도 자기의 옷을 빨 것이며 저녁까지 부정하리라 이는 이스라엘 자손과 그 중에 거류하는 외인에게 영원한 율례니라'),
    (4302, '<시체를 만진 자> ○사람의 시체를 만진 자는 이레 동안 부정하리니'),
    (4304, '누구든지 죽은 사람의 시체를 만지고 자신을 정결하게 하지 아니하는 자는 여호와의 성막을 더럽힘이라 그가 이스라엘에서 끊어질 것은 정결하게 하는 물을 그에게 뿌리지 아니하므로 깨끗하게 되지 못하고 그 부정함이 그대로 있음이니라'),
    (4305, '○장막에서 사람이 죽을 때의 법은 이러하니 누구든지 그 장막에 들어가는 자와 그 장막에 있는 자가 이레 동안 부정할 것이며'),
    (4311, '○사람이 부정하고도 자신을 정결하게 하지 아니하면 여호와의 성소를 더럽힘이니 그러므로 회중 가운데에서 끊어질 것이니라 그는 정결하게 하는 물로 뿌림을 받지 아니하였은즉 부정하니라'),
    (4314, '<가데스의 다툼과 므리바 물> 첫째 달에 이스라엘 자손 곧 온 회중이 신 광야에 이르러 백성이 가데스에 머물더니 미리암이 거기서 죽으매 거기에 장사되니라'),
    (4315, '○회중이 물이 없으므로 모세와 아론에게로 모여드니라'),
    (4323, '○모세와 아론이 회중을 그 반석 앞에 모으고 모세가 그들에게 이르되 반역한 너희여 들으라 우리가 너희를 위하여 이 반석에서 물을 내랴 하고'),
    (4325, '여호와께서 모세와 아론에게 이르시되 너희가 나를 믿지 아니하고 이스라엘 자손의 목전에서 내 거룩함을 나타내지 아니한 고로 너희는 이 회중을 내가 그들에게 준 땅으로 인도하여 들이지 못하리라 하시니라'),
    (4327, '<에돔이 이스라엘이 지나감을 거절하다> ○모세가 가데스에서 에돔 왕에게 사신을 보내며 이르되 당신의 형제 이스라엘의 말에 우리가 당한 모든 고난을 당신도 아시거니와'),
    (4330, '청하건대 우리에게 당신의 땅을 지나가게 하소서 우리가 밭으로나 포도원으로 지나가지 아니하고 우물물도 마시지 아니하고 왕의 큰길로만 지나가고 당신의 지경에서 나가기까지 왼쪽으로나 오른쪽으로나 치우치지 아니하리이다 한다고 하라 하였더니'),
    (4335, '<아론의 죽음> ○이스라엘 자손 곧 온 회중이 가데스를 떠나 호르 산에 이르렀더니'),
    (4428, '야곱의 티끌을 누가 능히 세며 이스라엘 사분의 일을 누가 능히 셀꼬 나는 의인의 죽음을 죽기 원하며 나의 종말이 그와 같기를 바라노라 하매'),
    (4431, '<발람의 두 번째 예언> ○발락이 말하되 나와 함께 그들을 달리 볼 곳으로 가자 거기서는 그들을 다 보지 못하고 그들의 끝만 보리니 거기서 나를 위하여 그들을 저주하라 하고'),
    (4445, '<발람의 세 번째 예언> ○발락이 발람에게 또 이르되 오라 내가 너를 다른 곳으로 인도하리니 네가 거기서 나를 위하여 그들을 저주하기를 하나님이 혹시 기뻐하시리라 하고'),
    (4379, '○십볼의 아들 발락이 이스라엘이 아모리인에게 행한 모든 일을 보았으므로'),
    (4383, '우리보다 강하니 청하건대 와서 나를 위하여 이 백성을 저주하라 내가 혹 그들을 쳐서 이겨 이 땅에서 몰아내리라 그대가 복을 비는 자는 복을 받고 저주하는 자는 저주를 받을 줄을 내가 앎이니라'),
    (4384, '○모압 장로들과 미디안 장로들이 손에 복채를 가지고 떠나 발람에게 이르러 발락의 말을 그에게 전하매'),
    (4392, '○발락이 다시 그들보다 더 높은 고관들을 더 많이 보내매'),
    (4398, '<발람과 그 나귀> ○발람이 아침에 일어나서 자기 나귀에 안장을 지우고 모압 고관들과 함께 가니'),
    (4406, '발람이 나귀에게 말하되 네가 나를 거역하기 때문이니 내 손에 칼이 있었다면 곧 너를 죽였으리라'),
    (4408, '○그 때에 여호와께서 발람의 눈을 밝히시매 여호와의 사자가 손에 칼을 빼들고 길에 선 것을 그가 보고 머리를 숙이고 엎드리니'),
    (4413, '<발락이 발람을 대접하다> ○발락은 발람이 온다 함을 듣고 모압 변경의 끝 아르논 가에 있는 성읍까지 가서 그를 영접하고'),
    (4418, '<발람의 첫번째 예언> ○아침에 발락이 발람과 함께 하고 그를 인도하여 바알의 산당에 오르매 발람이 거기서 이스라엘 백성의 진 끝까지 보니라'),
    (4458, '<발람의 마지막 예언> ○발락이 발람에게 노하여 손뼉을 치며 말하되 내가 그대를 부른 것은 내 원수를 저주하라는 것이어늘 그대가 이같이 세 번 그들을 축복하였도다'),
    (4465, '내가 그를 보아도 이 때의 일이 아니며 내가 그를 바라보아도 가까운 일이 아니로다 한 별이 야곱에게서 나오며 한 규가 이스라엘에게서 일어나서 모압을 이쪽에서 저쪽까지 쳐서 무찌르고 또 셋의 자식들을 다 멸하리로다'),
    (4260, '<제사장과 레위인의 직무> 여호와께서 아론에게 이르시되 너와 네 아들들과 네 조상의 가문은 성소에 대한 죄를 함께 담당할 것이요 너와 네 아들들은 너희의 제사장 직분에 대한 죄를 함께 담당할 것이니라'),
    (4267, '<제사장의 몫> ○여호와께서 또 아론에게 이르시되 보라 내가 내 거제물 곧 이스라엘 자손이 거룩하게 한 모든 헌물을 네가 주관하게 하고 네가 기름 부음을 받았음으로 말미암아 그것을 너와 네 아들들에게 영구한 몫의 음식으로 주노라'),
    (4280, '<레위인의 몫> ○내가 이스라엘의 십일조를 레위 자손에게 기업으로 다 주어서 그들이 하는 일 곧 회막에서 하는 일을 갚나니'),
    (4284, '<레위인의 십일조> ○여호와께서 모세에게 말씀하여 이르시되'),
    (4346, '<놋뱀으로 백성을 구하다> ○백성이 호르 산에서 출발하여 홍해 길을 따라 에돔 땅을 우회하려 하였다가 길로 말미암아 백성의 마음이 상하니라'),
    (4347, '백성이 하나님과 모세를 향하여 원망하되 어찌하여 우리를 애굽에서 인도해 내어 이 광야에서 죽게 하는가 이 곳에는 먹을 것도 없고 물도 없도다 우리 마음이 이 하찮은 음식을 싫어하노라 하매'),
    (4352, '<이스라엘 자손이 모압으로 떠나다> ○이스라엘 자손이 그 곳을 떠나 오봇에 진을 쳤고'),
    (4363, '<요단 동쪽을 점령하다> ○이스라엘이 아모리 왕 시혼에게 사신을 보내어 이르되'),
    (4375, '○그들이 돌이켜 바산 길로 올라가매 바산 왕 옥이 그의 백성을 다 거느리고 나와서 그들을 맞아 에드레이에서 싸우려 하는지라'),
    (4479, '○이스라엘 자손의 온 회중이 회막 문에서 울 때에 이스라엘 자손 한 사람이 모세와 온 회중의 눈앞에 미디안의 한 여인을 데리고 그의 형제에게로 온지라'),
    (4483, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4487, '○죽임을 당한 이스라엘 남자 곧 미디안 여인과 함께 죽임을 당한 자의 이름은 시므리니 살루의 아들이요 시므온인의 조상의 가문 중 한 지도자이며'),
    (4489, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4580, '<날마다 바치는 번제물> 여호와께서 모세에게 말씀하여 이르시되'),
    (4588, '<안식일> ○안식일에는 일 년 되고 흠 없는 숫양 두 마리와 고운 가루 십분의 이에 기름 섞은 소제와 그 전제를 드릴 것이니'),
    (4590, '<초하루> ○초하루에는 수송아지 두 마리와 숫양 한 마리와 일 년 되고 흠 없는 숫양 일곱 마리로 여호와께 번제를 드리되'),
    (4595, '<유월절> ○첫째 달 열넷째 날은 여호와를 위하여 지킬 유월절이며'),
    (4605, '<칠칠절> ○칠칠절 처음 익은 열매를 드리는 날에 너희가 여호와께 새 소제를 드릴 때에도 성회로 모일 것이요 아무 일도 하지 말 것이며'),
    (4496, '○이스라엘의 장자는 르우벤이라 르우벤 자손은 하녹에게서 난 하녹 종족과 발루에게서 난 발루 종족과'),
    (4503, '○시므온 자손의 종족들은 이러하니 느무엘에게서 난 느무엘 종족과 야민에게서 난 야민 종족과 야긴에게서 난 야긴 종족과'),
    (4506, '○갓 자손의 종족들은 이러하니 스본에게서 난 스본 종족과 학기에게서 난 학기 종족과 수니에게서 난 수니 종족과'),
    (4510, '○유다의 아들들은 에르와 오난이라 이 에르와 오난은 가나안 땅에서 죽었고'),
    (4517, '○스불론 자손의 종족들은 이러하니 세렛에게서 난 세렛 종족과 엘론에게서 난 엘론 종족과 얄르엘에게서 난 얄르엘 종족이라'),
    (4519, '○요셉의 아들들의 종족들은 므낫세와 에브라임이요'),
    (4526, '○에브라임 자손의 종족들은 이러하니 수델라에게서 난 수델라 종족과 베겔에게서 난 베겔 종족과 다한에게서 난 다한 종족이며'),
    (4529, '○베냐민 자손의 종족들은 이러하니 벨라에게서 난 벨라 종족과 아스벨에게서 난 아스벨 종족과 아히람에게서 난 아히람 종족과'),
    (4533, '○단 자손의 종족들은 이러하니라 수함에게서 수함 종족이 났으니 이는 그들의 종족을 따른 단 종족들이라'),
    (4535, '○아셀 자손의 종족들은 이러하니 임나에게서 난 임나 종족과 이스위에게서 난 이스위 종족과 브리아에게서 난 브리아 종족이며'),
    (4539, '○납달리 자손은 그들의 종족대로 이러하니 야셀에게서 난 야셀 종족과 구니에게서 난 구니 종족과'),
    (4542, '○이스라엘 자손의 계수된 자가 육십만 천칠백삼십 명이었더라'),
    (4543, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4548, '○레위인으로 계수된 자들의 종족들은 이러하니 게르손에게서 난 게르손 종족과 고핫에게서 난 고핫 종족과 므라리에게서 난 므라리 종족이며'),
    (4554, '○이는 모세와 제사장 엘르아살이 계수한 자라 그들이 여리고 맞은편 요단 가 모압 평지에서 이스라엘 자손을 계수한 중에는'),
    (4656, '○또 혹시 남편을 맞을 때에 서원이나 결심한 서약을 경솔하게 그의 입술로 말하였으면'),
    (4659, '○과부나 이혼 당한 여자의 서원이나 그가 결심한 모든 서약은 지킬 것이니라'),
    (4662, '그러나 그의 남편이 그것을 듣는 날에 무효하게 하면 그 서원과 결심한 일에 대하여 입술로 말한 것을 아무것도 이루지 못하나니 그의 남편이 그것을 무효하게 하였은즉 여호와께서 그 부녀를 사하시느니라'),
    (4663, '○모든 서원과 마음을 자제하기로 한 모든 서약은 그의 남편이 그것을 지키게도 할 수 있고 무효하게도 할 수 있으니'),
    (4611, '<일곱째 달 초하루> 일곱째 달에 이르러는 그 달 초하루에 성회로 모이고 아무 노동도 하지 말라 이는 너희가 나팔을 불 날이니라'),
    (4617, '<속죄일> ○일곱째 달 열흘 날에는 너희가 성회로 모일 것이요 너희의 심령을 괴롭게 하며 아무 일도 하지 말 것이니라'),
    (4622, '<장막절> ○일곱째 달 열다섯째 날에는 너희가 성회로 모일 것이요 아무 일도 하지 말 것이며 이레 동안 여호와 앞에 절기를 지킬 것이라'),
    (4627, '○둘째 날에는 수송아지 열두 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4630, '○셋째 날에는 수송아지 열한 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4633, '○넷째 날에는 수송아지 열 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4636, '○다섯째 날에는 수송아지 아홉 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4639, '○여섯째 날에는 수송아지 여덟 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4642, '○일곱째 날에는 수송아지 일곱 마리와 숫양 두 마리와 일 년 되고 흠 없는 숫양 열네 마리를 드릴 것이며'),
    (4645, '○여덟째 날에는 장엄한 대회로 모일 것이요 아무 일도 하지 말 것이며'),
    (4649, '○너희가 이 절기를 당하거든 여호와께 이같이 드릴지니 이는 너희의 서원제나 낙헌제로 드리는 번제, 소제, 전제, 화목제 외에 드릴 것이니라'),
    (4557, '<슬로브핫의 딸들> 요셉의 아들 므낫세 종족들에게 므낫세의 현손 마길의 증손 길르앗의 손자 헤벨의 아들 슬로브핫의 딸들이 찾아왔으니 그의 딸들의 이름은 말라와 노아와 호글라와 밀가와 디르사라'),
    (4562, '○여호와께서 모세에게 말씀하여 이르시되'),
    (4568, '<모세의 후계자 여호수아> ○여호와께서 모세에게 이르시되 너는 이 아바림 산에 올라가서 내가 이스라엘 자손에게 준 땅을 바라보라'),
    (4767, '○이스라엘 자손이 라암셋을 떠나 숙곳에 진을 치고'),
    (4800, '○이스라엘 자손이 애굽 땅에서 나온 지 사십 년째 오월 초하루에 제사장 아론이 여호와의 명령으로 호르 산에 올라가 거기서 죽었으니'),
    (4802, '○가나안 땅 남방에 살고 있는 가나안 사람 아랏 왕은 이스라엘 자손이 온다는 소식을 들었더라'),
    (4803, '○그들이 호르 산을 떠나 살모나에 진을 치고'),
    (4812, '<가나안 땅을 제비 뽑아 나누다> ○여리고 맞은편 요단 강 가 모압 평지에서 여호와께서 모세에게 말씀하여 이르시되'),
    (4816, '너희의 종족을 따라 그 땅을 제비 뽑아 나눌 것이니 수가 많으면 많은 기업을 주고 적으면 적은 기업을 주되 각기 제비 뽑은 대로 그 소유가 될 것인즉 너희 조상의 지파를 따라 기업을 받을 것이니라'),
    (4824, '○서쪽 경계는 대해가 경계가 되나니 이는 너희의 서쪽 경계니라'),
    (4825, '○북쪽 경계는 이러하니 대해에서부터 호르 산까지 그어라'),
    (4828, '○너희의 동쪽 경계는 하살에난에서 그어 스밤에 이르고'),
    (4831, '○모세가 이스라엘 자손에게 명령하여 이르되 이는 너희가 제비 뽑아 받을 땅이라 여호와께서 이것을 아홉 지파 반 쪽에게 주라고 명령하셨나니'),
    (4834, '<각 지파의 기업 분할 책임자> ○여호와께서 또 모세에게 말씀하여 이르시되'),
    (4721, '<요단 강 동쪽 지파들> 르우벤 자손과 갓 자손은 심히 많은 가축 떼를 가졌더라 그들이 야셀 땅과 길르앗 땅을 본즉 그 곳은 목축할 만한 장소인지라'),
    (4726, '○모세가 갓 자손과 르우벤 자손에게 이르되 너희 형제들은 싸우러 가거늘 너희는 여기 앉아 있고자 하느냐'),
    (4736, '○그들이 모세에게 가까이 나아와 이르되 우리가 이 곳에 우리 가축을 위하여 우리를 짓고 우리 어린 아이들을 위하여 성읍을 건축하고'),
    (4740, '○모세가 그들에게 이르되 너희가 만일 이 일을 행하여 무장하고 여호와 앞에서 가서 싸우되'),
    (4748, '○이에 모세가 그들에 대하여 제사장 엘르아살과 눈의 아들 여호수아와 이스라엘 자손 지파의 수령들에게 명령하니라'),
    (4749, '모세가 그들에게 이르되 갓 자손과 르우벤 자손이 만일 각각 무장하고 너희와 함께 요단을 건너가서 여호와 앞에서 싸워서 그 땅이 너희 앞에 항복하기에 이르면 길르앗 땅을 그들의 소유로 줄 것이니라'),
    (4753, '○모세가 갓 자손과 르우벤 자손과 요셉의 아들 므낫세 반 지파에게 아모리인의 왕 시혼의 나라와 바산 왕 옥의 나라를 주되 곧 그 땅과 그 경내의 성읍들과 그 성읍들의 사방 땅을 그들에게 주매'),
    (4883, '이르되 여호와께서 우리 주에게 명령하사 이스라엘 자손에게 제비 뽑아 그 기업의 땅을 주게 하셨고 여호와께서 또 우리 주에게 명령하사 우리 형제 슬로브핫의 기업을 그의 딸들에게 주게 하셨은즉'),
    (4884, '그들이 만일 이스라엘 자손의 다른 지파들의 남자들의 아내가 되면 그들의 기업은 우리 조상의 기업에서 떨어져 나가고 그들이 속할 그 지파의 기업에 첨가되리니 그러면 우리가 제비 뽑은 기업에서 떨어져 나갈 것이요'),
    (4886, '○모세가 여호와의 말씀으로 이스라엘 자손에게 명령하여 이르되 요셉 자손 지파의 말이 옳도다'),
    (4891, '○슬로브핫의 딸들이 여호와께서 모세에게 명령하신 대로 행하니라'),
    (4894, '○이는 여리고 맞은편 요단 가 모압 평지에서 여호와께서 모세를 통하여 이스라엘 자손에게 명령하신 계명과 규례니라'),
    (4855, '너희가 이스라엘 자손의 소유에서 레위인에게 너희가 성읍을 줄 때에 많이 받은 자에게서는 많이 떼어서 주고 적게 받은 자에게서는 적게 떼어 줄 것이라 각기 받은 기업을 따라서 그 성읍들을 레위인에게 줄지니라'),
    (4856, '<도피성> ○여호와께서 또 모세에게 말씀하여 이르시되'),
    (4863, '○만일 철 연장으로 사람을 쳐죽이면 그는 살인자니 그 살인자를 반드시 죽일 것이요'),
    (4869, '○악의가 없이 우연히 사람을 밀치거나 기회를 엿봄이 없이 무엇을 던지거나'),
    (4876, '○이는 너희의 대대로 거주하는 곳에서 판결하는 규례라'),
    (4897, '마흔째 해 열한째 달 그 달 첫째 날에 모세가 이스라엘 자손에게 여호와께서 그들을 위하여 자기에게 주신 명령을 다 알렸으니'),
    (4903, '<모세가 수령을 세우다> ○그 때에 내가 너희에게 말하여 이르기를 나는 홀로 너희의 짐을 질 수 없도다'),
    (4911, '재판은 하나님께 속한 것인즉 너희는 재판할 때에 외모를 보지 말고 귀천을 차별 없이 듣고 사람의 낯을 두려워하지 말 것이며 스스로 결단하기 어려운 일이 있거든 내게로 돌리라 내가 들으리라 하였고'),
    (4913, '<정탐할 사람을 보내다> ○우리 하나님 여호와께서 우리에게 명령하신 대로 우리가 호렙 산을 떠나 너희가 보았던 그 크고 두려운 광야를 지나 아모리 족속의 산지 길로 가데스 바네아에 이른 때에'),
    (4916, '너희가 다 내 앞으로 나아와 말하기를 우리가 사람을 우리보다 먼저 보내어 우리를 위하여 그 땅을 정탐하고 어느 길로 올라가야 할 것과 어느 성읍으로 들어가야 할 것을 우리에게 알리게 하자 하기에'),
    (4922, '우리가 어디로 가랴 우리의 형제들이 우리를 낙심하게 하여 말하기를 그 백성은 우리보다 장대하며 그 성읍들은 크고 성곽은 하늘에 닿았으며 우리가 또 거기서 아낙 자손을 보았노라 하는도다 하기로'),
    (4928, '<여호와께서 이스라엘을 벌하시다> ○여호와께서 너희의 말소리를 들으시고 노하사 맹세하여 이르시되'),
    (4935, '너희가 대답하여 내게 이르기를 우리가 여호와께 범죄하였사오니 우리 하나님께서 우리에게 명령하신 대로 우리가 올라가서 싸우리이다 하고 너희가 각각 무기를 가지고 경솔히 산지로 올라가려 할 때에'),
    (4679, '<군대가 이기고 돌아오다> ○모세와 제사장 엘르아살과 회중의 지도자들이 다 진영 밖에 나가서 영접하다가'),
    (4686, '모든 의복과 가죽으로 만든 모든 것과 염소털로 만든 모든 것과 나무로 만든 모든 것을 다 깨끗하게 할지니라'),
    (4687, '○제사장 엘르아살이 싸움에 나갔던 군인들에게 이르되 이는 여호와께서 모세에게 명령하신 율법이니라'),
    (4691, '<전리품 분배> ○여호와께서 모세에게 말씀하여 이르시되'),
    (4698, '○그 탈취물 곧 군인들의 다른 탈취물 외에 양이 육십칠만 오천 마리요'),
    (4708, '○모세가 전쟁에 나갔던 자에게서 나누어 이스라엘 자손에게 준 절반'),
    (4714, '○군대의 지휘관들 곧 천부장과 백부장들이 모세에게 나아와서'),
    (4978, '<이스라엘이 바산 왕 옥을 치다> 우리가 돌이켜 바산으로 올라가매 바산 왕 옥이 그의 모든 백성을 거느리고 나와서 우리를 대적하여 에드레이에서 싸우고자 하는지라'),
    (4979, '여호와께서 내게 이르시되 그를 두려워하지 말라 내가 그와 그의 모든 백성과 그의 땅을 네 손에 넘겼으니 네가 헤스본에 거주하던 아모리 족속의 왕 시혼에게 행한 것과 같이 그에게도 행할 것이니라 하시고'),
    (4988, '(르바임 족속의 남은 자는 바산 왕 옥뿐이었으며 그의 침상은 철 침상이라 아직도 암몬 족속의 랍바에 있지 아니하냐 그것을 사람의 보통 규빗으로 재면 그 길이가 아홉 규빗이요 너비가 네 규빗이니라)'),
    (4989, '<요단 강 동쪽에 자리잡은 지파들> ○그 때에 우리가 이 땅을 얻으매 아르논 골짜기 곁의 아로엘에서부터 길르앗 산지 절반과 그 성읍들을 내가 르우벤 자손과 갓 자손에게 주었고'),
    (4995, '○그 때에 내가 너희에게 명령하여 이르기를 너희의 하나님 여호와께서 이 땅을 너희에게 주어 기업이 되게 하셨은즉 너희의 군인들은 무장하고 너희의 형제 이스라엘 자손의 선봉이 되어 건너가되'),
    (4997, '여호와께서 너희에게 주신 것 같이 너희의 형제에게도 안식을 주시리니 그들도 요단 저쪽에서 너희의 하나님 여호와께서 그들에게 주시는 땅을 받아 기업을 삼기에 이르거든 너희는 각기 내가 준 기업으로 돌아갈 것이니라 하고'),
    (5000, '<모세가 요단을 건너지 못하다> ○그 때에 내가 여호와께 간구하기를'),
    (4947, '네 하나님 여호와께서 네가 하는 모든 일에 네게 복을 주시고 네가 이 큰 광야에 두루 다님을 알고 네 하나님 여호와께서 이 사십 년 동안을 너와 함께 하셨으므로 네게 부족함이 없었느니라 하시기로'),
    (4956, '○모든 군인이 사망하여 백성 중에서 멸망한 후에'),
    (4966, '<이스라엘이 헤스본 왕 시혼을 치다> ○내가 그데못 광야에서 헤스본 왕 시혼에게 사자를 보내어 평화의 말로 이르기를'),
    (4970, '헤스본 왕 시혼이 우리가 통과하기를 허락하지 아니하였으니 이는 네 하나님 여호와께서 그를 네 손에 넘기시려고 그의 성품을 완강하게 하셨고 그의 마음을 완고하게 하셨음이 오늘날과 같으니라'),
    (4976, '우리 하나님 여호와께서 그 모든 땅을 우리에게 넘겨주심으로 아르논 골짜기 가장자리에 있는 아로엘과 골짜기 가운데에 있는 성읍으로부터 길르앗까지 우리가 모든 높은 성읍을 점령하지 못한 것이 하나도 없었으나'),
    (5092, '○이스라엘아 들으라 우리 하나님 여호와는 오직 유일한 여호와이시니'),
    (5098, '<불순종에 대한 경고> ○네 하나님 여호와께서 네 조상 아브라함과 이삭과 야곱을 향하여 네게 주리라 맹세하신 땅으로 너를 들어가게 하시고 네가 건축하지 아니한 크고 아름다운 성읍을 얻게 하시며'),
    (5104, '○너희가 맛사에서 시험한 것 같이 너희의 하나님 여호와를 시험하지 말고'),
    (5106, '여호와께서 보시기에 정직하고 선량한 일을 행하라 그리하면 네가 복을 받고 그 땅에 들어가서 여호와께서 모든 대적을 네 앞에서 쫓아내시겠다고 네 조상들에게 맹세하신 아름다운 땅을 차지하리니 여호와의 말씀과 같으니라'),
    (5107, '○후일에 네 아들이 네게 묻기를 우리 하나님 여호와께서 명령하신 증거와 규례와 법도가 무슨 뜻이냐 하거든'),
    (5111, '여호와께서 우리에게 이 모든 규례를 지키라 명령하셨으니 이는 우리가 우리 하나님 여호와를 경외하여 항상 복을 누리게 하기 위하심이며 또 여호와께서 우리를 오늘과 같이 살게 하려 하심이라'),
    (5113, '<여호와께서 택하신 민족> 네 하나님 여호와께서 너를 인도하사 네가 가서 차지할 땅으로 들이시고 네 앞에서 여러 민족 헷 족속과 기르가스 족속과 아모리 족속과 가나안 족속과 브리스 족속과 히위 족속과 여부스 족속 곧 너보다 많고 힘이 센 일곱 족속을 쫓아내실 때에'),
    (5120, '여호와께서 다만 너희를 사랑하심으로 말미암아, 또는 너희의 조상들에게 하신 맹세를 지키려 하심으로 말미암아 자기의 권능의 손으로 너희를 인도하여 내시되 너희를 그 종 되었던 집에서 애굽 왕 바로의 손에서 속량하셨나니'),
    (5124, '<법도를 듣고 지켜 행하면> ○너희가 이 모든 법도를 듣고 지켜 행하면 네 하나님 여호와께서 네 조상들에게 맹세하신 언약을 지켜 네게 인애를 베푸실 것이라'),
    (5125, '곧 너를 사랑하시고 복을 주사 너를 번성하게 하시되 네게 주리라고 네 조상들에게 맹세하신 땅에서 네 소생에게 은혜를 베푸시며 네 토지 소산과 곡식과 포도주와 기름을 풍성하게 하시고 네 소와 양을 번식하게 하시리니'),
    (5129, '○네가 혹시 심중에 이르기를 이 민족들이 나보다 많으니 내가 어찌 그를 쫓아낼 수 있으리요 하리라마는'),
    (5137, '너는 그들이 조각한 신상들을 불사르고 그것에 입힌 은이나 금을 탐내지 말며 취하지 말라 네가 그것으로 말미암아 올무에 걸릴까 하노니 이는 네 하나님 여호와께서 가증히 여기시는 것임이니라'),
    (5056, '<십계명> 모세가 온 이스라엘을 불러 그들에게 이르되 이스라엘아 오늘 내가 너희의 귀에 말하는 규례와 법도를 듣고 그것을 배우며 지켜 행하라'),
    (5062, '○나 외에는 다른 신들을 네게 두지 말지니라'),
    (5063, '○너는 자기를 위하여 새긴 우상을 만들지 말고 위로 하늘에 있는 것이나 아래로 땅에 있는 것이나 땅밑 물 속에 있는 것의 어떤 형상도 만들지 말며'),
    (5066, '○너는 네 하나님 여호와의 이름을 망령되이 일컫지 말라 나 여호와는 내 이름을 망령되이 일컫는 자를 죄 없는 줄로 인정하지 아니하리라'),
    (5067, '○네 하나님 여호와가 네게 명령한 대로 안식일을 지켜 거룩하게 하라'),
    (5069, '일곱째 날은 네 하나님 여호와의 안식일인즉 너나 네 아들이나 네 딸이나 네 남종이나 네 여종이나 네 소나 네 나귀나 네 모든 가축이나 네 문 안에 유하는 객이라도 아무 일도 하지 못하게 하고 네 남종이나 네 여종에게 너 같이 안식하게 할지니라'),
    (5071, '○너는 네 하나님 여호와께서 명령한 대로 네 부모를 공경하라 그리하면 네 하나님 여호와가 네게 준 땅에서 네 생명이 길고 복을 누리리라'),
    (5072, '○살인하지 말지니라'),
    (5073, '○간음하지 말지니라'),
    (5074, '○도둑질 하지 말지니라'),
    (5075, '○네 이웃에 대하여 거짓 증거하지 말지니라'),
    (5076, '○네 이웃의 아내를 탐내지 말지니라 네 이웃의 집이나 그의 밭이나 그의 남종이나 그의 여종이나 그의 소나 그의 나귀나 네 이웃의 모든 소유를 탐내지 말지니라'),
    (5077, '<여호와의 음성 듣기를 두려워하다> ○여호와께서 이 모든 말씀을 산 위 불 가운데, 구름 가운데, 흑암 가운데에서 큰 음성으로 너희 총회에 이르신 후에 더 말씀하지 아니하시고 그것을 두 돌판에 써서 내게 주셨느니라'),
    (5079, '말하되 우리 하나님 여호와께서 그의 영광과 위엄을 우리에게 보이시매 불 가운데에서 나오는 음성을 우리가 들었고 하나님이 사람과 말씀하시되 그 사람이 생존하는 것을 오늘 우리가 보았나이다'),
    (5083, '○여호와께서 너희가 내게 말할 때에 너희가 말하는 소리를 들으신지라 여호와께서 내게 이르시되 이 백성이 네게 말하는 그 말소리를 내가 들은즉 그 말이 다 옳도다'),
    (5139, '<이스라엘이 차지할 아름다운 땅> 내가 오늘 명하는 모든 명령을 너희는 지켜 행하라 그리하면 너희가 살고 번성하고 여호와께서 너희의 조상들에게 맹세하신 땅에 들어가서 그것을 차지하리라'),
    (5141, '너를 낮추시며 너를 주리게 하시며 또 너도 알지 못하며 네 조상들도 알지 못하던 만나를 네게 먹이신 것은 사람이 떡으로만 사는 것이 아니요 여호와의 입에서 나오는 모든 말씀으로 사는 줄을 네가 알게 하려 하심이니라'),
    (5149, '<여호와를 잊지 말라> ○내가 오늘 네게 명하는 여호와의 명령과 법도와 규례를 지키지 아니하고 네 하나님 여호와를 잊어버리지 않도록 삼갈지어다'),
    (5007, '<지켜야 할 하나님의 규례들> 이스라엘아 이제 내가 너희에게 가르치는 규례와 법도를 듣고 준행하라 그리하면 너희가 살 것이요 너희 조상의 하나님 여호와께서 너희에게 주시는 땅에 들어가서 그것을 얻게 되리라'),
    (5015, '○오직 너는 스스로 삼가며 네 마음을 힘써 지키라 그리하여 네가 눈으로 본 그 일을 잊어버리지 말라 네가 생존하는 날 동안에 그 일들이 네 마음에서 떠나지 않도록 조심하라 너는 그 일들을 네 아들들과 네 손자들에게 알게 하라'),
    (5016, '네가 호렙 산에서 네 하나님 여호와 앞에 섰던 날에 여호와께서 내게 이르시기를 나에게 백성을 모으라 내가 그들에게 내 말을 들려주어 그들이 세상에 사는 날 동안 나를 경외함을 배우게 하며 그 자녀에게 가르치게 하리라 하시매'),
    (5021, '<우상을 만들어 섬기지 말라> ○여호와께서 호렙 산 불길 중에서 너희에게 말씀하시던 날에 너희가 어떤 형상도 보지 못하였은즉 너희는 깊이 삼가라'),
    (5031, '○네가 그 땅에서 아들을 낳고 손자를 얻으며 오래 살 때에 만일 스스로 부패하여 무슨 형상의 우상이든지 조각하여 네 하나님 여호와 앞에 악을 행함으로 그의 노를 일으키면'),
    (5038, '○네가 있기 전 하나님이 사람을 세상에 창조하신 날부터 지금까지 지나간 날을 상고하여 보라 하늘 이 끝에서 저 끝까지 이런 큰 일이 있었느냐 이런 일을 들은 적이 있었느냐'),
    (5040, '어떤 신이 와서 시험과 이적과 기사와 전쟁과 강한 손과 편 팔과 크게 두려운 일로 한 민족을 다른 민족에게서 인도하여 낸 일이 있느냐 이는 다 너희의 하나님 여호와께서 애굽에서 너희를 위하여 너희의 목전에서 행하신 일이라'),
    (5047, '<요단 강 동쪽의 도피성> ○그 때에 모세가 요단 이쪽 해 돋는 쪽에서 세 성읍을 구별하였으니'),
    (5050, '<모세가 선포한 율법> ○모세가 이스라엘 자손에게 선포한 율법은 이러하니라'),
    (5161, '오늘 너는 알라 네 하나님 여호와께서 맹렬한 불과 같이 네 앞에 나아가신즉 여호와께서 그들을 멸하사 네 앞에 엎드러지게 하시리니 여호와께서 네게 말씀하신 것 같이 너는 그들을 쫓아내며 속히 멸할 것이라'),
    (5162, '네 하나님 여호와께서 그들을 네 앞에서 쫓아내신 후에 네가 심중에 이르기를 내 공의로움으로 말미암아 여호와께서 나를 이 땅으로 인도하여 들여서 그것을 차지하게 하셨다 하지 말라 이 민족들이 악함으로 말미암아 여호와께서 그들을 네 앞에서 쫓아내심이니라'),
    (5163, '네가 가서 그 땅을 차지함은 네 공의로 말미암음도 아니며 네 마음이 정직함으로 말미암음도 아니요 이 민족들이 악함으로 말미암아 네 하나님 여호와께서 그들을 네 앞에서 쫓아내심이라 여호와께서 이같이 하심은 네 조상 아브라함과 이삭과 야곱에게 하신 맹세를 이루려 하심이니라'),
    (5164, '○그러므로 네가 알 것은 네 하나님 여호와께서 네게 이 아름다운 땅을 기업으로 주신 것이 네 공의로 말미암음이 아니니라 너는 목이 곧은 백성이니라'),
    (5176, '그리고 내가 전과 같이 사십 주 사십 야를 여호와 앞에 엎드려서 떡도 먹지 아니하고 물도 마시지 아니하였으니 이는 너희가 여호와의 목전에 악을 행하여 그를 격노하게 하여 크게 죄를 지었음이라'),
    (5180, '○너희가 다베라와 맛사와 기브롯 핫다아와에서도 여호와를 격노하게 하였느니라'),
    (5181, '여호와께서 너희를 가데스 바네아에서 떠나게 하실 때에 이르시기를 너희는 올라가서 내가 너희에게 준 땅을 차지하라 하시되 너희가 너희의 하나님 여호와의 명령을 거역하여 믿지 아니하고 그 말씀을 듣지 아니하였나니'),
    (5183, '○그 때에 여호와께서 너희를 멸하겠다 하셨으므로 내가 여전히 사십 주 사십 야를 여호와 앞에 엎드리고'),
    (5186, '주께서 우리를 인도하여 내신 그 땅 백성이 말하기를 여호와께서 그들에게 허락하신 땅으로 그들을 인도하여 들일 만한 능력도 없고 그들을 미워하기도 하사 광야에서 죽이려고 인도하여 내셨다 할까 두려워하나이다'),
    (5188, '<모세가 십계명을 다시 받다> 그 때에 여호와께서 내게 이르시기를 너는 처음과 같은 두 돌판을 다듬어 가지고 산에 올라 내게로 나아오고 또 나무궤 하나를 만들라'),
    (5199, '<여호와께서 요구하시는 것> ○이스라엘아 네 하나님 여호와께서 네게 요구하시는 것이 무엇이냐 곧 네 하나님 여호와를 경외하여 그의 모든 도를 행하고 그를 사랑하며 마음을 다하고 뜻을 다하여 네 하나님 여호와를 섬기고'),
    (5276, '너는 그 선지자나 꿈 꾸는 자의 말을 청종하지 말라 이는 너희의 하나님 여호와께서 너희가 마음을 다하고 뜻을 다하여 너희의 하나님 여호와를 사랑하는 여부를 알려 하사 너희를 시험하심이니라'),
    (5278, '그런 선지자나 꿈 꾸는 자는 죽이라 이는 그가 너희에게 너희를 애굽 땅에서 인도하여 내시며 종 되었던 집에서 속량하신 너희의 하나님 여호와를 배반하게 하려 하며 너희의 하나님 여호와께서 네게 행하라 명령하신 도에서 너를 꾀어내려고 말하였음이라 너는 이같이 하여 너희 중에서 악을 제할지니라'),
    (5279, '○네 어머니의 아들 곧 네 형제나 네 자녀나 네 품의 아내나 너와 생명을 함께 하는 친구가 가만히 너를 꾀어 이르기를 너와 네 조상들이 알지 못하던 다른 신들'),
    (5285, '○네 하나님 여호와께서 네게 주어 거주하게 하시는 한 성읍에 대하여 네게 소문이 들리기를'),
    (5217, '<주리라고 맹세하신 땅> ○그러므로 너희는 내가 오늘 너희에게 명하는 모든 명령을 지키라 그리하면 너희가 강성할 것이요 너희가 건너가 차지할 땅에 들어가서 그것을 차지할 것이며'),
    (5222, '○내가 오늘 너희에게 명하는 내 명령을 너희가 만일 청종하고 너희의 하나님 여호와를 사랑하여 마음을 다하고 뜻을 다하여 섬기면'),
    (5227, '○이러므로 너희는 나의 이 말을 너희의 마음과 뜻에 두고 또 그것을 너희의 손목에 매어 기호를 삼고 너희 미간에 붙여 표를 삼으며'),
    (5235, '○내가 오늘 복과 저주를 너희 앞에 두나니'),
    (5294, '<정한 짐승과 부정한 짐승> ○너는 가증한 것은 무엇이든지 먹지 말라'),
    (5300, '○물에 있는 모든 것 중에서 이런 것은 너희가 먹을 것이니 지느러미와 비늘 있는 모든 것은 너희가 먹을 것이요'),
    (5312, '○너희는 너희의 하나님 여호와의 성민이라 스스로 죽은 모든 것은 먹지 말 것이나 그것을 성중에 거류하는 객에게 주어 먹게 하거나 이방인에게 파는 것은 가하니라 너는 염소 새끼를 그 어미의 젖에 삶지 말지니라'),
    (5313, '<십일조 규례> ○너는 마땅히 매 년 토지 소산의 십일조를 드릴 것이며'),
    (5314, '네 하나님 여호와 앞 곧 여호와께서 그의 이름을 두시려고 택하신 곳에서 네 곡식과 포도주와 기름의 십일조를 먹으며 또 네 소와 양의 처음 난 것을 먹고 네 하나님 여호와 경외하기를 항상 배울 것이니라'),
    (5319, '○매 삼 년 끝에 그 해 소산의 십분의 일을 다 내어 네 성읍에 저축하여'),
    (5251, '너희가 요단을 건너 너희 하나님 여호와께서 너희에게 기업으로 주시는 땅에 거주하게 될 때 또는 여호와께서 너희에게 너희 주위의 모든 대적을 이기게 하시고 너희에게 안식을 주사 너희를 평안히 거주하게 하실 때에'),
    (5252, '너희는 너희의 하나님 여호와께서 자기 이름을 두시려고 택하실 그 곳으로 내가 명령하는 것을 모두 가지고 갈지니 곧 너희의 번제와 너희의 희생과 너희의 십일조와 너희 손의 거제와 너희가 여호와께 서원하는 모든 아름다운 서원물을 가져가고'),
    (5256, '○그러나 네 하나님 여호와께서 네게 주신 복을 따라 각 성에서 네 마음에 원하는 대로 가축을 잡아 그 고기를 먹을 수 있나니 곧 정한 자나 부정한 자를 막론하고 노루나 사슴을 먹는 것 같이 먹으려니와'),
    (5259, '오직 네 하나님 여호와께서 택하실 곳에서 네 하나님 여호와 앞에서 너는 네 자녀와 노비와 성중에 거주하는 레위인과 함께 그것을 먹고 또 네 손으로 수고한 모든 일로 말미암아 네 하나님 여호와 앞에서 즐거워하되'),
    (5261, '○네 하나님 여호와께서 네게 허락하신 대로 네 지경을 넓히신 후에 네 마음에 고기를 먹고자 하여 이르기를 내가 고기를 먹으리라 하면 네가 언제나 마음에 원하는 만큼 고기를 먹을 수 있으리니'),
    (5270, '<다른 신들을 섬기지 말라> ○네 하나님 여호와께서 네가 들어가서 쫓아낼 그 민족들을 네 앞에서 멸절하시고 네가 그 땅을 차지하여 거기에 거주하게 하실 때에'),
    (5272, '네 하나님 여호와께는 네가 그와 같이 행하지 못할 것이라 그들은 여호와께서 꺼리시며 가증히 여기시는 일을 그들의 신들에게 행하여 심지어 자기들의 자녀를 불살라 그들의 신들에게 드렸느니라'),
    (5273, '○내가 너희에게 명령하는 이 모든 말을 너희는 지켜 행하고 그것에 가감하지 말지니라'),
    (5343, '<유월절> 아빕월을 지켜 네 하나님 여호와께 유월절을 행하라 이는 아빕월에 네 하나님 여호와께서 밤에 너를 애굽에서 인도하여 내셨음이라'),
    (5345, '유교병을 그것과 함께 먹지 말고 이레 동안은 무교병 곧 고난의 떡을 그것과 함께 먹으라 이는 네가 애굽 땅에서 급히 나왔음이니 이같이 행하여 네 평생에 항상 네가 애굽 땅에서 나온 날을 기억할 것이니라'),
    (5350, '너는 엿새 동안은 무교병을 먹고 일곱째 날에 네 하나님 여호와 앞에 성회로 모이고 일하지 말지니라'),
    (5351, '<칠칠절> ○일곱 주를 셀지니 곡식에 낫을 대는 첫 날부터 일곱 주를 세어'),
    (5353, '너와 네 자녀와 노비와 네 성중에 있는 레위인과 및 너희 중에 있는 객과 고아와 과부가 함께 네 하나님 여호와께서 자기의 이름을 두시려고 택하신 곳에서 네 하나님 여호와 앞에서 즐거워할지니라'),
    (5355, '<초막절> ○너희 타작 마당과 포도주 틀의 소출을 거두어 들인 후에 이레 동안 초막절을 지킬 것이요'),
    (5357, '네 하나님 여호와께서 택하신 곳에서 너는 이레 동안 네 하나님 여호와 앞에서 절기를 지키고 네 하나님 여호와께서 네 모든 소출과 네 손으로 행한 모든 일에 복 주실 것이니 너는 온전히 즐거워할지니라'),
    (5360, '<공의로 재판하라> ○네 하나님 여호와께서 네게 주시는 각 성에서 네 지파를 따라 재판장들과 지도자들을 둘 것이요 그들은 공의로 백성을 재판할 것이니라'),
    (5363, '○네 하나님 여호와를 위하여 쌓은 제단 곁에 어떤 나무로든지 아세라 상을 세우지 말며'),
    (5321, '<빚을 면제해 주는 해> 매 칠 년 끝에는 면제하라'),
    (5324, '네가 만일 네 하나님 여호와의 말씀만 듣고 내가 오늘 네게 내리는 그 명령을 다 지켜 행하면'),
    (5326, '○네 하나님 여호와께서 네게 주신 땅 어느 성읍에서든지 가난한 형제가 너와 함께 거주하거든 그 가난한 형제에게 네 마음을 완악하게 하지 말며 네 손을 움켜 쥐지 말고'),
    (5328, '삼가 너는 마음에 악한 생각을 품지 말라 곧 이르기를 일곱째 해 면제년이 가까이 왔다 하고 네 궁핍한 형제를 악한 눈으로 바라보며 아무것도 주지 아니하면 그가 너를 여호와께 호소하리니 그것이 네게 죄가 되리라'),
    (5331, '<종을 대우하는 법> ○네 동족 히브리 남자나 히브리 여자가 네게 팔렸다 하자 만일 여섯 해 동안 너를 섬겼거든 일곱째 해에 너는 그를 놓아 자유롭게 할 것이요'),
    (5338, '<처음 난 소와 양의 새끼> ○네 소와 양의 처음 난 수컷은 구별하여 네 하나님 여호와께 드릴 것이니 네 소의 첫 새끼는 부리지 말고 네 양의 첫 새끼의 털은 깎지 말고'),
    (5390, '○이스라엘 온 땅 어떤 성읍에든지 거주하는 레위인이 간절한 소원이 있어 그가 사는 곳을 떠날지라도 여호와께서 택하신 곳에 이르면'),
    (5393, '<다른 민족들의 가증한 행위> ○네 하나님 여호와께서 네게 주시는 땅에 들어가거든 너는 그 민족들의 가증한 행위를 본받지 말 것이니'),
    (5399, '<선지자를 일으키실 약속> ○네 하나님 여호와께서 너희 가운데 네 형제 중에서 너를 위하여 나와 같은 선지자 하나를 일으키시리니 너희는 그의 말을 들을지니라'),
    (5400, '이것이 곧 네가 총회의 날에 호렙 산에서 네 하나님 여호와께 구한 것이라 곧 네가 말하기를 내가 다시는 내 하나님 여호와의 음성을 듣지 않게 하시고 다시는 이 큰 불을 보지 않게 하소서 두렵건대 내가 죽을까 하나이다 하매'),
    (5366, '○네 하나님 여호와께서 네게 주시는 어느 성중에서든지 너희 가운데에 어떤 남자나 여자가 네 하나님 여호와의 목전에 악을 행하여 그 언약을 어기고'),
    (5372, '○네 성중에서 서로 피를 흘렸거나 다투었거나 구타하였거나 서로 간에 고소하여 네가 판결하기 어려운 일이 생기거든 너는 일어나 네 하나님 여호와께서 택하실 곳으로 올라가서'),
    (5378, '<이스라엘의 왕> ○네가 네 하나님 여호와께서 네게 주시는 땅에 이르러 그 땅을 차지하고 거주할 때에 만일 우리도 우리 주위의 모든 민족들 같이 우리 위에 왕을 세워야겠다는 생각이 나거든'),
    (5380, '그는 병마를 많이 두지 말 것이요 병마를 많이 얻으려고 그 백성을 애굽으로 돌아가게 하지 말 것이니 이는 여호와께서 너희에게 이르시기를 너희가 이 후에는 그 길로 다시 돌아가지 말 것이라 하셨음이며'),
    (5382, '○그가 왕위에 오르거든 이 율법서의 등사본을 레위 사람 제사장 앞에서 책에 기록하여'),
    (5407, '<도피성> 네 하나님 여호와께서 이 여러 민족을 멸절하시고 네 하나님 여호와께서 그 땅을 네게 주시므로 네가 그것을 받고 그들의 성읍과 가옥에 거주할 때에'),
    (5411, '가령 사람이 그 이웃과 함께 벌목하러 삼림에 들어가서 손에 도끼를 들고 벌목하려고 찍을 때에 도끼가 자루에서 빠져 그의 이웃을 맞춰 그를 죽게 함과 같은 것이라 이런 사람은 그 성읍 중 하나로 도피하여 생명을 보존할 것이니라'),
    (5412, '그 사람이 그에게 본래 원한이 없으니 죽이기에 합당하지 아니하나 두렵건대 그 피를 보복하는 자의 마음이 복수심에 불타서 살인자를 뒤쫓는데 그 가는 길이 멀면 그를 따라 잡아 죽일까 하노라'),
    (5417, '○그러나 만일 어떤 사람이 그의 이웃을 미워하여 엎드려 그를 기다리다가 일어나 상처를 입혀 죽게 하고 이 한 성읍으로 도피하면'),
    (5420, '<이웃의 경계표를 옮기지 말라> ○네 하나님 여호와께서 네게 주어 차지하게 하시는 땅 곧 네 소유가 된 기업의 땅에서 조상이 정한 네 이웃의 경계표를 옮기지 말지니라'),
    (5421, '<두 세 증인의 입으로 하라> ○사람의 모든 악에 관하여 또한 모든 죄에 관하여는 한 증인으로만 정할 것이 아니요 두 증인의 입으로나 또는 세 증인의 입으로 그 사건을 확정할 것이며'),
    (5428, '<적군과 싸우려 할 때에> 네가 나가서 적군과 싸우려 할 때에 말과 병거와 백성이 너보다 많음을 볼지라도 그들을 두려워하지 말라 애굽 땅에서 너를 인도하여 내신 네 하나님 여호와께서 너와 함께 하시느니라'),
    (5437, '○네가 어떤 성읍으로 나아가서 치려 할 때에는 그 성읍에 먼저 화평을 선언하라'),
    (5446, '○너희가 어떤 성읍을 오랫동안 에워싸고 그 성읍을 쳐서 점령하려 할 때에도 도끼를 둘러 그 곳의 나무를 찍어내지 말라 이는 너희가 먹을 것이 될 것임이니 찍지 말라 들의 수목이 사람이냐 너희가 어찌 그것을 에워싸겠느냐'),
    (5452, '레위 자손 제사장들도 그리로 갈지니 그들은 네 하나님 여호와께서 택하사 자기를 섬기게 하시며 또 여호와의 이름으로 축복하게 하신 자라 모든 소송과 모든 투쟁이 그들의 말대로 판결될 것이니라'),
    (5457, '<여자 포로를 아내로 삼는 규정> ○네가 나가서 적군과 싸울 때에 네 하나님 여호와께서 그들을 네 손에 넘기시므로 네가 그들을 사로잡은 후에'),
    (5462, '<장자의 상속권> ○어떤 사람이 두 아내를 두었는데 하나는 사랑을 받고 하나는 미움을 받다가 그 사랑을 받는 자와 미움을 받는 자가 둘 다 아들을 낳았다 하자 그 미움을 받는 자의 아들이 장자이면'),
    (5465, '<패역한 아들에게 내리는 벌> ○사람에게 완악하고 패역한 아들이 있어 그의 아버지의 말이나 그 어머니의 말을 순종하지 아니하고 부모가 징계하여도 순종하지 아니하거든'),
    (5469, '<기타 규정> ○사람이 만일 죽을 죄를 범하므로 네가 그를 죽여 나무 위에 달거든'),
    (5502, '○사생자는 여호와의 총회에 들어오지 못하리니 십 대에 이르기까지도 여호와의 총회에 들어오지 못하리라'),
    (5503, '○암몬 사람과 모압 사람은 여호와의 총회에 들어오지 못하리니 그들에게 속한 자는 십 대뿐 아니라 영원히 여호와의 총회에 들어오지 못하리라'),
    (5507, '○너는 에돔 사람을 미워하지 말라 그는 네 형제임이니라 애굽 사람을 미워하지 말라 네가 그의 땅에서 객이 되었음이니라'),
    (5509, '<진영을 거룩하게 하는 법> ○네가 적군을 치러 출진할 때에 모든 악한 일을 스스로 삼갈지니'),
    (5514, '이는 네 하나님 여호와께서 너를 구원하시고 적군을 네게 넘기시려고 네 진영 중에 행하심이라 그러므로 네 진영을 거룩히 하라 그리하면 네게서 불결한 것을 보시지 않으므로 너를 떠나지 아니하시리라'),
    (5515, '<기타 규정> ○종이 그의 주인을 피하여 네게로 도망하거든 너는 그의 주인에게 돌려주지 말고'),
    (5517, '○이스라엘 여자 중에 창기가 있지 못할 것이요 이스라엘 남자 중에 남창이 있지 못할지니'),
    (5519, '○네가 형제에게 꾸어주거든 이자를 받지 말지니 곧 돈의 이자, 식물의 이자, 이자를 낼 만한 모든 것의 이자를 받지 말 것이라'),
    (5520, '타국인에게 네가 꾸어주면 이자를 받아도 되거니와 네 형제에게 꾸어주거든 이자를 받지 말라 그리하면 네 하나님 여호와께서 네가 들어가서 차지할 땅에서 네 손으로 하는 범사에 복을 내리시리라'),
    (5521, '○네 하나님 여호와께 서원하거든 갚기를 더디하지 말라 네 하나님 여호와께서 반드시 그것을 네게 요구하시리니 더디면 그것이 네게 죄가 될 것이라'),
    (5524, '○네 이웃의 포도원에 들어갈 때에는 마음대로 그 포도를 배불리 먹어도 되느니라 그러나 그릇에 담지는 말 것이요'),
    (5475, '○여자는 남자의 의복을 입지 말 것이요 남자는 여자의 의복을 입지 말 것이라 이같이 하는 자는 네 하나님 여호와께 가증한 자이니라'),
    (5476, '○길을 가다가 나무에나 땅에 있는 새의 보금자리에 새 새끼나 알이 있고 어미 새가 그의 새끼나 알을 품은 것을 보거든 그 어미 새와 새끼를 아울러 취하지 말고'),
    (5478, '○네가 새 집을 지을 때에 지붕에 난간을 만들어 사람이 떨어지지 않게 하라 그 피가 네 집에 돌아갈까 하노라'),
    (5479, '○네 포도원에 두 종자를 섞어 뿌리지 말라 그리하면 네가 뿌린 씨의 열매와 포도원의 소산을 다 빼앗길까 하노라'),
    (5482, '○너희는 너희가 입는 겉옷의 네 귀에 술을 만들지니라'),
    (5483, '<순결에 관한 법> ○누구든지 아내를 맞이하여 그에게 들어간 후에 그를 미워하여'),
    (5491, '그 처녀를 그의 아버지 집 문에서 끌어내고 그 성읍 사람들이 그를 돌로 쳐죽일지니 이는 그가 그의 아버지 집에서 창기의 행동을 하여 이스라엘 중에서 악을 행하였음이라 너는 이와 같이 하여 너희 가운데서 악을 제할지니라'),
    (5492, '○어떤 남자가 유부녀와 동침한 것이 드러나거든 그 동침한 남자와 그 여자를 둘 다 죽여 이스라엘 중에 악을 제할지니라'),
    (5493, '○처녀인 여자가 남자와 약혼한 후에 어떤 남자가 그를 성읍 중에서 만나 동침하면'),
    (5494, '너희는 그들을 둘 다 성읍 문으로 끌어내고 그들을 돌로 쳐죽일 것이니 그 처녀는 성안에 있으면서도 소리 지르지 아니하였음이요 그 남자는 그 이웃의 아내를 욕보였음이라 너는 이같이 하여 너희 가운데에서 악을 제할지니라'),
    (5495, '○만일 남자가 어떤 약혼한 처녀를 들에서 만나서 강간하였으면 그 강간한 남자만 죽일 것이요'),
    (5498, '○만일 남자가 약혼하지 아니한 처녀를 만나 그를 붙들고 동침하는 중에 그 두 사람이 발견되면'),
    (5500, '○사람이 그의 아버지의 아내를 취하여 아버지의 하체를 드러내지 말지니라'),
    (5529, '그 여자는 이미 몸을 더럽혔은즉 그를 내보낸 전남편이 그를 다시 아내로 맞이하지 말지니 이 일은 여호와 앞에 가증한 것이라 너는 네 하나님 여호와께서 네게 기업으로 주시는 땅을 범죄하게 하지 말지니라'),
    (5530, '<기타 규정> ○사람이 새로이 아내를 맞이하였으면 그를 군대로 내보내지 말 것이요 아무 직무도 그에게 맡기지 말 것이며 그는 일 년 동안 한가하게 집에 있으면서 그가 맞이한 아내를 즐겁게 할지니라'),
    (5531, '○사람이 맷돌이나 그 위짝을 전당 잡지 말지니 이는 그 생명을 전당 잡음이니라'),
    (5532, '○사람이 자기 형제 곧 이스라엘 자손 중 한 사람을 유인하여 종으로 삼거나 판 것이 발견되면 그 유인한 자를 죽일지니 이같이 하여 너희 중에서 악을 제할지니라'),
    (5533, '○너는 나병에 대하여 삼가서 레위 사람 제사장들이 너희에게 가르치는 대로 네가 힘써 다 지켜 행하되 너희는 내가 그들에게 명령한 대로 지켜 행하라'),
    (5535, '○네 이웃에게 무엇을 꾸어줄 때에 너는 그의 집에 들어가서 전당물을 취하지 말고'),
    (5539, '○곤궁하고 빈한한 품꾼은 너희 형제든지 네 땅 성문 안에 우거하는 객이든지 그를 학대하지 말며'),
    (5541, '○아버지는 그 자식들로 말미암아 죽임을 당하지 않을 것이요 자식들은 그 아버지로 말미암아 죽임을 당하지 않을 것이니 각 사람은 자기 죄로 말미암아 죽임을 당할 것이니라'),
    (5542, '○너는 객이나 고아의 송사를 억울하게 하지 말며 과부의 옷을 전당 잡지 말라'),
    (5544, '○네가 밭에서 곡식을 벨 때에 그 한 뭇을 밭에 잊어버렸거든 다시 가서 가져오지 말고 나그네와 고아와 과부를 위하여 남겨두라 그리하면 네 하나님 여호와께서 네 손으로 하는 모든 일에 복을 내리시리라'),
    (5551, '○곡식 떠는 소에게 망을 씌우지 말지니라'),
    (5552, '<죽은 형제에 대한 의무> ○형제들이 함께 사는데 그 중 하나가 죽고 아들이 없거든 그 죽은 자의 아내는 나가서 타인에게 시집 가지 말 것이요 그의 남편의 형제가 그에게로 들어가서 그를 맞이하여 아내로 삼아 그의 남편의 형제 된 의무를 그에게 다 행할 것이요'),
    (5554, '그러나 그 사람이 만일 그 형제의 아내 맞이하기를 즐겨하지 아니하면 그 형제의 아내는 그 성문으로 장로들에게로 나아가서 말하기를 내 남편의 형제가 그의 형제의 이름을 이스라엘 중에 잇기를 싫어하여 남편의 형제 된 의무를 내게 행하지 아니하나이다 할 것이요'),
    (5558, '<다른 법> ○두 사람이 서로 싸울 때에 한 사람의 아내가 그 치는 자의 손에서 그의 남편을 구하려 하여 가까이 가서 손을 벌려 그 사람의 음낭을 잡거든'),
    (5560, '○너는 네 주머니에 두 종류의 저울추 곧 큰 것과 작은 것을 넣지 말 것이며'),
    (5564, '<아말렉에 대한 기억을 지워버리라> ○너희는 애굽에서 나오는 길에 아말렉이 네게 행한 일을 기억하라'),
    (5566, '그러므로 네 하나님 여호와께서 네게 기업으로 주어 차지하게 하시는 땅에서 네 하나님 여호와께서 사방에 있는 모든 적군으로부터 네게 안식을 주실 때에 너는 천하에서 아말렉에 대한 기억을 지워버리라 너는 잊지 말지니라'),
    (5588, '요단을 건넌 후에 이 율법의 모든 말씀을 그 위에 기록하라 그리하면 네 하나님 여호와께서 네게 주시는 땅 곧 젖과 꿀이 흐르는 땅에 네가 들어가기를 네 조상들의 하나님 여호와께서 네게 말씀하신 대로 하리라'),
    (5594, '○모세와 레위 제사장들이 온 이스라엘에게 말하여 이르되 이스라엘아 잠잠하여 들으라 오늘 네가 네 하나님 여호와의 백성이 되었으니'),
    (5596, '<에발 산에서 선포한 저주> ○모세가 그 날 백성에게 명령하여 이르되'),
    (5601, '○그의 부모를 경홀히 여기는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5602, '○그의 이웃의 경계표를 옮기는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5603, '○맹인에게 길을 잃게 하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5604, '○객이나 고아나 과부의 송사를 억울하게 하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5605, '○그의 아버지의 아내와 동침하는 자는 그의 아버지의 하체를 드러냈으니 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5606, '○짐승과 교합하는 모든 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5607, '○그의 자매 곧 그의 아버지의 딸이나 어머니의 딸과 동침하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5608, '○장모와 동침하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5609, '○그의 이웃을 암살하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5610, '○무죄한 자를 죽이려고 뇌물을 받는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5611, '○이 율법의 말씀을 실행하지 아니하는 자는 저주를 받을 것이라 할 것이요 모든 백성은 아멘 할지니라'),
    (5568, '네 하나님 여호와께서 네게 주신 땅에서 그 토지의 모든 소산의 맏물을 거둔 후에 그것을 가져다가 광주리에 담고 네 하나님 여호와께서 그의 이름을 두시려고 택하신 곳으로 그것을 가지고 가서'),
    (5578, '○셋째 해 곧 십일조를 드리는 해에 네 모든 소산의 십일조 내기를 마친 후에 그것을 레위인과 객과 고아와 과부에게 주어 네 성읍 안에서 먹고 배부르게 하라'),
    (5579, '그리 할 때에 네 하나님 여호와 앞에 아뢰기를 내가 성물을 내 집에서 내어 레위인과 객과 고아와 과부에게 주기를 주께서 내게 명령하신 명령대로 하였사오니 내가 주의 명령을 범하지도 아니하였고 잊지도 아니하였나이다'),
    (5580, '내가 애곡하는 날에 이 성물을 먹지 아니하였고 부정한 몸으로 이를 떼어두지 아니하였고 죽은 자를 위하여 이를 쓰지 아니하였고 내 하나님 여호와의 말씀을 청종하여 주께서 내게 명령하신 대로 다 행하였사오니'),
    (5582, '<하나님의 보배로운 백성> ○오늘 네 하나님 여호와께서 이 규례와 법도를 행하라고 네게 명령하시나니 그런즉 너는 마음을 다하고 뜻을 다하여 지켜 행하라'),
    (5583, '네가 오늘 여호와를 네 하나님으로 인정하고 또 그 도를 행하고 그의 규례와 명령과 법도를 지키며 그의 소리를 들으리라 확언하였고'),
    (5681, '○모세가 온 이스라엘을 소집하고 그들에게 이르되 여호와께서 애굽 땅에서 너희의 목전에 바로와 그의 모든 신하와 그의 온 땅에 행하신 모든 일을 너희가 보았나니'),
    (5683, '그러나 깨닫는 마음과 보는 눈과 듣는 귀는 오늘까지 여호와께서 너희에게 주지 아니하셨느니라'),
    (5684, '주께서 사십 년 동안 너희를 광야에서 인도하셨거니와 너희 몸의 옷이 낡아지지 아니하였고 너희 발의 신이 해어지지 아니하였으며'),
    (5689, '○오늘 너희 곧 너희의 수령과 너희의 지파와 너희의 장로들과 너희의 지도자와 이스라엘 모든 남자와'),
    (5693, '○내가 이 언약과 맹세를 너희에게만 세우는 것이 아니라'),
    (5699, '여호와는 이런 자를 사하지 않으실 뿐 아니라 그 위에 여호와의 분노와 질투의 불을 부으시며 또 이 책에 기록된 모든 저주를 그에게 더하실 것이라 여호와께서 그의 이름을 천하에서 지워버리시되'),
    (5701, '○너희 뒤에 일어나는 너희의 자손과 멀리서 오는 객이 그 땅의 재앙과 여호와께서 그 땅에 유행시키시는 질병을 보며'),
    (5702, '그 온 땅이 유황이 되며 소금이 되며 또 불에 타서 심지도 못하며 결실함도 없으며 거기에는 아무 풀도 나지 아니함이 옛적에 여호와께서 진노와 격분으로 멸하신 소돔과 고모라와 아드마와 스보임의 무너짐과 같음을 보고 물을 것이요'),
    (5612, '<순종하여 받는 복> 네가 네 하나님 여호와의 말씀을 삼가 듣고 내가 오늘 네게 명령하는 그의 모든 명령을 지켜 행하면 네 하나님 여호와께서 너를 세계 모든 민족 위에 뛰어나게 하실 것이라'),
    (5618, '○여호와께서 너를 대적하기 위해 일어난 적군들을 네 앞에서 패하게 하시리라 그들이 한 길로 너를 치러 들어왔으나 네 앞에서 일곱 길로 도망하리라'),
    (5631, '<불순종하여 받는 저주> ○네가 악을 행하여 그를 잊으므로 네 손으로 하는 모든 일에 여호와께서 저주와 혼란과 책망을 내리사 망하며 속히 파멸하게 하실 것이며'),
    (5636, '○여호와께서 네 적군 앞에서 너를 패하게 하시리니 네가 그들을 치러 한 길로 나가서 그들 앞에서 일곱 길로 도망할 것이며 네가 또 땅의 모든 나라 중에 흩어지고'),
    (5647, '○여호와께서 너와 네가 세울 네 임금을 너와 네 조상들이 알지 못하던 나라로 끌어 가시리니 네가 거기서 목석으로 만든 다른 신들을 섬길 것이며'),
    (5658, '○네가 모든 것이 풍족하여도 기쁨과 즐거운 마음으로 네 하나님 여호와를 섬기지 아니함으로 말미암아'),
    (5669, '○네가 만일 이 책에 기록한 이 율법의 모든 말씀을 지켜 행하지 아니하고 네 하나님 여호와라 하는 영화롭고 두려운 이름을 경외하지 아니하면'),
    (5674, '여호와께서 너희에게 선을 행하시고 너희를 번성하게 하시기를 기뻐하시던 것 같이 이제는 여호와께서 너희를 망하게 하시며 멸하시기를 기뻐하시리니 너희가 들어가 차지할 땅에서 뽑힐 것이요'),
    (5679, '여호와께서 너를 배에 싣고 전에 네게 말씀하여 이르시기를 네가 다시는 그 길을 보지 아니하리라 하시던 그 길로 너를 애굽으로 끌어 가실 것이라 거기서 너희가 너희 몸을 적군에게 남녀 종으로 팔려 하나 너희를 살 자가 없으리라'),
    (5713, '네 하나님 여호와께서 너를 네 조상들이 차지한 땅으로 돌아오게 하사 네게 다시 그것을 차지하게 하실 것이며 여호와께서 또 네게 선을 행하사 너를 네 조상들보다 더 번성하게 하실 것이며'),
    (5714, '네 하나님 여호와께서 네 마음과 네 자손의 마음에 할례를 베푸사 너로 마음을 다하며 뜻을 다하여 네 하나님 여호와를 사랑하게 하사 너로 생명을 얻게 하실 것이며'),
    (5717, '네가 네 하나님 여호와의 말씀을 청종하여 이 율법책에 기록된 그의 명령과 규례를 지키고 네 마음을 다하며 뜻을 다하여 여호와 네 하나님께 돌아오면 네 하나님 여호와께서 네 손으로 하는 모든 일과 네 몸의 소생과 네 가축의 새끼와 네 토지 소산을 많게 하시고 네게 복을 주시되 곧 여호와께서 네 조상들을 기뻐하신 것과 같이 너를 다시 기뻐하사 네게 복을 주시리라'),
    (5718, '○내가 오늘 네게 명령한 이 명령은 네게 어려운 것도 아니요 먼 것도 아니라'),
    (5722, '○보라 내가 오늘 생명과 복과 사망과 화를 네 앞에 두었나니'),
    (5723, '곧 내가 오늘 네게 명령하여 네 하나님 여호와를 사랑하고 그 모든 길로 행하며 그의 명령과 규례와 법도를 지키라 하는 것이라 그리하면 네가 생존하며 번성할 것이요 또 네 하나님 여호와께서 네가 가서 차지할 땅에서 네게 복을 주실 것임이니라'),
    (5727, '네 하나님 여호와를 사랑하고 그의 말씀을 청종하며 또 그를 의지하라 그는 네 생명이시요 네 장수이시니 여호와께서 네 조상 아브라함과 이삭과 야곱에게 주리라고 맹세하신 땅에 네가 거주하리라'),
    (5860, '<여호수아가 백성에게 명령을 내리다> ○이에 여호수아가 그 백성의 관리들에게 명령하여 이르되'),
    (5861, '진중에 두루 다니며 그 백성에게 명령하여 이르기를 양식을 준비하라 사흘 안에 너희가 이 요단을 건너 너희의 하나님 여호와께서 너희에게 주사 차지하게 하시는 땅을 차지하기 위하여 들어갈 것임이니라 하라'),
    (5862, '○여호수아가 또 르우벤 지파와 갓 지파와 므낫세 반 지파에게 말하여 이르되'),
    (5865, '여호와께서 너희를 안식하게 하신 것 같이 너희의 형제도 안식하며 그들도 너희의 하나님 여호와께서 주시는 그 땅을 차지하기까지 하라 그리고 너희는 너희 소유지 곧 여호와의 종 모세가 너희에게 준 요단 이쪽 해 돋는 곳으로 돌아와서 그것을 차지할지니라'),
    (5816, '유다에 대한 축복은 이러하니라 일렀으되 여호와여 유다의 음성을 들으시고 그의 백성에게로 인도하시오며 그의 손으로 자기를 위하여 싸우게 하시고 주께서 도우사 그가 그 대적을 치게 하시기를 원하나이다'),
    (5818, '그는 그의 부모에게 대하여 이르기를 내가 그들을 보지 못하였다 하며 그의 형제들을 인정하지 아니하며 그의 자녀를 알지 아니한 것은 주의 말씀을 준행하고 주의 언약을 지킴으로 말미암음이로다'),
    (5838, '이스라엘이여 너는 행복한 사람이로다 여호와의 구원을 너 같이 얻은 백성이 누구냐 그는 너를 돕는 방패시요 네 영광의 칼이시로다 네 대적이 네게 복종하리니 네가 그들의 높은 곳을 밟으리로다'),
    (5869, '<여호수아가 여리고에 정탐꾼을 보내다> 눈의 아들 여호수아가 싯딤에서 두 사람을 정탐꾼으로 보내며 이르되 가서 그 땅과 여리고를 엿보라 하매 그들이 가서 라합이라 하는 기생의 집에 들어가 거기서 유숙하더니'),
    (5876, '○또 그들이 눕기 전에 라합이 지붕에 올라가서 그들에게 이르러'),
    (5878, '이는 너희가 애굽에서 나올 때에 여호와께서 너희 앞에서 홍해 물을 마르게 하신 일과 너희가 요단 저쪽에 있는 아모리 사람의 두 왕 시혼과 옥에게 행한 일 곧 그들을 전멸시킨 일을 우리가 들었음이니라'),
    (5880, '그러므로 이제 청하노니 내가 너희를 선대하였은즉 너희도 내 아버지의 집을 선대하도록 여호와로 내게 맹세하고 내게 증표를 내라'),
    (5883, '○라합이 그들을 창문에서 줄로 달아 내리니 그의 집이 성벽 위에 있으므로 그가 성벽 위에 거주하였음이라'),
    (5887, '누구든지 네 집 문을 나가서 거리로 가면 그의 피가 그의 머리로 돌아갈 것이요 우리는 허물이 없으리라 그러나 누구든지 너와 함께 집에 있는 자에게 손을 대면 그의 피는 우리의 머리로 돌아오려니와'),
    (5890, '○그들이 가서 산에 이르러 뒤쫓는 자들이 돌아가기까지 사흘을 거기 머물매 뒤쫓는 자들이 그들을 길에서 두루 찾다가 찾지 못하니라'),
    (5734, '모세가 여호수아를 불러 온 이스라엘의 목전에서 그에게 이르되 너는 강하고 담대하라 너는 이 백성을 거느리고 여호와께서 그들의 조상에게 주리라고 맹세하신 땅에 들어가서 그들에게 그 땅을 차지하게 하라'),
    (5736, '<일곱 해마다 율법을 낭독하여 주라> ○또 모세가 이 율법을 써서 여호와의 언약궤를 메는 레위 자손 제사장들과 이스라엘 모든 장로에게 주고'),
    (5741, '<여호와께서 모세에게 하신 마지막 지시> ○여호와께서 모세에게 이르시되 네가 죽을 기한이 가까웠으니 여호수아를 불러서 함께 회막으로 나아오라 내가 그에게 명령을 내리리라 모세와 여호수아가 나아가서 회막에 서니'),
    (5743, '또 여호와께서 모세에게 이르시되 너는 네 조상과 함께 누우려니와 이 백성은 그 땅으로 들어가 음란히 그 땅의 이방 신들을 따르며 일어날 것이요 나를 버리고 내가 그들과 맺은 언약을 어길 것이라'),
    (5744, '내가 그들에게 진노하여 그들을 버리며 내 얼굴을 숨겨 그들에게 보이지 않게 할 것인즉 그들이 삼킴을 당하여 허다한 재앙과 환난이 그들에게 임할 그 때에 그들이 말하기를 이 재앙이 우리에게 내림은 우리 하나님이 우리 가운데에 계시지 않은 까닭이 아니냐 할 것이라'),
    (5748, '그들이 수많은 재앙과 환난을 당할 때에 그들의 자손이 부르기를 잊지 아니한 이 노래가 그들 앞에 증인처럼 되리라 나는 내가 맹세한 땅으로 그들을 인도하여 들이기 전 오늘 나는 그들이 생각하는 바를 아노라'),
    (5751, '○모세가 이 율법의 말씀을 다 책에 써서 마친 후에'),
    (5756, '내가 알거니와 내가 죽은 후에 너희가 스스로 부패하여 내가 너희에게 명령한 길을 떠나 여호와의 목전에 악을 행하여 너희의 손으로 하는 일로 그를 격노하게 하므로 너희가 후일에 재앙을 당하리라 하니라'),
    (5757, '<모세의 노래> ○그리고 모세가 이스라엘 총회에 이 노래의 말씀을 끝까지 읽어 들리니라'),
    (5805, '○바로 그 날에 여호와께서 모세에게 말씀하여 이르시되'),
    (5847, '○모세가 눈의 아들 여호수아에게 안수하였으므로 그에게 지혜의 영이 충만하니 이스라엘 자손이 여호와께서 모세에게 명령하신 대로 여호수아의 말을 순종하였더라'),
    (5917, '이스라엘 자손들이 여호수아가 명령한 대로 행하되 여호와께서 여호수아에게 이르신 대로 이스라엘 자손들의 지파의 수를 따라 요단 가운데에서 돌 열둘을 택하여 자기들이 유숙할 곳으로 가져다가 거기에 두었더라'),
    (5924, '○여호와께서 여호수아에게 말씀하여 이르시되'),
    (5928, '○첫째 달 십일에 백성이 요단에서 올라와 여리고 동쪽 경계 길갈에 진 치매'),
    (5899, '○여호와께서 여호수아에게 이르시되 내가 오늘부터 시작하여 너를 온 이스라엘의 목전에서 크게 하여 내가 모세와 함께 있었던 것 같이 너와 함께 있는 것을 그들이 알게 하리라'),
    (5902, '또 말하되 살아 계신 하나님이 너희 가운데에 계시사 가나안 족속과 헷 족속과 히위 족속과 브리스 족속과 기르가스 족속과 아모리 족속과 여부스 족속을 너희 앞에서 반드시 쫓아내실 줄을 이것으로서 너희가 알리라'),
    (5906, '○백성이 요단을 건너려고 자기들의 장막을 떠날 때에 제사장들은 언약궤를 메고 백성 앞에서 나아가니라'),
    (5908, '곧 위에서부터 흘러내리던 물이 그쳐서 사르단에 가까운 매우 멀리 있는 아담 성읍 변두리에 일어나 한 곳에 쌓이고 아라바의 바다 염해로 향하여 흘러가는 물은 온전히 끊어지매 백성이 여리고 앞으로 바로 건널새'),
    (5956, '○여호수아가 백성에게 이르기를 마치매 제사장 일곱은 양각 나팔 일곱을 잡고 여호와 앞에서 나아가며 나팔을 불고 여호와의 언약궤는 그 뒤를 따르며'),
    (5958, '여호수아가 백성에게 명령하여 이르되 너희는 외치지 말며 너희 음성을 들리게 하지 말며 너희 입에서 아무 말도 내지 말라 그리하다가 내가 너희에게 명령하여 외치라 하는 날에 외칠지니라 하고'),
    (5960, '○또 여호수아가 아침에 일찍이 일어나니 제사장들이 여호와의 궤를 메고'),
    (5963, '○일곱째 날 새벽에 그들이 일찍이 일어나서 전과 같은 방식으로 그 성을 일곱 번 도니 그 성을 일곱 번 돌기는 그 날뿐이었더라'),
    (5970, '○여호수아가 그 땅을 정탐한 두 사람에게 이르되 그 기생의 집에 들어가서 너희가 그 여인에게 맹세한 대로 그와 그에게 속한 모든 것을 이끌어 내라 하매'),
    (5973, '여호수아가 기생 라합과 그의 아버지의 가족과 그에게 속한 모든 것을 살렸으므로 그가 오늘까지 이스라엘 중에 거주하였으니 이는 여호수아가 여리고를 정탐하려고 보낸 사자들을 숨겼음이었더라'),
    (5974, '여호수아가 그 때에 맹세하게 하여 이르되 누구든지 일어나서 이 여리고 성을 건축하는 자는 여호와 앞에서 저주를 받을 것이라 그 기초를 쌓을 때에 그의 맏아들을 잃을 것이요 그 문을 세울 때에 그의 막내아들을 잃으리라 하였더라'),
    (5934, '요단 서쪽의 아모리 사람의 모든 왕들과 해변의 가나안 사람의 모든 왕들이 여호와께서 요단 물을 이스라엘 자손들 앞에서 말리시고 우리를 건너게 하셨음을 듣고 마음이 녹았고 이스라엘 자손들 때문에 정신을 잃었더라'),
    (5935, '<이스라엘이 길갈에서 할례를 받다> ○그 때에 여호와께서 여호수아에게 이르시되 너는 부싯돌로 칼을 만들어 이스라엘 자손들에게 다시 할례를 행하라 하시매'),
    (5939, '이스라엘 자손들이 여호와의 음성을 청종하지 아니하므로 여호와께서 그들에게 대하여 맹세하사 그들의 조상들에게 맹세하여 우리에게 주리라고 하신 땅 곧 젖과 꿀이 흐르는 땅을 그들이 보지 못하게 하리라 하시매 애굽에서 나온 족속 곧 군사들이 다 멸절하기까지 사십 년 동안을 광야에서 헤매었더니'),
    (5943, '○또 이스라엘 자손들이 길갈에 진 쳤고 그 달 십사일 저녁에는 여리고 평지에서 유월절을 지켰으며'),
    (5946, '<칼을 든 여호와의 군대 대장> ○여호수아가 여리고에 가까이 이르렀을 때에 눈을 들어 본즉 한 사람이 칼을 빼어 손에 들고 마주 서 있는지라 여호수아가 나아가서 그에게 묻되 너는 우리를 위하느냐 우리의 적들을 위하느냐 하니'),
    (5976, '<아간의 범죄> 이스라엘 자손들이 온전히 바친 물건으로 말미암아 범죄하였으니 이는 유다 지파 세라의 증손 삽디의 손자 갈미의 아들 아간이 온전히 바친 물건을 가졌음이라 여호와께서 이스라엘 자손들에게 진노하시니라'),
    (5977, '○여호수아가 여리고에서 사람을 벧엘 동쪽 벧아웬 곁에 있는 아이로 보내며 그들에게 말하여 이르되 올라가서 그 땅을 정탐하라 하매 그 사람들이 올라가서 아이를 정탐하고'),
    (5982, '이르되 슬프도소이다 주 여호와여 어찌하여 이 백성을 인도하여 요단을 건너게 하시고 우리를 아모리 사람의 손에 넘겨 멸망시키려 하셨나이까 우리가 요단 저쪽을 만족하게 여겨 거주하였더면 좋을 뻔하였나이다'),
    (5987, '그러므로 이스라엘 자손들이 그들의 원수 앞에 능히 맞서지 못하고 그 앞에서 돌아섰나니 이는 그들도 온전히 바친 것이 됨이라 그 온전히 바친 물건을 너희 중에서 멸하지 아니하면 내가 다시는 너희와 함께 있지 아니하리라'),
    (5988, '너는 일어나서 백성을 거룩하게 하여 이르기를 너희는 내일을 위하여 스스로 거룩하게 하라 이스라엘의 하나님 여호와의 말씀에 이스라엘아 너희 가운데에 온전히 바친 물건이 있나니 너희가 그 온전히 바친 물건을 너희 가운데에서 제하기까지는 네 원수들 앞에 능히 맞서지 못하리라'),
    (5989, '너희는 아침에 너희의 지파대로 가까이 나아오라 여호와께 뽑히는 그 지파는 그 족속대로 가까이 나아올 것이요 여호와께 뽑히는 족속은 그 가족대로 가까이 나아올 것이요 여호와께 뽑히는 그 가족은 그 남자들이 가까이 나아올 것이며'),
    (5991, '○이에 여호수아가 아침 일찍이 일어나서 이스라엘을 그의 지파대로 가까이 나아오게 하였더니 유다 지파가 뽑혔고'),
    (5996, '내가 노략한 물건 중에 시날 산의 아름다운 외투 한 벌과 은 이백 세겔과 그 무게가 오십 세겔 되는 금덩이 하나를 보고 탐내어 가졌나이다 보소서 이제 그 물건들을 내 장막 가운데 땅 속에 감추었는데 은은 그 밑에 있나이다 하더라'),
    (5997, '○이에 여호수아가 사자들을 보내매 그의 장막에 달려가 본즉 물건이 그의 장막 안에 감추어져 있는데 은은 그 밑에 있는지라'),
    (5999, '여호수아가 이스라엘 모든 사람과 더불어 세라의 아들 아간을 잡고 그 은과 그 외투와 그 금덩이와 그의 아들들과 그의 딸들과 그의 소들과 그의 나귀들과 그의 양들과 그의 장막과 그에게 속한 모든 것을 이끌고 아골 골짜기로 가서'),
    (6037, '<기브온 주민들이 여호수아를 속이다> 이 일 후에 요단 서쪽 산지와 평지와 레바논 앞 대해 연안에 있는 헷 사람과 아모리 사람과 가나안 사람과 브리스 사람과 히위 사람과 여부스 사람의 모든 왕들이 이 일을 듣고'),
    (6039, '○기브온 주민들이 여호수아가 여리고와 아이에 행한 일을 듣고'),
    (6047, '그러므로 우리 장로들과 우리 나라의 모든 주민이 우리에게 말하여 이르되 너희는 여행할 양식을 손에 가지고 가서 그들을 만나서 그들에게 이르기를 우리는 당신들의 종들이니 이제 우리와 조약을 맺읍시다 하라 하였나이다'),
    (6052, '○그들과 조약을 맺은 후 사흘이 지나서야 그들이 이웃에서 자기들 중에 거주하는 자들이라 함을 들으니라'),
    (6058, '○여호수아가 그들을 불러다가 말하여 이르되 너희가 우리 가운데에 거주하면서 어찌하여 심히 먼 곳에서 왔다고 하여 우리를 속였느냐'),
    (6060, '그들이 여호수아에게 대답하여 이르되 당신의 하나님 여호와께서 그의 종 모세에게 명령하사 이 땅을 다 당신들에게 주고 이 땅의 모든 주민을 당신들 앞에서 멸하라 하신 것이 당신의 종들에게 분명히 들리므로 당신들로 말미암아 우리의 목숨을 잃을까 심히 두려워하여 이같이 하였나이다'),
    (6002, '<아이 성을 점령하다> 여호와께서 여호수아에게 이르시되 두려워하지 말라 놀라지 말라 군사를 다 거느리고 일어나 아이로 올라가라 보라 내가 아이 왕과 그의 백성과 그의 성읍과 그의 땅을 다 네 손에 넘겨 주었으니'),
    (6004, '○이에 여호수아가 일어나서 군사와 함께 아이로 올라가려 하여 용사 삼만 명을 뽑아 밤에 보내며'),
    (6011, '○여호수아가 아침에 일찍이 일어나 백성을 점호하고 이스라엘 장로들과 더불어 백성에 앞서 아이로 올라가매'),
    (6019, '○여호와께서 여호수아에게 이르시되 네 손에 잡은 단창을 들어 아이를 가리키라 내가 이 성읍을 네 손에 넘겨 주리라 여호수아가 그의 손에 잡은 단창을 들어 그 성읍을 가리키니'),
    (6025, '○이스라엘이 자기들을 광야로 추격하던 모든 아이 주민을 들에서 죽이되 그들을 다 칼날에 엎드러지게 하여 진멸하기를 마치고 온 이스라엘이 아이로 돌아와서 칼날로 죽이매'),
    (6031, '<에발 산에서 율법을 낭독하다> ○그 때에 여호수아가 이스라엘의 하나님 여호와를 위하여 에발 산에 한 제단을 쌓았으니'),
    (6032, '이는 여호와의 종 모세가 이스라엘 자손에게 명령한 것과 모세의 율법책에 기록된 대로 쇠 연장으로 다듬지 아니한 새 돌로 만든 제단이라 무리가 여호와께 번제물과 화목제물을 그 위에 드렸으며'),
    (6034, '온 이스라엘과 그 장로들과 관리들과 재판장들과 본토인뿐 아니라 이방인까지 여호와의 언약궤를 멘 레위 사람 제사장들 앞에서 궤의 좌우에 서되 절반은 그리심 산 앞에, 절반은 에발 산 앞에 섰으니 이는 전에 여호와의 종 모세가 이스라엘 백성에게 축복하라고 명령한 대로 함이라'),
    (6136, '<여호수아가 정복한 왕들> ○여호수아와 이스라엘 자손이 요단 이편 곧 서쪽 레바논 골짜기의 바알갓에서부터 세일로 올라가는 곳 할락 산까지 쳐서 멸한 그 땅의 왕들은 이러하니라 (그 땅을 여호수아가 이스라엘의 지파들에게 구분에 따라 소유로 주었으니'),
    (6267, '서쪽으로 내려가서 야블렛 족속의 경계와 아래 벧호론과 게셀에까지 이르고 그 끝은 바다라'),
    (6269, '<에브라임 자손의 기업> ○에브라임 자손이 그들의 가족대로 받은 지역은 이러하니라 그들의 기업의 경계는 동쪽으로 아다롯 앗달에서 윗 벧호론에 이르고'),
    (6112, '○여호와께서 여호수아에게 이르시되 그들로 말미암아 두려워하지 말라 내일 이맘때에 내가 그들을 이스라엘 앞에 넘겨 주어 몰살시키리니 너는 그들의 말 뒷발의 힘줄을 끊고 그들의 병거를 불사르라 하시니라'),
    (6114, '여호와께서 그들을 이스라엘의 손에 넘겨 주셨기 때문에 그들을 격파하고 큰 시돈과 미스르봇 마임까지 추격하고 동쪽으로는 미스바 골짜기까지 추격하여 한 사람도 남기지 아니하고 쳐죽이고'),
    (6116, '○하솔은 본래 그 모든 나라의 머리였더니 그 때에 여호수아가 돌아와서 하솔을 취하고 그 왕을 칼날로 쳐죽이고'),
    (6122, '<여호수아가 취한 지역> ○여호수아가 이같이 그 온 땅 곧 산지와 온 네겝과 고센 온 땅과 평지와 아라바와 이스라엘 산지와 평지를 점령하였으니'),
    (6126, '그들의 마음이 완악하여 이스라엘을 대적하여 싸우러 온 것은 여호와께서 그리하게 하신 것이라 그들을 진멸하여 바치게 하여 은혜를 입지 못하게 하시고 여호와께서 모세에게 명령하신 대로 그들을 멸하려 하심이었더라'),
    (6127, '○그 때에 여호수아가 가서 산지와 헤브론과 드빌과 아납과 유다 온 산지와 이스라엘의 온 산지에서 아낙 사람들을 멸절하고 그가 또 그들의 성읍들을 진멸하여 바쳤으므로'),
    (6192, '<갈렙이 헤브론을 기업으로 받다> ○그 때에 유다 자손이 길갈에 있는 여호수아에게 나아오고 그니스 사람 여분네의 아들 갈렙이 여호수아에게 말하되 여호와께서 가데스 바네아에서 나와 당신에게 대하여 하나님의 사람 모세에게 이르신 일을 당신이 아시는 바라'),
    (6198, '그 날에 여호와께서 말씀하신 이 산지를 지금 내게 주소서 당신도 그 날에 들으셨거니와 그 곳에는 아낙 사람이 있고 그 성읍들은 크고 견고할지라도 여호와께서 나와 함께 하시면 내가 여호와께서 말씀하신 대로 그들을 쫓아내리이다 하니'),
    (6199, '○여호수아가 여분네의 아들 갈렙을 위하여 축복하고 헤브론을 그에게 주어 기업을 삼게 하매'),
    (6200, '헤브론이 그니스 사람 여분네의 아들 갈렙의 기업이 되어 오늘까지 이르렀으니 이는 그가 이스라엘의 하나님 여호와를 온전히 좇았음이라'),
    (6214, '<갈렙이 헤브론과 드빌을 정복하다> ○여호와께서 여호수아에게 명령하신 대로 여호수아가 기럇 아르바 곧 헤브론을 유다 자손 중에서 분깃으로 여분네의 아들 갈렙에게 주었으니 아르바는 아낙의 아버지였더라'),
    (6221, '<유다 자손의 기업> ○유다 자손의 지파가 그들의 가족대로 받은 기업은 이러하니라'),
    (6222, '○유다 자손의 지파의 남쪽 끝 에돔 경계에 접근한 성읍들은 갑스엘과 에델과 야굴과'),
    (6264, '○예루살렘 주민 여부스 족속을 유다 자손이 쫓아내지 못하였으므로 여부스 족속이 오늘까지 유다 자손과 함께 예루살렘에 거주하니라'),
    (6275, '<서쪽 므낫세 자손의 기업> 므낫세 지파를 위하여 제비 뽑은 것은 이러하니라 므낫세는 요셉의 장자였고 므낫세의 장자 마길은 길르앗의 아버지라 그는 용사였기 때문에 길르앗과 바산을 받았으므로'),
    (6276, '므낫세의 남은 자손을 위하여 그들의 가족대로 제비를 뽑았는데 그들은 곧 아비에셀의 자손과 헬렉의 자손과 아스리엘의 자손과 세겜의 자손과 헤벨의 자손과 스미다의 자손이니 그들의 가족대로 요셉의 아들 므낫세의 남자 자손들이며'),
    (6278, '그들이 제사장 엘르아살과 눈의 아들 여호수아와 지도자들 앞에 나아와서 말하기를 여호와께서 모세에게 명령하사 우리 형제 중에서 우리에게 기업을 주라 하셨다 하매 여호와의 명령을 따라 그들에게 그들의 아버지 형제들 중에서 기업을 주므로'),
    (6281, '○므낫세의 경계는 아셀에서부터 세겜 앞 믹므닷까지이며 그 오른쪽으로 가서 엔답부아 주민의 경계에 이르나니'),
    (6285, '잇사갈과 아셀에도 므낫세의 소유가 있으니 곧 벧 스안과 그 마을들과 이블르암과 그 마을들과 돌의 주민과 그 마을들이요 또 엔돌 주민과 그 마을들과 다아낙 주민과 그 마을들과 므깃도 주민과 그 마을들 세 언덕 지역이라'),
    (6288, '<에브라임과 므낫세 지파가 땅을 더 요구함> ○요셉 자손이 여호수아에게 말하여 이르되 여호와께서 지금까지 내게 복을 주시므로 내가 큰 민족이 되었거늘 당신이 나의 기업을 위하여 한 제비, 한 분깃으로만 내게 주심은 어찌함이니이까 하니'),
    (6290, '요셉 자손이 이르되 그 산지는 우리에게 넉넉하지도 못하고 골짜기 땅에 거주하는 모든 가나안 족속에게는 벧 스안과 그 마을들에 거주하는 자이든지 이스르엘 골짜기에 거주하는 자이든지 다 철 병거가 있나이다 하니'),
    (6330, '<스불론 자손의 기업> ○셋째로 스불론 자손을 위하여 그들의 가족대로 제비를 뽑았으니 그들의 기업의 경계는 사릿까지이며'),
    (6337, '<잇사갈 자손의 기업> ○넷째로 잇사갈 곧 잇사갈 자손을 위하여 그들의 가족대로 제비를 뽑았으니'),
    (6344, '<아셀 자손의 기업> ○다섯째로 아셀 자손의 지파를 위하여 그 가족대로 제비를 뽑았으니'),
    (6352, '<납달리 자손의 기업> ○여섯째로 납달리 자손을 위하여 납달리 자손의 가족대로 제비를 뽑았으니'),
    (6360, '<단 자손의 기업> ○일곱째로 단 자손의 지파를 위하여 그들의 가족대로 제비를 뽑았으니'),
    (6367, '그런데 단 자손의 경계는 더욱 확장되었으니 이는 단 자손이 올라가서 레셈과 싸워 그것을 점령하여 칼날로 치고 그것을 차지하여 거기 거주하였음이라 그들의 조상 단의 이름을 따라서 레셈을 단이라 하였더라'),
    (6369, '<기업의 땅 나누기를 마치다> ○이스라엘 자손이 그들의 경계를 따라서 기업의 땅 나누기를 마치고 자기들 중에서 눈의 아들 여호수아에게 기업을 주었으니'),
    (6371, '○제사장 엘르아살과 눈의 아들 여호수아와 이스라엘 자손의 지파의 족장들이 실로에 있는 회막 문 여호와 앞에서 제비 뽑아 나눈 기업이 이러하니라 이에 땅 나누는 일을 마쳤더라'),
    (6299, '레위 사람은 너희 중에 분깃이 없나니 여호와의 제사장 직분이 그들의 기업이 됨이며 갓과 르우벤과 므낫세 반 지파는 요단 저편 동쪽에서 이미 기업을 받았나니 이는 여호와의 종 모세가 그들에게 준 것이니라 하더라'),
    (6300, '○그 사람들이 일어나 떠나니 여호수아가 그 땅을 그리러 가는 사람들에게 명령하여 이르되 가서 그 땅으로 두루 다니며 그것을 그려 가지고 내게로 돌아오라 내가 여기 실로의 여호와 앞에서 너희를 위하여 제비를 뽑으리라 하니'),
    (6303, '<베냐민 자손의 기업> ○베냐민 자손 지파를 위하여 그들의 가족대로 제비를 뽑았으니 그 제비 뽑은 땅의 경계는 유다 자손과 요셉 자손의 중간이라'),
    (6305, '또 그 경계가 거기서부터 루스로 나아가서 루스 남쪽에 이르나니 루스는 곧 벧엘이며 또 그 경계가 아다롯 앗달로 내려가서 아래 벧호론 남쪽 산 곁으로 지나고'),
    (6306, '벧호론 앞 남쪽 산에서부터 서쪽으로 돌아 남쪽으로 향하여 유다 자손의 성읍 기럇 바알 곧 기럇 여아림에 이르러 끝이 되나니 이는 서쪽 경계며'),
    (6313, '○베냐민 자손의 지파가 그들의 가족대로 받은 성읍들은 여리고와 벧 호글라와 에멕 그시스와'),
    (6375, '이 성읍들 중의 하나에 도피하는 자는 그 성읍에 들어가는 문 어귀에 서서 그 성읍의 장로들의 귀에 자기의 사건을 말할 것이요 그들은 그를 성읍에 받아들여 한 곳을 주어 자기들 중에 거주하게 하고'),
    (6377, '그 살인자는 회중 앞에 서서 재판을 받기까지 또는 그 당시 대제사장이 죽기까지 그 성읍에 거주하다가 그 후에 그 살인자는 그 성읍 곧 자기가 도망하여 나온 자기 성읍 자기 집으로 돌아갈지니라 하라 하시니라'),
    (6378, '○이에 그들이 납달리의 산지 갈릴리 게데스와 에브라임 산지의 세겜과 유다 산지의 기럇 아르바 곧 헤브론과'),
    (6380, '이는 곧 이스라엘 모든 자손과 그들 중에 거류하는 거류민을 위하여 선정된 성읍들로서 누구든지 부지중에 살인한 자가 그리로 도망하여 그가 회중 앞에 설 때까지 피의 보복자의 손에 죽지 아니하게 하기 위함이라'),
    (6064, '<여호수아가 기브온을 구하다> 그 때에 여호수아가 아이를 빼앗아 진멸하되 여리고와 그 왕에게 행한 것 같이 아이와 그 왕에게 행한 것과 또 기브온 주민이 이스라엘과 화친하여 그 중에 있다 함을 예루살렘 왕 아도니세덱이 듣고'),
    (6069, '○기브온 사람들이 길갈 진영에 사람을 보내어 여호수아에게 전하되 당신의 종들 돕기를 더디게 하지 마시고 속히 우리에게 올라와 우리를 구하소서 산지에 거주하는 아모리 사람의 왕들이 다 모여 우리를 치나이다 하매'),
    (6073, '여호와께서 그들을 이스라엘 앞에서 패하게 하시므로 여호수아가 그들을 기브온에서 크게 살륙하고 벧호론에 올라가는 비탈에서 추격하여 아세가와 막게다까지 이르니라'),
    (6074, '그들이 이스라엘 앞에서 도망하여 벧호론의 비탈에서 내려갈 때에 여호와께서 하늘에서 큰 우박 덩이를 아세가에 이르기까지 내리시매 그들이 죽었으니 이스라엘 자손의 칼에 죽은 자보다 우박에 죽은 자가 더 많았더라'),
    (6075, '○여호와께서 아모리 사람을 이스라엘 자손에게 넘겨 주시던 날에 여호수아가 여호와께 아뢰어 이스라엘의 목전에서 이르되 태양아 너는 기브온 위에 머무르라 달아 너도 아얄론 골짜기에서 그리할지어다 하매'),
    (6078, '○여호수아가 온 이스라엘과 더불어 길갈 진영으로 돌아왔더라'),
    (6079, '<아모리의 모든 왕과 땅을 취하다> ○그 다섯 왕들이 도망하여 막게다의 굴에 숨었더니'),
    (6085, '○그 때에 여호수아가 이르되 굴 어귀를 열고 그 굴에서 그 다섯 왕들을 내게로 끌어내라 하매'),
    (6087, '그 왕들을 여호수아에게로 끌어내매 여호수아가 이스라엘 모든 사람을 부르고 자기와 함께 갔던 지휘관들에게 이르되 가까이 와서 이 왕들의 목을 발로 밟으라 하매 그들이 가까이 가서 그들의 목을 밟으매'),
    (6091, '○그 날에 여호수아가 막게다를 취하고 칼날로 그 성읍과 왕을 쳐서 그 성읍과 그 중에 있는 모든 사람을 진멸하여 바치고 한 사람도 남기지 아니하였으니 막게다 왕에게 행한 것이 여리고 왕에게 행한 것과 같았더라'),
    (6092, '○여호수아가 온 이스라엘과 더불어 막게다에서 립나로 나아가서 립나와 싸우매'),
    (6093, '여호와께서 또 그 성읍과 그 왕을 이스라엘의 손에 붙이신지라 칼날로 그 성읍과 그 중의 모든 사람을 쳐서 멸하여 한 사람도 남기지 아니하였으니 그 왕에게 행한 것이 여리고 왕에게 행한 것과 같았더라'),
    (6094, '○여호수아가 또 온 이스라엘과 더불어 립나에서 라기스로 나아가서 대진하고 싸우더니'),
    (6096, '○그 때에 게셀 왕 호람이 라기스를 도우려고 올라오므로 여호수아가 그와 그의 백성을 쳐서 한 사람도 남기지 아니하였더라'),
    (6097, '○여호수아가 온 이스라엘과 더불어 라기스에서 에글론으로 나아가서 대진하고 싸워'),
    (6099, '○여호수아가 또 온 이스라엘과 더불어 에글론에서 헤브론으로 올라가서 싸워'),
    (6100, '그 성읍을 점령하고 그것과 그 왕과 그 속한 성읍들과 그 중의 모든 사람을 칼날로 쳐서 하나도 남기지 아니하였으니 그 성읍들과 그 중의 모든 사람을 진멸하여 바친 것이 에글론에 행한 것과 같았더라'),
    (6101, '○여호수아가 온 이스라엘과 더불어 돌아와서 드빌에 이르러 싸워'),
    (6102, '그 성읍과 그 왕과 그 속한 성읍들을 점령하고 칼날로 그 성읍을 쳐서 그 안의 모든 사람을 진멸하여 바치고 하나도 남기지 아니하였으니 드빌과 그 왕에게 행한 것이 헤브론에 행한 것과 같았으며 립나와 그 왕에게 행한 것과 같았더라'),
    (6103, '○이와 같이 여호수아가 그 온 땅 곧 산지와 네겝과 평지와 경사지와 그 모든 왕을 쳐서 하나도 남기지 아니하고 호흡이 있는 모든 자는 다 진멸하여 바쳤으니 이스라엘의 하나님 여호와께서 명령하신 것과 같았더라'),
    (6156, '곧 애굽 앞 시홀 시내에서부터 가나안 사람에게 속한 북쪽 에그론 경계까지와 블레셋 사람의 다섯 통치자들의 땅 곧 가사 족속과 아스돗 족속과 아스글론 족속과 가드 족속과 에그론 족속과 또 남쪽 아위 족속의 땅과'),
    (6159, '또 레바논에서부터 미스르봇마임까지 산지의 모든 주민 곧 모든 시돈 사람의 땅이라 내가 그들을 이스라엘 자손 앞에서 쫓아내리니 너는 내가 명령한 대로 그 땅을 이스라엘에게 분배하여 기업이 되게 하되'),
    (6161, '<요단 동쪽 기업의 분배> ○므낫세 반 지파와 함께 르우벤 족속과 갓 족속은 요단 저편 동쪽에서 그들의 기업을 모세에게 받았는데 여호와의 종 모세가 그들에게 준 것은 이러하니'),
    (6168, '<르우벤 자손의 기업> ○모세가 르우벤 자손의 지파에게 그들의 가족을 따라서 기업을 주었으니'),
    (6177, '<갓 자손의 기업> ○모세가 갓 지파 곧 갓 자손에게도 그들의 가족을 따라서 기업을 주었으니'),
    (6182, '<동쪽 므낫세 자손의 기업> ○모세가 므낫세 반 지파에게 기업을 주었으되 므낫세 자손의 반 지파에게 그들의 가족대로 주었으니'),
    (6185, '○요단 동쪽 여리고 맞은편 모압 평지에서 모세가 분배한 기업이 이러하여도'),
    (6429, '이제는 너희의 하나님 여호와께서 이미 말씀하신 대로 너희 형제에게 안식을 주셨으니 그런즉 이제 너희는 여호와의 종 모세가 요단 저쪽에서 너희에게 준 소유지로 가서 너희의 장막으로 돌아가되'),
    (6430, '오직 여호와의 종 모세가 너희에게 명령한 명령과 율법을 반드시 행하여 너희의 하나님 여호와를 사랑하고 그의 모든 길로 행하며 그의 계명을 지켜 그에게 친근히 하고 너희의 마음을 다하며 성품을 다하여 그를 섬길지니라 하고'),
    (6432, '므낫세 반 지파에게는 모세가 바산에서 기업을 주었고 그 남은 반 지파에게는 여호수아가 요단 이쪽 서쪽에서 그들의 형제들과 함께 기업을 준지라 여호수아가 그들을 그들의 장막으로 돌려보낼 때에 그들에게 축복하고'),
    (6433, '말하여 이르되 너희는 많은 재산과 심히 많은 가축과 은과 금과 구리와 쇠와 심히 많은 의복을 가지고 너희의 장막으로 돌아가서 너희의 원수들에게서 탈취한 것을 너희의 형제와 나눌지니라 하매'),
    (6435, '<요단 가에 제단을 쌓다> 르우벤 자손과 갓 자손과 므낫세 반 지파가 가나안 땅 요단 언덕 가에 이르자 거기서 요단 가에 제단을 쌓았는데 보기에 큰 제단이었더라'),
    (6440, '그들이 길르앗 땅에 이르되 르우벤 자손과 갓 자손과 므낫세 반 지파에게 나아가서 그들에게 말하여 이르되'),
    (6444, '그런데 너희의 소유지가 만일 깨끗하지 아니하거든 여호와의 성막이 있는 여호와의 소유지로 건너와 우리 중에서 소유지를 나누어 가질 것이니라 오직 우리 하나님 여호와의 제단 외에 다른 제단을 쌓음으로 여호와를 거역하지 말며 우리에게도 거역하지 말라'),
    (6450, '너희 르우벤 자손 갓 자손아 여호와께서 우리와 너희 사이에 요단으로 경계를 삼으셨나니 너희는 여호와께 받을 분깃이 없느니라 하여 너희의 자손이 우리 자손에게 여호와 경외하기를 그치게 할까 하여'),
    (6452, '우리가 여호와 앞에서 우리의 번제와 우리의 다른 제사와 우리의 화목제로 섬기는 것을 우리와 너희 사이와 우리의 후대 사이에 증거가 되게 할 뿐으로서 너희 자손들이 후일에 우리 자손들에게 이르기를 너희는 여호와께 받을 분깃이 없다 하지 못하게 하려 함이라'),
    (6453, '우리가 말하였거니와 만일 그들이 후일에 우리에게나 우리 후대에게 이같이 말하면 우리가 말하기를 우리 조상이 지은 여호와의 제단 모형을 보라 이는 번제를 위한 것도 아니요 다른 제사를 위한 것도 아니라 오직 우리와 너희 사이에 증거만 되게 할 뿐이라'),
    (6454, '우리가 번제나 소제나 다른 제사를 위하여 우리 하나님 여호와의 성막 앞에 있는 제단 외에 제단을 쌓음으로 여호와를 거역하고 오늘 여호와를 따르는 데에서 돌아서려는 것은 결단코 아니라 하리라'),
    (6456, '제사장 엘르아살의 아들 비느하스가 르우벤 자손과 갓 자손과 므낫세 자손에게 이르되 우리가 오늘 여호와께서 우리 중에 계신 줄을 아노니 이는 너희가 이 죄를 여호와께 범하지 아니하였음이니라 너희가 이제 이스라엘 자손을 여호와의 손에서 건져내었느니라 하고'),
    (6472, '확실히 알라 너희의 하나님 여호와께서 이 민족들을 너희 목전에서 다시는 쫓아내지 아니하시리니 그들이 너희에게 올무가 되며 덫이 되며 너희의 옆구리에 채찍이 되며 너희의 눈에 가시가 되어서 너희가 마침내 너희의 하나님 여호와께서 너희에게 주신 이 아름다운 땅에서 멸하리라'),
    (6473, '○보라 나는 오늘 온 세상이 가는 길로 가려니와 너희의 하나님 여호와께서 너희에게 대하여 말씀하신 모든 선한 말씀이 하나도 틀리지 아니하고 다 너희에게 응하여 그 중에 하나도 어김이 없음을 너희 모든 사람은 마음과 뜻으로 아는 바라'),
    (6474, '너희의 하나님 여호와께서 너희에게 말씀하신 모든 선한 말씀이 너희에게 임한 것 같이 여호와께서 모든 불길한 말씀도 너희에게 임하게 하사 너희의 하나님 여호와께서 너희에게 주신 이 아름다운 땅에서 너희를 멸절하기까지 하실 것이라'),
    (6475, '만일 너희가 너희의 하나님 여호와께서 너희에게 명령하신 언약을 범하고 가서 다른 신들을 섬겨 그들에게 절하면 여호와의 진노가 너희에게 미치리니 너희에게 주신 아름다운 땅에서 너희가 속히 멸망하리라 하니라'),
    (6511, '유다가 그의 형제 시므온에게 이르되 내가 제비 뽑아 얻은 땅에 나와 함께 올라가서 가나안 족속과 싸우자 그리하면 나도 네가 제비 뽑아 얻은 땅에 함께 가리라 하니 이에 시므온이 그와 함께 가니라'),
    (6515, '아도니 베섹이 이르되 옛적에 칠십 명의 왕들이 그들의 엄지손가락과 엄지발가락이 잘리고 내 상 아래에서 먹을 것을 줍더니 하나님이 내가 행한 대로 내게 갚으심이로다 하니라 무리가 그를 끌고 예루살렘에 이르렀더니 그가 거기서 죽었더라'),
    (6516, '<유다 지파가 예루살렘과 헤브론을 치다> ○유다 자손이 예루살렘을 쳐서 점령하여 칼날로 치고 그 성을 불살랐으며'),
    (6519, '<옷니엘이 드빌을 치다> ○거기서 나아가서 드빌의 주민들을 쳤으니 드빌의 본 이름은 기럇 세벨이라'),
    (6524, '<유다와 베냐민 지파의 승리> ○모세의 장인은 겐 사람이라 그의 자손이 유다 자손과 함께 종려나무 성읍에서 올라가서 아랏 남방의 유다 황무지에 이르러 그 백성 중에 거주하니라'),
    (6530, '<에브라임과 므낫세 지파가 벧엘을 치다> ○요셉 가문도 벧엘을 치러 올라가니 여호와께서 그와 함께 하시니라'),
    (6535, '<쫓아내지 못한 가나안 족속> ○므낫세가 벧스안과 그에 딸린 마을들의 주민과 다아낙과 그에 딸린 마을들의 주민과 돌과 그에 딸린 마을들의 주민과 이블르암과 그에 딸린 마을들의 주민과 므깃도와 그에 딸린 마을들의 주민들을 쫓아내지 못하매 가나안 족속이 결심하고 그 땅에 거주하였더니'),
    (6537, '○에브라임이 게셀에 거주하는 가나안 족속을 쫓아내지 못하매 가나안 족속이 게셀에서 그들 중에 거주하였더라'),
    (6538, '○스불론은 기드론 주민과 나할롤 주민을 쫓아내지 못하였으므로 가나안 족속이 그들 중에 거주하면서 노역을 하였더라'),
    (6539, '○아셀이 악고 주민과 시돈 주민과 알랍과 악십과 헬바와 아빅과 르홉 주민을 쫓아내지 못하고'),
    (6541, '○납달리는 벧세메스 주민과 벧아낫 주민을 쫓아내지 못하고 그 땅의 주민 가나안 족속 가운데 거주하였으나 벧세메스와 벧아낫 주민들이 그들에게 노역을 하였더라'),
    (6542, '○아모리 족속이 단 자손을 산지로 몰아넣고 골짜기에 내려오기를 용납하지 아니하였으며'),
    (6384, '○그핫 가족을 위하여 제비를 뽑았는데 레위 사람 중 제사장 아론의 자손들은 유다 지파와 시므온 지파와 베냐민 지파 중에서 제비 뽑은 대로 열세 성읍을 받았고'),
    (6387, '○므라리 자손들은 그 가족대로 르우벤 지파와 갓 지파와 스불론 지파 중에서 열두 성읍을 받았더라'),
    (6388, '○여호와께서 모세에게 명령하신 대로 이스라엘 자손이 제비 뽑아 레위 사람에게 준 성읍들과 그 목초지들이 이러하니라'),
    (6393, '○제사장 아론의 자손에게 준 것은 살인자의 도피성 헤브론과 그 목초지이요 또 립나와 그 목초지와'),
    (6400, '○레위 사람인 그핫 자손 중에 남은 자들의 가족들 곧 그핫 자손에게는 제비 뽑아 에브라임 지파 중에서 그 성읍들을 주었으니'),
    (6402, '깁사임과 그 목초지와 벧호론과 그 목초지이니 네 성읍이요'),
    (6407, '○레위 가족의 게르손 자손에게는 므낫세 반 지파 중에서 살인자의 도피성 바산 골란과 그 목초지를 주었고 또 브에스드라와 그 목초지를 주었으니 두 성읍이요'),
    (6414, '○그 남은 레위 사람 므라리 자손의 가족들에게 준 것은 스불론 지파 중에서 욕느암과 그 목초지와 가르다와 그 목초지와'),
    (6421, '○레위 사람들이 이스라엘 자손의 기업 중에서 받은 성읍은 모두 마흔여덟 성읍이요 또 그 목초지들이라'),
    (6423, '<약속하신 온 땅을 차지하다> ○여호와께서 이스라엘의 조상들에게 맹세하사 주리라 하신 온 땅을 이와 같이 이스라엘에게 다 주셨으므로 그들이 그것을 차지하여 거기에 거주하였으니'),
    (6424, '여호와께서 그들의 주위에 안식을 주셨으되 그 조상들에게 맹세하신 대로 하셨으므로 그들의 모든 원수들 중에 그들과 맞선 자가 하나도 없었으니 이는 여호와께서 그들의 모든 원수들을 그들의 손에 넘겨 주셨음이니라'),
    (6545, '<여호와의 사자가 보김에 나타나다> 여호와의 사자가 길갈에서부터 보김으로 올라와 말하되 내가 너희를 애굽에서 올라오게 하여 내가 너희의 조상들에게 맹세한 땅으로 들어가게 하였으며 또 내가 이르기를 내가 너희와 함께 한 언약을 영원히 어기지 아니하리니'),
    (6550, '<여호수아가 죽다> ○전에 여호수아가 백성을 보내매 이스라엘 자손이 각기 그들의 기업으로 가서 땅을 차지하였고'),
    (6555, '<이스라엘이 여호와를 버리다> ○이스라엘 자손이 여호와의 목전에 악을 행하여 바알들을 섬기며'),
    (6560, '○여호와께서 사사들을 세우사 노략자의 손에서 그들을 구원하게 하셨으나'),
    (6561, '그들이 그 사사들에게도 순종하지 아니하고 오히려 다른 신들을 따라가 음행하며 그들에게 절하고 여호와의 명령을 순종하던 그들의 조상들이 행하던 길에서 속히 치우쳐 떠나서 그와 같이 행하지 아니하였더라'),
    (6562, '여호와께서 그들을 위하여 사사들을 세우실 때에는 그 사사와 함께 하셨고 그 사사가 사는 날 동안에는 여호와께서 그들을 대적의 손에서 구원하셨으니 이는 그들이 대적에게 압박과 괴롭게 함을 받아 슬피 부르짖으므로 여호와께서 뜻을 돌이키셨음이거늘'),
    (6477, '여호수아가 모든 백성에게 이르되 이스라엘의 하나님 여호와께서 이같이 말씀하시기를 옛적에 너희의 조상들 곧 아브라함의 아버지, 나홀의 아버지 데라가 강 저쪽에 거주하여 다른 신들을 섬겼으나'),
    (6482, '너희의 조상들이 나 여호와께 부르짖기로 내가 너희와 애굽 사람들 사이에 흑암을 두고 바다를 이끌어 그들을 덮었나니 내가 애굽에서 행한 일을 너희의 눈이 보았으며 또 너희가 많은 날을 광야에서 거주하였느니라'),
    (6483, '내가 또 너희를 인도하여 요단 저쪽에 거주하는 아모리 족속의 땅으로 들어가게 하매 그들이 너희와 싸우기로 내가 그들을 너희 손에 넘겨 주매 너희가 그 땅을 점령하였고 나는 그들을 너희 앞에서 멸절시켰으며'),
    (6486, '너희가 요단을 건너 여리고에 이른즉 여리고 주민들 곧 아모리 족속과 브리스 족속과 가나안 족속과 헷 족속과 기르가스 족속과 히위 족속과 여부스 족속이 너희와 싸우기로 내가 그들을 너희의 손에 넘겨 주었으며'),
    (6488, '내가 또 너희가 수고하지 아니한 땅과 너희가 건설하지 아니한 성읍들을 너희에게 주었더니 너희가 그 가운데에 거주하며 너희는 또 너희가 심지 아니한 포도원과 감람원의 열매를 먹는다 하셨느니라'),
    (6489, '○그러므로 이제는 여호와를 경외하며 온전함과 진실함으로 그를 섬기라 너희의 조상들이 강 저쪽과 애굽에서 섬기던 신들을 치워 버리고 여호와만 섬기라'),
    (6490, '만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 조상들이 강 저쪽에서 섬기던 신들이든지 또는 너희가 거주하는 땅에 있는 아모리 족속의 신들이든지 너희가 섬길 자를 오늘 택하라 오직 나와 내 집은 여호와를 섬기겠노라 하니'),
    (6492, '이는 우리 하나님 여호와께서 친히 우리와 우리 조상들을 인도하여 애굽 땅 종 되었던 집에서 올라오게 하시고 우리 목전에서 그 큰 이적들을 행하시고 우리가 행한 모든 길과 우리가 지나온 모든 백성들 중에서 우리를 보호하셨음이며'),
    (6494, '○여호수아가 백성에게 이르되 너희가 여호와를 능히 섬기지 못할 것은 그는 거룩하신 하나님이시요 질투하시는 하나님이시니 너희의 잘못과 죄들을 사하지 아니하실 것임이라'),
    (6502, '모든 백성에게 이르되 보라 이 돌이 우리에게 증거가 되리니 이는 여호와께서 우리에게 하신 모든 말씀을 이 돌이 들었음이니라 그런즉 너희가 너희의 하나님을 부인하지 못하도록 이 돌이 증거가 되리라 하고'),
    (6504, '<여호수아와 엘르아살이 죽다> ○이 일 후에 여호와의 종 눈의 아들 여호수아가 백십 세에 죽으매'),
    (6507, '○또 이스라엘 자손이 애굽에서 가져 온 요셉의 뼈를 세겜에 장사하였으니 이곳은 야곱이 백 크시타를 주고 세겜의 아버지 하몰의 자손들에게서 산 밭이라 그것이 요셉 자손의 기업이 되었더라'),
    (6574, '<사사 옷니엘> ○이스라엘 자손이 여호와의 목전에 악을 행하여 자기들의 하나님 여호와를 잊어버리고 바알들과 아세라들을 섬긴지라'),
    (6575, '여호와께서 이스라엘에게 진노하사 그들을 메소보다미아 왕 구산 리사다임의 손에 파셨으므로 이스라엘 자손이 구산 리사다임을 팔 년 동안 섬겼더니'),
    (6577, '여호와의 영이 그에게 임하셨으므로 그가 이스라엘의 사사가 되어 나가서 싸울 때에 여호와께서 메소보다미아 왕 구산 리사다임을 그의 손에 넘겨 주시매 옷니엘의 손이 구산 리사다임을 이기니라'),
    (6579, '<사사 에훗> ○이스라엘 자손이 또 여호와의 목전에 악을 행하니라 이스라엘 자손이 여호와의 목전에 악을 행하므로 여호와께서 모압 왕 에글론을 강성하게 하사 그들을 대적하게 하시매'),
    (6582, '○이스라엘 자손이 여호와께 부르짖으매 여호와께서 그들을 위하여 한 구원자를 세우셨으니 그는 곧 베냐민 사람 게라의 아들 왼손잡이 에훗이라 이스라엘 자손이 그를 통하여 모압 왕 에글론에게 공물을 바칠 때에'),
    (6591, '○에훗이 나간 후에 왕의 신하들이 들어와서 다락문들이 잠겼음을 보고 이르되 왕이 분명히 서늘한 방에서 그의 발을 가리우신다 하고'),
    (6593, '○그들이 기다리는 동안에 에훗이 피하여 돌 뜨는 곳을 지나 스이라로 도망하니라'),
    (6595, '그들에게 이르되 나를 따르라 여호와께서 너희의 원수들인 모압을 너희의 손에 넘겨 주셨느니라 하매 무리가 에훗을 따라 내려가 모압 맞은편 요단 강 나루를 장악하여 한 사람도 건너지 못하게 하였고'),
    (6598, '<사사 삼갈> ○에훗 후에는 아낫의 아들 삼갈이 있어 소 모는 막대기로 블레셋 사람 육백 명을 죽였고 그도 이스라엘을 구원하였더라'),
    (6633, '활 쏘는 자들의 소리로부터 멀리 떨어진 물 긷는 곳에서도 여호와의 공의로우신 일을 전하라 이스라엘에서 마을 사람들을 위한 의로우신 일을 노래하라 그 때에 여호와의 백성이 성문에 내려갔도다'),
    (6636, '에브라임에게서 나온 자들은 아말렉에 뿌리 박힌 자들이요 베냐민은 백성들 중에서 너를 따르는 자들이요 마길에게서는 명령하는 자들이 내려왔고 스불론에게서는 대장군의 지팡이를 잡은 자들이 내려왔도다'),
    (6652, '그들이 어찌 노략물을 얻지 못하였으랴 그것을 나누지 못하였으랴 사람마다 한두 처녀를 얻었으리로다 시스라는 채색 옷을 노략하였으리니 그것은 수 놓은 채색 옷이리로다 곧 양쪽에 수 놓은 채색 옷이리니 노략한 자의 목에 꾸미리로다 하였으리라'),
    (6600, '여호와께서 하솔에서 통치하는 가나안 왕 야빈의 손에 그들을 파셨으니 그의 군대 장관은 하로셋 학고임에 거주하는 시스라요'),
    (6602, '○그 때에 랍비돗의 아내 여선지자 드보라가 이스라엘의 사사가 되었는데'),
    (6604, '드보라가 사람을 보내어 아비노암의 아들 바락을 납달리 게데스에서 불러다가 그에게 이르되 이스라엘의 하나님 여호와께서 이같이 명령하지 아니하셨느냐 너는 납달리 자손과 스불론 자손 만 명을 거느리고 다볼 산으로 가라'),
    (6607, '이르되 내가 반드시 너와 함께 가리라 그러나 네가 이번에 가는 길에서는 영광을 얻지 못하리니 이는 여호와께서 시스라를 여인의 손에 파실 것임이니라 하고 드보라가 일어나 바락과 함께 게데스로 가니라'),
    (6609, '○모세의 장인 호밥의 자손 중 겐 사람 헤벨이 자기 족속을 떠나 게데스에 가까운 사아난님 상수리나무 곁에 이르러 장막을 쳤더라'),
    (6610, '○아비노암의 아들 바락이 다볼 산에 오른 것을 사람들이 시스라에게 알리매'),
    (6612, '드보라가 바락에게 이르되 일어나라 이는 여호와께서 시스라를 네 손에 넘겨 주신 날이라 여호와께서 너에 앞서 나가지 아니하시느냐 하는지라 이에 바락이 만 명을 거느리고 다볼 산에서 내려가니'),
    (6615, '○시스라가 걸어서 도망하여 겐 사람 헤벨의 아내 야엘의 장막에 이르렀으니 이는 하솔 왕 야빈과 겐 사람 헤벨의 집 사이에는 화평이 있음이라'),
    (6620, '바락이 시스라를 추격할 때에 야엘이 나가서 그를 맞아 그에게 이르되 오라 네가 찾는 그 사람을 내가 네게 보이리라 하매 바락이 그에게 들어가 보니 시스라가 엎드러져 죽었고 말뚝이 그의 관자놀이에 박혔더라'),
    (6621, '○이와 같이 이 날에 하나님이 가나안 왕 야빈을 이스라엘 자손 앞에 굴복하게 하신지라'),
    (6695, '○여호와께서 기드온에게 이르시되 너를 따르는 백성이 너무 많은즉 내가 그들의 손에 미디안 사람을 넘겨 주지 아니하리니 이는 이스라엘이 나를 거슬러 스스로 자랑하기를 내 손이 나를 구원하였다 할까 함이니라'),
    (6697, '○여호와께서 또 기드온에게 이르시되 백성이 아직도 많으니 그들을 인도하여 물 가로 내려가라 거기서 내가 너를 위하여 그들을 시험하리라 내가 누구를 가리켜 네게 이르기를 이 사람이 너와 함께 가리라 하면 그는 너와 함께 갈 것이요 내가 누구를 가리켜 네게 이르기를 이 사람은 너와 함께 가지 말 것이니라 하면 그는 가지 말 것이니라 하신지라'),
    (6698, '이에 백성을 인도하여 물 가에 내려가매 여호와께서 기드온에게 이르시되 누구든지 개가 핥는 것 같이 혀로 물을 핥는 자들을 너는 따로 세우고 또 누구든지 무릎을 꿇고 마시는 자들도 그와 같이 하라 하시더니'),
    (6702, '○그 밤에 여호와께서 기드온에게 이르시되 일어나 진영으로 내려가라 내가 그것을 네 손에 넘겨 주었느니라'),
    (6706, '기드온이 그 곳에 이른즉 어떤 사람이 그의 친구에게 꿈을 말하여 이르기를 보라 내가 한 꿈을 꾸었는데 꿈에 보리떡 한 덩어리가 미디안 진영으로 굴러 들어와 한 장막에 이르러 그것을 쳐서 무너뜨려 위쪽으로 엎으니 그 장막이 쓰러지더라'),
    (6708, '○기드온이 그 꿈과 해몽하는 말을 듣고 경배하며 이스라엘 진영으로 돌아와 이르되 일어나라 여호와께서 미디안과 그 모든 진영을 너희 손에 넘겨 주셨느니라 하고'),
    (6712, '○기드온과 그와 함께 한 백 명이 이경 초에 진영 근처에 이른즉 바로 파수꾼들을 교대한 때라 그들이 나팔을 불며 손에 가졌던 항아리를 부수니라'),
    (6717, '○기드온이 사자들을 보내서 에브라임 온 산지로 두루 다니게 하여 이르기를 내려와서 미디안을 치고 그들을 앞질러 벧 바라와 요단 강에 이르는 수로를 점령하라 하매 이에 에브라임 사람들이 다 모여 벧 바라와 요단 강에 이르는 수로를 점령하고'),
    (6718, '또 미디안의 두 방백 오렙과 스엡을 사로잡아 오렙은 오렙 바위에서 죽이고 스엡은 스엡 포도주 틀에서 죽이고 미디안을 추격하였고 오렙과 스엡의 머리를 요단 강 건너편에서 기드온에게 가져왔더라'),
    (6719, '<기드온이 죽인 미디안 왕들> 에브라임 사람들이 기드온에게 이르되 네가 미디안과 싸우러 갈 때에 우리를 부르지 아니하였으니 우리를 이같이 대접함은 어찌 됨이냐 하고 그와 크게 다투는지라'),
    (6722, '○기드온과 그와 함께 한 자 삼백 명이 요단 강에 이르러 건너고 비록 피곤하나 추격하며'),
    (6728, '○이 때에 세바와 살문나가 갈골에 있는데 동방 사람의 모든 군대 중에 칼 든 자 십이만 명이 죽었고 그 남은 만 오천 명 가량은 그들을 따라와서 거기에 있더라'),
    (6731, '○요아스의 아들 기드온이 헤레스 비탈 전장에서 돌아오다가'),
    (6733, '기드온이 숙곳 사람들에게 이르러 말하되 너희가 전에 나를 희롱하여 이르기를 세바와 살문나의 손이 지금 네 손 안에 있다는거냐 어찌 우리가 네 피곤한 사람들에게 떡을 주겠느냐 한 그 세바와 살문나를 보라 하고'),
    (6736, '○이에 그가 세바와 살문나에게 말하되 너희가 다볼에서 죽인 자들은 어떠한 사람들이더냐 하니 대답하되 그들이 너와 같아서 하나 같이 왕자들의 모습과 같더라 하니라'),
    (6739, '세바와 살문나가 이르되 네가 일어나 우리를 치라 사람이 어떠하면 그의 힘도 그러하니라 하니 기드온이 일어나 세바와 살문나를 죽이고 그들의 낙타 목에 있던 초승달 장식들을 떼어서 가지니라'),
    (6740, '○그 때에 이스라엘 사람들이 기드온에게 이르되 당신이 우리를 미디안의 손에서 구원하셨으니 당신과 당신의 아들과 당신의 손자가 우리를 다스리소서 하는지라'),
    (6747, '<기드온이 죽다> ○요아스의 아들 여룹바알이 돌아가서 자기 집에 거주하였는데'),
    (6751, '○기드온이 이미 죽으매 이스라엘 자손이 돌아서서 바알들을 따라가 음행하였으며 또 바알브릿을 자기들의 신으로 삼고'),
    (6660, '○이스라엘 자손이 미디안으로 말미암아 여호와께 부르짖었으므로'),
    (6661, '여호와께서 이스라엘 자손에게 한 선지자를 보내시니 그가 그들에게 이르되 여호와께서 이같이 말씀하시기를 이스라엘의 하나님 내가 너희를 애굽에서 인도하여 내며 너희를 그 종 되었던 집에서 나오게 하여'),
    (6664, '○여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래에 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니'),
    (6666, '기드온이 그에게 대답하되 오 나의 주여 여호와께서 우리와 함께 계시면 어찌하여 이 모든 일이 우리에게 일어났나이까 또 우리 조상들이 일찍이 우리에게 이르기를 여호와께서 우리를 애굽에서 올라오게 하신 것이 아니냐 한 그 모든 이적이 어디 있나이까 이제 여호와께서 우리를 버리사 미디안의 손에 우리를 넘겨 주셨나이다 하니'),
    (6671, '내가 예물을 가지고 다시 주께로 와서 그것을 주 앞에 드리기까지 이 곳을 떠나지 마시기를 원하나이다 하니 그가 이르되 내가 너 돌아올 때까지 머무르리라 하니라'),
    (6672, '○기드온이 가서 염소 새끼 하나를 준비하고 가루 한 에바로 무교병을 만들고 고기를 소쿠리에 담고 국을 양푼에 담아 상수리나무 아래 그에게로 가져다가 드리매'),
    (6678, '○그 날 밤에 여호와께서 기드온에게 이르시되 네 아버지에게 있는 수소 곧 칠 년 된 둘째 수소를 끌어 오고 네 아버지에게 있는 바알의 제단을 헐며 그 곁의 아세라 상을 찍고'),
    (6681, '○그 성읍 사람들이 아침에 일찍이 일어나 본즉 바알의 제단이 파괴되었으며 그 곁의 아세라가 찍혔고 새로 쌓은 제단 위에 그 둘째 수소를 드렸는지라'),
    (6684, '요아스가 자기를 둘러선 모든 자에게 이르되 너희가 바알을 위하여 다투느냐 너희가 바알을 구원하겠느냐 그를 위하여 다투는 자는 아침까지 죽임을 당하리라 바알이 과연 신일진대 그의 제단을 파괴하였은즉 그가 자신을 위해 다툴 것이니라 하니라'),
    (6686, '○그 때에 미디안과 아말렉과 동방 사람들이 다 함께 모여 요단 강을 건너와서 이스르엘 골짜기에 진을 친지라'),
    (6689, '○기드온이 하나님께 여쭈되 주께서 이미 말씀하심 같이 내 손으로 이스라엘을 구원하시려거든'),
    (6692, '기드온이 또 하나님께 여쭈되 주여 내게 노하지 마옵소서 내가 이번만 말하리이다 구하옵나니 내게 이번만 양털로 시험하게 하소서 원하건대 양털만 마르고 그 주변 땅에는 다 이슬이 있게 하옵소서 하였더니'),
    (6755, '청하노니 너희는 세겜의 모든 사람들의 귀에 말하라 여룹바알의 아들 칠십 명이 다 너희를 다스림과 한 사람이 너희를 다스림이 어느 것이 너희에게 나으냐 또 나는 너희와 골육임을 기억하라 하니'),
    (6760, '○사람들이 요담에게 그 일을 알리매 요담이 그리심 산 꼭대기로 가서 서서 그의 목소리를 높여 그들에게 외쳐 이르되 세겜 사람들아 내 말을 들으라 그리하여야 하나님이 너희의 말을 들으시리라'),
    (6768, '가시나무가 나무들에게 이르되 만일 너희가 참으로 내게 기름을 부어 너희 위에 왕으로 삼겠거든 와서 내 그늘에 피하라 그리하지 아니하면 불이 가시나무에서 나와서 레바논의 백향목을 사를 것이니라 하였느니라'),
    (6775, '○아비멜렉이 이스라엘을 다스린 지 삼 년에'),
    (6777, '이는 여룹바알의 아들 칠십 명에게 저지른 포학한 일을 갚되 그들을 죽여 피 흘린 죄를 그들의 형제 아비멜렉과 아비멜렉의 손을 도와 그의 형제들을 죽이게 한 세겜 사람들에게로 돌아가게 하심이라'),
    (6779, '○에벳의 아들 가알이 그의 형제와 더불어 세겜에 이르니 세겜 사람들이 그를 신뢰하니라'),
    (6781, '에벳의 아들 가알이 이르되 아비멜렉은 누구며 세겜은 누구기에 우리가 아비멜렉을 섬기리요 그가 여룹바알의 아들이 아니냐 그의 신복은 스불이 아니냐 차라리 세겜의 아버지 하몰의 후손을 섬길 것이라 우리가 어찌 아비멜렉을 섬기리요'),
    (6783, '○그 성읍의 방백 스불이 에벳의 아들 가알의 말을 듣고 노하여'),
    (6787, '○아비멜렉과 그와 함께 있는 모든 백성이 밤에 일어나 네 떼로 나누어 세겜에 맞서 매복하였더니'),
    (6791, '스불이 그에게 이르되 네가 전에 말하기를 아비멜렉이 누구이기에 우리가 그를 섬기리요 하던 그 입이 이제 어디 있느냐 이들이 네가 업신여기던 그 백성이 아니냐 청하노니 이제 나가서 그들과 싸우라 하니'),
    (6794, '아비멜렉은 아루마에 거주하고 스불은 가알과 그의 형제들을 쫓아내어 세겜에 거주하지 못하게 하더니'),
    (6799, '○세겜 망대의 모든 사람들이 이를 듣고 엘브릿 신전의 보루로 들어갔더니'),
    (6801, '아비멜렉 및 그와 함께 있는 모든 백성이 살몬 산에 오르고 아비멜렉이 손에 도끼를 들고 나뭇가지를 찍어 그것을 들어올려 자기 어깨에 메고 그와 함께 있는 백성에게 이르되 너희는 내가 행하는 것을 보나니 빨리 나와 같이 행하라 하니'),
    (6803, '○아비멜렉이 데베스에 가서 데베스에 맞서 진 치고 그것을 점령하였더니'),
    (6807, '아비멜렉이 자기의 무기를 든 청년을 급히 불러 그에게 이르되 너는 칼을 빼어 나를 죽이라 사람들이 나를 가리켜 이르기를 여자가 그를 죽였다 할까 하노라 하니 그 청년이 그를 찌르매 그가 죽은지라'),
    (6813, '<사사 야일> ○그 후에 길르앗 사람 야일이 일어나서 이십이 년 동안 이스라엘의 사사가 되니라'),
    (6816, '<사사 입다> ○이스라엘 자손이 다시 여호와의 목전에 악을 행하여 바알들과 아스다롯과 아람의 신들과 시돈의 신들과 모압의 신들과 암몬 자손의 신들과 블레셋 사람들의 신들을 섬기고 여호와를 버리고 그를 섬기지 아니하므로'),
    (6820, '○이스라엘 자손이 여호와께 부르짖어 이르되 우리가 우리 하나님을 버리고 바알들을 섬김으로 주께 범죄하였나이다 하니'),
    (6821, '여호와께서 이스라엘 자손에게 이르시되 내가 애굽 사람과 아모리 사람과 암몬 자손과 블레셋 사람에게서 너희를 구원하지 아니하였느냐'),
    (6827, '○그 때에 암몬 자손이 모여서 길르앗에 진을 쳤으므로 이스라엘 자손도 모여서 미스바에 진을 치고'),
    (6869, '<입다와 에브라임 사람들> 에브라임 사람들이 모여 북쪽으로 가서 입다에게 이르되 네가 암몬 자손과 싸우러 건너갈 때에 어찌하여 우리를 불러 너와 함께 가게 하지 아니하였느냐 우리가 반드시 너와 네 집을 불사르리라 하니'),
    (6871, '나는 너희가 도와 주지 아니하는 것을 보고 내 목숨을 돌보지 아니하고 건너가서 암몬 자손을 쳤더니 여호와께서 그들을 내 손에 넘겨 주셨거늘 너희가 어찌하여 오늘 내게 올라와서 나와 더불어 싸우고자 하느냐 하니라'),
    (6872, '입다가 길르앗 사람을 다 모으고 에브라임과 싸웠으며 길르앗 사람들이 에브라임을 쳐서 무찔렀으니 이는 에브라임의 말이 너희 길르앗 사람은 본래 에브라임에서 도망한 자로서 에브라임과 므낫세 중에 있다 하였음이라'),
    (6873, '길르앗 사람이 에브라임 사람보다 앞서 요단 강 나루턱을 장악하고 에브라임 사람의 도망하는 자가 말하기를 청하건대 나를 건너가게 하라 하면 길르앗 사람이 그에게 묻기를 네가 에브라임 사람이냐 하여 그가 만일 아니라 하면'),
    (6874, '그에게 이르기를 쉽볼렛이라 발음하라 하여 에브라임 사람이 그렇게 바로 말하지 못하고 십볼렛이라 발음하면 길르앗 사람이 곧 그를 잡아서 요단 강 나루턱에서 죽였더라 그 때에 에브라임 사람의 죽은 자가 사만 이천 명이었더라'),
    (6875, '○입다가 이스라엘의 사사가 된 지 육 년이라 길르앗 사람 입다가 죽으매 길르앗에 있는 그의 성읍에 장사되었더라'),
    (6876, '<사사 입산> ○그 뒤를 이어 베들레헴의 입산이 이스라엘의 사사가 되었더라'),
    (6879, '○그 뒤를 이어 스불론 사람 엘론이 이스라엘의 사사가 되어 십 년 동안 이스라엘을 다스렸더라'),
    (6881, '<사사 압돈> ○그 뒤를 이어 비라돈 사람 힐렐의 아들 압돈이 이스라엘의 사사가 되었더라'),
    (6832, '○얼마 후에 암몬 자손이 이스라엘을 치려 하니라'),
    (6840, '○입다가 암몬 자손의 왕에게 사자들을 보내 이르되 네가 나와 무슨 상관이 있기에 내 땅을 치러 내게 왔느냐 하니'),
    (6845, '이스라엘이 사자들을 에돔 왕에게 보내어 이르기를 청하건대 나를 네 땅 가운데로 지나게 하라 하였으나 에돔 왕이 이를 듣지 아니하였고 또 그와 같이 사람을 모압 왕에게도 보냈으나 그도 허락하지 아니하므로 이스라엘이 가데스에 머물렀더니'),
    (6857, '○이에 여호와의 영이 입다에게 임하시니 입다가 길르앗과 므낫세를 지나서 길르앗의 미스베에 이르고 길르앗의 미스베에서부터 암몬 자손에게로 나아갈 때에'),
    (6862, '<입다의 딸> ○입다가 미스바에 있는 자기 집에 이를 때에 보라 그의 딸이 소고를 잡고 춤추며 나와서 영접하니 이는 그의 무남독녀라'),
    (6863, '입다가 이를 보고 자기 옷을 찢으며 이르되 어찌할꼬 내 딸이여 너는 나를 참담하게 하는 자요 너는 나를 괴롭게 하는 자 중의 하나로다 내가 여호와를 향하여 입을 열었으니 능히 돌이키지 못하리로다 하니'),
    (6864, '딸이 그에게 이르되 나의 아버지여 아버지께서 여호와를 향하여 입을 여셨으니 아버지의 입에서 낸 말씀대로 내게 행하소서 이는 여호와께서 아버지를 위하여 아버지의 대적 암몬 자손에게 원수를 갚으셨음이니이다 하니라'),
    (6911, '그의 부모가 그에게 이르되 네 형제들의 딸들 중에나 내 백성 중에 어찌 여자가 없어서 네가 할례 받지 아니한 블레셋 사람에게 가서 아내를 맞으려 하느냐 하니 삼손이 그의 아버지에게 이르되 내가 그 여자를 좋아하오니 나를 위하여 그 여자를 데려오소서 하니라'),
    (6913, '○삼손이 그의 부모와 함께 딤나에 내려가 딤나의 포도원에 이른즉 젊은 사자가 그를 보고 소리 지르는지라'),
    (6918, '○삼손의 아버지가 여자에게로 내려가매 삼손이 거기서 잔치를 베풀었으니 청년들은 이렇게 행하는 풍속이 있음이더라'),
    (6923, '○일곱째 날에 이르러 그들이 삼손의 아내에게 이르되 너는 네 남편을 꾀어 그 수수께끼를 우리에게 알려 달라 하라 그렇지 아니하면 너와 네 아버지의 집을 불사르리라 너희가 우리의 소유를 빼앗고자 하여 우리를 청한 것이 아니냐 그렇지 아니하냐 하니'),
    (6924, '삼손의 아내가 그의 앞에서 울며 이르되 당신이 나를 미워할 뿐이요 사랑하지 아니하는도다 우리 민족에게 수수께끼를 말하고 그 뜻을 내게 알려 주지 아니하도다 하는지라 삼손이 그에게 이르되 보라 내가 그것을 나의 부모에게도 알려 주지 아니하였거든 어찌 그대에게 알게 하리요 하였으나'),
    (6926, '일곱째 날 해 지기 전에 성읍 사람들이 삼손에게 이르되 무엇이 꿀보다 달겠으며 무엇이 사자보다 강하겠느냐 한지라 삼손이 그들에게 이르되 너희가 내 암송아지로 밭 갈지 아니하였더라면 내 수수께끼를 능히 풀지 못하였으리라 하니라'),
    (6927, '○여호와의 영이 삼손에게 갑자기 임하시매 삼손이 아스글론에 내려가서 그 곳 사람 삼십 명을 쳐죽이고 노략하여 수수께끼 푼 자들에게 옷을 주고 심히 노하여 그의 아버지의 집으로 올라갔고'),
    (6934, '블레셋 사람들이 이르되 누가 이 일을 행하였느냐 하니 사람들이 대답하되 딤나 사람의 사위 삼손이니 장인이 삼손의 아내를 빼앗아 그의 친구에게 준 까닭이라 하였더라 블레셋 사람들이 올라가서 그 여인과 그의 아버지를 불사르니라'),
    (6937, '<삼손이 블레셋을 치다> ○이에 블레셋 사람들이 올라와 유다에 진을 치고 레히에 가득한지라'),
    (6939, '유다 사람 삼천 명이 에담 바위 틈에 내려가서 삼손에게 이르되 너는 블레셋 사람이 우리를 다스리는 줄을 알지 못하느냐 네가 어찌하여 우리에게 이같이 행하였느냐 하니 삼손이 그들에게 이르되 그들이 내게 행한 대로 나도 그들에게 행하였노라 하니라'),
    (6941, '그들이 삼손에게 말하여 이르되 아니라 우리가 다만 너를 단단히 결박하여 그들의 손에 넘겨 줄 뿐이요 우리가 결단코 너를 죽이지 아니하리라 하고 새 밧줄 둘로 결박하고 바위 틈에서 그를 끌어내니라'),
    (6942, '○삼손이 레히에 이르매 블레셋 사람들이 그에게로 마주 나가며 소리 지를 때 여호와의 영이 삼손에게 갑자기 임하시매 그의 팔 위의 밧줄이 불탄 삼과 같이 그의 결박되었던 손에서 떨어진지라'),
    (6947, '하나님이 레히에서 한 우묵한 곳을 터뜨리시니 거기서 물이 솟아나오는지라 삼손이 그것을 마시고 정신이 회복되어 소생하니 그러므로 그 샘 이름을 엔학고레라 불렀으며 그 샘이 오늘까지 레히에 있더라'),
    (6885, '○소라 땅에 단 지파의 가족 중에 마노아라 이름하는 자가 있더라 그의 아내가 임신하지 못하므로 출산하지 못하더니'),
    (6888, '보라 네가 임신하여 아들을 낳으리니 그의 머리 위에 삭도를 대지 말라 이 아이는 태에서 나옴으로부터 하나님께 바쳐진 나실인이 됨이라 그가 블레셋 사람의 손에서 이스라엘을 구원하기 시작하리라 하시니'),
    (6889, '이에 그 여인이 가서 그의 남편에게 말하여 이르되 하나님의 사람이 내게 오셨는데 그의 모습이 하나님의 사자의 용모 같아서 심히 두려우므로 어디서부터 왔는지를 내가 묻지 못하였고 그도 자기 이름을 내게 이르지 아니하였으며'),
    (6890, '그가 내게 이르기를 보라 네가 임신하여 아들을 낳으리니 이제 포도주와 독주를 마시지 말며 어떤 부정한 것도 먹지 말라 이 아이는 태에서부터 그가 죽는 날까지 하나님께 바쳐진 나실인이 됨이라 하더이다 하니라'),
    (6891, '○마노아가 여호와께 기도하여 이르되 주여 구하옵나니 주께서 보내셨던 하나님의 사람을 우리에게 다시 오게 하사 우리가 그 낳을 아이에게 어떻게 행할지를 우리에게 가르치게 하소서 하니'),
    (6898, '○마노아가 여호와의 사자에게 말하되 구하옵나니 당신은 우리에게 머물러서 우리가 당신을 위하여 염소 새끼 하나를 준비하게 하소서 하니'),
    (6899, '여호와의 사자가 마노아에게 이르되 네가 비록 나를 머물게 하나 내가 네 음식을 먹지 아니하리라 번제를 준비하려거든 마땅히 여호와께 드릴지니라 하니 이는 그가 여호와의 사자인 줄을 마노아가 알지 못함이었더라'),
    (6904, '○여호와의 사자가 마노아와 그의 아내에게 다시 나타나지 아니하니 마노아가 그제야 그가 여호와의 사자인 줄 알고'),
    (6906, '그의 아내가 그에게 이르되 여호와께서 우리를 죽이려 하셨더라면 우리 손에서 번제와 소제를 받지 아니하셨을 것이요 이 모든 일을 보이지 아니하셨을 것이며 이제 이런 말씀도 우리에게 이르지 아니하셨으리이다 하였더라'),
    (6952, '<삼손과 들릴라> ○이 후에 삼손이 소렉 골짜기의 들릴라라 이름하는 여인을 사랑하매'),
    (6953, '블레셋 사람의 방백들이 그 여인에게로 올라가서 그에게 이르되 삼손을 꾀어서 무엇으로 말미암아 그 큰 힘이 생기는지 그리고 우리가 어떻게 하면 능히 그를 결박하여 굴복하게 할 수 있을는지 알아보라 그리하면 우리가 각각 은 천백 개씩을 네게 주리라 하니'),
    (6957, '이미 사람을 방 안에 매복시켰으므로 삼손에게 말하되 삼손이여 블레셋 사람들이 당신에게 들이닥쳤느니라 하니 삼손이 그 줄들을 끊기를 불탄 삼실을 끊음 같이 하였고 그의 힘의 근원은 알아내지 못하니라'),
    (6958, '○들릴라가 삼손에게 이르되 보라 당신이 나를 희롱하여 내게 거짓말을 하였도다 청하건대 무엇으로 당신을 결박할 수 있을는지 이제는 내게 말하라 하니'),
    (6960, '들릴라가 새 밧줄들을 가져다가 그것들로 그를 결박하고 그에게 이르되 삼손이여 블레셋 사람이 당신에게 들이닥쳤느니라 하니 삼손이 팔 위의 줄 끊기를 실을 끊음 같이 하였고 그 때에도 사람이 방 안에 매복하였더라'),
    (6961, '○들릴라가 삼손에게 이르되 당신이 이 때까지 나를 희롱하여 내게 거짓말을 하였도다 내가 무엇으로 당신을 결박할 수 있을는지 내게 말하라 하니 삼손이 그에게 이르되 그대가 만일 나의 머리털 일곱 가닥을 베틀의 날실에 섞어 짜면 되리라 하는지라'),
    (6963, '○들릴라가 삼손에게 이르되 당신의 마음이 내게 있지 아니하면서 당신이 어찌 나를 사랑한다 하느냐 당신이 이로써 세 번이나 나를 희롱하고 당신의 큰 힘이 무엇으로 말미암아 생기는지를 내게 말하지 아니하였도다 하며'),
    (6965, '삼손이 진심을 드러내어 그에게 이르되 내 머리 위에는 삭도를 대지 아니하였나니 이는 내가 모태에서부터 하나님의 나실인이 되었음이라 만일 내 머리가 밀리면 내 힘이 내게서 떠나고 나는 약해져서 다른 사람과 같으리라 하니라'),
    (6966, '○들릴라가 삼손이 진심을 다 알려 주므로 사람을 보내어 블레셋 사람들의 방백들을 불러 이르되 삼손이 내게 진심을 알려 주었으니 이제 한 번만 올라오라 하니 블레셋 방백들이 손에 은을 가지고 그 여인에게로 올라오니라'),
    (6968, '들릴라가 이르되 삼손이여 블레셋 사람이 당신에게 들이닥쳤느니라 하니 삼손이 잠을 깨며 이르기를 내가 전과 같이 나가서 몸을 떨치리라 하였으나 여호와께서 이미 자기를 떠나신 줄을 깨닫지 못하였더라'),
    (6971, '<삼손이 죽다> ○블레셋 사람의 방백들이 이르되 우리의 신이 우리 원수 삼손을 우리 손에 넘겨 주었다 하고 다 모여 그들의 신 다곤에게 큰 제사를 드리고 즐거워하고'),
    (6973, '그들의 마음이 즐거울 때에 이르되 삼손을 불러다가 우리를 위하여 재주를 부리게 하자 하고 옥에서 삼손을 불러내매 삼손이 그들을 위하여 재주를 부리니라 그들이 삼손을 두 기둥 사이에 세웠더니'),
    (6976, '○삼손이 여호와께 부르짖어 이르되 주 여호와여 구하옵나니 나를 생각하옵소서 하나님이여 구하옵나니 이번만 나를 강하게 하사 나의 두 눈을 뺀 블레셋 사람에게 원수를 단번에 갚게 하옵소서 하고'),
    (6978, '삼손이 이르되 블레셋 사람과 함께 죽기를 원하노라 하고 힘을 다하여 몸을 굽히매 그 집이 곧 무너져 그 안에 있는 모든 방백들과 온 백성에게 덮이니 삼손이 죽을 때에 죽인 자가 살았을 때에 죽인 자보다 더욱 많았더라'),
    (6981, '그의 어머니에게 이르되 어머니께서 은 천백을 잃어버리셨으므로 저주하시고 내 귀에도 말씀하셨더니 보소서 그 은이 내게 있나이다 내가 그것을 가졌나이다 하니 그의 어머니가 이르되 내 아들이 여호와께 복 받기를 원하노라 하니라'),
    (6986, '○유다 가족에 속한 유다 베들레헴에 한 청년이 있었으니 그는 레위인으로서 거기서 거류하였더라'),
    (7026, '그의 남편이 그 여자에게 다정하게 말하고 그를 데려오고자 하여 하인 한 사람과 나귀 두 마리를 데리고 그에게로 가매 여자가 그를 인도하여 아버지의 집에 들어가니 그 여자의 아버지가 그를 보고 기뻐하니라'),
    (7032, '그 사람이 첩과 하인과 더불어 일어나 떠나고자 하매 그의 장인 곧 그 여자의 아버지가 그에게 이르되 보라 이제 날이 저물어 가니 청하건대 이 밤도 유숙하라 보라 해가 기울었느니라 그대는 여기서 유숙하여 그대의 마음을 즐겁게 하고 내일 일찍이 그대의 길을 가서 그대의 집으로 돌아가라 하니'),
    (7033, '○그 사람이 다시 밤을 지내고자 하지 아니하여 일어나서 떠나 여부스 맞은편에 이르렀으니 여부스는 곧 예루살렘이라 안장 지운 나귀 두 마리와 첩이 그와 함께 하였더라'),
    (7039, '○저녁 때에 한 노인이 밭에서 일하다가 돌아오니 그 사람은 본래 에브라임 산지 사람으로서 기브아에 거류하는 자요 그 곳 사람들은 베냐민 자손이더라'),
    (7041, '그가 그에게 이르되 우리는 유다 베들레헴에서 에브라임 산지 구석으로 가나이다 나는 그 곳 사람으로서 유다 베들레헴에 갔다가 이제 여호와의 집으로 가는 중인데 나를 자기 집으로 영접하는 사람이 없나이다'),
    (7045, '○그들이 마음을 즐겁게 할 때에 그 성읍의 불량배들이 그 집을 에워싸고 문을 두들기며 집 주인 노인에게 말하여 이르되 네 집에 들어온 사람을 끌어내라 우리가 그와 관계하리라 하니'),
    (7050, '○그의 주인이 일찍이 일어나 집 문을 열고 떠나고자 하더니 그 여인이 집 문에 엎드러져 있고 그의 두 손이 문지방에 있는 것을 보고'),
    (6994, '단 자손이 소라와 에스다올에서부터 그들의 가족 가운데 용맹스런 다섯 사람을 보내어 땅을 정탐하고 살피게 하며 그들에게 이르되 너희는 가서 땅을 살펴보라 하매 그들이 에브라임 산지에 가서 미가의 집에 이르러 거기서 유숙하니라'),
    (6999, '○이에 다섯 사람이 떠나 라이스에 이르러 거기 있는 백성을 본즉 염려 없이 거주하며 시돈 사람들이 사는 것처럼 평온하며 안전하니 그 땅에는 부족한 것이 없으며 부를 누리며 시돈 사람들과 거리가 멀고 어떤 사람과도 상종하지 아니함이라'),
    (7003, '○단 지파의 가족 중 육백 명이 무기를 지니고 소라와 에스다올에서 출발하여'),
    (7006, '○전에 라이스 땅을 정탐하러 갔던 다섯 사람이 그 형제들에게 말하여 이르되 이 집에 에봇과 드라빔과 새긴 신상과 부어 만든 신상이 있는 줄을 너희가 아느냐 그런즉 이제 너희는 마땅히 행할 것을 생각하라 하고'),
    (7011, '그들이 그에게 이르되 잠잠하라 네 손을 입에 대라 우리와 함께 가서 우리의 아버지와 제사장이 되라 네가 한 사람의 집의 제사장이 되는 것과 이스라엘의 한 지파 한 족속의 제사장이 되는 것 중에서 어느 것이 낫겠느냐 하는지라'),
    (7013, '○그들이 돌이켜서 어린 아이들과 가축과 값진 물건들을 앞세우고 길을 떠나더니'),
    (7019, '○단 자손이 미가가 만든 것과 그 제사장을 취하여 라이스에 이르러 한가하고 걱정 없이 사는 백성을 만나 칼날로 그들을 치며 그 성읍을 불사르되'),
    (7132, '<나오미와 룻이 베들레헴으로 오다> ○그 여인이 모압 지방에서 여호와께서 자기 백성을 돌보시사 그들에게 양식을 주셨다 함을 듣고 이에 두 며느리와 함께 일어나 모압 지방에서 돌아오려 하여'),
    (7139, '너희가 어찌 그들이 자라기를 기다리겠으며 어찌 남편 없이 지내겠다고 결심하겠느냐 내 딸들아 그렇지 아니하니라 여호와의 손이 나를 치셨으므로 나는 너희로 말미암아 더욱 마음이 아프도다 하매'),
    (7141, '○나오미가 또 이르되 보라 네 동서는 그의 백성과 그의 신들에게로 돌아가나니 너도 너의 동서를 따라 돌아가라 하니'),
    (7142, '룻이 이르되 내게 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 머무시는 곳에서 나도 머물겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니'),
    (7145, '○이에 그 두 사람이 베들레헴까지 갔더라 베들레헴에 이를 때에 온 성읍이 그들로 말미암아 떠들며 이르기를 이이가 나오미냐 하는지라'),
    (7177, '○그가 타작 마당으로 내려가서 시어머니의 명령대로 다 하니라'),
    (7184, '이 밤에 여기서 머무르라 아침에 그가 기업 무를 자의 책임을 네게 이행하려 하면 좋으니 그가 그 기업 무를 자의 책임을 행할 것이니라 만일 그가 기업 무를 자의 책임을 네게 이행하기를 기뻐하지 아니하면 여호와께서 살아 계심을 두고 맹세하노니 내가 기업 무를 자의 책임을 네게 이행하리라 아침까지 누워 있을지니라 하는지라'),
    (7185, '○룻이 새벽까지 그의 발치에 누웠다가 사람이 서로 알아보기 어려울 때에 일어났으니 보아스가 말하기를 여인이 타작 마당에 들어온 것을 사람이 알지 못하여야 할 것이라 하였음이라'),
    (7156, '○보아스가 룻에게 이르되 내 딸아 들으라 이삭을 주우러 다른 밭으로 가지 말며 여기서 떠나지 말고 나의 소녀들과 함께 있으라'),
    (7162, '○식사할 때에 보아스가 룻에게 이르되 이리로 와서 떡을 먹으며 네 떡 조각을 초에 찍으라 하므로 룻이 곡식 베는 자 곁에 앉으니 그가 볶은 곡식을 주매 룻이 배불리 먹고 남았더라'),
    (7165, '○룻이 밭에서 저녁까지 줍고 그 주운 것을 떠니 보리가 한 에바쯤 되는지라'),
    (7167, '시어머니가 그에게 이르되 오늘 어디서 주웠느냐 어디서 일을 하였느냐 너를 돌본 자에게 복이 있기를 원하노라 하니 룻이 누구에게서 일했는지를 시어머니에게 알게 하여 이르되 오늘 일하게 한 사람의 이름은 보아스니이다 하는지라'),
    (7168, '나오미가 자기 며느리에게 이르되 그가 여호와로부터 복 받기를 원하노라 그가 살아 있는 자와 죽은 자에게 은혜 베풀기를 그치지 아니하도다 하고 나오미가 또 그에게 이르되 그 사람은 우리와 가까우니 우리 기업을 무를 자 중의 하나이니라 하니라'),
    (7106, '이스라엘 자손이 이르되 이스라엘 온 지파 중에 총회와 함께 하여 여호와 앞에 올라오지 아니한 자가 누구냐 하니 이는 그들이 크게 맹세하기를 미스바에 와서 여호와 앞에 이르지 아니하는 자는 반드시 죽일 것이라 하였음이라'),
    (7109, '○또 이르되 이스라엘 지파 중 미스바에 올라와서 여호와께 이르지 아니한 자가 누구냐 하고 본즉 야베스 길르앗에서는 한 사람도 진영에 이르러 총회에 참여하지 아니하였으니'),
    (7114, '○온 회중이 림몬 바위에 있는 베냐민 자손에게 사람을 보내어 평화를 공포하게 하였더니'),
    (7117, '○회중의 장로들이 이르되 베냐민의 여인이 다 멸절되었으니 이제 그 남은 자들에게 어떻게 하여야 아내를 얻게 할까 하고'),
    (7123, '만일 그의 아버지나 형제가 와서 우리에게 시비하면 우리가 그에게 말하기를 청하건대 너희는 우리에게 은혜를 베풀어 그들을 우리에게 줄지니라 이는 우리가 전쟁할 때에 각 사람을 위하여 그의 아내를 얻어 주지 못하였고 너희가 자의로 그들에게 준 것이 아니니 너희에게 죄가 없을 것임이니라 하겠노라 하매'),
    (7126, '○그 때에 이스라엘에 왕이 없으므로 사람이 각기 자기의 소견에 옳은 대로 행하였더라'),
    (7190, '<룻이 보아스와 결혼하다> 보아스가 성문으로 올라가서 거기 앉아 있더니 마침 보아스가 말하던 기업 무를 자가 지나가는지라 보아스가 그에게 이르되 아무개여 이리로 와서 앉으라 하니 그가 와서 앉으매'),
    (7193, '내가 여기 앉은 이들과 내 백성의 장로들 앞에서 그것을 사라고 네게 말하여 알게 하려 하였노라 만일 네가 무르려면 무르려니와 만일 네가 무르지 아니하려거든 내게 고하여 알게 하라 네 다음은 나요 그 외에는 무를 자가 없느니라 하니 그가 이르되 내가 무르리라 하는지라'),
    (7196, '○옛적 이스라엘 중에는 모든 것을 무르거나 교환하는 일을 확정하기 위하여 사람이 그의 신을 벗어 그의 이웃에게 주더니 이것이 이스라엘 중에 증명하는 전례가 된지라'),
    (7199, '또 말론의 아내 모압 여인 룻을 사서 나의 아내로 맞이하고 그 죽은 자의 기업을 그의 이름으로 세워 그의 이름이 그의 형제 중과 그 곳 성문에서 끊어지지 아니하게 함에 너희가 오늘 증인이 되었느니라 하니'),
    (7200, '성문에 있는 모든 백성과 장로들이 이르되 우리가 증인이 되나니 여호와께서 네 집에 들어가는 여인으로 이스라엘의 집을 세운 라헬과 레아 두 사람과 같게 하시고 네가 에브랏에서 유력하고 베들레헴에서 유명하게 하시기를 원하며'),
    (7202, '○이에 보아스가 룻을 맞이하여 아내로 삼고 그에게 들어갔더니 여호와께서 그에게 임신하게 하시므로 그가 아들을 낳은지라'),
    (7207, '○베레스의 계보는 이러하니라 베레스는 헤스론을 낳고'),
    (7061, '○모든 백성이 일제히 일어나 이르되 우리가 한 사람도 자기 장막으로 돌아가지 말며 한 사람도 자기 집으로 들어가지 말고'),
    (7063, '우리가 이스라엘 모든 지파 중에서 백 명에 열 명, 천 명에 백 명, 만 명에 천 명을 뽑아 그 백성을 위하여 양식을 준비하고 그들에게 베냐민의 기브아에 가서 그 무리가 이스라엘 중에서 망령된 일을 행한 대로 징계하게 하리라 하니라'),
    (7065, '○이스라엘 지파들이 베냐민 온 지파에 사람들을 보내어 두루 다니며 이르기를 너희 중에서 생긴 이 악행이 어찌 됨이냐'),
    (7066, '그런즉 이제 기브아 사람들 곧 그 불량배들을 우리에게 넘겨 주어서 우리가 그들을 죽여 이스라엘 중에서 악을 제거하여 버리게 하라 하나 베냐민 자손이 그들의 형제 이스라엘 자손의 말을 듣지 아니하고'),
    (7070, '<이스라엘과 베냐민 자손이 싸우다> ○베냐민 자손 외에 이스라엘 사람으로서 칼을 빼는 자의 수는 사십만 명이니 다 전사라'),
    (7072, '○이스라엘 자손이 아침에 일어나 기브아를 대하여 진을 치니라'),
    (7077, '○그 이튿날에 이스라엘 자손이 베냐민 자손을 치러 나아가매'),
    (7081, '아론의 손자인 엘르아살의 아들 비느하스가 그 앞에 모시고 섰더라 이스라엘 자손들이 여쭈기를 우리가 다시 나아가 내 형제 베냐민 자손과 싸우리이까 말리이까 하니 여호와께서 이르시되 올라가라 내일은 내가 그를 네 손에 넘겨 주리라 하시는지라'),
    (7082, '○이스라엘이 기브아 주위에 군사를 매복하니라'),
    (7084, '베냐민 자손이 나와서 백성을 맞더니 꾀임에 빠져 성읍을 떠났더라 그들이 큰 길 곧 한쪽은 벧엘로 올라가는 길이요 한쪽은 기브아의 들로 가는 길에서 백성을 쳐서 전과 같이 이스라엘 사람 삼십 명 가량을 죽이기 시작하며'),
    (7089, '<이스라엘이 승리한 방법> ○이에 베냐민 자손이 자기가 패한 것을 깨달았으니 이는 이스라엘 사람이 기브아에 매복한 군사를 믿고 잠깐 베냐민 사람 앞을 피하매'),
    (7240, '<한나의 기도> 한나가 기도하여 이르되 내 마음이 여호와로 말미암아 즐거워하며 내 뿔이 여호와로 말미암아 높아졌으며 내 입이 내 원수들을 향하여 크게 열렸으니 이는 내가 주의 구원으로 말미암아 기뻐함이니이다'),
    (7247, '가난한 자를 진토에서 일으키시며 빈궁한 자를 거름더미에서 올리사 귀족들과 함께 앉게 하시며 영광의 자리를 차지하게 하시는도다 땅의 기둥들은 여호와의 것이라 여호와께서 세계를 그것들 위에 세우셨도다'),
    (7249, '여호와를 대적하는 자는 산산이 깨어질 것이라 하늘에서 우레로 그들을 치시리로다 여호와께서 땅 끝까지 심판을 내리시고 자기 왕에게 힘을 주시며 자기의 기름 부음을 받은 자의 뿔을 높이시리로다 하니라'),
    (7251, '<행실이 나쁜 엘리의 아들들> ○엘리의 아들들은 행실이 나빠 여호와를 알지 못하더라'),
    (7257, '<실로에 머문 사무엘> ○사무엘은 어렸을 때에 세마포 에봇을 입고 여호와 앞에서 섬겼더라'),
    (7259, '엘리가 엘가나와 그의 아내에게 축복하여 이르되 여호와께서 이 여인으로 말미암아 네게 다른 후사를 주사 이가 여호와께 간구하여 얻어 바친 아들을 대신하게 하시기를 원하노라 하였더니 그들이 자기 집으로 돌아가매'),
    (7261, '<엘리와 그의 아들들> ○엘리가 매우 늙었더니 그의 아들들이 온 이스라엘에게 행한 모든 일과 회막 문에서 수종 드는 여인들과 동침하였음을 듣고'),
    (7264, '사람이 사람에게 범죄하면 하나님이 심판하시려니와 만일 사람이 여호와께 범죄하면 누가 그를 위하여 간구하겠느냐 하되 그들이 자기 아버지의 말을 듣지 아니하였으니 이는 여호와께서 그들을 죽이기로 뜻하셨음이더라'),
    (7266, '<엘리의 집에 내린 저주> ○하나님의 사람이 엘리에게 와서 그에게 이르되 여호와의 말씀에 너희 조상의 집이 애굽에서 바로의 집에 속하였을 때에 내가 그들에게 나타나지 아니하였느냐'),
    (7267, '이스라엘 모든 지파 중에서 내가 그를 택하여 내 제사장으로 삼아 그가 내 제단에 올라 분향하며 내 앞에서 에봇을 입게 하지 아니하였느냐 이스라엘 자손이 드리는 모든 화제를 내가 네 조상의 집에 주지 아니하였느냐'),
    (7269, '그러므로 이스라엘의 하나님 나 여호와가 말하노라 내가 전에 네 집과 네 조상의 집이 내 앞에 영원히 행하리라 하였으나 이제 나 여호와가 말하노니 결단코 그렇게 하지 아니하리라 나를 존중히 여기는 자를 내가 존중히 여기고 나를 멸시하는 자를 내가 경멸하리라'),
    (7281, '여호와께서 다시 사무엘을 부르시는지라 사무엘이 일어나 엘리에게로 가서 이르되 당신이 나를 부르셨기로 내가 여기 있나이다 하니 그가 대답하되 내 아들아 내가 부르지 아니하였으니 다시 누우라 하니라'),
    (7285, '○여호와께서 임하여 서서 전과 같이 사무엘아 사무엘아 부르시는지라 사무엘이 이르되 말씀하옵소서 주의 종이 듣겠나이다 하니'),
    (7290, '○사무엘이 아침까지 누웠다가 여호와의 집의 문을 열었으나 그 이상을 엘리에게 알게 하기를 두려워하더니'),
    (7294, '○사무엘이 자라매 여호와께서 그와 함께 계셔서 그의 말이 하나도 땅에 떨어지지 않게 하시니'),
    (7220, '<한나와 엘리> ○그들이 실로에서 먹고 마신 후에 한나가 일어나니 그 때에 제사장 엘리는 여호와의 전 문설주 곁 의자에 앉아 있었더라'),
    (7222, '서원하여 이르되 만군의 여호와여 만일 주의 여종의 고통을 돌보시고 나를 기억하사 주의 여종을 잊지 아니하시고 주의 여종에게 아들을 주시면 내가 그의 평생에 그를 여호와께 드리고 삭도를 그의 머리에 대지 아니하겠나이다'),
    (7223, '○그가 여호와 앞에 오래 기도하는 동안에 엘리가 그의 입을 주목한즉'),
    (7230, '<사무엘의 출생과 봉헌> ○그들이 아침에 일찍이 일어나 여호와 앞에 경배하고 돌아가 라마의 자기 집에 이르니라 엘가나가 그의 아내 한나와 동침하매 여호와께서 그를 생각하신지라'),
    (7232, '○그 사람 엘가나와 그의 온 집이 여호와께 매년제와 서원제를 드리러 올라갈 때에'),
    (7234, '그의 남편 엘가나가 그에게 이르되 그대의 소견에 좋은 대로 하여 그를 젖 떼기까지 기다리라 오직 여호와께서 그의 말씀대로 이루시기를 원하노라 하니라 이에 그 여자가 그의 아들을 양육하며 그가 젖 떼기까지 기다리다가'),
    (7297, '<언약궤를 빼앗기다> 사무엘의 말이 온 이스라엘에 전파되니라 ○이스라엘은 나가서 블레셋 사람들과 싸우려고 에벤에셀 곁에 진 치고 블레셋 사람들은 아벡에 진 쳤더니'),
    (7300, '백성이 진영으로 돌아오매 이스라엘 장로들이 이르되 여호와께서 어찌하여 우리에게 오늘 블레셋 사람들 앞에 패하게 하셨는고 여호와의 언약궤를 실로에서 우리에게로 가져다가 우리 중에 있게 하여 그것으로 우리를 우리 원수들의 손에서 구원하게 하자 하니'),
    (7302, '○여호와의 언약궤가 진영에 들어올 때에 온 이스라엘이 큰 소리로 외치매 땅이 울린지라'),
    (7309, '<엘리가 죽다> ○당일에 어떤 베냐민 사람이 진영에서 달려나와 자기의 옷을 찢고 자기의 머리에 티끌을 덮어쓰고 실로에 이르니라'),
    (7314, '소식을 전하는 자가 대답하여 이르되 이스라엘이 블레셋 사람들 앞에서 도망하였고 백성 중에는 큰 살륙이 있었고 당신의 두 아들 홉니와 비느하스도 죽임을 당하였고 하나님의 궤는 빼앗겼나이다'),
    (7316, '<비느하스의 아내가 죽다> ○그의 며느리인 비느하스의 아내가 임신하여 해산 때가 가까웠더니 하나님의 궤를 빼앗긴 것과 그의 시아버지와 남편이 죽은 소식을 듣고 갑자기 아파서 몸을 구푸려 해산하고'),
    (7325, '○여호와의 손이 아스돗 사람에게 엄중히 더하사 독한 종기의 재앙으로 아스돗과 그 지역을 쳐서 망하게 하니'),
    (7327, '이에 사람을 보내어 블레셋 사람들의 모든 방백을 모으고 이르되 우리가 이스라엘 신의 궤를 어찌하랴 하니 그들이 대답하되 이스라엘 신의 궤를 가드로 옮겨 가라 하므로 이스라엘 신의 궤를 옮겨 갔더니'),
    (7329, '이에 그들이 하나님의 궤를 에그론으로 보내니라 하나님의 궤가 에그론에 이른즉 에그론 사람이 부르짖어 이르되 그들이 이스라엘 신의 궤를 우리에게로 가져다가 우리와 우리 백성을 죽이려 한다 하고'),
    (7330, '이에 사람을 보내어 블레셋 모든 방백을 모으고 이르되 이스라엘 신의 궤를 보내어 그 있던 곳으로 돌아가게 하고 우리와 우리 백성이 죽임 당함을 면하게 하자 하니 이는 온 성읍이 사망의 환난을 당함이라 거기서 하나님의 손이 엄중하시므로'),
    (7335, '그들이 이르되 무엇으로 그에게 드릴 속건제를 삼을까 하니 이르되 블레셋 사람의 방백의 수효대로 금 독종 다섯과 금 쥐 다섯 마리라야 하리니 너희와 너희 통치자에게 내린 재앙이 같음이니라'),
    (7337, '애굽인과 바로가 그들의 마음을 완악하게 한 것 같이 어찌하여 너희가 너희의 마음을 완악하게 하겠느냐 그가 그들 중에서 재앙을 내린 후에 그들이 백성을 가게 하므로 백성이 떠나지 아니하였느냐'),
    (7340, '보고 있다가 만일 궤가 그 본 지역 길로 올라가서 벧세메스로 가면 이 큰 재앙은 그가 우리에게 내린 것이요 그렇지 아니하면 우리를 친 것이 그의 손이 아니요 우연히 당한 것인 줄 알리라 하니라'),
    (7341, '○그 사람들이 그같이 하여 젖 나는 소 둘을 끌어다가 수레를 메우고 송아지들은 집에 가두고'),
    (7348, '○블레셋 사람이 여호와께 속건제물로 드린 금 독종은 이러하니 아스돗을 위하여 하나요 가사를 위하여 하나요 아스글론을 위하여 하나요 가드를 위하여 하나요 에그론을 위하여 하나이며'),
    (7349, '드린 바 금 쥐들은 견고한 성읍에서부터 시골의 마을에까지 그리고 사람들이 여호와의 궤를 놓은 큰 돌에 이르기까지 다섯 방백들에게 속한 블레셋 사람들의 모든 성읍들의 수대로였더라 그 돌은 벧세메스 사람 여호수아의 밭에 오늘까지 있더라'),
    (7350, '<언약궤를 기럇여아림으로 보내다> ○벧세메스 사람들이 여호와의 궤를 들여다 본 까닭에 그들을 치사 (오만) 칠십 명을 죽이신지라 여호와께서 백성을 쳐서 크게 살륙하셨으므로 백성이 슬피 울었더라'),
    (7373, '○이스라엘 모든 장로가 모여 라마에 있는 사무엘에게 나아가서'),
    (7379, '○사무엘이 왕을 요구하는 백성에게 여호와의 모든 말씀을 말하여'),
    (7388, '○백성이 사무엘의 말 듣기를 거절하여 이르되 아니로소이다 우리도 우리 왕이 있어야 하리니'),
    (7355, '<사무엘이 이스라엘을 다스리다> ○사무엘이 이스라엘 온 족속에게 말하여 이르되 만일 너희가 전심으로 여호와께 돌아오려거든 이방 신들과 아스다롯을 너희 중에서 제거하고 너희 마음을 여호와께로 향하여 그만을 섬기라 그리하면 너희를 블레셋 사람의 손에서 건져내시리라'),
    (7357, '○사무엘이 이르되 온 이스라엘은 미스바로 모이라 내가 너희를 위하여 여호와께 기도하리라 하매'),
    (7364, '○사무엘이 돌을 취하여 미스바와 센 사이에 세워 이르되 여호와께서 여기까지 우리를 도우셨다 하고 그 이름을 에벤에셀이라 하니라'),
    (7366, '블레셋 사람들이 이스라엘에게서 빼앗았던 성읍이 에그론부터 가드까지 이스라엘에게 회복되니 이스라엘이 그 사방 지역을 블레셋 사람들의 손에서 도로 찾았고 또 이스라엘과 아모리 사람 사이에 평화가 있었더라'),
    (7367, '○사무엘이 사는 날 동안에 이스라엘을 다스렸으되'),
    (7463, '내가 여기 있나니 여호와 앞과 그의 기름 부음을 받은 자 앞에서 내게 대하여 증언하라 내가 누구의 소를 빼앗았느냐 누구의 나귀를 빼앗았느냐 누구를 속였느냐 누구를 압제하였느냐 내 눈을 흐리게 하는 뇌물을 누구의 손에서 받았느냐 그리하였으면 내가 그것을 너희에게 갚으리라 하니'),
    (7465, '사무엘이 백성에게 이르되 너희가 내 손에서 아무것도 찾아낸 것이 없음을 여호와께서 너희에게 대하여 증언하시며 그의 기름 부음을 받은 자도 오늘 증언하느니라 하니 그들이 이르되 그가 증언하시나이다 하니라'),
    (7466, '○사무엘이 백성에게 이르되 모세와 아론을 세우시며 너희 조상들을 애굽 땅에서 인도하여 내신 이는 여호와이시니'),
    (7470, '백성이 여호와께 부르짖어 이르되 우리가 여호와를 버리고 바알들과 아스다롯을 섬김으로 범죄하였나이다 그러하오나 이제 우리를 원수들의 손에서 건져내소서 그리하시면 우리가 주를 섬기겠나이다 하매'),
    (7472, '너희가 암몬 자손의 왕 나하스가 너희를 치러 옴을 보고 너희의 하나님 여호와께서는 너희의 왕이 되심에도 불구하고 너희가 내게 이르기를 아니라 우리를 다스릴 왕이 있어야 하겠다 하였도다'),
    (7479, '○모든 백성이 사무엘에게 이르되 당신의 종들을 위하여 당신의 하나님 여호와께 기도하여 우리가 죽지 않게 하소서 우리가 우리의 모든 죄에 왕을 구하는 악을 더하였나이다'),
    (7451, '○사울이 이 말을 들을 때에 하나님의 영에게 크게 감동되매 그의 노가 크게 일어나'),
    (7452, '한 겨리의 소를 잡아 각을 뜨고 전령들의 손으로 그것을 이스라엘 모든 지역에 두루 보내어 이르되 누구든지 나와서 사울과 사무엘을 따르지 아니하면 그의 소들도 이와 같이 하리라 하였더니 여호와의 두려움이 백성에게 임하매 그들이 한 사람 같이 나온지라'),
    (7454, '무리가 와 있는 전령들에게 이르되 너희는 길르앗 야베스 사람에게 이같이 이르기를 내일 해가 더울 때에 너희가 구원을 받으리라 하라 전령들이 돌아가서 야베스 사람들에게 전하매 그들이 기뻐하니라'),
    (7457, '<사무엘이 길갈에서 사울을 왕으로 세우다> ○백성이 사무엘에게 이르되 사울이 어찌 우리를 다스리겠느냐 한 자가 누구니이까 그들을 끌어내소서 우리가 죽이겠나이다'),
    (7459, '○사무엘이 백성에게 이르되 오라 우리가 길갈로 가서 나라를 새롭게 하자'),
    (7420, '네가 오늘 나를 떠나가다가 베냐민 경계 셀사에 있는 라헬의 묘실 곁에서 두 사람을 만나리니 그들이 네게 이르기를 네가 찾으러 갔던 암나귀들을 찾은지라 네 아버지가 암나귀들의 염려는 놓았으나 너희로 말미암아 걱정하여 이르되 내 아들을 위하여 어찌하리요 하더라 할 것이요'),
    (7421, '네가 거기서 더 나아가서 다볼 상수리나무에 이르면 거기서 하나님을 뵈오려고 벧엘로 올라가는 세 사람을 만나리니 한 사람은 염소 새끼 셋을 이끌었고 한 사람은 떡 세 덩이를 가졌고 한 사람은 포도주 한 가죽부대를 가진 자라'),
    (7423, '그 후에 네가 하나님의 산에 이르리니 그 곳에는 블레셋 사람들의 영문이 있느니라 네가 그리로 가서 그 성읍으로 들어갈 때에 선지자의 무리가 산당에서부터 비파와 소고와 저와 수금을 앞세우고 예언하며 내려오는 것을 만날 것이요'),
    (7427, '○그가 사무엘에게서 떠나려고 몸을 돌이킬 때에 하나님이 새 마음을 주셨고 그 날 그 징조도 다 응하니라'),
    (7432, '○사울의 숙부가 사울과 그의 사환에게 이르되 너희가 어디로 갔더냐 사울이 이르되 암나귀들을 찾다가 찾지 못하므로 사무엘에게 갔었나이다 하니'),
    (7435, '<사울이 왕으로 뽑히다> ○사무엘이 백성을 미스바로 불러 여호와 앞에 모으고'),
    (7436, '이스라엘 자손에게 이르되 이스라엘 하나님 여호와께서 이같이 말씀하시기를 내가 이스라엘을 애굽에서 인도하여 내고 너희를 애굽인의 손과 너희를 압제하는 모든 나라의 손에서 건져내었느니라 하셨거늘'),
    (7437, '너희는 너희를 모든 재난과 고통 중에서 친히 구원하여 내신 너희의 하나님을 오늘 버리고 이르기를 우리 위에 왕을 세우라 하는도다 그런즉 이제 너희의 지파대로 천 명씩 여호와 앞에 나아오라 하고'),
    (7443, '○사무엘이 나라의 제도를 백성에게 말하고 책에 기록하여 여호와 앞에 두고 모든 백성을 각기 집으로 보내매'),
    (7396, '○그들이 숩 땅에 이른 때에 사울이 함께 가던 사환에게 이르되 돌아가자 내 아버지께서 암나귀 생각은 고사하고 우리를 위하여 걱정하실까 두려워하노라 하니'),
    (7402, '○그들이 성읍을 향한 비탈길로 올라가다가 물 길으러 나오는 소녀들을 만나 그들에게 묻되 선견자가 여기 있느냐 하니'),
    (7404, '당신들이 성읍으로 들어가면 그가 먹으러 산당에 올라가기 전에 곧 만나리이다 그가 오기 전에는 백성이 먹지 아니하나니 이는 그가 제물을 축사한 후에야 청함을 받은 자가 먹음이니이다 그러므로 지금 올라가소서 곧 그를 만나리이다 하는지라'),
    (7406, '○사울이 오기 전날에 여호와께서 사무엘에게 알게 하여 이르시되'),
    (7407, '내일 이맘 때에 내가 베냐민 땅에서 한 사람을 네게로 보내리니 너는 그에게 기름을 부어 내 백성 이스라엘의 지도자로 삼으라 그가 내 백성을 블레셋 사람들의 손에서 구원하리라 내 백성의 부르짖음이 내게 상달되었으므로 내가 그들을 돌보았노라 하셨더니'),
    (7412, '사울이 대답하여 이르되 나는 이스라엘 지파의 가장 작은 지파 베냐민 사람이 아니니이까 또 나의 가족은 베냐민 지파 모든 가족 중에 가장 미약하지 아니하니이까 당신이 어찌하여 내게 이같이 말씀하시나이까 하니'),
    (7413, '○사무엘이 사울과 그의 사환을 인도하여 객실로 들어가서 청한 자 중 상석에 앉게 하였는데 객은 삼십 명 가량이었더라'),
    (7415, '요리인이 넓적다리와 그것에 붙은 것을 가져다가 사울 앞에 놓는지라 사무엘이 이르되 보라 이는 두었던 것이니 네 앞에 놓고 먹으라 내가 백성을 청할 때부터 너를 위하여 이것을 두고 이 때를 기다리게 하였느니라 그 날에 사울이 사무엘과 함께 먹으니라'),
    (7416, '<사무엘이 사울에게 기름을 붓다> ○그들이 산당에서 내려 성읍에 들어가서는 사무엘이 사울과 함께 지붕에서 담화하고'),
    (7490, '○블레셋 사람들이 이스라엘과 싸우려고 모였는데 병거가 삼만이요 마병이 육천 명이요 백성은 해변의 모래 같이 많더라 그들이 올라와 벧아웬 동쪽 믹마스에 진 치매'),
    (7493, '○사울은 사무엘이 정한 기한대로 이레 동안을 기다렸으나 사무엘이 길갈로 오지 아니하매 백성이 사울에게서 흩어지는지라'),
    (7498, '사무엘이 사울에게 이르되 왕이 망령되이 행하였도다 왕이 왕의 하나님 여호와께서 왕에게 내리신 명령을 지키지 아니하였도다 그리하였더라면 여호와께서 이스라엘 위에 왕의 나라를 영원히 세우셨을 것이거늘'),
    (7499, '지금은 왕의 나라가 길지 못할 것이라 여호와께서 왕에게 명령하신 바를 왕이 지키지 아니하였으므로 여호와께서 그의 마음에 맞는 사람을 구하여 여호와께서 그를 그의 백성의 지도자로 삼으셨느니라 하고'),
    (7500, '사무엘이 일어나 길갈에서 떠나 베냐민 기브아로 올라가니라 사울이 자기와 함께 한 백성의 수를 세어 보니 육백 명 가량이라'),
    (7505, '○그 때에 이스라엘 온 땅에 철공이 없었으니 이는 블레셋 사람들이 말하기를 히브리 사람이 칼이나 창을 만들까 두렵다 하였음이라'),
    (7512, '아히야는 에봇을 입고 거기 있었으니 그는 이가봇의 형제 아히둡의 아들이요 비느하스의 손자요 실로에서 여호와의 제사장이 되었던 엘리의 증손이었더라 백성은 요나단이 간 줄을 알지 못하니라'),
    (7515, '○요나단이 자기의 무기를 든 소년에게 이르되 우리가 이 할례 받지 않은 자들에게로 건너가자 여호와께서 우리를 위하여 일하실까 하노라 여호와의 구원은 사람이 많고 적음에 달리지 아니하였느니라'),
    (7521, '그 부대 사람들이 요나단과 그의 무기를 든 자에게 이르되 우리에게로 올라오라 너희에게 보여 줄 것이 있느니라 한지라 요나단이 자기의 무기를 든 자에게 이르되 나를 따라 올라오라 여호와께서 그들을 이스라엘의 손에 넘기셨느니라 하고'),
    (7525, '<블레셋 군인들이 칼로 서로를 치다> ○베냐민 기브아에 있는 사울의 파수꾼이 바라본즉 허다한 블레셋 사람들이 무너져 이리 저리 흩어지더라'),
    (7533, '<사울의 맹세와 요나단의 실수> ○이 날에 이스라엘 백성들이 피곤하였으니 이는 사울이 백성에게 맹세시켜 경계하여 이르기를 저녁 곧 내가 내 원수에게 보복하는 때까지 아무 음식물이든지 먹는 사람은 저주를 받을지어다 하였음이라 그러므로 모든 백성이 음식물을 맛보지 못하고'),
    (7537, '그 때에 백성 중 한 사람이 말하여 이르되 당신의 부친이 백성에게 맹세하여 엄히 말씀하시기를 오늘 음식물을 먹는 사람은 저주를 받을지어다 하셨나이다 그러므로 백성이 피곤하였나이다 하니'),
    (7540, '○그 날에 백성이 믹마스에서부터 아얄론에 이르기까지 블레셋 사람들을 쳤으므로 그들이 심히 피곤한지라'),
    (7543, '또 사울이 이르되 너희는 백성 중에 흩어져 다니며 그들에게 이르기를 사람은 각기 소와 양을 이리로 끌어다가 여기서 잡아 먹되 피째로 먹어 여호와께 범죄하지 말라 하라 하매 그 밤에 모든 백성이 각각 자기의 소를 끌어다가 거기서 잡으니라'),
    (7545, '○사울이 이르되 우리가 밤에 블레셋 사람들을 추격하여 동틀 때까지 그들 중에서 탈취하고 한 사람도 남기지 말자 무리가 이르되 왕의 생각에 좋은 대로 하소서 할 때에 제사장이 이르되 이리로 와서 하나님께로 나아가사이다 하매'),
    (7552, '○사울이 요나단에게 이르되 네가 행한 것을 내게 말하라 요나단이 말하여 이르되 내가 다만 내 손에 가진 지팡이 끝으로 꿀을 조금 맛보았을 뿐이오나 내가 죽을 수밖에 없나이다'),
    (7554, '백성이 사울에게 말하되 이스라엘에 이 큰 구원을 이룬 요나단이 죽겠나이까 결단코 그렇지 아니하니이다 여호와의 살아 계심을 두고 맹세하옵나니 그의 머리털 하나도 땅에 떨어지지 아니할 것은 그가 오늘 하나님과 동역하였음이니이다 하여 백성이 요나단을 구원하여 죽지 않게 하니라'),
    (7556, '<사울의 업적과 그 집안> ○사울이 이스라엘 왕위에 오른 후에 사방에 있는 모든 대적 곧 모압과 암몬 자손과 에돔과 소바의 왕들과 블레셋 사람들을 쳤는데 향하는 곳마다 이겼고'),
    (7558, '○사울의 아들은 요나단과 이스위와 말기수아요 그의 두 딸의 이름은 이러하니 맏딸의 이름은 메랍이요 작은 딸의 이름은 미갈이며'),
    (7561, '○사울이 사는 날 동안에 블레셋 사람과 큰 싸움이 있었으므로 사울이 힘 센 사람이나 용감한 사람을 보면 그들을 불러모았더라'),
    (7597, '여호와께서 사무엘에게 이르시되 내가 이미 사울을 버려 이스라엘 왕이 되지 못하게 하였거늘 네가 그를 위하여 언제까지 슬퍼하겠느냐 너는 뿔에 기름을 채워 가지고 가라 내가 너를 베들레헴 사람 이새에게로 보내리니 이는 내가 그의 아들 중에서 한 왕을 보았느니라 하시는지라'),
    (7602, '○그들이 오매 사무엘이 엘리압을 보고 마음에 이르기를 여호와의 기름 부으실 자가 과연 주님 앞에 있도다 하였더니'),
    (7607, '또 사무엘이 이새에게 이르되 네 아들들이 다 여기 있느냐 이새가 이르되 아직 막내가 남았는데 그는 양을 지키나이다 사무엘이 이새에게 이르되 사람을 보내어 그를 데려오라 그가 여기 오기까지는 우리가 식사 자리에 앉지 아니하겠노라'),
    (7610, '<사울을 섬기게 된 다윗> ○여호와의 영이 사울에게서 떠나고 여호와께서 부리시는 악령이 그를 번뇌하게 한지라'),
    (7612, '원하건대 우리 주께서는 당신 앞에서 모시는 신하들에게 명령하여 수금을 잘 타는 사람을 구하게 하소서 하나님께서 부리시는 악령이 왕에게 이를 때에 그가 손으로 타면 왕이 나으시리이다 하는지라'),
    (7712, '그가 자기 생명을 아끼지 아니하고 블레셋 사람을 죽였고 여호와께서는 온 이스라엘을 위하여 큰 구원을 이루셨으므로 왕이 이를 보고 기뻐하셨거늘 어찌 까닭 없이 다윗을 죽여 무죄한 피를 흘려 범죄하려 하시나이까'),
    (7715, '○전쟁이 다시 있으므로 다윗이 나가서 블레셋 사람들과 싸워 그들을 크게 쳐죽이매 그들이 그 앞에서 도망하니라'),
    (7718, '사울이 전령들을 다윗의 집에 보내어 그를 지키다가 아침에 그를 죽이게 하려 한지라 다윗의 아내 미갈이 다윗에게 말하여 이르되 당신이 이 밤에 당신의 생명을 구하지 아니하면 내일에는 죽임을 당하리라 하고'),
    (7724, '사울이 미갈에게 이르되 너는 어찌하여 이처럼 나를 속여 내 대적을 놓아 피하게 하였느냐 미갈이 사울에게 대답하되 그가 내게 이르기를 나를 놓아 가게 하라 어찌하여 나로 너를 죽이게 하겠느냐 하더이다 하니라'),
    (7725, '○다윗이 도피하여 라마로 가서 사무엘에게로 나아가서 사울이 자기에게 행한 일을 다 전하였고 다윗과 사무엘이 나욧으로 가서 살았더라'),
    (7565, '○사울이 백성을 소집하고 그들을 들라임에서 세어 보니 보병이 이십만 명이요 유다 사람이 만 명이라'),
    (7567, '사울이 겐 사람에게 이르되 아말렉 사람 중에서 떠나 가라 그들과 함께 너희를 멸하게 될까 하노라 이스라엘 모든 자손이 애굽에서 올라올 때에 너희가 그들을 선대하였느니라 이에 겐 사람이 아말렉 사람 중에서 떠나니라'),
    (7571, '<여호와께서 사울을 버리시다> ○여호와의 말씀이 사무엘에게 임하니라 이르시되'),
    (7576, '사울이 이르되 그것은 무리가 아말렉 사람에게서 끌어 온 것인데 백성이 당신의 하나님 여호와께 제사하려 하여 양들과 소들 중에서 가장 좋은 것을 남김이요 그 외의 것은 우리가 진멸하였나이다 하는지라'),
    (7578, '○사무엘이 이르되 왕이 스스로 작게 여길 그 때에 이스라엘 지파의 머리가 되지 아니하셨나이까 여호와께서 왕에게 기름을 부어 이스라엘 왕을 삼으시고'),
    (7585, '○사울이 사무엘에게 이르되 내가 범죄하였나이다 내가 여호와의 명령과 당신의 말씀을 어긴 것은 내가 백성을 두려워하여 그들의 말을 청종하였음이니이다'),
    (7593, '<사무엘이 아각을 처형하다> ○사무엘이 이르되 너희는 아말렉 사람의 왕 아각을 내게로 끌어 오라 하였더니 아각이 즐거이 오며 이르되 진실로 사망의 괴로움이 지났도다 하니라'),
    (7595, '<사무엘이 다윗에게 기름을 붓다> ○이에 사무엘은 라마로 가고 사울은 사울 기브아 자기의 집으로 올라가니라'),
    (7733, '요나단이 그에게 이르되 결단코 아니라 네가 죽지 아니하리라 내 아버지께서 크고 작은 일을 내게 알리지 아니하고는 행하지 아니하나니 내 아버지께서 어찌하여 이 일은 내게 숨기리요 그렇지 아니하니라'),
    (7734, '다윗이 또 맹세하여 이르되 내가 네게 은혜 받은 줄을 네 아버지께서 밝히 알고 스스로 이르기를 요나단이 슬퍼할까 두려운즉 그에게 이것을 알리지 아니하리라 함이니라 그러나 진실로 여호와의 살아 계심과 네 생명을 두고 맹세하노니 나와 죽음의 사이는 한 걸음 뿐이니라'),
    (7737, '네 아버지께서 만일 나에 대하여 자세히 묻거든 그 때에 너는 말하기를 다윗이 자기 성읍 베들레헴으로 급히 가기를 내게 허락하라 간청하였사오니 이는 온 가족을 위하여 거기서 매년제를 드릴 때가 됨이니이다 하라'),
    (7739, '그런즉 바라건대 네 종에게 인자하게 행하라 네가 네 종에게 여호와 앞에서 너와 맹약하게 하였음이니라 그러나 내게 죄악이 있으면 네가 친히 나를 죽이라 나를 네 아버지에게로 데려갈 이유가 무엇이냐 하니라'),
    (7743, '○요나단이 다윗에게 이르되 이스라엘의 하나님 여호와께서 증언하시거니와 내가 내일이나 모레 이맘때에 내 아버지를 살펴서 너 다윗에게 대한 의향이 선하면 내가 사람을 보내어 네게 알리지 않겠느냐'),
    (7744, '그러나 만일 내 아버지께서 너를 해치려 하는데도 내가 이 일을 네게 알려 주어 너를 보내어 평안히 가게 하지 아니하면 여호와께서 나 요나단에게 벌을 내리시고 또 내리시기를 원하노라 여호와께서 내 아버지와 함께 하신 것 같이 너와 함께 하시기를 원하노니'),
    (7748, '○다윗에 대한 요나단의 사랑이 그를 다시 맹세하게 하였으니 이는 자기 생명을 사랑함 같이 그를 사랑함이었더라'),
    (7752, '아이를 보내어 가서 화살을 찾으라 하며 내가 짐짓 아이에게 이르기를 보라 화살이 네 이쪽에 있으니 가져오라 하거든 너는 돌아올지니 여호와께서 살아 계심을 두고 맹세하노니 네가 평안 무사할 것이요'),
    (7755, '○다윗이 들에 숨으니라 초하루가 되매 왕이 앉아 음식을 먹을 때에'),
    (7760, '이르되 원하건대 나에게 가게 하라 우리 가족이 그 성읍에서 제사할 일이 있으므로 나의 형이 내게 오기를 명령하였으니 내가 네게 사랑을 받거든 내가 가서 내 형들을 보게 하라 하였으므로 그가 왕의 식사 자리에 오지 아니하였나이다 하니'),
    (7761, '○사울이 요나단에게 화를 내며 그에게 이르되 패역무도한 계집의 소생아 네가 이새의 아들을 택한 것이 네 수치와 네 어미의 벌거벗은 수치 됨을 내가 어찌 알지 못하랴'),
    (7766, '○아침에 요나단이 작은 아이를 데리고 다윗과 정한 시간에 들로 나가서'),
    (7773, '요나단이 다윗에게 이르되 평안히 가라 우리 두 사람이 여호와의 이름으로 맹세하여 이르기를 여호와께서 영원히 나와 너 사이에 계시고 내 자손과 네 자손 사이에 계시리라 하였느니라 하니 다윗은 일어나 떠나고 요나단은 성읍으로 들어가니라'),
    (7683, '<사울이 불쾌하여 다윗을 주목하다> ○무리가 돌아올 때 곧 다윗이 블레셋 사람을 죽이고 돌아올 때에 여인들이 이스라엘 모든 성읍에서 나와서 노래하며 춤추며 소고와 경쇠를 가지고 왕 사울을 환영하는데'),
    (7687, '○그 이튿날 하나님께서 부리시는 악령이 사울에게 힘 있게 내리매 그가 집 안에서 정신 없이 떠들어대므로 다윗이 평일과 같이 손으로 수금을 타는데 그 때에 사울의 손에 창이 있는지라'),
    (7694, '<다윗이 사울의 사위가 되다> ○사울이 다윗에게 이르되 내 맏딸 메랍을 네게 아내로 주리니 오직 너는 나를 위하여 용기를 내어 여호와의 싸움을 싸우라 하니 이는 그가 생각하기를 내 손을 그에게 대지 않고 블레셋 사람들의 손을 그에게 대게 하리라 함이라'),
    (7699, '○사울이 그의 신하들에게 명령하되 너희는 다윗에게 비밀히 말하여 이르기를 보라 왕이 너를 기뻐하시고 모든 신하도 너를 사랑하나니 그런즉 네가 왕의 사위가 되는 것이 가하니라 하라'),
    (7702, '사울이 이르되 너희는 다윗에게 이같이 말하기를 왕이 아무 것도 원하지 아니하고 다만 왕의 원수의 보복으로 블레셋 사람들의 포피 백 개를 원하신다 하라 하였으니 이는 사울의 생각에 다윗을 블레셋 사람들의 손에 죽게 하리라 함이라'),
    (7707, '○블레셋 사람들의 방백들이 싸우러 나오면 그들이 나올 때마다 다윗이 사울의 모든 신하보다 더 지혜롭게 행하매 이에 그의 이름이 심히 귀하게 되니라'),
    (7775, '다윗이 제사장 아히멜렉에게 이르되 왕이 내게 일을 명령하고 이르시기를 내가 너를 보내는 것과 네게 명령한 일은 아무것도 사람에게 알리지 말라 하시기로 내가 나의 소년들을 이러이러한 곳으로 오라고 말하였나이다'),
    (7778, '다윗이 제사장에게 대답하여 이르되 우리가 참으로 삼 일 동안이나 여자를 가까이 하지 아니하였나이다 내가 떠난 길이 보통 여행이라도 소년들의 그릇이 성결하겠거든 하물며 오늘 그들의 그릇이 성결하지 아니하겠나이까 하매'),
    (7780, '○그 날에 사울의 신하 한 사람이 여호와 앞에 머물러 있었는데 그는 도엑이라 이름하는 에돔 사람이요 사울의 목자장이었더라'),
    (7782, '제사장이 이르되 네가 엘라 골짜기에서 죽인 블레셋 사람 골리앗의 칼이 보자기에 싸여 에봇 뒤에 있으니 네가 그것을 가지려거든 가지라 여기는 그것밖에 다른 것이 없느니라 하는지라 다윗이 이르되 그같은 것이 또 없나니 내게 주소서 하더라'),
    (7783, '○그 날에 다윗이 사울을 두려워하여 일어나 도망하여 가드 왕 아기스에게로 가니'),
    (7784, '아기스의 신하들이 아기스에게 말하되 이는 그 땅의 왕 다윗이 아니니이까 무리가 춤추며 이 사람의 일을 노래하여 이르되 사울이 죽인 자는 천천이요 다윗은 만만이로다 하지 아니하였나이까 한지라'),
    (7627, '그가 서서 이스라엘 군대를 향하여 외쳐 이르되 너희가 어찌하여 나와서 전열을 벌였느냐 나는 블레셋 사람이 아니며 너희는 사울의 신복이 아니냐 너희는 한 사람을 택하여 내게로 내려보내라'),
    (7631, '<사울의 진영에 나타난 다윗> ○다윗은 유다 베들레헴 에브랏 사람 이새라 하는 사람의 아들이었는데 이새는 사울 당시 사람 중에 나이가 많아 늙은 사람으로서 여덟 아들이 있는 중'),
    (7636, '○이새가 그의 아들 다윗에게 이르되 지금 네 형들을 위하여 이 볶은 곡식 한 에바와 이 떡 열 덩이를 가지고 진영으로 속히 가서 네 형들에게 주고'),
    (7644, '이스라엘 사람들이 이르되 너희가 이 올라 온 사람을 보았느냐 참으로 이스라엘을 모욕하러 왔도다 그를 죽이는 사람은 왕이 많은 재물로 부하게 하고 그의 딸을 그에게 주고 그 아버지의 집을 이스라엘 중에서 세금을 면제하게 하시리라'),
    (7645, '다윗이 곁에 서 있는 사람들에게 말하여 이르되 이 블레셋 사람을 죽여 이스라엘의 치욕을 제거하는 사람에게는 어떠한 대우를 하겠느냐 이 할례 받지 않은 블레셋 사람이 누구이기에 살아 계시는 하나님의 군대를 모욕하겠느냐'),
    (7647, '○큰형 엘리압이 다윗이 사람들에게 하는 말을 들은지라 그가 다윗에게 노를 발하여 이르되 네가 어찌하여 이리로 내려왔느냐 들에 있는 양들을 누구에게 맡겼느냐 나는 네 교만과 네 마음의 완악함을 아노니 네가 전쟁을 구경하러 왔도다'),
    (7650, '○어떤 사람이 다윗이 한 말을 듣고 그것을 사울에게 전하였으므로 사울이 다윗을 부른지라'),
    (7651, '다윗이 사울에게 말하되 그로 말미암아 사람이 낙담하지 말 것이라 주의 종이 가서 저 블레셋 사람과 싸우리이다 하니'),
    (7656, '또 다윗이 이르되 여호와께서 나를 사자의 발톱과 곰의 발톱에서 건져내셨은즉 나를 이 블레셋 사람의 손에서도 건져내시리이다 사울이 다윗에게 이르되 가라 여호와께서 너와 함께 계시기를 원하노라'),
    (7660, '<다윗이 골리앗을 이기다> ○블레셋 사람이 방패 든 사람을 앞세우고 다윗에게로 점점 가까이 나아가니라'),
    (7669, '○다윗이 이같이 물매와 돌로 블레셋 사람을 이기고 그를 쳐죽였으나 자기 손에는 칼이 없었더라'),
    (7671, '이스라엘과 유다 사람들이 일어나서 소리 지르며 블레셋 사람들을 쫓아 가이와 에그론 성문까지 이르렀고 블레셋 사람들의 부상자들은 사아라임 가는 길에서부터 가드와 에그론까지 엎드러졌더라'),
    (7674, '<다윗이 사울 앞에 서다> ○사울은 다윗이 블레셋 사람을 향하여 나아감을 보고 군사령관 아브넬에게 묻되 아브넬아 이 소년이 누구의 아들이냐 아브넬이 이르되 왕이여 왕의 사심으로 맹세하옵나니 내가 알지 못하나이다 하매'),
    (7791, '○다윗이 거기서 모압 미스베로 가서 모압 왕에게 이르되 하나님이 나를 위하여 어떻게 하실지를 내가 알기까지 나의 부모가 나와서 당신들과 함께 있게 하기를 청하나이다 하고'),
    (7794, '○사울이 다윗과 그와 함께 있는 사람들이 나타났다 함을 들으니라 그 때에 사울이 기브아 높은 곳에서 손에 단창을 들고 에셀 나무 아래에 앉았고 모든 신하들은 그의 곁에 섰더니'),
    (7796, '너희가 다 공모하여 나를 대적하며 내 아들이 이새의 아들과 맹약하였으되 내게 고발하는 자가 하나도 없고 나를 위하여 슬퍼하거나 내 아들이 내 신하를 선동하여 오늘이라도 매복하였다가 나를 치려 하는 것을 내게 알리는 자가 하나도 없도다 하니'),
    (7799, '○왕이 사람을 보내어 아히둡의 아들 제사장 아히멜렉과 그의 아버지의 온 집 곧 놉에 있는 제사장들을 부르매 그들이 다 왕께 이른지라'),
    (7801, '사울이 그에게 이르되 네가 어찌하여 이새의 아들과 공모하여 나를 대적하여 그에게 떡과 칼을 주고 그를 위하여 하나님께 물어서 그에게 오늘이라도 매복하였다가 나를 치게 하려 하였느냐 하니'),
    (7803, '내가 그를 위하여 하나님께 물은 것이 오늘이 처음이니이까 결단코 아니니이다 원하건대 왕은 종과 종의 아비의 온 집에 아무것도 돌리지 마옵소서 왕의 종은 이 모든 크고 작은 일에 관하여 아는 것이 없나이다 하니라'),
    (7805, '왕이 좌우의 호위병에게 이르되 돌아가서 여호와의 제사장들을 죽이라 그들도 다윗과 합력하였고 또 그들이 다윗이 도망한 것을 알고도 내게 알리지 아니하였음이니라 하나 왕의 신하들이 손을 들어 여호와의 제사장들 죽이기를 싫어한지라'),
    (7808, '○아히둡의 아들 아히멜렉의 아들 중 하나가 피하였으니 그의 이름은 아비아달이라 그가 도망하여 다윗에게로 가서'),
    (7844, '다윗의 사람들이 이르되 보소서 여호와께서 당신에게 이르시기를 내가 원수를 네 손에 넘기리니 네 생각에 좋은 대로 그에게 행하라 하시더니 이것이 그 날이니이다 하니 다윗이 일어나서 사울의 겉옷 자락을 가만히 베니라'),
    (7848, '○그 후에 다윗도 일어나 굴에서 나가 사울의 뒤에서 외쳐 이르되 내 주 왕이여 하매 사울이 돌아보는지라 다윗이 땅에 엎드려 절하고'),
    (7850, '오늘 여호와께서 굴에서 왕을 내 손에 넘기신 것을 왕이 아셨을 것이니이다 어떤 사람이 나를 권하여 왕을 죽이라 하였으나 내가 왕을 아껴 말하기를 나는 내 손을 들어 내 주를 해하지 아니하리니 그는 여호와의 기름 부음을 받은 자이기 때문이라 하였나이다'),
    (7851, '내 아버지여 보소서 내 손에 있는 왕의 옷자락을 보소서 내가 왕을 죽이지 아니하고 겉옷 자락만 베었은즉 내 손에 악이나 죄과가 없는 줄을 오늘 아실지니이다 왕은 내 생명을 찾아 해하려 하시나 나는 왕에게 범죄한 일이 없나이다'),
    (7856, '○다윗이 사울에게 이같이 말하기를 마치매 사울이 이르되 내 아들 다윗아 이것이 네 목소리냐 하고 소리를 높여 울며'),
    (7932, '<다윗이 블레셋 땅으로 피하다> 다윗이 그 마음에 생각하기를 내가 후일에는 사울의 손에 붙잡히리니 블레셋 사람들의 땅으로 피하여 들어가는 것이 좋으리로다 사울이 이스라엘 온 영토 내에서 다시 나를 찾다가 단념하리니 내가 그의 손에서 벗어나리라 하고'),
    (7936, '○다윗이 아기스에게 이르되 바라건대 내가 당신께 은혜를 입었다면 지방 성읍 가운데 한 곳을 내게 주어 내가 살게 하소서 당신의 종이 어찌 당신과 함께 왕도에 살리이까 하니'),
    (7939, '○다윗과 그의 사람들이 올라가서 그술 사람과 기르스 사람과 아말렉 사람을 침노하였으니 그들은 옛적부터 술과 애굽 땅으로 지나가는 지방의 주민이라'),
    (7942, '다윗이 그 남녀를 살려서 가드로 데려가지 아니한 것은 그의 생각에 그들이 우리에게 대하여 이르기를 다윗이 행한 일이 이러하니라 하여 블레셋 사람들의 지방에 거주하는 동안에 이같이 행하는 습관이 있었다 할까 두려워함이었더라'),
    (7817, '○아히멜렉의 아들 아비아달이 그일라 다윗에게로 도망할 때에 손에 에봇을 가지고 내려왔더라'),
    (7822, '그일라 사람들이 나를 그의 손에 넘기겠나이까 주의 종이 들은 대로 사울이 내려 오겠나이까 이스라엘의 하나님 여호와여 원하건대 주의 종에게 일러 주옵소서 하니 여호와께서 이르시되 그가 내려오리라 하신지라'),
    (7826, '<다윗이 엔게디 요새로 피하다> ○다윗이 사울이 자기의 생명을 빼앗으려고 나온 것을 보았으므로 그가 십 광야 수풀에 있었더니'),
    (7830, '○그 때에 십 사람들이 기브아에 이르러 사울에게 나아와 이르되 다윗이 우리와 함께 광야 남쪽 하길라 산 수풀 요새에 숨지 아니하였나이까'),
    (7835, '○그들이 일어나 사울보다 먼저 십으로 가니라 다윗과 그의 사람들이 광야 남쪽 마온 광야 아라바에 있더니'),
    (7837, '사울이 산 이쪽으로 가매 다윗과 그의 사람들은 산 저쪽으로 가며 다윗이 사울을 두려워하여 급히 피하려 하였으니 이는 사울과 그의 사람들이 다윗과 그의 사람들을 에워싸고 잡으려 함이었더라'),
    (7912, '○이에 다윗이 헷 사람 아히멜렉과 스루야의 아들 요압의 아우 아비새에게 물어 이르되 누가 나와 더불어 진영에 내려가서 사울에게 이르겠느냐 하니 아비새가 이르되 내가 함께 가겠나이다'),
    (7914, '아비새가 다윗에게 이르되 하나님이 오늘 당신의 원수를 당신의 손에 넘기셨나이다 그러므로 청하오니 내가 창으로 그를 찔러서 단번에 땅에 꽂게 하소서 내가 그를 두 번 찌를 것이 없으리이다 하니'),
    (7918, '다윗이 사울의 머리 곁에서 창과 물병을 가지고 떠나가되 아무도 보거나 눈치 채지 못하고 깨어 있는 사람도 없었으니 이는 여호와께서 그들을 깊이 잠들게 하셨으므로 그들이 다 잠들어 있었기 때문이었더라'),
    (7919, '○이에 다윗이 건너편으로 가서 멀리 산 꼭대기에 서니 거리가 멀더라'),
    (7921, '다윗이 아브넬에게 이르되 네가 용사가 아니냐 이스라엘 가운데에 너 같은 자가 누구냐 그러한데 네가 어찌하여 네 주 왕을 보호하지 아니하느냐 백성 가운데 한 사람이 네 주 왕을 죽이려고 들어갔었느니라'),
    (7922, '네가 행한 이 일이 옳지 못하도다 여호와께서 살아 계심을 두고 맹세하노니 여호와의 기름 부음 받은 너희 주를 보호하지 아니하였으니 너희는 마땅히 죽을 자이니라 이제 왕의 창과 왕의 머리 곁에 있던 물병이 어디 있나 보라 하니'),
    (7923, '○사울이 다윗의 음성을 알아 듣고 이르되 내 아들 다윗아 이것이 네 음성이냐 하는지라 다윗이 이르되 내 주 왕이여 내 음성이니이다 하고'),
    (7925, '원하건대 내 주 왕은 이제 종의 말을 들으소서 만일 왕을 충동시켜 나를 해하려 하는 이가 여호와시면 여호와께서는 제물을 받으시기를 원하나이다마는 만일 사람들이면 그들이 여호와 앞에 저주를 받으리니 이는 그들이 이르기를 너는 가서 다른 신들을 섬기라 하고 오늘 나를 쫓아내어 여호와의 기업에 참여하지 못하게 함이니이다'),
    (7927, '○사울이 이르되 내가 범죄하였도다 내 아들 다윗아 돌아오라 네가 오늘 내 생명을 귀하게 여겼은즉 내가 다시는 너를 해하려 하지 아니하리라 내가 어리석은 일을 하였으니 대단히 잘못되었도다 하는지라'),
    (7864, '<다윗과 아비가일> ○마온에 한 사람이 있는데 그의 생업이 갈멜에 있고 심히 부하여 양이 삼천 마리요 염소가 천 마리이므로 그가 갈멜에서 그의 양 털을 깎고 있었으니'),
    (7871, '○다윗의 소년들이 가서 다윗의 이름으로 이 모든 말을 나발에게 말하기를 마치매'),
    (7876, '○하인들 가운데 하나가 나발의 아내 아비가일에게 말하여 이르되 다윗이 우리 주인에게 문안하러 광야에서 전령들을 보냈거늘 주인이 그들을 모욕하였나이다'),
    (7880, '○아비가일이 급히 떡 이백 덩이와 포도주 두 가죽 부대와 잡아서 요리한 양 다섯 마리와 볶은 곡식 다섯 세아와 건포도 백 송이와 무화과 뭉치 이백 개를 가져다가 나귀들에게 싣고'),
    (7882, '아비가일이 나귀를 타고 산 호젓한 곳을 따라 내려가더니 다윗과 그의 사람들이 자기에게로 마주 내려오는 것을 만나니라'),
    (7885, '○아비가일이 다윗을 보고 급히 나귀에서 내려 다윗 앞에 엎드려 그의 얼굴을 땅에 대니라'),
    (7888, '내 주여 여호와께서 살아 계심을 두고 맹세하노니 내 주도 살아 계시거니와 내 주의 손으로 피를 흘려 친히 보복하시는 일을 여호와께서 막으셨으니 내 주의 원수들과 내 주를 해하려 하는 자들은 나발과 같이 되기를 원하나이다'),
    (7890, '주의 여종의 허물을 용서하여 주옵소서 여호와께서 반드시 내 주를 위하여 든든한 집을 세우시리니 이는 내 주께서 여호와의 싸움을 싸우심이요 내 주의 일생에 내 주에게서 악한 일을 찾을 수 없음이니이다'),
    (7891, '사람이 일어나서 내 주를 쫓아 내 주의 생명을 찾을지라도 내 주의 생명은 내 주의 하나님 여호와와 함께 생명 싸개 속에 싸였을 것이요 내 주의 원수들의 생명은 물매로 던지듯 여호와께서 그것을 던지시리이다'),
    (7893, '내 주께서 무죄한 피를 흘리셨다든지 내 주께서 친히 보복하셨다든지 함으로 말미암아 슬퍼하실 것도 없고 내 주의 마음에 걸리는 것도 없으시리니 다만 여호와께서 내 주를 후대하실 때에 원하건대 내 주의 여종을 생각하소서 하니라'),
    (7894, '○다윗이 아비가일에게 이르되 오늘 너를 보내어 나를 영접하게 하신 이스라엘의 하나님 여호와를 찬송할지로다'),
    (7896, '나를 막아 너를 해하지 않게 하신 이스라엘의 하나님 여호와의 살아 계심을 두고 맹세하노니 네가 급히 와서 나를 영접하지 아니하였더면 밝는 아침에는 과연 나발에게 한 남자도 남겨 두지 아니하였으리라 하니라'),
    (7898, '○아비가일이 나발에게로 돌아오니 그가 왕의 잔치와 같은 잔치를 그의 집에 배설하고 크게 취하여 마음에 기뻐하므로 아비가일이 밝는 아침까지는 아무 말도 하지 아니하다가'),
    (7901, '○나발이 죽었다 함을 다윗이 듣고 이르되 나발에게 당한 나의 모욕을 갚아 주사 종으로 악한 일을 하지 않게 하신 여호와를 찬송할지로다 여호와께서 나발의 악행을 그의 머리에 돌리셨도다 하니라 다윗이 아비가일을 자기 아내로 삼으려고 사람을 보내어 그에게 말하게 하매'),
    (7905, '○다윗이 또 이스르엘 아히노암을 아내로 맞았더니 그들 두 사람이 그의 아내가 되니라'),
    (7971, '블레셋 사람들의 방백들이 이르되 이 히브리 사람들이 무엇을 하려느냐 하니 아기스가 블레셋 사람들의 방백들에게 이르되 이는 이스라엘 왕 사울의 신하 다윗이 아니냐 그가 나와 함께 있은 지 여러 날 여러 해로되 그가 망명하여 온 날부터 오늘까지 내가 그의 허물을 보지 못하였노라'),
    (7972, '블레셋 사람의 방백들이 그에게 노한지라 블레셋 방백들이 그에게 이르되 이 사람을 돌려보내어 왕이 그에게 정하신 그 처소로 가게 하소서 그는 우리와 함께 싸움에 내려가지 못하리니 그가 전장에서 우리의 대적이 될까 하나이다 그가 무엇으로 그 주와 다시 화합하리이까 이 사람들의 머리로 하지 아니하겠나이까'),
    (7974, '○아기스가 다윗을 불러 그에게 이르되 여호와께서 살아 계심을 두고 맹세하노니 네가 정직하여 내게 온 날부터 오늘까지 네게 악이 있음을 보지 못하였으니 나와 함께 진중에 출입하는 것이 내 생각에는 좋으나 수령들이 너를 좋아하지 아니하니'),
    (7946, '<사울이 신접한 여인을 찾다> ○사무엘이 죽었으므로 온 이스라엘이 그를 두고 슬피 울며 그의 고향 라마에 장사하였고 사울은 신접한 자와 박수를 그 땅에서 쫓아내었더라'),
    (7951, '○사울이 다른 옷을 입어 변장하고 두 사람과 함께 갈새 그들이 밤에 그 여인에게 이르러서는 사울이 이르되 청하노니 나를 위하여 신접한 술법으로 내가 네게 말하는 사람을 불러 올리라 하니'),
    (7958, '○사무엘이 사울에게 이르되 네가 어찌하여 나를 불러 올려서 나를 성가시게 하느냐 하니 사울이 대답하되 나는 심히 다급하니이다 블레셋 사람들은 나를 향하여 군대를 일으켰고 하나님은 나를 떠나서 다시는 선지자로도, 꿈으로도 내게 대답하지 아니하시기로 내가 행할 일을 알아보려고 당신을 불러 올렸나이다 하더라'),
    (7963, '○사울이 갑자기 땅에 완전히 엎드러지니 이는 사무엘의 말로 말미암아 심히 두려워함이요 또 그의 기력이 다하였으니 이는 그가 하루 밤낮을 음식을 먹지 못하였음이니라'),
    (8011, '<사울과 요나단이 죽다> 블레셋 사람들이 이스라엘을 치매 이스라엘 사람들이 블레셋 사람들 앞에서 도망하여 길보아 산에서 엎드러져 죽으니라'),
    (8014, '그가 무기를 든 자에게 이르되 네 칼을 빼어 그것으로 나를 찌르라 할례 받지 않은 자들이 와서 나를 찌르고 모욕할까 두려워하노라 하나 무기를 든 자가 심히 두려워하여 감히 행하지 아니하는지라 이에 사울이 자기의 칼을 뽑아서 그 위에 엎드러지매'),
    (8017, '○골짜기 저쪽에 있는 이스라엘 사람과 요단 건너쪽에 있는 자들이 이스라엘 사람들이 도망한 것과 사울과 그의 아들들이 죽었음을 보고 성읍들을 버리고 도망하매 블레셋 사람들이 이르러 거기에서 사니라'),
    (7986, '○다윗이 아히멜렉의 아들 제사장 아비아달에게 이르되 원하건대 에봇을 내게로 가져오라 아비아달이 에봇을 다윗에게로 가져가매'),
    (7990, '○무리가 들에서 애굽 사람 하나를 만나 그를 다윗에게로 데려다가 떡을 주어 먹게 하며 물을 마시게 하고'),
    (7994, '다윗이 그에게 이르되 네가 나를 그 군대로 인도하겠느냐 하니 그가 이르되 당신이 나를 죽이지도 아니하고 내 주인의 수중에 넘기지도 아니하겠다고 하나님의 이름으로 내게 맹세하소서 그리하면 내가 당신을 그 군대로 인도하리이다 하니라'),
    (7995, '○그가 다윗을 인도하여 내려가니 그들이 온 땅에 편만하여 블레셋 사람들의 땅과 유다 땅에서 크게 약탈하였음으로 말미암아 먹고 마시며 춤추는지라'),
    (8000, '○다윗이 전에 피곤하여 능히 자기를 따르지 못하므로 브솔 시내에 머물게 한 이백 명에게 오매 그들이 다윗과 그와 함께 한 백성을 영접하러 나오는지라 다윗이 그 백성에게 이르러 문안하매'),
    (8001, '다윗과 함께 갔던 자들 가운데 악한 자와 불량배들이 다 이르되 그들이 우리와 함께 가지 아니하였은즉 우리가 도로 찾은 물건은 무엇이든지 그들에게 주지 말고 각자의 처자만 데리고 떠나가게 하라 하는지라'),
    (8005, '○다윗이 시글락에 이르러 전리품을 그의 친구 유다 장로들에게 보내어 이르되 보라 여호와의 원수에게서 탈취한 것을 너희에게 선사하노라 하고'),
    (8027, '다윗이 그에게 이르되 일이 어떻게 되었느냐 너는 내게 말하라 그가 대답하되 군사가 전쟁 중에 도망하기도 하였고 무리 가운데에 엎드러져 죽은 자도 많았고 사울과 그의 아들 요나단도 죽었나이다 하는지라'),
    (8034, '○이에 다윗이 자기 옷을 잡아 찢으매 함께 있는 모든 사람도 그리하고'),
    (8040, '<사울과 요나단을 위한 다윗의 조가> ○다윗이 이 슬픈 노래로 사울과 그의 아들 요나단을 조상하고'),
    (8051, '<다윗이 유다의 왕이 되다> 그 후에 다윗이 여호와께 여쭈어 아뢰되 내가 유다 한 성읍으로 올라가리이까 여호와께서 이르시되 올라가라 다윗이 아뢰되 어디로 가리이까 이르시되 헤브론으로 갈지니라'),
    (8054, '유다 사람들이 와서 거기서 다윗에게 기름을 부어 유다 족속의 왕으로 삼았더라 ○어떤 사람이 다윗에게 말하여 이르되 사울을 장사한 사람은 길르앗 야베스 사람들이니이다 하매'),
    (8059, '<이스보셋이 이스라엘의 왕이 되다> ○사울의 군사령관 넬의 아들 아브넬이 이미 사울의 아들 이스보셋을 데리고 마하나임으로 건너가'),
    (8063, '<이스라엘과 유다의 전쟁> ○넬의 아들 아브넬과 사울의 아들 이스보셋의 신복들은 마하나임에서 나와 기브온에 이르고'),
    (8069, '○그 곳에 스루야의 세 아들 요압과 아비새와 아사헬이 있었는데 아사헬의 발은 들노루 같이 빠르더라'),
    (8075, '○요압과 아비새가 아브넬의 뒤를 쫓아 기브온 거친 땅의 길 가 기아 맞은쪽 암마 산에 이를 때에 해가 졌고'),
    (8081, '○요압이 아브넬 쫓기를 그치고 돌아와 무리를 다 모으니 다윗의 신복 중에 열아홉 명과 아사헬이 없어졌으나'),
    (8124, '사울의 아들 이스보셋에게 군지휘관 두 사람이 있으니 한 사람의 이름은 바아나요 한 사람의 이름은 레갑이라 베냐민 족속 브에롯 사람 림몬의 아들들이더라 브에롯도 베냐민 지파에 속하였으니'),
    (8126, '○사울의 아들 요나단에게 다리 저는 아들 하나가 있었으니 이름은 므비보셋이라 전에 사울과 요나단이 죽은 소식이 이스르엘에서 올 때에 그의 나이가 다섯 살이었는데 그 유모가 안고 도망할 때 급히 도망하다가 아이가 떨어져 절게 되었더라'),
    (8127, '○브에롯 사람 림몬의 아들 레갑과 바아나가 길을 떠나 볕이 쬘 때 즈음에 이스보셋의 집에 이르니 마침 그가 침상에서 낮잠을 자는지라'),
    (8130, '헤브론에 이르러 다윗 왕에게 이스보셋의 머리를 드리며 아뢰되 왕의 생명을 해하려 하던 원수 사울의 아들 이스보셋의 머리가 여기 있나이다 여호와께서 오늘 우리 주 되신 왕의 원수를 사울과 그의 자손에게 갚으셨나이다 하니'),
    (8085, '<다윗의 아들들> ○다윗이 헤브론에서 아들들을 낳았으되 맏아들은 암논이라 이스르엘 여인 아히노암의 소생이요'),
    (8089, '<아브넬이 이스보셋을 배반하다> ○사울의 집과 다윗의 집 사이에 전쟁이 있는 동안에 아브넬이 사울의 집에서 점점 권세를 잡으니라'),
    (8091, '아브넬이 이스보셋의 말을 매우 분하게 여겨 이르되 내가 유다의 개 머리냐 내가 오늘 당신의 아버지 사울의 집과 그의 형제와 그의 친구에게 은혜를 베풀어 당신을 다윗의 손에 내주지 아니하였거늘 당신이 오늘 이 여인에게 관한 허물을 내게 돌리는도다'),
    (8095, '○아브넬이 자기를 대신하여 전령들을 다윗에게 보내어 이르되 이 땅이 누구의 것이니이까 또 이르되 당신은 나와 더불어 언약을 맺사이다 내 손이 당신을 도와 온 이스라엘이 당신에게 돌아가게 하리이다 하니'),
    (8100, '○아브넬이 이스라엘 장로들에게 말하여 이르되 너희가 여러 번 다윗을 너희의 임금으로 세우기를 구하였으니'),
    (8101, '이제 그대로 하라 여호와께서 이미 다윗에 대하여 말씀하시기를 내가 내 종 다윗의 손으로 내 백성 이스라엘을 구원하여 블레셋 사람의 손과 모든 대적의 손에서 벗어나게 하리라 하셨음이니라 하고'),
    (8104, '아브넬이 다윗에게 말하되 내가 일어나 가서 온 이스라엘 무리를 내 주 왕의 앞에 모아 더불어 언약을 맺게 하고 마음에 원하시는 대로 모든 것을 다스리시게 하리이다 하니 이에 다윗이 아브넬을 보내매 그가 평안히 가니라'),
    (8105, '<아브넬이 살해되다> ○다윗의 신복들과 요압이 적군을 치고 크게 노략한 물건을 가지고 돌아오니 아브넬은 이미 보냄을 받아 평안히 갔고 다윗과 함께 헤브론에 있지 아니한 때라'),
    (8110, '○아브넬이 헤브론으로 돌아오매 요압이 더불어 조용히 말하려는 듯이 그를 데리고 성문 안으로 들어가 거기서 배를 찔러 죽이니 이는 자기의 동생 아사헬의 피로 말미암음이더라'),
    (8112, '그 죄가 요압의 머리와 그의 아버지의 온 집으로 돌아갈지어다 또 요압의 집에서 백탁병자나 나병 환자나 지팡이를 의지하는 자나 칼에 죽는 자나 양식이 떨어진 자가 끊어지지 아니할지로다 하니라'),
    (8114, '<아브넬을 장사하다> ○다윗이 요압과 및 자기와 함께 있는 모든 백성에게 이르되 너희는 옷을 찢고 굵은 베를 띠고 아브넬 앞에서 애도하라 하니라 다윗 왕이 상여를 따라가'),
    (8160, '<하나님의 궤를 다윗 성으로 옮기다> 다윗이 이스라엘에서 뽑은 무리 삼만 명을 다시 모으고'),
    (8165, '○그들이 나곤의 타작 마당에 이르러서는 소들이 뛰므로 웃사가 손을 들어 하나님의 궤를 붙들었더니'),
    (8171, '○어떤 사람이 다윗 왕에게 아뢰어 이르되 여호와께서 하나님의 궤로 말미암아 오벧에돔의 집과 그의 모든 소유에 복을 주셨다 한지라 다윗이 가서 하나님의 궤를 기쁨으로 메고 오벧에돔의 집에서 다윗 성으로 올라갈새'),
    (8175, '○여호와의 궤가 다윗 성으로 들어올 때에 사울의 딸 미갈이 창으로 내다보다가 다윗 왕이 여호와 앞에서 뛰놀며 춤추는 것을 보고 심중에 그를 업신여기니라'),
    (8179, '○다윗이 자기의 가족에게 축복하러 돌아오매 사울의 딸 미갈이 나와서 다윗을 맞으며 이르되 이스라엘 왕이 오늘 어떻게 영화로우신지 방탕한 자가 염치 없이 자기의 몸을 드러내는 것처럼 오늘 그의 신복의 계집종의 눈앞에서 몸을 드러내셨도다 하니'),
    (8180, '다윗이 미갈에게 이르되 이는 여호와 앞에서 한 것이니라 그가 네 아버지와 그의 온 집을 버리시고 나를 택하사 나를 여호와의 백성 이스라엘의 주권자로 삼으셨으니 내가 여호와 앞에서 뛰놀리라'),
    (8135, '<다윗이 온 이스라엘의 왕이 되다> 이스라엘 모든 지파가 헤브론에 이르러 다윗에게 나아와 이르되 보소서 우리는 왕의 한 골육이니이다'),
    (8136, '전에 곧 사울이 우리의 왕이 되었을 때에도 이스라엘을 거느려 출입하게 하신 분은 왕이시었고 여호와께서도 왕에게 말씀하시기를 네가 내 백성 이스라엘의 목자가 되며 네가 이스라엘의 주권자가 되리라 하셨나이다 하니라'),
    (8138, '○다윗이 나이가 삼십 세에 왕위에 올라 사십 년 동안 다스렸으되'),
    (8140, '<다윗이 시온을 빼앗아 성을 둘러 쌓다> ○왕과 그의 부하들이 예루살렘으로 가서 그 땅 주민 여부스 사람을 치려 하매 그 사람들이 다윗에게 이르되 네가 결코 이리로 들어오지 못하리라 맹인과 다리 저는 자라도 너를 물리치리라 하니 그들 생각에는 다윗이 이리로 들어오지 못하리라 함이나'),
    (8142, '그 날에 다윗이 이르기를 누구든지 여부스 사람을 치거든 물 긷는 데로 올라가서 다윗의 마음에 미워하는 다리 저는 사람과 맹인을 치라 하였으므로 속담이 되어 이르기를 맹인과 다리 저는 사람은 집에 들어오지 못하리라 하더라'),
    (8145, '○두로 왕 히람이 다윗에게 사절들과 백향목과 목수와 석수를 보내매 그들이 다윗을 위하여 집을 지으니'),
    (8147, '<다윗의 아들과 딸들> ○다윗이 헤브론에서 올라온 후에 예루살렘에서 처첩들을 더 두었으므로 아들과 딸들이 또 다윗에게서 나니'),
    (8151, '<다윗이 블레셋을 쳐서 이기다> ○이스라엘이 다윗에게 기름을 부어 이스라엘 왕으로 삼았다 함을 블레셋 사람들이 듣고 블레셋 사람들이 다윗을 찾으러 다 올라오매 다윗이 듣고 요새로 나가니라'),
    (8153, '다윗이 여호와께 여쭈어 이르되 내가 블레셋 사람에게로 올라가리이까 여호와께서 그들을 내 손에 넘기시겠나이까 하니 여호와께서 다윗에게 말씀하시되 올라가라 내가 반드시 블레셋 사람을 네 손에 넘기리라 하신지라'),
    (8156, '○블레셋 사람들이 다시 올라와서 르바임 골짜기에 가득한지라'),
    (8243, '<다윗이 암몬과 싸우다> 그 후에 암몬 자손의 왕이 죽고 그의 아들 하눈이 대신하여 왕이 되니'),
    (8244, '다윗이 이르되 내가 나하스의 아들 하눈에게 은총을 베풀되 그의 아버지가 내게 은총을 베푼 것 같이 하리라 하고 다윗이 그의 신하들을 보내 그의 아버지를 조상하라 하니라 다윗의 신하들이 암몬 자손의 땅에 이르매'),
    (8245, '암몬 자손의 관리들이 그들의 주 하눈에게 말하되 왕은 다윗이 조객을 당신에게 보낸 것이 왕의 아버지를 공경함인 줄로 여기시나이까 다윗이 그의 신하들을 당신에게 보내 이 성을 엿보고 탐지하여 함락시키고자 함이 아니니이까 하니'),
    (8248, '○암몬 자손들이 자기들이 다윗에게 미움이 된 줄 알고 암몬 자손들이 사람을 보내 벧르홉 아람 사람과 소바 아람 사람의 보병 이만 명과 마아가 왕과 그의 사람 천 명과 돕 사람 만 이천 명을 고용한지라'),
    (8251, '○요압이 자기와 맞서 앞뒤에 친 적진을 보고 이스라엘의 선발한 자 중에서 또 엄선하여 아람 사람과 싸우려고 진 치고'),
    (8257, '○아람 사람이 자기가 이스라엘 앞에서 패하였음을 보고 다 모이매'),
    (8212, '<다윗이 어디로 가든지 이기다> 그 후에 다윗이 블레셋 사람들을 쳐서 항복을 받고 블레셋 사람들의 손에서 메덱암마를 빼앗으니라'),
    (8213, '○다윗이 또 모압을 쳐서 그들로 땅에 엎드리게 하고 줄로 재어 그 두 줄 길이의 사람은 죽이고 한 줄 길이의 사람은 살리니 모압 사람들이 다윗의 종들이 되어 조공을 드리니라'),
    (8214, '○르홉의 아들 소바 왕 하닷에셀이 자기 권세를 회복하려고 유브라데 강으로 갈 때에 다윗이 그를 쳐서'),
    (8220, '○하맛 왕 도이가 다윗이 하닷에셀의 온 군대를 쳐서 무찔렀다 함을 듣고'),
    (8221, '도이가 그의 아들 요람을 보내 다윗 왕에게 문안하고 축복하게 하니 이는 하닷에셀이 도이와 더불어 전쟁이 있던 터에 다윗이 하닷에셀을 쳐서 무찌름이라 요람이 은 그릇과 금 그릇과 놋 그릇을 가지고 온지라'),
    (8224, '○다윗이 소금 골짜기에서 에돔 사람 만 팔천 명을 쳐죽이고 돌아와서 명성을 떨치니라'),
    (8226, '○다윗이 온 이스라엘을 다스려 다윗이 모든 백성에게 정의와 공의를 행할새'),
    (8236, '다윗이 그에게 이르되 무서워하지 말라 내가 반드시 네 아버지 요나단으로 말미암아 네게 은총을 베풀리라 내가 네 할아버지 사울의 모든 밭을 다 네게 도로 주겠고 또 너는 항상 내 상에서 떡을 먹을지니라 하니'),
    (8238, '○왕이 사울의 시종 시바를 불러 그에게 이르되 사울과 그의 온 집에 속한 것은 내가 다 네 주인의 아들에게 주었노니'),
    (8239, '너와 네 아들들과 네 종들은 그를 위하여 땅을 갈고 거두어 네 주인의 아들에게 양식을 대주어 먹게 하라 그러나 네 주인의 아들 므비보셋은 항상 내 상에서 떡을 먹으리라 하니라 시바는 아들이 열다섯 명이요 종이 스무 명이라'),
    (8183, '<나단이 계시대로 다윗에게 말하다> 여호와께서 주위의 모든 원수를 무찌르사 왕으로 궁에 평안히 살게 하신 때에'),
    (8189, '이스라엘 자손과 더불어 다니는 모든 곳에서 내가 내 백성 이스라엘을 먹이라고 명령한 이스라엘 어느 지파들 가운데 하나에게 내가 말하기를 너희가 어찌하여 나를 위하여 백향목 집을 건축하지 아니하였느냐고 말하였느냐'),
    (8190, '그러므로 이제 내 종 다윗에게 이와 같이 말하라 만군의 여호와께서 이와 같이 말씀하시기를 내가 너를 목장 곧 양을 따르는 데에서 데려다가 내 백성 이스라엘의 주권자로 삼고'),
    (8193, '전에 내가 사사에게 명령하여 내 백성 이스라엘을 다스리던 때와 같지 아니하게 하고 너를 모든 원수에게서 벗어나 편히 쉬게 하리라 여호와가 또 네게 이르노니 여호와가 너를 위하여 집을 짓고'),
    (8200, '<다윗의 기도> ○다윗 왕이 여호와 앞에 들어가 앉아서 이르되 주 여호와여 나는 누구이오며 내 집은 무엇이기에 나를 여기까지 이르게 하셨나이까'),
    (8205, '땅의 어느 한 나라가 주의 백성 이스라엘과 같으리이까 하나님이 가서 구속하사 자기 백성으로 삼아 주의 명성을 내시며 그들을 위하여 큰 일을, 주의 땅을 위하여 두려운 일을 애굽과 많은 나라들과 그의 신들에게서 구속하신 백성 앞에서 행하셨사오며'),
    (8207, '여호와 하나님이여 이제 주의 종과 종의 집에 대하여 말씀하신 것을 영원히 세우시며 말씀하신 대로 행하사'),
    (8262, '<다윗과 밧세바> 그 해가 돌아와 왕들이 출전할 때가 되매 다윗이 요압과 그에게 있는 그의 부하들과 온 이스라엘 군대를 보내니 그들이 암몬 자손을 멸하고 랍바를 에워쌌고 다윗은 예루살렘에 그대로 있더라'),
    (8263, '○저녁 때에 다윗이 그의 침상에서 일어나 왕궁 옥상에서 거닐다가 그 곳에서 보니 한 여인이 목욕을 하는데 심히 아름다워 보이는지라'),
    (8267, '○다윗이 요압에게 기별하여 헷 사람 우리아를 내게 보내라 하매 요압이 우리아를 다윗에게로 보내니'),
    (8272, '우리아가 다윗에게 아뢰되 언약궤와 이스라엘과 유다가 야영 중에 있고 내 주 요압과 내 왕의 부하들이 바깥 들에 진 치고 있거늘 내가 어찌 내 집으로 가서 먹고 마시고 내 처와 같이 자리이까 내가 이 일을 행하지 아니하기로 왕의 살아 계심과 왕의 혼의 살아 계심을 두고 맹세하나이다 하니라'),
    (8275, '○아침이 되매 다윗이 편지를 써서 우리아의 손에 들려 요압에게 보내니'),
    (8282, '여룹베셋의 아들 아비멜렉을 쳐죽인 자가 누구냐 여인 하나가 성에서 맷돌 위짝을 그 위에 던지매 그가 데벳스에서 죽지 아니하였느냐 어찌하여 성에 가까이 갔더냐 하시거든 네가 말하기를 왕의 종 헷 사람 우리아도 죽었나이다 하라'),
    (8283, '○전령이 가서 다윗에게 이르러 요압이 그를 보낸 모든 일을 다윗에게 아뢰어'),
    (8286, '다윗이 전령에게 이르되 너는 요압에게 이같이 말하기를 이 일로 걱정하지 말라 칼은 이 사람이나 저 사람이나 삼키느니라 그 성을 향하여 더욱 힘써 싸워 함락시키라 하여 너는 그를 담대하게 하라 하니라'),
    (8287, '○우리아의 아내는 그 남편 우리아가 죽었음을 듣고 그의 남편을 위하여 소리내어 우니라'),
    (8291, '가난한 사람은 아무것도 없고 자기가 사서 기르는 작은 암양 새끼 한 마리뿐이라 그 암양 새끼는 그와 그의 자식과 함께 자라며 그가 먹는 것을 먹으며 그의 잔으로 마시며 그의 품에 누우므로 그에게는 딸처럼 되었거늘'),
    (8295, '○나단이 다윗에게 이르되 당신이 그 사람이라 이스라엘의 하나님 여호와께서 이와 같이 이르시기를 내가 너를 이스라엘 왕으로 기름 붓기 위하여 너를 사울의 손에서 구원하고'),
    (8303, '<다윗의 아이가 죽다> 나단이 자기 집으로 돌아가니라 ○우리아의 아내가 다윗에게 낳은 아이를 여호와께서 치시매 심히 앓는지라'),
    (8307, '이레 만에 그 아이가 죽으니라 그러나 다윗의 신하들이 아이가 죽은 것을 왕에게 아뢰기를 두려워하니 이는 그들이 말하기를 아이가 살았을 때에 우리가 그에게 말하여도 왕이 그 말을 듣지 아니하셨나니 어떻게 그 아이가 죽은 것을 그에게 아뢸 수 있으랴 왕이 상심하시리로다 함이라'),
    (8313, '<솔로몬이 태어나다> ○다윗이 그의 아내 밧세바를 위로하고 그에게 들어가 그와 동침하였더니 그가 아들을 낳으매 그의 이름을 솔로몬이라 하니라 여호와께서 그를 사랑하사'),
    (8315, '<다윗이 랍바를 쳐서 점령하다> ○요압이 암몬 자손의 랍바를 쳐서 그 왕성을 점령하매'),
    (8322, '그는 처녀이므로 어찌할 수 없는 줄을 알고 암논이 그의 누이 다말 때문에 울화로 말미암아 병이 되니라'),
    (8325, '요나답이 그에게 이르되 침상에 누워 병든 체하다가 네 아버지가 너를 보러 오거든 너는 그에게 말하기를 원하건대 내 누이 다말이 와서 내게 떡을 먹이되 내가 보는 데에서 떡을 차려 그의 손으로 먹여 주게 하옵소서 하라 하니'),
    (8327, '○다윗이 사람을 그의 집으로 보내 다말에게 이르되 이제 네 오라버니 암논의 집으로 가서 그를 위하여 음식을 차리라 한지라'),
    (8335, '○그리하고 암논이 그를 심히 미워하니 이제 미워하는 미움이 전에 사랑하던 사랑보다 더한지라 암논이 그에게 이르되 일어나 가라 하니'),
    (8340, '○그의 오라버니 압살롬이 그에게 이르되 네 오라버니 암논이 너와 함께 있었느냐 그러나 그는 네 오라버니이니 누이야 지금은 잠잠히 있고 이것으로 말미암아 근심하지 말라 하니라 이에 다말이 그의 오라버니 압살롬의 집에 있어 처량하게 지내니라'),
    (8343, '<압살롬의 복수> ○만 이 년 후에 에브라임 곁 바알하솔에서 압살롬이 양 털을 깎는 일이 있으매 압살롬이 왕의 모든 아들을 청하고'),
    (8348, '압살롬이 이미 그의 종들에게 명령하여 이르기를 너희는 이제 암논의 마음이 술로 즐거워할 때를 자세히 보다가 내가 너희에게 암논을 치라 하거든 그를 죽이라 두려워하지 말라 내가 너희에게 명령한 것이 아니냐 너희는 담대히 용기를 내라 한지라'),
    (8350, '○그들이 길에 있을 때에 압살롬이 왕의 모든 아들들을 죽이고 하나도 남기지 아니하였다는 소문이 다윗에게 이르매'),
    (8352, '다윗의 형 시므아의 아들 요나답이 아뢰어 이르되 내 주여 젊은 왕자들이 다 죽임을 당한 줄로 생각하지 마옵소서 오직 암논만 죽었으리이다 그가 압살롬의 누이 다말을 욕되게 한 날부터 압살롬이 결심한 것이니이다'),
    (8354, '○이에 압살롬은 도망하니라 파수하는 청년이 눈을 들어 보니 보아라 뒷산 언덕길로 여러 사람이 오는도다'),
    (8357, '○압살롬은 도망하여 그술 왕 암미훌의 아들 달매에게로 갔고 다윗은 날마다 그의 아들로 말미암아 슬퍼하니라'),
    (8483, '다윗이 그의 백성을 내보낼새 삼분의 일은 요압의 휘하에, 삼분의 일은 스루야의 아들 요압의 동생 아비새의 휘하에 넘기고 삼분의 일은 가드 사람 잇대의 휘하에 넘기고 왕이 백성에게 이르되 나도 반드시 너희와 함께 나가리라 하니'),
    (8484, '백성들이 이르되 왕은 나가지 마소서 우리가 도망할지라도 그들은 우리에게 마음을 쓰지 아니할 터이요 우리가 절반이나 죽을지라도 우리에게 마음을 쓰지 아니할 터이라 왕은 우리 만 명보다 중하시오니 왕은 성읍에 계시다가 우리를 도우심이 좋으니이다 하니라'),
    (8487, '○이에 백성이 이스라엘을 치러 들로 나가서 에브라임 수풀에서 싸우더니'),
    (8490, '○압살롬이 다윗의 부하들과 마주치니라 압살롬이 노새를 탔는데 그 노새가 큰 상수리나무 번성한 가지 아래로 지날 때에 압살롬의 머리가 그 상수리나무에 걸리매 그가 공중과 그 땅 사이에 달리고 그가 탔던 노새는 그 아래로 빠져나간지라'),
    (8493, '그 사람이 요압에게 대답하되 내가 내 손에 은 천 개를 받는다 할지라도 나는 왕의 아들에게 손을 대지 아니하겠나이다 우리가 들었거니와 왕이 당신과 아비새와 잇대에게 명령하여 이르시기를 삼가 누구든지 젊은 압살롬을 해하지 말라 하셨나이다'),
    (8497, '○요압이 나팔을 불어 백성들에게 그치게 하니 그들이 이스라엘을 추격하지 아니하고 돌아오니라'),
    (8499, '압살롬이 살았을 때에 자기를 위하여 한 비석을 마련하여 세웠으니 이는 그가 자기 이름을 전할 아들이 내게 없다고 말하였음이더라 그러므로 자기 이름을 기념하여 그 비석에 이름을 붙였으며 그 비석이 왕의 골짜기에 있고 이제까지 그것을 압살롬의 기념비라 일컫더라'),
    (8500, '<압살롬의 죽음과 다윗의 울음> ○사독의 아들 아히마아스가 이르되 청하건대 내가 빨리 왕에게 가서 여호와께서 왕의 원수 갚아 주신 소식을 전하게 하소서'),
    (8503, '사독의 아들 아히마아스가 다시 요압에게 이르되 청하건대 아무쪼록 내가 또한 구스 사람의 뒤를 따라 달려가게 하소서 하니 요압이 이르되 내 아들아 너는 왜 달려가려 하느냐 이 소식으로 말미암아서는 너는 상을 받지 못하리라 하되'),
    (8505, '○때에 다윗이 두 문 사이에 앉아 있더라 파수꾼이 성 문 위층에 올라가서 눈을 들어 보니 어떤 사람이 홀로 달려오는지라'),
    (8509, '○아히마아스가 외쳐 왕께 아뢰되 평강하옵소서 하고 왕 앞에서 얼굴을 땅에 대고 절하며 이르되 왕의 하나님 여호와를 찬양하리로소이다 그의 손을 들어 내 주 왕을 대적하는 자들을 넘겨 주셨나이다 하니'),
    (8512, '○구스 사람이 이르러 말하되 내 주 왕께 아뢸 소식이 있나이다 여호와께서 오늘 왕을 대적하던 모든 원수를 갚으셨나이다 하니'),
    (8514, '왕의 마음이 심히 아파 문 위층으로 올라가서 우니라 그가 올라갈 때에 말하기를 내 아들 압살롬아 내 아들 내 아들 압살롬아 차라리 내가 너를 대신하여 죽었더면, 압살롬 내 아들아 내 아들아 하였더라'),
    (8361, '드고아에 사람을 보내 거기서 지혜로운 여인 하나를 데려다가 그에게 이르되 청하건대 너는 상주가 된 것처럼 상복을 입고 기름을 바르지 말고 죽은 사람을 위하여 오래 슬퍼하는 여인 같이 하고'),
    (8363, '○드고아 여인이 왕께 아뢸 때에 얼굴을 땅에 대고 엎드려 이르되 왕이여 도우소서 하니'),
    (8366, '온 족속이 일어나서 당신의 여종 나를 핍박하여 말하기를 그의 동생을 쳐죽인 자를 내놓으라 우리가 그의 동생 죽인 죄를 갚아 그를 죽여 상속자 될 것까지 끊겠노라 하오니 그러한즉 그들이 내게 남아 있는 숯불을 꺼서 내 남편의 이름과 씨를 세상에 남겨두지 아니하겠나이다 하니'),
    (8370, '여인이 이르되 청하건대 왕은 왕의 하나님 여호와를 기억하사 원수 갚는 자가 더 죽이지 못하게 하옵소서 내 아들을 죽일까 두렵나이다 하니 왕이 이르되 여호와께서 살아 계심을 두고 맹세하노니 네 아들의 머리카락 하나도 땅에 떨어지지 아니하리라 하니라'),
    (8371, '○여인이 이르되 청하건대 당신의 여종을 용납하여 한 말씀을 내 주 왕께 여쭙게 하옵소서 하니 그가 이르되 말하라 하니라'),
    (8372, '여인이 이르되 그러면 어찌하여 왕께서 하나님의 백성에게 대하여 이같은 생각을 하셨나이까 이 말씀을 하심으로 왕께서 죄 있는 사람 같이 되심은 그 내쫓긴 자를 왕께서 집으로 돌아오게 하지 아니하심이니이다'),
    (8376, '당신의 여종이 또 스스로 말하기를 내 주 왕의 말씀이 나의 위로가 되기를 원한다 하였사오니 이는 내 주 왕께서 하나님의 사자 같이 선과 악을 분간하심이니이다 원하건대 왕의 하나님 여호와께서 왕과 같이 계시옵소서'),
    (8377, '○왕이 그 여인에게 대답하여 이르되 바라노니 내가 네게 묻는 것을 내게 숨기지 말라 여인이 이르되 내 주 왕은 말씀하옵소서'),
    (8378, '왕이 이르되 이 모든 일에 요압이 너와 함께 하였느냐 하니 여인이 대답하여 이르되 내 주 왕의 살아 계심을 두고 맹세하옵나니 내 주 왕의 말씀을 좌로나 우로나 옮길 자가 없으리이다 왕의 종 요압이 내게 명령하였고 그가 이 모든 말을 왕의 여종의 입에 넣어 주었사오니'),
    (8380, '○왕이 요압에게 이르되 내가 이 일을 허락하였으니 가서 청년 압살롬을 데려오라 하니라'),
    (8384, '<다윗이 압살롬과 화해하다> ○온 이스라엘 가운데에서 압살롬 같이 아름다움으로 크게 칭찬 받는 자가 없었으니 그는 발바닥부터 정수리까지 흠이 없음이라'),
    (8387, '○압살롬이 이태 동안 예루살렘에 있으되 왕의 얼굴을 보지 못하였으므로'),
    (8391, '압살롬이 요압에게 대답하되 내가 일찍이 사람을 네게 보내 너를 이리로 오라고 청한 것은 내가 너를 왕께 보내 아뢰게 하기를 어찌하여 내가 그술에서 돌아오게 되었나이까 이 때까지 거기에 있는 것이 내게 나았으리이다 하려 함이로라 이제는 네가 나로 하여금 왕의 얼굴을 볼 수 있게 하라 내가 만일 죄가 있으면 왕이 나를 죽이시는 것이 옳으니라 하는지라'),
    (8431, '왕이 시바에게 이르되 네가 무슨 뜻으로 이것을 가져왔느냐 하니 시바가 이르되 나귀는 왕의 가족들이 타게 하고 떡과 과일은 청년들이 먹게 하고 포도주는 들에서 피곤한 자들에게 마시게 하려 함이니이다'),
    (8434, '<다윗과 시므이> ○다윗 왕이 바후림에 이르매 거기서 사울의 친족 한 사람이 나오니 게라의 아들이요 이름은 시므이라 그가 나오면서 계속하여 저주하고'),
    (8437, '사울의 족속의 모든 피를 여호와께서 네게로 돌리셨도다 그를 이어서 네가 왕이 되었으나 여호와께서 나라를 네 아들 압살롬의 손에 넘기셨도다 보라 너는 피를 흘린 자이므로 화를 자초하였느니라 하는지라'),
    (8438, '○스루야의 아들 아비새가 왕께 여짜오되 이 죽은 개가 어찌 내 주 왕을 저주하리이까 청하건대 내가 건너가서 그의 머리를 베게 하소서 하니'),
    (8444, '<압살롬의 입성과 후새의 위장 전향> ○압살롬과 모든 이스라엘 백성들이 예루살렘에 이르고 아히도벨도 그와 함께 이른지라'),
    (8449, '○압살롬이 아히도벨에게 이르되 너는 어떻게 행할 계략을 우리에게 가르치라 하니'),
    (8450, '아히도벨이 압살롬에게 이르되 왕의 아버지가 남겨 두어 왕궁을 지키게 한 후궁들과 더불어 동침하소서 그리하면 왕께서 왕의 아버지가 미워하는 바 됨을 온 이스라엘이 들으리니 왕과 함께 있는 모든 사람의 힘이 더욱 강하여지리이다 하니라'),
    (8453, '<압살롬이 아히도벨의 계략을 따르지 않다> 아히도벨이 또 압살롬에게 이르되 이제 내가 사람 만 이천 명을 택하게 하소서 오늘 밤에 내가 일어나서 다윗의 뒤를 추적하여'),
    (8457, '○압살롬이 이르되 아렉 사람 후새도 부르라 우리가 이제 그의 말도 듣자 하니라'),
    (8460, '또 후새가 말하되 왕도 아시거니와 왕의 아버지와 그의 추종자들은 용사라 그들은 들에 있는 곰이 새끼를 빼앗긴 것 같이 격분하였고 왕의 부친은 전쟁에 익숙한 사람인즉 백성과 함께 자지 아니하고'),
    (8466, '압살롬과 온 이스라엘 사람들이 이르되 아렉 사람 후새의 계략은 아히도벨의 계략보다 낫다 하니 이는 여호와께서 압살롬에게 화를 내리려 하사 아히도벨의 좋은 계략을 물리치라고 명령하셨음이더라'),
    (8467, '<후새의 계략과 아히도벨의 죽음> ○이에 후새가 사독과 아비아달 두 제사장에게 이르되 아히도벨이 압살롬과 이스라엘 장로들에게 이러이러하게 계략을 세웠고 나도 이러이러하게 계략을 세웠으니'),
    (8472, '압살롬의 종들이 그 집에 와서 여인에게 묻되 아히마아스와 요나단이 어디 있느냐 하니 여인이 그들에게 이르되 그들이 시내를 건너가더라 하니 그들이 찾아도 만나지 못하고 예루살렘으로 돌아가니라'),
    (8473, '○그들이 간 후에 두 사람이 우물에서 올라와서 다윗 왕에게 가서 다윗 왕에게 말하여 이르되 당신들은 일어나 빨리 물을 건너가소서 아히도벨이 당신들을 해하려고 이러이러하게 계략을 세웠나이다'),
    (8476, '○이에 다윗은 마하나임에 이르고 압살롬은 모든 이스라엘 사람과 함께 요단을 건너니라'),
    (8477, '압살롬이 아마사로 요압을 대신하여 군지휘관으로 삼으니라 아마사는 이스라엘 사람 이드라라 하는 자의 아들이라 이드라가 나하스의 딸 아비갈과 동침하여 그를 낳았으며 아비갈은 요압의 어머니 스루야의 동생이더라'),
    (8479, '○다윗이 마하나임에 이르렀을 때에 암몬 족속에게 속한 랍바 사람 나하스의 아들 소비와 로데발 사람 암미엘의 아들 마길과 로글림 길르앗 사람 바르실래가'),
    (8394, '압살롬이 일찍이 일어나 성문 길 곁에 서서 어떤 사람이든지 송사가 있어 왕에게 재판을 청하러 올 때에 그 사람을 불러 이르되 너는 어느 성읍 사람이냐 하니 그 사람의 대답이 종은 이스라엘 아무 지파에 속하였나이다 하면'),
    (8399, '○사 년 만에 압살롬이 왕께 아뢰되 내가 여호와께 서원한 것이 있사오니 청하건대 내가 헤브론에 가서 그 서원을 이루게 하소서'),
    (8405, '<다윗이 예루살렘에서 도망하다> ○전령이 다윗에게 와서 말하되 이스라엘의 인심이 다 압살롬에게로 돌아갔나이다 한지라'),
    (8406, '다윗이 예루살렘에 함께 있는 그의 모든 신하들에게 이르되 일어나 도망하자 그렇지 아니하면 우리 중 한 사람도 압살롬에게서 피하지 못하리라 빨리 가자 두렵건대 그가 우리를 급히 따라와 우리를 해하고 칼날로 성읍을 칠까 하노라'),
    (8411, '○그 때에 왕이 가드 사람 잇대에게 이르되 어찌하여 너도 우리와 함께 가느냐 너는 쫓겨난 나그네이니 돌아가서 왕과 함께 네 곳에 있으라'),
    (8416, '○보라 사독과 그와 함께 한 모든 레위 사람도 하나님의 언약궤를 메어다가 하나님의 궤를 내려놓고 아비아달도 올라와서 모든 백성이 성에서 나오기를 기다리도다'),
    (8422, '○다윗이 감람 산 길로 올라갈 때에 그의 머리를 그가 가리고 맨발로 울며 가고 그와 함께 가는 모든 백성들도 각각 자기의 머리를 가리고 울며 올라가니라'),
    (8426, '그러나 네가 만일 성읍으로 돌아가서 압살롬에게 말하기를 왕이여 내가 왕의 종이니이다 전에는 내가 왕의 아버지의 종이었더니 이제는 내가 왕의 종이니이다 하면 네가 나를 위하여 아히도벨의 모략을 패하게 하리라'),
    (8520, '이는 왕께서 미워하는 자는 사랑하시며 사랑하는 자는 미워하시고 오늘 지휘관들과 부하들을 멸시하심을 나타내심이라 오늘 내가 깨달으니 만일 압살롬이 살고 오늘 우리가 다 죽었더면 왕이 마땅히 여기실 뻔하였나이다'),
    (8521, '이제 곧 일어나 나가 왕의 부하들의 마음을 위로하여 말씀하옵소서 내가 여호와를 두고 맹세하옵나니 왕이 만일 나가지 아니하시면 오늘 밤에 한 사람도 왕과 함께 머물지 아니할지라 그리하면 그 화가 왕이 젊었을 때부터 지금까지 당하신 모든 화보다 더욱 심하리이다 하니'),
    (8522, '<다윗의 귀환 준비> 왕이 일어나 성문에 앉으매 어떤 사람이 모든 백성에게 말하되 왕이 문에 앉아 계신다 하니 모든 백성이 왕 앞으로 나아오니라 ○이스라엘은 이미 각기 장막으로 도망하였더라'),
    (8526, '○다윗 왕이 사독과 아비아달 두 제사장에게 소식을 전하여 이르되 너희는 유다 장로들에게 말하여 이르기를 왕의 말씀이 온 이스라엘이 왕을 왕궁으로 도로 모셔오자 하는 말이 왕께 들렸거늘 너희는 어찌하여 왕을 궁으로 모시는 일에 나중이 되느냐'),
    (8531, '<다윗과 시므이> ○바후림에 있는 베냐민 사람 게라의 아들 시므이가 급히 유다 사람과 함께 다윗 왕을 맞으러 내려올 때에'),
    (8536, '○스루야의 아들 아비새가 대답하여 이르되 시므이가 여호와의 기름 부으신 자를 저주하였으니 그로 말미암아 죽어야 마땅하지 아니하니이까 하니라'),
    (8537, '다윗이 이르되 스루야의 아들들아 내가 너희와 무슨 상관이 있기에 너희가 오늘 나의 원수가 되느냐 오늘 어찌하여 이스라엘 가운데에서 사람을 죽이겠느냐 내가 오늘 이스라엘의 왕이 된 것을 내가 알지 못하리요 하고'),
    (8539, '<다윗과 므비보셋> ○사울의 손자 므비보셋이 내려와 왕을 맞으니 그는 왕이 떠난 날부터 평안히 돌아오는 날까지 그의 발을 맵시 내지 아니하며 그의 수염을 깎지 아니하며 옷을 빨지 아니하였더라'),
    (8543, '내 아버지의 온 집이 내 주 왕 앞에서는 다만 죽을 사람이 되지 아니하였나이까 그러나 종을 왕의 상에서 음식 먹는 자 가운데에 두셨사오니 내게 아직 무슨 공의가 있어서 다시 왕께 부르짖을 수 있사오리이까 하니라'),
    (8546, '<다윗과 바르실래> ○길르앗 사람 바르실래가 왕이 요단을 건너가게 하려고 로글림에서 내려와 함께 요단에 이르니'),
    (8550, '내 나이가 이제 팔십 세라 어떻게 좋고 흉한 것을 분간할 수 있사오며 음식의 맛을 알 수 있사오리이까 이 종이 어떻게 다시 노래하는 남자나 여인의 소리를 알아들을 수 있사오리이까 어찌하여 종이 내 주 왕께 아직도 누를 끼치리이까'),
    (8551, '당신의 종은 왕을 모시고 요단을 건너려는 것뿐이거늘 왕께서 어찌하여 이같은 상으로 내게 갚으려 하시나이까'),
    (8552, '청하건대 당신의 종을 돌려보내옵소서 내가 내 고향 부모의 묘 곁에서 죽으려 하나이다 그러나 왕의 종 김함이 여기 있사오니 청하건대 그가 내 주 왕과 함께 건너가게 하시옵고 왕의 처분대로 그에게 베푸소서 하니라'),
    (8555, '<남북의 분쟁> ○왕이 길갈로 건너오고 김함도 함께 건너오니 온 유다 백성과 이스라엘 백성의 절반이나 왕과 함께 건너니라'),
    (8557, '모든 유다 사람이 이스라엘 사람에게 대답하되 왕은 우리의 종친인 까닭이라 너희가 어찌 이 일에 대하여 분 내느냐 우리가 왕의 것을 조금이라도 얻어 먹었느냐 왕께서 우리에게 선물로 주신 것이 있느냐'),
    (8558, '이스라엘 사람이 유다 사람에게 대답하여 이르되 우리는 왕에 대하여 열 몫을 가졌으니 다윗에게 대하여 너희보다 더욱 관계가 있거늘 너희가 어찌 우리를 멸시하여 우리 왕을 모셔 오는 일에 먼저 우리와 의논하지 아니하였느냐 하나 유다 사람의 말이 이스라엘 사람의 말보다 더 강경하였더라'),
    (8559, '<세바의 반역> 마침 거기에 불량배 하나가 있으니 그의 이름은 세바인데 베냐민 사람 비그리의 아들이었더라 그가 나팔을 불며 이르되 우리는 다윗과 나눌 분깃이 없으며 이새의 아들에게서 받을 유산이 우리에게 없도다 이스라엘아 각각 장막으로 돌아가라 하매'),
    (8561, '○다윗이 예루살렘 본궁에 이르러 전에 머물러 왕궁을 지키게 한 후궁 열 명을 잡아 별실에 가두고 먹을 것만 주고 그들에게 관계하지 아니하니 그들이 죽는 날까지 갇혀서 생과부로 지내니라'),
    (8562, '○왕이 아마사에게 이르되 너는 나를 위하여 삼 일 내로 유다 사람을 큰 소리로 불러 모으고 너도 여기 있으라 하니라'),
    (8564, '다윗이 이에 아비새에게 이르되 이제 비그리의 아들 세바가 압살롬보다 우리를 더 해하리니 너는 네 주의 부하들을 데리고 그의 뒤를 쫓아가라 그가 견고한 성읍에 들어가 우리들을 피할까 염려하노라 하매'),
    (8568, '아마사가 요압의 손에 있는 칼은 주의하지 아니한지라 요압이 칼로 그의 배를 찌르매 그의 창자가 땅에 쏟아지니 그를 다시 치지 아니하여도 죽으니라 ○요압과 그의 동생 아비새가 비그리의 아들 세바를 뒤쫓을새'),
    (8571, '아마사가 길 가운데 피 속에 놓여 있는지라 그 청년이 모든 백성이 서 있는 것을 보고 아마사를 큰길에서부터 밭으로 옮겼으나 거기에 이르는 자도 다 멈추어 서는 것을 보고 옷을 그 위에 덮으니라'),
    (8573, '○세바가 이스라엘 모든 지파 가운데 두루 다녀서 아벨과 벧마아가와 베림 온 땅에 이르니 그 무리도 다 모여 그를 따르더라'),
    (8580, '그 일이 그러한 것이 아니니라 에브라임 산지 사람 비그리의 아들 그의 이름을 세바라 하는 자가 손을 들어 왕 다윗을 대적하였나니 너희가 그만 내주면 내가 이 성벽에서 떠나가리라 하니라 여인이 요압에게 이르되 그의 머리를 성벽에서 당신에게 내어던지리이다 하고'),
    (8581, '이에 여인이 그의 지혜를 가지고 모든 백성에게 나아가매 그들이 비그리의 아들 세바의 머리를 베어 요압에게 던진지라 이에 요압이 나팔을 불매 무리가 흩어져 성읍에서 물러나 각기 장막으로 돌아가고 요압은 예루살렘으로 돌아와 왕에게 나아가니라'),
    (8582, '<다윗의 관리들> ○요압은 이스라엘 온 군대의 지휘관이 되고 여호야다의 아들 브나야는 그렛 사람과 블렛 사람의 지휘관이 되고'),
    (8586, '<다윗이 기브온 사람의 말을 들어 주다> 다윗의 시대에 해를 거듭하여 삼 년 기근이 있으므로 다윗이 여호와 앞에 간구하매 여호와께서 이르시되 이는 사울과 피를 흘린 그의 집으로 말미암음이니 그가 기브온 사람을 죽였음이니라 하시니라'),
    (8587, '기브온 사람은 이스라엘 족속이 아니요 그들은 아모리 사람 중에서 남은 자라 이스라엘 족속들이 전에 그들에게 맹세하였거늘 사울이 이스라엘과 유다 족속을 위하여 열심이 있으므로 그들을 죽이고자 하였더라 이에 왕이 기브온 사람을 불러 그들에게 물으니라'),
    (8589, '기브온 사람이 그에게 대답하되 사울과 그의 집과 우리 사이의 문제는 은금에 있지 아니하오며 이스라엘 가운데에서 사람을 죽이는 문제도 우리에게 있지 아니하니이다 하니라 왕이 이르되 너희가 말하는 대로 시행하리라'),
    (8592, '○그러나 다윗과 사울의 아들 요나단 사이에 서로 여호와를 두고 맹세한 것이 있으므로 왕이 사울의 손자 요나단의 아들 므비보셋은 아끼고'),
    (8595, '○아야의 딸 리스바가 굵은 베를 가져다가 자기를 위하여 바위 위에 펴고 곡식 베기 시작할 때부터 하늘에서 비가 시체에 쏟아지기까지 그 시체에 낮에는 공중의 새가 앉지 못하게 하고 밤에는 들짐승이 범하지 못하게 한지라'),
    (8597, '다윗이 가서 사울의 뼈와 그의 아들 요나단의 뼈를 길르앗 야베스 사람에게서 가져가니 이는 전에 블레셋 사람들이 사울을 길보아에서 죽여 블레셋 사람들이 벧산 거리에 매단 것을 그들이 가만히 가져온 것이라'),
    (8600, '<블레셋의 거인들을 죽인 다윗의 용사들> ○블레셋 사람이 다시 이스라엘을 치거늘 다윗이 그의 부하들과 함께 내려가서 블레셋 사람과 싸우더니 다윗이 피곤하매'),
    (8602, '스루야의 아들 아비새가 다윗을 도와 그 블레셋 사람들을 쳐죽이니 그 때에 다윗의 추종자들이 그에게 맹세하여 이르되 왕은 다시 우리와 함께 전장에 나가지 마옵소서 이스라엘의 등불이 꺼지지 말게 하옵소서 하니라'),
    (8603, '○그 후에 다시 블레셋 사람과 곱에서 전쟁할 때에 후사 사람 십브개는 거인족의 아들 중의 삽을 쳐죽였고'),
    (8608, '<다윗의 승전가> 여호와께서 다윗을 모든 원수의 손과 사울의 손에서 구원하신 그 날에 다윗이 이 노래의 말씀으로 여호와께 아뢰어'),
    (8632, '그러므로 여호와께서 내 의대로, 그의 눈앞에서 내 깨끗한 대로 내게 갚으셨도다'),
    (8666, '<다윗의 용사들> ○다윗의 용사들의 이름은 이러하니라 다그몬 사람 요셉밧세벳이라고도 하고 에센 사람 아디노라고도 하는 자는 군지휘관의 두목이라 그가 단번에 팔백 명을 쳐죽였더라'),
    (8667, '○그 다음은 아호아 사람 도대의 아들 엘르아살이니 다윗과 함께 한 세 용사 중의 한 사람이라 블레셋 사람들이 싸우려고 거기에 모이매 이스라엘 사람들이 물러간지라 세 용사가 싸움을 돋우고'),
    (8669, '○그 다음은 하랄 사람 아게의 아들 삼마라 블레셋 사람들이 사기가 올라 거기 녹두나무가 가득한 한쪽 밭에 모이매 백성들은 블레셋 사람들 앞에서 도망하되'),
    (8671, '○또 삼십 두목 중 세 사람이 곡식 벨 때에 아둘람 굴에 내려가 다윗에게 나아갔는데 때에 블레셋 사람의 한 무리가 르바임 골짜기에 진 쳤더라'),
    (8675, '이르되 여호와여 내가 나를 위하여 결단코 이런 일을 하지 아니하리이다 이는 목숨을 걸고 갔던 사람들의 피가 아니니이까 하고 마시기를 즐겨하지 아니하니라 세 용사가 이런 일을 행하였더라'),
    (8676, '○또 스루야의 아들 요압의 아우 아비새이니 그는 그 세 사람의 우두머리라 그가 그의 창을 들어 삼백 명을 죽이고 세 사람 중에 이름을 얻었으니'),
    (8678, '○또 갑스엘 용사의 손자 여호야다의 아들 브나야이니 그는 용맹스런 일을 행한 자라 일찍이 모압 아리엘의 아들 둘을 죽였고 또 눈이 올 때에 구덩이에 내려가서 사자 한 마리를 쳐죽였으며'),
    (8682, '○요압의 아우 아사헬은 삼십 명 중의 하나요 또 베들레헴 도도의 아들 엘하난과'),
    (8689, '아르바 사람 아비알본과 바르훔 사람 아스마웻과'),
    (8698, '<인구 조사> 여호와께서 다시 이스라엘을 향하여 진노하사 그들을 치시려고 다윗을 격동시키사 가서 이스라엘과 유다의 인구를 조사하라 하신지라'),
    (8700, '요압이 왕께 아뢰되 이 백성이 얼마든지 왕의 하나님 여호와께서 백 배나 더하게 하사 내 주 왕의 눈으로 보게 하시기를 원하나이다 그런데 내 주 왕은 어찌하여 이런 일을 기뻐하시나이까 하되'),
    (8707, '○다윗이 백성을 조사한 후에 그의 마음에 자책하고 다윗이 여호와께 아뢰되 내가 이 일을 행함으로 큰 죄를 범하였나이다 여호와여 이제 간구하옵나니 종의 죄를 사하여 주옵소서 내가 심히 미련하게 행하였나이다 하니라'),
    (8710, '갓이 다윗에게 이르러 아뢰어 이르되 왕의 땅에 칠 년 기근이 있을 것이니이까 혹은 왕이 왕의 원수에게 쫓겨 석 달 동안 그들 앞에서 도망하실 것이니이까 혹은 왕의 땅에 사흘 동안 전염병이 있을 것이니이까 왕은 생각하여 보고 나를 보내신 이에게 무엇을 대답하게 하소서 하는지라'),
    (8713, '천사가 예루살렘을 향하여 그의 손을 들어 멸하려 하더니 여호와께서 이 재앙 내리심을 뉘우치사 백성을 멸하는 천사에게 이르시되 족하다 이제는 네 손을 거두라 하시니 여호와의 사자가 여부스 사람 아라우나의 타작 마당 곁에 있는지라'),
    (8714, '다윗이 백성을 치는 천사를 보고 곧 여호와께 아뢰어 이르되 나는 범죄하였고 악을 행하였거니와 이 양 무리는 무엇을 행하였나이까 청하건대 주의 손으로 나와 내 아버지의 집을 치소서 하니라'),
    (8715, '○이 날에 갓이 다윗에게 이르러 그에게 아뢰되 올라가서 여부스 사람 아라우나의 타작 마당에서 여호와를 위하여 제단을 쌓으소서 하매'),
    (8727, '<아도니야가 왕이 되고자 하다> ○그 때에 학깃의 아들 아도니야가 스스로 높여서 이르기를 내가 왕이 되리라 하고 자기를 위하여 병거와 기병과 호위병 오십 명을 준비하니'),
    (8733, '<솔로몬이 왕이 되다> ○나단이 솔로몬의 어머니 밧세바에게 말하여 이르되 학깃의 아들 아도니야가 왕이 되었음을 듣지 못하였나이까 우리 주 다윗은 알지 못하시나이다'),
    (8735, '당신은 다윗 왕 앞에 들어가서 아뢰기를 내 주 왕이여 전에 왕이 여종에게 맹세하여 이르시기를 네 아들 솔로몬이 반드시 나를 이어 왕이 되어 내 왕위에 앉으리라 하지 아니하셨나이까 그런데 아도니야가 무슨 이유로 왕이 되었나이까 하소서'),
    (8737, '○밧세바가 이에 침실에 들어가 왕에게 이르니 왕이 심히 늙었으므로 수넴 여자 아비삭이 시중들었더라'),
    (8744, '○밧세바가 왕과 말할 때에 선지자 나단이 들어온지라'),
    (8747, '그가 오늘 내려가서 수소와 살찐 송아지와 양을 많이 잡고 왕의 모든 아들과 군사령관들과 제사장 아비아달을 청하였는데 그들이 아도니야 앞에서 먹고 마시며 아도니야 왕은 만세수를 하옵소서 하였나이다'),
    (8752, '내가 이전에 이스라엘의 하나님 여호와를 가리켜 네게 맹세하여 이르기를 네 아들 솔로몬이 반드시 나를 이어 왕이 되고 나를 대신하여 내 왕위에 앉으리라 하였으니 내가 오늘 그대로 행하리라'),
    (8754, '○다윗 왕이 이르되 제사장 사독과 선지자 나단과 여호야다의 아들 브나야를 내 앞으로 부르라 하니 그들이 왕 앞에 이른지라'),
    (8760, '○제사장 사독과 선지자 나단과 여호야다의 아들 브나야와 그렛 사람과 블렛 사람이 내려가서 솔로몬을 다윗 왕의 노새에 태우고 인도하여 기혼으로 가서'),
    (8769, '왕의 신하들도 와서 우리 주 다윗 왕에게 축복하여 이르기를 왕의 하나님이 솔로몬의 이름을 왕의 이름보다 더 아름답게 하시고 그의 왕위를 왕의 위보다 크게 하시기를 원하나이다 하매 왕이 침상에서 몸을 굽히고'),
    (8773, '어떤 사람이 솔로몬에게 말하여 이르되 아도니야가 솔로몬 왕을 두려워하여 지금 제단 뿔을 잡고 말하기를 솔로몬 왕이 오늘 칼로 자기 종을 죽이지 않겠다고 내게 맹세하기를 원한다 하나이다'),
    (8884, '<솔로몬이 성전 건축을 준비하다> 솔로몬이 기름 부음을 받고 그의 아버지를 이어 왕이 되었다 함을 두로 왕 히람이 듣고 그의 신하들을 솔로몬에게 보냈으니 이는 히람이 평생에 다윗을 사랑하였음이라'),
    (8886, '당신도 알거니와 내 아버지 다윗이 사방의 전쟁으로 말미암아 그의 하나님 여호와의 이름을 위하여 성전을 건축하지 못하고 여호와께서 그의 원수들을 그의 발바닥 밑에 두시기를 기다렸나이다'),
    (8888, '여호와께서 내 아버지 다윗에게 하신 말씀에 내가 너를 이어 네 자리에 오르게 할 네 아들 그가 내 이름을 위하여 성전을 건축하리라 하신 대로 내가 내 하나님 여호와의 이름을 위하여 성전을 건축하려 하오니'),
    (8889, '당신은 명령을 내려 나를 위하여 레바논에서 백향목을 베어내게 하소서 내 종과 당신의 종이 함께 할 것이요 또 내가 당신의 모든 말씀대로 당신의 종의 삯을 당신에게 드리리이다 당신도 알거니와 우리 중에는 시돈 사람처럼 벌목을 잘하는 자가 없나이다'),
    (8890, '○히람이 솔로몬의 말을 듣고 크게 기뻐하여 이르되 오늘 여호와를 찬양할지로다 그가 다윗에게 지혜로운 아들을 주사 그 많은 백성을 다스리게 하셨도다 하고'),
    (8892, '내 종이 레바논에서 바다로 운반하겠고 내가 그것을 바다에서 뗏목으로 엮어 당신이 지정하는 곳으로 보내고 거기서 그것을 풀리니 당신은 받으시고 내 원을 이루어 나의 궁정을 위하여 음식물을 주소서 하고'),
    (8896, '○이에 솔로몬 왕이 온 이스라엘 가운데서 역군을 불러일으키니 그 역군의 수가 삼만 명이라'),
    (8822, '<솔로몬이 지혜를 구하다> 솔로몬이 애굽의 왕 바로와 더불어 혼인 관계를 맺어 그의 딸을 맞이하고 다윗 성에 데려다가 두고 자기의 왕궁과 여호와의 성전과 예루살렘 주위의 성의 공사가 끝나기를 기다리니라'),
    (8825, '○이에 왕이 제사하러 기브온으로 가니 거기는 산당이 큼이라 솔로몬이 그 제단에 일천 번제를 드렸더니'),
    (8826, '기브온에서 밤에 여호와께서 솔로몬의 꿈에 나타나시니라 하나님이 이르시되 내가 네게 무엇을 줄꼬 너는 구하라'),
    (8827, '솔로몬이 이르되 주의 종 내 아버지 다윗이 성실과 공의와 정직한 마음으로 주와 함께 주 앞에서 행하므로 주께서 그에게 큰 은혜를 베푸셨고 주께서 또 그를 위하여 이 큰 은혜를 항상 주사 오늘과 같이 그의 자리에 앉을 아들을 그에게 주셨나이다'),
    (8829, '주께서 택하신 백성 가운데 있나이다 그들은 큰 백성이라 수효가 많아서 셀 수도 없고 기록할 수도 없사오니'),
    (8832, '이에 하나님이 그에게 이르시되 네가 이것을 구하도다 자기를 위하여 장수하기를 구하지 아니하며 부도 구하지 아니하며 자기 원수의 생명을 멸하기도 구하지 아니하고 오직 송사를 듣고 분별하는 지혜를 구하였으니'),
    (8837, '<솔로몬의 재판> ○그 때에 창기 두 여자가 왕에게 와서 그 앞에 서며'),
    (8847, '그 산 아들의 어머니 되는 여자가 그 아들을 위하여 마음이 불붙는 것 같아서 왕께 아뢰어 청하건대 내 주여 산 아이를 그에게 주시고 아무쪼록 죽이지 마옵소서 하되 다른 여자는 말하기를 내 것도 되게 말고 네 것도 되게 말고 나누게 하라 하는지라'),
    (8856, '○솔로몬이 또 온 이스라엘에 열두 지방 관장을 두매 그 사람들이 왕과 왕실을 위하여 양식을 공급하되 각기 일 년에 한 달씩 양식을 공급하였으니'),
    (8869, '<솔로몬의 영화> ○유다와 이스라엘의 인구가 바닷가의 모래 같이 많게 되매 먹고 마시며 즐거워하였으며'),
    (8878, '○하나님이 솔로몬에게 지혜와 총명을 심히 많이 주시고 또 넓은 마음을 주시되 바닷가의 모래 같이 하시니'),
    (8902, '<솔로몬이 성전을 건축하다> 이스라엘 자손이 애굽 땅에서 나온 지 사백팔십 년이요 솔로몬이 이스라엘 왕이 된 지 사 년 시브월 곧 둘째 달에 솔로몬이 여호와를 위하여 성전 건축하기를 시작하였더라'),
    (8907, '하층 다락의 너비는 다섯 규빗이요 중층 다락의 너비는 여섯 규빗이요 셋째 층 다락의 너비는 일곱 규빗이라 성전의 벽 바깥으로 돌아가며 턱을 내어 골방 들보들로 성전의 벽에 박히지 아니하게 하였으며'),
    (8912, '○여호와의 말씀이 솔로몬에게 임하여 이르시되'),
    (8915, '<성전 내부 장식> ○솔로몬이 성전 건축하기를 마치고'),
    (8924, '○내소 안에 감람나무로 두 그룹을 만들었는데 그 높이가 각각 십 규빗이라'),
    (8928, '솔로몬이 내소 가운데에 그룹을 두었으니 그룹들의 날개가 퍼져 있는데 이쪽 그룹의 날개는 이쪽 벽에 닿았고 저쪽 그룹의 날개는 저쪽 벽에 닿았으며 두 날개는 성전의 중앙에서 서로 닿았더라'),
    (8930, '○내 외소 사방 벽에는 모두 그룹들과 종려와 핀 꽃 형상을 아로새겼고'),
    (8938, '○넷째 해 시브월에 여호와의 성전 기초를 쌓았고'),
    (8779, '여호와께서 내 일에 대하여 말씀하시기를 만일 네 자손들이 그들의 길을 삼가 마음을 다하고 성품을 다하여 진실히 내 앞에서 행하면 이스라엘 왕위에 오를 사람이 네게서 끊어지지 아니하리라 하신 말씀을 확실히 이루게 하시리라'),
    (8780, '스루야의 아들 요압이 내게 행한 일 곧 이스라엘 군대의 두 사령관 넬의 아들 아브넬과 예델의 아들 아마사에게 행한 일을 네가 알거니와 그가 그들을 죽여 태평 시대에 전쟁의 피를 흘리고 전쟁의 피를 자기의 허리에 띤 띠와 발에 신은 신에 묻혔으니'),
    (8783, '바후림 베냐민 사람 게라의 아들 시므이가 너와 함께 있나니 그는 내가 마하나임으로 갈 때에 악독한 말로 나를 저주하였느니라 그러나 그가 요단에 내려와서 나를 영접하므로 내가 여호와를 두고 맹세하여 이르기를 내가 칼로 너를 죽이지 아니하리라 하였노라'),
    (8785, '<다윗이 죽다> ○다윗이 그의 조상들과 함께 누워 다윗 성에 장사되니'),
    (8788, '<아도니야가 죽임을 당하다> ○학깃의 아들 아도니야가 솔로몬의 어머니 밧세바에게 나아온지라 밧세바가 이르되 네가 화평한 목적으로 왔느냐 대답하되 화평한 목적이니이다'),
    (8790, '그가 이르되 당신도 아시는 바이거니와 이 왕위는 내 것이었고 온 이스라엘은 다 얼굴을 내게로 향하여 왕으로 삼으려 하였는데 그 왕권이 돌아가 내 아우의 것이 되었음은 여호와께로 말미암음이니이다'),
    (8794, '○밧세바가 이에 아도니야를 위하여 말하려고 솔로몬 왕에게 이르니 왕이 일어나 영접하여 절한 후에 다시 왕좌에 앉고 그의 어머니를 위하여 자리를 베푸니 그가 그의 오른쪽에 앉는지라'),
    (8797, '솔로몬 왕이 그의 어머니에게 대답하여 이르되 어찌하여 아도니야를 위하여 수넴 여자 아비삭을 구하시나이까 그는 나의 형이오니 그를 위하여 왕권도 구하옵소서 그뿐 아니라 제사장 아비아달과 스루야의 아들 요압을 위해서도 구하옵소서 하고'),
    (8799, '그러므로 이제 나를 세워 내 아버지 다윗의 왕위에 오르게 하시고 허락하신 말씀대로 나를 위하여 집을 세우신 여호와께서 살아 계심을 두고 맹세하노니 아도니야는 오늘 죽임을 당하리라 하고'),
    (8801, '<아비아달의 추방과 요압의 처형> ○왕이 제사장 아비아달에게 이르되 네 고향 아나돗으로 가라 너는 마땅히 죽을 자이로되 네가 내 아버지 다윗 앞에서 주 여호와의 궤를 메었고 또 내 아버지가 모든 환난을 받을 때에 너도 환난을 받았은즉 내가 오늘 너를 죽이지 아니하노라 하고'),
    (8803, '○그 소문이 요압에게 들리매 그가 여호와의 장막으로 도망하여 제단 뿔을 잡으니 이는 그가 다윗을 떠나 압살롬을 따르지 아니하였으나 아도니야를 따랐음이더라'),
    (8805, '브나야가 여호와의 장막에 이르러 그에게 이르되 왕께서 나오라 하시느니라 그가 대답하되 아니라 내가 여기서 죽겠노라 브나야가 돌아가서 왕께 아뢰어 이르되 요압이 이리이리 내게 대답하더이다'),
    (8807, '여호와께서 요압의 피를 그의 머리로 돌려보내실 것은 그가 자기보다 의롭고 선한 두 사람을 쳤음이니 곧 이스라엘 군사령관 넬의 아들 아브넬과 유다 군사령관 예델의 아들 아마사를 칼로 죽였음이라 이 일을 내 아버지 다윗은 알지 못하셨나니'),
    (8811, '<시므이가 처형되다> ○왕이 사람을 보내어 시므이를 불러서 이르되 너는 예루살렘에서 너를 위하여 집을 짓고 거기서 살고 어디든지 나가지 말라'),
    (8814, '○삼 년 후에 시므이의 두 종이 가드 왕 마아가의 아들 아기스에게로 도망하여 간지라 어떤 사람이 시므이에게 말하여 이르되 당신의 종이 가드에 있나이다'),
    (8817, '왕이 사람을 보내어 시므이를 불러서 이르되 내가 너에게 여호와를 두고 맹세하게 하고 경고하여 이르기를 너는 분명히 알라 네가 밖으로 나가서 어디든지 가는 날에는 죽임을 당하리라 하지 아니하였느냐 너도 내게 말하기를 내가 들은 말씀이 좋으니이다 하였거늘'),
    (8948, '○이 집들은 안팎을 모두 귀하고 다듬은 돌로 지었으니 크기대로 톱으로 켠 것이라 그 초석에서 처마까지와 외면에서 큰 뜰에 이르기까지 다 그러하니'),
    (8952, '<놋쇠 대장장이 히람과 두 놋기둥> ○솔로몬 왕이 사람을 보내어 히람을 두로에서 데려오니'),
    (8962, '<놋을 부어 만든 바다> ○또 바다를 부어 만들었으니 그 직경이 십 규빗이요 그 모양이 둥글며 그 높이는 다섯 규빗이요 주위는 삼십 규빗 줄을 두를 만하며'),
    (8966, '<놋 받침 수레와 물두멍> ○또 놋으로 받침 수레 열을 만들었으니 매 받침 수레의 길이가 네 규빗이요 너비가 네 규빗이요 높이가 세 규빗이라'),
    (8970, '그 받침 수레 위로 들이켜 높이가 한 규빗 되게 내민 것이 있고 그 면은 직경 한 규빗 반 되게 반원형으로 우묵하며 그 나머지 면에는 아로새긴 것이 있으며 그 내민 판들은 네모지고 둥글지 아니하며'),
    (8979, '<성전 기구들> ○히람이 또 물두멍과 부삽과 대접들을 만들었더라 이와 같이 히람이 솔로몬 왕을 위하여 여호와의 전의 모든 일을 마쳤으니'),
    (8987, '○솔로몬이 또 여호와의 성전의 모든 기구를 만들었으니 곧 금 단과 진설병의 금 상과'),
    (8990, '○솔로몬 왕이 여호와의 성전을 위하여 만드는 모든 일을 마친지라 이에 솔로몬이 그의 아버지 다윗이 드린 물건 곧 은과 금과 기구들을 가져다가 여호와의 성전 곳간에 두었더라'),
    (9085, '<스바의 여왕이 솔로몬을 찾아오다> 스바의 여왕이 여호와의 이름으로 말미암은 솔로몬의 명성을 듣고 와서 어려운 문제로 그를 시험하고자 하여'),
    (9093, '당신의 하나님 여호와를 송축할지로다 여호와께서 당신을 기뻐하사 이스라엘 왕위에 올리셨고 여호와께서 영원히 이스라엘을 사랑하시므로 당신을 세워 왕으로 삼아 정의와 공의를 행하게 하셨도다 하고'),
    (9095, '○오빌에서부터 금을 실어온 히람의 배들이 오빌에서 많은 백단목과 보석을 운반하여 오매'),
    (9098, '<솔로몬의 재산과 지혜> ○솔로몬의 세입금의 무게가 금 육백육십육 달란트요'),
    (9107, '○솔로몬 왕의 재산과 지혜가 세상의 그 어느 왕보다 큰지라'),
    (9110, '○솔로몬이 병거와 마병을 모으매 병거가 천사백 대요 마병이 만이천 명이라 병거성에도 두고 예루살렘 왕에게도 두었으며'),
    (9059, '여호와께서 그에게 이르시되 네 기도와 네가 내 앞에서 간구한 바를 내가 들었은즉 나는 네가 건축한 이 성전을 거룩하게 구별하여 내 이름을 영원히 그 곳에 두며 내 눈길과 내 마음이 항상 거기에 있으리니'),
    (9063, '내가 이스라엘을 내가 그들에게 준 땅에서 끊어 버릴 것이요 내 이름을 위하여 내가 거룩하게 구별한 이 성전이라도 내 앞에서 던져버리리니 이스라엘은 모든 민족 가운데에서 속담거리와 이야기거리가 될 것이며'),
    (9065, '대답하기를 그들이 그들의 조상들을 애굽 땅에서 인도하여 내신 그들의 하나님 여호와를 버리고 다른 신을 따라가서 그를 경배하여 섬기므로 여호와께서 이 모든 재앙을 그들에게 내리심이라 하리라 하셨더라'),
    (9066, '<솔로몬과 히람의 거래> ○솔로몬이 두 집 곧 여호와의 성전과 왕궁을 이십 년 만에 건축하기를 마치고'),
    (9071, '<솔로몬의 나머지 업적> ○솔로몬 왕이 역군을 일으킨 까닭은 이러하니 여호와의 성전과 자기 왕궁과 밀로와 예루살렘 성과 하솔과 므깃도와 게셀을 건축하려 하였음이라'),
    (9079, '○솔로몬에게 일을 감독하는 우두머리 오백오십 명이 있어 일하는 백성을 다스렸더라'),
    (9080, '○바로의 딸이 다윗 성에서부터 올라와 솔로몬이 그를 위하여 건축한 궁에 이를 때에 솔로몬이 밀로를 건축하였더라'),
    (9081, '○솔로몬이 여호와를 위하여 쌓은 제단 위에 해마다 세 번씩 번제와 감사의 제물을 드리고 또 여호와 앞에 있는 제단에 분향하니라 이에 성전 짓는 일을 마치니라'),
    (9082, '○솔로몬 왕이 에돔 땅 홍해 물 가의 엘롯 근처 에시온게벨에서 배들을 지은지라'),
    (9191, '하나님의 사람이 제단을 향하여 여호와의 말씀으로 외쳐 이르되 제단아 제단아 여호와께서 이와 같이 말씀하시기를 다윗의 집에 요시야라 이름하는 아들을 낳으리니 그가 네 위에 분향하는 산당 제사장을 네 위에서 제물로 바칠 것이요 또 사람의 뼈를 네 위에서 사르리라 하셨느니라 하고'),
    (9195, '왕이 하나님의 사람에게 말하여 이르되 청하건대 너는 나를 위하여 네 하나님 여호와께 은혜를 구하여 내 손이 다시 성하게 기도하라 하나님의 사람이 여호와께 은혜를 구하니 왕의 손이 다시 성하도록 전과 같이 되니라'),
    (9200, '<벧엘의 늙은 선지자> ○벧엘에 한 늙은 선지자가 살더니 그의 아들들이 와서 이 날에 하나님의 사람이 벧엘에서 행한 모든 일을 그에게 말하고 또 그가 왕에게 드린 말씀도 그들이 그들의 아버지에게 말한지라'),
    (9201, '그들의 아버지가 그들에게 이르되 그가 어느 길로 가더냐 하니 그의 아들들이 유다에서부터 온 하나님의 사람의 간 길을 보았음이라'),
    (9207, '그가 그 사람에게 이르되 나도 그대와 같은 선지자라 천사가 여호와의 말씀으로 내게 이르기를 그를 네 집으로 데리고 돌아가서 그에게 떡을 먹이고 물을 마시게 하라 하였느니라 하니 이는 그 사람을 속임이라'),
    (9209, '○그들이 상 앞에 앉아 있을 때에 여호와의 말씀이 그 사람을 데려온 선지자에게 임하니'),
    (9215, '그 사람을 길에서 데리고 돌아간 선지자가 듣고 말하되 이는 여호와의 말씀을 어긴 하나님의 사람이로다 여호와께서 그에게 하신 말씀과 같이 여호와께서 그를 사자에게 넘기시매 사자가 그를 찢어 죽였도다 하고'),
    (9222, '<여로보암의 죄> ○여로보암이 이 일 후에도 그의 악한 길에서 떠나 돌이키지 아니하고 다시 일반 백성을 산당의 제사장으로 삼되 누구든지 자원하면 그 사람을 산당의 제사장으로 삼았으므로'),
    (9115, '여호와께서 일찍이 이 여러 백성에 대하여 이스라엘 자손에게 말씀하시기를 너희는 그들과 서로 통혼하지 말며 그들도 너희와 서로 통혼하게 하지 말라 그들이 반드시 너희의 마음을 돌려 그들의 신들을 따르게 하리라 하셨으나 솔로몬이 그들을 사랑하였더라'),
    (9117, '솔로몬의 나이가 많을 때에 그의 여인들이 그의 마음을 돌려 다른 신들을 따르게 하였으므로 왕의 마음이 그의 아버지 다윗의 마음과 같지 아니하여 그의 하나님 여호와 앞에 온전하지 못하였으니'),
    (9122, '○솔로몬이 마음을 돌려 이스라엘의 하나님 여호와를 떠나므로 여호와께서 그에게 진노하시니라 여호와께서 일찍이 두 번이나 그에게 나타나시고'),
    (9127, '<솔로몬의 대적> ○여호와께서 에돔 사람 하닷을 일으켜 솔로몬의 대적이 되게 하시니 그는 왕의 자손으로서 에돔에 거하였더라'),
    (9136, '○하나님이 또 엘리아다의 아들 르손을 일으켜 솔로몬의 대적자가 되게 하시니 그는 그의 주인 소바 왕 하닷에셀에게서 도망한 자라'),
    (9139, '<여로보암에게 하신 여호와의 말씀> ○솔로몬의 신하 느밧의 아들 여로보암이 또한 손을 들어 왕을 대적하였으니 그는 에브라임 족속인 스레다 사람이요 그의 어머니의 이름은 스루아이니 과부더라'),
    (9146, '이는 그들이 나를 버리고 시돈 사람의 여신 아스다롯과 모압의 신 그모스와 암몬 자손의 신 밀곰을 경배하며 그의 아버지 다윗이 행함 같지 아니하여 내 길로 행하지 아니하며 나 보기에 정직한 일과 내 법도와 내 율례를 행하지 아니함이니라'),
    (9151, '네가 만일 내가 명령한 모든 일에 순종하고 내 길로 행하며 내 눈에 합당한 일을 하며 내 종 다윗이 행함 같이 내 율례와 명령을 지키면 내가 너와 함께 있어 내가 다윗을 위하여 세운 것 같이 너를 위하여 견고한 집을 세우고 이스라엘을 네게 주리라'),
    (9152, '내가 이로 말미암아 다윗의 자손을 괴롭게 할 것이나 영원히 하지는 아니하리라 하셨느니라 한지라'),
    (9154, '<솔로몬이 죽다> ○솔로몬의 남은 사적과 그의 행한 모든 일과 그의 지혜는 솔로몬의 실록에 기록되지 아니하였느냐'),
    (9157, '<북쪽 지파들의 배반> 르호보암이 세겜으로 갔으니 이는 온 이스라엘이 그를 왕으로 삼고자 하여 세겜에 이르렀음이더라'),
    (9162, '○르호보암 왕이 그의 아버지 솔로몬의 생전에 그 앞에 모셨던 노인들과 의논하여 이르되 너희는 어떻게 충고하여 이 백성에게 대답하게 하겠느냐'),
    (9166, '함께 자라난 소년들이 왕께 아뢰어 이르되 이 백성들이 왕께 아뢰기를 왕의 부친이 우리의 멍에를 무겁게 하였으나 왕은 우리를 위하여 가볍게 하라 하였은즉 왕은 대답하기를 내 새끼 손가락이 내 아버지의 허리보다 굵으니'),
    (9168, '○삼 일 만에 여로보암과 모든 백성이 르호보암에게 나아왔으니 이는 왕이 명령하여 이르기를 삼 일 만에 내게로 다시 오라 하였음이라'),
    (9170, '어린 사람들의 자문을 따라 그들에게 말하여 이르되 내 아버지는 너희의 멍에를 무겁게 하였으나 나는 너희의 멍에를 더욱 무겁게 할지라 내 아버지는 채찍으로 너희를 징계하였으나 나는 전갈 채찍으로 너희를 징치하리라 하니라'),
    (9172, '○온 이스라엘이 자기들의 말을 왕이 듣지 아니함을 보고 왕에게 대답하여 이르되 우리가 다윗과 무슨 관계가 있느냐 이새의 아들에게서 받을 유산이 없도다 이스라엘아 너희의 장막으로 돌아가라 다윗이여 이제 너는 네 집이나 돌아보라 하고 이스라엘이 그 장막으로 돌아가니라'),
    (9177, '<스마야가 여호와의 말씀을 전하다> ○르호보암이 예루살렘에 이르러 유다 온 족속과 베냐민 지파를 모으니 택한 용사가 십팔만 명이라 이스라엘 족속과 싸워 나라를 회복하여 솔로몬의 아들 르호보암에게 돌리려 하더니'),
    (9180, '여호와의 말씀이 너희는 올라가지 말라 너희 형제 이스라엘 자손과 싸우지 말고 각기 집으로 돌아가라 이 일이 나로 말미암아 난 것이라 하셨다 하라 하신지라 그들이 여호와의 말씀을 듣고 그 말씀을 따라 돌아갔더라'),
    (9181, '<여로보암이 금송아지를 만들다> ○여로보암이 에브라임 산지에 세겜을 건축하고 거기서 살며 또 거기서 나가서 부느엘을 건축하고'),
    (9183, '만일 이 백성이 예루살렘에 있는 여호와의 성전에 제사를 드리고자 하여 올라가면 이 백성의 마음이 유다 왕 된 그들의 주 르호보암에게로 돌아가서 나를 죽이고 유다의 왕 르호보암에게로 돌아가리로다 하고'),
    (9188, '여덟째 달 곧 그 달 열다섯째 날로 절기를 정하여 유다의 절기와 비슷하게 하고 제단에 올라가되 벧엘에서 그와 같이 행하여 그가 만든 송아지에게 제사를 드렸으며 그가 지은 산당의 제사장을 벧엘에서 세웠더라'),
    (9323, '<엘리야와 가뭄> 길르앗에 우거하는 자 중에 디셉 사람 엘리야가 아합에게 말하되 내가 섬기는 이스라엘의 하나님 여호와께서 살아 계심을 두고 맹세하노니 내 말이 없으면 수 년 동안 비도 이슬도 있지 아니하리라 하니라'),
    (9330, '<엘리야와 사르밧 과부> ○여호와의 말씀이 엘리야에게 임하여 이르시되'),
    (9334, '그가 이르되 당신의 하나님 여호와께서 살아 계심을 두고 맹세하노니 나는 떡이 없고 다만 통에 가루 한 움큼과 병에 기름 조금 뿐이라 내가 나뭇가지 둘을 주워다가 나와 내 아들을 위하여 음식을 만들어 먹고 그 후에는 죽으리라'),
    (9339, '○이 일 후에 그 집 주인 되는 여인의 아들이 병들어 증세가 심히 위중하다가 숨이 끊어진지라'),
    (9225, '여로보암이 자기 아내에게 이르되 청하건대 일어나 변장하여 사람들이 그대가 여로보암의 아내임을 알지 못하게 하고 실로로 가라 거기 선지자 아히야가 있나니 그는 이전에 내가 이 백성의 왕이 될 것을 내게 말한 사람이니라'),
    (9229, '○그가 문으로 들어올 때에 아히야가 그 발소리를 듣고 말하되 여로보암의 아내여 들어오라 네가 어찌하여 다른 사람인 체하느냐 내가 명령을 받아 흉한 일을 네게 전하리니'),
    (9233, '그러므로 내가 여로보암의 집에 재앙을 내려 여로보암에게 속한 사내는 이스라엘 가운데 매인 자나 놓인 자나 다 끊어 버리되 거름 더미를 쓸어 버림 같이 여로보암의 집을 말갛게 쓸어 버릴지라'),
    (9236, '온 이스라엘이 그를 위하여 슬퍼하며 장사하려니와 여로보암에게 속한 자는 오직 이 아이만 묘실에 들어가리니 이는 여로보암의 집 가운데에서 그가 이스라엘의 하나님 여호와를 향하여 선한 뜻을 품었음이니라'),
    (9238, '여호와께서 이스라엘을 쳐서 물에서 흔들리는 갈대 같이 되게 하시고 이스라엘을 그의 조상들에게 주신 이 좋은 땅에서 뽑아 그들을 강 너머로 흩으시리니 그들이 아세라 상을 만들어 여호와를 진노하게 하였음이니라'),
    (9240, '○여로보암의 아내가 일어나 디르사로 돌아가서 집 문지방에 이를 때에 그 아이가 죽은지라'),
    (9242, '<여로보암의 죽음> ○여로보암의 그 남은 행적 곧 그가 어떻게 싸웠는지와 어떻게 다스렸는지는 이스라엘 왕 역대지략에 기록되니라'),
    (9244, '<유다 왕 르호보암> ○솔로몬의 아들 르호보암은 유다 왕이 되었으니 르호보암이 왕위에 오를 때에 나이가 사십일 세라 여호와께서 자기 이름을 두시려고 이스라엘 모든 지파 가운데에서 택하신 성읍 예루살렘에서 십칠 년 동안 다스리니라 그의 어머니의 이름은 나아마요 암몬 사람이더라'),
    (9248, '○르호보암 왕 제오년에 애굽의 왕 시삭이 올라와서 예루살렘을 치고'),
    (9252, '○르호보암의 남은 사적과 그가 행한 모든 일은 유다 왕 역대지략에 기록되지 아니하였느냐'),
    (9293, '○바아사의 남은 사적과 행한 모든 일과 권세는 이스라엘 왕 역대지략에 기록되지 아니하였느냐'),
    (9295, '여호와의 말씀이 하나니의 아들 선지자 예후에게도 임하사 바아사와 그의 집을 꾸짖으심은 그가 여로보암의 집과 같이 여호와 보시기에 모든 악을 행하며 그의 손의 행위로 여호와를 노엽게 하였음이며 또 그의 집을 쳤음이더라'),
    (9296, '<이스라엘 왕 엘라> ○유다의 아사 왕 제이십육년에 바아사의 아들 엘라가 디르사에서 이스라엘의 왕이 되어 이 년 동안 그 왕위에 있으니라'),
    (9303, '<이스라엘 왕 시므리> ○유다의 아사 왕 제이십칠년에 시므리가 디르사에서 칠 일 동안 왕이 되니라 그 때에 백성들이 블레셋 사람에게 속한 깁브돈을 향하여 진을 치고 있더니'),
    (9309, '<이스라엘 왕 오므리> ○그 때에 이스라엘 백성이 둘로 나뉘어 그 절반은 기낫의 아들 디브니를 따라 그를 왕으로 삼으려 하고 그 절반은 오므리를 따랐더니'),
    (9317, '<이스라엘 왕 아합> ○유다의 아사 왕 제삼십팔년에 오므리의 아들 아합이 이스라엘의 왕이 되니라 오므리의 아들 아합이 사마리아에서 이십이 년 동안 이스라엘을 다스리니라'),
    (9322, '그 시대에 벧엘 사람 히엘이 여리고를 건축하였는데 그가 그 터를 쌓을 때에 맏아들 아비람을 잃었고 그 성문을 세울 때에 막내 아들 스굽을 잃었으니 여호와께서 눈의 아들 여호수아를 통하여 하신 말씀과 같이 되었더라'),
    (9255, '<유다 왕 아비얌> 느밧의 아들 여로보암 왕 열여덟째 해에 아비얌이 유다 왕이 되고'),
    (9263, '<유다 왕 아사> ○이스라엘의 여로보암 왕 제이십년에 아사가 유다 왕이 되어'),
    (9270, '○아사와 이스라엘의 왕 바아사 사이에 일생 동안 전쟁이 있으니라'),
    (9273, '나와 당신 사이에 약조가 있고 내 아버지와 당신의 아버지 사이에도 있었느니라 내가 당신에게 은금 예물을 보냈으니 와서 이스라엘의 왕 바아사와 세운 약조를 깨뜨려서 그가 나를 떠나게 하라 하매'),
    (9277, '○아사의 남은 사적과 모든 권세와 그가 행한 모든 일과 성읍을 건축한 일이 유다 왕 역대지략에 기록되지 아니하였느냐 그러나 그는 늘그막에 발에 병이 들었더라'),
    (9279, '<이스라엘 왕 나답> ○유다의 아사 왕 둘째 해에 여로보암의 아들 나답이 이스라엘 왕이 되어 이 년 동안 이스라엘을 다스리니라'),
    (9287, '<이스라엘 왕 바아사> ○유다의 아사 왕 셋째 해에 아히야의 아들 바아사가 디르사에서 모든 이스라엘의 왕이 되어 이십사 년 동안 다스리니라'),
    (9394, '이세벨이 사신을 엘리야에게 보내어 이르되 내가 내일 이맘때에는 반드시 네 생명을 저 사람들 중 한 사람의 생명과 같게 하리라 그렇게 하지 아니하면 신들이 내게 벌 위에 벌을 내림이 마땅하니라 한지라'),
    (9396, '자기 자신은 광야로 들어가 하룻길쯤 가서 한 로뎀 나무 아래에 앉아서 자기가 죽기를 원하여 이르되 여호와여 넉넉하오니 지금 내 생명을 거두시옵소서 나는 내 조상들보다 낫지 못하니이다 하고'),
    (9401, '○엘리야가 그 곳 굴에 들어가 거기서 머물더니 여호와의 말씀이 그에게 임하여 이르시되 엘리야야 네가 어찌하여 여기 있느냐'),
    (9402, '그가 대답하되 내가 만군의 하나님 여호와께 열심이 유별하오니 이는 이스라엘 자손이 주의 언약을 버리고 주의 제단을 헐며 칼로 주의 선지자들을 죽였음이오며 오직 나만 남았거늘 그들이 내 생명을 찾아 빼앗으려 하나이다'),
    (9403, '여호와께서 이르시되 너는 나가서 여호와 앞에서 산에 서라 하시더니 여호와께서 지나가시는데 여호와 앞에 크고 강한 바람이 산을 가르고 바위를 부수나 바람 가운데에 여호와께서 계시지 아니하며 바람 후에 지진이 있으나 지진 가운데에도 여호와께서 계시지 아니하며'),
    (9406, '그가 대답하되 내가 만군의 하나님 여호와께 열심이 유별하오니 이는 이스라엘 자손이 주의 언약을 버리고 주의 제단을 헐며 칼로 주의 선지자들을 죽였음이오며 오직 나만 남았거늘 그들이 내 생명을 찾아 빼앗으려 하나이다'),
    (9407, '○여호와께서 그에게 이르시되 너는 네 길을 돌이켜 광야를 통하여 다메섹에 가서 이르거든 하사엘에게 기름을 부어 아람의 왕이 되게 하고'),
    (9411, '<엘리야가 엘리사를 부르다> ○엘리야가 거기서 떠나 사밧의 아들 엘리사를 만나니 그가 열두 겨릿소를 앞세우고 밭을 가는데 자기는 열두째 겨릿소와 함께 있더라 엘리야가 그리로 건너가서 겉옷을 그의 위에 던졌더니'),
    (9412, '그가 소를 버리고 엘리야에게로 달려가서 이르되 청하건대 나를 내 부모와 입맞추게 하소서 그리한 후에 내가 당신을 따르리이다 엘리야가 그에게 이르되 돌아가라 내가 네게 어떻게 행하였느냐 하니라'),
    (9458, '아합이 나봇에게 말하여 이르되 네 포도원이 내 왕궁 곁에 가까이 있으니 내게 주어 채소 밭을 삼게 하라 내가 그 대신에 그보다 더 아름다운 포도원을 네게 줄 것이요 만일 네가 좋게 여기면 그 값을 돈으로 네게 주리라'),
    (9462, '왕이 그에게 이르되 내가 이스르엘 사람 나봇에게 말하여 이르기를 네 포도원을 내게 주되 돈으로 바꾸거나 만일 네가 좋아하면 내가 그 대신에 포도원을 네게 주리라 한즉 그가 대답하기를 내가 내 포도원을 네게 주지 아니하겠노라 하기 때문이로다'),
    (9467, '○그의 성읍 사람 곧 그의 성읍에 사는 장로와 귀족들이 이세벨의 지시 곧 그가 자기들에게 보낸 편지에 쓴 대로 하여'),
    (9471, '이세벨이 나봇이 돌에 맞아 죽었다 함을 듣고 이세벨이 아합에게 이르되 일어나 그 이스르엘 사람 나봇이 돈으로 바꾸어 주기를 싫어하던 나봇의 포도원을 차지하소서 나봇이 살아 있지 아니하고 죽었나이다'),
    (9473, '○여호와의 말씀이 디셉 사람 엘리야에게 임하여 이르시되'),
    (9475, '너는 그에게 말하여 이르기를 여호와의 말씀이 네가 죽이고 또 빼앗았느냐고 하셨다 하고 또 그에게 이르기를 여호와의 말씀이 개들이 나봇의 피를 핥은 곳에서 개들이 네 피 곧 네 몸의 피도 핥으리라 하였다 하라'),
    (9483, '○아합이 이 모든 말씀을 들을 때에 그의 옷을 찢고 굵은 베로 몸을 동이고 금식하고 굵은 베에 누우며 또 풀이 죽어 다니더라'),
    (9353, '○오바댜가 길에 있을 때에 엘리야가 그를 만난지라 그가 알아보고 엎드려 말하되 내 주 엘리야여 당신이시니이까'),
    (9356, '당신의 하나님 여호와께서 살아 계심을 두고 맹세하노니 내 주께서 사람을 보내어 당신을 찾지 아니한 족속이나 나라가 없었는데 그들이 말하기를 엘리야가 없다 하면 그 나라와 그 족속으로 당신을 보지 못하였다는 맹세를 하게 하였거늘'),
    (9358, '내가 당신을 떠나간 후에 여호와의 영이 내가 알지 못하는 곳으로 당신을 이끌어 가시리니 내가 가서 아합에게 말하였다가 그가 당신을 찾지 못하면 내가 죽임을 당하리이다 당신의 종은 어려서부터 여호와를 경외하는 자라'),
    (9362, '○오바댜가 가서 아합을 만나 그에게 말하매 아합이 엘리야를 만나러 가다가'),
    (9366, '○아합이 이에 이스라엘의 모든 자손에게로 사람을 보내 선지자들을 갈멜 산으로 모으니라'),
    (9367, '엘리야가 모든 백성에게 가까이 나아가 이르되 너희가 어느 때까지 둘 사이에서 머뭇머뭇 하려느냐 여호와가 만일 하나님이면 그를 따르고 바알이 만일 하나님이면 그를 따를지니라 하니 백성이 말 한마디도 대답하지 아니하는지라'),
    (9371, '○엘리야가 바알의 선지자들에게 이르되 너희는 많으니 먼저 송아지 한 마리를 택하여 잡고 너희 신의 이름을 부르라 그러나 불을 붙이지 말라'),
    (9372, '그들이 받은 송아지를 가져다가 잡고 아침부터 낮까지 바알의 이름을 불러 이르되 바알이여 우리에게 응답하소서 하나 아무 소리도 없고 아무 응답하는 자도 없으므로 그들이 그 쌓은 제단 주위에서 뛰놀더라'),
    (9373, '정오에 이르러는 엘리야가 그들을 조롱하여 이르되 큰 소리로 부르라 그는 신인즉 묵상하고 있는지 혹은 그가 잠깐 나갔는지 혹은 그가 길을 행하는지 혹은 그가 잠이 들어서 깨워야 할 것인지 하매'),
    (9376, '○엘리야가 모든 백성을 향하여 이르되 내게로 가까이 오라 백성이 다 그에게 가까이 가매 그가 무너진 여호와의 제단을 수축하되'),
    (9382, '저녁 소제 드릴 때에 이르러 선지자 엘리야가 나아가서 말하되 아브라함과 이삭과 이스라엘의 하나님 여호와여 주께서 이스라엘 중에서 하나님이신 것과 내가 주의 종인 것과 내가 주의 말씀대로 이 모든 일을 행하는 것을 오늘 알게 하옵소서'),
    (9387, '<가뭄이 그침> ○엘리야가 아합에게 이르되 올라가서 먹고 마시소서 큰 비 소리가 있나이다'),
    (8991, '<언약궤를 성전으로 옮기다> 이에 솔로몬이 여호와의 언약궤를 다윗 성 곧 시온에서 메어 올리고자 하여 이스라엘 장로와 모든 지파의 우두머리 곧 이스라엘 자손의 족장들을 예루살렘에 있는 자기에게로 소집하니'),
    (8996, '제사장들이 여호와의 언약궤를 그 처소로 메어 들였으니 곧 성전의 내소인 지성소 그룹들의 날개 아래라'),
    (9002, '<솔로몬의 연설> ○그 때에 솔로몬이 이르되 여호와께서 캄캄한 데 계시겠다 말씀하셨사오나'),
    (9006, '내가 내 백성 이스라엘을 애굽에서 인도하여 낸 날부터 내 이름을 둘 만한 집을 건축하기 위하여 이스라엘 모든 지파 가운데에서 아무 성읍도 택하지 아니하고 다만 다윗을 택하여 내 백성 이스라엘을 다스리게 하였노라 하신지라'),
    (9010, '이제 여호와께서 말씀하신 대로 이루시도다 내가 여호와께서 말씀하신 대로 내 아버지 다윗을 이어서 일어나 이스라엘의 왕위에 앉고 이스라엘의 하나님 여호와의 이름을 위하여 성전을 건축하고'),
    (9012, '<솔로몬의 기도> ○솔로몬이 여호와의 제단 앞에서 이스라엘의 온 회중과 마주서서 하늘을 향하여 손을 펴고'),
    (9015, '이스라엘의 하나님 여호와여 주께서 주의 종 내 아버지 다윗에게 말씀하시기를 네 자손이 자기 길을 삼가서 네가 내 앞에서 행한것 같이 내 앞에서 행하기만 하면 네게서 나서 이스라엘의 왕위에 앉을 사람이 내 앞에서 끊어지지 아니하리라 하셨사오니 이제 다윗을 위하여 그 하신 말씀을 지키시옵소서'),
    (9017, '○하나님이 참으로 땅에 거하시리이까 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까'),
    (9021, '○만일 어떤 사람이 그 이웃에게 범죄함으로 맹세시킴을 받고 그가 와서 이 성전에 있는 주의 제단 앞에서 맹세하거든'),
    (9022, '주는 하늘에서 들으시고 행하시되 주의 종들을 심판하사 악한 자의 죄를 정하여 그 행위대로 그 머리에 돌리시고 의로운 자를 의롭다 하사 그의 의로운 바대로 갚으시옵소서'),
    (9023, '○만일 주의 백성 이스라엘이 주께 범죄하여 적국 앞에 패하게 되므로 주께로 돌아와서 주의 이름을 인정하고 이 성전에서 주께 기도하며 간구하거든'),
    (9025, '○만일 그들이 주께 범죄함으로 말미암아 하늘이 닫히고 비가 없어서 주께 벌을 받을 때에 이 곳을 향하여 기도하며 주의 이름을 찬양하고 그들의 죄에서 떠나거든'),
    (9027, '○만일 이 땅에 기근이나 전염병이 있거나 곡식이 시들거나 깜부기가 나거나 메뚜기나 황충이 나거나 적국이 와서 성읍을 에워싸거나 무슨 재앙이나 무슨 질병이 있든지 막론하고'),
    (9031, '○또 주의 백성 이스라엘에 속하지 아니한 자 곧 주의 이름을 위하여 먼 지방에서 온 이방인이라도'),
    (9033, '주는 계신 곳 하늘에서 들으시고 이방인이 주께 부르짖는 대로 이루사 땅의 만민이 주의 이름을 알고 주의 백성 이스라엘처럼 경외하게 하시오며 또 내가 건축한 이 성전을 주의 이름으로 일컫는 줄을 알게 하옵소서'),
    (9034, '○주의 백성이 그들의 적국과 더불어 싸우고자 하여 주께서 보내신 길로 나갈 때에 그들이 주께서 택하신 성읍과 내가 주의 이름을 위하여 건축한 성전이 있는 쪽을 향하여 여호와께 기도하거든'),
    (9036, '○범죄하지 아니하는 사람이 없사오니 그들이 주께 범죄함으로 주께서 그들에게 진노하사 그들을 적국에게 넘기시매 적국이 그들을 사로잡아 원근을 막론하고 적국의 땅으로 끌어간 후에'),
    (9038, '자기를 사로잡아 간 적국의 땅에서 온 마음과 온 뜻으로 주께 돌아와서 주께서 그들의 조상들에게 주신 땅 곧 주께서 택하신 성읍과 내가 주의 이름을 위하여 건축한 성전 있는 쪽을 향하여 주께 기도하거든'),
    (9044, '<솔로몬의 축복> ○솔로몬이 무릎을 꿇고 손을 펴서 하늘을 향하여 이 기도와 간구로 여호와께 아뢰기를 마치고 여호와의 제단 앞에서 일어나'),
    (9052, '<성전 봉헌식> ○이에 왕과 및 왕과 함께 한 이스라엘이 다 여호와 앞에 희생제물을 드리니라'),
    (9054, '그 날에 왕이 여호와의 성전 앞뜰 가운데를 거룩히 구별하고 거기서 번제와 소제와 감사제물의 기름을 드렸으니 이는 여호와의 앞 놋제단이 작으므로 번제물과 소제물과 화목제의 기름을 다 용납할 수 없음이라'),
    (9056, '여덟째 날에 솔로몬이 백성을 돌려보내매 백성이 왕을 위하여 축복하고 자기 장막으로 돌아가는데 여호와께서 그의 종 다윗과 그의 백성 이스라엘에게 베푸신 모든 은혜로 말미암아 기뻐하며 마음에 즐거워하였더라'),
    (9420, '이에 이스라엘 왕이 나라의 장로를 다 불러 이르되 너희는 이 사람이 악을 도모하고 있는 줄을 자세히 알라 그가 내 아내들과 내 자녀들과 내 은금을 빼앗으려고 사람을 내게 보냈으나 내가 거절하지 못하였노라'),
    (9422, '그러므로 왕이 벤하닷의 사신들에게 이르되 너희는 내 주 왕께 말하기를 왕이 처음에 보내 종에게 구하신 것은 내가 다 그대로 하려니와 이것은 내가 할 수 없나이다 하라 하니 사자들이 돌아가서 보고하니라'),
    (9426, '○한 선지자가 이스라엘의 아합 왕에게 나아가서 이르되 여호와의 말씀이 네가 이 큰 무리를 보느냐 내가 오늘 그들을 네 손에 넘기리니 너는 내가 여호와인 줄을 알리라 하셨나이다'),
    (9429, '○그들이 정오에 나가니 벤하닷은 장막에서 돕는 왕 삼십이 명과 더불어 마시고 취한 중이라'),
    (9435, '<아람 군대의 두 번째 공격> ○그 선지자가 이스라엘 왕에게 나아와 이르되 왕은 가서 힘을 기르고 왕께서 행할 일을 알고 준비하소서 해가 바뀌면 아람 왕이 왕을 치러 오리이다 하니라'),
    (9438, '또 왕의 잃어버린 군대와 같은 군대를 왕을 위하여 보충하고 말은 말대로, 병거는 병거대로 보충하고 우리가 평지에서 그들과 싸우면 반드시 그들보다 강하리이다 왕이 그 말을 듣고 그리하니라'),
    (9439, '○해가 바뀌니 벤하닷이 아람 사람을 소집하고 아벡으로 올라와서 이스라엘과 싸우려 하매'),
    (9441, '그 때에 하나님의 사람이 이스라엘 왕에게 나아와 말하여 이르되 여호와의 말씀에 아람 사람이 말하기를 여호와는 산의 신이요 골짜기의 신은 아니라 하는도다 그러므로 내가 이 큰 군대를 다 네 손에 넘기리니 너희는 내가 여호와인 줄을 알리라 하셨나이다 하니라'),
    (9444, '○그의 신하들이 그에게 말하되 우리가 들은즉 이스라엘 집의 왕들은 인자한 왕이라 하니 만일 우리가 굵은 베로 허리를 동이고 테두리를 머리에 쓰고 이스라엘의 왕에게로 나아가면 그가 혹시 왕의 생명을 살리리이다 하고'),
    (9445, '그들이 굵은 베로 허리를 동이고 테두리를 머리에 쓰고 이스라엘의 왕에게 이르러 이르되 왕의 종 벤하닷이 청하기를 내 생명을 살려 주옵소서 하더이다 아합이 이르되 그가 아직도 살아 있느냐 그는 내 형제이니라'),
    (9446, '그 사람들이 좋은 징조로 여기고 그 말을 얼른 받아 대답하여 이르되 벤하닷은 왕의 형제니이다 왕이 이르되 너희는 가서 그를 인도하여 오라 벤하닷이 이에 왕에게 나아오니 왕이 그를 병거에 올린지라'),
    (9447, '벤하닷이 왕께 아뢰되 내 아버지께서 당신의 아버지에게서 빼앗은 모든 성읍을 내가 돌려보내리이다 또 내 아버지께서 사마리아에서 만든 것 같이 당신도 다메섹에서 당신을 위하여 거리를 만드소서 아합이 이르되 내가 이 조약으로 인해 당신을 놓으리라 하고 이에 더불어 조약을 맺고 그를 놓았더라'),
    (9448, '<한 선지자가 아합을 규탄하다> ○선지자의 무리 중 한 사람이 여호와의 말씀을 그의 친구에게 이르되 너는 나를 치라 하였더니 그 사람이 치기를 싫어하는지라'),
    (9452, '왕이 지나갈 때에 그가 소리 질러 왕을 불러 이르되 종이 전장 가운데에 나갔더니 한 사람이 돌이켜 어떤 사람을 끌고 내게로 와서 말하기를 이 사람을 지키라 만일 그를 잃어 버리면 네 생명으로 그의 생명을 대신하거나 그렇지 아니하면 네가 은 한 달란트를 내어야 하리라 하였거늘'),
    (9541, '여호와의 사자가 디셉 사람 엘리야에게 이르되 너는 일어나 올라가서 사마리아 왕의 사자를 만나 그에게 이르기를 이스라엘에 하나님이 없어서 너희가 에그론의 신 바알세붑에게 물으러 가느냐'),
    (9543, '○사자들이 왕에게 돌아오니 왕이 그들에게 이르되 너희는 어찌하여 돌아왔느냐 하니'),
    (9544, '그들이 말하되 한 사람이 올라와서 우리를 만나 이르되 너희는 너희를 보낸 왕에게로 돌아가서 그에게 고하기를 여호와의 말씀이 이스라엘에 하나님이 없어서 네가 에그론의 신 바알세붑에게 물으려고 보내느냐 그러므로 네가 올라간 침상에서 내려오지 못할지라 네가 반드시 죽으리라 하셨다 하라 하더이다'),
    (9547, '○이에 오십부장과 그의 군사 오십 명을 엘리야에게로 보내매 그가 엘리야에게로 올라가 본즉 산 꼭대기에 앉아 있는지라 그가 엘리야에게 이르되 하나님의 사람이여 왕의 말씀이 내려오라 하셨나이다'),
    (9548, '엘리야가 오십부장에게 대답하여 이르되 내가 만일 하나님의 사람이면 불이 하늘에서 내려와 너와 너의 오십 명을 사를지로다 하매 불이 곧 하늘에서 내려와 그와 그의 군사 오십 명을 살랐더라'),
    (9550, '엘리야가 그들에게 대답하여 이르되 내가 만일 하나님의 사람이면 불이 하늘에서 내려와 너와 너의 오십 명을 사를지로다 하매 하나님의 불이 곧 하늘에서 내려와 그와 그의 군사 오십 명을 살랐더라'),
    (9551, '왕이 세 번째 오십부장과 그의 군사 오십 명을 보낸지라 셋째 오십부장이 올라가서 엘리야 앞에 이르러 그의 무릎을 꿇어 엎드려 간구하여 이르되 하나님의 사람이여 원하건대 나의 생명과 당신의 종인 이 오십 명의 생명을 당신은 귀히 보소서'),
    (9554, '말하되 여호와의 말씀이 네가 사자를 보내 에그론의 신 바알세붑에게 물으려 하니 이스라엘에 그의 말을 물을 만한 하나님이 안 계심이냐 그러므로 네가 그 올라간 침상에서 내려오지 못할지라 네가 반드시 죽으리라 하셨다 하니라'),
    (9555, '○왕이 엘리야가 전한 여호와의 말씀대로 죽고 그가 아들이 없으므로 여호람이 그를 대신하여 왕이 되니 유다 왕 여호사밧의 아들 여호람의 둘째 해였더라'),
    (9558, '엘리야가 엘리사에게 이르되 청하건대 너는 여기 머물라 여호와께서 나를 벧엘로 보내시느니라 하니 엘리사가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하는지라 이에 두 사람이 벧엘로 내려가니'),
    (9559, '벧엘에 있는 선지자의 제자들이 엘리사에게로 나아와 그에게 이르되 여호와께서 오늘 당신의 선생을 당신의 머리 위로 데려가실 줄을 아시나이까 하니 이르되 나도 또한 아노니 너희는 잠잠하라 하니라'),
    (9560, '엘리야가 그에게 이르되 엘리사야 청하건대 너는 여기 머물라 여호와께서 나를 여리고로 보내시느니라 엘리사가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하니라 그들이 여리고에 이르매'),
    (9562, '엘리야가 또 엘리사에게 이르되 청하건대 너는 여기 머물라 여호와께서 나를 요단으로 보내시느니라 하니 그가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하는지라 이에 두 사람이 가니라'),
    (9568, '○엘리사가 보고 소리 지르되 내 아버지여 내 아버지여 이스라엘의 병거와 그 마병이여 하더니 다시 보이지 아니하는지라 이에 엘리사가 자기의 옷을 잡아 둘로 찢고'),
    (9571, '○맞은편 여리고에 있는 선지자의 제자들이 그를 보며 말하기를 엘리야의 성령이 하시는 역사가 엘리사 위에 머물렀다 하고 가서 그에게로 나아가 땅에 엎드려 그에게 경배하고'),
    (9572, '그에게 이르되 당신의 종들에게 용감한 사람 오십 명이 있으니 청하건대 그들이 가서 당신의 주인을 찾게 하소서 염려하건대 여호와의 성령이 그를 들고 가다가 어느 산에나 어느 골짜기에 던지셨을까 하나이다 하니라 엘리사가 이르되 보내지 말라 하나'),
    (9575, '<엘리사의 기적> ○그 성읍 사람들이 엘리사에게 말하되 우리 주인께서 보시는 바와 같이 이 성읍의 위치는 좋으나 물이 나쁘므로 토산이 익지 못하고 떨어지나이다'),
    (9579, '○엘리사가 거기서 벧엘로 올라가더니 그가 길에서 올라갈 때에 작은 아이들이 성읍에서 나와 그를 조롱하여 이르되 대머리여 올라가라 대머리여 올라가라 하는지라'),
    (9585, '○모압 왕 메사는 양을 치는 자라 새끼 양 십만 마리의 털과 숫양 십만 마리의 털을 이스라엘 왕에게 바치더니'),
    (9588, '또 가서 유다의 왕 여호사밧에게 사신을 보내 이르되 모압 왕이 나를 배반하였으니 당신은 나와 함께 가서 모압을 치시겠느냐 하니 그가 이르되 내가 올라가리이다 나는 당신과 같고 내 백성은 당신의 백성과 같고 내 말들도 당신의 말들과 같으니이다 하는지라'),
    (9592, '여호사밧이 이르되 우리가 여호와께 물을 만한 여호와의 선지자가 여기 없느냐 하는지라 이스라엘 왕의 신하들 중의 한 사람이 대답하여 이르되 전에 엘리야의 손에 물을 붓던 사밧의 아들 엘리사가 여기 있나이다 하니'),
    (9594, '○엘리사가 이스라엘 왕에게 이르되 내가 당신과 무슨 상관이 있나이까 당신의 부친의 선지자들과 당신의 모친의 선지자들에게로 가소서 하니 이스라엘 왕이 그에게 이르되 그렇지 아니하니이다 여호와께서 이 세 왕을 불러 모아 모압의 손에 넘기려 하시나이다 하니라'),
    (9595, '엘리사가 이르되 내가 섬기는 만군의 여호와께서 살아 계심을 두고 맹세하노니 내가 만일 유다의 왕 여호사밧의 얼굴을 봄이 아니면 그 앞에서 당신을 향하지도 아니하고 보지도 아니하였으리이다'),
    (9602, '○모압의 모든 사람은 왕들이 올라와서 자기를 치려 한다 함을 듣고 갑옷 입을 만한 자로부터 그 이상이 다 모여 그 경계에 서 있더라'),
    (9486, '<선지자 미가야가 아합에게 경고하다> 아람과 이스라엘 사이에 전쟁이 없이 삼 년을 지냈더라'),
    (9489, '여호사밧에게 이르되 당신은 나와 함께 길르앗 라못으로 가서 싸우시겠느냐 여호사밧이 이스라엘 왕에게 이르되 나는 당신과 같고 내 백성은 당신의 백성과 같고 내 말들도 당신의 말들과 같으니이다'),
    (9490, '○여호사밧이 또 이스라엘의 왕에게 이르되 청하건대 먼저 여호와의 말씀이 어떠하신지 물어 보소서'),
    (9493, '이스라엘의 왕이 여호사밧 왕에게 이르되 아직도 이믈라의 아들 미가야 한 사람이 있으니 그로 말미암아 여호와께 물을 수 있으나 그는 내게 대하여 길한 일은 예언하지 아니하고 흉한 일만 예언하기로 내가 그를 미워하나이다 여호사밧이 이르되 왕은 그런 말씀을 마소서'),
    (9507, '여호와께서 그에게 이르시되 어떻게 하겠느냐 이르되 내가 나가서 거짓말하는 영이 되어 그의 모든 선지자들의 입에 있겠나이다 여호와께서 이르시되 너는 꾀겠고 또 이루리라 나가서 그리하라 하셨은즉'),
    (9509, '○그나아나의 아들 시드기야가 가까이 와서 미가야의 뺨을 치며 이르되 여호와의 영이 나를 떠나 어디로 가서 네게 말씀하시더냐'),
    (9514, '<아합의 죽음> ○이스라엘의 왕과 유다의 여호사밧 왕이 길르앗 라못으로 올라가니라'),
    (9522, '○왕이 이미 죽으매 그의 시체를 메어 사마리아에 이르러 왕을 사마리아에 장사하니라'),
    (9526, '<유다 왕 여호사밧> ○이스라엘의 아합 왕 제사년에 아사의 아들 여호사밧이 유다의 왕이 되니'),
    (9530, '○여호사밧의 남은 사적과 그가 부린 권세와 그가 어떻게 전쟁하였는지는 다 유다 왕 역대지략에 기록되지 아니하였느냐'),
    (9536, '<이스라엘 왕 아하시야> ○유다의 여호사밧 왕 제십칠년에 아합의 아들 아하시야가 사마리아에서 이스라엘의 왕이 되어 이 년 동안 이스라엘을 다스리니라'),
    (9660, '이스라엘 왕이 그 글을 읽고 자기 옷을 찢으며 이르되 내가 사람을 죽이고 살리는 하나님이냐 그가 어찌하여 사람을 내게로 보내 그의 나병을 고치라 하느냐 너희는 깊이 생각하고 저 왕이 틈을 타서 나와 더불어 시비하려 함인줄 알라 하니라'),
    (9661, '○하나님의 사람 엘리사가 이스라엘 왕이 자기의 옷을 찢었다 함을 듣고 왕에게 보내 이르되 왕이 어찌하여 옷을 찢었나이까 그 사람을 내게로 오게 하소서 그가 이스라엘 중에 선지자가 있는 줄을 알리이다 하니라'),
    (9668, '○나아만이 모든 군대와 함께 하나님의 사람에게로 도로 와서 그의 앞에 서서 이르되 내가 이제 이스라엘 외에는 온 천하에 신이 없는 줄을 아나이다 청하건대 당신의 종에게서 예물을 받으소서 하니'),
    (9670, '나아만이 이르되 그러면 청하건대 노새 두 마리에 실을 흙을 당신의 종에게 주소서 이제부터는 종이 번제물과 다른 희생제사를 여호와 외 다른 신에게는 드리지 아니하고 다만 여호와께 드리겠나이다'),
    (9671, '오직 한 가지 일이 있사오니 여호와께서 당신의 종을 용서하시기를 원하나이다 곧 내 주인께서 림몬의 신당에 들어가 거기서 경배하며 그가 내 손을 의지하시매 내가 림몬의 신당에서 몸을 굽히오니 내가 림몬의 신당에서 몸을 굽힐 때에 여호와께서 이 일에 대하여 당신의 종을 용서하시기를 원하나이다 하니'),
    (9673, '○하나님의 사람 엘리사의 사환 게하시가 스스로 이르되 내 주인이 이 아람 사람 나아만에게 면하여 주고 그가 가지고 온 것을 그의 손에서 받지 아니하였도다 여호와께서 살아 계심을 두고 맹세하노니 내가 그를 쫓아가서 무엇이든지 그에게서 받으리라 하고'),
    (9675, '그가 이르되 평안하나이다 우리 주인께서 나를 보내시며 말씀하시기를 지금 선지자의 제자 중에 두 청년이 에브라임 산지에서부터 내게로 왔으니 청하건대 당신은 그들에게 은 한 달란트와 옷 두 벌을 주라 하시더이다'),
    (9679, '엘리사가 이르되 한 사람이 수레에서 내려 너를 맞이할 때에 내 마음이 함께 가지 아니하였느냐 지금이 어찌 은을 받으며 옷을 받으며 감람원이나 포도원이나 양이나 소나 남종이나 여종을 받을 때이냐'),
    (9609, '<과부의 기름 그릇> 선지자의 제자들의 아내 중의 한 여인이 엘리사에게 부르짖어 이르되 당신의 종 나의 남편이 이미 죽었는데 당신의 종이 여호와를 경외한 줄은 당신이 아시는 바니이다 이제 빚 준 사람이 와서 나의 두 아이를 데려가 그의 종을 삼고자 하나이다 하니'),
    (9616, '<엘리사와 수넴 여인> ○하루는 엘리사가 수넴에 이르렀더니 거기에 한 귀한 여인이 그를 간권하여 음식을 먹게 하였으므로 엘리사가 그 곳을 지날 때마다 음식을 먹으러 그리로 들어갔더라'),
    (9621, '엘리사가 자기 사환에게 이르되 너는 그에게 이르라 네가 이같이 우리를 위하여 세심한 배려를 하는도다 내가 너를 위하여 무엇을 하랴 왕에게나 사령관에게 무슨 구할 것이 있느냐 하니 여인이 이르되 나는 내 백성 중에 거주하나이다 하니라'),
    (9625, '○여인이 과연 잉태하여 한 해가 지나 이 때쯤에 엘리사가 여인에게 말한 대로 아들을 낳았더라'),
    (9633, '드디어 갈멜 산으로 가서 하나님의 사람에게로 나아가니라 ○하나님의 사람이 멀리서 그를 보고 자기 사환 게하시에게 이르되 저기 수넴 여인이 있도다'),
    (9636, '산에 이르러 하나님의 사람에게 나아가서 그 발을 안은지라 게하시가 가까이 와서 그를 물리치고자 하매 하나님의 사람이 이르되 가만 두라 그의 영혼이 괴로워하지마는 여호와께서 내게 숨기시고 이르지 아니하셨도다 하니라'),
    (9638, '엘리사가 게하시에게 이르되 네 허리를 묶고 내 지팡이를 손에 들고 가라 사람을 만나거든 인사하지 말며 사람이 네게 인사할지라도 대답하지 말고 내 지팡이를 그 아이 얼굴에 놓으라 하는지라'),
    (9641, '○엘리사가 집에 들어가 보니 아이가 죽었는데 자기의 침상에 눕혔는지라'),
    (9647, '<두 가지 기적> ○엘리사가 다시 길갈에 이르니 그 땅에 흉년이 들었는데 선지자의 제자들이 엘리사의 앞에 앉은지라 엘리사가 자기 사환에게 이르되 큰 솥을 걸고 선지자의 제자들을 위하여 국을 끓이라 하매'),
    (9651, '○한 사람이 바알 살리사에서부터 와서 처음 만든 떡 곧 보리떡 이십 개와 또 자루에 담은 채소를 하나님의 사람에게 드린지라 그가 이르되 무리에게 주어 먹게 하라'),
    (9714, '엘리사가 이르되 여호와의 말씀을 들을지어다 여호와께서 이르시되 내일 이맘때에 사마리아 성문에서 고운 밀가루 한 스아를 한 세겔로 매매하고 보리 두 스아를 한 세겔로 매매하리라 하셨느니라'),
    (9715, '그 때에 왕이 그의 손에 의지하는 자 곧 한 장관이 하나님의 사람에게 대답하여 이르되 여호와께서 하늘에 창을 내신들 어찌 이런 일이 있으리요 하더라 엘리사가 이르되 네가 네 눈으로 보리라 그러나 그것을 먹지는 못하리라 하니라'),
    (9716, '<아람 군대가 도망하다> ○성문 어귀에 나병환자 네 사람이 있더니 그 친구에게 서로 말하되 우리가 어찌하여 여기 앉아서 죽기를 기다리랴'),
    (9717, '만일 우리가 성읍으로 가자고 말한다면 성읍에는 굶주림이 있으니 우리가 거기서 죽을 것이요 만일 우리가 여기서 머무르면 역시 우리가 죽을 것이라 그런즉 우리가 가서 아람 군대에게 항복하자 그들이 우리를 살려 두면 살 것이요 우리를 죽이면 죽을 것이라 하고'),
    (9719, '이는 주께서 아람 군대로 병거 소리와 말 소리와 큰 군대의 소리를 듣게 하셨으므로 아람 사람이 서로 말하기를 이스라엘 왕이 우리를 치려 하여 헷 사람의 왕들과 애굽 왕들에게 값을 주고 그들을 우리에게 오게 하였다 하고'),
    (9722, '○나병환자들이 그 친구에게 서로 말하되 우리가 이렇게 해서는 아니되겠도다 오늘은 아름다운 소식이 있는 날이거늘 우리가 침묵하고 있도다 만일 밝은 아침까지 기다리면 벌이 우리에게 미칠지니 이제 떠나 왕궁에 가서 알리자 하고'),
    (9725, '왕이 밤에 일어나 그의 신복들에게 이르되 아람 사람이 우리에게 행한 것을 내가 너희에게 알게 하노니 그들이 우리가 주린 것을 알고 있으므로 그 진영을 떠나서 들에 매복하고 스스로 이르기를 그들이 성읍에서 나오거든 우리가 사로잡고 성읍에 들어가겠다 한 것이니라 하니'),
    (9726, '그의 신하 중 한 사람이 대답하여 이르되 청하건대 아직 성중에 남아 있는 말 다섯 마리를 취하고 사람을 보내 정탐하게 하소서 그것들이 성중에 남아 있는 이스라엘 온 무리 곧 멸망한 이스라엘 온 무리와 같으니이다 하고'),
    (9688, '<아람 군대를 물리치다> ○그 때에 아람 왕이 이스라엘과 더불어 싸우며 그의 신복들과 의논하여 이르기를 우리가 아무데 아무데 진을 치리라 하였더니'),
    (9694, '○왕이 이에 말과 병거와 많은 군사를 보내매 그들이 밤에 가서 그 성읍을 에워쌌더라'),
    (9700, '○사마리아에 들어갈 때에 엘리사가 이르되 여호와여 이 무리의 눈을 열어서 보게 하옵소서 하니 여호와께서 그들의 눈을 여시매 그들이 보니 자기들이 사마리아 가운데에 있더라'),
    (9704, '<에워싸인 사마리아가 굶주리다> ○이 후에 아람 왕 벤하닷이 그의 온 군대를 모아 올라와서 사마리아를 에워싸니'),
    (9712, '그 때에 엘리사가 그의 집에 앉아 있고 장로들이 그와 함께 앉아 있는데 왕이 자기 처소에서 사람을 보냈더니 그 사자가 이르기 전에 엘리사가 장로들에게 이르되 너희는 이 살인한 자의 아들이 내 머리를 베려고 사람을 보내는 것을 보느냐 너희는 보다가 사자가 오거든 문을 닫고 문 안에 들이지 말라 그의 주인의 발소리가 그의 뒤에서 나지 아니하느냐 하고'),
    (9734, '<수넴 여인이 돌아오다> 엘리사가 이전에 아들을 다시 살려 준 여인에게 이르되 너는 일어나서 네 가족과 함께 거주할 만한 곳으로 가서 거주하라 여호와께서 기근을 부르셨으니 그대로 이 땅에 칠 년 동안 임하리라 하니'),
    (9738, '게하시가 곧 엘리사가 죽은 자를 다시 살린 일을 왕에게 이야기할 때에 그 다시 살린 아이의 어머니가 자기 집과 전토를 위하여 왕에게 호소하는지라 게하시가 이르되 내 주 왕이여 이는 그 여인이요 저는 그의 아들이니 곧 엘리사가 다시 살린 자니이다 하니라'),
    (9739, '왕이 그 여인에게 물으매 여인이 설명한지라 왕이 그를 위하여 한 관리를 임명하여 이르되 이 여인에게 속한 모든 것과 이 땅에서 떠날 때부터 이제까지 그의 밭의 소출을 다 돌려 주라 하였더라'),
    (9740, '<엘리사와 아람 왕 벤하닷> ○엘리사가 다메섹에 갔을 때에 아람 왕 벤하닷이 병들었더니 왕에게 들리기를 이르되 하나님의 사람이 여기 이르렀나이다 하니'),
    (9742, '하사엘이 그를 맞이하러 갈새 다메섹의 모든 좋은 물품으로 예물을 삼아 가지고 낙타 사십 마리에 싣고 나아가서 그의 앞에 서서 이르되 당신의 아들 아람 왕 벤하닷이 나를 당신에게 보내 이르되 나의 이 병이 낫겠나이까 하더이다 하니'),
    (9745, '하사엘이 이르되 내 주여 어찌하여 우시나이까 하는지라 대답하되 네가 이스라엘 자손에게 행할 모든 악을 내가 앎이라 네가 그들의 성에 불을 지르며 장정을 칼로 죽이며 어린 아이를 메치며 아이 밴 부녀를 가르리라 하니'),
    (9749, '<유다 왕 여호람> ○이스라엘의 왕 아합의 아들 요람 제오년에 여호사밧이 유다의 왕이었을 때에 유다의 왕 여호사밧의 아들 여호람이 왕이 되니라'),
    (9753, '○여호람 때에 에돔이 유다의 손에서 배반하여 자기 위에 왕을 세운 고로'),
    (9758, '<유다 왕 아하시야> ○이스라엘의 왕 아합의 아들 요람 제십이년에 유다 왕 여호람의 아들 아하시야가 왕이 되니'),
    (9762, '요람 왕이 아람 왕 하사엘과 싸울 때에 라마에서 아람 사람에게 당한 부상을 치료하려 하여 이스르엘로 돌아왔더라 유다의 왕 여호람의 아들 아하시야가 아합의 아들 요람을 보기 위하여 내려갔으니 이는 그에게 병이 생겼음이더라'),
    (9767, '그가 이르러 보니 군대 장관들이 앉아 있는지라 소년이 이르되 장관이여 내가 당신에게 할 말이 있나이다 예후가 이르되 우리 모든 사람 중에 누구에게 하려느냐 하니 이르되 장관이여 당신에게니이다 하는지라'),
    (9773, '○예후가 나와서 그의 주인의 신복들에게 이르니 한 사람이 그에게 묻되 평안하냐 그 미친 자가 무슨 까닭으로 그대에게 왔더냐 대답하되 그대들이 그 사람과 그가 말한 것을 알리라 하더라'),
    (9774, '무리가 이르되 당치 아니한 말이라 청하건대 그대는 우리에게 이르라 하니 대답하되 그가 이리 이리 내게 말하여 이르기를 여호와의 말씀이 내가 네게 기름을 부어 이스라엘 왕으로 삼는다 하셨다 하더라 하는지라'),
    (9776, '<이스라엘 왕 요람이 살해되다> ○이에 님시의 손자 여호사밧의 아들 예후가 요람을 배반하였으니 곧 요람이 온 이스라엘과 더불어 아람의 왕 하사엘과 맞서서 길르앗 라못을 지키다가'),
    (9777, '아람의 왕 하사엘과 더불어 싸울 때에 아람 사람에게 부상한 것을 치료하려 하여 이스르엘로 돌아왔던 때라 예후가 이르되 너희 뜻에 합당하거든 한 사람이라도 이 성에서 도망하여 이스르엘에 알리러 가지 못하게 하라 하니라'),
    (9779, '○이스르엘 망대에 파수꾼 하나가 서 있더니 예후의 무리가 오는 것을 보고 이르되 내가 한 무리를 보나이다 하니 요람이 이르되 한 사람을 말에 태워 보내어 맞이하여 평안하냐 묻게 하라 하는지라'),
    (9780, '한 사람이 말을 타고 가서 만나 이르되 왕의 말씀이 평안하냐 하시더이다 하매 예후가 이르되 평안이 네게 상관이 있느냐 내 뒤로 물러나라 하니라 파수꾼이 전하여 이르되 사자가 그들에게 갔으나 돌아오지 아니하나이다 하는지라'),
    (9783, '○요람이 이르되 메우라 하매 그의 병거를 메운지라 이스라엘 왕 요람과 유다 왕 아하시야가 각각 그의 병거를 타고 가서 예후를 맞을새 이스르엘 사람 나봇의 토지에서 만나매'),
    (9786, '예후가 힘을 다하여 활을 당겨 요람의 두 팔 사이를 쏘니 화살이 그의 염통을 꿰뚫고 나오매 그가 병거 가운데에 엎드러진지라'),
    (9787, '예후가 그의 장관 빗갈에게 이르되 그 시체를 가져다가 이스르엘 사람 나봇의 밭에 던지라 네가 기억하려니와 이전에 너와 내가 함께 타고 그의 아버지 아합을 좇았을 때에 여호와께서 이같이 그의 일을 예언하셨느니라'),
    (9788, '여호와께서 말씀하시기를 내가 어제 나봇의 피와 그의 아들들의 피를 분명히 보았노라 여호와께서 또 말씀하시기를 이 토지에서 네게 갚으리라 하셨으니 그런즉 여호와의 말씀대로 그의 시체를 가져다가 이 밭에 던질지니라 하는지라'),
    (9789, '<유다 왕 아하시야가 살해되다> ○유다의 왕 아하시야가 이를 보고 정원의 정자 길로 도망하니 예후가 그 뒤를 쫓아가며 이르되 그도 병거 가운데서 죽이라 하매 이블르암 가까운 구르 비탈에서 치니 그가 므깃도까지 도망하여 거기서 죽은지라'),
    (9791, '○아합의 아들 요람의 제십일년에 아하시야가 유다 왕이 되었었더라'),
    (9792, '<이세벨 왕후가 살해되다> ○예후가 이스르엘에 오니 이세벨이 듣고 눈을 그리고 머리를 꾸미고 창에서 바라보다가'),
    (9836, '<유다 여왕 아달랴> 아하시야의 어머니 아달랴가 그의 아들이 죽은 것을 보고 일어나 왕의 자손을 모두 멸절하였으나'),
    (9839, '○일곱째 해에 여호야다가 사람을 보내 가리 사람의 백부장들과 호위병의 백부장들을 불러 데리고 여호와의 성전으로 들어가서 그들과 언약을 맺고 그들에게 여호와의 성전에서 맹세하게 한 후에 왕자를 그들에게 보이고'),
    (9844, '○백부장들이 이에 제사장 여호야다의 모든 명령대로 행하여 각기 관할하는 바 안식일에 들어오는 자와 안식일에 나가는 자를 거느리고 제사장 여호야다에게 나아오매'),
    (9848, '○아달랴가 호위병과 백성의 소리를 듣고 여호와의 성전에 들어가 백성에게 이르러'),
    (9850, '제사장 여호야다가 군대를 거느린 백부장들에게 명령하여 이르되 그를 대열 밖으로 몰아내라 그를 따르는 자는 모두 칼로 죽이라 하니 제사장의 이 말은 여호와의 성전에서는 그를 죽이지 말라 함이라'),
    (9852, '<여호야다의 개혁> ○여호야다가 왕과 백성에게 여호와와 언약을 맺어 여호와의 백성이 되게 하고 왕과 백성 사이에도 언약을 세우게 하매'),
    (9853, '온 백성이 바알의 신당으로 가서 그 신당을 허물고 그 제단들과 우상들을 철저히 깨뜨리고 그 제단 앞에서 바알의 제사장 맛단을 죽이니라 제사장이 관리들을 세워 여호와의 성전을 수직하게 하고'),
    (9856, '○요아스가 왕이 될 때에 나이가 칠 세였더라'),
    (9800, '<아합의 아들들이 살해되다> 아합의 아들 칠십 명이 사마리아에 있는지라 예후가 편지들을 써서 사마리아에 보내서 이스르엘 귀족들 곧 장로들과 아합의 여러 아들을 교육하는 자들에게 전하니 일렀으되'),
    (9804, '그 왕궁을 책임지는 자와 그 성읍을 책임지는 자와 장로들과 왕자를 교육하는 자들이 예후에게 말을 전하여 이르되 우리는 당신의 종이라 당신이 말하는 모든 것을 우리가 행하고 어떤 사람이든지 왕으로 세우지 아니하리니 당신이 보기에 좋은 대로 행하라 한지라'),
    (9805, '예후가 다시 그들에게 편지를 부치니 일렀으되 만일 너희가 내 편이 되어 내 말을 너희가 들으려거든 너희 주의 아들된 사람들의 머리를 가지고 내일 이맘때에 이스르엘에 이르러 내게 나아오라 하였더라 왕자 칠십 명이 그 성읍의 귀족들, 곧 그들을 양육하는 자들과 함께 있는 중에'),
    (9811, '<아하시야 왕의 형제들이 살해되다> ○예후가 일어나서 사마리아로 가더니 도중에 목자가 양털 깎는 집에 이르러'),
    (9814, '<아합의 나머지 사람들이 살해되다> ○예후가 거기에서 떠나가다가 자기를 맞이하러 오는 레갑의 아들 여호나답을 만난지라 그의 안부를 묻고 그에게 이르되 내 마음이 네 마음을 향하여 진실함과 같이 네 마음도 진실하냐 하니 여호나답이 대답하되 그러하니이다 이르되 그러면 나와 손을 잡자 손을 잡으니 예후가 끌어 병거에 올리며'),
    (9817, '<바알을 섬기는 자들이 살해되다> ○예후가 뭇 백성을 모으고 그들에게 이르되 아합은 바알을 조금 섬겼으나 예후는 많이 섬기리라'),
    (9818, '그러므로 내가 이제 큰 제사를 바알에게 드리고자 하노니 바알의 모든 선지자와 모든 섬기는 자와 모든 제사장들을 한 사람도 빠뜨리지 말고 불러 내게로 나아오게 하라 모든 오지 아니하는 자는 살려 두지 아니하리라 하니 이는 예후가 바알 섬기는 자를 멸하려 하여 계책을 씀이라'),
    (9822, '예후가 레갑의 아들 여호나답과 더불어 바알의 신당에 들어가서 바알을 섬기는 자들에게 이르되 너희는 살펴보아 바알을 섬기는 자들만 여기 있게 하고 여호와의 종은 하나도 여기 너희 중에 있지 못하게 하라 하고'),
    (9823, '무리가 번제와 다른 제사를 드리려고 들어간 때에 예후가 팔십 명을 밖에 두며 이르되 내가 너희 손에 넘겨 주는 사람을 한 사람이라도 도망하게 하는 자는 자기의 생명으로 그 사람의 생명을 대신하리라 하니라'),
    (9824, '○번제 드리기를 다하매 예후가 호위병과 지휘관들에게 이르되 들어가서 한 사람도 나가지 못하게 하고 죽이라 하매 호위병과 지휘관들이 칼로 그들을 죽여 밖에 던지고'),
    (9829, '○여호와께서 예후에게 이르시되 네가 나보기에 정직한 일을 행하되 잘 행하여 내 마음에 있는 대로 아합 집에 다 행하였은즉 네 자손이 이스라엘 왕위를 이어 사대를 지내리라 하시니라'),
    (9831, '<예후가 죽다> ○이 때에 여호와께서 이스라엘에서 땅을 잘라 내기 시작하시매 하사엘이 이스라엘의 모든 영토에서 공격하되'),
    (9857, '<유다 왕 요아스> 예후의 제칠년에 요아스가 왕이 되어 예루살렘에서 사십 년간 통치하니라 그의 어머니의 이름은 시비아라 브엘세바 사람이더라'),
    (9860, '○요아스가 제사장들에게 이르되 여호와의 성전에 거룩하게 하여 드리는 모든 은 곧 사람이 통용하는 은이나 각 사람의 몸값으로 드리는 은이나 자원하여 여호와의 성전에 드리는 모든 은을'),
    (9863, '요아스 왕이 대제사장 여호야다와 제사장들을 불러 이르되 너희가 어찌하여 성전의 파손한 데를 수리하지 아니하였느냐 이제부터는 너희가 아는 사람에게서 은을 받지 말고 그들이 성전의 파손한 데를 위하여 드리게 하라'),
    (9865, '○제사장 여호야다가 한 궤를 가져다가 그것의 뚜껑에 구멍을 뚫어 여호와의 전문 어귀 오른쪽 곧 제단 옆에 두매 여호와의 성전에 가져 오는 모든 은을 다 문을 지키는 제사장들이 그 궤에 넣더라'),
    (9873, '○그 때에 아람 왕 하사엘이 올라와서 가드를 쳐서 점령하고 예루살렘을 향하여 올라오고자 하므로'),
    (9874, '유다의 왕 요아스가 그의 조상들 유다 왕 여호사밧과 여호람과 아하시야가 구별하여 드린 모든 성물과 자기가 구별하여 드린 성물과 여호와의 성전 곳간과 왕궁에 있는 금을 다 가져다가 아람 왕 하사엘에게 보냈더니 하사엘이 예루살렘에서 떠나갔더라'),
    (9875, '○요아스의 남은 사적과 그가 행한 모든 일은 유다 왕 역대지략에 기록되지 아니하였느냐'),
    (9887, '<이스라엘 왕 요아스> ○유다의 왕 요아스의 제삼십칠 년에 여호아하스의 아들 요아스가 사마리아에서 이스라엘 왕이 되어 십육 년간 다스리며'),
    (9891, '<엘리사가 죽다> ○엘리사가 죽을 병이 들매 이스라엘의 왕 요아스가 그에게로 내려와 자기의 얼굴에 눈물을 흘리며 이르되 내 아버지여 내 아버지여 이스라엘의 병거와 마병이여 하매'),
    (9894, '이르되 동쪽 창을 여소서 하여 곧 열매 엘리사가 이르되 쏘소서 하는지라 곧 쏘매 엘리사가 이르되 이는 여호와를 위한 구원의 화살 곧 아람에 대한 구원의 화살이니 왕이 아람 사람을 멸절하도록 아벡에서 치리이다 하니라'),
    (9897, '○엘리사가 죽으니 그를 장사하였고 해가 바뀌매 모압 도적 떼들이 그 땅에 온지라'),
    (9899, '<이스라엘과 아람의 전쟁> ○여호아하스 왕의 시대에 아람 왕 하사엘이 항상 이스라엘을 학대하였으나'),
    (9900, '여호와께서 아브라함과 이삭과 야곱과 더불어 세우신 언약 때문에 이스라엘에게 은혜를 베풀며 그들을 불쌍히 여기시며 돌보사 멸하기를 즐겨하지 아니하시고 이 때까지 자기 앞에서 쫓아내지 아니하셨더라'),
    (9902, '여호아하스의 아들 요아스가 하사엘의 아들 벤하닷의 손에서 성읍을 다시 빼앗으니 이 성읍들은 자기 부친 여호아하스가 전쟁 중에 빼앗겼던 것이라 요아스가 벤하닷을 세 번 쳐서 무찌르고 이스라엘 성읍들을 회복하였더라'),
    (9903, '<유다 왕 아마샤> 이스라엘의 왕 여호아하스의 아들 요아스 제이년에 유다의 왕 요아스의 아들 아마샤가 왕이 되니'),
    (9908, '왕을 죽인 자의 자녀들은 죽이지 아니하였으니 이는 모세의 율법책에 기록된 대로 함이라 곧 여호와께서 명령하여 이르시기를 자녀로 말미암아 아버지를 죽이지 말 것이요 아버지로 말미암아 자녀를 죽이지 말 것이라 오직 사람마다 자기의 죄로 말미암아 죽을 것이니라 하셨더라'),
    (9910, '○아마샤가 예후의 손자 여호아하스의 아들 이스라엘의 왕 요아스에게 사자를 보내 이르되 오라 우리가 서로 대면하자 한지라'),
    (9911, '이스라엘의 왕 요아스가 유다의 왕 아마샤에게 사람을 보내 이르되 레바논 가시나무가 레바논 백향목에게 전갈을 보내어 이르기를 네 딸을 내 아들에게 주어 아내로 삼게 하라 하였더니 레바논 들짐승이 지나가다가 그 가시나무를 짓밟았느니라'),
    (9917, '○요아스의 남은 사적과 그의 업적과 또 유다의 왕 아마샤와 싸운 일은 이스라엘 왕 역대지략에 기록되지 아니하였느냐'),
    (9919, '<유다 왕 아마샤가 죽다> ○이스라엘의 왕 여호아하스의 아들 요아스가 죽은 후에도 유다의 왕 요아스의 아들 아마샤가 십오 년간을 생존하였더라'),
    (9925, '<이스라엘 왕 여로보암 2세> ○유다의 왕 요아스의 아들 아마샤 제십오년에 이스라엘의 왕 요아스의 아들 여로보암이 사마리아에서 왕이 되어 사십일 년간 다스렸으며'),
    (9930, '○여로보암의 남은 사적과 모든 행한 일과 싸운 업적과 다메섹을 회복한 일과 이전에 유다에 속하였던 하맛을 이스라엘에 돌린 일은 이스라엘 왕 역대지략에 기록되지 아니하였느냐'),
    (9970, '<유다 왕 아하스> 르말랴의 아들 베가 제십칠년에 유다의 왕 요담의 아들 아하스가 왕이 되니'),
    (9974, '○이 때에 아람의 왕 르신과 이스라엘의 왕 르말랴의 아들 베가가 예루살렘에 올라와서 싸우려 하여 아하스를 에워쌌으나 능히 이기지 못하니라'),
    (9979, '○아하스 왕이 앗수르의 왕 디글랏 빌레셀을 만나러 다메섹에 갔다가 거기 있는 제단을 보고 아하스 왕이 그 제단의 모든 구조와 제도의 양식을 그려 제사장 우리야에게 보냈더니'),
    (9984, '아하스 왕이 제사장 우리야에게 명령하여 이르되 아침 번제물과 저녁 소제물과 왕의 번제물과 그 소제물과 모든 국민의 번제물과 그 소제물과 전제물을 다 이 큰 제단 위에 불사르고 또 번제물의 피와 다른 제물의 피를 다 그 위에 뿌리라 오직 놋제단은 내가 주께 여쭐 일에만 쓰게 하라 하매'),
    (9986, '○아하스 왕이 물두멍 받침의 옆판을 떼내고 물두멍을 그 자리에서 옮기고 또 놋바다를 놋소 위에서 내려다가 돌판 위에 그것을 두며'),
    (9932, '<유다 왕 아사랴> 이스라엘 왕 여로보암 제이십칠년에 유다 왕 아마샤의 아들 아사랴가 왕이 되니'),
    (9939, '<이스라엘 왕 스가랴> ○유다의 왕 아사랴의 제삼십팔년에 여로보암의 아들 스가랴가 사마리아에서 여섯 달 동안 이스라엘을 다스리며'),
    (9944, '<이스라엘 왕 살룸> ○유다 왕 웃시야 제삼십구년에 야베스의 아들 살룸이 사마리아에서 왕이 되어 한 달 동안 다스리니라'),
    (9947, '그 때에 므나헴이 디르사에서 와서 딥사와 그 가운데에 있는 모든 사람과 그 사방을 쳤으니 이는 그들이 성문을 열지 아니하였음이라 그러므로 그들이 그 곳을 치고 그 가운데에 아이 밴 부녀를 갈랐더라'),
    (9948, '<이스라엘 왕 므나헴> ○유다 왕 아사랴 제삼십구년에 가디의 아들 므나헴이 이스라엘 왕이 되어 사마리아에서 십 년간 다스리며'),
    (9954, '<이스라엘 왕 브가히야> ○유다의 왕 아사랴 제오십년에 므나헴의 아들 브가히야가 사마리아에서 이스라엘 왕이 되어 이 년간 다스리며'),
    (9958, '<이스라엘 왕 베가> ○유다의 왕 아사랴 제오십이년에 르말랴의 아들 베가가 이스라엘 왕이 되어 사마리아에서 이십 년간 다스리며'),
    (9960, '○이스라엘 왕 베가 때에 앗수르 왕 디글랏 빌레셀이 와서 이욘과 아벨벳 마아가와 야노아와 게데스와 하솔과 길르앗과 갈릴리와 납달리 온 땅을 점령하고 그 백성을 사로잡아 앗수르로 옮겼더라'),
    (9963, '<유다 왕 요담> ○이스라엘의 왕 르말랴의 아들 베가 제이년에 유다 왕 웃시야의 아들 요담이 왕이 되니'),
    (9968, '○그 때에 여호와께서 비로소 아람 왕 르신과 르말랴의 아들 베가를 보내어 유다를 치게 하셨더라'),
    (10031, '<유다 왕 히스기야> 이스라엘의 왕 엘라의 아들 호세아 제삼년에 유다 왕 아하스의 아들 히스기야가 왕이 되니'),
    (10039, '○히스기야 왕 제사년 곧 이스라엘의 왕 엘라의 아들 호세아 제칠년에 앗수르의 왕 살만에셀이 사마리아로 올라와서 에워쌌더라'),
    (10043, '<앗수르 사람들이 예루살렘을 위협하다> ○히스기야 왕 제십사년에 앗수르의 왕 산헤립이 올라와서 유다 모든 견고한 성읍들을 쳐서 점령하매'),
    (10044, '유다의 왕 히스기야가 라기스로 사람을 보내어 앗수르 왕에게 이르되 내가 범죄하였나이다 나를 떠나 돌아가소서 왕이 내게 지우시는 것을 내가 당하리이다 하였더니 앗수르 왕이 곧 은 삼백 달란트와 금 삼십 달란트를 정하여 유다 왕 히스기야에게 내게 한지라'),
    (10047, '○앗수르 왕이 다르단과 랍사리스와 랍사게로 하여금 대군을 거느리고 라기스에서부터 예루살렘으로 가서 히스기야 왕을 치게 하매 그들이 예루살렘으로 올라가니라 그들이 올라가서 윗못 수도 곁 곧 세탁자의 밭에 있는 큰 길에 이르러 서니라'),
    (10052, '너희가 내게 이르기를 우리는 우리 하나님 여호와를 의뢰하노라 하리라마는 히스기야가 그들의 산당들과 제단을 제거하고 유다와 예루살렘 사람에게 명령하기를 예루살렘 이 제단 앞에서만 예배하라 하지 아니하였느냐 하셨나니'),
    (10056, '힐기야의 아들 엘리야김과 셉나와 요아가 랍사게에게 이르되 우리가 알아듣겠사오니 청하건대 아람 말로 당신의 종들에게 말씀하시고 성 위에 있는 백성이 듣는 데서 유다 말로 우리에게 말씀하지 마옵소서'),
    (10057, '랍사게가 그에게 이르되 내 주께서 네 주와 네게만 이 말을 하라고 나를 보내신 것이냐 성 위에 앉은 사람들도 너희와 함께 자기의 대변을 먹게 하고 자기의 소변을 마시게 하신 것이 아니냐 하고'),
    (10062, '내가 장차 와서 너희를 한 지방으로 옮기리니 그 곳은 너희 본토와 같은 지방 곧 곡식과 포도주가 있는 지방이요 떡과 포도원이 있는 지방이요 기름 나는 감람과 꿀이 있는 지방이라 너희가 살고 죽지 아니하리라 히스기야가 너희를 설득하여 이르기를 여호와께서 우리를 건지시리라 하여도 히스기야에게 듣지 말라'),
    (10066, '○그러나 백성이 잠잠하고 한 마디도 그에게 대답하지 아니하니 이는 왕이 명령하여 대답하지 말라 하였음이라'),
    (10068, '<왕이 이사야의 충고를 듣고자 하다> 히스기야 왕이 듣고 그 옷을 찢고 굵은 베를 두르고 여호와의 전에 들어가서'),
    (10071, '랍사게가 그의 주 앗수르 왕의 보냄을 받고 와서 살아 계신 하나님을 비방하였으니 당신의 하나님 여호와께서 혹시 그의 말을 들으셨을지라 당신의 하나님 여호와께서 그 들으신 말 때문에 꾸짖으실 듯하니 당신은 이 남아 있는 자들을 위하여 기도하소서 하더이다 하니라'),
    (10075, '<앗수르가 또 위협하다> ○랍사게가 돌아가다가 앗수르 왕이 이미 라기스에서 떠났다 함을 듣고 립나로 가서 앗수르 왕을 만났으니 왕이 거기서 립나와 싸우는 중이더라'),
    (10081, '○히스기야가 사자의 손에서 편지를 받아보고 여호와의 성전에 올라가서 히스기야가 그 편지를 여호와 앞에 펴 놓고'),
    (10087, '<이사야가 왕에게 보낸 여호와의 말씀> ○아모스의 아들 이사야가 히스기야에게 보내 이르되 이스라엘 하나님 여호와의 말씀이 네가 앗수르 왕 산헤립 때문에 내게 기도하는 것을 내가 들었노라 하셨나이다'),
    (10090, '네가 사자들을 통하여 주를 비방하여 이르기를 내가 많은 병거를 거느리고 여러 산 꼭대기에 올라가며 레바논 깊은 곳에 이르러 높은 백향목과 아름다운 잣나무를 베고 내가 그 가장 먼 곳에 들어가며 그의 동산의 무성한 수풀에 이르리라'),
    (10096, '○또 네게 보일 징조가 이러하니 너희가 금년에는 스스로 자라난 것을 먹고 내년에는 그것에서 난 것을 먹되 제삼년에는 심고 거두며 포도원을 심고 그 열매를 먹으리라'),
    (10102, '<산헤립이 죽다> ○이 밤에 여호와의 사자가 나와서 앗수르 진영에서 군사 십팔만 오천 명을 친지라 아침에 일찍이 일어나 보니 다 송장이 되었더라'),
    (10105, '<히스기야의 발병과 회복> 그 때에 히스기야가 병들어 죽게 되매 아모스의 아들 선지자 이사야가 그에게 나아와서 그에게 이르되 여호와의 말씀이 너는 집을 정리하라 네가 죽고 살지 못하리라 하셨나이다'),
    (10109, '너는 돌아가서 내 백성의 주권자 히스기야에게 이르기를 왕의 조상 다윗의 하나님 여호와의 말씀이 내가 네 기도를 들었고 네 눈물을 보았노라 내가 너를 낫게 하리니 네가 삼 일 만에 여호와의 성전에 올라가겠고'),
    (10112, '○히스기야가 이사야에게 이르되 여호와께서 나를 낫게 하시고 삼 일 만에 여호와의 성전에 올라가게 하실 무슨 징표가 있나이까 하니'),
    (10116, '<바벨론에서 온 사자들> ○그 때에 발라단의 아들 바벨론의 왕 브로닥발라단이 히스기야가 병 들었다 함을 듣고 편지와 예물을 그에게 보낸지라'),
    (10117, '히스기야가 사자들의 말을 듣고 자기 보물고의 금은과 향품과 보배로운 기름과 그의 군기고와 창고의 모든 것을 다 사자들에게 보였는데 왕궁과 그의 나라 안에 있는 모든 것 중에서 히스기야가 그에게 보이지 아니한 것이 없더라'),
    (10120, '<히스기야가 죽다> ○이사야가 히스기야에게 이르되 여호와의 말씀을 들으소서'),
    (9996, '<앗수르 왕이 사마리아를 차지하다> ○이 일은 이스라엘 자손이 자기를 애굽 땅에서 인도하여 내사 애굽의 왕 바로의 손에서 벗어나게 하신 그 하나님 여호와께 죄를 범하고 또 다른 신들을 경외하며'),
    (10002, '여호와께서 각 선지자와 각 선견자를 통하여 이스라엘과 유다에게 지정하여 이르시기를 너희는 돌이켜 너희 악한 길에서 떠나 나의 명령과 율례를 지키되 내가 너희 조상들에게 명령하고 또 내 종 선지자들을 통하여 너희에게 전한 모든 율법대로 행하라 하셨으나'),
    (10008, '○유다도 그들의 하나님 여호와의 명령을 지키지 아니하고 이스라엘 사람들이 만든 관습을 행하였으므로'),
    (10013, '<앗수르 사람들이 사마리아에 거주하다> ○앗수르 왕이 바벨론과 구다와 아와와 하맛과 스발와임에서 사람을 옮겨다가 이스라엘 자손을 대신하여 사마리아 여러 성읍에 두매 그들이 사마리아를 차지하고 그 여러 성읍에 거주하니라'),
    (10015, '그러므로 어떤 사람이 앗수르 왕에게 말하여 이르되 왕께서 사마리아 여러 성읍에 옮겨 거주하게 하신 민족들이 그 땅 신의 법을 알지 못하므로 그들의 신이 사자들을 그들 가운데에 보내매 그들을 죽였사오니 이는 그들이 그 땅 신의 법을 알지 못함이니이다 하니라'),
    (10016, '○앗수르 왕이 명령하여 이르되 너희는 그 곳에서 사로잡아 온 제사장 한 사람을 그 곳으로 데려가되 그가 그 곳에 가서 거주하며 그 땅 신의 법을 무리에게 가르치게 하라 하니'),
    (10023, '○그들이 오늘까지 이전 풍속대로 행하여 여호와를 경외하지 아니하며 또 여호와께서 이스라엘이라 이름을 주신 야곱의 자손에게 명령하신 율례와 법도와 율법과 계명을 준행하지 아니하는도다'),
    (10152, '<유다 왕 요시야> 요시야가 왕위에 오를 때에 나이가 팔 세라 예루살렘에서 삼십일 년간 다스리니라 그의 어머니의 이름은 여디다요 보스갓 아다야의 딸이더라'),
    (10154, '<율법책을 발견하다> ○요시야 왕 열여덟째 해에 왕이 므술람의 손자 아살리야의 아들 서기관 사반을 여호와의 성전에 보내며 이르되'),
    (10159, '○대제사장 힐기야가 서기관 사반에게 이르되 내가 여호와의 성전에서 율법책을 발견하였노라 하고 힐기야가 그 책을 사반에게 주니 사반이 읽으니라'),
    (10164, '너희는 가서 나와 백성과 온 유다를 위하여 이 발견한 책의 말씀에 대하여 여호와께 물으라 우리 조상들이 이 책의 말씀을 듣지 아니하며 이 책에 우리를 위하여 기록된 모든 것을 행하지 아니하였으므로 여호와께서 우리에게 내리신 진노가 크도다'),
    (10165, '○이에 제사장 힐기야와 또 아히감과 악볼과 사반과 아사야가 여선지 훌다에게로 나아가니 그는 할하스의 손자 디과의 아들로서 예복을 주관하는 살룸의 아내라 예루살렘 둘째 구역에 거주하였더라 그들이 그와 더불어 말하매'),
    (10170, '내가 이 곳과 그 주민에게 대하여 빈 터가 되고 저주가 되리라 한 말을 네가 듣고 마음이 부드러워져서 여호와 앞 곧 내 앞에서 겸비하여 옷을 찢고 통곡하였으므로 나도 네 말을 들었노라 여호와가 말하였느니라'),
    (10213, '○여호야김의 남은 사적과 행한 모든 일은 유다 왕 역대지략에 기록되지 아니하였느냐'),
    (10216, '<유다 왕 여호야긴> ○여호야긴이 왕이 될 때에 나이가 십팔 세라 예루살렘에서 석 달간 다스리니라 그의 어머니의 이름은 느후스다요 예루살렘 엘라단의 딸이더라'),
    (10218, '○그 때에 바벨론의 왕 느부갓네살의 신복들이 예루살렘에 올라와서 그 성을 에워싸니라'),
    (10226, '<유다 왕 시드기야> ○시드기야가 왕이 될 때에 나이가 이십일 세라 예루살렘에서 십일 년간 다스리니라 그의 어머니의 이름은 하무달이요 리블라인 예레미야의 딸이더라'),
    (10228, '여호와께서 예루살렘과 유다를 진노하심이 그들을 그 앞에서 쫓아내실 때까지 이르렀더라 시드기야가 바벨론 왕을 배반하니라'),
    (10126, '<유다 왕 므낫세> 므낫세가 왕이 될 때에 나이가 십이 세라 예루살렘에서 오십오 년간 다스리니라 그의 어머니의 이름은 헵시바더라'),
    (10132, '또 자기가 만든 아로새긴 아세라 목상을 성전에 세웠더라 옛적에 여호와께서 이 성전에 대하여 다윗과 그의 아들 솔로몬에게 이르시기를 내가 이스라엘의 모든 지파 중에서 택한 이 성전과 예루살렘에 내 이름을 영원히 둘지라'),
    (10135, '○여호와께서 그의 종 모든 선지자들을 통하여 말씀하여 이르시되'),
    (10141, '○므낫세가 유다에게 범죄하게 하여 여호와께서 보시기에 악을 행한 것 외에도 또 무죄한 자의 피를 심히 많이 흘려 예루살렘 이 끝에서 저 끝까지 가득하게 하였더라'),
    (10144, '<유다 왕 아몬> ○아몬이 왕이 될 때에 나이가 이십이 세라 예루살렘에서 이 년간 다스리니라 그의 어머니의 이름은 므술레멧이요 욧바 하루스의 딸이더라'),
    (10230, '<예루살렘의 멸망> 시드기야 제구년 열째 달 십일에 바벨론의 왕 느부갓네살이 그의 모든 군대를 거느리고 예루살렘을 치러 올라와서 그 성에 대하여 진을 치고 주위에 토성을 쌓으매'),
    (10235, '그들이 왕을 사로잡아 그를 리블라에 있는 바벨론 왕에게로 끌고 가매 그들이 그를 심문하니라'),
    (10237, '<성전 붕괴> ○바벨론 왕 느부갓네살의 열아홉째 해 오월 칠일에 바벨론 왕의 신복 시위대장 느부사라단이 예루살렘에 이르러'),
    (10242, '○갈대아 사람이 또 여호와의 성전의 두 놋 기둥과 받침들과 여호와의 성전의 놋 바다를 깨뜨려 그 놋을 바벨론으로 가져가고'),
    (10247, '<유다 백성이 바벨론으로 사로잡혀 가다> ○시위대장이 대제사장 스라야와 부제사장 스바냐와 성전 문지기 세 사람을 사로잡고'),
    (10248, '또 성 중에서 사람을 사로잡았으니 곧 군사를 거느린 내시 한 사람과 또 성 중에서 만난 바 왕의 시종 다섯 사람과 백성을 징집하는 장관의 서기관 한 사람과 성 중에서 만난 바 백성 육십 명이라'),
    (10249, '시위대장 느부사라단이 그들을 사로잡아 가지고 리블라 바벨론 왕에게 나아가매'),
    (10250, '바벨론 왕이 하맛 땅 리블라에서 다 쳐죽였더라 이와 같이 유다가 사로잡혀 본토에서 떠났더라'),
    (10251, '<유다 지도자 그달리야> ○유다 땅에 머물러 있는 백성은 곧 바벨론 왕 느부갓네살이 남긴 자라 왕이 사반의 손자 아히감의 아들 그달리야가 관할하게 하였더라'),
    (10252, '모든 군대 지휘관과 그를 따르는 자가 바벨론 왕이 그달리야를 지도자로 삼았다 함을 듣고 이에 느다니야의 아들 이스마엘과 가레아의 아들 요하난과 느도바 사람 단후멧의 아들 스라야와 마아가 사람의 아들 야아사니야와 그를 따르는 사람이 모두 미스바로 가서 그달리야에게 나아가매'),
    (10256, '<여호야긴이 석방되다> ○유다의 왕 여호야긴이 사로잡혀 간 지 삼십칠 년 곧 바벨론의 왕 에윌므로닥이 즉위한 원년 십이월 그 달 이십칠일에 유다의 왕 여호야긴을 옥에서 내놓아 그 머리를 들게 하고'),
    (10260, '<아담에서 아브라함까지> 아담, 셋, 에노스,'),
    (10264, '○야벳의 자손은 고멜과 마곡과 마대와 야완과 두발과 메섹과 디라스요'),
    (10267, '○함의 자손은 구스와 미스라임과 붓과 가나안이요'),
    (10276, '○셈의 자손은 엘람과 앗수르와 아르박삿과 룻과 아람과 우스와 훌과 게델과 메섹이라'),
    (10279, '욕단이 알모닷과 셀렙과 하살마웻과 예라와'),
    (10283, '○셈, 아르박삿, 셀라,'),
    (10287, '<이스마엘의 세계> ○아브라함의 자손은 이삭과 이스마엘이라'),
    (10291, '○아브라함의 소실 그두라가 낳은 자손은 시므란과 욕산과 므단과 미디안과 이스박과 수아요 욕산의 자손은 스바와 드단이요'),
    (10293, '<에서의 자손> ○아브라함이 이삭을 낳았으니 이삭의 아들은 에서와 이스라엘이더라'),
    (10294, '○에서의 아들은 엘리바스와 르우엘과 여우스와 얄람과 고라요'),
    (10302, '<에돔 땅을 다스린 왕들> ○이스라엘 자손을 다스리는 왕이 있기 전에 에돔 땅을 다스린 왕은 이러하니라 브올의 아들 벨라니 그의 도성 이름은 딘하바이며'),
    (10316, '<유다의 자손> ○유다의 아들은 에르와 오난과 셀라니 이 세 사람은 가나안 사람 수아의 딸이 유다에게 낳아 준 자요 유다의 맏아들 에르는 여호와 보시기에 악하였으므로 여호와께서 죽이셨고'),
    (10318, '○베레스의 아들은 헤스론과 하물이요'),
    (10322, '<다윗의 가계> ○헤스론이 낳은 아들은 여라므엘과 람과 글루배라'),
    (10331, '<헤스론의 자손> ○헤스론의 아들 갈렙이 그의 아내 아수바와 여리옷에게서 아들을 낳았으니 그가 낳은 아들들은 예셀과 소밥과 아르돈이며'),
    (10334, '○그 후에 헤스론이 육십 세에 길르앗의 아버지 마길의 딸에게 장가 들어 동침하였더니 그가 스굽을 헤스론에게 낳아 주었으며'),
    (10338, '<여라므엘의 자손> ○헤스론의 맏아들 여라므엘의 아들은 맏아들 람과 그 다음 브나와 오렌과 오셈과 아히야이며'),
    (10355, '<갈렙의 자손> ○여라므엘의 아우 갈렙의 아들 곧 맏아들은 메사이니 십의 아버지요 그 아들은 마레사니 헤브론의 아버지이며'),
    (10363, '○갈렙의 자손 곧 에브라다의 맏아들 훌의 아들은 이러하니 기럇여아림의 아버지 소발과'),
    (10378, '<솔로몬 왕의 자손> ○솔로몬의 아들은 르호보암이요 그의 아들은 아비야요 그의 아들은 아사요 그의 아들은 여호사밧이요'),
    (10436, '<르우벤의 자손> 이스라엘의 장자 르우벤의 아들들은 이러하니라 (르우벤은 장자라도 그의 아버지의 침상을 더럽혔으므로 장자의 명분이 이스라엘의 아들 요셉의 자손에게로 돌아가서 족보에 장자의 명분대로 기록되지 못하였느니라'),
    (10446, '<갓의 자손> ○갓 자손은 르우벤 사람을 마주 대하여 바산 땅에 거주하면서 살르가까지 다다랐으니'),
    (10451, '그들이 바산 길르앗과 그 마을과 사론의 모든 들에 거주하여 그 사방 변두리에 다다랐더라'),
    (10453, '<므낫세 반 지파의 용사> ○르우벤 자손과 갓 사람과 므낫세 반 지파에서 나가 싸울 만한 용사 곧 능히 방패와 칼을 들며 활을 당겨 싸움에 익숙한 자는 사만 사천칠백육십 명이라'),
    (10458, '<므낫세 반 지파의 자손들> ○므낫세 반 지파 자손들이 그 땅에 거주하면서 그들이 번성하여 바산에서부터 바알헤르몬과 스닐과 헤르몬 산까지 다다랐으며'),
    (10460, '<므낫세 반 지파의 추방> ○그들이 그들의 조상들의 하나님께 범죄하여 하나님이 그들 앞에서 멸하신 그 땅 백성의 신들을 간음하듯 섬긴지라'),
    (10461, '그러므로 이스라엘 하나님이 앗수르 왕 불의 마음을 일으키시며 앗수르 왕 디글랏빌레셀의 마음을 일으키시매 곧 르우벤과 갓과 므낫세 반 지파를 사로잡아 할라와 하볼과 하라와 고산 강 가에 옮긴지라 그들이 오늘까지 거기에 있으니라'),
    (10402, '야베스가 이스라엘 하나님께 아뢰어 이르되 주께서 내게 복을 주시려거든 나의 지역을 넓히시고 주의 손으로 나를 도우사 나로 환난을 벗어나 내게 근심이 없게 하옵소서 하였더니 하나님이 그가 구하는 것을 허락하셨더라'),
    (10403, '<다른 족보> ○수하의 형 글룹이 므힐을 낳았으니 므힐은 에스돈의 아버지요'),
    (10410, '이는 메렛이 아내로 맞은 바로의 딸 비디아의 아들들이며 또 그의 아내 여후디야는 그들의 조상 예렛과 소고의 조상 헤벨과 사노아의 조상 여구디엘을 낳았으며'),
    (10416, '<시므온의 자손> ○시므온의 아들들은 느무엘과 야민과 야립과 세라와 사울이요'),
    (10433, '이 명단에 기록된 사람들이 유다 왕 히스기야 때에 가서 그들의 장막을 쳐서 무찌르고 거기에 있는 모우님 사람을 쳐서 진멸하고 대신하여 오늘까지 거기에 살고 있으니 이는 그들의 양 떼를 먹일 목장이 거기에 있음이며'),
    (10172, '<요시야가 이방 예배를 없애다> 왕이 보내 유다와 예루살렘의 모든 장로를 자기에게로 모으고'),
    (10173, '이에 왕이 여호와의 성전에 올라가매 유다 모든 사람과 예루살렘 주민과 제사장들과 선지자들과 모든 백성이 노소를 막론하고 다 왕과 함께 한지라 왕이 여호와의 성전 안에서 발견한 언약책의 모든 말씀을 읽어 무리의 귀에 들리고'),
    (10174, '왕이 단 위에 서서 여호와 앞에서 언약을 세우되 마음을 다하고 뜻을 다하여 여호와께 순종하고 그의 계명과 법도와 율례를 지켜 이 책에 기록된 이 언약의 말씀을 이루게 하리라 하매 백성이 다 그 언약을 따르기로 하니라'),
    (10175, '○왕이 대제사장 힐기야와 모든 부제사장들과 문을 지킨 자들에게 명령하여 바알과 아세라와 하늘의 일월 성신을 위하여 만든 모든 그릇들을 여호와의 성전에서 내다가 예루살렘 바깥 기드론 밭에서 불사르고 그것들의 재를 벧엘로 가져가게 하고'),
    (10176, '옛적에 유다 왕들이 세워서 유다 모든 성읍과 예루살렘 주위의 산당들에서 분향하며 우상을 섬기게 한 제사장들을 폐하며 또 바알과 해와 달과 별 떼와 하늘의 모든 별에게 분향하는 자들을 폐하고'),
    (10177, '또 여호와의 성전에서 아세라 상을 내다가 예루살렘 바깥 기드론 시내로 가져다 거기에서 불사르고 빻아서 가루를 만들어 그 가루를 평민의 묘지에 뿌리고'),
    (10179, '또 유다 각 성읍에서 모든 제사장을 불러오고 또 제사장이 분향하던 산당을 게바에서부터 브엘세바까지 더럽게 하고 또 성문의 산당들을 헐어 버렸으니 이 산당들은 그 성읍의 지도자 여호수아의 대문 어귀 곧 성문 왼쪽에 있었더라'),
    (10184, '또 예루살렘 앞 멸망의 산 오른쪽에 세운 산당들을 왕이 더럽게 하였으니 이는 옛적에 이스라엘 왕 솔로몬이 시돈 사람의 가증한 아스다롯과 모압 사람의 가증한 그모스와 암몬 자손의 가증한 밀곰을 위하여 세웠던 것이며'),
    (10186, '○또한 이스라엘에게 범죄하게 한 느밧의 아들 여로보암이 벧엘에 세운 제단과 산당을 왕이 헐고 또 그 산당을 불사르고 빻아서 가루를 만들며 또 아세라 목상을 불살랐더라'),
    (10187, '요시야가 몸을 돌이켜 산에 있는 무덤들을 보고 보내어 그 무덤에서 해골을 가져다가 제단 위에서 불살라 그 제단을 더럽게 하니라 이 일을 하나님의 사람이 전하였더니 그 전한 여호와의 말씀대로 되었더라'),
    (10188, '요시야가 이르되 내게 보이는 저것은 무슨 비석이냐 하니 성읍 사람들이 그에게 말하되 왕께서 벧엘의 제단에 대하여 행하신 이 일을 전하러 유다에서 왔던 하나님의 사람의 묘실이니이다 하니라'),
    (10192, '<요시야 왕이 유월절을 지키다> ○왕이 뭇 백성에게 명령하여 이르되 이 언약책에 기록된 대로 너희의 하나님 여호와를 위하여 유월절을 지키라 하매'),
    (10195, '<요시야의 나머지 개혁> ○요시야가 또 유다 땅과 예루살렘에 보이는 신접한 자와 점쟁이와 드라빔과 우상과 모든 가증한 것을 다 제거하였으니 이는 대제사장 힐기야가 여호와의 성전에서 발견한 책에 기록된 율법의 말씀을 이루려 함이라'),
    (10197, '○그러나 여호와께서 유다를 향하여 내리신 그 크게 타오르는 진노를 돌이키지 아니하셨으니 이는 므낫세가 여호와를 격노하게 한 그 모든 격노 때문이라'),
    (10199, '<요시야가 죽다> ○요시야의 남은 사적과 행한 모든 일은 유다 왕 역대지략에 기록되지 아니하였느냐'),
    (10201, '신복들이 그의 시체를 병거에 싣고 므깃도에서 예루살렘으로 돌아와 그의 무덤에 장사하니 백성들이 요시야의 아들 여호아하스를 데려다가 그에게 기름을 붓고 그의 아버지를 대신하여 왕으로 삼았더라'),
    (10202, '<유다 왕 여호아하스> ○여호아하스가 왕이 될 때에 나이가 이십삼 세라 예루살렘에서 석 달간 다스리니라 그의 어머니의 이름은 하무달이라 립나 예레미야의 딸이더라'),
    (10207, '<유다 왕 여호야김> ○여호야김이 왕이 될 때에 나이가 이십오 세라 예루살렘에서 십일 년간 다스리니라 그의 어머니의 이름은 스비다라 루마 브다야의 딸이더라'),
    (10548, '<베냐민의 자손> ○베냐민의 아들들은 벨라와 베겔과 여디아엘 세 사람이며'),
    (10554, '일의 아들은 숩빔과 훕빔이요 아헬의 아들은 후심이더라'),
    (10555, '<납달리의 자손> ○납달리의 아들들은 야시엘과 구니와 예셀과 살룸이니 이는 빌하의 손자더라'),
    (10556, '<므낫세의 자손> ○므낫세의 아들들은 그의 아내가 낳아 준 아스리엘과 그의 소실 아람 여인이 낳아 준 길르앗의 아버지 마길이니'),
    (10557, '마길은 훕빔과 숩빔의 누이 마아가라 하는 이에게 장가 들었더라 므낫세의 둘째 아들의 이름은 슬로브핫이니 슬로브핫은 딸들만 낳았으며'),
    (10562, '<에브라임의 자손> ○에브라임의 아들은 수델라요 그의 아들은 베렛이요 그의 아들은 다핫이요 그의 아들은 엘르아다요 그의 아들은 다핫이요'),
    (10570, '○에브라임 자손의 토지와 거주지는 벧엘과 그 주변 마을이요 동쪽으로는 나아란이요 서쪽에는 게셀과 그 주변 마을이며 또 세겜과 그 주변 마을이니 아사와 그 주변 마을까지이며'),
    (10572, '<아셀의 자손> ○아셀의 아들들은 임나와 이스와와 이스위와 브리아요 그들의 매제는 세라이며'),
    (10611, '<기브온과 예루살렘의 베냐민 사람들> ○기브온의 조상 여이엘은 기브온에 거주하였으니 그 아내의 이름은 마아가며'),
    (10618, '아하스는 여호앗다를 낳고 여호앗다는 알레멧과 아스마웻과 시므리를 낳고 시므리는 모사를 낳고'),
    (10667, '<사울 왕이 죽다> 블레셋 사람들과 이스라엘이 싸우더니 이스라엘 사람들이 블레셋 사람들 앞에서 도망하다가 길보아 산에서 죽임을 당하여 엎드러지니라'),
    (10670, '사울이 자기의 무기를 가진 자에게 이르되 너는 칼을 빼어 그것으로 나를 찌르라 할례 받지 못한 자들이 와서 나를 욕되게 할까 두려워하노라 그러나 그의 무기를 가진 자가 심히 두려워하여 행하기를 원하지 아니하매 사울이 자기 칼을 뽑아서 그 위에 엎드러지니'),
    (10673, '○골짜기에 있는 모든 이스라엘 사람이 그들의 도망한 것과 사울과 그의 아들들이 다 죽은 것을 보고 그 성읍들을 버리고 도망하매 블레셋 사람들이 와서 거기에 거주하니라'),
    (10681, '<다윗이 이스라엘과 유다의 왕이 되다> 온 이스라엘이 헤브론에 모여 다윗을 보고 이르되 우리는 왕의 가까운 혈족이니이다'),
    (10682, '전에 곧 사울이 왕이 되었을 때에도 이스라엘을 거느리고 출입하게 한 자가 왕이시었고 왕의 하나님 여호와께서도 왕에게 말씀하시기를 네가 내 백성 이스라엘의 목자가 되며 내 백성 이스라엘의 주권자가 되리라 하셨나이다 하니라'),
    (10683, '이에 이스라엘의 모든 장로가 헤브론에 있는 왕에게로 나아가니 헤브론에서 다윗이 그들과 여호와 앞에 언약을 맺으매 그들이 다윗에게 기름을 부어 이스라엘의 왕으로 삼으니 여호와께서 사무엘을 통하여 전하신 말씀대로 되었더라'),
    (10684, '○다윗이 온 이스라엘과 더불어 예루살렘 곧 여부스에 이르니 여부스 땅의 주민들이 거기에 거주하였더라'),
    (10690, '<다윗의 용사들> ○다윗에게 있는 용사의 우두머리는 이러하니라 이 사람들이 온 이스라엘과 더불어 다윗을 힘껏 도와 나라를 얻게 하고 그를 세워 왕으로 삼았으니 이는 여호와께서 이스라엘에 대하여 이르신 말씀대로 함이었더라'),
    (10695, '○삼십 우두머리 중 세 사람이 바위로 내려가서 아둘람 굴 다윗에게 이를 때에 블레셋 군대가 르바임 골짜기에 진 쳤더라'),
    (10699, '이르되 내 하나님이여 내가 결단코 이런 일을 하지 아니하리이다 생명을 돌아보지 아니하고 갔던 이 사람들의 피를 어찌 마시리이까 하고 그들이 자기 생명도 돌보지 아니하고 이것을 가져왔으므로 그것을 마시기를 원하지 아니하니라 세 용사가 이런 일을 행하였더라'),
    (10700, '○요압의 아우 아비새는 그 세 명 중 우두머리라 그가 창을 휘둘러 삼백 명을 죽이고 그 세 명 가운데에 이름을 얻었으니'),
    (10702, '○갑스엘 용사의 손자 여호야다의 아들 브나야는 용감한 사람이라 그가 모압 아리엘의 아들 둘을 죽였고 또 눈 올 때에 함정에 내려가서 사자 한 마리를 죽였으며'),
    (10706, '○또 군사 중의 큰 용사는 요압의 아우 아사헬과 베들레헴 사람 도도의 아들 엘하난과'),
    (10713, '바하룸 사람 아스마웻과 사알본 사람 엘리아바와'),
    (10768, '<하나님의 궤를 옮기다> 다윗이 천부장과 백부장 곧 모든 지휘관과 더불어 의논하고'),
    (10769, '다윗이 이스라엘의 온 회중에게 이르되 만일 너희가 좋게 여기고 또 우리의 하나님 여호와께로 말미암았으면 우리가 이스라엘 온 땅에 남아 있는 우리 형제와 또 초원이 딸린 성읍에 사는 제사장과 레위 사람에게 전령을 보내 그들을 우리에게로 모이게 하고'),
    (10773, '다윗이 온 이스라엘을 거느리고 바알라 곧 유다에 속한 기럇여아림에 올라가서 여호와 하나님의 궤를 메어오려 하니 이는 여호와께서 두 그룹 사이에 계시므로 그러한 이름으로 일컬음을 받았더라'),
    (10776, '○기돈의 타작 마당에 이르러서는 소들이 뛰므로 웃사가 손을 펴서 궤를 붙들었더니'),
    (10782, '<예루살렘에서 다윗이 활동하다> 두로 왕 히람이 다윗에게 사신들과 백향목과 석수와 목수를 보내 그의 궁전을 건축하게 하였더라'),
    (10784, '○다윗이 예루살렘에서 또 아내들을 맞아 다윗이 다시 아들들과 딸들을 낳았으니'),
    (10789, '<다윗이 블레셋을 이기다> ○다윗이 기름 부음을 받아 온 이스라엘의 왕이 되었다 함을 블레셋 사람들이 듣고 모든 블레셋 사람들이 다윗을 찾으러 올라오매 다윗이 듣고 대항하러 나갔으나'),
    (10791, '다윗이 하나님께 물어 이르되 내가 블레셋 사람들을 치러 올라가리이까 주께서 그들을 내 손에 넘기시겠나이까 하니 여호와께서 그에게 이르시되 올라가라 내가 그들을 네 손에 넘기리라 하신지라'),
    (10794, '○블레셋 사람들이 다시 골짜기를 침범한지라'),
    (10632, '<예루살렘에 정착한 제사장들> ○제사장 중에서는 여다야와 여호야립과 야긴과'),
    (10636, '<예루살렘에 정착한 레위 사람들> ○레위 사람 중에서는 므라리 자손 스마야이니 그는 핫숩의 아들이요 아스리감의 손자요 하사뱌의 증손이며'),
    (10639, '<예루살렘에 정착한 회막 문지기> ○문지기는 살룸과 악굽과 달몬과 아히만과 그의 형제들이니 살룸은 그 우두머리라'),
    (10650, '<나머지 레위 사람들> ○그 중에 어떤 자는 섬기는 데 쓰는 기구를 맡아서 그 수효대로 들여가고 수효대로 내오며'),
    (10655, '○또 찬송하는 자가 있으니 곧 레위 우두머리라 그들은 골방에 거주하면서 주야로 자기 직분에 전념하므로 다른 일은 하지 아니하였더라'),
    (10657, '<사울의 족보> ○기브온의 조상 여이엘은 기브온에 거주하였으니 그의 아내의 이름은 마아가라'),
    (10664, '아하스는 야라를 낳고 야라는 알레멧과 아스마웻과 시므리를 낳고 시므리는 모사를 낳고'),
    (10730, '그 우두머리는 아히에셀이요 다음은 요아스이니 기브아 사람 스마아의 두 아들이요 또 아스마웻의 아들 여시엘과 벨렛과 또 브라가와 아나돗 사람 예후와'),
    (10735, '<갓 지파에서 다윗을 도운 용사들> ○갓 사람 중에서 광야에 있는 요새에 이르러 다윗에게 돌아온 자가 있었으니 다 용사요 싸움에 익숙하여 방패와 창을 능히 쓰는 자라 그의 얼굴은 사자 같고 빠르기는 산의 사슴 같으니'),
    (10743, '<베냐민과 유다에서 다윗을 도운 용사들> ○베냐민과 유다 자손 중에서 요새에 이르러 다윗에게 나오매'),
    (10744, '다윗이 나가서 맞아 그들에게 말하여 이르되 만일 너희가 평화로이 내게 와서 나를 돕고자 하면 내 마음이 너희 마음과 하나가 되려니와 만일 너희가 나를 속여 내 대적에게 넘기고자 하면 내 손에 불의함이 없으니 우리 조상들의 하나님이 감찰하시고 책망하시기를 원하노라 하매'),
    (10745, '그 때에 성령이 삼십 명의 우두머리 아마새를 감싸시니 이르되 다윗이여 우리가 당신에게 속하겠고 이새의 아들이여 우리가 당신과 함께 있으리니 원하건대 평안하소서 당신도 평안하고 당신을 돕는 자에게도 평안이 있을지니 이는 당신의 하나님이 당신을 도우심이니이다 한지라 다윗이 그들을 받아들여 군대 지휘관을 삼았더라'),
    (10746, '<므낫세 지파에서 다윗을 도운 용사들> ○다윗이 전에 블레셋 사람들과 함께 가서 사울을 치려 할 때에 므낫세 지파에서 두어 사람이 다윗에게 돌아왔으나 다윗 등이 블레셋 사람들을 돕지 못하였음은 블레셋 사람들의 방백이 서로 의논하고 보내며 이르기를 그가 그의 왕 사울에게로 돌아가리니 우리 머리가 위태할까 하노라 함이라'),
    (10750, '<다윗의 군사들> ○싸움을 준비한 군대 지휘관들이 헤브론에 이르러 다윗에게로 나아와서 여호와의 말씀대로 사울의 나라를 그에게 돌리고자 하였으니 그 수효가 이러하였더라'),
    (10765, '○이 모든 군사가 전열을 갖추고 다 성심으로 헤브론에 이르러 다윗을 온 이스라엘 왕으로 삼고자 하고 또 이스라엘의 남은 자도 다 한 마음으로 다윗을 왕으로 삼고자 하여'),
    (10767, '또 그들의 근처에 있는 자로부터 잇사갈과 스불론과 납달리까지도 나귀와 낙타와 노새와 소에다 음식을 많이 실어왔으니 곧 밀가루 과자와 무화과 과자와 건포도와 포도주와 기름이요 소와 양도 많이 가져왔으니 이는 이스라엘 가운데에 기쁨이 있음이었더라'),
    (10897, '<다윗의 승전 기록> 그 후에 다윗이 블레셋 사람들을 쳐서 항복을 받고 블레셋 사람들의 손에서 가드와 그 동네를 빼앗고'),
    (10899, '○소바 왕 하닷에셀이 유브라데 강 가에서 자기 세력을 펴고자 하매 다윗이 그를 쳐서 하맛까지 이르고'),
    (10905, '○하맛 왕 도우가 다윗이 소바 왕 하닷에셀의 온 군대를 쳐서 무찔렀다 함을 듣고'),
    (10906, '그의 아들 하도람을 보내서 다윗 왕에게 문안하고 축복하게 하니 이는 하닷에셀이 벌써 도우와 맞서 여러 번 전쟁이 있던 터에 다윗이 하닷에셀을 쳐서 무찔렀음이라 하도람이 금과 은과 놋의 여러 가지 그릇을 가져온지라'),
    (10910, '○다윗이 온 이스라엘을 다스려 모든 백성에게 정의와 공의를 행할새'),
    (10477, '<레위의 자손> ○레위의 아들들은 게르손과 그핫과 므라리이며'),
    (10492, '<회막 앞에서 찬송하는 사람들> ○언약궤가 평안을 얻었을 때에 다윗이 여호와의 성전에서 찬송하는 직분을 맡긴 자들은 아래와 같았더라'),
    (10510, '<아론의 자손> ○아론과 그의 자손들은 번제단과 향단 위에 분향하며 제사를 드리며 지성소의 모든 일을 하여 하나님의 종 모세의 모든 명령대로 이스라엘을 위하여 속죄하니'),
    (10515, '<레위 사람의 정착지> ○그들의 거주한 곳은 사방 지계 안에 있으니 그들의 마을은 아래와 같으니라 아론 자손 곧 그핫 종족이 먼저 제비 뽑았으므로'),
    (10522, '○그핫 자손의 남은 자에게는 절반 지파 즉 므낫세 반 지파 종족 중에서 제비 뽑아 열 성읍을 주었고'),
    (10527, '○그핫 자손의 몇 종족은 에브라임 지파 중에서 성읍을 얻어 영토를 삼았으며'),
    (10532, '○게르손 자손에게는 므낫세 반 지파 종족 중에서 바산의 골란과 그 초원과 아스다롯과 그 초원을 주고'),
    (10538, '○므라리 자손의 남은 자에게는 스불론 지파 중에서 림모노와 그 초원과 다볼과 그 초원을 주었고'),
    (10831, '○또 레위 사람을 세워 여호와의 궤 앞에서 섬기며 이스라엘 하나님 여호와를 칭송하고 감사하며 찬양하게 하였으니'),
    (10834, '<감사 찬양> ○그 날에 다윗이 아삽과 그의 형제를 세워 먼저 여호와께 감사하게 하여 이르기를'),
    (10861, '너희는 이르기를 우리 구원의 하나님이여 우리를 구원하여 만국 가운데에서 건져내시고 모으사 우리로 주의 거룩한 이름을 감사하며 주의 영광을 드높이게 하소서 할지어다'),
    (10863, '<기브온에서 번제를 드리다> ○다윗이 아삽과 그의 형제를 여호와의 언약궤 앞에 있게 하며 항상 그 궤 앞에서 섬기게 하되 날마다 그 일대로 하게 하였고'),
    (10914, '<다윗이 암몬과 아람을 치다> 그 후에 암몬 자손의 왕 나하스가 죽고 그의 아들이 대신하여 왕이 되니'),
    (10915, '다윗이 이르되 하눈의 아버지 나하스가 전에 내게 호의를 베풀었으니 이제 내가 그의 아들 하눈에게 호의를 베풀리라 하고 사절들을 보내서 그의 아버지 죽음을 문상하게 하니라 다윗의 신하들이 암몬 자손의 땅에 이르러 하눈에게 나아가 문상하매'),
    (10916, '암몬 자손의 방백들이 하눈에게 말하되 왕은 다윗이 조문사절을 보낸 것이 왕의 부친을 존경함인 줄로 여기시나이까 그의 신하들이 왕에게 나아온 것이 이 땅을 엿보고 정탐하여 전복시키고자 함이 아니니이까 하는지라'),
    (10918, '어떤 사람이 다윗에게 가서 그 사람들이 당한 일을 말하니라 그 사람들이 심히 부끄러워하므로 다윗이 그들을 맞으러 보내 왕이 이르기를 너희는 수염이 자라기까지 여리고에 머물다가 돌아오라 하니라'),
    (10919, '○암몬 자손이 자기가 다윗에게 밉게 한 줄 안지라 하눈과 암몬 자손은 더불어 은 천 달란트를 아람 나하라임과 아람마아가와 소바에 보내 병거와 마병을 삯 내되'),
    (10923, '○요압이 앞 뒤에 친 적진을 보고 이스라엘에서 뽑은 자 중에서 또 뽑아 아람 사람을 대하여 진을 치고'),
    (10929, '○아람 사람이 자기가 이스라엘 앞에서 패하였음을 보고 사신을 보내 강 건너편에 있는 아람 사람을 불러내니 하닷에셀의 군대사령관 소박이 그들을 거느린지라'),
    (10814, '○다윗이 레위 사람의 어른들에게 명령하여 그의 형제들을 노래하는 자들로 세우고 비파와 수금과 제금 등의 악기를 울려서 즐거운 소리를 크게 내라 하매'),
    (10823, '<하나님의 궤를 예루살렘으로 옮기다> ○이에 다윗과 이스라엘 장로들과 천부장들이 가서 여호와의 언약궤를 즐거이 메고 오벧에돔의 집에서 올라왔는데'),
    (10827, '○여호와의 언약궤가 다윗 성으로 들어올 때에 사울의 딸 미갈이 창으로 내다보다가 다윗 왕이 춤추며 뛰노는 것을 보고 그 마음에 업신여겼더라'),
    (10870, '<다윗에 대한 여호와의 말씀과 계시> 다윗이 그의 궁전에 거주할 때에 다윗이 선지자 나단에게 이르되 나는 백향목 궁에 거주하거늘 여호와의 언약궤는 휘장 아래에 있도다'),
    (10885, '<다윗의 감사 기도> ○다윗 왕이 여호와 앞에 들어가 앉아서 이르되 여호와 하나님이여 나는 누구이오며 내 집은 무엇이기에 나에게 이에 이르게 하셨나이까'),
    (10890, '땅의 어느 한 나라가 주의 백성 이스라엘과 같으리이까 하나님이 자기 백성을 구속하시려고 나가사 크고 두려운 일로 말미암아 이름을 얻으시고 애굽에서 구속하신 자기 백성 앞에서 모든 민족을 쫓아내셨사오며'),
    (10893, '견고하게 하시고 사람에게 영원히 주의 이름을 높여 이르기를 만군의 여호와는 이스라엘의 하나님 곧 이스라엘에게 하나님이시라 하게 하시며 주의 종 다윗의 왕조가 주 앞에서 견고히 서게 하옵소서'),
    (10933, '<다윗이 랍바를 함락시키다> 해가 바뀌어 왕들이 출전할 때가 되매 요압이 그 군대를 거느리고 나가서 암몬 자손의 땅을 격파하고 들어가 랍바를 에워싸고 다윗은 예루살렘에 그대로 있더니 요압이 랍바를 쳐서 함락시키매'),
    (10936, '<블레셋 사람들과 싸우다> ○이 후에 블레셋 사람들과 게셀에서 전쟁할 때에 후사 사람 십브개가 키가 큰 자의 아들 중에 십배를 쳐죽이매 그들이 항복하였더라'),
    (11053, '<찬송을 맡은 사람들> 다윗이 군대 지휘관들과 더불어 아삽과 헤만과 여두둔의 자손 중에서 구별하여 섬기게 하되 수금과 비파와 제금을 잡아 신령한 노래를 하게 하였으니 그 직무대로 일하는 자의 수효는 이러하니라'),
    (11055, '여두둔에게 이르러서는 그의 아들들 그달리야와 스리와 여사야와 시므이와 하사뱌와 맛디디야 여섯 사람이니 그의 아버지 여두둔의 지휘 아래 수금을 잡아 신령한 노래를 하며 여호와께 감사하며 찬양하며'),
    (11027, '레위 사람 느다넬의 아들 서기관 스마야가 왕과 방백과 제사장 사독과 아비아달의 아들 아히멜렉과 및 제사장과 레위 사람의 우두머리 앞에서 그 이름을 기록하여 엘르아살의 자손 중에서 한 집을 뽑고 이다말의 자손 중에서 한 집을 뽑았으니'),
    (11034, '열셋째는 훕바요 열넷째는 예세브압이요'),
    (11041, '<레위 자손 중에 남은 자들> ○레위 자손 중에 남은 자는 이러하니 아므람의 아들들 중에는 수바엘이요 수바엘의 아들들 중에는 예드야며'),
    (11095, '○이상은 다 문지기의 반장으로서 그 형제처럼 직임을 얻어 여호와의 성전에서 섬기는 자들이라'),
    (11103, '<성전 곳간을 맡은 사람들> ○레위 사람 중에 아히야는 하나님의 전 곳간과 성물 곳간을 맡았으며'),
    (11112, '<다른 레위 사람들의 직임> ○이스할 자손 중에 그나냐와 그의 아들들은 성전 밖에서 이스라엘의 일을 다스리는 관원과 재판관이 되었고'),
    (10972, '<성전 건축 준비> ○다윗이 명령하여 이스라엘 땅에 거류하는 이방 사람을 모으고 석수를 시켜 하나님의 성전을 건축할 돌을 다듬게 하고'),
    (10975, '다윗이 이르되 내 아들 솔로몬은 어리고 미숙하고 여호와를 위하여 건축할 성전은 극히 웅장하여 만국에 명성과 영광이 있게 하여야 할지라 그러므로 내가 이제 그것을 위하여 준비하리라 하고 다윗이 죽기 전에 많이 준비하였더라'),
    (10976, '○다윗이 그의 아들 솔로몬을 불러 이스라엘 하나님 여호와를 위하여 성전 건축하기를 부탁하여'),
    (10979, '보라 한 아들이 네게서 나리니 그는 온순한 사람이라 내가 그로 주변 모든 대적에게서 평온을 얻게 하리라 그의 이름을 솔로몬이라 하리니 이는 내가 그의 생전에 평안과 안일함을 이스라엘에게 줄 것임이니라'),
    (10987, '○다윗이 또 이스라엘 모든 방백에게 명령하여 그의 아들 솔로몬을 도우라 하여 이르되'),
    (10988, '너희 하나님 여호와께서 너희와 함께 계시지 아니하시느냐 사면으로 너희에게 평온함을 주지 아니하셨느냐 이 땅 주민을 내 손에 넘기사 이 땅으로 여호와와 그의 백성 앞에 복종하게 하셨나니'),
    (10989, '이제 너희는 마음과 뜻을 바쳐서 너희 하나님 여호와를 구하라 그리고 일어나서 여호와 하나님의 성전을 건축하고 여호와의 언약궤와 하나님 성전의 기물을 가져다가 여호와의 이름을 위하여 건축한 성전에 들이게 하라 하였더라'),
    (10996, '○게르손 자손은 라단과 시므이라'),
    (11001, '○그핫의 아들들은 아므람과 이스할과 헤브론과 웃시엘 네 사람이라'),
    (11002, '아므람의 아들들은 아론과 모세이니 아론은 그 자손들과 함께 구별되어 몸을 성결하게 하여 영원토록 심히 거룩한 자가 되어 여호와 앞에 분향하고 섬기며 영원토록 그 이름으로 축복하게 되었느니라'),
    (11005, '게르솜의 아들 중에 스브엘이 우두머리가 되었고'),
    (11010, '○므라리의 아들들은 마흘리와 무시요 마흘리의 아들들은 엘르아살과 기스라'),
    (11013, '○이는 다 레위 자손이니 그 조상의 가문을 따라 계수된 이름이 기록되고 여호와의 성전에서 섬기는 일을 하는 이십세 이상 된 우두머리들이라'),
    (11116, '<모든 가문의 우두머리와 관원들> 이스라엘 자손의 모든 가문의 우두머리와 천부장과 백부장과 왕을 섬기는 관원들이 그들의 숫자대로 반이 나누이니 각 반열이 이만 사천 명씩이라 일 년 동안 달마다 들어가며 나왔으니'),
    (11131, '<각 지파를 관할하는 자들> ○이스라엘 지파를 관할하는 자는 이러하니라 르우벤 사람의 지도자는 시그리의 아들 엘리에셀이요 시므온 사람의 지도자는 마아가의 아들 스바댜요'),
    (11140, '<왕의 재산을 맡은 자들> ○아디엘의 아들 아스마웻은 왕의 곳간을 맡았고 웃시야의 아들 요나단은 밭과 성읍과 마을과 망대의 곳간을 맡았고'),
    (11147, '<다윗을 섬기는 사람들> ○다윗의 숙부 요나단은 지혜가 있어서 모사가 되며 서기관도 되었고 학모니의 아들 여히엘은 왕자들의 수종자가 되었고'),
    (10941, '<다윗의 인구 조사> 사탄이 일어나 이스라엘을 대적하고 다윗을 충동하여 이스라엘을 계수하게 하니라'),
    (10943, '요압이 아뢰되 여호와께서 그 백성을 지금보다 백 배나 더하시기를 원하나이다 내 주 왕이여 이 백성이 다 내 주의 종이 아니니이까 내 주께서 어찌하여 이 일을 명령하시나이까 어찌하여 이스라엘이 범죄하게 하시나이까 하나'),
    (10949, '○여호와께서 다윗의 선견자 갓에게 말씀하여 이르시되'),
    (10952, '혹 삼년 기근이든지 혹 네가 석 달을 적군에게 패하여 적군의 칼에 쫓길 일이든지 혹 여호와의 칼 곧 전염병이 사흘 동안 이 땅에 유행하며 여호와의 천사가 이스라엘 온 지경을 멸할 일이든지라고 하셨나니 내가 무슨 말로 나를 보내신 이에게 대답할지를 결정하소서 하니'),
    (10955, '하나님이 예루살렘을 멸하러 천사를 보내셨더니 천사가 멸하려 할 때에 여호와께서 보시고 이 재앙 내림을 뉘우치사 멸하는 천사에게 이르시되 족하다 이제는 네 손을 거두라 하시니 그 때에 여호와의 천사가 여부스 사람 오르난의 타작 마당 곁에 선지라'),
    (10957, '하나님께 아뢰되 명령하여 백성을 계수하게 한 자가 내가 아니니이까 범죄하고 악을 행한 자는 곧 나이니이다 이 양 떼는 무엇을 행하였나이까 청하건대 나의 하나님 여호와여 주의 손으로 나와 내 아버지의 집을 치시고 주의 백성에게 재앙을 내리지 마옵소서 하니라'),
    (10958, '○여호와의 천사가 갓에게 명령하여 다윗에게 이르시기를 다윗은 올라가서 여부스 사람 오르난의 타작 마당에서 여호와를 위하여 제단을 쌓으라 하신지라'),
    (10963, '오르난이 다윗에게 말하되 왕은 취하소서 내 주 왕께서 좋게 여기시는 대로 행하소서 보소서 내가 이것들을 드리나이다 소들은 번제물로, 곡식 떠는 기계는 화목으로, 밀은 소제물로 삼으시기 위하여 다 드리나이다 하는지라'),
    (10965, '그리하여 다윗은 그 터 값으로 금 육백 세겔을 달아 오르난에게 주고'),
    (10968, '○이 때에 다윗이 여호와께서 여부스 사람 오르난의 타작 마당에서 응답하심을 보고 거기서 제사를 드렸으니'),
    (11202, '<솔로몬 왕이 지혜를 구하다> 다윗의 아들 솔로몬의 왕위가 견고하여 가며 그의 하나님 여호와께서 그와 함께 하사 심히 창대하게 하시니라'),
    (11208, '○그 날 밤에 하나님이 솔로몬에게 나타나 그에게 이르시되 내가 네게 무엇을 주랴 너는 구하라 하시니'),
    (11212, '하나님이 솔로몬에게 이르시되 이런 마음이 네게 있어서 부나 재물이나 영광이나 원수의 생명 멸하기를 구하지 아니하며 장수도 구하지 아니하고 오직 내가 네게 다스리게 한 내 백성을 재판하기 위하여 지혜와 지식을 구하였으니'),
    (11215, '<솔로몬의 부귀영화> ○솔로몬이 병거와 마병을 모으매 병거가 천사백 대요 마병이 만 이천 명이라 병거성에도 두고 예루살렘 왕에게도 두었으며'),
    (11244, '○또 지성소를 지었으니 성전 넓이대로 길이가 이십 규빗이요 너비도 이십 규빗이라 순금 육백 달란트로 입혔으니'),
    (11246, '○지성소 안에 두 그룹의 형상을 새겨 만들어 금으로 입혔으니'),
    (11251, '<두 기둥> ○성전 앞에 기둥 둘을 만들었으니 높이가 삼십오 규빗이요 각 기둥 꼭대기의 머리가 다섯 규빗이라'),
    (11254, '<성전 안에 있는 물건들> 솔로몬이 또 놋으로 제단을 만들었으니 길이가 이십 규빗이요 너비가 이십 규빗이요 높이가 십 규빗이며'),
    (11257, '그 바다를 놋쇠 황소 열두 마리가 받쳤으니 세 마리는 북쪽을 향하였고 세 마리는 서쪽을 향하였고 세 마리는 남쪽을 향하였고 세 마리는 동쪽을 향하였으며 바다를 그 위에 놓았고 소의 엉덩이는 다 안으로 향하였으며'),
    (11260, '○또 규례대로 금으로 등잔대 열 개를 만들어 내전 안에 두었으니 왼쪽에 다섯 개요 오른쪽에 다섯 개이며'),
    (11264, '○후람이 또 솥과 부삽과 대접을 만들었더라 이와 같이 후람이 솔로몬 왕을 위하여 하나님의 성전에서 할 일을 마쳤으니'),
    (11272, '○솔로몬이 또 하나님의 전의 모든 기구를 만들었으니 곧 금 제단과 진설병 상들과'),
    (11150, '<다윗이 성전 건축을 지시하다> 다윗이 이스라엘 모든 고관들 곧 각 지파의 어른과 왕을 섬기는 반장들과 천부장들과 백부장들과 및 왕과 왕자의 모든 소유와 가축의 감독과 내시와 장사와 모든 용사를 예루살렘으로 소집하고'),
    (11153, '그러나 이스라엘 하나님 여호와께서 전에 나를 내 부친의 온 집에서 택하여 영원히 이스라엘 왕이 되게 하셨나니 곧 하나님이 유다 지파를 택하사 머리를 삼으시고 유다의 가문에서 내 부친의 집을 택하시고 내 부친의 아들들 중에서 나를 기뻐하사 온 이스라엘의 왕을 삼으셨느니라'),
    (11157, '이제 너희는 온 이스라엘 곧 여호와의 회중이 보는 데에서와 우리 하나님이 들으시는 데에서 너희 하나님 여호와의 모든 계명을 구하여 지키기로 하라 그리하면 너희가 이 아름다운 땅을 누리고 너희 후손에게 끼쳐 영원한 기업이 되게 하리라'),
    (11158, '내 아들 솔로몬아 너는 네 아버지의 하나님을 알고 온전한 마음과 기쁜 뜻으로 섬길지어다 여호와께서는 모든 마음을 감찰하사 모든 의도를 아시나니 네가 만일 그를 찾으면 만날 것이요 만일 네가 그를 버리면 그가 너를 영원히 버리시리라'),
    (11160, '○다윗이 성전의 복도와 그 집들과 그 곳간과 다락과 골방과 속죄소의 설계도를 그의 아들 솔로몬에게 주고'),
    (11169, '○또 그의 아들 솔로몬에게 이르되 너는 강하고 담대하게 이 일을 행하라 두려워하지 말며 놀라지 말라 네가 여호와의 성전 공사의 모든 일을 마치기까지 여호와 하나님 나의 하나님이 너와 함께 계시사 네게서 떠나지 아니하시고 너를 버리지 아니하시리라'),
    (11170, '제사장과 레위 사람의 반이 있으니 하나님의 성전의 모든 공사를 도울 것이요 또 모든 공사에 유능한 기술자가 기쁜 마음으로 너와 함께 할 것이요 또 모든 지휘관과 백성이 온전히 네 명령 아래에 있으리라'),
    (11171, '<성전 건축에 쓸 예물> 다윗 왕이 온 회중에게 이르되 내 아들 솔로몬이 유일하게 하나님께서 택하신 바 되었으나 아직 어리고 미숙하며 이 공사는 크도다 이 성전은 사람을 위한 것이 아니요 여호와 하나님을 위한 것이라'),
    (11176, '○이에 모든 가문의 지도자들과 이스라엘 모든 지파의 지도자들과 천부장과 백부장과 왕의 사무관이 다 즐거이 드리되'),
    (11180, '<다윗의 감사 기도> ○다윗이 온 회중 앞에서 여호와를 송축하여 이르되 우리 조상 이스라엘의 하나님 여호와여 주는 영원부터 영원까지 송축을 받으시옵소서'),
    (11187, '나의 하나님이여 주께서 마음을 감찰하시고 정직을 기뻐하시는 줄을 내가 아나이다 내가 정직한 마음으로 이 모든 것을 즐거이 드렸사오며 이제 내가 또 여기 있는 주의 백성이 주께 자원하여 드리는 것을 보오니 심히 기쁘도소이다'),
    (11190, '○다윗이 온 회중에게 이르되 너희는 너희 하나님 여호와를 송축하라 하매 회중이 그의 조상들의 하나님 여호와를 송축하고 머리를 숙여 여호와와 왕에게 절하고'),
    (11192, '이 날에 무리가 크게 기뻐하여 여호와 앞에서 먹으며 마셨더라 ○무리가 다윗의 아들 솔로몬을 다시 왕으로 삼아 기름을 부어 여호와께 돌려 주권자가 되게 하고 사독에게도 기름을 부어 제사장이 되게 하니라'),
    (11197, '<다윗의 행적> ○이새의 아들 다윗이 온 이스라엘의 왕이 되어'),
    (11219, '<성전 건축을 준비하다> 솔로몬이 여호와의 이름을 위하여 성전을 건축하고 자기 왕위를 위하여 궁궐 건축하기를 결심하니라'),
    (11222, '이제 내가 나의 하나님 여호와의 이름을 위하여 성전을 건축하여 구별하여 드리고 주 앞에서 향 재료를 사르며 항상 떡을 차려 놓으며 안식일과 초하루와 우리 하나님 여호와의 절기에 아침 저녁으로 번제를 드리려 하오니 이는 이스라엘의 영원한 규례니이다'),
    (11224, '누가 능히 하나님을 위하여 성전을 건축하리요 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 내가 누구이기에 어찌 능히 그를 위하여 성전을 건축하리요 그 앞에 분향하려 할 따름이니이다'),
    (11225, '이제 청하건대 당신은 금, 은, 동, 철로 제조하며 자색 홍색 청색 실로 직조하며 또 아로새길 줄 아는 재주 있는 사람 하나를 내게 보내어 내 아버지 다윗이 유다와 예루살렘에서 준비한 나의 재주 있는 사람들과 함께 일하게 하고'),
    (11229, '○두로 왕 후람이 솔로몬에게 답장하여 이르되 여호와께서 자기 백성을 사랑하시므로 당신을 세워 그들의 왕을 삼으셨도다'),
    (11230, '후람이 또 이르되 천지를 지으신 이스라엘의 하나님 여호와는 송축을 받으실지로다 다윗 왕에게 지혜로운 아들을 주시고 명철과 총명을 주시사 능히 여호와를 위하여 성전을 건축하고 자기 왕위를 위하여 궁궐을 건축하게 하시도다'),
    (11232, '이 사람은 단의 여자들 중 한 여인의 아들이요 그의 아버지는 두로 사람이라 능히 금, 은, 동, 철과 돌과 나무와 자색 청색 홍색 실과 가는 베로 일을 잘하며 또 모든 아로새기는 일에 익숙하고 모든 기묘한 양식에 능한 자이니 그에게 당신의 재주 있는 사람들과 당신의 아버지 내 주 다윗의 재주 있는 사람들과 함께 일하게 하소서'),
    (11235, '<성전 건축 시작> ○전에 솔로몬의 아버지 다윗이 이스라엘 땅에 사는 이방 사람들을 조사하였더니 이제 솔로몬이 다시 조사하매 모두 십오만 삼천 육백 명이라'),
    (11277, '<언약궤를 성전으로 옮기다> ○이에 솔로몬이 여호와의 언약궤를 다윗 성 곧 시온에서부터 메어 올리고자 하여 이스라엘 장로들과 모든 지파의 우두머리 곧 이스라엘 자손의 족장들을 다 예루살렘으로 소집하니'),
    (11286, '<여호와의 영광> ○이 때에는 제사장들이 그 반열대로 하지 아니하고 스스로 정결하게 하고 성소에 있다가 나오매'),
    (11288, '나팔 부는 자와 노래하는 자들이 일제히 소리를 내어 여호와를 찬송하며 감사하는데 나팔 불고 제금 치고 모든 악기를 울리며 소리를 높여 여호와를 찬송하여 이르되 선하시도다 그의 자비하심이 영원히 있도다 하매 그 때에 여호와의 전에 구름이 가득한지라'),
    (11372, '<스바 여왕이 솔로몬을 찾아오다> 스바 여왕이 솔로몬의 명성을 듣고 와서 어려운 질문으로 솔로몬을 시험하고자 하여 예루살렘에 이르니 매우 많은 시종들을 거느리고 향품과 많은 금과 보석을 낙타에 실었더라 그가 솔로몬에게 나아와 자기 마음에 있는 것을 다 말하매'),
    (11379, '당신의 하나님 여호와를 송축할지로다 하나님이 당신을 기뻐하시고 그 자리에 올리사 당신의 하나님 여호와를 위하여 왕이 되게 하셨도다 당신의 하나님이 이스라엘을 사랑하사 영원히 견고하게 하시려고 당신을 세워 그들의 왕으로 삼아 정의와 공의를 행하게 하셨도다 하고'),
    (11384, '<솔로몬의 재산과 지혜> ○솔로몬의 세입금의 무게가 금 육백육십육 달란트요'),
    (11393, '○솔로몬 왕의 재산과 지혜가 천하의 모든 왕들보다 큰지라'),
    (11400, '<솔로몬이 죽다> ○이 외에 솔로몬의 시종 행적은 선지자 나단의 글과 실로 사람 아히야의 예언과 선견자 잇도의 묵시 책 곧 잇도가 느밧의 아들 여로보암에 대하여 쓴 책에 기록되지 아니하였느냐'),
    (11354, '<솔로몬의 업적> 솔로몬이 여호와의 전과 자기의 궁궐을 이십 년 동안에 건축하기를 마치고'),
    (11356, '○솔로몬이 가서 하맛소바를 쳐서 점령하고'),
    (11360, '○이스라엘이 아닌 헷 족속과 아모리 족속과 브리스 족속과 히위 족속과 여부스 족속의 남아 있는 모든 자'),
    (11364, '○솔로몬이 바로의 딸을 데리고 다윗 성에서부터 그를 위하여 건축한 왕궁에 이르러 이르되 내 아내가 이스라엘 왕 다윗의 왕궁에 살지 못하리니 이는 여호와의 궤가 이른 곳은 다 거룩함이니라 하였더라'),
    (11365, '○솔로몬이 낭실 앞에 쌓은 여호와의 제단 위에 여호와께 번제를 드리되'),
    (11367, '○솔로몬이 또 그의 아버지 다윗의 규례를 따라 제사장들의 반열을 정하여 섬기게 하고 레위 사람들에게도 그 직분을 맡겨 매일의 일과대로 찬송하며 제사장들 앞에서 수종들게 하며 또 문지기들에게 그 반열을 따라 각 문을 지키게 하였으니 이는 하나님의 사람 다윗이 전에 이렇게 명령하였음이라'),
    (11369, '○솔로몬이 여호와의 전의 기초를 쌓던 날부터 준공하기까지 모든 것을 완비하였으므로 여호와의 전 공사가 결점 없이 끝나니라'),
    (11370, '○그 때에 솔로몬이 에돔 땅의 바닷가 에시온게벨과 엘롯에 이르렀더니'),
    (11403, '<북쪽 지파들의 배반> 르호보암이 세겜으로 갔으니 이는 온 이스라엘이 그를 왕으로 삼고자 하여 세겜에 이르렀음이더라'),
    (11408, '○르호보암 왕이 그의 아버지 솔로몬의 생전에 그 앞에 모셨던 원로들과 의논하여 이르되 너희는 이 백성에게 어떻게 대답하도록 권고하겠느냐 하니'),
    (11412, '함께 자라난 젊은 신하들이 왕께 말하여 이르되 이 백성들이 왕께 아뢰기를 왕의 아버지께서 우리의 멍에를 무겁게 하였으나 왕은 우리를 위하여 가볍게 하라 하였은즉 왕은 대답하시기를 내 새끼 손가락이 내 아버지의 허리보다 굵으니'),
    (11414, '○삼 일 만에 여로보암과 모든 백성이 르호보암에게 나왔으니 이는 왕이 명령하여 이르기를 삼 일 만에 내게로 다시 오라 하였음이라'),
    (11416, '젊은 신하들의 가르침을 따라 그들에게 말하여 이르되 내 아버지는 너희의 멍에를 무겁게 하였으나 나는 더 무겁게 할지라 내 아버지는 가죽 채찍으로 너희를 치셨으나 나는 전갈 채찍으로 치리라 하니라'),
    (11418, '○온 이스라엘은 왕이 자기들의 말을 듣지 아니함을 보고 왕에게 대답하여 이르되 우리가 다윗과 무슨 관계가 있느냐 이새의 아들에게서 받을 유산이 없도다 이스라엘아 각각 너희의 장막으로 돌아가라 다윗이여 이제 너는 네 집이나 돌보라 하고 온 이스라엘이 그들의 장막으로 돌아가니라'),
    (11422, '<스마야가 여호와의 말씀을 전하다> 르호보암이 예루살렘에 이르러 유다와 베냐민 족속을 모으니 택한 용사가 십팔만 명이라 이스라엘과 싸워 나라를 회복하여 르호보암에게 돌리려 하더니'),
    (11425, '여호와께서 이같이 말씀하시기를 너희는 올라가지 말라 너희 형제와 싸우지 말고 각기 집으로 돌아가라 이 일이 내게로 말미암아 난 것이라 하셨다 하라 하신지라 그들이 여호와의 말씀을 듣고 돌아가고 여로보암을 치러 가던 길에서 되돌아왔더라'),
    (11426, '<르호보암이 방비하는 성읍들을 건축하다> ○르호보암이 예루살렘에 살면서 유다 땅에 방비하는 성읍들을 건축하였으니'),
    (11434, '<제사장들과 레위 사람들이 유다로 오다> ○온 이스라엘의 제사장들과 레위 사람들이 그들의 모든 지방에서부터 르호보암에게 돌아오되'),
    (11439, '<르호보암의 가족> ○르호보암이 다윗의 아들 여리못의 딸 마할랏을 아내로 삼았으니 마할랏은 이새의 아들 엘리압의 딸 아비하일의 소생이라'),
    (11332, '<성전 낙성식> 솔로몬이 기도를 마치매 불이 하늘에서부터 내려와서 그 번제물과 제물들을 사르고 여호와의 영광이 그 성전에 가득하니'),
    (11335, '○이에 왕과 모든 백성이 여호와 앞에 제사를 드리니'),
    (11337, '그 때에 제사장들은 직분대로 모셔 서고 레위 사람도 여호와의 악기를 가지고 섰으니 이 악기는 전에 다윗 왕이 레위 사람들에게 여호와께 감사하게 하려고 만들어서 여호와의 인자하심이 영원함을 찬송하게 하던 것이라 제사장들은 무리 앞에서 나팔을 불고 온 이스라엘은 서 있더라'),
    (11339, '○그 때에 솔로몬이 칠 일 동안 절기를 지켰는데 하맛 어귀에서부터 애굽 강까지의 온 이스라엘의 심히 큰 회중이 모여 그와 함께 하였더니'),
    (11342, '<여호와께서 다시 솔로몬에게 나타나시다> ○솔로몬이 여호와의 전과 왕궁 건축을 마치고 솔로몬의 심중에 여호와의 전과 자기의 궁궐에 그가 이루고자 한 것을 다 형통하게 이루니라'),
    (11350, '○그러나 너희가 만일 돌아서서 내가 너희 앞에 둔 내 율례와 명령을 버리고 가서 다른 신들을 섬겨 그들을 경배하면'),
    (11353, '대답하기를 그들이 자기 조상들을 애굽 땅에서 인도하여 내신 자기 하나님 여호와를 버리고 다른 신들에게 붙잡혀서 그것들을 경배하여 섬기므로 여호와께서 이 모든 재앙을 그들에게 내리셨다 하리라 하셨더라'),
    (11489, '아사가 일찍이 유다 사람에게 이르되 우리가 우리 하나님 여호와를 찾았으므로 이 땅이 아직 우리 앞에 있나니 우리가 이 성읍들을 건축하고 그 주위에 성곽과 망대와 문과 빗장을 만들자 우리가 주를 찾았으므로 주께서 우리 사방에 평안을 주셨느니라 하고 이에 그들이 성읍을 형통하게 건축하였더라'),
    (11491, '○구스 사람 세라가 그들을 치려 하여 군사 백만 명과 병거 삼백 대를 거느리고 마레사에 이르매'),
    (11493, '아사가 그의 하나님 여호와께 부르짖어 이르되 여호와여 힘이 강한 자와 약한 자 사이에는 주밖에 도와 줄 이가 없사오니 우리 하나님 여호와여 우리를 도우소서 우리가 주를 의지하오며 주의 이름을 의탁하옵고 이 많은 무리를 치러 왔나이다 여호와여 주는 우리 하나님이시오니 원하건대 사람이 주를 이기지 못하게 하옵소서 하였더니'),
    (11495, '아사와 그와 함께 한 백성이 구스 사람들을 추격하여 그랄까지 이르매 이에 구스 사람들이 엎드러지고 살아 남은 자가 없었으니 이는 여호와 앞에서와 그의 군대 앞에서 패망하였음이라 노략한 물건이 매우 많았더라'),
    (11290, '<솔로몬의 축복> 그 때에 솔로몬이 이르되 여호와께서 캄캄한 데 계시겠다 말씀하셨사오나'),
    (11294, '내가 내 백성을 애굽 땅에서 인도하여 낸 날부터 내 이름을 둘 만한 집을 건축하기 위하여 이스라엘 모든 지파 가운데서 아무 성읍도 택하지 아니하였으며 내 백성 이스라엘의 주권자가 될 사람을 아무도 택하지 아니하였더니'),
    (11299, '이제 여호와께서 말씀하신 대로 이루셨도다 내가 여호와께서 말씀하신 대로 내 아버지 다윗을 대신하여 일어나 이스라엘 왕위에 앉고 이스라엘의 하나님 여호와의 이름을 위하여 성전을 건축하고'),
    (11301, '<솔로몬의 기도> ○솔로몬이 여호와의 제단 앞에서 이스라엘의 모든 회중과 마주 서서 그의 손을 펴니라'),
    (11302, '솔로몬이 일찍이 놋으로 대를 만들었으니 길이가 다섯 규빗이요 너비가 다섯 규빗이요 높이가 세 규빗이라 뜰 가운데에 두었더니 그가 그 위에 서서 이스라엘의 모든 회중 앞에서 무릎을 꿇고 하늘을 향하여 손을 펴고'),
    (11305, '이스라엘의 하나님 여호와여 주께서 주의 종 내 아버지 다윗에게 말씀하시기를 네 자손이 그들의 행위를 삼가서 네가 내 앞에서 행한 것 같이 내 율법대로 행하기만 하면 네게로부터 나서 이스라엘 왕위에 앉을 사람이 내 앞에서 끊어지지 아니하리라 하셨사오니 이제 다윗을 위하여 그 허락하신 말씀을 지키시옵소서'),
    (11307, '○하나님이 참으로 사람과 함께 땅에 계시리이까 보소서 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까'),
    (11311, '○만일 어떤 사람이 그의 이웃에게 범죄하므로 맹세시킴을 받고 그가 와서 이 성전에 있는 주의 제단 앞에서 맹세하거든'),
    (11313, '○만일 주의 백성 이스라엘이 주께 범죄하여 적국 앞에 패하게 되므로 주의 이름을 인정하고 주께로 돌아와서 이 성전에서 주께 빌며 간구하거든'),
    (11315, '○만일 그들이 주께 범죄함으로 말미암아 하늘이 닫히고 비가 내리지 않는 주의 벌을 받을 때에 이 곳을 향하여 빌며 주의 이름을 인정하고 그들의 죄에서 떠나거든'),
    (11317, '○만일 이 땅에 기근이나 전염병이 있거나 곡식이 시들거나 깜부기가 나거나 메뚜기나 황충이 나거나 적국이 와서 성읍들을 에워싸거나 무슨 재앙이나 무슨 질병이 있거나를 막론하고'),
    (11321, '○주의 백성 이스라엘에 속하지 않은 이방인에게 대하여도 그들이 주의 큰 이름과 능한 손과 펴신 팔을 위하여 먼 지방에서 와서 이 성전을 향하여 기도하거든'),
    (11322, '주는 계신 곳 하늘에서 들으시고 모든 이방인이 주께 부르짖는 대로 이루사 땅의 만민이 주의 이름을 알고 주의 백성 이스라엘처럼 경외하게 하시오며 또 내가 건축한 이 성전을 주의 이름으로 일컫는 줄을 알게 하옵소서'),
    (11323, '○주의 백성이 그 적국과 더불어 싸우고자 하여 주께서 보내신 길로 나갈 때에 그들이 주께서 택하신 이 성과 내가 주의 이름을 위하여 건축한 성전 있는 쪽을 향하여 주께 기도하거든'),
    (11327, '자기들을 사로잡아 간 적국의 땅에서 온 마음과 온 뜻으로 주께 돌아와서 주께서 그들의 조상들에게 주신 땅과 주께서 택하신 성과 내가 주의 이름을 위하여 건축한 성전 있는 쪽을 향하여 기도하거든'),
    (11330, '여호와 하나님이여 일어나 들어가사 주의 능력의 궤와 함께 주의 평안한 처소에 계시옵소서 여호와 하나님이여 원하옵건대 주의 제사장들에게 구원을 입게 하시고 또 주의 성도들에게 은혜를 기뻐하게 하옵소서'),
    (11461, '<아비야와 여로보암의 전쟁> 여로보암 왕 열여덟째 해에 아비야가 유다의 왕이 되고'),
    (11469, '너희가 아론 자손인 여호와의 제사장들과 레위 사람들을 쫓아내고 이방 백성들의 풍속을 따라 제사장을 삼지 아니하였느냐 누구를 막론하고 어린 수송아지 한 마리와 숫양 일곱 마리를 끌고 와서 장립을 받고자 하는 자마다 허무한 신들의 제사장이 될 수 있도다'),
    (11471, '매일 아침 저녁으로 여호와 앞에 번제를 드리며 분향하며 또 깨끗한 상에 진설병을 놓고 또 금 등잔대가 있어 그 등에 저녁마다 불을 켜나니 우리는 우리 하나님 여호와의 계명을 지키나 너희는 그를 배반하였느니라'),
    (11472, '하나님이 우리와 함께 하사 우리의 머리가 되시고 그의 제사장들도 우리와 함께 하여 전쟁의 나팔을 불어 너희를 공격하느니라 이스라엘 자손들아 너희 조상들의 하나님 여호와와 싸우지 말라 너희가 형통하지 못하리라'),
    (11473, '○여로보암이 유다의 뒤를 둘러 복병하였으므로 그 앞에는 이스라엘 사람들이 있고 그 뒤에는 복병이 있는지라'),
    (11445, '<애굽이 유다를 치다> 르호보암의 나라가 견고하고 세력이 강해지매 그가 여호와의 율법을 버리니 온 이스라엘이 본받은지라'),
    (11449, '그 때에 유다 방백들이 시삭의 일로 예루살렘에 모였는지라 선지자 스마야가 르호보암과 방백들에게 나아와 이르되 여호와께서 이같이 말씀하시기를 너희가 나를 버렸으므로 나도 너희를 버려 시삭의 손에 넘겼노라 하셨다 한지라'),
    (11451, '여호와께서 그들이 스스로 겸비함을 보신지라 여호와의 말씀이 스마야에게 임하여 이르시되 그들이 스스로 겸비하였으니 내가 멸하지 아니하고 저희를 조금 구원하여 나의 노를 시삭의 손을 통하여 예루살렘에 쏟지 아니하리라'),
    (11453, '○애굽 왕 시삭이 올라와서 예루살렘을 치고 여호와의 전 보물과 왕궁의 보물을 모두 빼앗고 솔로몬이 만든 금 방패도 빼앗은지라'),
    (11457, '<르호보암이 죽다> ○르호보암 왕은 예루살렘에서 스스로 세력을 굳게 하여 다스리니라 르호보암이 왕위에 오를 때에 나이가 사십일 세라 예루살렘 곧 여호와께서 이스라엘의 모든 지파 중에서 택하여 그의 이름을 두신 성에서 십칠 년 동안 다스리니라 르호보암의 어머니의 이름은 나아마요 암몬 여인이더라'),
    (11459, '○르호보암의 처음부터 끝까지의 행적은 선지자 스마야와 선견자 잇도의 족보책에 기록되지 아니하였느냐 르호보암과 여로보암 사이에 항상 전쟁이 있으니라'),
    (11499, '그가 나가서 아사를 맞아 이르되 아사와 및 유다와 베냐민의 무리들아 내 말을 들으라 너희가 여호와와 함께 하면 여호와께서 너희와 함께 하실지라 너희가 만일 그를 찾으면 그가 너희와 만나게 되시려니와 너희가 만일 그를 버리면 그도 너희를 버리시리라'),
    (11505, '○아사가 이 말 곧 선지자 오뎃의 예언을 듣고 마음을 강하게 하여 가증한 물건들을 유다와 베냐민 온 땅에서 없애고 또 에브라임 산지에서 빼앗은 성읍들에서도 없애고 또 여호와의 낭실 앞에 있는 여호와의 제단을 재건하고'),
    (11506, '또 유다와 베냐민의 무리를 모으고 에브라임과 므낫세와 시므온 가운데에서 나와서 저희 중에 머물러 사는 자들을 모았으니 이는 이스라엘 사람들이 아사의 하나님 여호와께서 그와 함께 하심을 보고 아사에게로 돌아오는 자가 많았음이더라'),
    (11513, '○아사 왕의 어머니 마아가가 아세라의 가증한 목상을 만들었으므로 아사가 그의 태후의 자리를 폐하고 그의 우상을 찍고 빻아 기드론 시냇가에서 불살랐으니'),
    (11517, '<이스라엘과 유다의 충돌> 아사 왕 제삼십육년에 이스라엘 왕 바아사가 유다를 치러 올라와서 라마를 건축하여 사람을 유다 왕 아사에게 왕래하지 못하게 하려 한지라'),
    (11523, '<선견자 하나니> ○그 때에 선견자 하나니가 유다 왕 아사에게 나와서 그에게 이르되 왕이 아람 왕을 의지하고 왕의 하나님 여호와를 의지하지 아니하였으므로 아람 왕의 군대가 왕의 손에서 벗어났나이다'),
    (11527, '<아사가 죽다> ○아사의 처음부터 끝까지의 행적은 유다와 이스라엘 열왕기에 기록되니라'),
    (11537, '○그가 왕위에 있은 지 삼 년에 그의 방백들 벤하일과 오바댜와 스가랴와 느다넬과 미가야를 보내어 유다 여러 성읍에 가서 가르치게 하고'),
    (11538, '또 그들과 함께 레위 사람 스마야와 느다냐와 스바댜와 아사헬과 스미라못과 여호나단과 아도니야와 도비야와 도바도니야 등 레위 사람들을 보내고 또 저희와 함께 제사장 엘리사마와 여호람을 보내었더니'),
    (11540, '<여호사밧이 강대하여지다> ○여호와께서 유다 사방의 모든 나라에 두려움을 주사 여호사밧과 싸우지 못하게 하시매'),
    (11550, '<선지자 미가야가 아합 왕에게 경고하다> 여호사밧이 부귀와 영광을 크게 떨쳤고 아합 가문과 혼인함으로 인척 관계를 맺었더라'),
    (11552, '이스라엘 왕 아합이 유다 왕 여호사밧에게 이르되 당신이 나와 함께 길르앗 라못으로 가시겠느냐 하니 여호사밧이 대답하되 나는 당신과 다름이 없고 내 백성은 당신의 백성과 다름이 없으니 당신과 함께 싸우리이다 하는지라'),
    (11553, '○여호사밧이 또 이스라엘 왕에게 이르되 청하건대 먼저 여호와의 말씀이 어떠하신지 오늘 물어 보소서 하더라'),
    (11556, '이스라엘 왕이 여호사밧에게 이르되 아직도 이믈라의 아들 미가야 한 사람이 있으니 그로 말미암아 여호와께 물을 수 있으나 그는 내게 대하여 좋은 일로는 예언하지 아니하고 항상 나쁜 일로만 예언하기로 내가 그를 미워하나이다 하더라 여호사밧이 이르되 왕은 그런 말씀을 마소서 하니'),
    (11572, '○그나아나의 아들 시드기야가 가까이 와서 미가야의 뺨을 치며 이르되 여호와의 영이 나를 떠나 어디로 가서 네게 말씀하더냐 하는지라'),
    (11577, '<아합이 죽다> ○이스라엘 왕과 유다 왕 여호사밧이 길르앗 라못으로 올라가니라'),
    (11580, '병거의 지휘관들이 여호사밧을 보고 이르되 이가 이스라엘 왕이라 하고 돌아서서 그와 싸우려 한즉 여호사밧이 소리를 지르매 여호와께서 그를 도우시며 하나님이 그들을 감동시키사 그를 떠나가게 하신지라'),
    (11585, '하나니의 아들 선견자 예후가 나가서 여호사밧 왕을 맞아 이르되 왕이 악한 자를 돕고 여호와를 미워하는 자들을 사랑하는 것이 옳으니이까 그러므로 여호와께로부터 진노하심이 왕에게 임하리이다'),
    (11587, '<여호사밧의 개혁> ○여호사밧이 예루살렘에 살더니 다시 나가서 브엘세바에서부터 에브라임 산지까지 민간에 두루 다니며 그들을 그들의 조상들의 하나님 여호와께로 돌아오게 하고'),
    (11590, '그런즉 너희는 여호와를 두려워하는 마음으로 삼가 행하라 우리의 하나님 여호와께서는 불의함도 없으시고 치우침도 없으시고 뇌물을 받는 일도 없으시니라 하니라'),
    (11591, '○여호사밧이 또 예루살렘에서 레위 사람들과 제사장들과 이스라엘 족장들 중에서 사람을 세워 여호와께 속한 일과 예루살렘 주민의 모든 송사를 재판하게 하고'),
    (11593, '어떤 성읍에 사는 너희 형제가 혹 피를 흘림이나 혹 율법이나 계명이나 율례나 규례로 말미암아 너희에게 와서 송사하거든 어떤 송사든지 그들에게 경고하여 여호와께 죄를 범하지 않게 하여 너희와 너희 형제에게 진노하심이 임하지 말게 하라 너희가 이렇게 행하면 죄가 없으리라'),
    (11594, '여호와께 속한 모든 일에는 대제사장 아마랴가 너희를 다스리고 왕에게 속한 모든 일은 유다 지파의 어른 이스마엘의 아들 스바댜가 다스리고 레위 사람들은 너희 앞에 관리가 되리라 너희는 힘써 행하라 여호와께서 선한 자와 함께 하실지로다 하니라'),
    (11652, '<유다 왕 아하시야> 예루살렘 주민이 여호람의 막내 아들 아하시야에게 왕위를 계승하게 하였으니 이는 전에 아라비아 사람들과 함께 와서 진을 치던 부대가 그의 모든 형들을 죽였음이라 그러므로 유다 왕 여호람의 아들 아하시야가 왕이 되었더라'),
    (11657, '요람이 아람 왕 하사엘과 싸울 때에 라마에서 맞아 상한 것을 치료하려 하여 이스르엘로 돌아왔더라 아합의 아들 요람이 병이 있으므로 유다 왕 여호람의 아들 아사랴가 이스르엘에 내려가서 방문하였더라'),
    (11658, '○아하시야가 요람에게 가므로 해를 입었으니 이는 하나님께로 말미암은 것이라 아하시야가 갔다가 요람과 함께 나가서 님시의 아들 예후를 맞았으니 그는 여호와께서 기름을 부으시고 아합의 집을 멸하게 하신 자이더라'),
    (11660, '아하시야는 사마리아에 숨었더니 예후가 찾으매 무리가 그를 예후에게로 잡아가서 죽이고 이르기를 그는 전심으로 여호와를 구하던 여호사밧의 아들이라 하고 장사하였더라 이에 아하시야의 집이 약하여 왕위를 힘으로 지키지 못하게 되니라'),
    (11661, '<유다 여왕 아달랴> ○아하시야의 어머니 아달랴가 자기의 아들이 죽은 것을 보고 일어나 유다 집의 왕국의 씨를 모두 진멸하였으나'),
    (11662, '왕의 딸 여호사브앗이 아하시야의 아들 요아스를 왕자들이 죽임을 당하는 중에서 몰래 빼내어 그와 그의 유모를 침실에 숨겨 아달랴를 피하게 하였으므로 아달랴가 그를 죽이지 못하였더라 여호사브앗은 여호람 왕의 딸이요 아하시야의 누이요 제사장 여호야다의 아내이더라'),
    (11632, '<유다 왕 여호람> 여호사밧이 그의 조상들과 함께 누우매 그의 조상들과 함께 다윗 성에 장사되고 그의 아들 여호람이 대신하여 왕이 되니라'),
    (11639, '○여호람 때에 에돔이 배반하여 유다의 지배하에서 벗어나 자기 위에 왕을 세우므로'),
    (11641, '이와 같이 에돔이 배반하여 유다의 지배하에서 벗어났더니 오늘까지 그러하였으며 그 때에 립나도 배반하여 여호람의 지배 하에서 벗어났으니 이는 그가 그의 조상들의 하나님 여호와를 버렸음이더라'),
    (11642, '○여호람이 또 유다 여러 산에 산당을 세워 예루살렘 주민으로 음행하게 하고 또 유다를 미혹하게 하였으므로'),
    (11647, '○여호와께서 블레셋 사람들과 구스에서 가까운 아라비아 사람들의 마음을 격동시키사 여호람을 치게 하셨으므로'),
    (11649, '○이 모든 일 후에 여호와께서 여호람을 치사 능히 고치지 못할 병이 그 창자에 들게 하셨으므로'),
    (11763, '<유다 왕 요담> 요담이 왕위에 오를 때에 나이가 이십오 세라 예루살렘에서 십육 년 동안 다스리니라 그의 어머니의 이름은 여루사요 사독의 딸이더라'),
    (11664, '<아달랴에 대한 반역> 제칠년에 여호야다가 용기를 내어 백부장 곧 여로함의 아들 아사랴와 여호하난의 아들 이스마엘과 오벳의 아들 아사랴와 아다야의 아들 마아세야와 시그리의 아들 엘리사밧 등과 더불어 언약을 세우매'),
    (11671, '○레위 사람들과 모든 유다 사람들이 제사장 여호야다가 명령한 모든 것을 준행하여 각기 수하에 안식일에 당번인 자와 안식일에 비번인 자들을 거느리고 있었으니 이는 제사장 여호야다가 비번인 자들을 보내지 아니함이더라'),
    (11675, '○아달랴가 백성들이 뛰며 왕을 찬송하는 소리를 듣고 여호와의 전에 들어가서 백성에게 이르러'),
    (11676, '보매 왕이 성전 문 기둥 곁에 섰고 지휘관들과 나팔수들이 왕의 곁에 모셔 서 있으며 그 땅의 모든 백성들이 즐거워하여 나팔을 불며 노래하는 자들은 주악하며 찬송을 인도하는지라 이에 아달랴가 그의 옷을 찢으며 외치되 반역이로다 반역이로다 하매'),
    (11679, '<여호야다의 개혁> ○여호야다가 자기와 모든 백성과 왕 사이에 언약을 세워 여호와의 백성이 되리라 한지라'),
    (11681, '여호야다가 여호와의 전의 직원들을 세워 레위 제사장의 수하에 맡기니 이들은 다윗이 전에 그들의 반열을 나누어서 여호와의 전에서 모세의 율법에 기록한 대로 여호와께 번제를 드리며 자기들의 정한 규례대로 즐거이 부르고 노래하게 하였던 자들이더라'),
    (11685, '<유다 왕 요아스> 요아스가 왕위에 오를 때에 나이가 칠 세라 예루살렘에서 사십 년 동안 다스리니라 그의 어머니의 이름은 시비아요 브엘세바 사람이더라'),
    (11688, '○그 후에 요아스가 여호와의 전을 보수할 뜻을 두고'),
    (11689, '제사장들과 레위 사람들을 모으고 그들에게 이르되 너희는 유다 여러 성읍에 가서 모든 이스라엘에게 해마다 너희의 하나님의 전을 수리할 돈을 거두되 그 일을 빨리 하라 하였으나 레위 사람이 빨리 하지 아니한지라'),
    (11690, '왕이 대제사장 여호야다를 불러 이르되 네가 어찌하여 레위 사람들을 시켜서 여호와의 종 모세와 이스라엘의 회중이 성막을 위하여 정한 세를 유다와 예루살렘에서 거두게 하지 아니하였느냐 하니'),
    (11692, '○이에 왕이 말하여 한 궤를 만들어 여호와의 전 문 밖에 두게 하고'),
    (11695, '레위 사람들이 언제든지 궤를 메고 왕의 관리에게 가지고 가서 돈이 많은 것을 보이면 왕의 서기관과 대제사장에게 속한 관원이 와서 그 궤를 쏟고 다시 그 곳에 가져다 두었더라 때때로 이렇게 하여 돈을 많이 거두매'),
    (11698, '공사를 마친 후에 그 남은 돈을 왕과 여호야다 앞으로 가져왔으므로 그것으로 여호와의 전에 쓸 그릇을 만들었으니 곧 섬겨 제사 드리는 그릇이며 또 숟가락과 금은 그릇들이라 여호야다가 세상에 사는 모든 날에 여호와의 전에 항상 번제를 드렸더라'),
    (11699, '<여호야다의 정책이 뒤집히다> ○여호야다가 나이가 많고 늙어서 죽으니 죽을 때에 백삼십 세라'),
    (11704, '○이에 하나님의 영이 제사장 여호야다의 아들 스가랴를 감동시키시매 그가 백성 앞에 높이 서서 그들에게 이르되 하나님이 이같이 말씀하시기를 너희가 어찌하여 여호와의 명령을 거역하여 스스로 형통하지 못하게 하느냐 하셨나니 너희가 여호와를 버렸으므로 여호와께서도 너희를 버리셨느니라 하나'),
    (11707, '<요아스가 죽다> ○일 주년 말에 아람 군대가 요아스를 치려고 올라와서 유다와 예루살렘에 이르러 백성 중에서 모든 방백들을 다 죽이고 노략한 물건을 다메섹 왕에게로 보내니라'),
    (11708, '아람 군대가 적은 무리로 왔으나 여호와께서 심히 큰 군대를 그들의 손에 넘기셨으니 이는 유다 사람들이 그들의 조상들의 하나님 여호와를 버렸음이라 이와 같이 아람 사람들이 요아스를 징벌하였더라'),
    (11709, '요아스가 크게 부상하매 적군이 그를 버리고 간 후에 그의 신하들이 제사장 여호야다의 아들들의 피로 말미암아 반역하여 그를 그의 침상에서 쳐죽인지라 다윗 성에 장사하였으나 왕들의 묘실에는 장사하지 아니하였더라'),
    (11599, '○여호사밧이 여호와의 전 새 뜰 앞에서 유다와 예루살렘의 회중 가운데 서서'),
    (11600, '이르되 우리 조상들의 하나님 여호와여 주는 하늘에서 하나님이 아니시니이까 이방 사람들의 모든 나라를 다스리지 아니하시나이까 주의 손에 권세와 능력이 있사오니 능히 주와 맞설 사람이 없나이다'),
    (11603, '만일 재앙이나 난리나 견책이나 전염병이나 기근이 우리에게 임하면 주의 이름이 이 성전에 있으니 우리가 이 성전 앞과 주 앞에 서서 이 환난 가운데에서 주께 부르짖은즉 들으시고 구원하시리라 하였나이다'),
    (11608, '○여호와의 영이 회중 가운데에서 레위 사람 야하시엘에게 임하셨으니 그는 아삽 자손 맛다냐의 현손이요 여이엘의 증손이요 브나야의 손자요 스가랴의 아들이더라'),
    (11609, '야하시엘이 이르되 온 유다와 예루살렘 주민과 여호사밧 왕이여 들을지어다 여호와께서 이같이 너희에게 말씀하시기를 너희는 이 큰 무리로 말미암아 두려워하거나 놀라지 말라 이 전쟁은 너희에게 속한 것이 아니요 하나님께 속한 것이니라'),
    (11611, '이 전쟁에는 너희가 싸울 것이 없나니 대열을 이루고 서서 너희와 함께 한 여호와가 구원하는 것을 보라 유다와 예루살렘아 너희는 두려워하지 말며 놀라지 말고 내일 그들을 맞서 나가라 여호와가 너희와 함께 하리라 하셨느니라 하매'),
    (11614, '○이에 백성들이 아침에 일찍이 일어나서 드고아 들로 나가니라 나갈 때에 여호사밧이 서서 이르되 유다와 예루살렘 주민들아 내 말을 들을지어다 너희는 너희 하나님 여호와를 신뢰하라 그리하면 견고히 서리라 그의 선지자들을 신뢰하라 그리하면 형통하리라 하고'),
    (11618, '○유다 사람이 들 망대에 이르러 그 무리를 본즉 땅에 엎드러진 시체들뿐이요 한 사람도 피한 자가 없는지라'),
    (11619, '여호사밧과 그의 백성이 가서 적군의 물건을 탈취할새 본즉 그 가운데에 재물과 의복과 보물이 많이 있으므로 각기 탈취하는데 그 물건이 너무 많아 능히 가져갈 수 없을 만큼 많으므로 사흘 동안에 거두어들이고'),
    (11625, '<여호사밧의 행적> ○여호사밧이 유다의 왕이 되어 왕위에 오를 때에 나이가 삼십오 세라 예루살렘에서 이십오 년 동안 다스리니라 그의 어머니의 이름은 아수바라 실히의 딸이더라'),
    (11629, '○유다 왕 여호사밧이 나중에 이스라엘 왕 아하시야와 교제하였는데 아하시야는 심히 악을 행하는 자였더라'),
    (11631, '마레사 사람 도다와후의 아들 엘리에셀이 여호사밧을 향하여 예언하여 이르되 왕이 아하시야와 교제하므로 여호와께서 왕이 지은 것들을 파하시리라 하더니 이에 그 배들이 부서져서 다시스로 가지 못하였더라'),
    (11740, '<유다 왕 웃시야> 유다 온 백성이 나이가 십육 세 된 웃시야를 세워 그의 아버지 아마샤를 대신하여 왕으로 삼으니'),
    (11745, '○웃시야가 나가서 블레셋 사람들과 싸우고 가드 성벽과 야브네 성벽과 아스돗 성벽을 헐고 아스돗 땅과 블레셋 사람들 가운데에 성읍들을 건축하매'),
    (11754, '또 예루살렘에서 재주 있는 사람들에게 무기를 고안하게 하여 망대와 성곽 위에 두어 화살과 큰 돌을 쏘고 던지게 하였으니 그의 이름이 멀리 퍼짐은 기이한 도우심을 얻어 강성하여짐이었더라'),
    (11755, '<웃시야에게 나병이 생기다> ○그가 강성하여지매 그의 마음이 교만하여 악을 행하여 그의 하나님 여호와께 범죄하되 곧 여호와의 성전에 들어가서 향단에 분향하려 한지라'),
    (11757, '웃시야 왕 곁에 서서 그에게 이르되 웃시야여 여호와께 분향하는 일은 왕이 할 바가 아니요 오직 분향하기 위하여 구별함을 받은 아론의 자손 제사장들이 할 바니 성소에서 나가소서 왕이 범죄하였으니 하나님 여호와에게서 영광을 얻지 못하리이다'),
    (11712, '<유다 왕 아마샤> 아마샤가 왕위에 오를 때에 나이가 이십오 세라 예루살렘에서 이십구 년 동안 다스리니라 그의 어머니의 이름은 여호앗단이요 예루살렘 사람이더라'),
    (11715, '그들의 자녀들은 죽이지 아니하였으니 이는 모세의 율법책에 기록된 대로 함이라 곧 여호와께서 명령하여 이르시기를 자녀로 말미암아 아버지를 죽이지 말 것이요 아버지로 말미암아 자녀를 죽이지 말 것이라 오직 각 사람은 자기의 죄로 말미암아 죽을 것이니라 하셨더라'),
    (11716, '<아마샤와 에돔의 전쟁> ○아마샤가 유다 사람들을 모으고 그 여러 족속을 따라 천부장들과 백부장들을 세우되 유다와 베냐민을 함께 그리하고 이십 세 이상으로 계수하여 창과 방패를 잡고 능히 전장에 나갈 만한 자 삼십만 명을 얻고'),
    (11725, '○아마샤가 에돔 사람들을 죽이고 돌아올 때에 세일 자손의 신들을 가져와서 자기의 신으로 세우고 그것들 앞에 경배하며 분향한지라'),
    (11726, '그러므로 여호와께서 아마샤에게 진노하사 한 선지자를 그에게 보내시니 그가 이르되 저 백성의 신들이 그들의 백성을 왕의 손에서 능히 구원하지 못하였거늘 왕은 어찌하여 그 신들에게 구하나이까 하며'),
    (11727, '선지자가 아직 그에게 말할 때에 왕이 그에게 이르되 우리가 너를 왕의 모사로 삼았느냐 그치라 어찌하여 맞으려 하느냐 하니 선지자가 그치며 이르되 왕이 이 일을 행하고 나의 경고를 듣지 아니하니 하나님이 왕을 멸하시기로 작정하신 줄 아노라 하였더라'),
    (11728, '<유다와 이스라엘의 전쟁> ○유다 왕 아마샤가 상의하고 예후의 손자 여호아하스의 아들 이스라엘 왕 요아스에게 사신을 보내어 이르되 오라 서로 대면하자 한지라'),
    (11729, '이스라엘 왕 요아스가 유다 왕 아마샤에게 사람을 보내어 이르되 레바논 가시나무가 레바논 백향목에게 전갈을 보내어 이르기를 네 딸을 내 아들에게 주어 아내로 삼게 하라 하였더니 레바논 들짐승이 지나가다가 그 가시나무를 짓밟았느니라'),
    (11734, '이스라엘 왕 요아스가 벧세메스에서 여호아하스의 손자 요아스의 아들 유다 왕 아마샤를 사로잡고 예루살렘에 이르러 예루살렘 성벽을 에브라임 문에서부터 성 모퉁이 문까지 사백 규빗을 헐고'),
    (11736, '○이스라엘 왕 요아하스의 아들 요아스가 죽은 후에도 유다 왕 요아스의 아들 아마샤가 십오 년 간 생존하였더라'),
    (11772, '<유다 왕 아하스> 아하스가 왕위에 오를 때에 나이가 이십 세라 예루살렘에서 십육 년 동안 다스렸으나 그의 조상 다윗과 같지 아니하여 여호와 보시기에 정직하게 행하지 아니하고'),
    (11779, '<선지자 오뎃> ○이스라엘 자손이 그들의 형제 중에서 그들의 아내와 자녀를 합하여 이십만 명을 사로잡고 그들의 재물을 많이 노략하여 사마리아로 가져가니'),
    (11780, '그 곳에 여호와의 선지자가 있는데 이름은 오뎃이라 그가 사마리아로 돌아오는 군대를 영접하고 그들에게 이르되 너희 조상의 하나님 여호와께서 유다에게 진노하셨으므로 너희 손에 넘기셨거늘 너희의 노기가 충천하여 살륙하고'),
    (11784, '그들에게 이르되 너희는 이 포로를 이리로 끌어들이지 못하리라 너희가 행하는 일이 우리를 여호와께 허물이 있게 함이니 우리의 죄와 허물을 더하게 함이로다 우리의 허물이 이미 커서 진노하심이 이스라엘에게 임박하였느니라 하매'),
    (11786, '이 위에 이름이 기록된 자들이 일어나서 포로를 맞고 노략하여 온 것 중에서 옷을 가져다가 벗은 자들에게 입히며 신을 신기며 먹이고 마시게 하며 기름을 바르고 그 약한 자들은 모두 나귀에 태워 데리고 종려나무 성 여리고에 이르러 그의 형제에게 돌려준 후에 사마리아로 돌아갔더라'),
    (11787, '<아하스가 앗수르에 도움을 구하다> ○그 때에 아하스 왕이 앗수르 왕에게 사람을 보내어 도와 주기를 구하였으니'),
    (11789, '블레셋 사람들도 유다의 평지와 남방 성읍들을 침노하여 벧세메스와 아얄론과 그데롯과 소고 및 그 주변 마을들과 딤나 및 그 주변 마을들과 김소 및 그 주변 마을들을 점령하고 거기에 살았으니'),
    (11793, '<아하스의 범죄> ○이 아하스 왕이 곤고할 때에 더욱 여호와께 범죄하여'),
    (11862, '<히스기야의 개혁> 이 모든 일이 끝나매 거기에 있는 이스라엘 무리가 나가서 유다 여러 성읍에 이르러 주상들을 깨뜨리며 아세라 목상들을 찍으며 유다와 베냐민과 에브라임과 므낫세 온 땅에서 산당들과 제단들을 제거하여 없애고 이스라엘 모든 자손이 각각 자기들의 본성 기업으로 돌아갔더라'),
    (11863, '○히스기야가 제사장들과 레위 사람들의 반열을 정하고 그들의 반열에 따라 각각 그들의 직임을 행하게 하되 곧 제사장들과 레위 사람들에게 번제와 화목제를 드리며 여호와의 휘장 문에서 섬기며 감사하며 찬송하게 하고'),
    (11871, '사독의 족속 대제사장 아사랴가 그에게 대답하여 이르되 백성이 예물을 여호와의 전에 드리기 시작함으로부터 우리가 만족하게 먹었으나 남은 것이 많으니 이는 여호와께서 그의 백성에게 복을 주셨음이라 그 남은 것이 이렇게 많이 쌓였나이다'),
    (11872, '○그 때에 히스기야가 명령하여 여호와의 전 안에 방들을 준비하라 하므로 그렇게 준비하고'),
    (11874, '여히엘과 아사시야와 나핫과 아사헬과 여리못과 요사밧과 엘리엘과 이스마갸와 마핫과 브나야는 고나냐와 그의 아우 시므이의 수하에서 보살피는 자가 되니 이는 히스기야 왕과 하나님의 전을 관리하는 아사랴가 명령한 바이며'),
    (11881, '○히스기야가 온 유다에 이같이 행하되 그의 하나님 여호와 보시기에 선과 정의와 진실함으로 행하였으니'),
    (11799, '<유다 왕 히스기야의 성전 정화> 히스기야가 왕위에 오를 때에 나이가 이십오 세라 예루살렘에서 이십구 년 동안 다스리니라 그의 어머니의 이름은 아비야요 스가랴의 딸이더라'),
    (11810, '○이에 레위 사람들이 일어나니 곧 그핫의 자손 중 아마새의 아들 마핫과 아사랴의 아들 요엘과 므라리의 자손 중 압디의 아들 기스와 여할렐렐의 아들 아사랴와 게르손 사람 중 심마의 아들 요아와 요아의 아들 에덴과'),
    (11818, '<성전의 일이 갖추어지다> ○히스기야 왕이 일찍이 일어나 성읍의 귀인들을 모아 여호와의 전에 올라가서'),
    (11819, '수송아지 일곱 마리와 숫양 일곱 마리와 어린 양 일곱 마리와 숫염소 일곱 마리를 끌어다가 나라와 성소와 유다를 위하여 속죄제물로 삼고 아론의 자손 제사장들을 명령하여 여호와의 제단에 드리게 하니'),
    (11823, '○왕이 레위 사람들을 여호와의 전에 두어서 다윗과 왕의 선견자 갓과 선지자 나단이 명령한 대로 제금과 비파와 수금을 잡게 하니 이는 여호와께서 그의 선지자들로 이렇게 명령하셨음이라'),
    (11827, '○제사 드리기를 마치매 왕과 그와 함께 있는 자들이 다 엎드려 경배하니라'),
    (11829, '○이에 히스기야가 말하여 이르되 너희가 이제 스스로 몸을 깨끗하게 하여 여호와께 드렸으니 마땅히 나아와 제물과 감사제물을 여호와의 전으로 가져오라 하니 회중이 제물과 감사제물을 가져오되 무릇 마음에 원하는 자는 또한 번제물도 가져오니'),
    (11832, '그런데 제사장이 부족하여 그 모든 번제 짐승들의 가죽을 능히 벗기지 못하는 고로 그의 형제 레위 사람들이 그 일을 마치기까지 돕고 다른 제사장들이 성결하게 하기까지 기다렸으니 이는 레위 사람들의 성결하게 함이 제사장들보다 성심이 있었음이라'),
    (11835, '<유월절 준비> 히스기야가 온 이스라엘과 유다에 사람을 보내고 또 에브라임과 므낫세에 편지를 보내어 예루살렘 여호와의 전에 와서 이스라엘 하나님 여호와를 위하여 유월절을 지키라 하니라'),
    (11837, '이는 성결하게 한 제사장들이 부족하고 백성도 예루살렘에 모이지 못하였으므로 그 정한 때에 지킬 수 없었음이라'),
    (11839, '드디어 왕이 명령을 내려 브엘세바에서부터 단까지 온 이스라엘에 공포하여 일제히 예루살렘으로 와서 이스라엘 하나님 여호와의 유월절을 지키라 하니 이는 기록한 규례대로 오랫동안 지키지 못하였음이더라'),
    (11840, '보발꾼들이 왕과 방백들의 편지를 받아 가지고 왕의 명령을 따라 온 이스라엘과 유다에 두루 다니며 전하니 일렀으되 이스라엘 자손들아 너희는 아브라함과 이삭과 이스라엘의 하나님 여호와께로 돌아오라 그리하면 그가 너희 남은 자 곧 앗수르 왕의 손에서 벗어난 자에게로 돌아오시리라'),
    (11843, '너희가 만일 여호와께 돌아오면 너희 형제들과 너희 자녀가 사로잡은 자들에게서 자비를 입어 다시 이 땅으로 돌아오리라 너희 하나님 여호와는 은혜로우시고 자비하신지라 너희가 그에게로 돌아오면 그의 얼굴을 너희에게서 돌이키지 아니하시리라 하였더라'),
    (11844, '○보발꾼이 에브라임과 므낫세 지방 각 성읍으로 두루 다녀서 스불론까지 이르렀으나 사람들이 그들을 조롱하며 비웃었더라'),
    (11847, '<유월절을 성대히 지키다> ○둘째 달에 백성이 무교절을 지키려 하여 예루살렘에 많이 모이니 매우 큰 모임이라'),
    (11852, '에브라임과 므낫세와 잇사갈과 스불론의 많은 무리는 자기들을 깨끗하게 하지 아니하고 유월절 양을 먹어 기록한 규례를 어긴지라 히스기야가 그들을 위하여 기도하여 이르되 선하신 여호와여 사하옵소서'),
    (11857, '<두 번째 절기> ○온 회중이 다시 칠 일을 지키기로 결의하고 이에 또 칠 일을 즐겁게 지켰더라'),
    (11883, '<앗수르 군대가 예루살렘을 위협하다> 이 모든 충성된 일을 한 후에 앗수르 왕 산헤립이 유다에 들어와서 견고한 성읍들을 향하여 진을 치고 쳐서 점령하고자 한지라'),
    (11890, '그와 함께 하는 자는 육신의 팔이요 우리와 함께 하시는 이는 우리의 하나님 여호와시라 반드시 우리를 도우시고 우리를 대신하여 싸우시리라 하매 백성이 유다 왕 히스기야의 말로 말미암아 안심하니라'),
    (11891, '○그 후에 앗수르 왕 산헤립이 그의 온 군대를 거느리고 라기스를 치며 그의 신하들을 예루살렘에 보내어 유다 왕 히스기야와 예루살렘에 있는 유다 무리에게 말하여 이르기를'),
    (11897, '그런즉 이와 같이 너희는 히스기야에게 속지 말라 꾀임을 받지 말라 그를 믿지도 말라 어떤 백성이나 어떤 나라의 신도 능히 자기의 백성을 나의 손과 나의 조상들의 손에서 건져내지 못하였나니 하물며 너희 하나님이 너희를 내 손에서 건져내겠느냐 하였더라'),
    (11898, '○산헤립의 신하들도 더욱 여호와 하나님과 그의 종 히스기야를 비방하였으며'),
    (11899, '산헤립이 또 편지를 써 보내어 이스라엘 하나님 여호와를 욕하고 비방하여 이르기를 모든 나라의 신들이 그들의 백성을 내 손에서 구원하여 내지 못한 것 같이 히스기야의 신들도 그의 백성을 내 손에서 구원하여 내지 못하리라 하고'),
    (11902, '○이러므로 히스기야 왕이 아모스의 아들 선지자 이사야와 더불어 하늘을 향하여 부르짖어 기도하였더니'),
    (11903, '여호와께서 한 천사를 보내어 앗수르 왕의 진영에서 모든 큰 용사와 대장과 지휘관들을 멸하신지라 앗수르 왕이 낯이 뜨거워 그의 고국으로 돌아갔더니 그의 신의 전에 들어갔을 때에 그의 몸에서 난 자들이 거기서 칼로 죽였더라'),
    (11906, '<히스기야의 병과 교만> ○그 때에 히스기야가 병들어 죽게 되었으므로 여호와께 기도하매 여호와께서 그에게 대답하시고 또 이적을 보이셨으나'),
    (11909, '<히스기야의 부와 영광> ○히스기야가 부와 영광이 지극한지라 이에 은금과 보석과 향품과 방패와 온갖 보배로운 그릇들을 위하여 창고를 세우며'),
    (11914, '<히스기야가 죽다> ○히스기야의 남은 행적과 그의 모든 선한 일은 아모스의 아들 선지자 이사야의 묵시 책과 유다와 이스라엘 열왕기에 기록되니라'),
    (11915, '히스기야가 그의 조상들과 함께 누우매 온 유다와 예루살렘 주민이 그를 다윗 자손의 묘실 중 높은 곳에 장사하여 그의 죽음에 그에게 경의를 표하였더라 그의 아들 므낫세가 대신하여 왕이 되니라'),
    (11916, '<유다 왕 므낫세> 므낫세가 왕위에 오를 때에 나이가 십이 세라 예루살렘에서 오십오 년 동안 다스리며'),
    (11921, '또 힌놈의 아들 골짜기에서 그의 아들들을 불 가운데로 지나가게 하며 또 점치며 사술과 요술을 행하며 신접한 자와 박수를 신임하여 여호와 보시기에 악을 많이 행하여 여호와를 진노하게 하였으며'),
    (11922, '또 자기가 만든 아로새긴 목상을 하나님의 전에 세웠더라 옛적에 하나님이 이 성전에 대하여 다윗과 그의 아들 솔로몬에게 이르시기를 내가 이스라엘 모든 지파 중에서 택한 이 성전과 예루살렘에 내 이름을 영원히 둘지라'),
    (11923, '만일 이스라엘 사람이 내가 명령한 일들 곧 모세를 통하여 전한 모든 율법과 율례와 규례를 지켜 행하면 내가 그들의 발로 다시는 그의 조상들에게 정하여 준 땅에서 옮기지 않게 하리라 하셨으나'),
    (11925, '<므낫세가 기도하다> ○여호와께서 므낫세와 그의 백성에게 이르셨으나 그들이 듣지 아니하므로'),
    (11929, '<므낫세가 죽다> ○그 후에 다윗 성 밖 기혼 서쪽 골짜기 안에 외성을 쌓되 어문 어귀까지 이르러 오벨을 둘러 매우 높이 쌓고 또 유다 모든 견고한 성읍에 군대 지휘관을 두며'),
    (11936, '<유다 왕 아몬> ○아몬이 왕위에 오를 때에 나이가 이십이 세라 예루살렘에서 이 년 동안 다스리며'),
    (12024, '<여호와께서 고레스의 마음을 감동시키다> 바사 왕 고레스 원년에 여호와께서 예레미야의 입을 통하여 하신 말씀을 이루게 하시려고 바사 왕 고레스의 마음을 감동시키시매 그가 온 나라에 공포도 하고 조서도 내려 이르되'),
    (12027, '그 남아 있는 백성이 어느 곳에 머물러 살든지 그 곳 사람들이 마땅히 은과 금과 그 밖의 물건과 짐승으로 도와 주고 그 외에도 예루살렘에 세울 하나님의 성전을 위하여 예물을 기쁘게 드릴지니라 하였더라'),
    (12028, '<사로잡혀 간 백성이 돌아오다> ○이에 유다와 베냐민 족장들과 제사장들과 레위 사람들과 그 마음이 하나님께 감동을 받고 올라가서 예루살렘에 여호와의 성전을 건축하고자 하는 자가 다 일어나니'),
    (11974, '<요시야가 유월절을 지키다> 요시야가 예루살렘에서 여호와께 유월절을 지켜 첫째 달 열넷째 날에 유월절 어린 양을 잡으니라'),
    (11976, '또 여호와 앞에 구별되어서 온 이스라엘을 가르치는 레위 사람에게 이르되 거룩한 궤를 이스라엘 왕 다윗의 아들 솔로몬이 건축한 전 가운데 두고 다시는 너희 어깨에 메지 말고 마땅히 너희의 하나님 여호와와 그의 백성 이스라엘을 섬길 것이라'),
    (11980, '○요시야가 그 모인 모든 이를 위하여 백성들에게 자기의 소유 양 떼 중에서 어린 양과 어린 염소 삼만 마리와 수소 삼천 마리를 내어 유월절 제물로 주매'),
    (11981, '방백들도 즐거이 희생을 드려 백성과 제사장들과 레위 사람들에게 주었고 하나님의 전을 주장하는 자 힐기야와 스가랴와 여히엘은 제사장들에게 양 이천육백 마리와 수소 삼백 마리를 유월절 제물로 주었고'),
    (11983, '○이와 같이 섬길 일이 구비되매 왕의 명령을 따라 제사장들은 그들의 처소에 서고 레위 사람들은 그들의 반열대로 서고'),
    (11988, '아삽의 자손 노래하는 자들은 다윗과 아삽과 헤만과 왕의 선견자 여두둔이 명령한 대로 자기 처소에 있고 문지기들은 각 문에 있고 그 직무에서 떠날 것이 없었으니 이는 그의 형제 레위 사람들이 그들을 위하여 준비하였음이더라'),
    (11989, '○이와 같이 당일에 여호와를 섬길 일이 다 준비되매 요시야 왕의 명령대로 유월절을 지키며 번제를 여호와의 제단에 드렸으며'),
    (11991, '선지자 사무엘 이후로 이스라엘 가운데서 유월절을 이같이 지키지 못하였고 이스라엘 모든 왕들도 요시야가 제사장들과 레위 사람들과 모인 온 유다와 이스라엘 무리와 예루살렘 주민과 함께 지킨 것처럼은 유월절을 지키지 못하였더라'),
    (11993, '<요시야가 죽다> ○이 모든 일 후 곧 요시야가 성전을 정돈하기를 마친 후에 애굽 왕 느고가 유브라데 강 가의 갈그미스를 치러 올라왔으므로 요시야가 나가서 방비하였더니'),
    (11994, '느고가 요시야에게 사신을 보내어 이르되 유다 왕이여 내가 그대와 무슨 관계가 있느냐 내가 오늘 그대를 치려는 것이 아니요 나와 더불어 싸우는 족속을 치려는 것이라 하나님이 나에게 명령하사 속히 하라 하셨은즉 하나님이 나와 함께 계시니 그대는 하나님을 거스르지 말라 그대를 멸하실까 하노라 하나'),
    (11941, '<유다 왕 요시야의 개혁> 요시야가 왕위에 오를 때에 나이가 팔 세라 예루살렘에서 삼십일 년 동안 다스리며'),
    (11943, '아직도 어렸을 때 곧 왕위에 있은 지 팔 년에 그의 조상 다윗의 하나님을 비로소 찾고 제십이년에 유다와 예루살렘을 비로소 정결하게 하여 그 산당들과 아세라 목상들과 아로새긴 우상들과 부어 만든 우상들을 제거하여 버리매'),
    (11944, '무리가 왕 앞에서 바알의 제단들을 헐었으며 왕이 또 그 제단 위에 높이 달린 태양상들을 찍고 또 아세라 목상들과 아로새긴 우상들과 부어 만든 우상들을 빻아 가루를 만들어 제사하던 자들의 무덤에 뿌리고'),
    (11948, '<율법책의 발견> ○요시야가 왕위에 있은 지 열여덟째 해에 그 땅과 성전을 정결하게 하기를 마치고 그의 하나님 여호와의 전을 수리하려 하여 아살랴의 아들 사반과 시장 마아세야와 서기관 요아하스의 아들 요아를 보낸지라'),
    (11949, '그들이 대제사장 힐기야에게 나아가 전에 하나님의 전에 헌금한 돈을 그에게 주니 이 돈은 문을 지키는 레위 사람들이 므낫세와 에브라임과 남아 있는 모든 이스라엘 사람과 온 유다와 베냐민과 예루살렘 주민들에게서 거둔 것이라'),
    (11952, '그 사람들이 성실하게 그 일을 하니라 그의 감독들은 레위 사람들 곧 므라리 자손 중 야핫과 오바댜요 그핫 자손들 중 스가랴와 무술람이라 다 그 일을 감독하고 또 악기에 익숙한 레위 사람들이 함께 하였으며'),
    (11954, '○무리가 여호와의 전에 헌금한 돈을 꺼낼 때에 제사장 힐기야가 모세가 전한 여호와의 율법책을 발견하고'),
    (11961, '너희는 가서 나와 및 이스라엘과 유다의 남은 자들을 위하여 이 발견한 책의 말씀에 대하여 여호와께 물으라 우리 조상들이 여호와의 말씀을 지키지 아니하고 이 책에 기록된 모든 것을 준행하지 아니하였으므로 여호와께서 우리에게 쏟으신 진노가 크도다 하니라'),
    (11962, '○이에 힐기야와 왕이 보낸 사람들이 여선지자 훌다에게로 나아가니 그는 하스라의 손자 독핫의 아들로서 예복을 관리하는 살룸의 아내라 예루살렘 둘째 구역에 살았더라 그들이 그에게 이 뜻을 전하매'),
    (11968, '그러므로 내가 네게 너의 조상들에게 돌아가서 평안히 묘실로 들어가게 하리니 내가 이 곳과 그 주민에게 내리는 모든 재앙을 네가 눈으로 보지 못하리라 하셨느니라 이에 사신들이 왕에게 복명하니라'),
    (11969, '<여호와께 순종하기로 하다> ○왕이 사람을 보내어 유다와 예루살렘의 모든 장로를 불러 모으고'),
    (11970, '여호와의 전에 올라가매 유다 모든 사람과 예루살렘 주민들과 제사장들과 레위 사람들과 모든 백성이 노소를 막론하고 다 함께 한지라 왕이 여호와의 전 안에서 발견한 언약책의 모든 말씀을 읽어 무리의 귀에 들려 주고'),
    (11973, '이와 같이 요시야가 이스라엘 자손에게 속한 모든 땅에서 가증한 것들을 다 제거하여 버리고 이스라엘의 모든 사람으로 그들의 하나님 여호와를 섬기게 하였으므로 요시야가 사는 날에 백성이 그들의 조상들의 하나님 여호와께 복종하고 떠나지 아니하였더라'),
    (12001, '<유다 왕 여호아하스> 그 땅의 백성이 요시야의 아들 여호아하스를 세워 그의 아버지를 대신하여 예루살렘에서 왕으로 삼으니'),
    (12005, '<유다 왕 여호야김> ○여호야김이 왕위에 오를 때에 나이가 이십오 세라 예루살렘에서 십일 년 동안 다스리며 그의 하나님 여호와 보시기에 악을 행하였더라'),
    (12009, '<유다 왕 여호야긴> ○여호야긴이 왕위에 오를 때에 나이가 팔 세라 예루살렘에서 석달 열흘 동안 다스리며 여호와 보시기에 악을 행하였더라'),
    (12011, '<유다 왕 시드기야> ○시드기야가 왕위에 오를 때에 나이가 이십일 세라 예루살렘에서 십일 년 동안 다스리며'),
    (12022, '<고레스의 귀국 명령> ○바사의 고레스 왕 원년에 여호와께서 예레미야의 입으로 하신 말씀을 이루시려고 여호와께서 바사의 고레스 왕의 마음을 감동시키시매 그가 온 나라에 공포도 하고 조서도 내려 이르되'),
    (12023, '바사 왕 고레스가 이같이 말하노니 하늘의 신 여호와께서 세상 만국을 내게 주셨고 나에게 명령하여 유다 예루살렘에 성전을 건축하라 하셨나니 너희 중에 그의 백성된 자는 다 올라갈지어다 너희 하나님 여호와께서 함께 하시기를 원하노라 하였더라'),
    (12035, '<돌아온 사람들> 옛적에 바벨론 왕 느부갓네살에게 사로잡혀 바벨론으로 갔던 자들의 자손들 중에서 놓임을 받고 예루살렘과 유다 도로 돌아와 각기 각자의 성읍으로 돌아간 자'),
    (12058, '아스마웻 자손이 사십이 명이요'),
    (12070, '○제사장들은 예수아의 집 여다야 자손이 구백칠십삼 명이요'),
    (12074, '○레위 사람은 호다위야 자손 곧 예수아와 갓미엘 자손이 칠십사 명이요'),
    (12077, '○느디님 사람들은 시하 자손과 하수바 자손과 답바옷 자손과'),
    (12089, '○솔로몬의 신하의 자손은 소대 자손과 하소베렛 자손과 브루다 자손과'),
    (12093, '○델멜라와 델하르사와 그룹과 앗단과 임멜에서 올라온 자가 있으나 그들의 조상의 가문과 선조가 이스라엘에 속하였는지 밝힐 수 없었더라'),
    (12098, '○온 회중의 합계가 사만 이천삼백육십 명이요'),
    (12102, '○어떤 족장들이 예루살렘에 있는 여호와의 성전 터에 이르러 하나님의 전을 그 곳에 다시 건축하려고 예물을 기쁘게 드리되'),
    (12104, '○이에 제사장들과 레위 사람들과 백성 몇과 노래하는 자들과 문지기들과 느디님 사람들이 각자의 성읍에 살았고 이스라엘 무리도 각자의 성읍에 살았더라'),
    (12119, '스룹바벨과 족장들에게 나아와 이르되 우리도 너희와 함께 건축하게 하라 우리도 너희 같이 너희 하나님을 찾노라 앗수르 왕 에살핫돈이 우리를 이리로 오게 한 날부터 우리가 하나님께 제사를 드리노라 하니'),
    (12120, '스룹바벨과 예수아와 기타 이스라엘 족장들이 이르되 우리 하나님의 성전을 건축하는 데 너희는 우리와 상관이 없느니라 바사 왕 고레스가 우리에게 명령하신 대로 우리가 이스라엘의 하나님 여호와를 위하여 홀로 건축하리라 하였더니'),
    (12124, '○아닥사스다 때에 비슬람과 미드르닷과 다브엘과 그의 동료들이 바사 왕 아닥사스다에게 글을 올렸으니 그 글은 아람 문자와 아람 방언으로 써서 진술하였더라'),
    (12128, '○아닥사스다 왕에게 올린 그 글의 초본은 이러하니 강 건너편에 있는 신하들은'),
    (12132, '왕은 조상들의 사기를 살펴보시면 그 사기에서 이 성읍은 패역한 성읍이라 예로부터 그 중에서 항상 반역하는 일을 행하여 왕들과 각 도에 손해가 된 것을 보시고 아실지라 이 성읍이 무너짐도 이 때문이니이다'),
    (12134, '○왕이 방백 르훔과 서기관 심새와 사마리아에 거주하는 그들 동관들과 강 건너편 다른 땅 백성에게 조서를 내리니 일렀으되 너희는 평안할지어다'),
    (12140, '○아닥사스다 왕의 조서 초본이 르훔과 서기관 심새와 그의 동료 앞에서 낭독되매 그들이 예루살렘으로 급히 가서 유다 사람들을 보고 권력으로 억제하여 그 공사를 그치게 하니'),
    (12106, '요사닥의 아들 예수아와 그의 형제 제사장들과 스알디엘의 아들 스룹바벨과 그의 형제들이 다 일어나 이스라엘 하나님의 제단을 만들고 하나님의 사람 모세의 율법에 기록한 대로 번제를 그 위에서 드리려 할새'),
    (12112, '<성전 건축을 시작하다> ○예루살렘에 있는 하나님의 성전에 이른 지 이 년 둘째 달에 스알디엘의 아들 스룹바벨과 요사닥의 아들 예수아와 다른 형제 제사장들과 레위 사람들과 무릇 사로잡혔다가 예루살렘에 돌아온 자들이 공사를 시작하고 이십 세 이상의 레위 사람들을 세워 여호와의 성전 공사를 감독하게 하매'),
    (12115, '찬양으로 화답하며 여호와께 감사하여 이르되 주는 지극히 선하시므로 그의 인자하심이 이스라엘에게 영원하시도다 하니 모든 백성이 여호와의 성전 기초가 놓임을 보고 여호와를 찬송하며 큰 소리로 즐거이 부르며'),
    (12245, '<에스라의 회개 기도> 이 일 후에 방백들이 내게 나아와 이르되 이스라엘 백성과 제사장들과 레위 사람들이 이 땅 백성들에게서 떠나지 아니하고 가나안 사람들과 헷 사람들과 브리스 사람들과 여부스 사람들과 암몬 사람들과 모압 사람들과 애굽 사람들과 아모리 사람들의 가증한 일을 행하여'),
    (12251, '우리 조상들의 때로부터 오늘까지 우리의 죄가 심하매 우리의 죄악으로 말미암아 우리와 우리 왕들과 우리 제사장들을 여러 나라 왕들의 손에 넘기사 칼에 죽으며 사로잡히며 노략을 당하며 얼굴을 부끄럽게 하심이 오늘날과 같으니이다'),
    (12252, '이제 우리 하나님 여호와께서 우리에게 잠시 동안 은혜를 베푸사 얼마를 남겨 두어 피하게 하신 우리를 그 거룩한 처소에 박힌 못과 같게 하시고 우리 하나님이 우리 눈을 밝히사 우리가 종노릇 하는 중에서 조금 소생하게 하셨나이다'),
    (12253, '우리가 비록 노예가 되었사오나 우리 하나님이 우리를 그 종살이하는 중에 버려 두지 아니하시고 바사 왕들 앞에서 우리가 불쌍히 여김을 입고 소생하여 우리 하나님의 성전을 세우게 하시며 그 무너진 것을 수리하게 하시며 유다와 예루살렘에서 우리에게 울타리를 주셨나이다'),
    (12255, '전에 주께서 주의 종 선지자들에게 명령하여 이르시되 너희가 가서 얻으려 하는 땅은 더러운 땅이니 이는 이방 백성들이 더럽고 가증한 일을 행하여 이 끝에서 저 끝까지 그 더러움으로 채웠음이라'),
    (12256, '그런즉 너희 여자들을 그들의 아들들에게 주지 말고 그들의 딸들을 너희 아들들을 위하여 데려오지 말며 그들을 위하여 평화와 행복을 영원히 구하지 말라 그리하면 너희가 왕성하여 그 땅의 아름다운 것을 먹으며 그 땅을 자손에게 물려 주어 영원한 유산으로 물려 주게 되리라 하셨나이다'),
    (12147, '○유브라데 강 건너편 총독 닷드내와 스달보스내와 그들의 동관인 유브라데 강 건너편 아바삭 사람이 다리오 왕에게 올린 글의 초본은 이러하니라'),
    (12158, '이제 왕께서 좋게 여기시거든 바벨론에서 왕의 보물전각에서 조사하사 과연 고레스 왕이 조서를 내려 하나님의 이 성전을 예루살렘에 다시 건축하라 하셨는지 보시고 왕은 이 일에 대하여 왕의 기쁘신 뜻을 우리에게 보이소서 하였더라'),
    (12161, '고레스 왕 원년에 조서를 내려 이르기를 예루살렘에 있는 하나님의 성전에 대하여 이르노니 이 성전 곧 제사 드리는 처소를 건축하되 지대를 견고히 쌓고 그 성전의 높이는 육십 규빗으로, 너비도 육십 규빗으로 하고'),
    (12166, '내가 또 조서를 내려서 하나님의 이 성전을 건축함에 대하여 너희가 유다 사람의 장로들에게 행할 것을 알리노니 왕의 재산 곧 유브라데 강 건너편에서 거둔 세금 중에서 그 경비를 이 사람들에게 끊임없이 주어 그들로 멈추지 않게 하라'),
    (12170, '만일 왕들이나 백성이 이 명령을 변조하고 손을 들어 예루살렘 하나님의 성전을 헐진대 그 곳에 이름을 두신 하나님이 그들을 멸하시기를 원하노라 나 다리오가 조서를 내렸노니 신속히 행할지어다 하였더라'),
    (12171, '<성전 봉헌> ○다리오 왕의 조서가 내리매 유브라데 강 건너편 총독 닷드내와 스달보스내와 그들의 동관들이 신속히 준행하니라'),
    (12172, '유다 사람의 장로들이 선지자 학개와 잇도의 손자 스가랴의 권면을 따랐으므로 성전 건축하는 일이 형통한지라 이스라엘 하나님의 명령과 바사 왕 고레스와 다리오와 아닥사스다의 조서를 따라 성전을 건축하며 일을 끝내되'),
    (12174, '○이스라엘 자손과 제사장들과 레위 사람들과 기타 사로잡혔던 자의 자손이 즐거이 하나님의 성전 봉헌식을 행하니'),
    (12177, '<유월절> ○사로잡혔던 자의 자손이 첫째 달 십사일에 유월절을 지키되'),
    (12180, '즐거움으로 이레 동안 무교절을 지켰으니 이는 여호와께서 그들을 즐겁게 하시고 또 앗수르 왕의 마음을 그들에게로 돌려 이스라엘의 하나님이신 하나님의 성전 건축하는 손을 힘 있게 하도록 하셨음이었더라'),
    (12304, '<느헤미야가 예루살렘을 두고 기도하다> 하가랴의 아들 느헤미야의 말이라 ○아닥사스다 왕 제이십년 기슬르월에 내가 수산 궁에 있는데'),
    (12310, '이제 종이 주의 종들인 이스라엘 자손을 위하여 주야로 기도하오며 우리 이스라엘 자손이 주께 범죄한 죄들을 자복하오니 주는 귀를 기울이시며 눈을 여시사 종의 기도를 들으시옵소서 나와 내 아버지의 집이 범죄하여'),
    (12313, '만일 내게로 돌아와 내 계명을 지켜 행하면 너희 쫓긴 자가 하늘 끝에 있을지라도 내가 거기서부터 그들을 모아 내 이름을 두려고 택한 곳에 돌아오게 하리라 하신 말씀을 이제 청하건대 기억하옵소서'),
    (12315, '주여 구하오니 귀를 기울이사 종의 기도와 주의 이름을 경외하기를 기뻐하는 종들의 기도를 들으시고 오늘 종이 형통하여 이 사람 앞에서 은혜를 입게 하옵소서 하였나니 그 때에 내가 왕의 술 관원이 되었느니라'),
    (12223, '<에스라가 레위 사람을 찾다> ○내가 무리를 아하와로 흐르는 강 가에 모으고 거기서 삼 일 동안 장막에 머물며 백성과 제사장들을 살핀즉 그 중에 레위 자손이 한 사람도 없는지라'),
    (12225, '가시뱌 지방으로 보내어 그 곳 족장 잇도에게 나아가게 하고 잇도와 그의 형제 곧 가시뱌 지방에 사는 느디님 사람들에게 할 말을 일러 주고 우리 하나님의 성전을 위하여 섬길 자를 데리고 오라 하였더니'),
    (12229, '<에스라가 금식하며 간구하다> ○그 때에 내가 아하와 강 가에서 금식을 선포하고 우리 하나님 앞에서 스스로 겸비하여 우리와 우리 어린 아이와 모든 소유를 위하여 평탄한 길을 그에게 간구하였으니'),
    (12230, '이는 우리가 전에 왕에게 아뢰기를 우리 하나님의 손은 자기를 찾는 모든 자에게 선을 베푸시고 자기를 배반하는 모든 자에게는 권능과 진노를 내리신다 하였으므로 길에서 적군을 막고 우리를 도울 보병과 마병을 왕에게 구하기를 부끄러워 하였음이라'),
    (12232, '<성전에 바친 예물> ○그 때에 내가 제사장의 우두머리들 중 열두 명 곧 세레뱌와 하사뱌와 그의 형제 열 명을 따로 세우고'),
    (12239, '<에스라가 예루살렘으로 돌아오다> ○첫째 달 십이 일에 우리가 아하와 강을 떠나 예루살렘으로 갈새 우리 하나님의 손이 우리를 도우사 대적과 길에 매복한 자의 손에서 건지신지라'),
    (12241, '제사일에 우리 하나님의 성전에서 은과 금과 그릇을 달아서 제사장 우리아의 아들 므레못의 손에 넘기니 비느하스의 아들 엘르아살과 레위 사람 예수아의 아들 요사밧과 빈누이의 아들 노아댜가 함께 있어'),
    (12243, '○사로잡혔던 자의 자손 곧 이방에서 돌아온 자들이 이스라엘의 하나님께 번제를 드렸는데 이스라엘 전체를 위한 수송아지가 열두 마리요 또 숫양이 아흔여섯 마리요 어린 양이 일흔일곱 마리요 또 속죄제의 숫염소가 열두 마리니 모두 여호와께 드린 번제물이라'),
    (12369, '자기 형제들과 사마리아 군대 앞에서 일러 말하되 이 미약한 유다 사람들이 하는 일이 무엇인가, 스스로 견고하게 하려는가, 제사를 드리려는가, 하루에 일을 마치려는가 불탄 돌을 흙 무더기에서 다시 일으키려는가 하고'),
    (12374, '○산발랏과 도비야와 아라비아 사람들과 암몬 사람들과 아스돗 사람들이 예루살렘 성이 중수되어 그 허물어진 틈이 메꾸어져 간다 함을 듣고 심히 분노하여'),
    (12381, '내가 돌아본 후에 일어나서 귀족들과 민장들과 남은 백성에게 말하기를 너희는 그들을 두려워하지 말고 지극히 크시고 두려우신 주를 기억하고 너희 형제와 자녀와 아내와 집을 위하여 싸우라 하였느니라'),
    (12382, '○우리의 대적이 우리가 그들의 의도를 눈치챘다 함을 들으니라 하나님이 그들의 꾀를 폐하셨으므로 우리가 다 성에 돌아와서 각각 일하였는데'),
    (12388, '○우리가 이같이 공사하는데 무리의 절반은 동틀 때부터 별이 나기까지 창을 잡았으며'),
    (12322, '내가 또 왕에게 아뢰되 왕이 만일 좋게 여기시거든 강 서쪽 총독들에게 내리시는 조서를 내게 주사 그들이 나를 용납하여 유다에 들어가기까지 통과하게 하시고'),
    (12323, '또 왕의 삼림 감독 아삽에게 조서를 내리사 그가 성전에 속한 영문의 문과 성곽과 내가 들어갈 집을 위하여 들보로 쓸 재목을 내게 주게 하옵소서 하매 내 하나님의 선한 손이 나를 도우시므로 왕이 허락하고'),
    (12334, '호론 사람 산발랏과 종이었던 암몬 사람 도비야와 아라비아 사람 게셈이 이 말을 듣고 우리를 업신여기고 우리를 비웃어 이르되 너희가 하는 일이 무엇이냐 너희가 왕을 배반하고자 하느냐 하기로'),
    (12335, '내가 그들에게 대답하여 이르되 하늘의 하나님이 우리를 형통하게 하시리니 그의 종들인 우리가 일어나 건축하려니와 오직 너희에게는 예루살렘에서 아무 기업도 없고 권리도 없고 기억되는 바도 없다 하였느니라'),
    (12336, '<예루살렘 성벽 중수> 그 때에 대제사장 엘리아십이 그의 형제 제사장들과 함께 일어나 양문을 건축하여 성별하고 문짝을 달고 또 성벽을 건축하여 함메아 망대에서부터 하나넬 망대까지 성별하였고'),
    (12350, '샘문은 미스바 지방을 다스리는 골호세의 아들 살룬이 중수하여 문을 세우고 덮었으며 문짝을 달고 자물쇠와 빗장을 갖추고 또 왕의 동산 근처 셀라 못 가의 성벽을 중수하여 다윗 성에서 내려오는 층계까지 이르렀고'),
    (12363, '○마문 위로부터는 제사장들이 각각 자기 집과 마주 대한 부분을 중수하였고'),
    (12395, '우리 육체도 우리 형제의 육체와 같고 우리 자녀도 그들의 자녀와 같거늘 이제 우리 자녀를 종으로 파는도다 우리 딸 중에 벌써 종된 자가 있고 우리의 밭과 포도원이 이미 남의 것이 되었으나 우리에게는 아무런 힘이 없도다 하더라'),
    (12396, '○내가 백성의 부르짖음과 이런 말을 듣고 크게 노하였으나'),
    (12398, '그들에게 이르기를 우리는 이방인의 손에 팔린 우리 형제 유다 사람들을 우리의 힘을 다하여 도로 찾았거늘 너희는 너희 형제를 팔고자 하느냐 더구나 우리의 손에 팔리게 하겠느냐 하매 그들이 잠잠하여 말이 없기로'),
    (12403, '내가 옷자락을 털며 이르기를 이 말대로 행하지 아니하는 자는 모두 하나님이 또한 이와 같이 그 집과 산업에서 털어 버리실지니 그는 곧 이렇게 털려서 빈손이 될지로다 하매 회중이 다 아멘 하고 여호와를 찬송하고 백성들이 그 말한 대로 행하였느니라'),
    (12404, '<느헤미야가 총독의 녹을 받지 아니하다> ○또한 유다 땅 총독으로 세움을 받은 때 곧 아닥사스다 왕 제이십년부터 제삼십이년까지 십이 년 동안은 나와 내 형제들이 총독의 녹을 먹지 아니하였느니라'),
    (12405, '나보다 먼저 있었던 총독들은 백성에게서, 양식과 포도주와 또 은 사십 세겔을 그들에게서 빼앗았고 또한 그들의 종자들도 백성을 압제하였으나 나는 하나님을 경외하므로 이같이 행하지 아니하고'),
    (12408, '매일 나를 위하여 소 한 마리와 살진 양 여섯 마리를 준비하며 닭도 많이 준비하고 열흘에 한 번씩은 각종 포도주를 갖추었나니 비록 이같이 하였을지라도 내가 총독의 녹을 요구하지 아니하였음은 이 백성의 부역이 중함이었더라'),
    (12410, '<느헤미야에 대한 음모> 산발랏과 도비야와 아라비아 사람 게셈과 그 나머지 우리의 원수들이 내가 성벽을 건축하여 허물어진 틈을 남기지 아니하였다 함을 들었는데 그 때는 내가 아직 성문에 문짝을 달지 못한 때였더라'),
    (12419, '○이 후에 므헤다벨의 손자 들라야의 아들 스마야가 두문불출 하기로 내가 그 집에 가니 그가 이르기를 그들이 너를 죽이러 올 터이니 우리가 하나님의 전으로 가서 외소 안에 머물고 그 문을 닫자 저들이 반드시 밤에 와서 너를 죽이리라 하기로'),
    (12424, '<성벽 공사가 끝나다> ○성벽 역사가 오십이 일 만인 엘룰월 이십오일에 끝나매'),
    (12260, '<이방 아내와 그 소생을 내쫓기로 하다> 에스라가 하나님의 성전 앞에 엎드려 울며 기도하여 죄를 자복할 때에 많은 백성이 크게 통곡하매 이스라엘 중에서 백성의 남녀와 어린 아이의 큰 무리가 그 앞에 모인지라'),
    (12264, '○이에 에스라가 일어나 제사장들과 레위 사람들과 온 이스라엘에게 이 말대로 행하기를 맹세하게 하매 무리가 맹세하는지라'),
    (12273, '이제 온 회중을 위하여 우리의 방백들을 세우고 우리 모든 성읍에 이방 여자에게 장가든 자는 다 기한에 각 고을의 장로들과 재판장과 함께 오게 하여 이 일로 인한 우리 하나님의 진노가 우리에게서 떠나게 하소서 하나'),
    (12275, '○사로잡혔던 자들의 자손이 그대로 한지라 제사장 에스라가 그 종족을 따라 각각 지명된 족장들 몇 사람을 선임하고 열째 달 초하루에 앉아 그 일을 조사하여'),
    (12277, '<이방 여자와 결혼한 남자들> ○제사장의 무리 중에 이방 여인을 아내로 맞이한 자는 예수아 자손 중 요사닥의 아들과 그의 형제 마아세야와 엘리에셀과 야립과 그달랴라'),
    (12282, '○레위 사람 중에서는 요사밧과 시므이와 글라야라 하는 글리다와 브다히야와 유다와 엘리에셀이었더라'),
    (12283, '○노래하는 자 중에서는 엘리아십이요 문지기 중에서는 살룸과 델렘과 우리였더라'),
    (12284, '○이스라엘 중에서는 바로스 자손 중에서는 라먀와 잇시야와 말기야와 미야민과 엘르아살과 말기야와 브나야요'),
    (12191, '<아닥사스다 왕이 내린 조서> ○여호와의 계명의 말씀과 이스라엘에게 주신 율례 학자요 학자 겸 제사장인 에스라에게 아닥사스다 왕이 내린 조서의 초본은 아래와 같으니라'),
    (12204, '내가 너희에게 이르노니 제사장들이나 레위 사람들이나 노래하는 자들이나 문지기들이나 느디님 사람들이나 혹 하나님의 성전에서 일하는 자들에게 조공과 관세와 통행세를 받는 것이 옳지 않으니라 하였노라'),
    (12207, '<에스라가 여호와를 송축하다> ○우리 조상들의 하나님 여호와를 송축할지로다 그가 왕의 마음에 예루살렘 여호와의 성전을 아름답게 할 뜻을 두시고'),
    (12208, '또 나로 왕과 그의 보좌관들 앞과 왕의 권세 있는 모든 방백의 앞에서 은혜를 얻게 하셨도다 내 하나님 여호와의 손이 내 위에 있으므로 내가 힘을 얻어 이스라엘 중에 우두머리들을 모아 나와 함께 올라오게 하였노라'),
    (12502, '이스라엘 자손이 자기들의 성읍에 거주하였더니 일곱째 달에 이르러 모든 백성이 일제히 수문 앞 광장에 모여 학사 에스라에게 여호와께서 이스라엘에게 명령하신 모세의 율법책을 가져오기를 청하매'),
    (12505, '그 때에 학사 에스라가 특별히 지은 나무 강단에 서고 그의 곁 오른쪽에 선 자는 맛디댜와 스마와 아나야와 우리야와 힐기야와 마아세야요 그의 왼쪽에 선 자는 브다야와 미사엘과 말기야와 하숨과 하스밧다나와 스가랴와 므술람이라'),
    (12508, '예수아와 바니와 세레뱌와 야민과 악굽과 사브대와 호디야와 마아세야와 그리다와 아사랴와 요사밧과 하난과 블라야와 레위 사람들은 백성이 제자리에 서 있는 동안 그들에게 율법을 깨닫게 하였는데'),
    (12510, '백성이 율법의 말씀을 듣고 다 우는지라 총독 느헤미야와 제사장 겸 학사 에스라와 백성을 가르치는 레위 사람들이 모든 백성에게 이르기를 오늘은 너희 하나님 여호와의 성일이니 슬퍼하지 말며 울지 말라 하고'),
    (12511, '느헤미야가 또 그들에게 이르기를 너희는 가서 살진 것을 먹고 단 것을 마시되 준비하지 못한 자에게는 나누어 주라 이 날은 우리 주의 성일이니 근심하지 말라 여호와로 인하여 기뻐하는 것이 너희의 힘이니라 하고'),
    (12514, '○그 이튿날 뭇 백성의 족장들과 제사장들과 레위 사람들이 율법의 말씀을 밝히 알고자 하여 학사 에스라에게 모여서'),
    (12516, '또 일렀으되 모든 성읍과 예루살렘에 공포하여 이르기를 너희는 산에 가서 감람나무 가지와 들감람나무 가지와 화석류나무 가지와 종려나무 가지와 기타 무성한 나무 가지를 가져다가 기록한 바를 따라 초막을 지으라 하라 한지라'),
    (12585, '○그 남은 백성과 제사장들과 레위 사람들과 문지기들과 노래하는 자들과 느디님 사람들과 및 이방 사람과 절교하고 하나님의 율법을 준행하는 모든 자와 그들의 아내와 그들의 자녀들 곧 지식과 총명이 있는 자들은'),
    (12588, '혹시 이 땅 백성이 안식일에 물품이나 온갖 곡물을 가져다가 팔려고 할지라도 우리가 안식일이나 성일에는 그들에게서 사지 않겠고 일곱째 해마다 땅을 쉬게 하고 모든 빚을 탕감하리라 하였고'),
    (12594, '또 처음 익은 밀의 가루와 거제물과 각종 과목의 열매와 새 포도주와 기름을 제사장들에게로 가져다가 우리 하나님의 전의 여러 방에 두고 또 우리 산물의 십일조를 레위 사람들에게 주리라 하였나니 이 레위 사람들은 우리의 모든 성읍에서 산물의 십일조를 받는 자임이며'),
    (12596, '곧 이스라엘 자손과 레위 자손이 거제로 드린 곡식과 새 포도주와 기름을 가져다가 성소의 그릇들을 두는 골방 곧 섬기는 제사장들과 문지기들과 노래하는 자들이 있는 골방에 둘 것이라 그리하여 우리가 우리 하나님의 전을 버려 두지 아니하리라'),
    (12524, '또 레위 사람 예수아와 갓미엘과 바니와 하삽느야와 세레뱌와 호디야와 스바냐와 브다히야는 이르기를 너희 무리는 마땅히 일어나 영원부터 영원까지 계신 너희 하나님 여호와를 송축할지어다 주여 주의 영화로운 이름을 송축하올 것은 주의 이름이 존귀하여 모든 송축이나 찬양에서 뛰어남이니이다'),
    (12527, '그의 마음이 주 앞에서 충성됨을 보시고 그와 더불어 언약을 세우사 가나안 족속과 헷 족속과 아모리 족속과 브리스 족속과 여부스 족속과 기르가스 족속의 땅을 그의 씨에게 주리라 하시더니 그 말씀대로 이루셨사오매 주는 의로우심이로소이다'),
    (12534, '그들의 굶주림 때문에 하늘에서 그들에게 양식을 주시며 그들의 목마름 때문에 그들에게 반석에서 물을 내시고 또 주께서 옛적에 손을 들어 맹세하시고 주겠다고 하신 땅을 들어가서 차지하라 말씀하셨사오나'),
    (12536, '거역하며 주께서 그들 가운데에서 행하신 기사를 기억하지 아니하고 목을 굳게 하며 패역하여 스스로 한 우두머리를 세우고 종 되었던 땅으로 돌아가고자 하였나이다 그러나 주께서는 용서하시는 하나님이시라 은혜로우시며 긍휼히 여기시며 더디 노하시며 인자가 풍부하시므로 그들을 버리지 아니하셨나이다'),
    (12546, '그러므로 주께서 그들을 대적의 손에 넘기사 그들이 곤고를 당하게 하시매 그들이 환난을 당하여 주께 부르짖을 때에 주께서 하늘에서 들으시고 주의 크신 긍휼로 그들에게 구원자들을 주어 그들을 대적의 손에서 구원하셨거늘'),
    (12547, '그들이 평강을 얻은 후에 다시 주 앞에서 악을 행하므로 주께서 그들을 원수들의 손에 버려 두사 원수들에게 지배를 당하게 하시다가 그들이 돌이켜 주께 부르짖으매 주께서 하늘에서 들으시고 여러 번 주의 긍휼로 건져내시고'),
    (12548, '다시 주의 율법을 복종하게 하시려고 그들에게 경계하셨으나 그들이 교만하여 사람이 준행하면 그 가운데에서 삶을 얻는 주의 계명을 듣지 아니하며 주의 규례를 범하여 고집하는 어깨를 내밀며 목을 굳게 하여 듣지 아니하였나이다'),
    (12551, '우리 하나님이여 광대하시고 능하시고 두려우시며 언약과 인자하심을 지키시는 하나님이여 우리와 우리 왕들과 방백들과 제사장들과 선지자들과 조상들과 주의 모든 백성이 앗수르 왕들의 때로부터 오늘까지 당한 모든 환난을 이제 작게 여기지 마옵소서'),
    (12431, '내가 그들에게 이르기를 해가 높이 뜨기 전에는 예루살렘 성문을 열지 말고 아직 파수할 때에 곧 문을 닫고 빗장을 지르며 또 예루살렘 주민이 각각 자기가 지키는 곳에서 파수하되 자기 집 맞은편을 지키게 하라 하였노니'),
    (12433, '<포로에서 돌아온 사람들> ○내 하나님이 내 마음을 감동하사 귀족들과 민장들과 백성을 모아 그 계보대로 등록하게 하시므로 내가 처음으로 돌아온 자의 계보를 얻었는데 거기에 기록된 것을 보면'),
    (12436, '바로스 자손이 이천백칠십이 명이요'),
    (12456, '벧아스마웻 사람이 사십이 명이요'),
    (12467, '○제사장들은 예수아의 집 여다야 자손이 구백칠십삼 명이요'),
    (12471, '○레위 사람들은 호드야 자손 곧 예수아와 갓미엘 자손이 칠십사 명이요'),
    (12474, '○느디님 사람들은 시하 자손과 하수바 자손과 답바옷 자손과'),
    (12485, '○솔로몬의 신하의 자손은 소대 자손과 소베렛 자손과 브리다 자손과'),
    (12489, '○델멜라와 델하르사와 그룹과 앗돈과 임멜로부터 올라온 자가 있으나 그들의 종족이나 계보가 이스라엘에 속하였는지는 증거할 수 없으니'),
    (12494, '○온 회중의 합계는 사만 이천삼백육십 명이요'),
    (12498, '○어떤 족장들은 역사를 위하여 보조하였고 총독은 금 천 드라크마와 대접 오십과 제사장의 의복 오백삼십 벌을 보물 곳간에 드렸고'),
    (12501, '<백성 앞에서 율법책을 읽다> ○이와 같이 제사장들과 레위 사람들과 문지기들과 노래하는 자들과 백성 몇 명과 느디님 사람들과 온 이스라엘 자손이 다 자기들의 성읍에 거주하였느니라'),
    (12719, '○왕후 와스디도 아하수에로 왕궁에서 여인들을 위하여 잔치를 베푸니라'),
    (12723, '○왕이 사례를 아는 현자들에게 묻되 (왕이 규례와 법률을 아는 자에게 묻는 전례가 있는데'),
    (12597, '<예루살렘에 거주하는 백성들> 백성의 지도자들은 예루살렘에 거주하였고 그 남은 백성은 제비 뽑아 십분의 일은 거룩한 성 예루살렘에서 거주하게 하고 그 십분의 구는 다른 성읍에 거주하게 하였으며'),
    (12599, '○이스라엘과 제사장들과 레위 사람들과 느디님 사람들과 솔로몬의 신하들의 자손은 유다 여러 성읍에서 각각 자기 성읍 자기 기업에 거주하였느니라 예루살렘에 거주한 그 지방의 지도자들은 이러하니'),
    (12600, '예루살렘에 거주한 자는 유다 자손과 베냐민 자손 몇 명이라 유다 자손 중에는 베레스 자손 아다야이니 그는 웃시야의 아들이요 스가랴의 손자요 아마랴의 증손이요 스바댜의 현손이요 마할랄렐의 오대 손이며'),
    (12603, '○베냐민 자손은 살루이니 그는 므술람의 아들이요 요엣의 손자요 브다야의 증손이요 골라야의 현손이요 마아세야의 오대 손이요 이디엘의 육대 손이요 여사야의 칠대 손이며'),
    (12606, '○제사장 중에는 요야립의 아들 여다야와 야긴이며'),
    (12608, '또 전에서 일하는 그들의 형제니 모두 팔백이십이 명이요 또 아다야이니 그는 여로함의 아들이요 블라야의 손자요 암시의 증손이요 스가랴의 현손이요 바스훌의 오대 손이요 말기야의 육대 손이며'),
    (12611, '○레위 사람 중에는 스마야이니 그는 핫숩의 아들이요 아스리감의 손자요 하사뱌의 증손이요 분니의 현손이며'),
    (12613, '또 아삽의 증손 삽디의 손자 미가의 아들 맛다냐이니 그는 기도할 때에 감사하는 말씀을 인도하는 자가 되었고 형제 중에 박부갸가 버금이 되었으며 또 여두둔의 증손 갈랄의 손자 삼무아의 아들 압다니'),
    (12615, '○성 문지기는 악굽과 달몬과 그 형제이니 모두 백칠십이 명이며'),
    (12618, '○노래하는 자들인 아삽 자손 중 미가의 현손 맛다냐의 증손 하사뱌의 손자 바니의 아들 웃시는 예루살렘에 거주하는 레위 사람의 감독이 되어 하나님의 전 일을 맡아 다스렸으니'),
    (12621, '<마을과 주변 동네들에 거주하는 백성들> ○마을과 들로 말하면 유다 자손의 일부는 기럇 아르바와 그 주변 동네들과 디본과 그 주변 동네들과 여갑스엘과 그 마을들에 거주하며'),
    (12762, '○아하수에로 왕 제십이년 첫째 달 곧 니산월에 무리가 하만 앞에서 날과 달에 대하여 부르 곧 제비를 뽑아 열두째 달 곧 아달월을 얻은지라'),
    (12767, '○첫째 달 십삼일에 왕의 서기관이 소집되어 하만의 명령을 따라 왕의 대신과 각 지방의 관리와 각 민족의 관원에게 아하수에로 왕의 이름으로 조서를 쓰되 곧 각 지방의 문자와 각 민족의 언어로 쓰고 왕의 반지로 인치니라'),
    (12768, '이에 그 조서를 역졸에게 맡겨 왕의 각 지방에 보내니 열두째 달 곧 아달월 십삼일 하루 동안에 모든 유다인을 젊은이 늙은이 어린이 여인들을 막론하고 죽이고 도륙하고 진멸하고 또 그 재산을 탈취하라 하였고'),
    (12737, '○도성 수산에 한 유다인이 있으니 이름은 모르드개라 그는 베냐민 자손이니 기스의 증손이요 시므이의 손자요 야일의 아들이라'),
    (12740, '○왕의 조서와 명령이 반포되매 처녀들이 도성 수산에 많이 모여 헤개의 수하에 나아갈 때에 에스더도 왕궁으로 이끌려 가서 궁녀를 주관하는 헤개의 수하에 속하니'),
    (12744, '○처녀마다 차례대로 아하수에로 왕에게 나아가기 전에 여자에 대하여 정한 규례대로 열두 달 동안을 행하되 여섯 달은 몰약 기름을 쓰고 여섯 달은 향품과 여자에게 쓰는 다른 물품을 써서 몸을 정결하게 하는 기한을 마치며'),
    (12747, '모르드개의 삼촌 아비하일의 딸 곧 모르드개가 자기의 딸 같이 양육하는 에스더가 차례대로 왕에게 나아갈 때에 궁녀를 주관하는 내시 헤개가 정한 것 외에는 다른 것을 구하지 아니하였으나 모든 보는 자에게 사랑을 받더라'),
    (12751, '<모르드개가 왕의 목숨을 구하다> ○처녀들을 다시 모을 때에는 모르드개가 대궐 문에 앉았더라'),
    (12774, '○에스더의 시녀와 내시가 나아와 전하니 왕후가 매우 근심하여 입을 의복을 모르드개에게 보내어 그 굵은 베 옷을 벗기고자 하나 모르드개가 받지 아니하는지라'),
    (12781, '왕의 신하들과 왕의 각 지방 백성이 다 알거니와 남녀를 막론하고 부름을 받지 아니하고 안뜰에 들어가서 왕에게 나가면 오직 죽이는 법이요 왕이 그 자에게 금 규를 내밀어야 살 것이라 이제 내가 부름을 입어 왕에게 나가지 못한 지가 이미 삼십 일이라 하라 하니라'),
    (12784, '이 때에 네가 만일 잠잠하여 말이 없으면 유다인은 다른 데로 말미암아 놓임과 구원을 얻으려니와 너와 네 아버지 집은 멸망하리라 네가 왕후의 자리를 얻은 것이 이 때를 위함이 아닌지 누가 알겠느냐 하니'),
    (12786, '당신은 가서 수산에 있는 유다인을 다 모으고 나를 위하여 금식하되 밤낮 삼 일을 먹지도 말고 마시지도 마소서 나도 나의 시녀와 더불어 이렇게 금식한 후에 규례를 어기고 왕에게 나아가리니 죽으면 죽으리이다 하니라'),
    (12810, '그 왕복과 말을 왕의 신하 중 가장 존귀한 자의 손에 맡겨서 왕이 존귀하게 하시기를 원하시는 사람에게 옷을 입히고 말을 태워서 성 중 거리로 다니며 그 앞에서 반포하여 이르기를 왕이 존귀하게 하기를 원하시는 사람에게는 이같이 할 것이라 하게 하소서 하니라'),
    (12811, '○이에 왕이 하만에게 이르되 너는 네 말대로 속히 왕복과 말을 가져다가 대궐 문에 앉은 유다 사람 모르드개에게 행하되 무릇 네가 말한 것에서 조금도 빠짐이 없이 하라'),
    (12814, '자기가 당한 모든 일을 그의 아내 세레스와 모든 친구에게 말하매 그 중 지혜로운 자와 그의 아내 세레스가 이르되 모르드개가 과연 유다 사람의 후손이면 당신이 그 앞에서 굴욕을 당하기 시작하였으니 능히 그를 이기지 못하고 분명히 그 앞에 엎드러지리이다'),
    (12792, '○왕이 이르되 에스더가 말한 대로 하도록 하만을 급히 부르라 하고 이에 왕이 하만과 함께 에스더가 베푼 잔치에 가니라'),
    (12795, '내가 만일 왕의 목전에서 은혜를 입었고 왕이 내 소청을 허락하시며 내 요구를 시행하시기를 좋게 여기시면 내가 왕과 하만을 위하여 베푸는 잔치에 또 오소서 내일은 왕의 말씀대로 하리이다 하니라'),
    (12796, '<하만의 음모> ○그 날 하만이 마음이 기뻐 즐거이 나오더니 모르드개가 대궐 문에 있어 일어나지도 아니하고 몸을 움직이지도 아니하는 것을 보고 매우 노하나'),
    (12801, '그의 아내 세레스와 모든 친구들이 이르되 높이가 오십 규빗 되는 나무를 세우고 내일 왕에게 모르드개를 그 나무에 매달기를 구하고 왕과 함께 즐거이 잔치에 가소서 하니 하만이 그 말을 좋게 여기고 명령하여 나무를 세우니라'),
    (12683, '○이전에 우리 하나님의 전의 방을 맡은 제사장 엘리아십이 도비야와 연락이 있었으므로'),
    (12684, '도비야를 위하여 한 큰 방을 만들었으니 그 방은 원래 소제물과 유향과 그릇과 또 레위 사람들과 노래하는 자들과 문지기들에게 십일조로 주는 곡물과 새 포도주와 기름과 또 제사장들에게 주는 거제물을 두는 곳이라'),
    (12689, '○내가 또 알아본즉 레위 사람들이 받을 몫을 주지 아니하였으므로 그 직무를 행하는 레위 사람들과 노래하는 자들이 각각 자기 밭으로 도망하였기로'),
    (12692, '내가 제사장 셀레먀와 서기관 사독과 레위 사람 브다야를 창고지기로 삼고 맛다냐의 손자 삭굴의 아들 하난을 버금으로 삼았나니 이는 그들이 충직한 자로 인정됨이라 그 직분은 형제들에게 분배하는 일이었느니라'),
    (12694, '○그 때에 내가 본즉 유다에서 어떤 사람이 안식일에 술틀을 밟고 곡식단을 나귀에 실어 운반하며 포도주와 포도와 무화과와 여러 가지 짐을 지고 안식일에 예루살렘에 들어와서 음식물을 팔기로 그 날에 내가 경계하였고'),
    (12697, '너희 조상들이 이같이 행하지 아니하였느냐 그래서 우리 하나님이 이 모든 재앙을 우리와 이 성읍에 내리신 것이 아니냐 그럼에도 불구하고 너희가 안식일을 범하여 진노가 이스라엘에게 더욱 심하게 임하도록 하는도다 하고'),
    (12701, '내가 또 레위 사람들에게 몸을 정결하게 하고 와서 성문을 지켜서 안식일을 거룩하게 하라 하였느니라 내 하나님이여 나를 위하여 이 일도 기억하시옵고 주의 크신 은혜대로 나를 아끼시옵소서'),
    (12702, '○그 때에 내가 또 본즉 유다 사람이 아스돗과 암몬과 모압 여인을 맞아 아내로 삼았는데'),
    (12704, '내가 그들을 책망하고 저주하며 그들 중 몇 사람을 때리고 그들의 머리털을 뽑고 이르되 너희는 너희 딸들을 그들의 아들들에게 주지 말고 너희 아들들이나 너희를 위하여 그들의 딸을 데려오지 아니하겠다고 하나님을 가리켜 맹세하라 하고'),
    (12705, '또 이르기를 옛적에 이스라엘 왕 솔로몬이 이 일로 범죄하지 아니하였느냐 그는 많은 나라 중에 비길 왕이 없이 하나님의 사랑을 입은 자라 하나님이 그를 왕으로 삼아 온 이스라엘을 다스리게 하셨으나 이방 여인이 그를 범죄하게 하였나니'),
    (12707, '○대제사장 엘리아십의 손자 요야다의 아들 하나가 호론 사람 산발랏의 사위가 되었으므로 내가 쫓아내어 나를 떠나게 하였느니라'),
    (12817, '왕이 이 둘째 날 잔치에 술을 마실 때에 다시 에스더에게 물어 이르되 왕후 에스더여 그대의 소청이 무엇이냐 곧 허락하겠노라 그대의 요구가 무엇이냐 곧 나라의 절반이라 할지라도 시행하겠노라'),
    (12823, '왕이 후원으로부터 잔치 자리에 돌아오니 하만이 에스더가 앉은 걸상 위에 엎드렸거늘 왕이 이르되 저가 궁중 내 앞에서 왕후를 강간까지 하고자 하는가 하니 이 말이 왕의 입에서 나오매 무리가 하만의 얼굴을 싸더라'),
    (12824, '왕을 모신 내시 중에 하르보나가 왕에게 아뢰되 왕을 위하여 충성된 말로 고발한 모르드개를 달고자 하여 하만이 높이가 오십 규빗 되는 나무를 준비하였는데 이제 그 나무가 하만의 집에 섰나이다 왕이 이르되 하만을 그 나무에 달라 하매'),
    (12826, '<유다 사람에게 살 길이 열리다> 그 날 아하수에로 왕이 유다인의 대적 하만의 집을 왕후 에스더에게 주니라 에스더가 모르드개는 자기에게 어떻게 관계됨을 왕께 아뢰었으므로 모르드개가 왕 앞에 나오니'),
    (12828, '○에스더가 다시 왕 앞에서 말씀하며 왕의 발 아래 엎드려 아각 사람 하만이 유다인을 해하려 한 악한 꾀를 제거하기를 울며 구하니'),
    (12830, '이르되 왕이 만일 즐거워하시며 내가 왕의 목전에 은혜를 입었고 또 왕이 이 일을 좋게 여기시며 나를 좋게 보실진대 조서를 내리사 아각 사람 함므다다의 아들 하만이 왕의 각 지방에 있는 유다인을 진멸하려고 꾀하고 쓴 조서를 철회하소서'),
    (12834, '○그 때 시완월 곧 삼월 이십삼일에 왕의 서기관이 소집되고 모르드개가 시키는 대로 조서를 써서 인도로부터 구스까지의 백이십칠 지방 유다인과 대신과 지방관과 관원에게 전할새 각 지방의 문자와 각 민족의 언어와 유다인의 문자와 언어로 쓰되'),
    (12836, '조서에는 왕이 여러 고을에 있는 유다인에게 허락하여 그들이 함께 모여 스스로 생명을 보호하여 각 지방의 백성 중 세력을 가지고 그들을 치려하는 자들과 그들의 처자를 죽이고 도륙하고 진멸하고 그 재산을 탈취하게 하되'),
    (12840, '○모르드개가 푸르고 흰 조복을 입고 큰 금관을 쓰고 자색 가는 베 겉옷을 입고 왕 앞에서 나오니 수산 성이 즐거이 부르며 기뻐하고'),
    (12902, '여호와께서 사탄에게 이르시되 네가 내 종 욥을 주의하여 보았느냐 그와 같이 온전하고 정직하여 하나님을 경외하며 악에서 떠난 자가 세상에 없느니라 네가 나를 충동하여 까닭 없이 그를 치게 하였어도 그가 여전히 자기의 온전함을 굳게 지켰느니라'),
    (12906, '○사탄이 이에 여호와 앞에서 물러가서 욥을 쳐서 그의 발바닥에서 정수리까지 종기가 나게 한지라'),
    (12910, '<친구들이 욥을 위로하러 오다> ○그 때에 욥의 친구 세 사람이 이 모든 재앙이 그에게 내렸다 함을 듣고 각각 자기 지역에서부터 이르렀으니 곧 데만 사람 엘리바스와 수아 사람 빌닷과 나아마 사람 소발이라 그들이 욥을 위문하고 위로하려 하여 서로 약속하고 오더니'),
    (12843, '<유다 사람이 대적들을 진멸하다> 아달월 곧 열두째 달 십삼일은 왕의 어명을 시행하게 된 날이라 유다인의 대적들이 그들을 제거하기를 바랐더니 유다인이 도리어 자기들을 미워하는 자들을 제거하게 된 그 날에'),
    (12853, '○그 날에 도성 수산에서 도륙한 자의 수효를 왕께 아뢰니'),
    (12854, '왕이 왕후 에스더에게 이르되 유다인이 도성 수산에서 이미 오백 명을 죽이고 멸하고 또 하만의 열 아들을 죽였으니 왕의 다른 지방에서는 어떠하였겠느냐 이제 그대의 소청이 무엇이냐 곧 허락하겠노라 그대의 요구가 무엇이냐 또한 시행하겠노라 하니'),
    (12859, '○아달월 십삼일에 그 일을 행하였고 십사일에 쉬며 그 날에 잔치를 베풀어 즐겼고'),
    (12862, '<부림일> ○모르드개가 이 일을 기록하고 아하수에로 왕의 각 지방에 있는 모든 유다인에게 원근을 막론하고 글을 보내어 이르기를'),
    (12864, '이 달 이 날에 유다인들이 대적에게서 벗어나서 평안함을 얻어 슬픔이 변하여 기쁨이 되고 애통이 변하여 길한 날이 되었으니 이 두 날을 지켜 잔치를 베풀고 즐기며 서로 예물을 주며 가난한 자를 구제하라 하매'),
    (12932, '○어찌하여 고난 당하는 자에게 빛을 주셨으며 마음이 아픈 자에게 생명을 주셨는고'),
    (12882, '그들이 차례대로 잔치를 끝내면 욥이 그들을 불러다가 성결하게 하되 아침에 일어나서 그들의 명수대로 번제를 드렸으니 이는 욥이 말하기를 혹시 내 아들들이 죄를 범하여 마음으로 하나님을 욕되게 하였을까 함이라 욥의 행위가 항상 이러하였더라'),
    (12883, '○하루는 하나님의 아들들이 와서 여호와 앞에 섰고 사탄도 그들 가운데에 온지라'),
    (12890, '<욥이 자녀와 재산을 잃다> ○하루는 욥의 자녀들이 그 맏아들의 집에서 음식을 먹으며 포도주를 마실 때에'),
    (12894, '그가 아직 말하는 동안에 또 한 사람이 와서 아뢰되 갈대아 사람이 세 무리를 지어 갑자기 낙타에게 달려들어 그것을 빼앗으며 칼로 종들을 죽였나이다 나만 홀로 피하였으므로 주인께 아뢰러 왔나이다'),
    (12895, '그가 아직 말하는 동안에 또 한 사람이 와서 아뢰되 주인의 자녀들이 그들의 맏형의 집에서 음식을 먹으며 포도주를 마시는데'),
    (12950, '○어떤 말씀이 내게 가만히 이르고 그 가느다란 소리가 내 귀에 들렸었나니'),
    (12640, '<대제사장 예수아의 자손들> ○레위 사람들은 예수아와 빈누이와 갓미엘과 세레뱌와 유다와 맛다냐니 이 맛다냐는 그의 형제와 함께 찬송하는 일을 맡았고'),
    (12644, '<제사장의 족장들> ○요야김 때에 제사장, 족장 된 자는 스라야 족속에는 므라야요 예레미야 족속에는 하나냐요'),
    (12654, '<제사장과 레위 사람들에 관한 기록> ○엘리아십과 요야다와 요하난과 얏두아 때에 레위 사람의 족장이 모두 책에 기록되었고 바사 왕 다리오 때에 제사장도 책에 기록되었고'),
    (12659, '<느헤미야가 성벽을 봉헌하다> ○예루살렘 성벽을 봉헌하게 되니 각처에서 레위 사람들을 찾아 예루살렘으로 데려다가 감사하며 노래하며 제금을 치며 비파와 수금을 타며 즐거이 봉헌식을 행하려 하매'),
    (12661, '또 벧길갈과 게바와 아스마웻 들에서 모여들었으니 이 노래하는 자들은 자기들을 위하여 예루살렘 사방에 마을들을 이루었음이라'),
    (12663, '○이에 내가 유다의 방백들을 성벽 위에 오르게 하고 또 감사 찬송하는 자의 큰 무리를 둘로 나누어 성벽 위로 대오를 지어 가게 하였는데 한 무리는 오른쪽으로 분문을 향하여 가게 하니'),
    (12664, '그들의 뒤를 따르는 자는 호세아와 유다 지도자의 절반이요'),
    (12676, '<제사장과 레위 사람에게 준 몫> ○그 날에 사람을 세워 곳간을 맡기고 제사장들과 레위 사람들에게 돌릴 것 곧 율법에 정한 대로 거제물과 처음 익은 것과 십일조를 모든 성읍 밭에서 거두어 이 곳간에 쌓게 하였노니 이는 유다 사람이 섬기는 제사장들과 레위 사람들로 말미암아 즐거워하기 때문이라'),
    (12679, '스룹바벨 때와 느헤미야 때에는 온 이스라엘이 노래하는 자들과 문지기들에게 날마다 쓸 몫을 주되 그들이 성별한 것을 레위 사람들에게 주고 레위 사람들은 그것을 또 성별하여 아론 자손에게 주었느니라'),
    (12967, '○나라면 하나님을 찾겠고 내 일을 하나님께 의탁하리라'),
    (12976, '○볼지어다 하나님께 징계 받는 자에게는 복이 있나니 그런즉 너는 전능자의 징계를 업신여기지 말지니라'),
    (13027, '○그런즉 내가 내 입을 금하지 아니하고 내 영혼의 아픔 때문에 말하며 내 마음의 괴로움 때문에 불평하리이다'),
    (12994, '○나의 간구를 누가 들어 줄 것이며 나의 소원을 하나님이 허락하시랴'),
    (13000, '○낙심한 자가 비록 전능자를 경외하기를 저버릴지라도 그의 친구로부터 동정을 받느니라'),
    (13010, '○내게 가르쳐서 나의 허물된 것을 깨닫게 하라 내가 잠잠하리라'),
    (13045, '○청하건대 너는 옛 시대 사람에게 물으며 조상들이 터득한 일을 배울지어다'),
    (13048, '○왕골이 진펄 아닌 데서 크게 자라겠으며 갈대가 물 없는 데서 크게 자라겠느냐'),
    (13084, '○나의 날이 경주자보다 빨리 사라져 버리니 복을 볼 수 없구나'),
    (13143, '○이제 모든 짐승에게 물어 보라 그것들이 네게 가르치리라 공중의 새에게 물어 보라 그것들이 또한 네게 말하리라'),
    (13149, '○지혜와 권능이 하나님께 있고 계략과 명철도 그에게 속하였나니'),
    (13196, '○나무는 희망이 있나니 찍힐지라도 다시 움이 나서 연한 가지가 끊이지 아니하며'),
    (13207, '○무너지는 산은 반드시 흩어지고 바위는 그 자리에서 옮겨가고'),
    (13181, '<욥의 기도> ○오직 내게 이 두 가지 일을 행하지 마옵소서 그리하시면 내가 주의 얼굴을 피하여 숨지 아니하오리니'),
    (13123, '○네가 하나님의 오묘함을 어찌 능히 측량하며 전능자를 어찌 능히 완전히 알겠느냐'),
    (13252, '○내가 말하여도 내 근심이 풀리지 아니하고 잠잠하여도 내 아픔이 줄어들지 않으리라'),
    (13264, '○땅아 내 피를 가리지 말라 나의 부르짖음이 쉴 자리를 잡지 못하게 하라'),
    (13218, '○네가 제일 먼저 난 사람이냐 산들이 있기 전에 네가 출생하였느냐'),
    (13228, '○내가 네게 보이리니 내게서 들으라 내가 본 것을 설명하리라'),
    (13289, '○악인의 빛은 꺼지고 그의 불꽃은 빛나지 않을 것이요'),
    (13346, '○그는 비록 악을 달게 여겨 혀 밑에 감추며'),
    (13354, '○그는 마음에 평안을 알지 못하니 그가 기뻐하는 것을 하나도 보존하지 못하겠고'),
    (13271, '○청하건대 나에게 담보물을 주소서 나의 손을 잡아 줄 자가 누구리이까'),
    (13274, '○하나님이 나를 백성의 속담거리가 되게 하시니 그들이 내 얼굴에 침을 뱉는구나'),
    (13312, '○내가 폭행을 당한다고 부르짖으나 응답이 없고 도움을 간구하였으나 정의가 없구나'),
    (13318, '○나의 형제들이 나를 멀리 떠나게 하시니 나를 아는 모든 사람이 내게 낯선 사람이 되었구나'),
    (13328, '○나의 말이 곧 기록되었으면, 책에 씌어졌으면,'),
    (13380, '○악인의 등불이 꺼짐과 재앙이 그들에게 닥침과 하나님이 진노하사 그들을 곤고하게 하심이 몇 번인가'),
    (13390, '○내가 너희의 생각을 알고 너희가 나를 해하려는 속셈도 아노라'),
    (13409, '○하나님은 높은 하늘에 계시지 아니하냐 보라 우두머리 별이 얼마나 높은가'),
    (13418, '○너는 하나님과 화목하고 평안하라 그리하면 복이 네게 임하리라'),
    (13480, '○죽은 자의 영들이 물 밑에서 떨며 물에서 사는 것들도 그러하도다'),
    (13437, '○그러나 내가 가는 길을 그가 아시나니 그가 나를 단련하신 후에는 내가 순금 같이 되어 나오리라'),
    (13457, '○또 광명을 배반하는 사람들은 이러하니 그들은 그 도리를 알지 못하며 그 길에 머물지 아니하는 자라'),
    (13462, '○그들은 물 위에 빨리 흘러가고 그들의 소유는 세상에서 저주를 받나니 그들이 다시는 포도원 길로 다니지 못할 것이라'),
    (13502, '○악인이 하나님께 얻을 분깃, 포악자가 전능자에게서 받을 산업은 이것이라'),
    (13524, '○그러나 지혜는 어디서 얻으며 명철이 있는 곳은 어디인고'),
    (13574, '○이제는 그들이 나를 노래로 조롱하며 내가 그들의 놀림거리가 되었으며'),
    (13581, '○이제는 내 생명이 내 속에서 녹으니 환난 날이 나를 사로잡음이라'),
    (13589, '○그러나 사람이 넘어질 때에 어찌 손을 펴지 아니하며 재앙을 당할 때에 어찌 도움을 부르짖지 아니하리이까'),
    (13637, '<엘리후가 화를 내다> 욥이 자신을 의인으로 여기므로 그 세 사람이 말을 그치니'),
    (13642, '<엘리후의 말> ○부스 사람 바라겔의 아들 엘리후가 대답하여 이르되 나는 연소하고 당신들은 연로하므로 뒷전에서 나의 의견을 감히 내놓지 못하였노라'),
    (13647, '○보라 나는 당신들의 말을 기다렸노라 당신들의 슬기와 당신들의 말에 귀 기울이고 있었노라'),
    (13651, '○그들이 놀라서 다시 대답하지 못하니 할 말이 없음이었더라'),
    (13601, '○만일 내가 허위와 함께 동행하고 내 발이 속임수에 빨랐다면'),
    (13605, '○만일 내 마음이 여인에게 유혹되어 이웃의 문을 엿보아 문에서 숨어 기다렸다면'),
    (13612, '○내가 언제 가난한 자의 소원을 막았거나 과부의 눈으로 하여금 실망하게 하였던가'),
    (13620, '○만일 내가 내 소망을 금에다 두고 순금에게 너는 내 의뢰하는 바라 하였다면'),
    (13629, '내가 언제  다른 사람처럼 내 악행을 숨긴 일이 있거나 나의 죄악을 나의 품에 감추었으며'),
    (13666, '○그대는 실로 내가 듣는 데서 말하였고 나는 그대의 말소리를 들었느니라'),
    (13671, '○하나님께서 사람의 말에 대답하지 않으신다 하여 어찌 하나님과 논쟁하겠느냐'),
    (13677, '○혹은 사람이 병상의 고통과 뼈가 늘 쑤심의 징계를 받나니'),
    (13681, '○만일 일천 천사 가운데 하나가 그 사람의 중보자로 함께 있어서 그의 정당함을 보일진대'),
    (13687, '○실로 하나님이 사람에게 이 모든 일을 재삼 행하심은'),
    (13737, '○사람은 학대가 많으므로 부르짖으며 군주들의 힘에 눌려 소리치나'),
    (13701, '○그러므로 너희 총명한 자들아 내 말을 들으라 하나님은 악을 행하지 아니하시며 전능자는 결코 불의를 행하지 아니하시고'),
    (13707, '○만일 네가 총명이 있거든 이것을 들으며 내 말소리에 귀를 기울이라'),
    (13712, '○그는 사람의 길을 주목하시며 사람의 모든 걸음을 감찰하시나니'),
    (13722, '○그대가 하나님께 아뢰기를 내가 죄를 지었사오니 다시는 범죄하지 아니하겠나이다'),
    (13761, '○이제는 악인의 받을 벌이 그대에게 가득하였고 심판과 정의가 그대를 잡았나니'),
    (13768, '○그대는 하나님께서 하신 일을 기억하고 높이라 잊지 말지니라 인생이 그의 일을 찬송하였느니라'),
    (13791, '○욥이여 이것을 듣고 가만히 서서 하나님의 오묘한 일을 깨달으라'),
    (13798, '○그런즉 바람이 불어 하늘이 말끔하게 되었을 때 그 밝은 빛을 아무도 볼 수 없느니라'),
    (13847, '○누가 들나귀를 놓아 자유롭게 하였느냐 누가 빠른 나귀의 매인 것을 풀었느냐'),
    (13855, '○타조는 즐거이 날개를 치나 학의 깃털과 날개 같겠느냐'),
    (13861, '○말의 힘을 네가 주었느냐 그 목에 흩날리는 갈기를 네가 입혔느냐'),
    (13868, '○매가 떠올라서 날개를 펼쳐 남쪽으로 향하는 것이 어찌 네 지혜로 말미암음이냐'),
    (13809, '○바다가 그 모태에서 터져 나올 때에 문으로 그것을 가둔 자가 누구냐'),
    (13813, '○네가 너의 날에 아침에게 명령하였느냐 새벽에게 그 자리를 일러 주었느냐'),
    (13817, '○네가 바다의 샘에 들어갔었느냐 깊은 물 밑으로 걸어 다녀 보았느냐'),
    (13820, '○어느 것이 광명이 있는 곳으로 가는 길이냐 어느 것이 흑암이 있는 곳으로 가는 길이냐'),
    (13826, '○누가 홍수를 위하여 물길을 터 주었으며 우레와 번개 길을 내어 주었느냐'),
    (13832, '○네가 묘성을 매어 묶을 수 있으며 삼성의 띠를 풀 수 있겠느냐'),
    (13835, '○네가 목소리를 구름에까지 높여 넘치는 물이 네게 덮이게 하겠느냐'),
    (13840, '○네가 사자를 위하여 먹이를 사냥하겠느냐 젊은 사자의 식욕을 채우겠느냐'),
    (13882, '○너는 위엄과 존귀로 단장하며 영광과 영화를 입을지니라'),
    (13887, '○이제 소 같이 풀을 먹는 베헤못을 볼지어다 내가 너를 지은 것 같이 그것도 지었느니라'),
    (13908, '○내가 그것의 지체와 그것의 큰 용맹과 늠름한 체구에 대하여 잠잠하지 아니하리라'),
    (13937, '<결론> ○여호와께서 욥에게 이 말씀을 하신 후에 여호와께서 데만 사람 엘리바스에게 이르시되 내가 너와 네 두 친구에게 노하나니 이는 너희가 나를 가리켜 말한 것이 내 종 욥의 말 같이 옳지 못함이니라'),
    (13938, '그런즉 너희는 수소 일곱과 숫양 일곱을 가지고 내 종 욥에게 가서 너희를 위하여 번제를 드리라 내 종 욥이 너희를 위하여 기도할 것인즉 내가 그를 기쁘게 받으리니 너희가 우매한 만큼 너희에게 갚지 아니하리라 이는 너희가 나를 가리켜 말한 것이 내 종 욥의 말 같이 옳지 못함이라'),
    (13940, '<여호와께서 욥에게 복을 주시다> ○욥이 그의 친구들을 위하여 기도할 때 여호와께서 욥의 곤경을 돌이키시고 여호와께서 욥에게 이전 모든 소유보다 갑절이나 주신지라'),
    (13941, '이에 그의 모든 형제와 자매와 이전에 알던 이들이 다 와서 그의 집에서 그와 함께 음식을 먹고 여호와께서 그에게 내리신 모든 재앙에 관하여 그를 위하여 슬퍼하며 위로하고 각각 케쉬타 하나씩과 금 고리 하나씩을 주었더라'),
    (13961, '○내가 여호와의 명령을 전하노라 여호와께서 내게 이르시되 너는 내 아들이라 오늘 내가 너를 낳았도다'),
    (13964, '○그런즉 군왕들아 너희는 지혜를 얻으며 세상의 재판관들아 너희는 교훈을 받을지어다'),
    (13975, '<다윗의 시, 인도자를 따라 현악에 맞춘 노래,> 내 의의 하나님이여 내가 부를 때에 응답하소서 곤란 중에 나를 너그럽게 하셨사오니 내게 은혜를 베푸사 나의 기도를 들으소서'),
    (13983, '<다윗의 시, 인도자를 따라 관악에 맞춘 노래,> 여호와여 나의 말에 귀를 기울이사 나의 심정을 헤아려 주소서'),
    (13990, '여호와여 나의 원수들로 말미암아 주의 의로 나를 인도하시고 주의 길을 내 목전에 곧게 하소서'),
    (13994, '여호와여 주는 의인에게 복을 주시고 방패로 함 같이 은혜로 그를 호위하시리이다'),
    (13995, '<다윗의 시, 인도자를 따라 현악 여덟째 줄에 맞춘 노래,> 여호와여 주의 분노로 나를 책망하지 마시오며 주의 진노로 나를 징계하지 마옵소서'),
    (14005, '<다윗의 식가욘, 베냐민인 구시의 말에 따라 여호와께 드린 노래,> 여호와 내 하나님이여 내가 주께 피하오니 나를 쫓아오는 모든 자들에게서 나를 구원하여 내소서'),
    (14031, '<다윗의 시, 인도자를 따라 뭇랍벤에 맞춘 노래,> 내가 전심으로 여호와께 감사하오며 주의 모든 기이한 일들을 전하리이다'),
    (14022, '<다윗의 시, 인도자를 따라 깃딧에 맞춘 노래,> 여호와 우리 주여 주의 이름이 온 땅에 어찌 그리 아름다운지요 주의 영광이 하늘을 덮었나이다'),
    (14060, '그가 구부려 엎드리니 그의 포악으로 말미암아 가련한 자들이 넘어지나이다'),
    (14069, '<다윗의 시, 인도자를 따라 부르는 노래,> 내가 여호와께 피하였거늘 너희가 내 영혼에게 새 같이 네 산으로 도망하라 함은 어찌함인가'),
    (14090, '<다윗의 시, 인도자를 따라 부르는 노래,> 어리석은 자는 그의 마음에 이르기를 하나님이 없다 하는도다 그들은 부패하고 그 행실이 가증하니 선을 행하는 자가 없도다'),
    (14076, '<다윗의 시, 인도자를 따라 여덟째 줄에 맞춘 노래,> 여호와여 도우소서 경건한 자가 끊어지며 충실한 자들이 인생 중에 없어지나이다'),
    (14084, '<다윗의 시, 인도자를 따라 부르는 노래,> 여호와여 어느 때까지니이까 나를 영원히 잊으시나이까 주의 얼굴을 나에게서 어느 때까지 숨기시겠나이까'),
    (14178, '<다윗의 시, 인도자를 따라 부르는 노래,> 하늘이 하나님의 영광을 선포하고 궁창이 그의 손으로 하신 일을 나타내는도다'),
    (14184, '○여호와의 율법은 완전하여 영혼을 소성시키며 여호와의 증거는 확실하여 우둔한 자를 지혜롭게 하며'),
    (14126, '여호와여 이 세상에 살아 있는 동안 그들의 분깃을 받은 사람들에게서 주의 손으로 나를 구하소서 그들은 주의 재물로 배를 채우고 자녀로 만족하고 그들의 남은 산업을 그들의 어린 아이들에게 물려 주는 자니이다'),
    (14201, '<다윗의 시, 인도자를 따라 부르는 노래,> 여호와여 왕이 주의 힘으로 말미암아 기뻐하며 주의 구원으로 말미암아 크게 즐거워하리이다'),
    (14192, '<다윗의 시, 인도자를 따라 부르는 노래,> 환난 날에 여호와께서 네게 응답하시고 야곱의 하나님의 이름이 너를 높이 드시며'),
    (14214, '<다윗의 시, 인도자를 따라 아얠렛샤할에 맞춘 노래,> 내 하나님이여 내 하나님이여 어찌 나를 버리셨나이까 어찌 나를 멀리 하여 돕지 아니하시오며 내 신음 소리를 듣지 아니하시나이까'),
    (14235, '○내가 주의 이름을 형제에게 선포하고 회중 가운데에서 주를 찬송하리이다'),
    (14128, '<여호와의 종 다윗의 시, 인도자를 따라 부르는 노래, 여호와께서 다윗을 그 모든 원수들의 손에서와 사울의 손에서 건져 주신 날에 다윗이 이 노래의 말로 여호와께 아뢰어 이르되> 나의 힘이신 여호와여 내가 주를 사랑하나이다'),
    (14255, '그는 여호와께 복을 받고 구원의 하나님께 의를 얻으리니'),
    (14257, '○문들아 너희 머리를 들지어다 영원한 문들아 들릴지어다 영광의 왕이 들어가시리로다'),
    (14314, '○여호와를 찬송함이여 내 간구하는 소리를 들으심이로다'),
    (14320, '○여호와의 소리가 물 위에 있도다 영광의 하나님이 우렛소리를 내시니 여호와는 많은 물 위에 계시도다'),
    (14327, '○여호와께서 홍수 때에 좌정하셨음이여 여호와께서 영원하도록 왕으로 좌정하시도다'),
    (14301, '○여호와여 내가 소리 내어 부르짖을 때에 들으시고 또한 나를 긍휼히 여기사 응답하소서'),
    (14329, '<다윗의 시, 곧 성전 낙성가,> 여호와여 내가 주를 높일 것은 주께서 나를 끌어내사 내 원수로 하여금 나로 말미암아 기뻐하지 못하게 하심이니이다'),
    (14330, '여호와 내 하나님이여 내가 주께 부르짖으매 나를 고치셨나이다'),
    (14341, '<다윗의 시, 인도자를 따라 부르는 노래,> 여호와여 내가 주께 피하오니 나를 영원히 부끄럽게 하지 마시고 주의 공의로 나를 건지소서'),
    (14448, '<여호와의 종 다윗의 시, 인도자를 따라 부르는 노래,> 악인의 죄가 그의 마음속으로 이르기를 그의 눈에는 하나님을 두려워하는 빛이 없다 하니'),
    (14452, '○여호와여 주의 인자하심이 하늘에 있고 주의 진실하심이 공중에 사무쳤으며'),
    (14453, '주의 의는 하나님의 산들과 같고 주의 심판은 큰 바다와 같으니이다 여호와여 주는 사람과 짐승을 구하여 주시나이다'),
    (14522, '<다윗의 시, 인도자를 따라 여두둔 형식으로 부르는 노래,> 내가 말하기를 나의 행위를 조심하여 내 혀로 범죄하지 아니하리니 악인이 내 앞에 있을 때에 내가 내 입에 재갈을 먹이리라 하였도다'),
    (14535, '<다윗의 시, 인도자를 따라 부르는 노래,> 내가 여호와를 기다리고 기다렸더니 귀를 기울이사 나의 부르짖음을 들으셨도다'),
    (14566, '<고라 자손의 마스길, 인도자를 따라 부르는 노래,> 하나님이여 사슴이 시냇물을 찾기에 갈급함 같이 내 영혼이 주를 찾기에 갈급하니이다'),
    (14571, '○내 하나님이여 내 영혼이 내 속에서 낙심이 되므로 내가 요단 땅과 헤르몬과 미살 산에서 주를 기억하나이다'),
    (14552, '<다윗의 시, 인도자를 따라 부르는 노래,> 가난한 자를 보살피는 자에게 복이 있음이여 재앙의 날에 여호와께서 그를 건지시리로다'),
    (14564, '○이스라엘의 하나님 여호와를 영원부터 영원까지 송축할지로다 아멘 아멘'),
    (14582, '<고라 자손의 마스길, 인도자를 따라 부르는 노래,> 하나님이여 주께서 우리 조상들의 날 곧 옛날에 행하신 일을 그들이 우리에게 일러 주매 우리가 우리 귀로 들었나이다'),
    (14590, '○그러나 이제는 주께서 우리를 버려 욕을 당하게 하시고 우리 군대와 함께 나아가지 아니하시나이다'),
    (14625, '<고라 자손의 시, 인도자를 따라 알라못에 맞춘 노래,> 하나님은 우리의 피난처시요 힘이시니 환난 중에 만날 큰 도움이시라'),
    (14628, '○한 시내가 있어 나뉘어 흘러 하나님의 성 곧 지존하신 이의 성소를 기쁘게 하도다'),
    (14636, '<고라 자손의 시, 인도자를 따라 부르는 노래,> 너희 만민들아 손바닥을 치고 즐거운 소리로 하나님께 외칠지어다'),
    (14659, '<고라 자손의 시, 인도자를 따라 부르는 노래,> 뭇 백성들아 이를 들으라 세상의 거민들아 모두 귀를 기울이라'),
    (14671, '○이것이 바로 어리석은 자들의 길이며 그들의 말을 기뻐하는 자들의 종말이로다 (셀라)'),
    (14694, '○악인에게는 하나님이 이르시되 네가 어찌하여 내 율례를 전하며 내 언약을 네 입에 두느냐'),
    (14700, '○하나님을 잊어버린 너희여 이제 이를 생각하라 그렇지 아니하면 내가 너희를 찢으리니 건질 자 없으리라'),
    (14702, '<다윗의 시, 인도자를 따라 부르는 노래, 다윗이 밧세바와 동침한 후 선지자 나단이 그에게 왔을 때> 하나님이여 주의 인자를 따라 내게 은혜를 베푸시며 주의 많은 긍휼을 따라 내 죄악을 지워 주소서'),
    (14715, '하나님이여 나의 구원의 하나님이여 피 흘린 죄에서 나를 건지소서 내 혀가 주의 의를 높이 노래하리이다'),
    (14736, '<다윗의 마스길, 인도자를 따라 현악에 맞춘 노래, 십 사람이 사울에게 이르러 말하기를 다윗이 우리가 있는 곳에 숨지 아니하였나이까 하던 때에> 하나님이여 주의 이름으로 나를 구원하시고 주의 힘으로 나를 변호하소서'),
    (14721, '<다윗의 마스길, 인도자를 따라 부르는 노래, 에돔인 도엑이 사울에게 이르러 다윗이 아히멜렉의 집에 왔다고 그에게 말하던 때에> 포악한 자여 네가 어찌하여 악한 계획을 스스로 자랑하는가 하나님의 인자하심은 항상 있도다'),
    (14730, '<다윗의 마스길, 인도자를 따라 마할랏에 맞춘 노래,> 어리석은 자는 그의 마음에 이르기를 하나님이 없다 하도다 그들은 부패하며 가증한 악을 행함이여 선을 행하는 자가 없도다'),
    (14779, '<다윗의 믹담 시, 인도자를 따라 알다스헷에 맞춘 노래, 다윗이 사울을 피하여 굴에 있던 때에> 하나님이여 내게 은혜를 베푸소서 내게 은혜를 베푸소서 내 영혼이 주께로 피하되 주의 날개 그늘 아래에서 이 재앙들이 지나기까지 피하리이다'),
    (14784, '○그들이 내 걸음을 막으려고 그물을 준비하였으니 내 영혼이 억울하도다 그들이 내 앞에 웅덩이를 팠으나 자기들이 그 중에 빠졌도다 (셀라)'),
    (14743, '<다윗의 마스길, 인도자를 따라 현악에 맞춘 노래,> 하나님이여 내 기도에 귀를 기울이시고 내가 간구할 때에 숨지 마소서'),
    (14790, '<다윗의 믹담 시, 인도자를 따라 알다스헷에 맞춘 노래,> 통치자들아 너희가 정의를 말해야 하거늘 어찌 잠잠하냐 인자들아 너희가 올바르게 판결해야 하거늘 어찌 잠잠하냐'),
    (14801, '<다윗의 믹담 시, 인도자를 따라 알다스헷에 맞춘 노래, 사울이 사람을 보내어 다윗을 죽이려고 그 집을 지킨 때에> 나의 하나님이여 나의 원수에게서 나를 건지시고 일어나 치려는 자에게서 나를 높이 드소서'),
    (14830, '<다윗의 시, 인도자를 따라 현악에 맞춘 노래,> 하나님이여 나의 부르짖음을 들으시며 내 기도에 유의하소서'),
    (14818, '<다윗이 교훈하기 위하여 지은 믹담, 인도자를 따라 수산에둣에 맞춘 노래, 다윗이 아람 나하라임과 아람소바와 싸우는 중에 요압이 돌아와 에돔을 소금 골짜기에서 쳐서 만 이천 명을 죽인 때에> 하나님이여 주께서 우리를 버려 흩으셨고 분노하셨사오나 지금은 우리를 회복시키소서'),
    (14822, '○주께서 사랑하시는 자를 건지시기 위하여 주의 오른손으로 구원하시고 응답하소서'),
    (14838, '<다윗의 시, 인도자를 따라 여두둔의 법칙에 따라 부르는 노래,> 나의 영혼이 잠잠히 하나님만 바람이여 나의 구원이 그에게서 나오는도다'),
    (14861, '<다윗의 시, 인도자를 따라 부르는 노래,> 하나님이여 내가 근심하는 소리를 들으시고 원수의 두려움에서 나의 생명을 보존하소서'),
    (14850, '<다윗의 시, 유다 광야에 있을 때에,> 하나님이여 주는 나의 하나님이시라 내가 간절히 주를 찾되 물이 없어 마르고 황폐한 땅에서 내 영혼이 주를 갈망하며 내 육체가 주를 앙모하나이다'),
    (14871, '<다윗의 시, 인도자를 따라 부르는 노래,> 하나님이여 찬송이 시온에서 주를 기다리오며 사람이 서원을 주께 이행하리이다'),
    (14988, '주의 의로 나를 건지시며 나를 풀어 주시며 주의 귀를 내게 기울이사 나를 구원하소서'),
    (15005, '하나님이여 주의 의가 또한 지극히 높으시니이다 하나님이여 주께서 큰 일을 행하셨사오니 누가 주와 같으리이까'),
    (15010, '나의 혀도 종일토록 주의 의를 작은 소리로 읊조리오리니 나를 모해하려 하던 자들이 수치와 무안을 당함이니이다'),
    (14917, '○하나님이여 주의 백성 앞에서 앞서 나가사 광야에서 행진하셨을 때에 (셀라)'),
    (14929, '○날마다 우리 짐을 지시는 주 곧 우리의 구원이신 하나님을 찬송할지로다 (셀라)'),
    (14938, '○네 하나님이 너의 힘을 명령하셨도다 하나님이여 우리를 위하여 행하신 것을 견고하게 하소서'),
    (15071, '○하나님은 예로부터 나의 왕이시라 사람에게 구원을 베푸셨나이다'),
    (15012, '그가 주의 백성을 공의로 재판하며 주의 가난한 자를 정의로 재판하리니'),
    (15013, '의로 말미암아 산들이 백성에게 평강을 주며 작은 산들도 그리하리로다'),
    (15093, '<아삽의 시, 인도자를 따라 현악에 맞춘 노래> 하나님은 유다에 알려지셨으며 그의 이름이 이스라엘에 크시도다'),
    (15213, '○만군의 하나님 여호와여 주의 백성의 기도에 대하여 어느 때까지 노하시리이까'),
    (15217, '○주께서 한 포도나무를 애굽에서 가져다가 민족들을 쫓아내시고 그것을 심으셨나이다'),
    (15424, '<안식일의 찬송 시> 지존자여 십현금과 비파와 수금으로 여호와께 감사하며'),
    (15490, '구름과 흑암이 그를 둘렀고 의와 공평이 그의 보좌의 기초로다'),
    (15340, '○주께서 이르시되 나는 내가 택한 자와 언약을 맺으며 내 종 다윗에게 맹세하기를'),
    (15351, '의와 공의가 주의 보좌의 기초라 인자함과 진실함이 주 앞에 있나이다'),
    (15356, '○그 때에 주께서 환상 중에 주의 성도들에게 말씀하여 이르시기를 내가 능력 있는 용사에게는 돕는 힘을 더하며 백성 중에서 택함 받은 자를 높였으되'),
    (15375, '○그러나 주께서 주의 기름 부음 받은 자에게 노하사 물리치셔서 버리셨으며'),
    (15389, '○여호와를 영원히 찬송할지어다 아멘 아멘'),
    (15513, '○능력 있는 왕은 정의를 사랑하느니라 주께서 공의를 견고하게 세우시고 주께서 야곱에게 정의와 공의를 행하시나이다'),
    (15515, '○그의 제사장들 중에는 모세와 아론이 있고 그의 이름을 부르는 자들 중에는 사무엘이 있도다 그들이 여호와께 간구하매 응답하셨도다'),
    (15532, '<곤고한 자가 마음이 상하여 그 근심을 여호와 앞에 토하는 기도> 여호와여 내 기도를 들으시고 나의 부르짖음을 주께 상달하게 하소서'),
    (15543, '○여호와여 주는 영원히 계시고 주에 대한 기억은 대대에 이르리이다'),
    (15554, '○그가 내 힘을 중도에 쇠약하게 하시며 내 날을 짧게 하셨도다'),
    (15576, '여호와의 인자하심은 자기를 경외하는 자에게 영원부터 영원까지 이르며 그의 의는 자손의 자손에게 이르리니'),
    (15621, '그의 종 아브라함의 후손 곧 택하신 야곱의 자손 너희는'),
    (15628, '이 족속에게서 저 족속에게로, 이 나라에서 다른 민족에게로 떠돌아 다녔도다'),
    (15713, '○그들이 광야 사막 길에서 방황하며 거주할 성읍을 찾지 못하고'),
    (15719, '○사람이 흑암과 사망의 그늘에 앉으며 곤고와 쇠사슬에 매임은'),
    (15732, '○배들을 바다에 띄우며 큰 물에서 일을 하는 자는'),
    (15742, '○여호와께서는 강이 변하여 광야가 되게 하시며 샘이 변하여 마른 땅이 되게 하시며'),
    (15806, '그의 행하시는 일이 존귀하고 엄위하며 그의 의가 영원히 서 있도다'),
    (16094, '○여호와께서 너를 실족하지 아니하게 하시며 너를 지키시는 이가 졸지 아니하시리로다'),
    (15917, '○청년이 무엇으로 그의 행실을 깨끗하게 하리이까 주의 말씀만 지킬 따름이니이다'),
    (15925, '○주의 종을 후대하여 살게 하소서 그리하시면 주의 말씀을 지키리이다'),
    (15933, '○내 영혼이 진토에 붙었사오니 주의 말씀대로 나를 살아나게 하소서'),
    (15941, '○여호와여 주의 율례들의 도를 내게 가르치소서 내가 끝까지 지키리이다'),
    (15948, '내가 주의 법도들을 사모하였사오니 주의 의로 나를 살아나게 하소서'),
    (15949, '○여호와여 주의 말씀대로 주의 인자하심과 주의 구원을 내게 임하게 하소서'),
    (15957, '○주의 종에게 하신 말씀을 기억하소서 주께서 내게 소망을 가지게 하셨나이다'),
    (15965, '○여호와는 나의 분깃이시니 나는 주의 말씀을 지키리라 하였나이다'),
    (15973, '○여호와여 주의 말씀대로 주의 종을 선대하셨나이다'),
    (15981, '○주의 손이 나를 만들고 세우셨사오니 내가 깨달아 주의 계명들을 배우게 하소서'),
    (15989, '○나의 영혼이 주의 구원을 사모하기에 피곤하오나 나는 주의 말씀을 바라나이다'),
    (15997, '○여호와여 주의 말씀은 영원히 하늘에 굳게 섰사오며'),
    (16005, '○내가 주의 법을 어찌 그리 사랑하는지요 내가 그것을 종일 작은 소리로 읊조리나이다'),
    (16013, '○주의 말씀은 내 발에 등이요 내 길에 빛이니이다'),
    (16021, '○내가 두 마음 품는 자들을 미워하고 주의 법을 사랑하나이다'),
    (16029, '○내가 정의와 공의를 행하였사오니 나를 박해하는 자들에게 나를 넘기지 마옵소서'),
    (16037, '○주의 증거들은 놀라우므로 내 영혼이 이를 지키나이다'),
    (16045, '○여호와여 주는 의로우시고 주의 판단은 옳으니이다'),
    (16050, '주의 의는 영원한 의요 주의 율법은 진리로소이다'),
    (16053, '○여호와여 내가 전심으로 부르짖었사오니 내게 응답하소서 내가 주의 교훈들을 지키리이다'),
    (16061, '○나의 고난을 보시고 나를 건지소서 내가 주의 율법을 잊지 아니함이니이다'),
    (16069, '○고관들이 거짓으로 나를 핍박하오나 나의 마음은 주의 말씀만 경외하나이다'),
    (16077, '○여호와여 나의 부르짖음이 주의 앞에 이르게 하시고 주의 말씀대로 나를 깨닫게 하소서'),
    (16200, '○열국의 우상은 은금이요 사람의 손으로 만든 것이라'),
    (16279, '○내가 여호와께 말하기를 주는 나의 하나님이시니 여호와여 나의 간구하는 소리에 귀를 기울이소서 하였나이다'),
    (16304, '<다윗의 시> 여호와여 내 기도를 들으시며 내 간구에 귀를 기울이시고 주의 진실과 의로 내게 응답하소서'),
    (16306, '원수가 내 영혼을 핍박하며 내 생명을 땅에 엎어서 나로 죽은 지 오랜 자 같이 나를 암흑 속에 두었나이다'),
    (16314, '여호와여 주의 이름을 위하여 나를 살리시고 주의 의로 내 영혼을 환난에서 끌어내소서'),
    (16327, '○우리 아들들은 어리다가 장성한 나무들과 같으며 우리 딸들은 궁전의 양식대로 아름답게 다듬은 모퉁잇돌들과 같으며'),
    (16337, '그들이 주의 크신 은혜를 기념하여 말하며 주의 의를 노래하리이다'),
    (16417, '<젊은이에게 주는 교훈> ○여호와를 경외하는 것이 지식의 근본이거늘 미련한 자는 지혜와 훈계를 멸시하느니라'),
    (16420, '○내 아들아 악한 자가 너를 꾈지라도 따르지 말라'),
    (16430, '<지혜가 부른다> ○지혜가 길거리에서 부르며 광장에서 소리를 높이며'),
    (16510, '○내 아들아 들으라 내 말을 받으라 그리하면 네 생명의 해가 길리라'),
    (16520, '○내 아들아 내 말에 주의하며 내가 말하는 것에 네 귀를 기울이라'),
    (16476, '○내 아들아 여호와의 징계를 경히 여기지 말라 그 꾸지람을 싫어하지 말라'),
    (16492, '○네 손이 선을 베풀 힘이 있거든 마땅히 받을 자에게 베풀기를 아끼지 말며'),
    (16534, '○그런즉 아들들아 나에게 들으며 내 입의 말을 버리지 말고'),
    (16542, '○너는 네 우물에서 물을 마시며 네 샘에서 흐르는 물을 마시라'),
    (16556, '○게으른 자여 개미에게 가서 그가 하는 것을 보고 지혜를 얻으라'),
    (16562, '○불량하고 악한 자는 구부러진 말을 하고 다니며'),
    (16570, '<훈계와 명령> ○내 아들아 네 아비의 명령을 지키며 네 어미의 법을 떠나지 말고'),
    (16655, '○거만한 자를 징계하는 자는 도리어 능욕을 받고 악인을 책망하는 자는 도리어 흠이 잡히느니라'),
    (16661, '○미련한 여인이 떠들며 어리석어서 아무것도 알지 못하고'),
    (16609, '○이제 아들들아 내 말을 듣고 내 입의 말에 주의하라'),
    (16634, '○여호와께서 그 조화의 시작 곧 태초에 일하시기 전에 나를 가지셨으며'),
    (16644, '○아들들아 이제 내게 들으라 내 도를 지키는 자가 복이 있느니라'),
    (16667, '<솔로몬의 잠언> 솔로몬의 잠언이라 ○지혜로운 아들은 아비를 기쁘게 하거니와 미련한 아들은 어미의 근심이니라'),
    (16765, '스스로 부한 체하여도 아무 것도 없는 자가 있고 스스로 가난한 체하여도 재물이 많은 자가 있느니라'),
    (17043, '○너는 귀를 기울여 지혜 있는 자의 말씀을 들으며 내 지식에 마음을 둘지어다'),
    (17048, '○약한 자를 그가 약하다고 탈취하지 말며 곤고한 자를 성문에서 압제하지 말라'),
    (17102, '네가 말하기를 나는 그것을 알지 못하였노라 할지라도 마음을 저울질 하시는 이가 어찌 통찰하지 못하시겠으며 네 영혼을 지키시는 이가 어찌 알지 못하시겠느냐 그가 각 사람의 행위대로 보응하시리라'),
    (17113, '○이것도 지혜로운 자들의 말씀이라 ○재판할 때에 낯을 보아 주는 것이 옳지 못하니라'),
    (17127, '○일을 숨기는 것은 하나님의 영화요 일을 살피는 것은 왕의 영화니라'),
    (17204, '○네 양 떼의 형편을 부지런히 살피며 네 소 떼에게 마음을 두라'),
    (17298, '○내 아들아 내가 무엇을 말하랴 내 태에서 난 아들아 내가 무엇을 말하랴 서원대로 얻은 아들아 내가 무엇을 말하랴'),
    (17306, '<현숙한 아내> ○누가 현숙한 여인을 찾아 얻겠느냐 그의 값은 진주보다 더 하니라'),
    (17265, '○나는 다른 사람에게 비하면 짐승이라 내게는 사람의 총명이 있지 아니하니라'),
    (17267, '하늘에 올라갔다가 내려온 자가 누구인지, 바람을 그 장중에 모은 자가 누구인지, 물을 옷에 싼 자가 누구인지, 땅의 모든 끝을 정한 자가 누구인지, 그의 이름이 무엇인지, 그의 아들의 이름이 무엇인지 너는 아느냐'),
    (17268, '○하나님의 말씀은 다 순전하며 하나님은 그를 의지하는 자의 방패시니라'),
    (17270, '○내가 두 가지 일을 주께 구하였사오니 내가 죽기 전에 내게 거절하지 마시옵소서'),
    (17273, '○너는 종을 그의 상전에게 비방하지 말라 그가 너를 저주하겠고 너는 죄책을 당할까 두려우니라'),
    (17274, '○아비를 저주하며 어미를 축복하지 아니하는 무리가 있느니라'),
    (17278, '○거머리에게는 두 딸이 있어 다오 다오 하느니라 족한 줄을 알지 못하여 족하다 하지 아니하는 것 서넛이 있나니'),
    (17280, '○아비를 조롱하며 어미 순종하기를 싫어하는 자의 눈은 골짜기의 까마귀에게 쪼이고 독수리 새끼에게 먹히리라'),
    (17281, '○내가 심히 기이히 여기고도 깨닫지 못하는 것 서넛이 있나니'),
    (17284, '○세상을 진동시키며 세상이 견딜 수 없게 하는 것 서넛이 있나니'),
    (17287, '○땅에 작고도 가장 지혜로운 것 넷이 있나니'),
    (17292, '○잘 걸으며 위풍 있게 다니는 것 서넛이 있나니'),
    (17295, '○만일 네가 미련하여 스스로 높은 체하였거나 혹 악한 일을 도모하였거든 네 손으로 입을 막으라'),
    (17385, '하나님께서 행하시는 모든 것은 영원히 있을 것이라 그 위에 더 할 수도 없고 그것에서 덜 할 수도 없나니 하나님이 이같이 행하심은 사람들이 그의 앞에서 경외하게 하려 하심인 줄을 내가 알았도다'),
    (17387, '○또 내가 해 아래에서 보건대 재판하는 곳 거기에도 악이 있고 정의를 행하는 곳 거기에도 악이 있도다'),
    (17393, '그러므로 나는 사람이 자기 일에 즐거워하는 것보다 더 나은 것이 없음을 보았나니 이는 그것이 그의 몫이기 때문이라 아, 그의 뒤에 일어날 일이 무엇인지를 보게 하려고 그를 도로 데리고 올 자가 누구이랴'),
    (17329, '○전도자가 이르되 헛되고 헛되며 헛되고 헛되니 모든 것이 헛되도다'),
    (17339, '<지혜가 많으면 번뇌도 많다> ○나 전도자는 예루살렘에서 이스라엘 왕이 되어'),
    (17343, '내가 내 마음 속으로 말하여 이르기를 보라 내가 크게 되고 지혜를 더 많이 얻었으므로 나보다 먼저 예루살렘에 있던 모든 사람들보다 낫다 하였나니 내 마음이 지혜와 지식을 많이 만나 보았음이로다'),
    (17394, '<학대, 수고 , 동무> 내가 다시 해 아래에서 행하는 모든 학대를 살펴 보았도다 보라 학대 받는 자들의 눈물이로다 그들에게 위로자가 없도다 그들을 학대하는 자들의 손에는 권세가 있으나 그들에게는 위로자가 없도다'),
    (17397, '○내가 또 본즉 사람이 모든 수고와 모든 재주로 말미암아 이웃에게 시기를 받으니 이것도 헛되어 바람을 잡는 것이로다'),
    (17400, '○내가 또 다시 해 아래에서 헛된 것을 보았도다'),
    (17401, '어떤 사람은 아들도 없고 형제도 없이 홀로 있으나 그의 모든 수고에는 끝이 없도다 또 비록 그의 눈은 부요를 족하게 여기지 아니하면서 이르기를 내가 누구를 위하여는 이같이 수고하고 나를 위하여는 행복을 누리지 못하게 하는가 하여도 이것도 헛되어 불행한 노고로다'),
    (17406, '<가난하게 태어나서 왕이 되어도> ○가난하여도 지혜로운 젊은이가 늙고 둔하여 경고를 더 받을 줄 모르는 왕보다 나으니'),
    (17348, '내가 내 마음으로 깊이 생각하기를 내가 어떻게 하여야 내 마음을 지혜로 다스리면서 술로 내 육신을 즐겁게 할까 또 내가 어떻게 하여야 천하의 인생들이 그들의 인생을 살아가는 동안 어떤 것이 선한 일인지를 알아볼 때까지 내 어리석음을 꼭 붙잡아 둘까 하여'),
    (17355, '무엇이든지 내 눈이 원하는 것을 내가 금하지 아니하며 무엇이든지 내 마음이 즐거워하는 것을 내가 막지 아니하였으니 이는 나의 모든 수고를 내 마음이 기뻐하였음이라 이것이 나의 모든 수고로 말미암아 얻은 몫이로다'),
    (17357, '<지혜자나 우매자나> ○내가 돌이켜 지혜와 망령됨과 어리석음을 보았나니 왕 뒤에 오는 자는 무슨 일을 행할까 이미 행한 지 오래 전의 일일 뿐이리라'),
    (17363, '<수고도 헛되다> ○내가 해 아래에서 내가 한 모든 수고를 미워하였노니 이는 내 뒤를 이을 이에게 남겨 주게 됨이라'),
    (17369, '○사람이 먹고 마시며 수고하는 것보다 그의 마음을 더 기쁘게 하는 것은 없나니 내가 이것도 본즉 하나님의 손에서 나오는 것이로다'),
    (17371, '하나님은 그가 기뻐하시는 자에게는 지혜와 지식과 희락을 주시나 죄인에게는 노고를 주시고 그가 모아 쌓게 하사 하나님을 기뻐하는 자에게 그가 주게 하시지만 이것도 헛되어 바람을 잡는 것이로다'),
    (17430, '<재물과 부요와 존귀도 헛되다> 내가 해 아래에서 한 가지 불행한 일이 있는 것을 보았나니 이는 사람의 마음을 무겁게 하는 것이라'),
    (17431, '어떤 사람은 그의 영혼이 바라는 모든 소원에 부족함이 없어 재물과 부요와 존귀를 하나님께 받았으나 하나님께서 그가 그것을 누리도록 허락하지 아니하셨으므로 다른 사람이 누리나니 이것도 헛되어 악한 병이로다'),
    (17436, '○사람의 수고는 다 자기의 입을 위함이나 그 식욕은 채울 수 없느니라'),
    (17439, '○이미 있는 것은 무엇이든지 오래 전부터 그의 이름이 이미 불린 바 되었으며 사람이 무엇인지도 이미 안 바 되었나니 자기보다 강한 자와는 능히 다툴 수 없느니라'),
    (17415, '네 입으로 네 육체가 범죄하게 하지 말라 사자 앞에서 내가 서원한 것이 실수라고 말하지 말라 어찌 하나님께서 네 목소리로 말미암아 진노하사 네 손으로 한 것을 멸하시게 하랴'),
    (17417, '○너는 어느 지방에서든지 빈민을 학대하는 것과 정의와 공의를 짓밟는 것을 볼지라도 그것을 이상히 여기지 말라 높은 자는 더 높은 자가 감찰하고 또 그들보다 더 높은 자들도 있음이니라'),
    (17419, '<재물과 부요와 존귀도 헛되다> ○은을 사랑하는 자는 은으로 만족하지 못하고 풍요를 사랑하는 자는 소득으로 만족하지 아니하나니 이것도 헛되도다'),
    (17422, '○내가 해 아래에서 큰 폐단 되는 일이 있는 것을 보았나니 곧 소유주가 재물을 자기에게 해가 되도록 소유하는 것이라'),
    (17427, '○사람이 하나님께서 그에게 주신 바 그 일평생에 먹고 마시며 해 아래에서 하는 모든 수고 중에서 낙을 보는 것이 선하고 아름다움을 내가 보았나니 그것이 그의 몫이로다'),
    (17471, '<지혜자와 우매한 자> 누가 지혜자와 같으며 누가 사물의 이치를 아는 자이냐 사람의 지혜는 그의 얼굴에 광채가 나게 하나니 그의 얼굴의 사나운 것이 변하느니라'),
    (17479, '<악인들과 의인들> ○내가 이 모든 것들을 보고 해 아래에서 행하는 모든 일을 마음에 두고 살핀즉 사람이 사람을 주장하여 해롭게 하는 때가 있도다'),
    (17484, '○세상에서 행해지는 헛된 일이 있나니 곧 악인들의 행위에 따라 벌을 받는 의인들도 있고 의인들의 행위에 따라 상을 받는 악인들도 있다는 것이라 내가 이르노니 이것도 헛되도다'),
    (17485, '이에 내가 희락을 찬양하노니 이는 사람이 먹고 마시고 즐거워하는 것보다 더 나은 것이 해 아래에는 없음이라 하나님이 사람을 해 아래에서 살게 하신 날 동안 수고하는 일 중에 그러한 일이 그와 함께 있을 것이니라'),
    (17486, '○내가 마음을 다하여 지혜를 알고자 하며 세상에서 행해지는 일을 보았는데 밤낮으로 자지 못하는 자도 있도다'),
    (17487, '또 내가 하나님의 모든 행사를 살펴 보니 해 아래에서 행해지는 일을 사람이 능히 알아낼 수 없도다 사람이 아무리 애써 알아보려고 할지라도 능히 알지 못하나니 비록 지혜자가 아노라 할지라도 능히 알아내지 못하리로다'),
    (17446, '○지혜로운 사람의 책망을 듣는 것이 우매한 자들의 노래를 듣는 것보다 나으니라'),
    (17449, '○일의 끝이 시작보다 낫고 참는 마음이 교만한 마음보다 나으니'),
    (17452, '○지혜는 유산 같이 아름답고 햇빛을 보는 자에게 유익이 되도다'),
    (17456, '○내 허무한 날을 사는 동안 내가 그 모든 일을 살펴 보았더니 자기의 의로움에도 불구하고 멸망하는 의인이 있고 자기의 악행에도 불구하고 장수하는 악인이 있으니'),
    (17460, '○지혜가 지혜자를 성읍 가운데에 있는 열 명의 권력자들보다 더 능력이 있게 하느니라'),
    (17464, '○내가 이 모든 것을 지혜로 시험하며 스스로 이르기를 내가 지혜자가 되리라 하였으나 지혜가 나를 멀리 하였도다'),
    (17534, '<젊은이에게 주는 교훈> ○청년이여 네 어린 때를 즐거워하며 네 청년의 날들을 마음에 기뻐하여 마음에 원하는 길들과 네 눈이 보는 대로 행하라 그러나 하나님이 이 모든 일로 말미암아 너를 심판하실 줄 알라'),
    (17488, '<모두 다 하나님의 손 안에 있다> 이 모든 것을 내가 마음에 두고 이 모든 것을 살펴 본즉 의인들이나 지혜자들이나 그들의 행위나 모두 다 하나님의 손 안에 있으니 사랑을 받을는지 미움을 받을는지 사람이 알지 못하는 것은 모두 그들의 미래의 일들임이니라'),
    (17489, '○모든 사람에게 임하는 그 모든 것이 일반이라 의인과 악인, 선한 자와 깨끗한 자와 깨끗하지 아니한 자, 제사를 드리는 자와 제사를 드리지 아니하는 자에게 일어나는 일들이 모두 일반이니 선인과 죄인, 맹세하는 자와 맹세하기를 무서워하는 자가 일반이로다'),
    (17490, '모든 사람의 결국은 일반이라 이것은 해 아래에서 행해지는 모든 일 중의 악한 것이니 곧 인생의 마음에는 악이 가득하여 그들의 평생에 미친 마음을 품고 있다가 후에는 죽은 자들에게로 돌아가는 것이라'),
    (17494, '○너는 가서 기쁨으로 네 음식물을 먹고 즐거운 마음으로 네 포도주를 마실지어다 이는 하나님이 네가 하는 일들을 벌써 기쁘게 받으셨음이니라'),
    (17498, '○내가 다시 해 아래에서 보니 빠른 경주자들이라고 선착하는 것이 아니며 용사들이라고 전쟁에 승리하는 것이 아니며 지혜자들이라고 음식물을 얻는 것도 아니며 명철자들이라고 재물을 얻는 것도 아니며 지식인들이라고 은총을 입는 것이 아니니 이는 시기와 기회는 그들 모두에게 임함이니라'),
    (17500, '<지혜를 보고 크게 여긴 것> ○내가 또 해 아래에서 지혜를 보고 내가 크게 여긴 것이 이러하니'),
    (17504, '○조용히 들리는 지혜자들의 말들이 우매한 자들을 다스리는 자의 호령보다 나으니라'),
    (17506, '<지혜를 보고 크게 여긴 것> 죽은 파리들이 향기름을 악취가 나게 만드는 것 같이 적은 우매가 지혜와 존귀를 난처하게 만드느니라'),
    (17510, '○내가 해 아래에서 한 가지 재난을 보았노니 곧 주권자에게서 나오는 허물이라'),
    (17513, '○함정을 파는 자는 거기에 빠질 것이요 담을 허는 자는 뱀에게 물리리라'),
    (17517, '○지혜자의 입의 말들은 은혜로우나 우매자의 입술들은 자기를 삼키나니'),
    (17521, '○왕은 어리고 대신들은 아침부터 잔치하는 나라여 네게 화가 있도다'),
    (17551, '○내게 입맞추기를 원하니 네 사랑이 포도주보다 나음이로구나'),
    (17553, '왕이 나를 그의 방으로 이끌어 들이시니 너는 나를 인도하라 우리가 너를 따라 달려가리라 우리가 너로 말미암아 기뻐하며 즐거워하니 네 사랑이 포도주보다 더 진함이라 처녀들이 너를 사랑함이 마땅하니라'),
    (17554, '○예루살렘 딸들아 내가 비록 검으나 아름다우니 게달의 장막 같을지라도 솔로몬의 휘장과도 같구나'),
    (17557, '○여인 중에 어여쁜 자야 네가 알지 못하겠거든 양 떼의 발자취를 따라 목자들의 장막 곁에서 너의 염소 새끼를 먹일지니라'),
    (17558, '○내 사랑아 내가 너를 바로의 병거의 준마에 비하였구나'),
    (17561, '○왕이 침상에 앉았을 때에 나의 나도 기름이 향기를 뿜어냈구나'),
    (17564, '○내 사랑아 너는 어여쁘고 어여쁘다 네 눈이 비둘기 같구나'),
    (17565, '○나의 사랑하는 자야 너는 어여쁘고 화창하다 우리의 침상은 푸르고'),
    (17536, '<젊은이에게 주는 교훈> 너는 청년의 때에 너의 창조주를 기억하라 곧 곤고한 날이 이르기 전에, 나는 아무 낙이 없다고 할 해들이 가깝기 전에'),
    (17540, '또한 그런 자들은 높은 곳을 두려워할 것이며 길에서는 놀랄 것이며 살구나무가 꽃이 필 것이며 메뚜기도 짐이 될 것이며 정욕이 그치리니 이는 사람이 자기의 영원한 집으로 돌아가고 조문객들이 거리로 왕래하게 됨이니라'),
    (17544, '<사람의 본분> ○전도자는 지혜자이어서 여전히 백성에게 지식을 가르쳤고 또 깊이 생각하고 연구하여 잠언을 많이 지었으며'),
    (17546, '○지혜자들의 말씀들은 찌르는 채찍들 같고 회중의 스승들의 말씀들은 잘 박힌 못 같으니 다 한 목자가 주신 바이니라'),
    (17548, '○일의 결국을 다 들었으니 하나님을 경외하고 그의 명령들을 지킬지어다 이것이 모든 사람의 본분이니라'),
    (17568, '○여자들 중에 내 사랑은 가시나무 가운데 백합화 같도다'),
    (17569, '○남자들 중에 나의 사랑하는 자는 수풀 가운데 사과나무 같구나 내가 그 그늘에 앉아서 심히 기뻐하였고 그 열매는 내 입에 달았도다'),
    (17574, '○내 사랑하는 자의 목소리로구나 보라 그가 산에서 달리고 작은 산을 빨리 넘어오는구나'),
    (17576, '○나의 사랑하는 자가 내게 말하여 이르기를 나의 사랑, 내 어여쁜 자야 일어나서 함께 가자'),
    (17581, '○우리를 위하여 여우 곧 포도원을 허는 작은 여우를 잡으라 우리의 포도원에 꽃이 피었음이라'),
    (17600, '○날이 저물고 그림자가 사라지기 전에 내가 몰약 산과 유향의 작은 산으로 가리라'),
    (17601, '○나의 사랑 너는 어여쁘고 아무 흠이 없구나'),
    (17610, '○북풍아 일어나라 남풍아 오라 나의 동산에 불어서 향기를 날리라 나의 사랑하는 자가 그 동산에 들어가서 그 아름다운 열매 먹기를 원하노라'),
    (17588, '○예루살렘 딸들아 내가 노루와 들사슴을 두고 너희에게 부탁한다 사랑하는 자가 원하기 전에는 흔들지 말고 깨우지 말지니라'),
    (17589, '○몰약과 유향과 상인의 여러 가지 향품으로 향내 풍기며 연기 기둥처럼 거친 들에서 오는 자가 누구인가'),
    (17628, '○내 사랑하는 자가 자기 동산으로 내려가 향기로운 꽃밭에 이르러서 동산 가운데에서 양 떼를 먹이며 백합화를 꺾는구나'),
    (17630, '○내 사랑아 너는 디르사 같이 어여쁘고, 예루살렘 같이 곱고, 깃발을 세운 군대 같이 당당하구나'),
    (17636, '○아침 빛 같이 뚜렷하고 달 같이 아름답고 해 같이 맑고 깃발을 세운 군대 같이 당당한 여자가 누구인가'),
    (17637, '○골짜기의 푸른 초목을 보려고 포도나무가 순이 났는가 석류나무가 꽃이 피었는가 알려고 내가 호도 동산으로 내려갔을 때에'),
    (17639, '○돌아오고 돌아오라 술람미 여자야 돌아오고 돌아오라 우리가 너를 보게 하라 ○너희가 어찌하여 마하나임에서 춤추는 것을 보는 것처럼 술람미 여자를 보려느냐'),
    (17648, '네 입은 좋은 포도주 같을 것이니라 ○이 포도주는 내 사랑하는 자를 위하여 미끄럽게 흘러내려서 자는 자의 입을 움직이게 하느니라'),
    (17650, '○나는 내 사랑하는 자에게 속하였도다 그가 나를 사모하는구나'),
    (17658, '○그의 사랑하는 자를 의지하고 거친 들에서 올라오는 여자가 누구인가 ○너로 말미암아 네 어머니가 고생한 곳 너를 낳은 자가 애쓴 그 곳 사과나무 아래에서 내가 너를 깨웠노라'),
    (17660, '○너는 나를 도장 같이 마음에 품고 도장 같이 팔에 두라 사랑은 죽음 같이 강하고 질투는 스올 같이 잔인하며 불길 같이 일어나니 그 기세가 여호와의 불과 같으니라'),
    (17662, '○우리에게 있는 작은 누이는 아직도 유방이 없구나 그가 청혼을 받는 날에는 우리가 그를 위하여 무엇을 할까'),
    (17664, '○나는 성벽이요 내 유방은 망대 같으니 그러므로 나는 그가 보기에 화평을 얻은 자 같구나'),
    (17667, '○너 동산에 거주하는 자야 친구들이 네 소리에 귀를 기울이니 내가 듣게 하려무나'),
    (17668, '○내 사랑하는 자야 너는 빨리 달리라 향기로운 산 위에 있는 노루와도 같고 어린 사슴과도 같아라'),
    (17611, '내 누이, 내 신부야 내가 내 동산에 들어와서 나의 몰약과 향 재료를 거두고 나의 꿀송이와 꿀을 먹고 내 포도주와 내 우유를 마셨으니 나의 친구들아 먹으라 나의 사랑하는 사람들아 많이 마시라'),
    (17612, '○내가 잘지라도 마음은 깨었는데 나의 사랑하는 자의 소리가 들리는구나 문을 두드려 이르기를 나의 누이, 나의 사랑, 나의 비둘기, 나의 완전한 자야 문을 열어 다오 내 머리에는 이슬이, 내 머리털에는 밤이슬이 가득하였다 하는구나'),
    (17619, '○여자들 가운데에 어여쁜 자야 너의 사랑하는 자가 남의 사랑하는 자보다 나은 것이 무엇인가 너의 사랑하는 자가 남의 사랑하는 자보다 나은 것이 무엇이기에 이같이 우리에게 부탁하는가'),
    (17620, '○내 사랑하는 자는 희고도 붉어 많은 사람 가운데에 뛰어나구나'),
    (17702, '많은 백성이 가며 이르기를 오라 우리가 여호와의 산에 오르며 야곱의 하나님의 전에 이르자 그가 그의 길을 우리에게 가르치실 것이라 우리가 그 길로 행하리라 하리니 이는 율법이 시온에서부터 나올 것이요 여호와의 말씀이 예루살렘에서부터 나올 것임이니라'),
    (17703, '그가 열방 사이에 판단하시며 많은 백성을 판결하시리니 무리가 그들의 칼을 쳐서 보습을 만들고 그들의 창을 쳐서 낫을 만들 것이며 이 나라와 저 나라가 다시는 칼을 들고 서로 치지 아니하며 다시는 전쟁을 연습하지 아니하리라'),
    (17760, '무릇 만군의 여호와의 포도원은 이스라엘 족속이요 그가 기뻐하시는 나무는 유다 사람이라 그들에게 정의를 바라셨더니 도리어 포학이요 그들에게 공의를 바라셨더니 도리어 부르짖음이었도다'),
    (17764, '아침에 일찌기 일어나 독주를 마시며 밤이 깊도록 포도주에 취하는 자들은 화 있을진저'),
    (17771, '거짓으로 끈을 삼아 죄악을 끌며 수레줄로 함 같이 죄악을 끄는 자는 화 있을진저'),
    (17777, '이로 말미암아 불꽃이 그루터기를 삼킴 같이, 마른 풀이 불 속에 떨어짐 같이 그들의 뿌리가 썩겠고 꽃이 티끌처럼 날리리니 그들이 만군의 여호와의 율법을 버리며 이스라엘의 거룩하신 이의 말씀을 멸시하였음이라'),
    (17778, '그러므로 여호와께서 자기 백성에게 노를 발하시고 그들 위에 손을 들어 그들을 치신지라 산들은 진동하며 그들의 시체는 거리 가운데 분토 같이 되었도다 그럴지라도 그의 노가 돌아서지 아니하였고 그의 손이 여전히 펼쳐져 있느니라'),
    (17795, '여호와께서 사람들을 멀리 옮기셔서 이 땅 가운데 황폐한 곳이 많을 때까지니라'),
    (17797, '<아하스 왕에게 삼가며 조용하라 하시다> 웃시야의 손자요 요담의 아들인 유다의 아하스 왕 때에 아람의 르신왕과 르말리야의 아들 이스라엘의 베가 왕이 올라와서 예루살렘을 쳤으나 능히 이기지 못하니라'),
    (17798, '어떤 사람이 다윗 집에 알려 이르되 아람이 에브라임과 동맹하였다 하였으므로 왕의 마음과 그의 백성의 마음이 숲이 바람에 흔들림 같이 흔들렸더라'),
    (17804, '대저 아람의 머리는 다메섹이요 다메섹의 머리는 르신이며 육십오 년 내에 에브라임이 패망하여 다시는 나라를 이루지 못할 것이며'),
    (17809, '이사야가 이르되 다윗의 집이여 원하건대 들을지어다 너희가 사람을 괴롭히고서 그것을 작은 일로 여겨 또 나의 하나님을 괴롭히려 하려느냐'),
    (17810, '그러므로 주께서 친히 징조를 너희에게 주실 것이라 보라 처녀가 잉태하여 아들을 낳을 것이요 그 이름을 임마누엘이라 하리라'),
    (17811, '그가 악을 버리며 선을 택할 줄 알 때가 되면 엉긴 젖과 꿀을 먹을 것이라'),
    (17812, '대저 이 아기가 악을 버리며 선을 택할 줄 알기 전에 네가 미워하는 두 왕의 땅이 황폐하게 되리라'),
    (17818, '그것들이 내는 젖이 많으므로 엉긴 젖을 먹을 것이라 그 땅 가운데 남아 있는 자는 엉긴 젖과 꿀을 먹으리라'),
    (17819, '그 날에는 천 그루에 은 천 개의 가치가 있는 포도나무 있던 곳마다 찔레와 가시가 날 것이라'),
    (17825, '이는 이 아기가 내 아빠, 내 엄마라 부를 줄 알기 전에 다메섹의 재물과 사마리아의 노략물이 앗수르 왕 앞에 옮겨질 것임이라 하시니라'),
    (17830, '<여호와께서 깨우치시다> 너희 민족들아 함성을 질러 보아라 그러나 끝내 패망하리라 너희 먼 나라 백성들아 들을지니라 너희 허리를 동이라 그러나 끝내 패망하리라 너희 허리에 띠를 띠라 그러나 끝내 패망하리라'),
    (17844, '<평강의 왕> 전에 고통 받던 자들에게는 흑암이 없으리로다 옛적에는 여호와께서 스불론 땅과 납달리 땅이 멸시를 당하게 하셨더니 후에는 해변 길과 요단 저쪽 이방의 갈릴리를 영화롭게 하셨느니라'),
    (17849, '이는 한 아기가 우리에게 났고 한 아들을 우리에게 주신 바 되었는데 그의 어깨에는 정사를 메었고 그의 이름은 기묘자라, 모사라, 전능하신 하나님이라, 영존하시는 아버지라, 평강의 왕이라 할 것임이라'),
    (17850, '그 정사와 평강의 더함이 무궁하며 또 다윗의 왕좌와 그의 나라에 군림하여 그 나라를 굳게 세우고 지금 이후로 영원히 정의와 공의로 그것을 보존하실 것이라 만군의 여호와의 열심이 이를 이루시리라'),
    (17860, '이 백성이 모두 경건하지 아니하며 악을 행하며 모든 입으로 망령되이 말하니 그러므로 주께서 그들의 장정들을 기뻐하지 아니하시며 그들의 고아와 과부를 긍휼히 여기지 아니하시리라 그럴지라도 여호와의 진노가 돌아서지 아니하며 그의 손이 여전히 펴져 있으리라'),
    (17878, '내 손으로 열국의 재물을 얻은 것은 새의 보금자리를 얻음 같고 온 세계를 얻은 것은 내버린 알을 주움 같았으나 날개를 치거나 입을 벌리거나 지저귀는 것이 하나도 없었다 하는도다'),
    (17888, '<주께서 앗수르를 멸하시리라> 그러므로 주 만군의 여호와께서 이르시되 시온에 거주하는 내 백성들아 앗수르가 애굽이 한 것 처럼 막대기로 너를 때리며 몽둥이를 들어 너를 칠지라도 그를 두려워하지 말라'),
    (17890, '만군의 여호와께서 채찍을 들어 그를 치시되 오렙 바위에서 미디안 사람을 쳐죽이신 것 같이 하실 것이며 막대기를 드시되 바다를 향하여 애굽에서 하신 것 같이 하실 것이라'),
    (17926, '너희는 애곡할지어다 여호와의 날이 가까왔으니 전능자에게서 멸망이 임할 것임이로다'),
    (17928, '그들이 놀라며 괴로움과 슬픔에 사로잡혀 해산이 임박한 여자 같이 고통하며 서로 보고 놀라며 얼굴은 불꽃 같으리로다'),
    (17930, '하늘의 별들과 별 무리가 그 빛을 내지 아니하며 해가 돋아도 어두우며 달이 그 빛을 비추이지 아니할 것이로다'),
    (17936, '그들의 어린아이들은 그들의 목전에서 메어침을 당하겠고 그들의 집은 노략을 당하겠고 그들의 아내는 욕을 당하리라'),
    (17939, '열국의 영광이요 갈대아 사람의 자랑하는 노리개가 된 바벨론이 하나님께 멸망당한 소돔과 고모라 같이 되리니'),
    (17975, '<여호와께서 모압을 황폐하게 하시리라> 모압에 관한 경고라 하룻 밤에 모압 알이 망하여 황폐할 것이며 하루 밤에 모압 기르가 망하여 황폐할 것이라'),
    (17977, '그들은 바잇과 디본 산당에 올라가서 울며 모압은 느보와 메드바를 위하여 통곡하는도다 그들이 각각 머리카락을 밀고 각각 수염을 깎았으며'),
    (17961, '오직 너는 자기 무덤에서 내쫓겼으니 가증한 나무가지 같고 칼에 찔려 돌구덩이에 떨어진 주검들에 둘러싸였으니 밟힌 시체와 같도다'),
    (17970, '<여호와께서 블레셋을 소멸시키시리라> 아하스 왕이 죽던 해에 이 경고가 임하니라'),
    (18015, '갈대 배를 물에 띄우고 그 사자를 수로로 보내며 이르기를 민첩한 사절들아 너희는 강들이 흘러 나누인 나라로 가되 장대하고 준수한 백성 곧 시초부터 두려움이 되며 강성하여 대적을 밟는 백성에게로 가라 하는도다'),
    (18020, '그 때에 강들이 흘러 나누인 나라의 장대하고 준수한 백성 곧 시초부터 두려움이 되며 강성하여 대적을 밟는 백성이 만군의 여호와께 드릴 예물을 가지고 만군의 여호와의 이름을 두신 곳 시온 산에 이르리라'),
    (17999, '<여호와께서 에브라임과 다메섹을 멸하시리라> 다메섹에 관한 경고라 보라 다메섹이 장차 성읍을 이루지 못하고 무너진 무더기가 될 것이라'),
    (18005, '그러나 그 안에 주울 것이 남으리니 감람나무를 흔들 때에 가장 높은 가지 꼭대기에 과일 두세 개가 남음 같겠고 무성한 나무의 가장 먼 가지에 네다섯 개가 남음 같으리라 이스라엘의 하나님 여호와의 말씀이니라'),
    (18021, '<여호와께서 애굽에 임하시리라> 애굽에 관한 경고라 보라 여호와께서 빠른 구름을 타고 애굽에 임하시리니 애굽의 우상들이 그 앞에서 떨겠고 애굽인의 마음이 그 속에서 녹으리로다'),
    (18025, '내가 애굽인을 잔인한 주인의 손에 붙이리니 포학한 왕이 그들을 다스리리라 주 만군의 여호와의 말씀이니라'),
    (18041, '이것이 애굽 땅에서 만군의 여호와를 위하여 징조와 증거가 되리니 이는 그들이 그 압박하는 자들로 말미암아 여호와께 부르짖겠고 여호와께서는 그들에게 한 구원자이자 보호자를 보내사 그들을 건지실 것임이라'),
    (18053, '<바벨론 멸망에 관한 묵시> 해변 광야에 관한 경고라 적병이 광야에서, 두려운 땅에서 네겝 회오리바람 같이 몰려왔도다'),
    (18064, '<두마에 관한 경고> 두마에 관한 경고라 사람이 세일에서 나를 부르되 파수꾼이여 밤이 어떻게 되었느냐 파수꾼이여 밤이 어떻게 되었느냐'),
    (18067, '<아라비아에 관한 경고> 아라비아에 관한 경고라 드단 대상들이여 너희가 아라비아 수풀에서 유숙하리라'),
    (18069, '데마 땅의 주민들아 물을 가져다가 목마른 자에게 주고 떡을 가지고 도피하는 자를 영접하라'),
    (18141, '<찬송> 여호와여 주는 나의 하나님이시라 내가 주를 높이고 주의 이름을 찬송하오리니 주는 기사를 옛적의 정하신 뜻대로 성실함과 진실함으로 행하셨음이라'),
    (18142, '주께서 성읍을 돌 무더기로 만드시며 견고한 성읍을 황폐하게 하시며 외인의 궁성을 성읍이 되지 못하게 하사 영원히 건설되지 못하게 하셨으므로'),
    (18144, '주는 포학자의 기세가 성벽을 치는 폭풍과 같을 때에 빈궁한 자의 요새이시며 환난당한 가난한 자의 요새이시며 폭풍 중의 피난처시며 폭양을 피하는 그늘이 되셨사오니'),
    (18146, '<여호와께서 연회를 베푸시리라> 만군의 여호와께서 이 산에서 만민을 위하여 기름진 것과 오래 저장하였던 포도주로 연회를 베푸시리니 곧 골수가 가득한 기름진 것과 오래 저장하였던 맑은 포도주로 하실 것이며'),
    (18149, '<여호와께서 모압을 벌하시리라> 그 날에 말하기를 이는 우리의 하나님이시라 우리가 그를 기다렸으니 그가 우리를 구원하시리로다 이는 여호와시라 우리가 그를 기다렸으니 우리는 그의 구원을 기뻐하며 즐거워하리라 할 것이며'),
    (18150, '여호와의 손이 이 산에 나타나시리니 모압이 거름물 속의 초개가 밟힘 같이 자기 처소에서 밟힐 것인즉'),
    (18099, '<다시스에 관한 경고> 두로에 관한 경고라 다시스의 배들아 너희는 슬피 부르짖을지어다 두로가 황무하여 집이 없고 들어갈 곳도 없음이요 이 소식이 깃딤 땅에서부터 그들에게 전파되었음이라'),
    (18103, '시돈이여 너는 부끄러워할지어다 대저 바다 곧 바다의 요새가 말하기를 나는 산고를 겪지 못하였으며 출산하지 못하였으며 청년들을 양육하지도 못하였으며 처녀들을 생육하지도 못하였다 하였음이라'),
    (18111, '이르시되 너 학대받은 처녀 딸 시돈아 네게 다시는 희락이 없으리니 일어나 깃딤으로 건너가라 거기에서도 네가 평안을 얻지 못하리라 하셨느니라'),
    (18157, '높은 데 거주하는 자를 낮추시며 솟은 성을 헐어 땅에 엎으시되 진토에 미치게 하셨도다'),
    (18171, '주의 죽은 자들은 살아나고 그들의 시체들은 일어나리이다 티끌에 누운 자들아 너희는 깨어 노래하라 주의 이슬은 빛난 이슬이니 땅이 죽은 자들을 내어 놓으리로다'),
    (18173, '보라 여호와께서 그의 처소에서 나오사 땅의 거민의 죄악을 벌하실 것이라 땅이 그 위에 잦았던 피를 드러내고 그 살해당한 자를 다시는 덮지 아니하리라'),
    (18073, '<환상의 골짜기에 관한 경고> 환상의 골짜기에 관한 경고라 네가 지붕에 올라감은 어찌함인고'),
    (18085, '그 날에 주 만군의 여호와께서 명령하사 통곡하며 애곡하며 머리털을 뜯으며 굵은 베를 띠라 하셨거늘'),
    (18088, '<셉나에게 경고하시다> 주 만군의 여호와께서 이르시되 너는 가서 그 국고를 맡고 왕궁을 맡은 자 셉나를 보고 이르기를'),
    (18089, '네가 여기와 무슨 관계가 있느냐 여기에 누가 있기에 여기서 너를 위하여 묘실을 팠느냐 높은 곳에 자기를 위하여 묘실을 팠고 반석에 자기를 위하여 처소를 쪼아 내었도다'),
    (18094, '네 옷을 그에게 입히며 네 띠를 그에게 띠워 힘있게 하고 네 정권을 그의 손에 맡기리니 그가 예루살렘 주민과 유다의 집의 아버지가 될 것이며'),
    (18097, '그의 아버지 집의 모든 영광이 그 위에 걸리리니 그의 후손과 족속 되는 각 작은 그릇 곧 종지로부터 모든 항아리까지니라'),
    (18098, '만군의 여호와께서 이르시되 그 날에는 단단한 곳에 박혔던 못이 삭으리니 그의 못이 부러져 떨어지므로 그 위에 걸린 물건이 부서지리라 하셨다 하라 나 여호와의 말이니라'),
    (18118, '<여호와께서 땅을 벌하시리라> 보라 여호와께서 땅을 공허하게 하시며 황폐하게 하시며 지면을 뒤집어 엎으시고 그 주민을 흩으시리니'),
    (18119, '백성과 제사장이 같을 것이며 종과 상전이 같을 것이며 여종과 여주인이 같을 것이며 사는 자와 파는 자가 같을 것이며 빌려주는 자와 빌리는 자가 같을 것이며 이자를 받는 자와 이자를 내는 자가 같을 것이라'),
    (18127, '약탈을 당한 성읍이 허물어 지고 집마다 닫혀서 들어가는 자가 없으며'),
    (18133, '땅 끝에서부터 노래하는 소리가 우리에게 들리기를 의로우신 이에게 영광을 돌리세 하도다 그러나 나는 이르기를 나는 쇠잔하였고 나는 쇠잔하였으니 내게 화가 있도다 배신자들은 배신 하고 배신자들이 크게 배신하였도다'),
    (18139, '그들이 죄수가 깊은 옥에 모임 같이 모이게 되고 옥에 갇혔다가 여러 날 후에 형벌을 받을 것이니라'),
    (18180, '주께서 그의 백성을 치셨던들 그의 백성을 친 자들을 치심과 같았겠으며 백성이 죽임을 당하였던들 백성을 죽인 자가 죽임을 당함과 같았겠느냐'),
    (18182, '야곱의 불의가 속함을 얻으며 그의 죄 없이함을 받을 결과는 이로 말미암나니 곧 그가 제단의 모든 돌을 부숴진 횟돌 같게 하며 아세라와 태양상이 다시 서지 못하게 함에 있는 것이라'),
    (18187, '<에브라임의 면류관이 밟히리라> 에브라임의 술취한 자들의 교만한 면류관은 화 있을진저 술에 빠진 자의 성 곧 영화로운 관 같이 기름진 골짜기 꼭대기에 세운 성이여 쇠잔해 가는 꽃 같으니 화 있을진저'),
    (18188, '보라 주께 있는 강하고 힘있는 자가 쏟아지는 우박 같이, 파괴하는 광풍 같이, 큰 물이 넘침 같이 손으로 그 면류관을 땅에 던지리니'),
    (18193, '그리하여도 이들은 포도주로 말미암아 옆걸음 치며 독주로 말미암아 비틀거리며 제사장과 선지자도 독주로 말미암아 옆걸음 치며 포도주에 빠지며 독주로 말미암아 비틀거리며 환상을 잘못 풀며 재판할 때에 실수하나니'),
    (18199, '여호와께서 그들에게 말씀하시되 경계에 경계를 더하며 경계에 경계를 더하며 교훈에 교훈을 더하며 교훈에 교훈을 더하고 여기서도 조금, 저기서도 조금 하사 그들이 가다가 뒤로 넘어져 부러지며 걸리며 붙잡히게 하시리라'),
    (18201, '너희가 말하기를 우리는 사망과 언약하였고 스올과 맹약하였은즉 넘치는 재앙이 밀려올지라도 우리에게 미치지 못하리니 우리는 거짓을 우리의 피난처로 삼았고 허위 아래에 우리를 숨겼음이라 하는도다'),
    (18207, '대저 여호와께서 브라심 산에서와 같이 일어나시며 기브온 골짜기에서와 같이 진노하사 자기의 일을 행하시리니 그의 일이 비상할 것이며 자기의 사역을 이루시리니 그의 사역이 기이할 것임이라'),
    (18214, '곡식은 부수는가, 아니라 늘 떨기만 하지 아니하고 그것에 수레 바퀴를 굴리고 그것을 말굽으로 밟게 할지라도 부수지는 아니하나니'),
    (18302, '모든 물가에 씨를 뿌리고 소와 나귀를 그리로 모는 너희는 복이 있느니라'),
    (18240, '<애굽과 맺은 맹약이 헛되다> 여호와께서 이르시되 패역한 자식들은 화 있을진저 그들이 계교를 베푸나 나로 말미암지 아니하며 맹약을 맺으나 나의 영으로 말미암지 아니하고 죄에 죄를 더하도다'),
    (18245, '네겝 짐승들에 관한 경고라 사신들이 그들의 재물을 어린 나귀 등에 싣고 그들의 보물을 낙타 안장에 얹고 암사자와 수사자와 독사와 및 날아다니는 불뱀이 나오는 위험하고 곤고한 땅을 지나 자기에게 무익한 민족에게로 갔으나'),
    (18257, '한 사람이 꾸짖은즉 천 사람이 도망하겠고 다섯이 꾸짖은즉 너희가 다 도망하고 너희 남은 자는 겨우 산 꼭대기의 깃대 같겠고 산 마루 위의 기치 같으리라 하셨느니라'),
    (18258, '<하나님을 기다리는 자는 복이 있도다> 그러나 여호와께서 기다리시나니 이는 너희에게 은혜를 베풀려 하심이요 일어나시리니 이는 너희를 긍휼히 여기려 하심이라 대저 여호와는 정의의 하나님이심이라 그를 기다리는 자마다 복이 있도다'),
    (18265, '크게 살륙하는 날 망대가 무너질 때에 고산마다 준령마다 그 위에 개울과 시냇물이 흐를 것이며'),
    (18267, '<여호와께서 앗수르를 치시리라> 보라 여호와의 이름이 원방에서부터 오되 그의 진노가 불붙듯 하며 빽빽한 연기가 일어나듯 하며 그의 입술에는 분노가 찼으며 그의 혀는 맹렬한 불 같으며'),
    (18328, '대저 여호와께서 열방을 향하여 진노하시며 그들의 만군을 향하여 분내사 그들을 진멸하시며 살륙당하게 하셨은즉'),
    (18329, '그 살륙당한 자는 내던진 바 되며 그 사체의 악취가 솟아오르고 그 피에 산들이 녹을 것이며'),
    (18341, '부엉이가 거기에 깃들이고 알을 낳아 까서 그의 그늘에 모으며 솔개들도 각각 제 짝과 함께 거기에 모이리라'),
    (18342, '너희는 여호와의 책에서 찾아 읽어 보라 이것들 가운데서 빠진 것이 하나도 없고 제 짝이 없는 것이 없으리니 이는 여호와의 입이 이를 명령하셨고 그의 영이 이것들을 모으셨음이라'),
    (18343, '여호와께서 그것들을 위하여 제비를 뽑으시며 그의 손으로 줄을 띠어 그 땅을 그것들에게 나눠 주셨으니 그들이 영원히 차지하며 대대로 거기에 살리라'),
    (18274, '도움을 구하러 애굽으로 내려가는 자들은 화 있을진저 그들은 말을 의지하며 병거의 많음과 마병의 심히 강함을 의지하고 이스라엘의 거룩하신 이를 앙모하지 아니하며 여호와를 구하지 아니하나니'),
    (18276, '애굽은 사람이요 신이 아니며 그들의 말들은 육체요 영이 아니라 여호와께서 그의 손을 펴시면 돕는 자도 넘어지며 도움을 받는 자도 엎드러져서 다 함께 멸망하리라'),
    (18277, '여호와께서 이같이 내게 이르시되 큰 사자나 젊은 사자가 자기의 먹이를 움키고 으르렁거릴 때에 그것을 치려고 여러 목자를 불러 왔다 할지라도 그것이 그들의 소리로 말미암아 놀라지 아니할 것이요 그들의 떠듦으로 말미암아 굴복하지 아니할 것이라 이와 같이 나 만군의 여호와가 강림하여 시온 산과 그 언덕에서 싸울 것이라'),
    (18280, '너희가 자기 손으로 만들어 범죄한 은우상, 금우상을 그 날에는 각 사람이 던져 버릴 것이며'),
    (18281, '앗수르는 칼에 엎드러질 것이나 사람의 칼로 말미암음이 아니겠고 칼에 삼켜질 것이나 사람의 칼로 말미암음이 아닐 것이며 그는 칼 앞에서 도망할 것이요 그의 장정들은 복역하는 자가 될 것이라'),
    (18216, '<아리엘을 괴롭게 하리라> 슬프다 아리엘이여 아리엘이여 다윗이 진친 성읍이여 해마다 절기가 돌아오려니와'),
    (18219, '네가 낮아져서 땅에서 말하며 네 말소리가 나직히 티끌에서 날 것이라 네 목소리가 신접한 자의 목소리 같이 땅에서 나며 네 말소리가 티끌에서 지껄이리라'),
    (18226, '그러므로 모든 계시가 너희에게는 봉한 책의 말처럼 되었으니 그것을 글 아는 자에게 주며 이르기를 그대에게 청하노니 이를 읽으라 하면 그가 대답하기를 그것이 봉해졌으니 나는 못 읽겠노라 할 것이요'),
    (18228, '주께서 이르시되 이 백성이 입으로는 나를 가까이하며 입술로는 나를 공경하나 그들의 마음은 내게서 멀리 떠났나니 그들이 나를 경외함은 사람의 계명으로 가르침을 받았을 뿐이라'),
    (18231, '너희의 패역함이 심하도다 토기장이를 어찌 진흙 같이 여기겠느냐 지음을 받은 물건이 어찌 자기를 지은 이에게 대하여 이르기를 그가 나를 짓지 아니하였다 하겠으며 빚음을 받은 물건이 자기를 빚은 이에게 대하여 이르기를 그가 총명이 없다 하겠느냐'),
    (18303, '<은혜를 구하는 기도> 너 학대를 당하지 아니하고도 학대하며 속이고도 속임을 당하지 아니하는 자여 화 있을진저 네가 학대하기를 그치면 네가 학대를 당할 것이며 네가 속이기를 그치면 사람이 너를 속이리라'),
    (18315, '너희 먼 데 있는 자들아 내가 행한 것을 들으라 너희 가까이에 있는 자들아 나의 권능을 알라'),
    (18317, '오직 공의롭게 행하는 자, 정직히 말하는 자, 토색한 재물을 가증히 여기는 자, 손을 흔들어 뇌물을 받지 아니하는 자, 귀를 막아 피 흘리려는 꾀를 듣지 아니하는 자, 눈을 감아 악을 보지 아니하는 자'),
    (18323, '여호와는 거기에 위엄 중에 우리와 함께 계시리니 그 곳에는 여러 강과 큰 호수가 있으나 노젓는 배나 큰 배가 통행하지 못하리라'),
    (18325, '네 돛대의 줄이 풀렸으니 돛대 밑을 튼튼히 하지 못하였고 돛을 달지 못하였느니라 때가 되면 많은 재물을 탈취하여 나누리니 저는 자도 그 재물을 취할 것이며'),
    (18351, '거기에 대로가 있어 그 길을 거룩한 길이라 일컫는 바 되리니 깨끗하지 못한 자는 지나가지 못하겠고 오직 구속함을 입은 자들을 위하여 있게 될 것이라 우매한 행인은 그 길로 다니지 못할 것이며'),
    (18436, '<바벨론에서 온 사자들> 그 때에 발라단의 아들 바벨론 왕 므로닥발라단이 히스기야가 병들었다가 나았다 함을 듣고 히스기야에게 글과 예물을 보낸지라'),
    (18437, '히스기야가 사자들로 말미암아 기뻐하여 그들에게 보물 창고 곧 은금과 향료와 보배로운 기름과 모든 무기고에 있는 것을 다 보여주었으니 히스기야가 궁중의 소유와 전 국내의 소유를 보이지 아니한 것이 없는지라'),
    (18439, '이사야가 이르되 그들이 왕의 궁전에서 무엇을 보았나이까 하니 히스기야가 대답하되 그들이 내 궁전에 있는 것을 다 보았나이다 내 창고에 있는 것으로 보이지 아니한 보물이 하나도 없나이다 하니라'),
    (18354, '<앗수르가 예루살렘을 협박하다> 히스기야 왕 십사 년에 앗수르 왕 산헤립이 올라와서 유다의 모든 견고한 성을 쳐서 취하니라'),
    (18359, '보라 네가 애굽을 믿는도다 그것은 상한 갈대 지팡이와 같은 것이라 사람이 그것을 의지하면 손에 찔리리니 애굽 왕 바로는 그를 믿는 모든 자에게 이와 같으니라'),
    (18360, '혹시 네가 내게 이르기를 우리는 우리 하나님 여호와를 신뢰하노라 하리라마는 그는 그의 산당과 제단을 히스기야가 제하여 버리고 유다와 예루살렘에 명령하기를 너희는 이 제단 앞에서만 예배하라 하던 그 신이 아니냐 하셨느니라'),
    (18364, '이에 엘리아김과 셉나와 요아가 랍사게에게 이르되 우리가 아람 방언을 아오니 청하건대 그 방언으로 당신의 종들에게 말하고 성 위에 있는 백성이 듣는 데에서 우리에게 유다 방언으로 말하지 마소서 하니'),
    (18365, '랍사게가 이르되 내 주께서 이 일을 네 주와 네게만 말하라고 나를 보내신 것이냐 너희와 함께 자기의 대변을 먹으며 자기의 소변을 마실 성 위에 앉은 사람들에게도 하라고 보내신 것이 아니냐 하더라'),
    (18369, '히스기야의 말을 듣지 말라 앗수르 왕이 또 이같이 말씀하시기를 너희는 내게 항복하고 내게로 나아오라 그리하면 너희가 각각 자기의 포도와 자기의 무화과를 먹을 것이며 각각 자기의 우물 물을 마실 것이요'),
    (18476, '누가 동방에서 사람을 일깨워서 공의로 그를 불러 자기 발 앞에 이르게 하였느냐 열국을 그의 앞에 넘겨주며 그가 왕들을 다스리게 하되 그들이 그의 칼에 티끌 같게, 그의 활에 불리는 초개 같게 하매'),
    (18487, '이는 나 여호와 너의 하나님이 네 오른손을 붙들고 네게 이르기를 두려워하지 말라 내가 너를 도우리라 할 것임이니라'),
    (18445, '너희는 예루살렘의 마음에 닿도록 말하며 그것에게 외치라 그 노역의 때가 끝났고 그 죄악이 사함을 받았느니라 그의 모든 죄로 말미암아 여호와의 손에서 벌을 배나 받았느니라 할지니라 하시니라'),
    (18452, '아름다운 소식을 시온에 전하는 자여 너는 높은 산에 오르라 아름다운 소식을 예루살렘에 전하는 자여 너는 힘써 소리를 높이라 두려워하지 말고 소리를 높여 유다의 성읍들에게 이르기를 너희의 하나님을 보라 하라'),
    (18454, '그는 목자같이 양 떼를 먹이시며 어린 양을 그 팔로 모아 품에 안으시며 젖 먹이는 암컷들을 온순히 인도하시리로다'),
    (18462, '우상은 장인이 부어 만들었고 장색이 금으로 입혔고 또 은사슬을 만든 것이니라'),
    (18465, '그는 땅 위 궁창에 앉으시나니 땅에 사는 사람들은 메뚜기 같으니라 그가 하늘을 차일같이 펴셨으며 거주할 천막같이 치셨고'),
    (18469, '너희는 눈을 높이 들어 누가 이 모든 것을 창조하였나 보라 주께서는 수효대로 만상을 이끌어 내시고 그들의 모든 이름을 부르시나니 그의 권세가 크고 그의 능력이 강하므로 하나도 빠짐이 없느니라'),
    (18474, '오직 여호와를 앙망하는 자는 새 힘을 얻으리니 독수리가 날개 치며 올라감 같을 것이요 달음박질하여도 곤비하지 아니하겠고 걸어가도 피곤하지 아니하리로다'),
    (18414, '<히스기야 왕의 발병과 회복> 그 때에 히스기야가 병들어 죽게 되니 아모스의 아들 선지자 이사야가 나아가 그에게 이르되 여호와께서 이같이 말씀하시기를 너는 네 집에 유언하라 네가 죽고 살지 못하리라 하셨나이다 하니'),
    (18424, '내가 또 말하기를 내가 다시는 여호와를 뵈옵지 못하리니 산자의 땅에서 다시는 여호와를 뵈옵지 못하겠고 내가 세상의 거민 중에서 한 사람도 다시는 보지 못하리라 하였도다'),
    (18376, '<왕이 이사야의 말을 듣고자 하다> 히스기야 왕이 듣고 자기의 옷을 찢고 굵은 베옷을 입고 여호와의 전으로 갔고'),
    (18377, '왕궁맡은 자 엘리아김과 서기관 셉나와 제사장 중 어른들도 굵은 베옷을 입으니라 왕이 그들을 아모스의 아들 선지자 이사야에게로 보내매'),
    (18379, '당신의 하나님 여호와께서 랍사게의 말을 들으셨을 것이라 그가 그의 상전 앗수르 왕의 보냄을 받고 살아 계시는 하나님을 훼방하였은즉 당신의 하나님 여호와께서 혹시 그 말로 말미암아 견책하실까 하노라 그런즉 바라건대 당신은 이 남아 있는 자를 위하여 기도하라 하시더이다 하니라'),
    (18383, '<앗수르가 또 다른 협박을 하다> 앗수르 왕이 라기스를 떠났다 함을 듣고 랍사게가 돌아가다가 그 왕을 만나니 립나를 치고 있더라'),
    (18384, '그 때에 앗수르 왕이 구스 왕 디르하가의 일에 대하여 들은즉 사람들이 이르기를 그가 나와서 왕과 싸우려 한다 하는지라 이 말을 듣고 사자들을 히스기야에게 보내며 이르되'),
    (18396, '<이사야가 왕에게 전한 말> 아모스의 아들 이사야가 사람을 보내어 히스기야에게 이르되 이스라엘의 하나님 여호와께서 말씀하시되 네가 앗수르의 산헤립 왕의 일로 내게 기도하였도다 하시고'),
    (18399, '네가 네 종을 통해서 주를 훼방하여 이르기를 내가 나의 허다한 병거를 거느리고 산들의 꼭대기에 올라가며 레바논의 깊은 곳에 이르렀으니 높은 백향목과 아름다운 향나무를 베고 또 그 제일 높은 곳에 들어가 살진 땅의 수풀에 이를 것이며'),
    (18408, '그러므로 여호와께서 앗수르 왕에 대하여 이같이 이르시되 그가 이 성에 이르지 못하며 화살 하나도 이리로 쏘지 못하며 방패를 가지고 성에 가까이 오지도 못하며 흉벽을 쌓고 치지도 못할 것이요'),
    (18529, '<구원의 약속> 야곱아 너를 창조하신 여호와께서 지금 말씀하시느니라 이스라엘아 너를 지으신 이가 말씀하시느니라 너는 두려워하지 말라 내가 너를 구속하였고 내가 너를 지명하여 불렀나니 너는 내 것이라'),
    (18537, '열방은 모였으며 민족들이 회집하였는데 그들 중에 누가 이 일을 알려 주며 이전 일들을 우리에게 들려 주겠느냐 그들이 그들의 증인을 세워서 자기들의 옳음을 나타내고 듣는 자들이 옳다고 말하게 하여 보라'),
    (18538, '나 여호와가 말하노라 너희는 나의 증인, 나의 종으로 택함을 입었나니 이는 너희가 나를 알고 믿으며 내가 그인 줄 깨닫게 하려 함이라 나의 전에 지음을 받은 신이 없었느니라 나의 후에도 없으리라'),
    (18542, '<바벨론으로부터 빠져 나오다> 너희의 구속자요 이스라엘의 거룩한 이 여호와가 말하노라 너희를 위하여 내가 바벨론에 사람을 보내어 모든 갈대아 사람에게 자기들의 연락하던 배를 타고 도망하여 내려가게 하리라'),
    (18551, '네 번제의 양을 내게로 가져오지 아니하였고 네 제물로 나를 공경하지 아니하였느니라 나는 제물로 말미암아 너를 수고롭게 하지 아니하였고 유향으로 말미암아 너를 괴롭게 하지 아니하였거늘'),
    (18556, '그러므로 내가 성소의 어른들을 욕되게 하며 야곱이 진멸 당하도록 내어 주며 이스라엘이 비방 거리가 되게 하리라'),
    (18514, '광야와 거기에 있는 성읍들과 게달 사람이 사는 마을들은 소리를 높이라 셀라의 주민들은 노래하며 산꼭대기에서 즐거이 부르라'),
    (18519, '내가 맹인들을 그들이 알지 못하는 길로 이끌며 그들이 알지 못하는 지름길로 인도하며 암흑이 그 앞에서 광명이 되게 하며 굽은 데를 곧게 할 것이라 내가 이 일을 행하여 그들을 버리지 아니하리니'),
    (18527, '야곱이 탈취를 당하게 하신 자가 누구냐 이스라엘을 약탈자들에게 넘기신 자가 누구냐 여호와가 아니시냐 우리가 그에게 범죄하였도다 그들이 그의 길로 다니기를 원하지 아니하며 그의 교훈을 순종하지 아니하였도다'),
    (18626, '우리의 구원자는 그 이름이 만군의 여호와 이스라엘의 거룩한 이시니라'),
    (18634, '이제 너는 젊어서부터 힘쓰던 주문과 많은 주술을 가지고 맞서보라 혹시 유익을 얻을 수 있을는지, 혹시 놀라게 할 수 있을는지,'),
    (18561, '한 사람은 이르기를 나는 여호와께 속하였다 할 것이며 또 한 사람은 야곱의 이름으로 자기를 부를 것이며 또 다른 사람은 자기가 여호와께 속하였음을 그의 손으로 기록하고 이스라엘의 이름으로 존귀히 여김을 받으리라'),
    (18564, '너희는 두려워하지 말며 겁내지 말라 내가 예로부터 너희에게 듣게 하지 아니하였느냐 알리지 아니하였느냐 너희는 나의 증인이라 나 외에 신이 있겠느냐 과연 반석은 없나니 다른 신이 있음을 내가 알지 못하노라'),
    (18575, '마음에 생각도 없고 지식도 없고 총명도 없으므로 내가 그것의 절반을 불사르고 또한 그 숯불 위에서 떡도 굽고 고기도 구워 먹었거늘 내가 어찌 그 나머지로 가증한 물건을 만들겠으며 내가 어찌 그 나무 토막 앞에 굴복하리요 말하지 아니하니'),
    (18579, '여호와께서 이 일을 행하셨으니 하늘아 노래할지어다 땅의 깊은 곳들아 높이 부를지어다 산들아 숲과 그 가운데의 모든 나무들아 소리내어 노래할지어다 여호와께서 야곱을 구속하셨으니 이스라엘 중에 자기의 영광을 나타내실 것임이로다'),
    (18582, '그의 종의 말을 세워 주며 그의 사자들의 계획을 성취하게 하며 예루살렘에 대하여는 이르기를 거기에 사람이 살리라 하며 유다 성읍들에 대하여는 중건될 것이라 내가 그 황폐한 곳들을 복구시키리라 하며'),
    (18638, '<하나님께서 새 일을 약속하시다> 야곱의 집이여 이를 들을지어다 너희는 이스라엘의 이름으로 일컬음을 받으며 유다의 허리에서 나왔으며 여호와의 이름으로 맹세하며 이스라엘의 하나님을 기념하면서도 진실이 없고 공의가 없도다'),
    (18642, '그러므로 내가 이 일을 예로부터 네게 알게 하였고 이 일이 이루어지기 전에 그것을 네게 듣게 하였느니라 그것을 네가 듣게 하여 내가 이것을 내 신이 행한 바요 내가 새긴 신상과 부어 만든 신상이 명령한 바라 말하지 못하게 하였느니라'),
    (18651, '너희는 다 모여 들으라 나 여호와가 사랑하는 자는 나의 기뻐하는 뜻을 바벨론에 행하리니 그의 팔이 갈대아인에게 임할 것이라 그들 중에 누가 이 일들을 알게하였느냐'),
    (18653, '너희는 내게 가까이 나아와 이것을 들으라 내가 처음부터 비밀히 말하지 아니하였나니 그것이 있을 때부터 내가 거기에 있었노라 하셨느니라 이제는 주 여호와께서 나와 그의 영을 보내셨느니라'),
    (18657, '너희는 바벨론에서 나와서 갈대아인을 피하고 즐거운 소리로 이를 알게 하여 들려주며 땅 끝까지 반포하여 이르기를 여호와께서 그의 종 야곱을 구속하셨다 하라'),
    (18686, '나 여호와가 이같이 말하노라 내가 너희의 어미를 내보낸 이혼 증서가 어디 있느냐 내가 어느 채주에게 너희를 팔았느냐 보라 너희는 너희의 죄악으로 말미암아 팔렸고 너희 어미는 너희의 배역함으로 말미암아 내보냄을 받았느니라'),
    (18687, '내가 왔어도 사람이 없었으며 내가 불러도 대답하는 자가 없었음은 어찌됨이냐 내 손이 어찌 짧아 구속하지 못하겠느냐 내게 어찌 건질 능력이 없겠느냐 보라 내가 꾸짖어 바다를 마르게 하며 강들을 사막이 되게 하며 물이 없어졌으므로 그 물고기들이 악취를 내며 갈하여 죽으리라'),
    (18689, '<주를 거역하지 아니하다> 주 여호와께서 학자들의 혀를 내게 주사 나로 곤고한 자를 말로 어떻게 도와 줄 줄을 알게 하시고 아침마다 깨우치시되 나의 귀를 깨우치사 학자들 같이 알아듣게 하시도다'),
    (18696, '보라 불을 피우고 횃불을 둘러 띤 자여 너희가 다 너희의 불꽃 가운데로 걸어가며 너희가 피운 횃불 가운데로 걸어갈지어다 너희가 내 손에서 얻을 것이 이것이라 너희가 고통이 있는 곳에 누우리라'),
    (18660, '<이방의 빛 이스라엘> 섬들아 내게 들으라 먼곳 백성들아 귀를 기울이라 여호와께서 태에서부터 나를 부르셨고 내 어머니의 복중에서부터 내 이름을 기억하셨으며'),
    (18664, '이제 여호와께서 말씀하시나니 그는 태에서부터 나를 그의 종으로 지으신 이시요 야곱을 그에게로 돌아오게 하시는 이시니 이스라엘이 그에게로 모이는도다 그러므로 내가 여호와 보시기에 영화롭게 되었으며 나의 하나님은 나의 힘이 되셨도다'),
    (18665, '그가 이르시되 네가 나의 종이 되어 야곱의 지파들을 일으키며 이스라엘 중에 보전된 자를 돌아오게 할 것은 매우 쉬운 일이라 내가 또 너를 이방의 빛으로 삼아 나의 구원을 베풀어서 땅 끝까지 이르게 하리라'),
    (18666, '이스라엘의 구속자, 이스라엘의 거룩한 이이신 여호와께서 사람에게 멸시를 당하는 자, 백성에게 미움을 받는 자, 관원들에게 종이 된 자에게 이같이 이르시되 왕들이 보고 일어서며 고관들이 경배하리니 이는 이스라엘의 거룩하신 이 신실하신 여호와 그가 너를 택하였음이니라'),
    (18667, '<예루살렘의 회복> 여호와께서 이같이 이르시되 은혜의 때에 내가 네게 응답하였고 구원의 날에 내가 너를 도왔도다 내가 장차 너를 보호하여 너를 백성의 언약으로 삼으며 나라를 일으켜 그들에게 그 황무하였던 땅을 기업으로 상속하게 하리라'),
    (18677, '네 눈을 들어 사방을 보라 그들이 다 모여 네게로 오느니라 나 여호와가 이르노라 내가 나의 삶으로 맹세하노니 네가 반드시 그 모든 무리를 장식처럼 몸에 차며 그것을 띠기를 신부처럼 할 것이라'),
    (18679, '자식을 잃었을 때에 낳은 자녀가 후일에 네 귀에 말하기를 이곳이 네게 좁으니 넓혀서 내가 거주하게 하라 하리니'),
    (18680, '그 때에 네가 네 마음에 이르기를 누가 나를 위하여 이들을 낳았는고 나는 자녀를 잃고 외로워졌으며 사로잡혀 유리하였거늘 이들을 누가 양육하였는고 나는 홀로 남았거늘 이들은 어디서 생겼는고 하리라'),
    (18682, '왕들은 네 양부가 되며 왕비들은 네 유모가 될 것이며 그들이 얼굴을 땅에 대고 네게 절하고 네 발의 티끌을 핥을 것이니 네가 나를 여호와인 줄을 알리라 나를 바라는 자는 수치를 당하지 아니하리라'),
    (18702, '너희는 하늘로 눈을 들며 그 아래의 땅을 살피라 하늘이 연기 같이 사라지고 땅이 옷 같이 해어지며 거기에 사는 자들이 하루살이 같이 죽으려니와 나의 구원은 영원히 있고 나의 공의는 폐하여지지 아니하리라'),
    (18705, '여호와의 팔이여 깨소서 깨소서 능력을 베푸소서 옛날 옛 시대에 깨신 것 같이 하소서 라합을 저미시고 용을 찌르신 이가 어찌 주가 아니시며'),
    (18707, '여호와께 구속받은 자들이 돌아와 노래하며 시온으로 돌아오니 영원한 기쁨이 그들의 머리 위에 있고 즐거움과 기쁨을 얻으리니 슬픔과 탄식이 달아나리이다'),
    (18718, '네 주 여호와, 그의 백성의 억울함을 풀어 주시는 네 하나님이 이같이 말씀하시되 보라 내가 비틀걸음 치게 하는 잔 곧 나의 분노의 큰 잔을 네 손에서 거두어서 네가 다시는 마시지 못하게 하고'),
    (18719, '그 잔을 너를 괴롭게 하던 자들의 손에 두리라 그들은 일찍이 네게 이르기를 엎드리라 우리가 넘어가리라 하던 자들이라 너를 넘어가려는 그들에게 네가 네 허리를 땅과 같게, 길거리와 같게 하였느니라 하시니라'),
    (18585, '<여호와께서 고레스를 세우시다> 여호와께서 그의 기름 부음을 받은 고레스에게 이같이 말씀하시되 내가 그의 오른손을 붙들고 그 앞에 열국을 항복하게 하며 내가 왕들의 허리를 풀어 그 앞에 문들을 열고 성문들이 닫히지 못하게 하리라'),
    (18593, '<창조의 주, 역사의 주,> 질그릇 조각 중 한 조각 같은 자가 자기를 지으신 이와 더불어 다툴진대 화 있을진저 진흙이 토기장이에게 너는 무엇을 만드느냐 또는 네가 만든 것이 그는 손이 없다 말할 수 있겠느냐'),
    (18598, '여호와께서 이같이 말씀하시되 애굽의 소득과 구스가 무역한 것과 스바의 장대한 남자들이 네게로 건너와서 네게 속할 것이요 그들이 너를 따를 것이라 사슬에 매여 건너와서 네게 굴복하고 간구하기를 하나님이 과연 네게 계시고 그 외에는 다른 하나님이 없다 하리라 하시니라'),
    (18602, '대저 여호와께서 이같이 말씀하시되 하늘을 창조하신 이 그는 하나님이시니 그가 땅을 지으시고 그것을 만드셨으며 그것을 견고하게 하시되 혼돈하게 창조하지 아니하시고 사람이 거주하게 그것을 지으셨으니 나는 여호와라 나 외에 다른 이가 없느니라'),
    (18605, '너희는 알리며 진술하고 또 함께 의논하여 보라 이 일을 옛부터 듣게 한 자가 누구냐 이전부터 그것을 알게 한 자가 누구냐 나 여호와가 아니냐 나 외에 다른 신이 없나니 나는 공의를 행하며 구원을 베푸는 하나님이라 나 외에 다른 이가 없느니라'),
    (18737, '그는 멸시를 받아 사람들에게 버림받았으며 간고를 많이 겪었으며 질고를 아는 자라 마치 사람들이 그에게서 얼굴을 가리는 것같이 멸시를 당하였고 우리도 그를 귀히 여기지 아니하였도다'),
    (18741, '그가 곤욕을 당하여 괴로울 때에도 그의 입을 열지 아니하였음이여 마치 도수장으로 끌려가는 어린 양과 털 깎는 자 앞에서 잠잠한 양 같이 그의 입을 열지 아니하였도다'),
    (18742, '그는 곤욕과 심문을 당하고 끌려갔으나 그 세대 중에 누가 생각하기를 그가 살아있는 자들의 땅에서 끊어짐은 마땅히 형벌받을 내 백성의 허물 때문이라 하였으리요'),
    (18744, '여호와께서 그에게 상함을 받게 하시기를 원하사 질고를 당하게 하셨은즉 그의 영혼을 속건제물로 드리기에 이르면 그가 씨를 보게 되며 그의 날은 길 것이요 또 그의 손으로 여호와께서 기뻐하시는 뜻을 성취하리로다'),
    (18746, '그러므로 내가 그에게 존귀한 자와 함께 몫을 받게 하며 강한 자와 함께 탈취한 것을 나누게 하리니 이는 그가 자기 영혼을 버려 사망에 이르게 하며 범죄자 중 하나로 헤아림을 받았음이니라 그러나 그가 많은 사람의 죄를 담당하며 범죄자를 위하여 기도하였느니라'),
    (18720, '<여호와께서 예루살렘을 구속하시다> 시온이여 깰지어다 깰지어다 네 힘을 낼지어다 거룩한 성 예루살렘이여 네 아름다운 옷을 입을지어다 이제부터 할례받지 아니한 자와 부정한 자가 다시는 네게로 들어옴이 없을 것임이라'),
    (18722, '여호와께서 이와 같이 말씀하시되 너희가 값없이 팔렸으니 돈 없이 속량되리라'),
    (18725, '그러므로 내 백성은 내 이름을 알리라 그러므로 그 날에는 그들이 이 말을 하는 자가 나인 줄 알리라 내가 여기 있느니라'),
    (18765, '너희가 어찌하여 양식이 아닌 것을 위하여 은을 달아 주며 배부르게 하지 못할 것을 위하여 수고하느냐 내게 듣고 들을지어다 그리하면 너희가 좋은 것을 먹을 것이며 너희 자신들이 기름진 것으로 즐거움을 얻으리라'),
    (18768, '보라 네가 알지 못하는 나라를 네가 부를 것이며 너를 알지 못하는 나라가 네게로 달려올 것은 여호와 네 하나님 곧 이스라엘의 거룩하신 이로 말미암음이니라 이는 그가 너를 영화롭게 하였느니라'),
    (18772, '이는 하늘이 땅보다 높음 같이 내 길은 너희의 길보다 높으며 내 생각은 너희의 생각보다 높음이니라'),
    (18774, '내 입에서 나가는 말도 이와 같이 헛되이 내게로 되돌아오지 아니하고 나의 기뻐하는 뜻을 이루며 내가 보낸 일에 형통함이니라'),
    (18779, '여호와께 연합한 이방인은 말하기를 여호와께서 나를 그의 백성 중에서 반드시 갈라내시리라 하지 말며 고자도 말하기를 나는 마른 나무라 하지 말라'),
    (18783, '내가 곧 그들을 나의 성산으로 인도하여 기도하는 내 집에서 그들을 기쁘게 할 것이며 그들의 번제와 희생을 나의 제단에서 기꺼이 받게 되리니 이는 내 집은 만민이 기도하는 집이라 일컬음이 될 것임이라'),
    (18789, '<우상 숭배를 규탄하시다> 의인이 죽을지라도 마음에 두는 자가 없고 진실한 이들이 거두어 감을 당할지라도 깨닫는 자가 없도다 의인들은 악한 자들 앞에서 불리어가도다'),
    (18790, '그들은 평안에 들어갔나니 바른 길로 가는 자들은 그들의 침상에서 편히 쉬리라'),
    (18793, '너희가 상수리나무 사이, 모든 푸른 나무 아래서 음욕을 피우며 골짜기 가운데 바위 틈에서 자녀를 도살하는도다'),
    (18799, '네가 누구를 두려워하며 누구로 말미암아 놀랐기에 거짓을 말하며 나를 생각하지 아니하며 이를 마음에 두지 아니하였느냐 네가 나를 경외하지 아니함은 내가 오랫동안 잠잠했기 때문이 아니냐'),
    (18801, '네가 부르짖을 때에 네가 모은 우상들에게 너를 구원하게 하라 그것들은 다 바람에 날려 가겠고 기운에 불려갈 것이로되 나를 의뢰하는 자는 땅을 차지하겠고 나의 거룩한 산을 기업으로 얻으리라'),
    (18803, '지극히 존귀하며 영원히 거하시며 거룩하다 이름하는 이가 이와 같이 말씀하시되 내가 높고 거룩한 곳에 있으며 또한 통회하고 마음이 겸손한 자와 함께 있나니 이는 겸손한 자의 영을 소생시키며 통회하는 자의 마음을 소생시키려 함이라'),
    (18747, '<하나님의 영원한 자비> 잉태하지 못하며 출산하지 못한 너는 노래할지어다 산고를 겪지 못한 너는 외쳐 노래할지어다 이는 홀로 된 여인의 자식이 남편 있는 자의 자식보다 많음이라 여호와께서 말씀하셨느니라'),
    (18760, '너는 공의로 설 것이며 학대가 네게서 멀어질 것인즉 네가 두려워 하지 아니할 것이며 공포도 네게 가까이하지 못할 것이라'),
    (18763, '너를 치려고 제조된 모든 연장이 쓸모가 없을 것이라 일어나 너를 대적하여 송사하는 모든 혀는 네게 정죄를 당하리니 이는 여호와의 종들의 기업이요 이는 그들이 내게서 얻은 공의니라 여호와의 말씀이니라'),
    (18811, '그들이 날마다 나를 찾아 나의 길 알기를 즐거워함이 마치 공의를 행하여 그의 하나님의 규례를 저버리지 아니하는 나라 같아서 의로운 판단을 내게 구하며 하나님과 가까이 하기를 즐거워하는도다'),
    (18814, '이것이 어찌 내가 기뻐하는 금식이 되겠으며 이것이 어찌 사람이 자기의 마음을 괴롭게 하는 날이 되겠느냐 그의 머리를 갈대 같이 숙이고 굵은 베와 재를 펴는 것을 어찌 금식이라 하겠으며 여호와께 열납될 날이라 하겠느냐'),
    (18818, '네가 부를 때에는 나 여호와가 응답하겠고 네가 부르짖을 때에는 내가 여기 있다 하리라 만일 네가 너희 중에서 멍에와 손가락질과 허망한 말을 제하여 버리고'),
    (18820, '주린 자에게 네 심정이 동하며 괴로워하는 자의 심정을 만족하게 하면 네 빛이 흑암 중에서 떠올라 네 어둠이 낮과 같이 될 것이며'),
    (18822, '네게서 날 자들이 오래 황폐된 곳들을 다시 세울 것이며 너는 역대의 파괴된 기초를 쌓으리니 너를 일컬어 무너진 데를 보수하는 자라 할 것이며 길을 수축하여 거할 곳이 되게 하는 자라 하리라'),
    (18823, '<안식일을 지키면> 만일 안식일에 네 발을 금하여 내 성일에 오락을 행하지 아니하고 안식일을 일컬어 즐거운 날이라, 여호와의 성일을 존귀한 날이라 하여 이를 존귀하게 여기고 네 길로 행하지 아니하며 네 오락을 구하지 아니하며 사사로운 말을 하지 아니하면'),
    (18839, '<여호와께서 백성을 구원하려고 하시다> 성실이 없어지므로 악을 떠나는 자가 탈취를 당하는도다 여호와께서 이를 살피시고 그 정의가 없는 것을 기뻐하지 아니하시고'),
    (18846, '여호와께서 이르시되 내가 그들과 세운 나의 언약이 이러하니 곧 네 위에 있는 나의 영과 네 입에 둔 나의 말이 이제부터 영원하도록 네 입에서와 네 후손의 입에서와 네 후손의 후손의 입에서 떠나지 아니하리라 하시니라 여호와의 말씀이니라'),
    (18869, '<구원의 아름다운 소식> 주 여호와의 영이 내게 내리셨으니 이는 여호와께서 내게 기름을 부으사 가난한 자에게 아름다운 소식을 전하게 하려 하심이라 나를 보내사 마음이 상한 자를 고치며 포로된 자에게 자유를, 갇힌 자에게 놓임을 선포하며'),
    (18871, '무릇 시온에서 슬퍼하는 자에게 화관을 주어 그 재를 대신하며 기쁨의 기름으로 그 슬픔을 대신하며 찬송의 옷으로 그 근심을 대신하시고 그들이 의의 나무 곧 여호와께서 심으신 그 영광을 나타낼 자라 일컬음을 받게 하려 하심이라'),
    (18878, '내가 여호와로 말미암아 크게 기뻐하며 내 영혼이 나의 하나님으로 말미암아 즐거워하리니 이는 그가 구원의 옷을 내게 입히시며 공의의 겉옷을 내게 더하심이 신랑이 사모를 쓰며 신부가 자기 보석으로 단장함 같게 하셨음이라'),
    (18855, '곧 섬들이 나를 앙망하고 다시스의 배들이 먼저 이르되 먼 곳에서 네 자손과 그들의 은금을 아울러 싣고 와서 네 하나님 여호와의 이름에 드리려 하며 이스라엘의 거룩한 이에게 드리려 하는 자들이라 이는 내가 너를 영화롭게 하였음이라'),
    (18883, '다시는 너를 버림 받은 자라 부르지 아니하며 다시는 네 땅을 황무지라 부르지 아니하고 오직 너를 헵시바라 하며 네 땅을 쁄라라 하리니 이는 여호와께서 너를 기뻐하실 것이며 네 땅이 결혼한 것처럼 될 것임이라'),
    (18885, '예루살렘이여 내가 너의 성벽 위에 파수꾼을 세우고 그들로 하여금 주야로 계속 잠잠하지 않게 하였느니라 너희 여호와로 기억하시게 하는 자들아 너희는 쉬지 말며'),
    (18915, '주께서 기쁘게 공의를 행하는 자와 주의 길에서 주를 기억하는 자를 선대하시거늘 우리가 범죄하므로 주께서 진노하셨사오며 이 현상이 이미 오래 되었사오니 우리가 어찌 구원을 얻을 수 있으리이까'),
    (18917, '주의 이름을 부르는 자가 없으며 스스로 분발하여 주를 붙잡는 자가 없사오니 이는 주께서 우리에게 얼굴을 숨기시며 우리의 죄악으로 말미암아 우리가 소멸되게 하셨음이라'),
    (18923, '<하나님께서 패역한 백성을 벌하시다> 나는 나를 구하지 아니하던 자에게 물음을 받았으며 나를 찾지 아니하던 자에게 찾아냄이 되었으며 내 이름을 부르지 아니하던 나라에 내가 여기 있노라 내가 여기 있노라 하였노라'),
    (18926, '그들이 무덤 사이에 앉으며 은밀한 처소에서 밤을 지내며 돼지 고기를 먹으며 가증한 것들의 국을 그릇에 담으면서'),
    (18929, '너희의 죄악과 너희 조상들의 죄악은 한 가지니 그들이 산 위에서 분향하며 작은 산 위에서 나를 능욕하였음이라 그러므로 내가 먼저 그들의 행위를 헤아리고 그들의 품에 보응하리라 여호와가 말하였느니라'),
    (18930, '여호와께서 이와 같이 말씀하시되 포도송이에는 즙이 있으므로 사람들이 말하기를 그것을 상하지 말라 거기 복이 있느니라 하나니 나도 내 종들을 위하여 그와 같이 행하여 다 멸하지 아니하고'),
    (18934, '내가 너희를 칼에 붙일 것인즉 다 구푸리고 죽임을 당하리니 이는 내가 불러도 너희가 대답하지 아니하며 내가 말하여도 듣지 아니하고 나의 눈에 악을 행하였으며 내가 즐겨하지 아니하는 일을 택하였음이니라'),
    (18935, '이러므로 주 여호와께서 이와 같이 말씀하시니라 보라 나의 종들은 먹을 것이로되 너희는 주릴 것이니라 보라 나의 종들은 마실 것이로되 너희는 갈할 것이니라 보라 나의 종들은 기뻐할 것이로되 너희는 수치를 당할 것이니라'),
    (18938, '이러므로 땅에서 자기를 위하여 복을 구하는 자는 진리의 하나님을 향하여 복을 구할 것이요 땅에서 맹세하는 자는 진리의 하나님으로 맹세하리니 이는 이전 환난이 잊어졌고 내 눈 앞에 숨겨졌음이라'),
    (18941, '내가 예루살렘을 즐거워하며 나의 백성을 기뻐하리니 우는 소리와 부르짖는 소리가 그 가운데서 다시는 들리지 아니할 것이며'),
    (18892, '<여호와의 승리> 에돔에서 오는 이는 누구며 붉은 옷을 입고 보스라에서 오는 이 누구냐 그의 화려한 의복 큰 능력으로 걷는 이가 누구냐 그는 나이니 공의를 말하는 이요 구원하는 능력을 가진 이니라'),
    (18894, '만민 가운데 나와 함께 한 자가 없이 내가 홀로 포도즙틀을 밟았는데 내가 노함으로 말미암아 무리를 밟았고 분함으로 말미암아 짓밟았으므로 그들의 선혈이 내 옷에 튀어 내 의복을 다 더럽혔음이니'),
    (18902, '백성이 옛적 모세의 때를 기억하여 이르되 백성과 양떼의 목자를 바다에서 올라오게 하신 이가 이제 어디 계시냐 그들 가운데에 성령을 두신 이가 이제 어디 계시냐'),
    (18906, '<자비와 사랑을 구하는 기도> 주여 하늘에서 굽어 살피시며 주의 거룩하고 영화로운 처소에서 보옵소서 주의 열성과 주의 능하신 행동이 이제 어디 있나이까 주께서 베푸시던 간곡한 자비와 사랑이 내게 그쳤나이다'),
    (18950, '소를 잡아 드리는 것은 살인함과 다름이 없이 하고 어린 양으로 제사드리는 것은 개의 목을 꺾음과 다름이 없이 하며 드리는 예물은 돼지의 피와 다름이 없이 하고 분향하는 것은 우상을 찬송함과 다름이 없이 행하는 그들은 자기의 길을 택하며 그들의 마음은 가증한 것을 기뻐한즉'),
    (18951, '나 또한 유혹을 그들에게 택하여 주며 그들이 무서워하는 것을 그들에게 임하게 하리니 이는 내가 불러도 대답하는 자가 없으며 내가 말하여도 그들이 듣지 않고 오직 나의 목전에서 악을 행하며 내가 기뻐하지 아니하는 것을 택하였음이라 하시니라'),
    (18952, '여호와의 말씀으로 말미암아 떠는 자들아 그의 말씀을 들을지어다 이르시되 너희 형제가 너희를 미워하며 내 이름으로 말미암아 너희를 쫓아내며 이르기를 여호와께서는 영광을 나타내사 너희 기쁨을 우리에게 보이시기를 원하노라 하였으나 그들은 수치를 당하리라 하셨느니라'),
    (18959, '여호와께서 이와 같이 말씀하시되 보라 내가 그에게 평강을 강 같이, 그에게 뭇 나라의 영광을 넘치는 시내 같이 주리니 너희가 그 성읍의 젖을 빨 것이며 너희가 옆에 안기며 그 무릎에서 놀 것이라'),
    (18963, '여호와께서 불과 칼로 모든 혈육에게 심판을 베푸신즉 여호와께 죽임당할 자가 많으리니'),
    (18966, '내가 그들 가운데에서 징조를 세워서 그들 가운데에서 도피한 자를 여러 나라 곧 다시스와 뿔과 활을 당기는 룻과 및 두발과 야완과 또 나의 명성을 듣지도 못하고 나의 영광을 보지도 못한 먼 섬들로 보내리니 그들이 나의 영광을 뭇 나라에 전파하리라'),
    (18967, '나 여호와가 말하노라 이스라엘 자손이 예물을 깨끗한 그릇에 담아 여호와의 집에 드림 같이 그들이 너희 모든 형제를 뭇 나라에서 나의 성산 예루살렘으로 말과 수레와 교자와 노새와 낙타에 태워다가 여호와께 예물로 드릴 것이요'),
    (19028, '<유다의 음란과 행악> 그들이 말하기를 가령 사람이 그의 아내를 버리므로 그가 그에게서 떠나 타인의 아내가 된다 하자 남편이 그를 다시 받겠느냐 그리하면 그 땅이 크게 더러워지지 아니하겠느냐 하느니라 네가 많은 무리와 행음하고서도 내게로 돌아오려느냐 여호와의 말씀이니라'),
    (19033, '<배역한 이스라엘과 반역한 유다> ○요시야 왕 때에 여호와께서 또 내게 이르시되 너는 배역한 이스라엘이 행한 바를 보았느냐 그가 모든 높은 산에 오르며 모든 푸른 나무 아래로 가서 거기서 행음하였도다'),
    (19038, '○여호와께서 내게 이르시되 배역한 이스라엘은 반역한 유다보다 자신이 더 의로움이 나타났나니'),
    (19039, '너는 가서 북을 향하여 이 말을 선포하여 이르라 여호와께서 이르시되 배역한 이스라엘아 돌아오라 나의 노한 얼굴을 너희에게로 향하지 아니하리라 나는 긍휼이 있는 자라 노를 한없이 품지 아니하느니라 여호와의 말씀이니라'),
    (19043, '여호와의 말씀이니라 너희가 이 땅에서 번성하여 많아질 때에는 사람들이 여호와의 언약궤를 다시는 말하지 아니할 것이요 생각하지 아니할 것이요 기억하지 아니할 것이요 찾지 아니할 것이요 다시는 만들지 아니할 것이며'),
    (19044, '그 때에 예루살렘이 그들에게 여호와의 보좌라 일컬음이 되며 모든 백성이 그리로 모이리니 곧 여호와의 이름으로 말미암아 예루살렘에 모이고 다시는 그들의 악한 마음의 완악한 대로 그들이 행하지 아니할 것이며'),
    (19046, '<이스라엘의 배역> ○내가 말하기를 내가 어떻게 하든지 너를 자녀들 중에 두며 허다한 나라들 중에 아름다운 기업인 이 귀한 땅을 네게 주리라 하였고 내가 다시 말하기를 너희가 나를 나의 아버지라 하고 나를 떠나지 말 것이니라 하였노라'),
    (19049, '<진실한 회개> 배역한 자식들아 돌아오라 내가 너희의 배역함을 고치리라 하시니라 ○보소서 우리가 주께 왔사오니 주는 우리 하나님 여호와이심이니이다'),
    (19053, '우리는 수치 중에 눕겠고 우리의 치욕이 우리를 덮을 것이니 이는 우리와 우리 조상들이 청년의 때로부터 오늘까지 우리 하나님 여호와께 범죄하여 우리 하나님 여호와의 목소리에 순종하지 아니하였음이니이다'),
    (18992, '가서 예루살렘의 귀에 외칠지니라 여호와께서 이와 같이 말씀하시기를 내가 너를 위하여 네 청년 때의 인애와 네 신혼 때의 사랑을 기억하노니 곧 씨 뿌리지 못하는 땅, 그 광야에서 나를 따랐음이니라'),
    (18994, '<조상들이 여호와를 멀리하였다> ○야곱의 집과 이스라엘의 집 모든 족속들아 여호와의 말씀을 들으라'),
    (18996, '그들이 우리를 애굽 땅에서 인도하여 내시고 광야 곧 사막과 구덩이 땅, 건조하고 사망의 그늘진 땅, 사람이 그 곳으로 다니지 아니하고 그 곳에 사람이 거주하지 아니하는 땅을 우리가 통과하게 하시던 여호와께서 어디 계시냐 하고 말하지 아니하였도다'),
    (18999, '<백성이 행한 악> ○그러므로 내가 다시 싸우고 너희 자손들과도 싸우리라 여호와의 말씀이니라'),
    (19004, '<이스라엘의 악과 반역> ○이스라엘이 종이냐 씨종이냐 어찌하여 포로가 되었느냐'),
    (19010, '<이방 신을 따라 가는 이스라엘> ○네가 옛적부터 네 멍에를 꺾고 네 결박을 끊으며 말하기를 나는 순종하지 아니하리라 하고 모든 높은 산 위에서와 모든 푸른 나무 아래에서 너는 몸을 굽혀 행음하도다'),
    (19013, '네가 어찌 말하기를 나는 더럽혀지지 아니하였다 바알들의 뒤를 따르지 아니하였다 하겠느냐 골짜기 속에 있는 네 길을 보라 네 행한 바를 알 것이니라 발이 빠른 암낙타가 그의 길을 어지러이 달리는 것과 같았으며'),
    (19015, '내가 또 말하기를 네 발을 제어하여 벗은 발이 되게 하지 말며 목을 갈하게 하지 말라 하였으나 오직 너는 말하기를 아니라 이는 헛된 말이라 내가 이방 신들을 사랑하였은즉 그를 따라 가겠노라 하도다'),
    (19016, '<유다를 심판하리라> ○도둑이 붙들리면 수치를 당함 같이 이스라엘 집 곧 그들의 왕들과 지도자들과 제사장들과 선지자들이 수치를 당하였느니라'),
    (19017, '그들이 나무를 향하여 너는 나의 아버지라 하며 돌을 향하여 너는 나를 낳았다 하고 그들의 등을 내게로 돌리고 그들의 얼굴은 내게로 향하지 아니하다가 그들이 환난을 당할 때에는 이르기를 일어나 우리를 구원하소서 하리라'),
    (19019, '○너희가 나에게 대항함은 어찌 됨이냐 너희가 다 내게 잘못하였느니라 여호와의 말씀이니라'),
    (19021, '너희 이 세대여 여호와의 말을 들어 보라 내가 이스라엘에게 광야가 되었었느냐 캄캄한 땅이 되었었느냐 무슨 이유로 내 백성이 말하기를 우리는 놓였으니 다시 주께로 가지 아니하겠다 하느냐'),
    (19056, '○여호와께서 유다와 예루살렘 사람에게 이와 같이 이르노라 너희 묵은 땅을 갈고 가시덤불에 파종하지 말라'),
    (19057, '유다인과 예루살렘 주민들아 너희는 스스로 할례를 행하여 너희 마음 가죽을 베고 나 여호와께 속하라 그리하지 아니하면 너희 악행으로 말미암아 나의 분노가 불 같이 일어나 사르리니 그것을 끌 자가 없으리라'),
    (19058, '<나라들을 멸하는 자가 나아오다> ○너희는 유다에 선포하며 예루살렘에 공포하여 이르기를 이 땅에서 나팔을 불라 하며 또 크게 외쳐 이르기를 너희는 모이라 우리가 견고한 성으로 들어가자 하고'),
    (19063, '○내가 이르되 슬프도소이다 주 여호와여 주께서 진실로 이 백성과 예루살렘을 크게 속이셨나이다 이르시기를 너희에게 평강이 있으리라 하시더니 칼이 생명에 이르렀나이다'),
    (19064, '<백성에게 심판을 행하리라> ○그 때에 이 백성과 예루살렘에 전할 자가 있어서 뜨거운 바람이 광야에 있는 헐벗은 산에서 내 딸 백성에게 불어온다 하리라 이는 키질하기 위함도 아니요 정결하게 하려 함도 아니며'),
    (19072, '<선지자의 탄식> ○슬프고 아프다 내 마음속이 아프고 내 마음이 답답하여 잠잠할 수 없으니 이는 나의 심령이 나팔 소리와 전쟁의 경보를 들음이로다'),
    (19076, '<혼돈의 환상> ○보라 내가 땅을 본즉 혼돈하고 공허하며 하늘에는 빛이 없으며'),
    (19084, '내가 소리를 들은즉 여인의 해산하는 소리 같고 초산하는 자의 고통하는 소리 같으니 이는 시온의 딸의 소리라 그가 헐떡이며 그의 손을 펴고 이르기를 내게 화가 있도다 죽이는 자로 말미암아 나의 심령이 피곤하도다 하는도다'),
    (19124, '<벌 받을 백성> ○만군의 여호와께서 이와 같이 말씀하시되 포도를 따듯이 그들이 이스라엘의 남은 자를 말갛게 주우리라 너는 포도 따는 자처럼 네 손을 광주리에 자주자주 놀리라 하시나니'),
    (19125, '내가 누구에게 말하며 누구에게 경책하여 듣게 할꼬 보라 그 귀가 할례를 받지 못하였으므로 듣지 못하는도다 보라 여호와의 말씀을 그들이 자신들에게 욕으로 여기고 이를 즐겨 하지 아니하니'),
    (19130, '그들이 가증한 일을 행할 때에 부끄러워하였느냐 아니라 조금도 부끄러워 하지 않을 뿐 아니라 얼굴도 붉어지지 않았느니라 그러므로 그들이 엎드러지는 자와 함께 엎드러질 것이라 내가 그들을 벌하리니 그 때에 그들이 거꾸러지리라 여호와의 말씀이니라'),
    (19131, '<선한 길로 가지 아니하다> ○여호와께서 이와 같이 말씀하시되 너희는 길에 서서 보며 옛적 길 곧 선한 길이 어디인지 알아보고 그리로 가라 너희 심령이 평강을 얻으리라 하나 그들의 대답이 우리는 그리로 가지 않겠노라 하였으며'),
    (19137, '<북방에서 쳐들어 오는 민족> ○여호와께서 이와 같이 말씀하시되 보라 한 민족이 북방에서 오며 큰 나라가 땅 끝에서부터 떨쳐 일어나나니'),
    (19142, '○내가 이미 너를 내 백성 중에 망대와 요새로 삼아 그들의 길을 알고 살피게 하였노라'),
    (19085, '<예루살렘의 허물과 반역> 너희는 예루살렘 거리로 빨리 다니며 그 넓은 거리에서 찾아보고 알라 너희가 만일 정의를 행하며 진리를 구하는 자를 한 사람이라도 찾으면 내가 이 성읍을 용서하리라'),
    (19087, '여호와여 주의 눈이 진리를 찾지 아니하시나이까 주께서 그들을 치셨을지라도 그들이 아픈 줄을 알지 못하며 그들을 멸하셨을지라도 그들이 징계를 받지 아니하고 그들의 얼굴을 바위보다 굳게 하여 돌아오기를 싫어하므로'),
    (19091, '○내가 어찌 너를 용서하겠느냐 네 자녀가 나를 버리고 신이 아닌 것들로 맹세하였으며 내가 그들을 배불리 먹인즉 그들이 간음하며 창기의 집에 허다히 모이며'),
    (19094, '<여호와께서 백성을 버리시다> ○너희는 그 성벽에 올라가 무너뜨리되 다 무너뜨리지 말고 그 가지만 꺾어 버리라 여호와의 것이 아님이니라'),
    (19098, '○그러므로 만군의 하나님 여호와께서 이와 같이 말씀하시니라 너희가 이 말을 하였은즉 볼지어다 내가 네 입에 있는 나의 말을 불이 되게 하고 이 백성을 나무가 되게 하여 불사르리라'),
    (19103, '○그들이 만일 이르기를 우리 하나님 여호와께서 어찌하여 이 모든 일을 우리에게 행하셨느냐 하거든 너는 그들에게 이르기를 너희가 여호와를 버리고 너희 땅에서 이방 신들을 섬겼은즉 이와 같이 너희 것이 아닌 땅에서 이방인들을 섬기리라 하라'),
    (19104, '<여호와께서 백성에게 이르시다> ○너는 이를 야곱 집에 선포하며 유다에 공포하여 이르기를'),
    (19106, '여호와의 말씀이니라 너희가 나를 두려워하지 아니하느냐 내 앞에서 떨지 아니하겠느냐 내가 모래를 두어 바다의 한계를 삼되 그것으로 영원한 한계를 삼고 지나치지 못하게 하였으므로 파도가 거세게 이나 그것을 이기지 못하며 뛰노나 그것을 넘지 못하느니라'),
    (19114, '○이 땅에 무섭고 놀라운 일이 있도다'),
    (19183, '<죄와 벌> ○너는 또 그들에게 말하기를 여호와의 말씀에 사람이 엎드러지면 어찌 일어나지 아니하겠으며 사람이 떠나갔으면 어찌 돌아오지 아니하겠느냐'),
    (19187, '○너희가 어찌 우리는 지혜가 있고 우리에게는 여호와의 율법이 있다 말하겠느냐 참으로 서기관의 거짓의 붓이 거짓되게 하였나니'),
    (19191, '그들이 가증한 일을 행할 때에 부끄러워하였느냐 아니라 조금도 부끄러워 하지 않을 뿐 아니라 얼굴도 붉어지지 아니하였느니라 그러므로 그들이 엎드러질 자와 함께 엎드러질 것이라 내가 그들을 벌할 때에 그들이 거꾸러지리라 여호와의 말씀이니라'),
    (19192, '○여호와의 말씀이니라 내가 그들을 진멸하리니 포도나무에 포도가 없을 것이며 무화과나무에 무화과가 없을 것이며 그 잎사귀가 마를 것이라 내가 그들에게 준 것이 없어지리라 하셨나니'),
    (19193, '우리가 어찌 가만히 앉았으랴 모일지어다 우리가 견고한 성읍들로 들어가서 거기에서 멸망하자 우리가 여호와께 범죄하였으므로 우리 하나님 여호와께서 우리를 멸하시며 우리에게 독한 물을 마시게 하심이니라'),
    (19197, '<선지자의 번뇌> ○슬프다 나의 근심이여 어떻게 위로를 받을 수 있을까 내 마음이 병들었도다'),
    (19198, '딸 내 백성의 심히 먼 땅에서 부르짖는 소리로다 여호와께서 시온에 계시지 아니한가, 그의 왕이 그 가운데 계시지 아니한가 그들이 어찌하여 그 조각한 신상과 이방의 헛된 것들로 나를 격노하게 하였는고 하시니'),
    (19233, '○여호와여 주와 같은 이 없나이다 주는 크시니 주의 이름이 그 권능으로 말미암아 크시니이다'),
    (19238, '○너희는 이같이 그들에게 이르기를 천지를 짓지 아니한 신들은 땅 위에서, 이 하늘 아래에서 망하리라 하라'),
    (19239, '<만물의 조성자 만군의 여호와> ○여호와께서 그의 권능으로 땅을 지으셨고 그의 지혜로 세계를 세우셨고 그의 명철로 하늘을 펴셨으며'),
    (19244, '<백성의 탄식> ○에워싸인 가운데에 앉은 자여 네 짐 꾸러미를 이 땅에서 꾸리라'),
    (19246, '○슬프다 내 상처여 내가 중상을 당하였도다 그러나 내가 말하노라 이는 참으로 고난이라 내가 참아야 하리로다'),
    (19250, '○여호와여 내가 알거니와 사람의 길이 자신에게 있지 아니하니 걸음을 지도함이 걷는 자에게 있지 아니하니이다'),
    (19208, '○그러므로 만군의 여호와께서 이와 같이 말씀하시되 보라 내가 내 딸 백성을 어떻게 처치할꼬 그들을 녹이고 연단하리라'),
    (19211, '○내가 산들을 위하여 울며 부르짖으며 광야 목장을 위하여 슬퍼하나니 이는 그것들이 불에 탔으므로 지나는 자가 없으며 거기서 가축의 소리가 들리지 아니하며 공중의 새도 짐승도 다 도망하여 없어졌음이라'),
    (19213, '○지혜가 있어서 이 일을 깨달을 만한 자가 누구며 여호와의 입의 말씀을 받아서 선포할 자가 누구인고 이 땅이 어찌하여 멸망하여 광야 같이 불타서 지나가는 자가 없게 되었느냐'),
    (19218, '<사랑과 정의와 공의를 행하시는 여호와> ○만군의 여호와께서 이와 같이 말씀하시되 너희는 잘 생각해 보고 곡하는 부녀를 불러오며 또 사람을 보내 지혜로운 부녀를 불러오되'),
    (19224, '○여호와께서 이와 같이 말씀하시되 지혜로운 자는 그의 지혜를 자랑하지 말라 용사는 그의 용맹을 자랑하지 말라 부자는 그의 부함을 자랑하지 말라'),
    (19226, '○여호와의 말씀이니라 보라 날이 이르면 할례 받은 자와 할례 받지 못한 자를 내가 다 벌하리니'),
    (19153, '○보라 너희가 무익한 거짓말을 의존하는도다'),
    (19157, '○너희는 내가 처음으로 내 이름을 둔 처소 실로에 가서 내 백성 이스라엘의 악에 대하여 내가 어떻게 행하였는지를 보라'),
    (19161, '<여호와를 순종하지 아니하는 백성> ○그런즉 너는 이 백성을 위하여 기도하지 말라 그들을 위하여 부르짖어 구하지 말라 내게 간구하지 말라 내가 네게서 듣지 아니하리라'),
    (19166, '○만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희 희생제물과 번제물의 고기를 아울러 먹으라'),
    (19168, '오직 내가 이것을 그들에게 명령하여 이르기를 너희는 내 목소리를 들으라 그리하면 나는 너희 하나님이 되겠고 너희는 내 백성이 되리라 너희는 내가 명령한 모든 길로 걸어가라 그리하면 복을 받으리라 하였으나'),
    (19172, '○네가 그들에게 이 모든 말을 할지라도 그들이 너에게 순종하지 아니할 것이요 네가 그들을 불러도 그들이 네게 대답하지 아니하리니'),
    (19174, '<도벳 사당을 건축> ○너의 머리털을 베어 버리고 벗은 산 위에서 통곡할지어다 여호와께서 그 노하신 바 이 세대를 끊어 버리셨음이라'),
    (19177, '그러므로 여호와께서 말씀하시니라 날이 이르면 이 곳을 도벳이라 하거나 힌놈의 아들의 골짜기라 말하지 아니하고 죽임의 골짜기라 말하리니 이는 도벳에 자리가 없을 만큼 매장했기 때문이니라'),
    (19256, '이 언약은 내가 너희 조상들을 쇠풀무 애굽 땅에서 이끌어내던 날에 그들에게 명령한 것이라 곧 내가 이르기를 너희는 내 목소리를 순종하고 나의 모든 명령을 따라 행하라 그리하면 너희는 내 백성이 되겠고 나는 너희의 하나님이 되리라'),
    (19257, '내가 또 너희 조상들에게 한 맹세는 그들에게 젖과 꿀이 흐르는 땅을 주리라 한 언약을 이루리라 한 것인데 오늘이 그것을 증언하느니라 하라 하시기로 내가 대답하여 이르되 아멘 여호와여 하였노라'),
    (19258, '○여호와께서 내게 이르시되 너는 이 모든 말로 유다 성읍들과 예루살렘 거리에서 선포하여 이르기를 너희는 이 언약의 말을 듣고 지키라'),
    (19260, '그들이 순종하지 아니하며 귀를 기울이지도 아니하고 각각 그 악한 마음의 완악한 대로 행하였으므로 내가 그들에게 행하라 명령하였어도 그들이 행하지 아니한 이 언약의 모든 규정대로 그들에게 이루게 하였느니라 하라'),
    (19261, '○여호와께서 또 내게 이르시되 유다인과 예루살렘 주민 중에 반역이 있도다'),
    (19266, '○그러므로 너는 이 백성을 위하여 기도하지 말라 그들을 위하여 부르짖거나 구하지 말라 그들이 그 고난으로 말미암아 내게 부르짖을 때에 내가 그들에게서 듣지 아니하리라'),
    (19270, '<아나돗 사람들이 예레미야를 죽이려고 꾀하다> ○여호와께서 내게 알게 하셨으므로 내가 그것을 알았나이다 그 때에 주께서 그들의 행위를 내게 보이셨나이다'),
    (19271, '나는 끌려서 도살 당하러 가는 순한 어린 양과 같으므로 그들이 나를 해하려고 꾀하기를 우리가 그 나무와 열매를 함께 박멸하자 그를 살아 있는 자의 땅에서 끊어서 그의 이름이 다시 기억되지 못하게 하자 함을 내가 알지 못하였나이다'),
    (19280, '○만일 네가 보행자와 함께 달려도 피곤하면 어찌 능히 말과 경주하겠느냐 네가 평안한 땅에서는 무사하려니와 요단 강 물이 넘칠 때에는 어찌하겠느냐'),
    (19282, '<황무지의 슬픔과 여호와의 분노> ○내가 내 집을 버리며 내 소유를 내던져 내 마음으로 사랑하는 것을 그 원수의 손에 넘겼나니'),
    (19289, '<여호와의 악한 이웃에 대하여> ○내가 내 백성 이스라엘에게 기업으로 준 소유에 손을 대는 나의 모든 악한 이웃에 대하여 여호와께서 이와 같이 말씀하시니라 보라 내가 그들을 그 땅에서 뽑아 버리겠고 유다 집을 그들 가운데서 뽑아 내리라'),
    (19291, '그들이 내 백성의 도를 부지런히 배우며 살아 있는 여호와라는 내 이름으로 맹세하기를 자기들이 내 백성을 가리켜 바알로 맹세하게 한 것 같이 하면 그들이 내 백성 가운데에 세움을 입으려니와'),
    (19343, '그들이 만일 네게 말하기를 우리가 어디로 나아가리요 하거든 너는 그들에게 이르기를 여호와께서 이와 같이 말씀하시니라 죽을 자는 죽음으로 나아가고 칼을 받을 자는 칼로 나아가고 기근을 당할 자는 기근으로 나아가고 포로 될 자는 포로 됨으로 나아갈지니라 하셨다 하라'),
    (19346, '○예루살렘아 너를 불쌍히 여길 자 누구며 너를 위해 울 자 누구며 돌이켜 네 평안을 물을 자 누구냐'),
    (19351, '<예레미야의 기도와 여호와의 말씀> ○내게 재앙이로다 나의 어머니여 어머니께서 나를 온 세계에 다투는 자와 싸우는 자를 만날 자로 낳으셨도다 내가 꾸어 주지도 아니하였고 사람이 내게 꾸이지도 아니하였건마는 다 나를 저주하는도다'),
    (19356, '○여호와여 주께서 아시오니 원하건대 주는 나를 기억하시며 돌보시사 나를 박해하는 자에게 보복하시고 주의 오래 참으심으로 말미암아 나로 멸망하지 아니하게 하옵시며 주를 위하여 내가 부끄러움 당하는 줄을 아시옵소서'),
    (19360, '○여호와께서 이와 같이 말씀하시되 네가 만일 돌아오면 내가 너를 다시 이끌어 내 앞에 세울 것이며 네가 만일 헛된 것을 버리고 귀한 것을 말한다면 너는 나의 입이 될 것이라 그들은 네게로 돌아오려니와 너는 그들에게로 돌아가지 말지니라'),
    (19367, '○여호와께서 이와 같이 말씀하시되 초상집에 들어가지 말라 가서 통곡하지 말며 그들을 위하여 애곡하지 말라 내가 이 백성에게서 나의 평강을 빼앗으며 인자와 사랑을 제함이라 여호와의 말씀이니라'),
    (19372, '○네가 이 모든 말로 백성에게 말할 때에 그들이 네게 묻기를 여호와께서 우리에게 이 모든 큰 재앙을 선포하심은 어찌 됨이며 우리의 죄악은 무엇이며 우리가 우리 하나님 여호와께 범한 죄는 무엇이냐 하거든'),
    (19375, '내가 너희를 이 땅에서 쫓아내어 너희와 너희 조상들이 알지 못하던 땅에 이르게 할 것이라 너희가 거기서 주야로 다른 신들을 섬기리니 이는 내가 너희에게 은혜를 베풀지 아니함이라 하셨다 하라'),
    (19376, '<포로의 귀환> ○여호와의 말씀이니라 그러나 보라 날이 이르리니 다시는 이스라엘 자손을 애굽 땅에서 인도하여 내신 여호와께서 살아 계심을 두고 맹세하지 아니하고'),
    (19378, '<악과 죄를 배나 갚을 것이라> ○여호와의 말씀이니라 보라 내가 많은 어부를 불러다가 그들을 낚게 하며 그 후에 많은 포수를 불러다가 그들을 모든 산과 모든 언덕과 바위 틈에서 사냥하게 하리니'),
    (19381, '<예레미야의 기도> ○여호와 나의 힘, 나의 요새, 환난날의 피난처시여 민족들이 땅 끝에서 주께 이르러 말하기를 우리 조상들의 계승한 바는 허망하고 거짓되고 무익한 것뿐이라'),
    (19321, '○유다가 슬퍼하며 성문의 무리가 피곤하여 땅 위에서 애통하니 예루살렘의 부르짖음이 위로 오르도다'),
    (19326, '○여호와여 우리의 죄악이 우리에게 대하여 증언할지라도 주는 주의 이름을 위하여 일하소서 우리의 타락함이 많으니이다 우리가 주께 범죄하였나이다'),
    (19329, '○여호와께서 이 백성에 대하여 이와 같이 말씀하시되 그들이 어그러진 길을 사랑하여 그들의 발을 멈추지 아니하므로 여호와께서 그들을 받지 아니하고 이제 그들의 죄를 기억하시고 그 죄를 벌하시리라 하시고'),
    (19332, '○이에 내가 말하되 슬프도소이다 주 여호와여 보시옵소서 선지자들이 그들에게 이르기를 너희가 칼을 보지 아니하겠고 기근은 너희에게 이르지 아니할 것이라 내가 이 곳에서 너희에게 확실한 평강을 주리라 하나이다'),
    (19333, '여호와께서 내게 이르시되 선지자들이 내 이름으로 거짓 예언을 하도다 나는 그들을 보내지 아니하였고 그들에게 명령하거나 이르지 아니하였거늘 그들이 거짓 계시와 점술과 헛된 것과 자기 마음의 거짓으로 너희에게 예언하는도다'),
    (19334, '그러므로 내가 보내지 아니하였어도 내 이름으로 예언하여 이르기를 칼과 기근이 이 땅에 이르지 아니하리라 하는 선지자들에 대하여 여호와께서 이와 같이 말씀하셨노라 그 선지자들은 칼과 기근에 멸망할 것이요'),
    (19335, '그들의 예언을 받은 백성은 기근과 칼로 말미암아 예루살렘 거리에 던짐을 당할 것인즉 그들을 장사할 자가 없을 것이요 그들의 아내와 아들과 딸이 그렇게 되리니 이는 내가 그들의 악을 그 위에 부음이니라'),
    (19338, '<백성이 주께 간구하다> ○주께서 유다를 온전히 버리시나이까 주의 심령이 시온을 싫어하시나이까 어찌하여 우리를 치시고 치료하지 아니하시나이까 우리가 평강을 바라도 좋은 것이 없고 치료 받기를 기다리나 두려움만 보나이다'),
    (19341, '이방인의 우상 가운데 능히 비를 내리게 할 자가 있나이까 하늘이 능히 소나기를 내릴 수 있으리이까 우리 하나님 여호와여 그리하는 자는 주가 아니시니이까 그러므로 우리가 주를 앙망하옵는 것은 주께서 이 모든 것을 만드셨음이니이다 하니라'),
    (19300, '○여호와의 말씀이 내게 임하니라 이르시되'),
    (19303, '여호와의 말씀이니라 띠가 사람의 허리에 속함 같이 내가 이스라엘 온 집과 유다 온 집으로 내게 속하게 하여 그들로 내 백성이 되게 하며 내 이름과 명예와 영광이 되게 하려 하였으나 그들이 듣지 아니하였느니라'),
    (19304, '<포도주 가죽부대> ○그러므로 너는 이 말로 그들에게 이르기를 이스라엘의 하나님 여호와의 말씀에 모든 가죽부대가 포도주로 차리라 하셨다 하라 그리하면 그들이 네게 이르기를 모든 가죽부대가 포도주로 찰 줄을 우리가 어찌 알지 못하리요 하리니'),
    (19306, '또 그들로 피차 충돌하여 상하게 하되 부자 사이에도 그러하게 할 것이라 내가 그들을 불쌍히 여기지 아니하며 사랑하지 아니하며 아끼지 아니하고 멸하리라 하셨다 하라 여호와의 말씀이니라'),
    (19307, '<교만에 대한 경고> ○너희는 들을지어다, 귀를 기울일지어다, 교만하지 말지어다, 여호와께서 말씀하셨음이라'),
    (19310, '○너는 왕과 왕후에게 전하기를 스스로 낮추어 앉으라 관 곧 영광의 면류관이 내려졌다 하라'),
    (19312, '○너는 눈을 들어 북방에서 오는 자들을 보라 네게 맡겼던 양 떼, 네 아름다운 양 떼는 어디 있느냐'),
    (19388, '○여호와께서 이와 같이 말씀하시니라 무릇 사람을 믿으며 육신으로 그의 힘을 삼고 마음이 여호와에게서 떠난 그 사람은 저주를 받을 것이라'),
    (19392, '○만물보다 거짓되고 심히 부패한 것은 마음이라 누가 능히 이를 알리요마는'),
    (19395, '<예레미야의 간구> ○영화로우신 보좌여 시작부터 높이 계시며 우리의 성소이시며'),
    (19401, '나를 박해하는 자로 치욕을 당하게 하시고 나로 치욕을 당하게 마옵소서 그들은 놀라게 하시고 나는 놀라게 하지 마시옵소서 재앙의 날을 그들에게 임하게 하시며 배나 되는 멸망으로 그들을 멸하소서'),
    (19402, '<안식일을 거룩하게 하라> ○여호와께서 내게 이와 같이 말씀하시되 너는 가서 유다 왕들이 출입하는 평민의 문과 예루살렘 모든 문에 서서'),
    (19407, '○여호와의 말씀이니라 너희가 만일 삼가 나를 순종하여 안식일에 짐을 지고 이 성문으로 들어오지 아니하며 안식일을 거룩히 하여 어떤 일이라도 하지 아니하면'),
    (19410, '그러나 만일 너희가 나를 순종하지 아니하고 안식일을 거룩되게 아니하여 안식일에 짐을 지고 예루살렘 문으로 들어오면 내가 성문에 불을 놓아 예루살렘 궁전을 삼키게 하리니 그 불이 꺼지지 아니하리라 하셨다 할지니라 하시니라'),
    (19415, '○그 때에 여호와의 말씀이 내게 임하니라 이르시되'),
    (19421, '그러므로 이제 너는 유다 사람들과 예루살렘 주민들에게 말하여 이르기를 여호와의 말씀에 보라 내가 너희에게 재앙을 내리며 계책을 세워 너희를 치려 하노니 너희는 각기 악한 길에서 돌이키며 너희의 길과 행위를 아름답게 하라 하셨다 하라'),
    (19423, '<이스라엘이 가증한 일을 행하다> ○그러므로 여호와께서 이와 같이 말씀하시니라 너희는 누가 이러한 일을 들었는지 여러 나라 가운데 물어보라 처녀 이스라엘이 심히 가증한 일을 행하였도다'),
    (19428, '<예레미야를 죽이려 하다> ○그들이 말하기를 오라 우리가 꾀를 내어 예레미야를 치자 제사장에게서 율법이, 지혜로운 자에게서 책략이, 선지자에게서 말씀이 끊어지지 아니할 것이니 오라 우리가 혀로 그를 치고 그의 어떤 말에도 주의하지 말자 하나이다'),
    (19429, '○여호와여 나를 돌아보사 나와 더불어 다투는 그들의 목소리를 들어 보옵소서'),
    (19430, '어찌 악으로 선을 갚으리이까마는 그들이 나의 생명을 해하려고 구덩이를 팠나이다 내가 주의 분노를 그들에게서 돌이키려 하고 주의 앞에 서서 그들을 위하여 유익한 말을 한 것을 기억하옵소서'),
    (19433, '여호와여 그들이 나를 죽이려 하는 계략을 주께서 다 아시오니 그 악을 사하지 마옵시며 그들의 죄를 주의 목전에서 지우지 마시고 그들을 주 앞에 넘어지게 하시되 주께서 노하시는 때에 이같이 그들에게 행하옵소서 하니라'),
    (19469, '○예레미야가 그들에게 대답하되 너희는 시드기야에게 이같이 말하라'),
    (19470, '이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 보라 너희가 성 밖에서 바벨론의 왕과 또 너희를 에워싼 갈대아인과 싸우는 데 쓰는 너희 손의 무기를 내가 뒤로 돌릴 것이요 그것들을 이 성 가운데 모아들이리라'),
    (19473, '여호와의 말씀이니라 그 후에 내가 유다의 왕 시드기야와 그의 신하들과 백성과 및 이 성읍에서 전염병과 칼과 기근에서 남은 자를 바벨론의 느부갓네살 왕의 손과 그들의 원수의 손과 그들의 생명을 찾는 자들의 손에 넘기리니 그가 칼날로 그들을 치되 측은히 여기지 아니하며 긍휼히 여기지 아니하며 불쌍히 여기지 아니하리라 하셨느니라'),
    (19474, '○여호와께서 말씀하시기를 보라 내가 너희 앞에 생명의 길과 사망의 길을 두었노라 너는 이 백성에게 전하라 하셨느니라'),
    (19477, '<유다 왕의 집에 내린 벌> ○유다 왕의 집에 대한 여호와의 말을 들으라'),
    (19478, '여호와께서 이와 같이 말씀하시니라 다윗의 집이여 너는 아침마다 정의롭게 판결하여 탈취 당한 자를 압박자의 손에서 건지라 그리하지 아니하면 너희의 악행 때문에 내 분노가 불 같이 일어나서 사르리니 능히 끌 자가 없으리라'),
    (19452, '여호와께서 이와 같이 말씀하시되 보라 내가 너로 너와 네 모든 친구에게 두려움이 되게 하리니 그들이 그들의 원수들의 칼에 엎드러질 것이요 네 눈은 그것을 볼 것이며 내가 온 유다를 바벨론 왕의 손에 넘기리니 그가 그들을 사로잡아 바벨론으로 옮겨 칼로 죽이리라'),
    (19455, '<예레미야가 여호와께 사정을 아뢰다> ○여호와여 주께서 나를 권유하시므로 내가 그 권유를 받았사오며 주께서 나보다 강하사 이기셨으므로 내가 조롱 거리가 되니 사람마다 종일토록 나를 조롱하나이다'),
    (19458, '나는 무리의 비방과 사방이 두려워함을 들었나이다 그들이 이르기를 고소하라 우리도 고소하리라 하오며 내 친한 벗도 다 내가 실족하기를 기다리며 그가 혹시 유혹을 받게 되면 우리가 그를 이기어 우리 원수를 갚자 하나이다'),
    (19459, '그러하오나 여호와는 두려운 용사 같으시며 나와 함께 하시므로 나를 박해하는 자들이 넘어지고 이기지 못할 것이오며 그들은 지혜롭게 행하지 못하므로 큰 치욕을 당하오리니 그 치욕은 길이 잊지 못할 것이니이다'),
    (19462, '○내 생일이 저주를 받았더면, 나의 어머니가 나를 낳던 날이 복이 없었더면,'),
    (19436, '말하기를 너희 유다 왕들과 예루살렘 주민아 여호와의 말씀을 들으라 만군의 여호와 이스라엘의 하나님이 이같이 말씀하시되 보라 내가 이 곳에 재앙을 내릴 것이라 그것을 듣는 모든 자의 귀가 떨리니'),
    (19444, '그들에게 이르기를 만군의 여호와께서 이와 같이 말씀하시되 사람이 토기장이의 그릇을 한 번 깨뜨리면 다시 완전하게 할 수 없나니 이와 같이 내가 이 백성과 이 성읍을 무너뜨리리니 도벳에 매장할 자리가 없을 만큼 매장하리라'),
    (19447, '○예레미야가 여호와께서 자기를 보내사 예언하게 하신 도벳에서 돌아와 여호와의 집 뜰에 서서 모든 백성에게 말하되'),
    (19448, '만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 보라 내가 이 성읍에 대하여 선언한 모든 재앙을 이 성읍과 그 모든 촌락에 내리리니 이는 그들의 목을 곧게 하여 내 말을 듣지 아니함이라 하시니라'),
    (19512, '그러므로 이스라엘의 하나님 여호와께서 내 백성을 기르는 목자에게 이와 같이 말씀하시니라 너희가 내 양 떼를 흩으며 그것을 몰아내고 돌보지 아니하였도다 보라 내가 너희의 악행 때문에 너희에게 보응하리라 여호와의 말씀이니라'),
    (19515, '○여호와의 말씀이니라 보라 때가 이르리니 내가 다윗에게 한 의로운 가지를 일으킬 것이라 그가 왕이 되어 지혜롭게 다스리며 세상에서 정의와 공의를 행할 것이며'),
    (19519, '<선지자들에 대한 말씀> ○선지자들에 대한 말씀이라 ○내 마음이 상하며 내 모든 뼈가 떨리며 내가 취한 사람 같으며 포도주에 잡힌 사람 같으니 이는 여호와와 그 거룩한 말씀 때문이라'),
    (19523, '그러므로 그들의 길이 그들에게 어두운 가운데 미끄러운 곳과 같이 되고 그들이 밀어냄을 당하여 그 길에 엎드러질 것이라 그들을 벌하는 해에 내가 그들에게 재앙을 내리리라 여호와의 말씀이니라'),
    (19524, '○내가 사마리아 선지자들 가운데 우매함을 보았나니 그들은 바알을 의지하고 예언하여 내 백성 이스라엘을 그릇되게 하였고'),
    (19525, '내가 예루살렘 선지자들 가운데도 가증한 일을 보았나니 그들은 간음을 행하며 거짓을 말하며 악을 행하는 자의 손을 강하게 하여 사람으로 그 악에서 돌이킴이 없게 하였은즉 그들은 다 내 앞에서 소돔과 다름이 없고 그 주민은 고모라와 다름이 없느니라'),
    (19526, '그러므로 만군의 여호와께서 선지자에 대하여 이와 같이 말씀하시니라 보라 내가 그들에게 쑥을 먹이며 독한 물을 마시게 하리니 이는 사악이 예루살렘 선지자들로부터 나와서 온 땅에 퍼짐이라 하시니라'),
    (19527, '○만군의 여호와께서 이와 같이 말씀하시되 너희에게 예언하는 선지자들의 말을 듣지 말라 그들은 너희에게 헛된 것을 가르치나니 그들이 말한 묵시는 자기 마음으로 말미암은 것이요 여호와의 입에서 나온 것이 아니니라'),
    (19528, '항상 그들이 나를 멸시하는 자에게 이르기를 너희가 평안하리라 여호와의 말씀이니라 하며 또 자기 마음이 완악한 대로 행하는 모든 사람에게 이르기를 재앙이 너희에게 임하지 아니하리라 하였느니라'),
    (19534, '○여호와의 말씀이니라 나는 가까운 데에 있는 하나님이요 먼 데에 있는 하나님은 아니냐'),
    (19543, '여호와의 말씀이니라 보라 거짓 꿈을 예언하여 이르며 거짓과 헛된 자만으로 내 백성을 미혹하게 하는 자를 내가 치리라 내가 그들을 보내지 아니하였으며 명령하지 아니하였나니 그들은 이 백성에게 아무 유익이 없느니라 여호와의 말씀이니라'),
    (19544, '<여호와의 엄중한 말씀> ○이 백성이나 선지자나 제사장이 네게 물어 이르기를 여호와의 엄중한 말씀이 무엇인가 묻거든 너는 그들에게 대답하기를 엄중한 말씀이 무엇이냐 묻느냐 여호와의 말씀에 내가 너희를 버리리라 하셨고'),
    (19549, '너희는 여호와의 엄중한 말씀이라 말하도다 그러므로 여호와께서 이와 같이 말씀하시되 내가 너희에게 사람을 보내어 이 말씀은 여호와의 엄중한 말씀이니 너희는 말하지 말라 하였으나 너희가 여호와의 엄중한 말씀이라 하였은즉'),
    (19483, '여호와께서 이와 같이 말씀하시되 너희가 정의와 공의를 행하여 탈취 당한 자를 압박하는 자의 손에서 건지고 이방인과 고아와 과부를 압제하거나 학대하지 말며 이 곳에서 무죄한 피를 흘리지 말라'),
    (19490, '<살룸 왕에 대하여 말하다> ○너희는 죽은 자를 위하여 울지 말며 그를 위하여 애통하지 말고 잡혀 간 자를 위하여 슬피 울라 그는 다시 돌아와 그 고국을 보지 못할 것임이라'),
    (19493, '<여호야김 왕에 대하여 말하다> ○불의로 그 집을 세우며 부정하게 그 다락방을 지으며 자기의 이웃을 고용하고 그의 품삯을 주지 아니하는 자에게 화 있을진저'),
    (19498, '그러므로 여호와께서 유다의 왕 요시야의 아들 여호야김에게 대하여 이와 같이 말씀하시니라 무리가 그를 위하여 슬프다 내 형제여, 슬프다 내 자매여 하며 통곡하지 아니할 것이며 그를 위하여 슬프다 주여 슬프다 그 영광이여 하며 통곡하지도 아니할 것이라'),
    (19500, '<예루살렘에 대한 탄식> ○너는 레바논에 올라 외치며 바산에서 네 소리를 높이며 아바림에서 외치라 이는 너를 사랑하는 자가 다 멸망하였음이라'),
    (19504, '<여호와께서 고니야 왕을 심판하시다> ○여호와의 말씀이니라 나의 삶으로 맹세하노니 유다 왕 여호야김의 아들 고니야가 나의 오른손의 인장반지라 할지라도 내가 빼어'),
    (19510, '여호와께서 이와 같이 말씀하시니라 너희는 이 사람이 자식이 없겠고 그의 평생 동안 형통하지 못할 자라 기록하라 이는 그의 자손 중 형통하여 다윗의 왕위에 앉아 유다를 다스릴 사람이 다시는 없을 것임이라 하시니라'),
    (19570, '보라 내가 북쪽 모든 종족과 내 종 바벨론의 왕 느부갓네살을 불러다가 이 땅과 그 주민과 사방 모든 나라를 쳐서 진멸하여 그들을 놀램과 비웃음 거리가 되게 하며 땅으로 영원한 폐허가 되게 할 것이라 여호와의 말씀이니라'),
    (19573, '○여호와의 말씀이니라 칠십 년이 끝나면 내가 바벨론의 왕과 그의 나라와 갈대아인의 땅을 그 죄악으로 말미암아 벌하여 영원히 폐허가 되게 하되'),
    (19576, '<모든 나라에 내리는 진노의 술잔> ○이스라엘의 하나님 여호와께서 이같이 내게 이르시되 너는 내 손에서 이 진노의 술잔을 받아가지고 내가 너를 보내는 바 그 모든 나라로 하여금 마시게 하라'),
    (19588, '○너는 그들에게 이르기를 만군의 여호와 이스라엘의 하나님의 말씀에 너희는 내가 너희 가운데 보내는 칼 앞에서 마시며 취하여 토하고 엎드러져 다시는 일어나지 말아라 하셨느니라'),
    (19590, '보라 내가 내 이름으로 일컬음을 받는 성에서부터 재앙 내리기를 시작하였은즉 너희가 어찌 능히 형벌을 면할 수 있느냐 면하지 못하리니 이는 내가 칼을 불러 세상의 모든 주민을 칠 것임이라 하셨다 하라 만군의 여호와의 말씀이니라'),
    (19591, '○그러므로 너는 그들에게 이 모든 말로 예언하여 이르기를 여호와께서 높은 데서 포효하시고 그의 거룩한 처소에서 소리를 내시며 그의 초장을 향하여 크게 부르시고 세상 모든 주민에 대하여 포도 밟는 자 같이 흥겹게 노래하시리라'),
    (19593, '○만군의 여호와께서 이와 같이 말씀하시니라 보라 재앙이 나서 나라에서 나라에 미칠 것이며 큰 바람이 땅 끝에서 일어날 것이라'),
    (19594, '그 날에 여호와에게 죽임을 당한 자가 땅 이 끝에서 땅 저 끝에 미칠 것이나 그들을 위하여 애곡하는 자도 없고 시신을 거두어 주는 자도 없고 매장하여 주는 자도 없으리니 그들은 지면에서 분토가 되리로다'),
    (19601, '여호와께서 이와 같이 말씀하시니라 너는 여호와의 성전 뜰에 서서 유다 모든 성읍에서 여호와의 성전에 와서 예배하는 자에게 내가 네게 명령하여 이르게 한 모든 말을 전하되 한 마디도 감하지 말라'),
    (19607, '○예레미야가 여호와께서 명령하신 말씀을 모든 백성에게 전하기를 마치매 제사장들과 선지자들과 모든 백성이 그를 붙잡고 이르되 네가 반드시 죽어야 하리라'),
    (19608, '어찌하여 네가 여호와의 이름을 의지하고 예언하여 이르기를 이 성전이 실로 같이 되겠고 이 성이 황폐하여 주민이 없으리라 하느냐 하며 그 모든 백성이 여호와의 성전에서 예레미야를 향하여 모여드니라'),
    (19609, '○유다의 고관들이 이 말을 듣고 왕궁에서 여호와의 성전으로 올라가 여호와의 성전 새 대문의 입구에 앉으매'),
    (19614, '너희는 분명히 알아라 너희가 나를 죽이면 반드시 무죄한 피를 너희 몸과 이 성과 이 성 주민에게 돌리는 것이니라 이는 여호와께서 진실로 나를 보내사 이 모든 말을 너희 귀에 말하게 하셨음이라'),
    (19615, '○고관들과 모든 백성이 제사장들과 선지자들에게 이르되 이 사람이 우리 하나님 여호와의 이름으로 우리에게 말하였으니 죽일 만한 이유가 없느니라'),
    (19617, '유다의 왕 히스기야 시대에 모레셋 사람 미가가 유다의 모든 백성에게 예언하여 이르되 만군의 여호와께서 이와 같이 말씀하셨느니라 시온은 밭 같이 경작지가 될 것이며 예루살렘은 돌 무더기가 되며 이 성전의 산은 산당의 숲과 같이 되리라 하였으나'),
    (19618, '유다의 왕 히스기야와 모든 유다가 그를 죽였느냐 히스기야가 여호와를 두려워하여 여호와께 간구하매 여호와께서 그들에게 선언한 재앙에 대하여 뜻을 돌이키지 아니하셨느냐 우리가 이같이 하면 우리의 생명을 스스로 심히 해롭게 하는 것이니라'),
    (19619, '○또 여호와의 이름으로 예언한 사람이 있었는데 곧 기럇여아림 스마야의 아들 우리야라 그가 예레미야의 모든 말과 같이 이 성과 이 땅에 경고하여 예언하매'),
    (19627, '그들에게 명령하여 그들의 주에게 말하게 하기를 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희는 너희의 주에게 이같이 전하라'),
    (19631, '여호와의 말씀이니라 바벨론의 왕 느부갓네살을 섬기지 아니하며 그 목으로 바벨론의 왕의 멍에를 메지 아니하는 백성과 나라는 내가 그들이 멸망하기까지 칼과 기근과 전염병으로 그 민족을 벌하리라'),
    (19635, '○내가 이 모든 말씀대로 유다의 왕 시드기야에게 전하여 이르되 왕과 백성은 바벨론 왕의 멍에를 목에 메고 그와 그의 백성을 섬기소서 그리하면 사시리라'),
    (19639, '○내가 또 제사장들과 그 모든 백성에게 전하여 이르되 여호와께서 이와 같이 말씀하시기를 보라 여호와의 성전의 기구를 이제 바벨론에서 속히 돌려오리라고 너희에게 예언하는 선지자들의 말을 듣지 말라 이는 그들이 거짓을 예언함이니라 하셨나니'),
    (19641, '만일 그들이 선지자이고 여호와의 말씀을 가지고 있다면 그들이 여호와의 성전에와 유다의 왕의 궁전에와 예루살렘에 남아 있는 기구를 바벨론으로 옮겨가지 못하도록 만군의 여호와께 구하여야 할 것이니라'),
    (19552, '<좋은 무화과 나쁜 무화과> 바벨론의 느부갓네살 왕이 유다 왕 여호야김의 아들 여고냐와 유다 고관들과 목공들과 철공들을 예루살렘에서 바벨론으로 옮긴 후에 여호와께서 여호와의 성전 앞에 놓인 무화과 두 광주리를 내게 보이셨는데'),
    (19555, '○여호와의 말씀이 또 내게 임하니라 이르시되'),
    (19559, '○여호와께서 이와 같이 말씀하시니라 내가 유다의 왕 시드기야와 그 고관들과 예루살렘의 남은 자로서 이 땅에 남아 있는 자와 애굽 땅에 사는 자들을 나빠서 먹을 수 없는 이 나쁜 무화과 같이 버리되'),
    (19646, '<예레미야와 하나냐> 그 해 곧 유다 왕 시드기야가 다스리기 시작한 지 사 년 다섯째 달 기브온앗술의 아들 선지자 하나냐가 여호와의 성전에서 제사장들과 모든 백성이 보는 앞에서 내게 말하여 이르되'),
    (19649, '내가 또 유다의 왕 여호야김의 아들 여고니야와 바벨론으로 간 유다 모든 포로를 다시 이 곳으로 돌아오게 하리니 이는 내가 바벨론의 왕의 멍에를 꺾을 것임이라 여호와의 말씀이니라 하시니라'),
    (19656, '모든 백성 앞에서 하나냐가 말하여 이르되 여호와께서 이와 같이 말씀하시니라 내가 이 년 안에 모든 민족의 목에서 바벨론의 왕 느부갓네살의 멍에를 이와 같이 꺾어 버리리라 하셨느니라 하매 선지자 예레미야가 자기의 길을 가니라'),
    (19657, '○선지자 하나냐가 선지자 예레미야의 목에서 멍에를 꺾어 버린 후에 여호와의 말씀이 예레미야에게 임하니라 이르시기를'),
    (19659, '만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 내가 쇠 멍에로 이 모든 나라의 목에 메워 바벨론의 왕 느부갓네살을 섬기게 하였으니 그들이 그를 섬기리라 내가 들짐승도 그에게 주었느니라 하라'),
    (19661, '그러므로 여호와께서 이와 같이 말씀하시되 내가 너를 지면에서 제하리니 네가 여호와께 패역한 말을 하였음이라 네가 금년에 죽으리라 하셨느니라 하더니'),
    (19697, '여호와의 말씀이니라 보라 내가 내 백성 이스라엘과 유다의 포로를 돌아가게 할 날이 오리니 내가 그들을 그 조상들에게 준 땅으로 돌아오게 할 것이니 그들이 그 땅을 차지하리라 여호와께서 말씀하시니라'),
    (19698, '○여호와께서 이스라엘과 유다에 대하여 하신 말씀이 이러하니라'),
    (19704, '여호와의 말씀이니라 그러므로 나의 종 야곱아 너는 두려워하지 말라 이스라엘아 놀라지 말라 내가 너를 먼 곳으로부터 구원하고 네 자손을 잡혀가 있는 땅에서 구원하리니 야곱이 돌아와서 태평과 안락을 누릴 것이며 두렵게 할 자가 없으리라'),
    (19705, '이는 여호와의 말씀이라 내가 너와 함께 있어 너를 구원할 것이라 너를 흩었던 그 모든 이방을 내가 멸망시키리라 그럴지라도 너만은 멸망시키지 아니하리라 그러나 내가 법에 따라 너를 징계할 것이요 결코 무죄한 자로만 여기지는 아니하리라'),
    (19706, '○여호와께서 이와 같이 말씀하시니라 네 상처는 고칠 수 없고 네 부상은 중하도다'),
    (19712, '○여호와께서 말씀하시니라 보라 내가 야곱 장막의 포로들을 돌아오게 할 것이고 그 거처들에 사랑을 베풀 것이라 성읍은 그 폐허가 된 언덕 위에 건축될 것이요 그 보루는 규정에 따라 사람이 살게 되리라'),
    (19713, '그들에게서 감사하는 소리가 나오고 즐거워하는 자들의 소리가 나오리라 내가 그들을 번성하게 하리니 그들의 수가 줄어들지 아니하겠고 내가 그들을 존귀하게 하리니 그들은 비천하여지지 아니하리라'),
    (19715, '그 영도자는 그들 중에서 나올 것이요 그 통치자도 그들 중에서 나오리라 내가 그를 가까이 오게 하리니 그가 내게 가까이 오리라 참으로 담대한 마음으로 내게 가까이 올 자가 누구냐 여호와의 말씀이니라'),
    (19717, '○보라 여호와의 노여움이 일어나 폭풍과 회오리바람처럼 악인의 머리 위에서 회오리칠 것이라'),
    (19761, '이는 그가 예언하기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 차지할 것이며 유다 왕 시드기야는 갈대아인의 손에서 벗어나지 못하고 반드시 바벨론 왕의 손에 넘겨진 바 되리니'),
    (19762, '○예레미야가 이르되 여호와의 말씀이 내게 임하였느니라 이르시기를'),
    (19764, '여호와의 말씀과 같이 나의 숙부의 아들 하나멜이 시위대 뜰 안 나에게 와서 이르되 청하노니 너는 베냐민 땅 아나돗에 있는 나의 밭을 사라 기업의 상속권이 네게 있고 무를 권리가 네게 있으니 너를 위하여 사라 하는지라 내가 이것이 여호와의 말씀인 줄 알았으므로'),
    (19772, '<예레미야의 기도> ○내가 매매 증서를 네리야의 아들 바룩에게 넘겨 준 뒤에 여호와께 기도하여 이르되'),
    (19779, '그들이 들어가서 이를 차지하였거늘 주의 목소리를 순종하지 아니하며 주의 율법에서 행하지 아니하며 무릇 주께서 행하라 명령하신 일을 행하지 아니하였으므로 주께서 이 모든 재앙을 그들에게 내리셨나이다'),
    (19780, '보옵소서 이 성을 빼앗으려고 만든 참호가 이 성에 이르렀고 칼과 기근과 전염병으로 말미암아 이 성이 이를 치는 갈대아인의 손에 넘긴 바 되었으니 주의 말씀대로 되었음을 주께서 보시나이다'),
    (19782, '○그 때에 여호와의 말씀이 예레미야에게 임하여 이르시되'),
    (19788, '이는 이스라엘 자손과 유다 자손이 모든 악을 행하여 내 노여움을 일으켰음이라 그들과 그들의 왕들과 그의 고관들과 그의 제사장들과 그의 선지자들과 유다 사람들과 예루살렘 주민들이 다 그러하였느니라'),
    (19791, '힌놈의 아들의 골짜기에 바알의 산당을 건축하였으며 자기들의 아들들과 딸들을 몰렉 앞으로 지나가게 하였느니라 그들이 이런 가증한 일을 행하여 유다로 범죄하게 한 것은 내가 명령한 것도 아니요 내 마음에 둔 것도 아니니라'),
    (19792, '<영원한 언약> ○그러나 이스라엘의 하나님 여호와께서 너희가 말하는 바 칼과 기근과 전염병으로 말미암아 바벨론 왕의 손에 넘긴 바 되었다 하는 이 성에 대하여 이와 같이 말씀하시니라'),
    (19800, '베냐민 땅과 예루살렘 사방과 유다 성읍들과 산지의 성읍들과 저지대의 성읍들과 네겝의 성읍들에 있는 밭을 은으로 사고 증서를 기록하여 봉인하고 증인을 세우리니 이는 내가 그들의 포로를 돌아오게 함이니라 여호와의 말씀이니라'),
    (19725, '○여호와께서 이와 같이 말씀하시니라 너희는 여러 민족의 앞에 서서 야곱을 위하여 기뻐 외치라 너희는 전파하며 찬양하며 말하라 여호와여 주의 백성 이스라엘의 남은 자를 구원하소서 하라'),
    (19728, '○이방들이여 너희는 여호와의 말씀을 듣고 먼 섬에 전파하여 이르기를 이스라엘을 흩으신 자가 그를 모으시고 목자가 그 양 떼에게 행함 같이 그를 지키시리로다'),
    (19730, '그들이 와서 시온의 높은 곳에서 찬송하며 여호와의 복 곧 곡식과 새 포도주와 기름과 어린 양의 떼와 소의 떼를 얻고 크게 기뻐하리라 그 심령은 물 댄 동산 같겠고 다시는 근심이 없으리로다 할지어다'),
    (19733, '<라헬의 애곡과 여호와의 위로> ○여호와께서 이와 같이 말씀하시니라 라마에서 슬퍼하며 통곡하는 소리가 들리니 라헬이 그 자식 때문에 애곡하는 것이라 그가 자식이 없어져서 위로 받기를 거절하는도다'),
    (19736, '에브라임이 스스로 탄식함을 내가 분명히 들었노니 주께서 나를 징벌하시매 멍에에 익숙하지 못한 송아지 같은 내가 징벌을 받았나이다 주는 나의 하나님 여호와이시니 나를 이끌어 돌이키소서 그리하시면 내가 돌아오겠나이다'),
    (19738, '에브라임은 나의 사랑하는 아들 기뻐하는 자식이 아니냐 내가 그를 책망하여 말할 때마다 깊이 생각하노라 그러므로 그를 위하여 내 창자가 들끓으니 내가 반드시 그를 불쌍히 여기리라 여호와의 말씀이니라'),
    (19739, '○처녀 이스라엘아 너의 이정표를 세우며 너의 푯말을 만들고 큰 길 곧 네가 전에 가던 길을 마음에 두라 돌아오라 네 성읍들로 돌아오라'),
    (19741, '<사로잡힌 자를 돌아오게 할 때> ○만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 내가 그 사로잡힌 자를 돌아오게 할 때에 그들이 유다 땅과 그 성읍들에서 다시 이 말을 쓰리니 곧 의로운 처소여, 거룩한 산이여, 여호와께서 네게 복 주시기를 원하노라 할 것이며'),
    (19745, '○여호와의 말씀이니라 보라 내가 사람의 씨와 짐승의 씨를 이스라엘 집과 유다 집에 뿌릴 날이 이르리니'),
    (19749, '<새 언약> ○여호와의 말씀이니라 보라 날이 이르리니 내가 이스라엘 집과 유다 집에 새 언약을 맺으리라'),
    (19751, '그러나 그 날 후에 내가 이스라엘 집과 맺을 언약은 이러하니 곧 내가 나의 법을 그들의 속에 두며 그들의 마음에 기록하여 나는 그들의 하나님이 되고 그들은 내 백성이 될 것이라 여호와의 말씀이니라'),
    (19752, '그들이 다시는 각기 이웃과 형제를 가리켜 이르기를 너는 여호와를 알라 하지 아니하리니 이는 작은 자로부터 큰 자까지 다 나를 알기 때문이라 내가 그들의 악행을 사하고 다시는 그 죄를 기억하지 아니하리라 여호와의 말씀이니라'),
    (19753, '○여호와께서 이와 같이 말씀하셨느니라 그는 해를 낮의 빛으로 주셨고 달과 별들을 밤의 빛으로 정하였고 바다를 뒤흔들어 그 파도로 소리치게 하나니 그의 이름은 만군의 여호와니라'),
    (19755, '여호와께서 이와 같이 말씀하시니라 위에 있는 하늘을 측량할 수 있으며 밑에 있는 땅의 기초를 탐지할 수 있다면 내가 이스라엘 자손이 행한 모든 일로 말미암아 그들을 다 버리리라 여호와의 말씀이니라'),
    (19756, '○보라, 날이 이르리니 이 성은 하나넬 망대로부터 모퉁이에 이르기까지 여호와를 위하여 건축될 것이라 여호와의 말씀이니라'),
    (19663, '<포로에게 보낸 예레미야의 편지> 선지자 예레미야가 예루살렘에서 이같은 편지를 느부갓네살이 예루살렘에서 바벨론으로 끌고 간 포로 중 남아 있는 장로들과 제사장들과 선지자들과 모든 백성에게 보냈는데'),
    (19670, '만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 너희 중에 있는 선지자들에게와 점쟁이에게 미혹되지 말며 너희가 꾼 꿈도 곧이 듣고 믿지 말라'),
    (19676, '이것은 여호와의 말씀이니라 나는 너희들을 만날 것이며 너희를 포로된 중에서 다시 돌아오게 하되 내가 쫓아 보내었던 나라들과 모든 곳에서 모아 사로잡혀 떠났던 그 곳으로 돌아오게 하리라 이것은 여호와의 말씀이니라'),
    (19677, '○너희가 말하기를 여호와께서 우리를 위하여 바벨론에서 선지자를 일으키셨느니라'),
    (19680, '내가 칼과 기근과 전염병으로 그들을 뒤따르게 하며 그들을 세계 여러 나라 가운데에 흩어 학대를 당하게 할 것이며 내가 그들을 쫓아낸 나라들 가운데에서 저주와 경악과 조소와 수모의 대상이 되게 하리라'),
    (19683, '만군의 여호와 이스라엘의 하나님께서 골라야의 아들 아합과 마아세야의 아들 시드기야에 대하여 이와 같이 말씀하시니라 그들은 내 이름으로 너희에게 거짓을 예언한 자라 보라 내가 그들을 바벨론의 왕 느부갓네살의 손에 넘기리니 그가 너희 눈 앞에서 그들을 죽일 것이라'),
    (19685, '이는 그들이 이스라엘 중에서 어리석게 행하여 그 이웃의 아내와 간음하며 내가 그들에게 명령하지 아니한 거짓을 내 이름으로 말함이라 나는 알고 있는 자로서 증인이니라 여호와의 말씀이니라 하시니라'),
    (19686, '<스마야에게 보낸 편지와 여호와의 말씀> ○너는 느헬람 사람 스마야에게 이같이 말하여 이르라'),
    (19688, '여호와께서 너를 제사장 여호야다를 대신하여 제사장을 삼아 여호와의 성전 감독자로 세우심은 모든 미친 자와 선지자 노릇을 하는 자들을 목에 씌우는 나무 고랑과 목에 씌우는 쇠 고랑을 채우게 하심이어늘'),
    (19693, '너는 모든 포로에게 전언하여 이르기를 여호와께서 느헬람 사람 스마야를 두고 이같이 말씀하셨느니라 내가 그를 보내지 아니하였거늘 스마야가 너희에게 예언하고 너희에게 거짓을 믿게 하였도다'),
    (19694, '그러므로 여호와께서 이와 같이 말씀하시니라 보라 내가 느헬람 사람 스마야와 그의 자손을 벌하리니 그가 나 여호와께 패역한 말을 하였기 때문에 이 백성 중에 살아 남을 그의 자손이 하나도 없을 것이라 내가 내 백성에게 행하려 하는 복된 일을 그가 보지 못하리라 하셨느니라 이것은 여호와의 말씀이니라'),
    (19826, '<시드기야 왕에 대한 말씀> 바벨론의 느부갓네살 왕과 그의 모든 군대와 그의 통치하에 있는 땅의 모든 나라와 모든 백성이 예루살렘과 그 모든 성읍을 칠 때에 말씀이 여호와께로부터 예레미야에게 임하여 이르시되'),
    (19827, '이스라엘의 하나님 여호와께서 이와 같이 말씀하시니라 너는 가서 유다의 시드기야 왕에게 아뢰어 이르기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 이 성을 불사를 것이라'),
    (19830, '평안히 죽을 것이며 사람이 너보다 먼저 있은 네 조상들 곧 선왕들에게 분향하던 것 같이 네게 분향하며 너를 위하여 애통하기를 슬프다 주여 하리니 이는 내가 말하였음이라 여호와의 말씀이니라 하시니라'),
    (19831, '○선지자 예레미야가 이 모든 말씀을 예루살렘에서 유다의 시드기야 왕에게 아뢰니라'),
    (19833, '<여호와 앞에서 맺은 계약을 어기다> ○시드기야 왕이 예루살렘에 있는 모든 백성과 한 가지로 하나님 앞에서 계약을 맺고 자유를 선포한 후에 여호와께로부터 말씀이 예레미야에게 임하니라'),
    (19837, '○그러므로 여호와의 말씀이 여호와께로부터 예레미야에게 임하니라 이르시되'),
    (19839, '너희 형제 히브리 사람이 네게 팔려 왔거든 너희는 칠 년 되는 해에 그를 놓아 줄 것이니라 그가 육 년 동안 너를 섬겼은즉 그를 놓아 자유롭게 할지니라 하였으나 너희 선조가 내게 순종하지 아니하며 귀를 기울이지도 아니하였느니라'),
    (19842, '○그러므로 여호와께서 이와 같이 말씀하시니라 너희가 나에게 순종하지 아니하고 각기 형제와 이웃에게 자유를 선포한 것을 실행하지 아니하였은즉 내가 너희를 대적하여 칼과 전염병과 기근에게 자유를 주리라 여호와의 말씀이니라 내가 너희를 세계 여러 나라 가운데에 흩어지게 할 것이며'),
    (19859, '○그 때에 여호와의 말씀이 예레미야에게 임하여 이르시되'),
    (19861, '레갑의 아들 요나답이 그의 자손에게 포도주를 마시지 말라 한 그 명령은 실행되도다 그들은 그 선조의 명령을 순종하여 오늘까지 마시지 아니하거늘 내가 너희에게 말하고 끊임없이 말하여도 너희는 내게 순종하지 아니하도다'),
    (19862, '내가 내 종 모든 선지자를 너희에게 보내고 끊임없이 보내며 이르기를 너희는 이제 각기 악한 길에서 돌이켜 행위를 고치고 다른 신을 따라 그를 섬기지 말라 그리하면 너희는 내가 너희와 너희 선조에게 준 이 땅에 살리라 하여도 너희가 귀를 기울이지 아니하며 내게 순종하지 아니하였느니라'),
    (19864, '그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 유다와 예루살렘의 모든 주민에게 내가 그들에게 대하여 선포한 모든 재앙을 내리리니 이는 내가 그들에게 말하여도 듣지 아니하며 불러도 대답하지 아니함이니라 하셨다 하라'),
    (19865, '○예레미야가 레갑 사람의 가문에게 이르되 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시기를 너희가 너희 선조 요나답의 명령을 순종하여 그의 모든 규율을 지키며 그가 너희에게 명령한 것을 행하였도다'),
    (19805, '싸우려 하였으나 내가 나의 노여움과 분함으로 그들을 죽이고 그들의 시체로 이 성을 채우게 하였나니 이는 그들의 모든 악행으로 말미암아 나의 얼굴을 가리어 이 성을 돌아보지 아니하였음이라'),
    (19809, '이 성읍이 세계 열방 앞에서 나의 기쁜 이름이 될 것이며 찬송과 영광이 될 것이요 그들은 내가 이 백성에게 베푼 모든 복을 들을 것이요 내가 이 성읍에 베푼 모든 복과 모든 평안으로 말미암아 두려워하며 떨리라'),
    (19810, '○여호와께서 이와 같이 말씀하시니라 너희가 가리켜 말하기를 황폐하여 사람도 없고 짐승도 없다 하던 여기 곧 황폐하여 사람도 없고 주민도 없고 짐승도 없던 유다 성읍들과 예루살렘 거리에서 즐거워하는 소리, 기뻐하는 소리, 신랑의 소리, 신부의 소리와 및 만군의 여호와께 감사하라, 여호와는 선하시니 그 인자하심이 영원하다 하는 소리와 여호와의 성전에 감사제를 드리는 자들의 소리가 다시 들리리니 이는 내가 이 땅의 포로를 돌려보내어 지난 날처럼 되게 할 것임이라 여호와의 말씀이니라'),
    (19811, '○만군의 여호와께서 이와 같이 말씀하시니라 황폐하여 사람도 없고 짐승도 없던 이 곳과 그 모든 성읍에 다시 목자가 살 곳이 있으리니 그의 양 떼를 눕게 할 것이라'),
    (19813, '○여호와의 말씀이니라 보라 내가 이스라엘 집과 유다 집에 대하여 일러 준 선한 말을 성취할 날이 이르리라'),
    (19818, '○여호와의 말씀이 예레미야에게 임하니라 이르시되'),
    (19822, '○여호와의 말씀이 예레미야에게 임하니라 이르시되'),
    (19899, '<느부갓네살이 시드기야를 유다 왕으로 삼다> 요시야의 아들 시드기야가 여호야김의 아들 고니야의 뒤를 이어 왕이 되었으니 이는 바벨론의 느부갓네살 왕이 그를 유다 땅의 왕으로 삼음이었더라'),
    (19901, '○시드기야 왕이 셀레먀의 아들 여후갈과 마아세야의 아들 제사장 스바냐를 선지자 예레미야에게 보내 청하되 너는 우리를 위하여 우리 하나님 여호와께 기도하라 하였으니'),
    (19904, '○여호와의 말씀이 선지자 예레미야에게 임하여 이르시되'),
    (19909, '<예레미야를 붙잡아 가두다> ○갈대아인의 군대가 바로의 군대를 두려워하여 예루살렘에서 떠나매'),
    (19914, '○예레미야가 뚜껑 씌운 웅덩이에 들어간 지 여러 날 만에'),
    (19915, '시드기야 왕이 사람을 보내어 그를 이끌어내고 왕궁에서 그에게 비밀히 물어 이르되 여호와께로부터 받은 말씀이 있느냐 예레미야가 대답하되 있나이다 또 이르되 왕이 바벨론의 왕의 손에 넘겨지리이다'),
    (19923, '이에 그 고관들이 왕께 아뢰되 이 사람이 백성의 평안을 구하지 아니하고 재난을 구하오니 청하건대 이 사람을 죽이소서 그가 이같이 말하여 이 성에 남은 군사의 손과 모든 백성의 손을 약하게 하나이다'),
    (19925, '그들이 예레미야를 끌어다가 감옥 뜰에 있는 왕의 아들 말기야의 구덩이에 던져 넣을 때에 예레미야를 줄로 달아내렸는데 그 구덩이에는 물이 없고 진창뿐이므로 예레미야가 진창 속에 빠졌더라'),
    (19926, '○왕궁 내시 구스인 에벳멜렉이 그들이 예레미야를 구덩이에 던져 넣었음을 들으니라 그 때에 왕이 베냐민 문에 앉았더니'),
    (19933, '<시드기야가 예레미야에게 묻다> ○시드기야 왕이 사람을 보내어 선지자 예레미야를 여호와의 성전 셋째 문으로 데려오게 하고 왕이 예레미야에게 이르되 내가 네게 한 가지 일을 물으리니 한 마디도 내게 숨기지 말라'),
    (19935, '시드기야 왕이 비밀히 예레미야에게 맹세하여 이르되 우리에게 이 영혼을 지으신 여호와께서 살아 계심을 두고 맹세하노니 내가 너를 죽이지도 아니하겠으며 네 생명을 찾는 그 사람들의 손에 넘기지도 아니하리라 하는지라'),
    (19936, '○예레미야가 시드기야에게 이르되 만군의 하나님이신 이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 네가 만일 바벨론의 왕의 고관들에게 항복하면 네 생명이 살겠고 이 성이 불사름을 당하지 아니하겠고 너와 네 가족이 살려니와'),
    (19941, '보라 곧 유다 왕궁에 남아 있는 모든 여자가 바벨론 왕의 고관들에게로 끌려갈 것이요 그 여자들은 네게 말하기를 네 친구들이 너를 꾀어 이기고 네 발이 진흙에 빠짐을 보고 물러갔도다 하리라'),
    (19943, '○시드기야가 예레미야에게 이르되 너는 이 말을 어느 사람에게도 알리지 말라 그리하면 네가 죽지 아니하리라'),
    (19944, '만일 고관들이 내가 너와 말하였다 함을 듣고 와서 네게 말하기를 네가 왕에게 말씀한 것을 우리에게 전하라 우리에게 숨기지 말라 그리하면 우리가 너를 죽이지 아니하리라 또 왕이 네게 말씀한 것을 전하라 하거든'),
    (19870, '○이에 예레미야가 네리야의 아들 바룩을 부르매 바룩이 예레미야가 불러 주는 대로 여호와께서 그에게 이르신 모든 말씀을 두루마리 책에 기록하니라'),
    (19875, '○유다의 요시야 왕의 아들 여호야김의 제오년 구월에 예루살렘 모든 백성과 유다 성읍들에서 예루살렘에 이른 모든 백성이 여호와 앞에서 금식을 선포한지라'),
    (19877, '<바룩이 고관 앞에서 두루마리를 낭독하다> ○사반의 손자요 그마랴의 아들인 미가야가 그 책에 기록된 여호와의 말씀을 다 듣고'),
    (19878, '왕궁에 내려가서 서기관의 방에 들어가니 모든 고관 곧 서기관 엘리사마와 스마야의 아들 들라야와 악볼의 아들 엘라단과 사반의 아들 그마랴와 하나냐의 아들 시드기야와 모든 고관이 거기에 앉아 있는지라'),
    (19880, '이에 모든 고관이 구시의 증손 셀레먀의 손자 느다냐의 아들 여후디를 바룩에게 보내 이르되 너는 백성의 귀에 낭독한 두루마리를 손에 가지고 오라 네리야의 아들 바룩이 두루마리를 손에 가지고 그들에게로 오니'),
    (19886, '<왕이 두루마리를 태우다> ○그들이 두루마리를 서기관 엘리사마의 방에 두고 뜰에 들어가 왕께 나아가서 이 모든 말을 왕의 귀에 아뢰니'),
    (19889, '여후디가 서너 쪽을 낭독하면 왕이 칼로 그것을 연하여 베어 화로 불에 던져서 두루마리를 모두 태웠더라'),
    (19893, '<예레미야가 말씀을 다시 쓰다> ○왕이 두루마리와 바룩이 예레미야의 입을 통해 기록한 말씀을 불사른 후에 여호와의 말씀이 예레미야에게 임하니라 이르시되'),
    (19895, '또 유다의 여호야김 왕에 대하여 이와 같이 말하기를 여호와의 말씀에 네가 이 두루마리를 불사르며 말하기를 네가 어찌하여 바벨론의 왕이 반드시 와서 이 땅을 멸하고 사람과 짐승을 이 땅에서 없어지게 하리라 하는 말을 이 두루마리에 기록하였느냐 하도다'),
    (19897, '또 내가 그와 그의 자손과 신하들을 그들의 죄악으로 말미암아 벌할 것이라 내가 일찍이 그들과 예루살렘 주민과 유다 사람에게 그 모든 재난을 내리리라 선포하였으나 그들이 듣지 아니하였느니라'),
    (19898, '이에 예레미야가 다른 두루마리를 가져다가 네리야의 아들 서기관 바룩에게 주매 그가 유다의 여호야김 왕이 불사른 책의 모든 말을 예레미야가 전하는 대로 기록하고 그 외에도 그 같은 말을 많이 더 하였더라'),
    (19969, '보라 내가 오늘 네 손의 사슬을 풀어 너를 풀어 주노니 만일 네가 나와 함께 바벨론으로 가는 것을 좋게 여기거든 가자 내가 너를 선대하리라 만일 나와 함께 바벨론으로 가는 것을 좋지 않게 여기거든 그만 두라 보라 온 땅이 네 앞에 있나니 네가 좋게 여기는 대로 옳게 여기는 곳으로 갈지니라 하니라'),
    (19970, '예레미야가 아직 돌이키기 전에 그가 다시 이르되 너는 바벨론의 왕이 유다 성읍들을 맡도록 세운 사반의 손자 아히감의 아들 그다랴에게로 돌아가서 그와 함께 백성 가운데 살거나 네가 옳게 여기는 곳으로 가거나 할지니라 하고 그 사령관이 그에게 양식과 선물을 주어 보내매'),
    (19971, '예레미야가 미스바로 가서 아히감의 아들 그다랴에게로 나아가서 그 땅에 남아 있는 백성 가운데서 그와 함께 사니라'),
    (19972, '<유다 총독 그다랴> ○들에 있는 모든 지휘관과 그 부하들이 바벨론의 왕이 아히감의 아들 그다랴에게 그 땅을 맡기고 남녀와 유아와 바벨론으로 잡혀가지 아니한 빈민을 그에게 위임하였다 함을 듣고'),
    (19973, '그들 곧 느다냐의 아들 이스마엘과 가레아의 두 아들 요하난과 요나단과 단후멧의 아들 스라야와 느도바 사람 에배의 아들들과 마아가 사람의 아들 여사냐와 그들의 사람들이 미스바로 가서 그다랴에게 이르니'),
    (19974, '사반의 손자 아히감의 아들 그다랴가 그들과 그들의 사람들에게 맹세하며 이르되 너희는 갈대아 사람을 섬기기를 두려워하지 말고 이 땅에 살면서 바벨론의 왕을 섬기라 그리하면 너희에게 유익하리라'),
    (19978, '<그다랴 총독을 죽이다> ○가레아의 아들 요하난과 들에 있던 모든 군 지휘관들이 미스바에 사는 그다랴에게 이르러'),
    (19980, '가레아의 아들 요하난이 미스바에서 그다랴에게 비밀히 말하여 이르되 청하노니 내가 가서 사람이 모르게 느다냐의 아들 이스마엘을 죽이게 하라 어찌하여 그가 네 생명을 빼앗게 하여 네게 모인 모든 유다 사람을 흩어지게 하며 유다의 남은 자로 멸망을 당하게 하랴 하니라'),
    (20022, '<예레미야가 애굽으로 가다> 예레미야가 모든 백성에게 그들의 하나님 여호와의 말씀 곧 그들의 하나님 여호와께서 자기를 보내사 그들에게 이르신 이 모든 말씀을 말하기를 마치니'),
    (20023, '호사야의 아들 아사랴와 가레아의 아들 요하난과 모든 오만한 자가 예레미야에게 말하기를 네가 거짓을 말하는도다 우리 하나님 여호와께서 너희는 애굽에서 살려고 그리로 가지 말라고 너를 보내어 말하게 하지 아니하셨느니라'),
    (20029, '○다바네스에서 여호와의 말씀이 예레미야에게 임하여 이르시되'),
    (20031, '그리고 너는 그들에게 말하기를 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 보라 내가 내 종 바벨론의 느부갓네살 왕을 불러오리니 그가 그의 왕좌를 내가 감추게 한 이 돌들 위에 놓고 또 그 화려한 큰 장막을 그 위에 치리라'),
    (20034, '그가 또 애굽 땅 벧세메스의 석상들을 깨뜨리고 애굽 신들의 신당들을 불사르리라 하셨다 할지니라 하시니라'),
    (19948, '<예루살렘이 함락되다> 유다의 시드기야 왕의 제구년 열째 달에 바벨론의 느부갓네살 왕과 그의 모든 군대가 와서 예루살렘을 에워싸고 치더니'),
    (19951, '○유다의 시드기야 왕과 모든 군사가 그들을 보고 도망하되 밤에 왕의 동산 길을 따라 두 담 샛문을 통하여 성읍을 벗어나서 아라바로 갔더니'),
    (19952, '갈대아인의 군대가 그들을 따라 여리고 평원에서 시드기야에게 미쳐 그를 잡아서 데리고 하맛 땅 리블라에 있는 바벨론의 느부갓네살 왕에게로 올라가매 왕이 그를 심문하였더라'),
    (19953, '바벨론의 왕이 리블라에서 시드기야의 눈 앞에서 그의 아들들을 죽였고 왕이 또 유다의 모든 귀족을 죽였으며'),
    (19958, '<예레미야가 석방되다> ○바벨론의 느부갓네살 왕이 예레미야에 대하여 사령관 느부사라단에게 명령하여 이르되'),
    (19962, '<여호와께서 에벳멜렉에게 구원을 약속하시다> ○예레미야가 감옥 뜰에 갇혔을 때에 여호와의 말씀이 그에게 임하니라 이르시되'),
    (19985, '○그가 그다랴를 죽인 지 이틀이 되었어도 이를 아는 사람이 없었더라'),
    (19990, '이스마엘이 그다랴에게 속한 사람들을 죽이고 그 시체를 던진 구덩이는 아사 왕이 이스라엘의 바아사 왕을 두려워하여 팠던 것이라 느다냐의 아들 이스마엘이 그가 쳐죽인 사람들의 시체를 거기에 채우고'),
    (19991, '미스바에 남아 있는 왕의 딸들과 모든 백성 곧 사령관 느부사라단이 아히감의 아들 그다랴에게 위임하였던 바 미스바에 남아 있는 모든 백성을 이스마엘이 사로잡되 곧 느다냐의 아들 이스마엘이 그들을 사로잡고 암몬 자손에게로 가려고 떠나니라'),
    (19992, '○가레아의 아들 요하난과 그와 함께 있는 모든 군 지휘관이 느다냐의 아들 이스마엘이 행한 모든 악을 듣고'),
    (19997, '가레아의 아들 요하난과 그와 함께 있던 모든 군 지휘관이 느다냐의 아들 이스마엘이 아히감의 아들 그다랴를 죽이고 미스바에서 잡아간 모든 남은 백성 곧 군사와 여자와 유아와 내시를 기브온에서 빼앗아 가지고 돌아와서'),
    (20065, '<여호와께서 바룩에게 구원을 약속하시다> 유다의 요시야 왕의 아들 여호야김 넷째 해에 네리야의 아들 바룩이 예레미야가 불러 주는 대로 이 모든 말을 책에 기록하니라 그 때에 선지자 예레미야가 그에게 말하여 이르되'),
    (20001, '선지자 예레미야에게 이르되 당신은 우리의 탄원을 듣고 이 남아 있는 모든 자를 위하여 당신의 하나님 여호와께 기도해 주소서 당신이 보는 바와 같이 우리는 많은 사람 중에서 남은 적은 무리이니'),
    (20005, '우리가 당신을 우리 하나님 여호와께 보냄은 그의 목소리가 우리에게 좋든지 좋지 않든지를 막론하고 순종하려 함이라 우리가 우리 하나님 여호와의 목소리를 순종하면 우리에게 복이 있으리이다 하니라'),
    (20006, '<여호와의 말씀> ○십일 후에 여호와의 말씀이 예레미야에게 임하니'),
    (20013, '또 너희가 말하기를 아니라 우리는 전쟁도 보이지 아니하며 나팔 소리도 들리지 아니하며 양식의 궁핍도 당하지 아니하는 애굽 땅으로 들어가 살리라 하면 잘못되리라'),
    (20014, '너희 유다의 남은 자여 이제 여호와의 말씀을 들으라 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희가 만일 애굽에 들어가서 거기에 살기로 고집하면'),
    (20017, '○만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 나의 노여움과 분을 예루살렘 주민에게 부은 것 같이 너희가 애굽에 이를 때에 나의 분을 너희에게 부으리니 너희가 가증함과 놀램과 저주와 치욕 거리가 될 것이라 너희가 다시는 이 땅을 보지 못하리라 하시도다'),
    (20019, '너희가 나를 너희 하나님 여호와께 보내며 이르기를 우리를 위하여 우리 하나님 여호와께 기도하고 우리 하나님 여호와께서 말씀하신 대로 우리에게 전하라 우리가 그대로 행하리라 하여 너희 마음을 속였느니라'),
    (20099, '○여호와께서 이와 같이 말씀하시되 보라 물이 북쪽에서 일어나 물결치는 시내를 이루어 그 땅과 그 중에 있는 모든 것과 그 성읍과 거기에 사는 자들을 휩쓸리니 사람들이 부르짖으며 그 땅 모든 주민이 울부짖으리라'),
    (20071, '○애굽에 관한 것이라 곧 유다의 요시야 왕의 아들 여호야김 넷째 해에 유브라데 강 가 갈그미스에서 바벨론의 느부갓네살 왕에게 패한 애굽의 왕 바로느고의 군대에 대한 말씀이라'),
    (20072, '○너희는 작은 방패와 큰 방패를 예비하고 나가서 싸우라'),
    (20079, '그 날은 주 만군의 여호와께서 그의 대적에게 원수 갚는 보복일이라 칼이 배부르게 삼키며 그들의 피를 넘치도록 마시리니 주 만군의 여호와께서 북쪽 유브라데 강 가에서 희생제물을 받으실 것임이로다'),
    (20082, '<느부갓네살이 애굽을 치리라> ○바벨론의 느부갓네살 왕이 와서 애굽 땅을 칠 일에 대하여 선지자 예레미야에게 이르신 여호와의 말씀이라'),
    (20083, '○너희는 애굽에 선포하며 믹돌과 놉과 다바네스에 선포하여 말하기를 너희는 굳건히 서서 준비하라 네 사방이 칼에 삼키웠느니라'),
    (20096, '<이스라엘을 구원하리라> ○내 종 야곱아 두려워하지 말라 이스라엘아 놀라지 말라 보라 내가 너를 먼 곳에서 구원하며 네 자손을 포로된 땅에서 구원하리니 야곱이 돌아와서 평안하며 걱정 없이 살게 될 것이라 그를 두렵게 할 자 없으리라'),
    (20097, '여호와의 말씀이니라 내 종 야곱아 내가 너와 함께 있나니 두려워하지 말라 내가 너를 흩었던 그 나라들은 다 멸할지라도 너는 사라지지 아니하리라 내가 너를 법도대로 징계할 것이요 결코 무죄한 자로 여기지 아니하리라 하시니라'),
    (20036, '만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 너희가 예루살렘과 유다 모든 성읍에 내린 나의 모든 재난을 보았느니라 보라 오늘 그것들이 황무지가 되었고 사는 사람이 없나니'),
    (20041, '만군의 하나님 이스라엘의 하나님 여호와께서 이와 같이 말씀하셨느니라 너희가 어찌하여 큰 악을 행하여 자기 영혼을 해하며 유다 가운데에서 너희의 남자와 여자와 아이와 젖 먹는 자를 멸절하여 남은 자가 없게 하려느냐'),
    (20042, '어찌하여 너희가 너희 손이 만든 것으로 나의 노여움을 일으켜 너희가 가서 머물러 사는 애굽 땅에서 다른 신들에게 분향함으로 끊어 버림을 당하여 세계 여러 나라 가운데에서 저주와 수치 거리가 되고자 하느냐'),
    (20045, '○그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 얼굴을 너희에게로 향하여 환난을 내리고 온 유다를 끊어 버릴 것이며'),
    (20046, '내가 또 애굽 땅에 머물러 살기로 고집하고 그리로 들어간 유다의 남은 자들을 처단하리니 그들이 다 멸망하여 애굽 땅에서 엎드러질 것이라 그들이 칼과 기근에 망하되 낮은 자로부터 높은 자까지 칼과 기근에 죽어서 저주와 놀램과 조롱과 수치의 대상이 되리라'),
    (20048, '애굽 땅에 들어가서 거기에 머물러 살려는 유다의 남은 자 중에 피하거나 살아 남아 소원대로 돌아와서 살고자 하여 유다 땅에 돌아올 자가 없을 것이라 도망치는 자들 외에는 돌아올 자가 없으리라 하셨느니라'),
    (20049, '○그리하여 자기 아내들이 다른 신들에게 분향하는 줄을 아는 모든 남자와 곁에 섰던 모든 여인 곧 애굽 땅 바드로스에 사는 모든 백성의 큰 무리가 예레미야에게 대답하여 이르되'),
    (20051, '우리 입에서 낸 모든 말을 반드시 실행하여 우리가 본래 하던 것 곧 우리와 우리 선조와 우리 왕들과 우리 고관들이 유다 성읍들과 예루살렘 거리에서 하던 대로 하늘의 여왕에게 분향하고 그 앞에 전제를 드리리라 그 때에는 우리가 먹을 것이 풍부하며 복을 받고 재난을 당하지 아니하였더니'),
    (20054, '○예레미야가 남녀 모든 무리 곧 이 말로 대답하는 모든 백성에게 일러 이르되'),
    (20058, '○예레미야가 다시 모든 백성과 모든 여인에게 말하되 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라'),
    (20059, '만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희와 너희 아내들이 입으로 말하고 손으로 이루려 하여 이르기를 우리가 서원한 대로 반드시 이행하여 하늘의 여왕에게 분향하고 전제를 드리리라 하였은즉 너희 서원을 성취하며 너희 서원을 이행하라 하시느니라'),
    (20060, '그러므로 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라 여호와께서 말씀하시되 보라 내가 나의 큰 이름으로 맹세하였은즉 애굽 온 땅에 사는 유다 사람들의 입에서 다시는 내 이름을 부르며 주 여호와의 살아 계심을 두고 맹세하노라 하는 자가 없으리라'),
    (20062, '그런즉 칼을 피한 소수의 사람이 애굽 땅에서 나와 유다 땅으로 돌아오리니 애굽 땅에 들어가서 거기에 머물러 사는 유다의 모든 남은 자가 내 말과 그들의 말 가운데서 누구의 말이 진리인지 알리라'),
    (20064, '보라 내가 유다의 시드기야 왕을 그의 원수 곧 그의 생명을 찾는 바벨론의 느부갓네살 왕의 손에 넘긴 것 같이 애굽의 바로 호브라 왕을 그의 원수들 곧 그의 생명을 찾는 자들의 손에 넘겨 주리라 여호와께서 이와 같이 말씀하셨느니라'),
    (20152, '<암몬이 받을 심판> 암몬 자손에 대한 말씀이라 여호와께서 이와 같이 말씀하시되 이스라엘이 자식이 없느냐 상속자가 없느냐 말감이 갓을 점령하며 그 백성이 그 성읍들에 사는 것은 어찌 됨이냐'),
    (20153, '여호와의 말씀이니라 그러므로 보라 날이 이르리니 내가 전쟁 소리로 암몬 자손의 랍바에 들리게 할 것이라 랍바는 폐허더미 언덕이 되겠고 그 마을들은 불에 탈 것이며 그 때에 이스라엘은 자기를 점령하였던 자를 점령하리라 여호와의 말씀이니라'),
    (20154, '헤스본아 슬피 울지어다 아이가 황폐하였도다 너희 랍바의 딸들아 부르짖을지어다 굵은 베를 감고 애통하며 울타리 가운데에서 허둥지둥할지어다 말감과 그 제사장들과 그 고관들이 다 사로잡혀 가리로다'),
    (20158, '<에돔이 받을 심판> ○에돔에 대한 말씀이라 만군의 여호와께서 이와 같이 말씀하시되 데만에 다시는 지혜가 없게 되었느냐 명철한 자에게 책략이 끊어졌느냐 그들의 지혜가 없어졌느냐'),
    (20165, '○내가 여호와에게서부터 오는 소식을 들었노라 사절을 여러 나라 가운데 보내어 이르시되 너희는 모여와서 그를 치며 일어나서 싸우라'),
    (20167, '바위 틈에 살며 산꼭대기를 점령한 자여 스스로 두려운 자인 줄로 여김과 네 마음의 교만이 너를 속였도다 네가 독수리 같이 보금자리를 높은 데에 지었을지라도 내가 그리로부터 너를 끌어내리리라 이는 여호와의 말씀이니라'),
    (20170, '보라 사자가 요단 강의 깊은 숲에서 나타나듯이 그가 와서 견고한 처소를 칠 것이라 내가 즉시 그들을 거기에서 쫓아내고 택한 자를 내가 그 위에 세우리니 나와 같은 자 누구며 나와 더불어 다툴 자 누구며 내 앞에 설 목자가 누구냐'),
    (20171, '○그런즉 에돔에 대한 여호와의 의도와 데만 주민에 대하여 결심하신 여호와의 계획을 들으라 양 떼의 어린 것들을 그들이 반드시 끌고 다니며 괴롭히고 그 처소로 황폐하게 하지 않으랴'),
    (20174, '<다메섹이 받을 심판> ○다메섹에 대한 말씀이라 하맛과 아르밧이 수치를 당하리니 이는 흉한 소문을 듣고 낙담함이니라 바닷가에서 비틀거리며 평안이 없도다'),
    (20179, '<게달과 하솔이 받을 심판> ○바벨론의 느부갓네살 왕에게 공격을 받은 게달과 하솔 나라들에 대한 말씀이라 여호와께서 이와 같이 말씀하시되 너희는 일어나 게달로 올라가서 동방 자손들을 황폐하게 하라'),
    (20185, '<엘람이 받을 심판> ○유다 왕 시드기야가 즉위한 지 오래지 아니하여서 엘람에 대한 여호와의 말씀이 선지자 예레미야에게 임하여 이르시되'),
    (20188, '여호와의 말씀이니라 내가 엘람으로 그의 원수의 앞, 그의 생명을 노리는 자의 앞에서 놀라게 할 것이며 내가 재앙 곧 나의 진노를 그들 위에 내릴 것이며 내가 또 그 뒤로 칼을 보내어 그들을 멸망시키리라'),
    (20192, '너희는 나라들 가운데에 전파하라 공포하라 깃발을 세우라 숨김이 없이 공포하여 이르라 바벨론이 함락되고 벨이 수치를 당하며 므로닥이 부스러지며 그 신상들은 수치를 당하며 우상들은 부스러진다 하라'),
    (20196, '<바벨론에서 도망하라 갈대아 땅에서 나오라> ○내 백성은 잃어 버린 양 떼로다 그 목자들이 그들을 곁길로 가게 하여 산으로 돌이키게 하였으므로 그들이 산에서 언덕으로 돌아다니며 쉴 곳을 잊었도다'),
    (20201, '<바벨론의 멸망> ○나의 소유를 노략하는 자여 너희가 즐거워하며 기뻐하고 타작하는 송아지 같이 발굽을 구르며 군마 같이 우는도다'),
    (20207, '<이스라엘을 돌아오게 하리라> ○이스라엘은 흩어진 양이라 사자들이 그를 따르도다 처음에는 앗수르 왕이 먹었고 다음에는 바벨론의 느부갓네살 왕이 그의 뼈를 꺾도다'),
    (20211, '<여호와께서 바벨론을 심판하시다> ○이는 여호와의 말씀이니라 너희는 올라가서 므라다임의 땅을 치며 브곳의 주민을 쳐서 진멸하되 내가 너희에게 명령한 대로 다하라'),
    (20219, '○활 쏘는 자를 바벨론에 소집하라 활을 당기는 자여 그 사면으로 진을 쳐서 피하는 자가 없게 하라 그가 일한 대로 갚고 그가 행한 대로 그에게 갚으라 그가 이스라엘의 거룩한 자 여호와를 향하여 교만하였음이라'),
    (20223, '○만군의 여호와께서 이와 같이 말씀하시니라 이스라엘 자손과 유다 자손이 함께 학대를 받는도다 그들을 사로잡은 자는 다 그들을 붙들고 놓아 주지 아니하리라'),
    (20231, '○보라 한 민족이 북쪽에서 오고 큰 나라와 여러 왕이 충동을 받아 땅 끝에서 일어나리니'),
    (20234, '보라 사자가 요단의 깊은 숲에서 나타나듯이 그가 와서 견고한 처소를 칠 것이라 내가 즉시 그들을 거기에서 쫓아내고 택한 자를 내가 그 자리에 세우리니 나와 같은 자 누구며 출두하라고 나에게 명령할 자가 누구며 내 앞에 설 목자가 누구냐'),
    (20105, '<모압의 멸망> 모압에 관한 것이라 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 오호라 느보여 그가 유린 당하였도다 기랴다임이 수치를 당하여 점령되었고 미스갑이 수치를 당하여 파괴되었으니'),
    (20106, '모압의 찬송 소리가 없어졌도다 헤스본에서 무리가 그를 해하려고 악을 도모하고 이르기를 와서 그를 끊어서 나라를 이루지 못하게 하자 하는도다 맛멘이여 너도 조용하게 되리니 칼이 너를 뒤쫓아 가리라'),
    (20115, '<모압이 황폐하였다> ○모압은 젊은 시절부터 평안하고 포로도 되지 아니하였으므로 마치 술이 그 찌끼 위에 있고 이 그릇에서 저 그릇으로 옮기지 않음 같아서 그 맛이 남아 있고 냄새가 변하지 아니하였도다'),
    (20130, '<모압이 조롱 거리가 되리라> ○모압으로 취하게 할지어다 이는 그가 여호와에 대하여 교만함이라 그가 그 토한 것에서 뒹굴므로 조롱 거리가 되리로다'),
    (20140, '<모압이 벌 받을 해> ○그러므로 나의 마음이 모압을 위하여 피리 같이 소리 내며 나의 마음이 길헤레스 사람들을 위하여 피리 같이 소리 내나니 이는 그가 모은 재물이 없어졌음이라'),
    (20149, '○도망하는 자들이 기진하여 헤스본 그늘 아래에 서니 이는 불이 헤스본에서 나며 불길이 시혼 가운데 나서 모압의 살쩍과 떠드는 자들의 정수리를 사름이로다'),
    (20241, '○이스라엘과 유다가 이스라엘의 거룩하신 이를 거역하므로 죄과가 땅에 가득하나 그의 하나님 만군의 여호와에게 버림 받은 홀아비는 아니니라'),
    (20247, '○화살을 갈며 둥근 방패를 준비하라 여호와께서 메대 왕들의 마음을 부추기사 바벨론을 멸하기로 뜻하시나니 이는 여호와께서 보복하시는 것 곧 그의 성전을 위하여 보복하시는 것이라'),
    (20251, '<여호와를 찬양하다> ○여호와께서 그의 능력으로 땅을 지으셨고 그의 지혜로 세계를 세우셨고 그의 명철로 하늘들을 펴셨으며'),
    (20256, '<바벨론은 여호와의 철퇴> ○여호와께서 이르시되 너는 나의 철퇴 곧 무기라 나는 네가 나라들을 분쇄하며 네가 국가들을 멸하며'),
    (20261, '<바벨론이 황무지가 되리라> ○여호와의 말씀이니라 온 세계를 멸하는 멸망의 산아 보라 나는 네 원수라 나의 손을 네 위에 펴서 너를 바위에서 굴리고 너로 불 탄 산이 되게 할 것이니'),
    (20263, '○땅에 깃발을 세우며 나라들 가운데에 나팔을 불어서 나라들을 동원시켜 그를 치며 아라랏과 민니와 아스그나스 나라를 불러 모아 그를 치며 사무관을 세우고 그를 치되 극성스런 메뚜기 같이 그 말들을 몰아오게 하라'),
    (20269, '<여호와께서 이스라엘을 위하여 보복하시다> ○만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 딸 바벨론은 때가 이른 타작 마당과 같은지라 멀지 않아 추수 때가 이르리라 하시도다'),
    (20277, '<바벨론의 파멸을 노래하다> ○슬프다 세삭이 함락되었도다 온 세상의 칭찬 받는 성읍이 빼앗겼도다 슬프다 바벨론이 나라들 가운데에 황폐하였도다'),
    (20281, '○나의 백성아 너희는 그 중에서 나와 각기 여호와의 진노를 피하라'),
    (20282, '너희 마음을 나약하게 말며 이 땅에서 들리는 소문으로 말미암아 두려워하지 말라 소문은 이 해에도 있겠고 저 해에도 있으리라 그 땅에는 강포함이 있어 다스리는 자가 다스리는 자를 서로 치리라'),
    (20286, '<여호와께서 바벨론에 보복하시다> ○칼을 피한 자들이여 멈추지 말고 걸어가라 먼 곳에서 여호와를 생각하며 예루살렘을 너희 마음에 두라'),
    (20290, '<바벨론이 황폐하리라> ○바벨론으로부터 부르짖는 소리가 들리도다 갈대아 사람의 땅에 큰 파멸의 소리가 들리도다'),
    (20295, '<예레미야가 바벨론에 예언을 전하다> ○유다의 시드기야 왕 제사년에 마세야의 손자 네리야의 아들 스라야가 그 왕과 함께 바벨론으로 갈 때에 선지자 예레미야가 그에게 말씀을 명령하니 스라야는 병참감이더라'),
    (20398, '○내 고초와 재난 곧 쑥과 담즙을 기억하소서'),
    (20419, '○우리가 스스로 우리의 행위들을 조사하고 여호와께로 돌아가자'),
    (20434, '○여호와여 내가 심히 깊은 구덩이에서 주의 이름을 불렀나이다'),
    (20358, '<예루살렘에 대한 여호와의 진노> 슬프다 주께서 어찌 그리 진노하사 딸 시온을 구름으로 덮으셨는가 이스라엘의 아름다움을 하늘에서 땅에 던지셨음이여 그의 진노의 날에 그의 발판을 기억하지 아니하셨도다'),
    (20368, '○내 눈이 눈물에 상하며 내 창자가 끊어지며 내 간이 땅에 쏟아졌으니 이는 딸 내 백성이 패망하여 어린 자녀와 젖 먹는 아이들이 성읍 길거리에 기절함이로다'),
    (20374, '여호와께서 이미 정하신 일을 행하시고 옛날에 명령하신 말씀을 다 이루셨음이여 긍휼히 여기지 아니하시고 무너뜨리사 원수가 너로 말미암아 즐거워하게 하며 네 대적자들의 뿔로 높이 들리게 하셨도다'),
    (20377, '○여호와여 보시옵소서 주께서 누구에게 이같이 행하셨는지요 여인들이 어찌 자기 열매 곧 그들이 낳은 아이들을 먹으오며 제사장들과 선지자들이 어찌 주의 성소에서 죽임을 당하오리이까'),
    (20379, '주께서 내 두려운 일들을 사방에서 부르시기를 절기 때 무리를 부름 같이 하셨나이다 여호와께서 진노하시는 날에는 피하거나 남은 자가 없나이다 내가 낳아 기르는 아이들을 내 원수가 다 멸하였나이다'),
    (20336, '<예루살렘의 슬픔> 슬프다 이 성이여 전에는 사람들이 많더니 이제는 어찌 그리 적막하게 앉았는고 전에는 열국 중에 크던 자가 이제는 과부 같이 되었고 전에는 열방 중에 공주였던 자가 이제는 강제 노동을 하는 자가 되었도다'),
    (20341, '딸 시온의 모든 영광이 떠나감이여 그의 지도자들은 꼴을 찾지 못한 사슴들처럼 뒤쫓는 자 앞에서 힘없이 달아났도다'),
    (20344, '그의 더러운 것이 그의 옷깃에 묻어 있으나 그의 나중을 생각하지 아니함이여 그러므로 놀랍도록 낮아져도 그를 위로할 자가 없도다 여호와여 원수가 스스로 큰 체하오니 나의 환난을 감찰하소서'),
    (20356, '그들이 내가 탄식하는 것을 들었으나 나를 위로하는 자가 없으며 나의 모든 원수들은 내가 재난 당하는 것을 듣고 주께서 이렇게 행하신 것을 기뻐하나이다 그러나 주께서 그 선포하신 날을 이르게 하셔서 그들이 나와 같이 되게 하소서'),
    (20456, '○여호와께서 그의 분을 내시며 그의 맹렬한 진노를 쏟으심이여 시온에 불을 지르사 그 터를 사르셨도다'),
    (20460, '사람들이 그들에게 외쳐 이르기를 저리 가라 부정하다, 저리 가라, 저리 가라, 만지지 말라 하였음이여 그들이 도망하여 방황할 때에 이방인들이 말하기를 그들이 다시는 여기서 살지 못하리라 하였도다'),
    (20462, '○우리가 헛되이 도움을 바라므로 우리의 눈이 상함이여 우리를 구원하지 못할 나라를 바라보고 바라보았도다'),
    (20464, '우리를 뒤쫓는 자들이 하늘의 독수리들보다 빠름이여 산 꼭대기까지도 뒤쫓으며 광야에서도 우리를 잡으려고 매복하였도다'),
    (20486, '○여호와여 주는 영원히 계시오며 주의 보좌는 대대에 이르나이다'),
    (20493, '○내가 보니 북쪽에서부터 폭풍과 큰 구름이 오는데 그 속에서 불이 번쩍번쩍하여 빛이 그 사방에 비치며 그 불 가운데 단 쇠 같은 것이 나타나 보이고'),
    (20504, '○내가 그 생물들을 보니 그 생물들 곁에 있는 땅 위에는 바퀴가 있는데 그 네 얼굴을 따라 하나씩 있고'),
    (20511, '○그 생물의 머리 위에는 수정 같은 궁창의 형상이 있어 보기에 두려운데 그들의 머리 위에 펼쳐져 있고'),
    (20515, '○그 머리 위에 있는 궁창 위에 보좌의 형상이 있는데 그 모양이 남보석 같고 그 보좌의 형상 위에 한 형상이 있어 사람의 모양 같더라'),
    (20301, '<시드기야의 배반과 죽음> 시드기야가 왕위에 오를 때에 나이가 이십일 세라 예루살렘에서 십일 년 동안 다스리니라 그의 어머니의 이름은 하무달이라 립나인 예레미야의 딸이더라'),
    (20303, '여호와께서 예루살렘과 유다에게 진노하심이 그들을 자기 앞에서 쫓아내시기까지 이르렀더라 ○시드기야가 바벨론 왕을 배반하니라'),
    (20313, '<여호와의 성전이 헐리다> ○바벨론의 느부갓네살 왕의 열아홉째 해 다섯째 달 열째 날에 바벨론 왕의 어전 사령관 느부사라단이 예루살렘에 이르러'),
    (20318, '○갈대아 사람은 또 여호와의 성전의 두 놋기둥과 받침들과 여호와의 성전의 놋대야를 깨뜨려 그 놋을 바벨론으로 가져갔고'),
    (20325, '<유다 백성이 바벨론으로 사로잡혀 가다> ○사령관이 대제사장 스라야와 부제사장 스바냐와 성전 문지기 세 사람을 사로잡고'),
    (20327, '사령관 느부사라단은 그들을 사로잡아 리블라에 있는 바벨론의 왕에게 나아가매'),
    (20328, '바벨론의 왕이 하맛 땅 리블라에서 다 쳐 죽였더라 이와 같이 유다가 사로잡혀 본국에서 떠났더라'),
    (20329, '○느부갓네살이 사로잡아 간 백성은 이러하니라 제칠년에 유다인이 삼천이십삼 명이요'),
    (20332, '○유다 왕 여호야긴이 사로잡혀 간 지 삼십칠 년 곧 바벨론의 에윌므로닥 왕의 즉위 원년 열두째 달 스물다섯째 날 그가 유다의 여호야긴 왕의 머리를 들어 주었고 감옥에서 풀어 주었더라'),
    (20523, '인자야 너는 비록 가시와 찔레와 함께 있으며 전갈 가운데에 거주할지라도 그들을 두려워하지 말고 그들의 말을 두려워하지 말지어다 그들은 패역한 족속이라도 그 말을 두려워하지 말며 그 얼굴을 무서워하지 말지어다'),
    (20525, '○너 인자야 내가 네게 이르는 말을 듣고 그 패역한 족속 같이 패역하지 말고 네 입을 벌리고 내가 네게 주는 것을 먹으라 하시기로'),
    (20531, '○그가 또 내게 이르시되 인자야 이스라엘 족속에게 가서 내 말로 그들에게 고하라'),
    (20539, '○때에 주의 영이 나를 들어올리시는데 내가 내 뒤에서 크게 울리는 소리를 들으니 찬송할지어다 여호와의 영광이 그의 처소로부터 나오는도다 하니'),
    (20543, '<파수꾼 에스겔> ○칠 일 후에 여호와의 말씀이 내게 임하여 이르시되'),
    (20545, '가령 내가 악인에게 말하기를 너는 꼭 죽으리라 할 때에 네가 깨우치지 아니하거나 말로 악인에게 일러서 그의 악한 길을 떠나 생명을 구원하게 하지 아니하면 그 악인은 그의 죄악 중에서 죽으려니와 내가 그의 피 값을 네 손에서 찾을 것이고'),
    (20547, '또 의인이 그의 공의에서 돌이켜 악을 행할 때에는 이미 행한 그의 공의는 기억할 바 아니라 내가 그 앞에 거치는 것을 두면 그가 죽을지니 이는 네가 그를 깨우치지 않음이니라 그는 그의 죄 중에서 죽으려니와 그의 피 값은 내가 네 손에서 찾으리라'),
    (20549, '<에스겔이 말 못하는 자가 되다> ○여호와께서 권능으로 거기서 내게 임하시고 또 내게 이르시되 일어나 들로 나아가라 내가 거기서 너와 말하리라 하시기로'),
    (20554, '그러나 내가 너와 말할 때에 네 입을 열리니 너는 그들에게 이르기를 주 여호와의 말씀이 이러하시다 하라 들을 자는 들을 것이요 듣기 싫은 자는 듣지 아니하리니 그들은 반역하는 족속임이니라'),
    (20594, '내가 너희가 거주하는 모든 성읍이 사막이 되게 하며 산당을 황폐하게 하리니 이는 너희 제단이 깨어지고 황폐하며 너희 우상들이 깨어져 없어지며 너희 분향제단들이 찍히며 너희가 만든 것이 폐하여지며'),
    (20596, '○그러나 너희가 여러 나라에 흩어질 때에 내가 너희 중에서 칼을 피하여 이방인들 중에 살아 남은 자가 있게 할지라'),
    (20597, '너희 중에서 살아 남은 자가 사로잡혀 이방인들 중에 있어서 나를 기억하되 그들이 음란한 마음으로 나를 떠나고 음란한 눈으로 우상을 섬겨 나를 근심하게 한 것을 기억하고 스스로 한탄하리니 이는 그 모든 가증한 일로 악을 행하였음이라'),
    (20599, '○주 여호와께서 이같이 이르시되 너는 손뼉을 치고 발을 구르며 말할지어다 오호라 이스라엘 족속이 모든 가증한 악을 행하므로 마침내 칼과 기근과 전염병에 망하되'),
    (20601, '그 죽임 당한 시체들이 그 우상들 사이에, 제단 사방에, 각 높은 고개 위에, 모든 산 꼭대기에, 모든 푸른 나무 아래에, 무성한 상수리나무 아래 곧 그 우상에게 분향하던 곳에 있으리니 내가 여호와인 줄을 너희가 알리라'),
    (20576, '○주 여호와께서 이와 같이 이르시되 이것이 곧 예루살렘이라 내가 그를 이방인 가운데에 두어 나라들이 둘러 있게 하였거늘'),
    (20578, '그러므로 나 주 여호와가 말하노라 너희 요란함이 너희를 둘러싸고 있는 이방인들보다 더하여 내 율례를 행하지 아니하며 내 규례를 지키지 아니하고 너희를 둘러 있는 이방인들의 규례대로도 행하지 아니하였느니라'),
    (20582, '그러므로 나 주 여호와가 말하노라 내가 나의 삶을 두고 맹세하노니 네가 모든 미운 물건과 모든 가증한 일로 내 성소를 더럽혔은즉 나도 너를 아끼지 아니하며 긍휼을 베풀지 아니하고 미약하게 하리니'),
    (20583, '너희 가운데에서 삼분의 일은 전염병으로 죽으며 기근으로 멸망할 것이요 삼분의 일은 너의 사방에서 칼에 엎드러질 것이며 삼분의 일은 내가 사방에 흩어 버리고 또 그 뒤를 따라 가며 칼을 빼리라'),
    (20584, '○이와 같이 내 노가 다한즉 그들을 향한 분이 풀려서 내 마음이 가라앉으리라 내 분이 그들에게 다한즉 나 여호와가 열심으로 말한 줄을 그들이 알리라'),
    (20558, '○너는 또 왼쪽으로 누워 이스라엘 족속의 죄악을 짊어지되 네가 눕는 날수대로 그 죄악을 담당할지니라'),
    (20563, '○너는 밀과 보리와 콩과 팥과 조와 귀리를 가져다가 한 그릇에 담고 너를 위하여 떡을 만들어 네가 옆으로 눕는 날수 곧 삼백구십 일 동안 먹되'),
    (20607, '○주 여호와께서 이같이 이르시되 재앙이로다, 비상한 재앙이로다 볼지어다 그것이 왔도다'),
    (20612, '○볼지어다 그 날이로다 볼지어다 임박하도다 정한 재앙이 이르렀으니 몽둥이가 꽃이 피며 교만이 싹이 났도다'),
    (20615, '파는 자가 살아 있다 할지라도 다시 돌아가서 그 판 것을 얻지 못하리니 이는 묵시가 그 모든 무리에게 돌아오지 아니하고, 사람이 그 죄악으로 말미암아 자기의 목숨을 유지할 수 없으리라 하였음이로다'),
    (20616, '<이스라엘이 받는 벌> ○그들이 나팔을 불어 온갖 것을 준비하였을지라도 전쟁에 나갈 사람이 없나니 이는 내 진노가 그 모든 무리에게 이르렀음이라'),
    (20621, '그들이 그 은을 거리에 던지며 그 금을 오물 같이 여기리니 이는 여호와 내가 진노를 내리는 날에 그들의 은과 금이 능히 그들을 건지지 못하며 능히 그 심령을 족하게 하거나 그 창자를 채우지 못하고 오직 죄악의 걸림돌이 됨이로다'),
    (20625, '○너는 쇠사슬을 만들라 이는 피 흘리는 죄가 그 땅에 가득하고 포악이 그 성읍에 찼음이라'),
    (20632, '그가 손 같은 것을 펴서 내 머리털 한 모숨을 잡으며 주의 영이 나를 들어 천지 사이로 올리시고 하나님의 환상 가운데에 나를 이끌어 예루살렘으로 가서 안뜰로 들어가는 북향한 문에 이르시니 거기에는 질투의 우상 곧 질투를 일어나게 하는 우상의 자리가 있는 곳이라'),
    (20634, '○그가 내게 이르시되 인자야 이제 너는 눈을 들어 북쪽을 바라보라 하시기로 내가 눈을 들어 북쪽을 바라보니 제단문 어귀 북쪽에 그 질투의 우상이 있더라'),
    (20635, '그가 또 내게 이르시되 인자야 이스라엘 족속이 행하는 일을 보느냐 그들이 여기에서 크게 가증한 일을 행하여 나로 내 성소를 멀리 떠나게 하느니라 너는 다시 다른 큰 가증한 일을 보리라 하시더라'),
    (20641, '또 내게 이르시되 인자야 이스라엘 족속의 장로들이 각각 그 우상의 방안 어두운 가운데에서 행하는 것을 네가 보았느냐 그들이 이르기를 여호와께서 우리를 보지 아니하시며 여호와께서 이 땅을 버리셨다 하느니라'),
    (20643, '○그가 또 나를 데리고 여호와의 전으로 들어가는 북문에 이르시기로 보니 거기에 여인들이 앉아 담무스를 위하여 애곡하더라'),
    (20645, '○그가 또 나를 데리고 여호와의 성전 안뜰에 들어가시니라 보라 여호와의 성전 문 곧 현관과 제단 사이에서 약 스물다섯 명이 여호와의 성전을 등지고 낯을 동쪽으로 향하여 동쪽 태양에게 예배하더라'),
    (20646, '또 내게 이르시되 인자야 네가 보았느냐 유다 족속이 여기에서 행한 가증한 일을 적다 하겠느냐 그들이 그 땅을 폭행으로 채우고 또 다시 내 노여움을 일으키며 심지어 나뭇가지를 그 코에 두었느니라'),
    (20649, '내가 보니 여섯 사람이 북향한 윗문 길로부터 오는데 각 사람의 손에 죽이는 무기를 잡았고 그 중의 한 사람은 가는 베 옷을 입고 허리에 서기관의 먹 그릇을 찼더라 그들이 들어와서 놋 제단 곁에 서더라'),
    (20650, '○그룹에 머물러 있던 이스라엘 하나님의 영광이 성전 문지방에 이르더니 여호와께서 그 가는 베 옷을 입고 서기관의 먹 그릇을 찬 사람을 불러'),
    (20651, '여호와께서 이르시되 너는 예루살렘 성읍 중에 순행하여 그 가운데에서 행하는 모든 가증한 일로 말미암아 탄식하며 우는 자의 이마에 표를 그리라 하시고'),
    (20656, '○그가 내게 이르시되 이스라엘과 유다 족속의 죄악이 심히 중하여 그 땅에 피가 가득하며 그 성읍에 불법이 찼나니 이는 그들이 이르기를 여호와께서 이 땅을 버리셨으며 여호와께서 보지 아니하신다 함이라'),
    (20660, '하나님이 가는 베 옷을 입은 사람에게 말씀하여 이르시되 너는 그룹 밑에 있는 바퀴 사이로 들어가 그 속에서 숯불을 두 손에 가득히 움켜 가지고 성읍 위에 흩으라 하시매 그가 내 목전에서 들어가더라'),
    (20667, '○내가 보니 그룹들 곁에 네 바퀴가 있는데 이 그룹 곁에도 한 바퀴가 있고 저 그룹 곁에도 한 바퀴가 있으며 그 바퀴 모양은 황옥 같으며'),
    (20673, '○그룹들이 올라가니 그들은 내가 그발 강 가에서 보던 생물이라'),
    (20676, '○여호와의 영광이 성전 문지방을 떠나서 그룹들 위에 머무르니'),
    (20677, '그룹들이 날개를 들고 내 눈 앞의 땅에서 올라가는데 그들이 나갈 때에 바퀴도 그 곁에서 함께 하더라 그들이 여호와의 전으로 들어가는 동문에 머물고 이스라엘 하나님의 영광이 그 위에 덮였더라'),
    (20678, '○그것은 내가 그발 강 가에서 보던 이스라엘의 하나님 아래에 있던 생물이라 그들이 그룹인 줄을 내가 아니라'),
    (20681, '<예루살렘이 심판을 받다> 그 때에 주의 영이 나를 들어올려서 여호와의 전 동문 곧 동향한 문에 이르시기로 보니 그 문에 사람이 스물다섯 명이 있는데 내가 그 중에서 앗술의 아들 야아사냐와 브나야의 아들 블라댜를 보았으니 그들은 백성의 고관이라'),
    (20685, '○여호와의 영이 내게 임하여 이르시되 너는 말하기를 여호와의 말씀에 이스라엘 족속아 너희가 이렇게 말하였도다 너희 마음에서 일어나는 것을 내가 다 아노라'),
    (20694, '<이스라엘의 회복을 이르시다> ○여호와의 말씀이 내게 임하여 이르시되'),
    (20695, '인자야 예루살렘 주민이 네 형제 곧 네 형제와 친척과 온 이스라엘 족속을 향하여 이르기를 너희는 여호와에게서 멀리 떠나라 이 땅은 우리에게 주어 기업이 되게 하신 것이라 하였나니'),
    (20702, '<여호와의 영광이 떠나시다> ○그 때에 그룹들이 날개를 드는데 바퀴도 그 곁에 있고 이스라엘 하나님의 영광도 그 위에 덮였더니'),
    (20741, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 너희가 허탄한 것을 말하며 거짓된 것을 보았은즉 내가 너희를 치리라 주 여호와의 말씀이니라'),
    (20742, '그 선지자들이 허탄한 묵시를 보며 거짓 것을 점쳤으니 내 손이 그들을 쳐서 내 백성의 공회에 들어오지 못하게 하며 이스라엘 족속의 호적에도 기록되지 못하게 하며 이스라엘 땅에도 들어가지 못하게 하리니 너희가 나를 여호와인 줄 알리라'),
    (20750, '<거짓말로 예언하는 여자들> ○너 인자야 너의 백성 중 자기 마음대로 예언하는 여자들에게 경고하며 예언하여'),
    (20751, '이르기를 주 여호와의 말씀에 사람의 영혼을 사냥하려고 손목마다 부적을 꿰어 매고 키가 큰 자나 작은 자의 머리를 위하여 수건을 만드는 여자들에게 화 있을진저 너희가 어찌하여 내 백성의 영혼은 사냥하면서 자기를 위하여는 영혼을 살리려 하느냐'),
    (20752, '너희가 두어 움큼 보리와 두어 조각 떡을 위하여 나를 내 백성 가운데에서 욕되게 하여 거짓말을 곧이 듣는 내 백성에게 너희가 거짓말을 지어내어 죽지 아니할 영혼을 죽이고 살지 못할 영혼을 살리는도다'),
    (20760, '그런즉 너는 그들에게 말하여 이르라 나 주 여호와가 말하노라 이스라엘 족속 중에 그 우상을 마음에 들이며 죄악의 걸림돌을 자기 앞에 두고 선지자에게로 가는 모든 자에게 나 여호와가 그 우상의 수효대로 보응하리니'),
    (20762, '○그런즉 너는 이스라엘 족속에게 이르기를 주 여호와의 말씀에 너희는 마음을 돌이켜 우상을 떠나고 얼굴을 돌려 모든 가증한 것을 떠나라'),
    (20763, '이스라엘 족속과 이스라엘 가운데에 거류하는 외국인 중에 누구든지 나를 떠나고 자기 우상을 마음에 들이며 죄악의 걸림돌을 자기 앞에 두고 자기를 위하여 내게 묻고자 하여 선지자에게 가는 모든 자에게는 나 여호와가 친히 응답하여'),
    (20767, '이는 이스라엘 족속이 다시는 미혹되어 나를 떠나지 아니하게 하며 다시는 모든 죄로 스스로 더럽히지 아니하게 하여 그들을 내 백성으로 삼고 나는 그들의 하나님이 되려 함이라 주 여호와의 말씀이니라'),
    (20768, '<의인도 자기의 생명만 건지리라> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20777, '○주 여호와께서 이같이 이르시되 내가 나의 네 가지 중한 벌 곧 칼과 기근과 사나운 짐승과 전염병을 예루살렘에 함께 내려 사람과 짐승을 그 중에서 끊으리니 그 해가 더욱 심하지 아니하겠느냐'),
    (20778, '그러나 그 가운데에 피하는 자가 남아 있어 끌려 나오리니 곧 자녀들이라 그들이 너희에게로 나아오리니 너희가 그 행동과 소행을 보면 내가 예루살렘에 내린 재앙 곧 그 내린 모든 일에 대하여 너희가 위로를 받을 것이라'),
    (20713, '○이튿날 아침에 여호와의 말씀이 또 내게 임하여 이르시되'),
    (20722, '<떨면서 먹고 마시며 보이는 징조> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20724, '이 땅 백성에게 말하되 주 여호와께서 예루살렘 주민과 이스라엘 땅에 대하여 이르시기를 그들이 근심하면서 그 음식을 먹으며 놀라면서 그 물을 마실 것은 이 땅 모든 주민의 포악으로 말미암아 땅에 가득한 것이 황폐하게 됨이라'),
    (20726, '<속담과 묵시> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20728, '그러므로 너는 그들에게 이르기를 주 여호와께서 이같이 말씀하시기를 내가 이 속담을 그치게 하리니 사람이 다시는 이스라엘 가운데에서 이 속담을 사용하지 못하리라 하셨다 하고 또 그들에게 이르기를 날과 모든 묵시의 응함이 가까우니'),
    (20731, '○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20733, '그러므로 너는 그들에게 이르기를 주 여호와의 말씀에 나의 말이 하나도 다시 더디지 아니할지니 내가 한 말이 이루어지리라 나 주 여호와의 말이니라 하셨다 하라'),
    (20916, '○네 피의 어머니는 물 가에 심겨진 포도나무 같아서 물이 많으므로 열매가 많고 가지가 무성하며'),
    (20857, '○또 날개가 크고 털이 많은 큰 독수리 하나가 있었는데 그 포도나무가 이 독수리에게 물을 받으려고 그 심어진 두둑에서 그를 향하여 뿌리가 뻗고 가지가 퍼졌도다'),
    (20859, '너는 이르기를 주 여호와의 말씀에 그 나무가 능히 번성하겠느냐 이 독수리가 어찌 그 뿌리를 빼고 열매를 따며 그 나무가 시들게 하지 아니하겠으며 그 연한 잎사귀가 마르게 하지 아니하겠느냐 많은 백성이나 강한 팔이 아니라도 그 뿌리를 뽑으리라'),
    (20861, '<비유의 해석> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20866, '주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 바벨론 왕이 그를 왕으로 세웠거늘 그가 맹세를 저버리고 언약을 배반하였은즉 그 왕이 거주하는 곳 바벨론에서 왕과 함께 있다가 죽을 것이라'),
    (20872, '<높은 나무를 낮추고> ○주 여호와께서 이같이 말씀하시되 내가 백향목 꼭대기에서 높은 가지를 꺾어다가 심으리라 내가 그 높은 새 가지 끝에서 연한 가지를 꺾어 높고 우뚝 솟은 산에 심되'),
    (20793, '○내가 네 곁으로 지나갈 때에 네가 피투성이가 되어 발짓하는 것을 보고 네게 이르기를 너는 피투성이라도 살아 있으라 다시 이르기를 너는 피투성이라도 살아 있으라 하고'),
    (20802, '○그러나 네가 네 화려함을 믿고 네 명성을 가지고 행음하되 지나가는 모든 자와 더불어 음란을 많이 행하므로 네 몸이 그들의 것이 되도다'),
    (20810, '<방자한 음녀 예루살렘> ○주 여호와의 말씀이니라 너는 화 있을진저 화 있을진저 네가 모든 악을 행한 후에'),
    (20817, '○주 여호와의 말씀이니라 네가 이 모든 일을 행하니 이는 방자한 음녀의 행위라 네 마음이 어찌 그리 약한지'),
    (20822, '<예루살렘을 벌하시다> ○그러므로 너 음녀야 여호와의 말씀을 들을지어다'),
    (20830, '네가 어렸을 때를 기억하지 아니하고 이 모든 일로 나를 분노하게 하였은즉 내가 네 행위대로 네 머리에 보응하리니 네가 이 음란과 네 모든 가증한 일을 다시는 행하지 아니하리라 주 여호와의 말씀이니라'),
    (20831, '<그 어머니에 그 딸> ○속담을 말하는 자마다 네게 대하여 속담을 말하기를 어머니가 그러하면 딸도 그러하다 하리라'),
    (20839, '네가 네 형과 아우를 유리하게 판단하였은즉 너도 네 수치를 담당할지니라 네가 그들보다 더욱 가증한 죄를 범하므로 그들이 너보다 의롭게 되었나니 네가 네 형과 아우를 의롭게 하였은즉 너는 놀라며 네 수치를 담당할지니라'),
    (20840, '<소돔과 사마리아도 회복되리라> ○내가 그들의 사로잡힘 곧 소돔과 그의 딸들의 사로잡힘과 사마리아와 그의 딸들의 사로잡힘과 그들 중에 너의 사로잡힌 자의 사로잡힘을 풀어 주어'),
    (20847, '<영원한 언약> ○그러나 내가 너의 어렸을 때에 너와 세운 언약을 기억하고 너와 영원한 언약을 세우리라'),
    (20879, '○사람이 만일 의로워서 정의와 공의를 따라 행하며'),
    (20884, '○가령 그가 아들을 낳았다 하자 그 아들이 이 모든 선은 하나도 행하지 아니하고 이 죄악 중 하나를 범하여 강포하거나 살인하거나'),
    (20888, '○또 가령 그가 아들을 낳았다 하자 그 아들이 그 아버지가 행한 모든 죄를 보고 두려워하여 그대로 행하지 아니하고'),
    (20893, '○그런데 너희는 이르기를 아들이 어찌 아버지의 죄를 담당하지 아니하겠느냐 하는도다 아들이 정의와 공의를 행하며 내 모든 율례를 지켜 행하였으면 그는 반드시 살려니와'),
    (20894, '범죄하는 그 영혼은 죽을지라 아들은 아버지의 죄악을 담당하지 아니할 것이요 아버지는 아들의 죄악을 담당하지 아니하리니 의인의 공의도 자기에게로 돌아가고 악인의 악도 자기에게로 돌아가리라'),
    (20895, '○그러나 악인이 만일 그가 행한 모든 죄에서 돌이켜 떠나 내 모든 율례를 지키고 정의와 공의를 행하면 반드시 살고 죽지 아니할 것이라'),
    (20898, '만일 의인이 돌이켜 그 공의에서 떠나 범죄하고 악인이 행하는 모든 가증한 일대로 행하면 살겠느냐 그가 행한 공의로운 일은 하나도 기억함이 되지 아니하리니 그가 그 범한 허물과 그 지은 죄로 죽으리라'),
    (20899, '○그런데 너희는 이르기를 주의 길이 공평하지 아니하다 하는도다 이스라엘 족속아 들을지어다 내 길이 어찌 공평하지 아니하냐 너희 길이 공평하지 아니한 것이 아니냐'),
    (20904, '주 여호와의 말씀이니라 이스라엘 족속아 내가 너희 각 사람이 행한 대로 심판할지라 너희는 돌이켜 회개하고 모든 죄에서 떠날지어다 그리한즉 그것이 너희에게 죄악의 걸림돌이 되지 아니하리라'),
    (21085, '건 후에 물을 붓고 양 떼에서 한 마리를 골라 각을 뜨고 그 넓적다리와 어깨 고기의 모든 좋은 덩이를 그 가운데에 모아 넣으며 고른 뼈를 가득히 담고'),
    (21086, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 피를 흘린 성읍, 녹슨 가마 곧 그 속의 녹을 없이하지 아니한 가마여 화 있을진저 제비 뽑을 것도 없이 그 덩이를 하나하나 꺼낼지어다'),
    (21094, '나 여호와가 말하였은즉 그 일이 이루어질지라 내가 돌이키지도 아니하고 아끼지도 아니하며 뉘우치지도 아니하고 행하리니 그들이 네 모든 행위대로 너를 재판하리라 주 여호와의 말씀이니라'),
    (21095, '<에스겔의 아내가 죽다> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (21101, '너는 이스라엘 족속에게 이르기를 주 여호와의 말씀에 내 성소는 너희 세력의 영광이요 너희 눈의 기쁨이요 너희 마음에 아낌이 되거니와 내가 더럽힐 것이며 너희의 버려 둔 자녀를 칼에 엎드러지게 할지라'),
    (21105, '○인자야 내가 그 힘과 그 즐거워하는 영광과 그 눈이 기뻐하는 것과 그 마음이 간절하게 생각하는 자녀를 데려가는 날'),
    (21110, '너는 암몬 족속에게 이르기를 너희는 주 여호와의 말씀을 들을지어다 주 여호와께서 이같이 말씀하셨느니라 내 성소가 더럽힘을 받을 때에 네가 그것에 관하여, 이스라엘 땅이 황폐할 때에 네가 그것에 관하여, 유다 족속이 사로잡힐 때에 네가 그들에 대하여 이르기를 아하 좋다 하였도다'),
    (21114, '그런즉 내가 손을 네 위에 펴서 너를 다른 민족에게 넘겨 주어 노략을 당하게 하며 너를 만민 중에서 끊어 버리며 너를 여러 나라 가운데에서 패망하게 하여 멸하리니 내가 주 여호와인 줄을 너희가 알리라 하셨다 하라'),
    (21115, '<모압과 세일이 받을 심판> ○주 여호와께서 이같이 말씀하셨느니라 모압과 세일이 이르기를 유다 족속은 모든 이방과 다름이 없다 하도다'),
    (21119, '<에돔과 블레셋이 받을 심판> ○주 여호와께서 이같이 말씀하셨느니라 에돔이 유다 족속을 쳐서 원수를 갚았고 원수를 갚음으로 심히 범죄하였도다'),
    (21005, '네가 흘린 피로 말미암아 죄가 있고 네가 만든 우상으로 말미암아 스스로 더럽혔으니 네 날이 가까웠고 네 연한이 찼도다 그러므로 내가 너로 이방의 능욕을 받으며 만국의 조롱 거리가 되게 하였노라'),
    (21007, '○이스라엘 모든 고관은 각기 권세대로 피를 흘리려고 네 가운데에 있었도다'),
    (21014, '○네가 불의를 행하여 이익을 얻은 일과 네 가운데에 피 흘린 일로 말미암아 내가 손뼉을 쳤나니'),
    (21018, '<풀무 불에 들어간 이스라엘> ○여호와의 말씀이 내게 임하여 이르시되'),
    (21024, '<선지자 제사장 고관들의 죄> ○여호와의 말씀이 내게 임하여 이르시되'),
    (21027, '그 제사장들은 내 율법을 범하였으며 나의 성물을 더럽혔으며 거룩함과 속된 것을 구별하지 아니하였으며 부정함과 정한 것을 사람이 구별하게 하지 아니하였으며 그의 눈을 가리어 나의 안식일을 보지 아니하였으므로 내가 그들 가운데에서 더럽힘을 받았느니라'),
    (21037, '○오홀라가 내게 속하였을 때에 행음하여 그가 연애하는 자 곧 그의 이웃 앗수르 사람을 사모하였나니'),
    (21043, '○그 아우 오홀리바가 이것을 보고도 그의 형보다 음욕을 더하며 그의 형의 간음함보다 그 간음이 더 심하므로 그의 형보다 더 부패하여졌느니라'),
    (21054, '<오홀리바가 받은 재판> ○그러므로 오홀리바야 주 여호와께서 이같이 말씀하셨느니라 나는 네가 사랑하다가 싫어하던 자들을 충동하여 그들이 사방에서 와서 너를 치게 하리니'),
    (21068, '<오홀라와 오홀리바가 받은 재판> ○여호와께서 또 내게 이르시되 인자야 네가 오홀라와 오홀리바를 심판하려느냐 그러면 그 가증한 일을 그들에게 말하라'),
    (21075, '○내가 음행으로 쇠한 여인을 가리켜 말하노라 그가 그래도 그들과 피차 행음하는도다'),
    (21078, '주 여호와께서 이같이 말씀하셨느니라 그들에게 무리를 올려 보내 그들이 공포와 약탈을 당하게 하라'),
    (20976, '그들이 네게 묻기를 네가 어찌하여 탄식하느냐 하거든 대답하기를 재앙이 다가온다는 소문 때문이니 각 마음이 녹으며 모든 손이 약하여지며 각 영이 쇠하며 모든 무릎이 물과 같이 약해지리라 보라 재앙이 오나니 반드시 이루어지리라 주 여호와의 말씀이니라 하라'),
    (20977, '○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20993, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 너희의 악이 기억을 되살리며 너희의 허물이 드러나며 너희 모든 행위의 죄가 나타났도다 너희가 기억한 바 되었은즉 그 손에 잡히리라'),
    (20997, '○인자야 너는 주 여호와께서 암몬 족속과 그의 능욕에 대하여 이같이 말씀하셨다고 예언하라 너는 이르기를 칼이 뽑히도다 칼이 뽑히도다 죽이며 멸절하며 번개 같이 되기 위하여 빛났도다'),
    (20921, '<하나님의 뜻, 이스라엘의 반역,> 일곱째 해 다섯째 달 열째 날에 이스라엘 장로 여러 사람이 여호와께 물으려고 와서 내 앞에 앉으니'),
    (20923, '인자야 이스라엘 장로들에게 말하여 이르라 주 여호와께서 이렇게 말씀하셨느니라 너희가 내게 물으려고 왔느냐 내가 나의 목숨을 걸고 맹세하거니와 너희가 내게 묻기를 내가 용납하지 아니하리라 주 여호와의 말씀이니라'),
    (20925, '이르라 주 여호와께서 이같이 말씀하셨느니라 옛날에 내가 이스라엘을 택하고 야곱 집의 후예를 향하여 내 손을 들어 맹세하고 애굽 땅에서 그들에게 나타나 맹세하여 이르기를 나는 여호와 너희 하나님이라 하였노라'),
    (20928, '그들이 내게 반역하여 내 말을 즐겨 듣지 아니하고 그들의 눈을 끄는 바 가증한 것을 각기 버리지 아니하며 애굽의 우상들을 떠나지 아니하므로 내가 말하기를 내가 애굽 땅에서 그들에게 나의 분노를 쏟으며 그들에게 진노를 이루리라 하였노라'),
    (20929, '그러나 내가 그들이 거주하는 이방인의 눈 앞에서 그들에게 나타나 그들을 애굽 땅에서 인도하여 내었나니 이는 내 이름을 위함이라 내 이름을 그 이방인의 눈 앞에서 더럽히지 아니하려고 행하였음이라'),
    (20930, '○그러므로 내가 그들을 애굽 땅에서 나와서 광야에 이르게 하고'),
    (20933, '그러나 이스라엘 족속이 광야에서 내게 반역하여 사람이 준행하면 그로 말미암아 삶을 얻을 나의 율례를 준행하지 아니하며 나의 규례를 멸시하였고 나의 안식일을 크게 더럽혔으므로 내가 이르기를 내가 내 분노를 광야에서 그들에게 쏟아 멸하리라 하였으나'),
    (20938, '○내가 광야에서 그들의 자손에게 이르기를 너희 조상들의 율례를 따르지 말며 그 규례를 지키지 말며 그 우상들로 말미암아 스스로 더럽히지 말라'),
    (20941, '그러나 그들의 자손이 내게 반역하여 사람이 지켜 행하면 그로 말미암아 삶을 얻을 나의 율례를 따르지 아니하며 나의 규례를 지켜 행하지 아니하였고 나의 안식일을 더럽힌지라 이에 내가 이르기를 내가 광야에서 그들에게 내 분노를 쏟으며 그들에게 내 진노를 이루리라 하였으나'),
    (20947, '○그런즉 인자야 이스라엘 족속에게 말하여 이르라 주 여호와께서 이같이 말씀하셨느니라 너희 조상들이 또 내게 범죄하여 나를 욕되게 하였느니라'),
    (20948, '내가 내 손을 들어 그들에게 주기로 맹세한 땅으로 그들을 인도하여 들였더니 그들이 모든 높은 산과 모든 무성한 나무를 보고 거기에서 제사를 드리고 분노하게 하는 제물을 올리며 거기서 또 분향하고 전제물을 부어 드린지라'),
    (20951, '너희가 또 너희 아들을 화제로 삼아 불 가운데로 지나게 하며 오늘까지 너희 자신을 우상들로 말미암아 더럽히느냐 이스라엘 족속아 너희가 내게 묻기를 내가 용납하겠느냐 주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 너희가 내게 묻기를 내가 용납하지 아니하리라'),
    (20953, '<맹세한 땅으로 이스라엘을 인도하리라> ○주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 내가 능한 손과 편 팔로 분노를 쏟아 너희를 반드시 다스릴지라'),
    (20958, '너희 가운데에서 반역하는 자와 내게 범죄하는 자를 모두 제하여 버릴지라 그들을 그 머물러 살던 땅에서는 나오게 하여도 이스라엘 땅에는 들어가지 못하게 하리니 너희가 나는 여호와인 줄을 알리라'),
    (20959, '주 여호와께서 이같이 말씀하셨느니라 이스라엘 족속아 너희가 내 말을 듣지 아니하려거든 가서 각각 그 우상을 섬기라 그렇게 하려거든 이 후에 다시는 너희 예물과 너희 우상들로 내 거룩한 이름을 더럽히지 말지니라'),
    (20960, '○주 여호와의 말씀이니라 이스라엘 온 족속이 그 땅에 있어서 내 거룩한 산 곧 이스라엘의 높은 산에서 다 나를 섬기리니 거기에서 내가 그들을 기쁘게 받을지라 거기에서 너희 예물과 너희가 드리는 첫 열매와 너희 모든 성물을 요구하리라'),
    (20961, '내가 너희를 인도하여 여러 나라 가운데에서 나오게 하고 너희가 흩어진 여러 민족 가운데에서 모아 낼 때에 내가 너희를 향기로 받고 내가 또 너희로 말미암아 내 거룩함을 여러 나라의 목전에서 나타낼 것이며'),
    (20965, '<불타는 숲의 비유> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (20967, '남쪽의 숲에게 이르기를 여호와의 말씀을 들을지어다 주 여호와께서 이같이 말씀하셨느니라 내가 너의 가운데에 불을 일으켜 모든 푸른 나무와 모든 마른 나무를 없애리니 맹렬한 불꽃이 꺼지지 아니하고 남에서 북까지 모든 얼굴이 그슬릴지라'),
    (21131, '○주 여호와께서 이같이 말씀하셨느니라 내가 왕들 중의 왕 곧 바벨론의 느부갓네살 왕으로 하여금 북쪽에서 말과 병거와 기병과 군대와 백성의 큰 무리를 거느리고 와서 두로를 치게 할 때에'),
    (21139, '○주 여호와께서 이같이 두로에 대하여 말씀하시되 네가 엎드러지는 소리에 모든 섬이 진동하지 아니하겠느냐 곧 너희 가운데에 상한 자가 부르짖으며 죽임을 당할 때에라'),
    (21141, '그들이 너를 위하여 슬픈 노래를 불러 이르기를 항해자가 살았던 유명한 성읍이여 너와 너의 주민이 바다 가운데에 있어 견고하였도다 해변의 모든 주민을 두렵게 하였더니 어찌 그리 멸망하였는고'),
    (21143, '○주 여호와께서 이같이 말씀하셨느니라 내가 너를 주민이 없는 성읍과 같이 황폐한 성읍이 되게 하고 깊은 바다가 네 위에 오르게 하며 큰 물이 너를 덮게 할 때에'),
    (21144, '내가 너를 구덩이에 내려가는 자와 함께 내려가서 옛적 사람에게로 나아가게 하고 너를 그 구덩이에 내려간 자와 함께 땅 깊은 곳 예로부터 황폐한 곳에 살게 하리라 네가 다시는 사람이 거주하는 곳이 되지 못하리니 살아 있는 자의 땅에서 영광을 얻지 못하리라'),
    (21157, '○다시스는 각종 보화가 풍부하므로 너와 거래하였음이여 은과 철과 주석과 납을 네 물품과 바꾸어 갔도다'),
    (21171, '○네 사공이 너를 인도하여 큰 물에 이르게 함이여 동풍이 바다 한가운데에서 너를 무찔렀도다'),
    (21172, '네 재물과 상품과 바꾼 물건과 네 사공과 선장과 네 배의 틈을 막는 자와 네 상인과 네 가운데에 있는 모든 용사와 네 가운데에 있는 모든 무리가 네가 패망하는 날에 다 바다 한가운데에 빠질 것임이여'),
    (21264, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 그의 키가 크고 꼭대기가 구름에 닿아서 높이 솟아났으므로 마음이 교만하였은즉'),
    (21266, '여러 나라의 포악한 다른 민족이 그를 찍어 버렸으므로 그 가는 가지가 산과 모든 골짜기에 떨어졌고 그 굵은 가지가 그 땅 모든 물 가에 꺾어졌으며 세상 모든 백성이 그를 버리고 그 그늘 아래에서 떠나매'),
    (21268, '이는 물 가에 있는 모든 나무는 키가 크다고 교만하지 못하게 하며 그 꼭대기가 구름에 닿지 못하게 하며 또 물을 마시는 모든 나무가 스스로 높아 서지 못하게 함이니 그들을 다 죽음에 넘겨 주어 사람들 가운데에서 구덩이로 내려가는 자와 함께 지하로 내려가게 하였음이라'),
    (21269, '○주 여호와께서 이같이 말씀하셨느니라 그가 스올에 내려가던 날에 내가 그를 위하여 슬프게 울게 하며 깊은 바다를 덮으며 모든 강을 쉬게 하며 큰 물을 그치게 하고 레바논이 그를 위하여 슬프게 울게 하며 들의 모든 나무를 그로 말미암아 쇠잔하게 하였느니라'),
    (21270, '내가 그를 구덩이에 내려가는 자와 함께 스올에 떨어뜨리던 때에 백성들이 그 떨어지는 소리로 말미암아 진동하게 하였고 물을 마시는 에덴의 모든 나무 곧 레바논의 뛰어나고 아름다운 나무들이 지하에서 위로를 받게 하였느니라'),
    (21272, '○너의 영광과 위대함이 에덴의 나무들 중에서 어떤 것과 같은고 그러나 네가 에덴의 나무들과 함께 지하에 내려갈 것이요 거기에서 할례를 받지 못하고 칼에 죽임을 당한 자 가운데에 누우리라 이들은 바로와 그의 모든 군대니라 주 여호와의 말씀이니라 하라'),
    (21183, '인자야 너는 두로 왕에게 이르기를 주 여호와께서 이같이 말씀하시되 네 마음이 교만하여 말하기를 나는 신이라 내가 하나님의 자리 곧 바다 가운데에 앉아 있다 하도다 네 마음이 하나님의 마음 같은 체할지라도 너는 사람이요 신이 아니거늘'),
    (21192, '여호와의 말씀이 또 내게 임하여 이르시되'),
    (21194, '네가 옛적에 하나님의 동산 에덴에 있어서 각종 보석 곧 홍보석과 황보석과 금강석과 황옥과 홍마노와 창옥과 청보석과 남보석과 홍옥과 황금으로 단장하였음이여 네가 지음을 받던 날에 너를 위하여 소고와 비파가 준비되었도다'),
    (21201, '<시돈이 받을 심판> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (21203, '너는 이르기를 주 여호와께서 이같이 말씀하시되 시돈아 내가 너를 대적하나니 네 가운데에서 내 영광이 나타나리라 하셨다 하라 내가 그 가운데에서 심판을 행하여 내 거룩함을 나타낼 때에 무리가 나를 여호와인 줄을 알지라'),
    (21206, '<이스라엘이 복을 받으리라> ○주 여호와께서 이같이 말씀하셨느니라 내가 여러 민족 가운데에 흩어져 있는 이스라엘 족속을 모으고 그들로 말미암아 여러 나라의 눈 앞에서 내 거룩함을 나타낼 때에 그들이 고국 땅 곧 내 종 야곱에게 준 땅에 거주할지라'),
    (21234, '○여호와께서 이같이 말씀하셨느니라 애굽을 붙들어 주는 자도 엎드러질 것이요 애굽의 교만한 권세도 낮아질 것이라 믹돌에서부터 수에네까지 무리가 그 가운데에서 칼에 엎드러지리라 주 여호와의 말씀이니라'),
    (21238, '○주 여호와께서 이같이 말씀하셨느니라 내가 또 바벨론의 느부갓네살 왕의 손으로 애굽의 무리들을 끊으리니'),
    (21248, '<애굽 왕의 꺾인 팔> ○열한째 해 첫째 달 일곱째 날에 여호와의 말씀이 내게 임하여 이르시되'),
    (21210, '너는 말하여 이르기를 주 여호와께서 이같이 말씀하시되 애굽의 바로 왕이여 내가 너를 대적하노라 너는 자기의 강들 가운데에 누운 큰 악어라 스스로 이르기를 나의 이 강은 내 것이라 내가 나를 위하여 만들었다 하는도다'),
    (21215, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 내가 칼이 네게 임하게 하여 네게서 사람과 짐승을 끊은즉'),
    (21224, '<느부갓네살이 애굽을 정복하리라> ○스물일곱째 해 첫째 달 초하루에 여호와의 말씀이 내게 임하여 이르시되'),
    (21225, '인자야 바벨론의 느부갓네살 왕이 그의 군대로 두로를 치게 할 때에 크게 수고하여 모든 머리털이 무지러졌고 모든 어깨가 벗어졌으나 그와 군대가 그 수고한 대가를 두로에서 얻지 못하였느니라'),
    (21226, '그러므로 주 여호와께서 이같이 말씀하셨느니라 내가 애굽 땅을 바벨론의 느부갓네살 왕에게 넘기리니 그가 그 무리를 잡아가며 물건을 노략하며 빼앗아 갈 것이라 이것이 그 군대의 보상이 되리라'),
    (21228, '○그 날에 나는 이스라엘 족속에게 한 뿔이 돋아나게 하고 나는 또 네가 그들 가운데에서 입을 열게 하리니 내가 여호와인 줄을 그들이 알리라'),
    (21274, '인자야 너는 애굽의 바로 왕에 대하여 슬픈 노래를 불러 그에게 이르라 너를 여러 나라에서 사자로 생각하였더니 실상은 바다 가운데의 큰 악어라 강에서 튀어 일어나 발로 물을 휘저어 그 강을 더럽혔도다'),
    (21282, '내가 그 많은 백성을 너로 말미암아 놀라게 할 것이며 내가 내 칼이 그들의 왕 앞에서 춤추게 할 때에 그 왕이 너로 말미암아 심히 두려워할 것이며 네가 엎드러지는 날에 그들이 각각 자기 생명을 위하여 무시로 떨리로다'),
    (21283, '○주 여호와께서 이같이 말씀하셨느니라 바벨론 왕의 칼이 네게 오리로다'),
    (21289, '<죽은 자들의 세계> ○열두째 해 어느 달 열다섯째 날에 여호와의 말씀이 내게 임하여 이르시되'),
    (21294, '○거기에 앗수르와 그 온 무리가 있음이여 다 죽임을 당하여 칼에 엎드러진 자라 그 무덤이 그 사방에 있도다'),
    (21296, '○거기에 엘람이 있고 그 모든 무리가 그 무덤 사방에 있음이여 그들은 다 할례를 받지 못하고 죽임을 당하여 칼에 엎드러져 지하에 내려간 자로다 그들이 생존하는 사람들의 세상에서 두렵게 하였으나 이제는 구덩이에 내려가는 자와 함께 수치를 당하였도다'),
    (21297, '그와 그 모든 무리를 위하여 죽임을 당한 자 가운데에 침상을 놓았고 그 여러 무덤은 사방에 있음이여 그들은 다 할례를 받지 못하고 칼에 죽임을 당한 자로다 그들이 생존하는 사람들의 세상에서 두렵게 하였으나 이제는 구덩이에 내려가는 자와 함께 수치를 당하고 죽임을 당한 자 가운데에 뉘었도다'),
    (21298, '○거기에 메섹과 두발과 그 모든 무리가 있고 그 여러 무덤은 사방에 있음이여 그들은 다 할례를 받지 못하고 칼에 죽임을 당한 자로다 그들이 생존하는 사람들의 세상에서 두렵게 하였으나'),
    (21299, '그들이 할례를 받지 못한 자 가운데에 이미 엎드러진 용사와 함께 누운 것이 마땅하지 아니하냐 이 용사들은 다 무기를 가지고 스올에 내려가서 자기의 칼을 베개로 삼았으니 그 백골이 자기 죄악을 졌음이여 생존하는 사람들의 세상에서 용사의 두려움이 있던 자로다'),
    (21301, '○거기에 에돔 곧 그 왕들과 그 모든 고관이 있음이여 그들이 강성하였었으나 칼에 죽임을 당한 자와 함께 있겠고 할례를 받지 못하고 구덩이에 내려간 자와 함께 누우리로다'),
    (21302, '거기에 죽임을 당한 자와 함께 내려간 북쪽 모든 방백과 모든 시돈 사람이 있음이여 그들이 본래는 강성하였으므로 두렵게 하였으나 이제는 부끄러움을 품고 할례를 받지 못하고 칼에 죽임을 당한 자와 함께 누웠고 구덩이에 내려가는 자와 함께 수치를 당하였도다'),
    (21303, '○바로가 그들을 보고 그 모든 무리로 말미암아 위로를 받을 것임이여 칼에 죽임을 당한 바로와 그 온 군대가 그러하리로다 주 여호와의 말씀이니라'),
    (21304, '내가 바로로 하여금 생존하는 사람들의 세상에서 사람을 두렵게 하게 하였으나 이제는 그가 그 모든 무리와 더불어 할례를 받지 못한 자 곧 칼에 죽임을 당한 자와 함께 누이리로다 주 여호와의 말씀이니라'),
    (21378, '○네가 말하기를 이 두 민족과 두 땅은 다 내 것이며 내 기업이 되리라 하였도다 그러나 여호와께서 거기에 계셨느니라'),
    (21305, '<여호와께서 에스겔을 파수꾼으로 삼으시다> 여호와의 말씀이 내게 임하여 이르시되'),
    (21310, '그러나 칼이 임함을 파수꾼이 보고도 나팔을 불지 아니하여 백성에게 경고하지 아니하므로 그 중의 한 사람이 그 임하는 칼에 제거 당하면 그는 자기 죄악으로 말미암아 제거되려니와 그 죄는 내가 파수꾼의 손에서 찾으리라'),
    (21311, '○인자야 내가 너를 이스라엘 족속의 파수꾼으로 삼음이 이와 같으니라 그런즉 너는 내 입의 말을 듣고 나를 대신하여 그들에게 경고할지어다'),
    (21312, '가령 내가 악인에게 이르기를 악인아 너는 반드시 죽으리라 하였다 하자 네가 그 악인에게 말로 경고하여 그의 길에서 떠나게 하지 아니하면 그 악인은 자기 죄악으로 말미암아 죽으려니와 내가 그의 피를 네 손에서 찾으리라'),
    (21314, '<의인의 범죄와 악인의 회개> ○그런즉 인자야 너는 이스라엘 족속에게 이르기를 너희가 말하여 이르되 우리의 허물과 죄가 이미 우리에게 있어 우리로 그 가운데에서 쇠퇴하게 하니 어찌 능히 살리요 하거니와'),
    (21315, '너는 그들에게 말하라 주 여호와의 말씀이니라 나의 삶을 두고 맹세하노니 나는 악인이 죽는 것을 기뻐하지 아니하고 악인이 그의 길에서 돌이켜 떠나 사는 것을 기뻐하노라 이스라엘 족속아 돌이키고 돌이키라 너희 악한 길에서 떠나라 어찌 죽고자 하느냐 하셨다 하라'),
    (21316, '인자야 너는 네 민족에게 이르기를 의인이 범죄하는 날에는 그 공의가 구원하지 못할 것이요 악인이 돌이켜 그 악에서 떠나는 날에는 그 악이 그를 엎드러뜨리지 못할 것인즉 의인이 범죄하는 날에는 그 의로 말미암아 살지 못하리라'),
    (21317, '가령 내가 의인에게 말하기를 너는 살리라 하였다 하자 그가 그 공의를 스스로 믿고 죄악을 행하면 그 모든 의로운 행위가 하나도 기억되지 아니하리니 그가 그 지은 죄악으로 말미암아 곧 그 안에서 죽으리라'),
    (21321, '○그래도 네 민족은 말하기를 주의 길이 바르지 아니하다 하는도다 그러나 실상은 그들의 길이 바르지 아니하니라'),
    (21325, '<예루살렘의 함락 소식> ○우리가 사로잡힌 지 열두째 해 열째 달 다섯째 날에 예루살렘에서부터 도망하여 온 자가 내게 나아와 말하기를 그 성이 함락되었다 하였는데'),
    (21327, '<백성의 죄와 여호와의 맹세> ○여호와의 말씀이 내게 임하여 이르시되'),
    (21328, '인자야 이 이스라엘의 이 황폐한 땅에 거주하는 자들이 말하여 이르기를 아브라함은 오직 한 사람이라도 이 땅을 기업으로 얻었나니 우리가 많은즉 더욱 이 땅을 우리에게 기업으로 주신 것이 되느니라 하는도다'),
    (21331, '너는 그들에게 이르기를 주 여호와께서 이같이 말씀하시되 내가 나의 삶을 두고 맹세하노니 황무지에 있는 자는 칼에 엎드러뜨리고 들에 있는 자는 들짐승에게 넘겨 먹히게 하고 산성과 굴에 있는 자는 전염병에 죽게 하리라'),
    (21334, '<선지자의 말과 백성> ○인자야 네 민족이 담 곁에서와 집 문에서 너에 대하여 말하며 각각 그 형제와 더불어 말하여 이르기를 자, 가서 여호와께로부터 무슨 말씀이 나오는가 들어 보자 하고'),
    (21339, '인자야 너는 이스라엘 목자들에게 예언하라 그들 곧 목자들에게 예언하여 이르기를 주 여호와께서 이같이 말씀하시되 자기만 먹는 이스라엘 목자들은 화 있을진저 목자들이 양 떼를 먹이는 것이 마땅하지 아니하냐'),
    (21341, '너희가 그 연약한 자를 강하게 아니하며 병든 자를 고치지 아니하며 상한 자를 싸매 주지 아니하며 쫓기는 자를 돌아오게 하지 아니하며 잃어버린 자를 찾지 아니하고 다만 포악으로 그것들을 다스렸도다'),
    (21344, '<여호와께서 양 떼를 구원하시리라> ○그러므로 목자들아 여호와의 말씀을 들을지어다'),
    (21345, '주 여호와의 말씀에 내가 나의 삶을 두고 맹세하노라 내 양 떼가 노략 거리가 되고 모든 들짐승의 밥이 된 것은 목자가 없기 때문이라 내 목자들이 내 양을 찾지 아니하고 자기만 먹이고 내 양 떼를 먹이지 아니하였도다'),
    (21347, '주 여호와께서 이같이 말씀하시되 내가 목자들을 대적하여 내 양 떼를 그들의 손에서 찾으리니 목자들이 양을 먹이지 못할 뿐 아니라 그들이 다시는 자기도 먹이지 못할지라 내가 내 양을 그들의 입에서 건져내어서 다시는 그 먹이가 되지 아니하게 하리라'),
    (21354, '○주 여호와께서 이같이 말씀하셨느니라 나의 양 떼 너희여 내가 양과 양 사이와 숫양과 숫염소 사이에서 심판하노라'),
    (21357, '○그러므로 주 여호와께서 그들에게 이같이 말씀하시되 나 곧 내가 살진 양과 파리한 양 사이에서 심판하리라'),
    (21362, '○내가 또 그들과 화평의 언약을 맺고 악한 짐승을 그 땅에서 그치게 하리니 그들이 빈 들에 평안히 거하며 수풀 가운데에서 잘지라'),
    (21364, '그리한즉 밭에 나무가 열매를 맺으며 땅이 그 소산을 내리니 그들이 그 땅에서 평안할지라 내가 그들의 멍에의 나무를 꺾고 그들을 종으로 삼은 자의 손에서 그들을 건져낸 후에 내가 여호와인 줄을 그들이 알겠고'),
    (21428, '○이에 내가 명령을 따라 대언하니 대언할 때에 소리가 나고 움직이며 이 뼈, 저 뼈가 들어 맞아 뼈들이 서로 연결되더라'),
    (21430, '또 내게 이르시되 인자야 너는 생기를 향하여 대언하라 생기에게 대언하여 이르기를 주 여호와께서 이같이 말씀하시기를 생기야 사방에서부터 와서 이 죽음을 당한 자에게 불어서 살아나게 하라 하셨다 하라'),
    (21432, '○또 내게 이르시되 인자야 이 뼈들은 이스라엘 온 족속이라 그들이 이르기를 우리의 뼈들이 말랐고 우리의 소망이 없어졌으니 우리는 다 멸절되었다 하느니라'),
    (21436, '<유다와 이스라엘의 통일> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (21440, '너는 곧 이르기를 주 여호와께서 이같이 말씀하시기를 내가 에브라임의 손에 있는 바 요셉과 그 짝 이스라엘 지파들의 막대기를 가져다가 유다의 막대기에 붙여서 한 막대기가 되게 한즉 내 손에서 하나가 되리라 하셨다 하고'),
    (21444, '그들이 그 우상들과 가증한 물건과 그 모든 죄악으로 더 이상 자신들을 더럽히지 아니하리라 내가 그들을 그 범죄한 모든 처소에서 구원하여 정결하게 한즉 그들은 내 백성이 되고 나는 그들의 하나님이 되리라'),
    (21445, '○내 종 다윗이 그들의 왕이 되리니 그들 모두에게 한 목자가 있을 것이라 그들이 내 규례를 준수하고 내 율례를 지켜 행하며'),
    (21456, '○너는 스스로 예비하되 너와 네게 모인 무리들이 다 스스로 예비하고 너는 그들의 우두머리가 될지어다'),
    (21459, '○주 여호와께서 이같이 말씀하셨느니라 그 날에 네 마음에서 여러 가지 생각이 나서 악한 꾀를 내어'),
    (21462, '스바와 드단과 다시스의 상인과 그 부자들이 네게 이르기를 네가 탈취하러 왔느냐 네가 네 무리를 모아 노략하고자 하느냐 은과 금을 빼앗으며 짐승과 재물을 빼앗으며 물건을 크게 약탈하여 가고자 하느냐 하리라'),
    (21465, '구름이 땅을 덮음 같이 내 백성 이스라엘을 치러 오리라 곡아 끝 날에 내가 너를 이끌어다가 내 땅을 치게 하리니 이는 내가 너로 말미암아 이방 사람의 눈 앞에서 내 거룩함을 나타내어 그들이 다 나를 알게 하려 함이라'),
    (21466, '<곡의 심판> ○주 여호와께서 이같이 말씀하셨느니라 내가 옛적에 내 종 이스라엘 선지자들을 통하여 말한 사람이 네가 아니냐 그들이 그 때에 여러 해 동안 예언하기를 내가 너를 이끌어다가 그들을 치게 하리라'),
    (21386, '그러므로 너는 예언하여 이르기를 주 여호와께서 이같이 말씀하시기를 그들이 너희를 황폐하게 하고 너희 사방을 삼켜 너희가 남은 이방인의 기업이 되게 하여 사람의 말 거리와 백성의 비방 거리가 되게 하였도다'),
    (21387, '그러므로 이스라엘 산들아 주 여호와의 말씀을 들을지어다 산들과 멧부리들과 시내들과 골짜기들과 황폐한 사막들과 사방에 남아 있는 이방인의 노략 거리와 조롱 거리가 된 버린 성읍들에게 주 여호와께서 이같이 말씀하셨느니라'),
    (21388, '주 여호와께서 이같이 말씀하시기를 내가 진실로 내 맹렬한 질투로 남아 있는 이방인과 에돔 온 땅을 쳐서 말하였노니 이는 그들이 심히 즐거워하는 마음과 멸시하는 심령으로 내 땅을 빼앗아 노략하여 자기 소유를 삼았음이라'),
    (21389, '그러므로 너는 이스라엘 땅에 대하여 예언하되 그 산들과 멧부리들과 시내들과 골짜기들에 관하여 이르기를 주 여호와께서 이같이 말씀하시기를 내가 내 질투와 내 분노로 말하였나니 이는 너희가 이방의 수치를 당하였음이라'),
    (21399, '<이스라엘을 정결하게 하시다> ○여호와의 말씀이 또 내게 임하여 이르시되'),
    (21405, '○그러므로 너는 이스라엘 족속에게 이르기를 주 여호와께서 이같이 말씀하시기를 이스라엘 족속아 내가 이렇게 행함은 너희를 위함이 아니요 너희가 들어간 그 여러 나라에서 더럽힌 나의 거룩한 이름을 위함이라'),
    (21406, '여러 나라 가운데에서 더럽혀진 이름 곧 너희가 그들 가운데에서 더럽힌 나의 큰 이름을 내가 거룩하게 할지라 내가 그들의 눈 앞에서 너희로 말미암아 나의 거룩함을 나타내리니 내가 여호와인 줄을 여러 나라 사람이 알리라 주 여호와의 말씀이니라'),
    (21415, '○주 여호와의 말씀이니라 내가 이렇게 행함은 너희를 위함이 아닌 줄을 너희가 알리라 이스라엘 족속아 너희 행위로 말미암아 부끄러워하고 한탄할지어다'),
    (21420, '○주 여호와께서 이같이 말씀하셨느니라 그래도 이스라엘 족속이 이같이 자기들에게 이루어 주기를 내게 구하여야 할지라 내가 그들의 수효를 양 떼 같이 많아지게 하되'),
    (21556, '골방은 삼 층인데 골방 위에 골방이 있어 모두 서른이라 그 삼면 골방이 성전 벽 밖으로 그 벽에 붙어 있는데 성전 벽 속을 뚫지는 아니하였으며'),
    (21557, '이 두루 있는 골방은 그 층이 높아질수록 넓으므로 성전에 둘린 이 골방이 높아질수록 성전에 가까워졌으나 성전의 넓이는 아래 위가 같으며 골방은 아래층에서 중층으로 위층에 올라가게 되었더라'),
    (21562, '<서쪽 건물과 성전의 넓이> ○서쪽 뜰 뒤에 건물이 있는데 너비는 일흔 척이요 길이는 아흔 척이며 그 사방 벽의 두께는 다섯 척이더라'),
    (21571, '<나무 제단과 성전의 문들> ○외전 문설주는 네모졌고 내전 전면에 있는 양식은 이러하니'),
    (21586, '○남쪽 골방 뜰 맞은쪽과 남쪽 건물 맞은쪽에도 방 둘이 있는데'),
    (21589, '○그가 내게 이르되 좌우 골방 뜰 앞 곧 북쪽과 남쪽에 있는 방들은 거룩한 방이라 여호와를 가까이 하는 제사장들이 지성물을 거기에서 먹을 것이며 지성물 곧 소제와 속죄제와 속건제의 제물을 거기 둘 것이니 이는 거룩한 곳이라'),
    (21591, '<성전의 사면 담을 측량하다> ○그가 안에 있는 성전 측량하기를 마친 후에 나를 데리고 동쪽을 향한 문의 길로 나가서 사방 담을 측량하는데'),
    (21505, '그 사람이 내게 이르되 인자야 내가 네게 보이는 그것을 눈으로 보고 귀로 들으며 네 마음으로 생각할지어다 내가 이것을 네게 보이려고 이리로 데리고 왔나니 너는 본 것을 다 이스라엘 족속에게 전할지어다 하더라'),
    (21506, '<동쪽을 향한 문> ○내가 본즉 집 바깥 사방으로 담이 있더라 그 사람의 손에 측량하는 장대를 잡았는데 그 길이가 팔꿈치에서 손가락에 이르고 한 손바닥 너비가 더한 자로 여섯 척이라 그 담을 측량하니 두께가 한 장대요 높이도 한 장대며'),
    (21513, '방 앞에 칸막이 벽이 있는데 이쪽 간막이 벽도 한 척이요 저쪽 간막이 벽도 한 척이며 그 방은 이쪽도 여섯 척이요 저쪽도 여섯 척이며'),
    (21518, '<바깥뜰> ○그가 나를 데리고 바깥뜰에 들어가니 뜰 삼면에 박석 깔린 땅이 있고 그 박석 깔린 땅 위에 여러 방이 있는데 모두 서른이며'),
    (21521, '<북쪽을 향한 문> ○그가 바깥뜰 북쪽을 향한 문간의 길이와 너비를 측량하니'),
    (21525, '<남쪽을 향한 문> ○그가 또 나를 이끌고 남으로 간즉 남쪽을 향한 문간이 있는데 그 벽과 현관을 측량하니 먼저 측량한 것과 같고'),
    (21529, '<안뜰 남쪽 문> ○그가 나를 데리고 그 남문을 통하여 안뜰에 들어가서 그 남문의 너비를 측량하니 크기는'),
    (21533, '<안뜰 동쪽 문> ○그가 나를 데리고 안뜰 동쪽으로 가서 그 문간을 측량하니 크기는'),
    (21536, '<안뜰 북쪽 문> ○그가 또 나를 데리고 북문에 이르러 측량하니 크기는'),
    (21539, '<안뜰 북쪽 문의 부속 건물들> ○그 문 벽 곁에 문이 있는 방이 있는데 그것은 번제물을 씻는 방이며'),
    (21545, '○안문 밖에 있는 안뜰에는 노래하는 자의 방 둘이 있는데 북문 곁에 있는 방은 남쪽으로 향하였고 남문 곁에 있는 방은 북쪽으로 향하였더라'),
    (21549, '<성전 문 현관> ○그가 나를 데리고 성전 문 현관에 이르러 그 문의 좌우 벽을 측량하니 너비는 이쪽도 다섯 척이요 저쪽도 다섯 척이며 두께는 문 이쪽도 세 척이요 문 저쪽도 세 척이며'),
    (21482, '이같이 그 무기로 불을 피울 것이므로 그들이 들에서 나무를 주워 오지 아니하며 숲에서 벌목하지 아니하겠고 전에 자기에게서 약탈하던 자의 것을 약탈하며 전에 자기에게서 늑탈하던 자의 것을 늑탈하리라 주 여호와의 말씀이니라'),
    (21483, '그 날에 내가 곡을 위하여 이스라엘 땅 곧 바다 동쪽 사람이 통행하는 골짜기를 매장지로 주리니 통행하던 길이 막힐 것이라 사람이 거기에서 곡과 그 모든 무리를 매장하고 그 이름을 하몬곡의 골짜기라 일컬으리라'),
    (21489, '○주 여호와께서 이같이 말씀하셨느니라 너 인자야 너는 각종 새와 들의 각종 짐승에게 이르기를 너희는 모여 오라 내가 너희를 위한 잔치 곧 이스라엘 산 위에 예비한 큰 잔치로 너희는 사방에서 모여 살을 먹으며 피를 마실지어다'),
    (21493, '<이스라엘의 회복> ○내가 내 영광을 여러 민족 가운데에 나타내어 모든 민족이 내가 행한 심판과 내가 그 위에 나타낸 권능을 보게 하리니'),
    (21495, '여러 민족은 이스라엘 족속이 그 죄악으로 말미암아 사로잡혀 갔던 줄을 알지라 그들이 내게 범죄하였으므로 내 얼굴을 그들에게 가리고 그들을 그 원수의 손에 넘겨 다 칼에 엎드러지게 하였으되'),
    (21497, '○그러므로 주 여호와께서 이같이 말씀하셨느니라 내가 이제 내 거룩한 이름을 위하여 열심을 내어 야곱의 사로잡힌 자를 돌아오게 하며 이스라엘 온 족속에게 사랑을 베풀지라'),
    (21500, '전에는 내가 그들이 사로잡혀 여러 나라에 이르게 하였거니와 후에는 내가 그들을 모아 고국 땅으로 돌아오게 하고 그 한 사람도 이방에 남기지 아니하리니 그들이 내가 여호와 자기들의 하나님인 줄을 알리라'),
    (21685, '○초하루에는 흠 없는 수송아지 한 마리와 어린 양 여섯 마리와 숫양 한 마리를 드리되 모두 흠 없는 것으로 할 것이며'),
    (21688, '○그러나 모든 정한 절기에 이 땅 백성이 나 여호와 앞에 나아올 때에는 북문으로 들어와서 경배하는 자는 남문으로 나가고 남문으로 들어오는 자는 북문으로 나갈지라 들어온 문으로 도로 나가지 말고 그 몸이 앞으로 향한 대로 나갈지며'),
    (21691, '만일 군주가 자원하여 번제를 준비하거나 혹은 자원하여 감사제를 준비하여 나 여호와께 드릴 때에는 그를 위하여 동쪽을 향한 문을 열고 그가 번제와 감사제를 안식일에 드림 같이 드리고 밖으로 나갈지며 나간 후에 문을 닫을지니라'),
    (21692, '<매일 드리는 제사> ○아침마다 일년 되고 흠 없는 어린 양 한 마리를 번제를 갖추어 나 여호와께 드리고'),
    (21695, '<군주와 그의 기업> ○주 여호와께서 이같이 말씀하셨느니라 군주가 만일 한 아들에게 선물을 준즉 그의 기업이 되어 그 자손에게 속하나니 이는 그 기업을 이어 받음이어니와'),
    (21698, '<성전 부엌> ○그 후에 그가 나를 데리고 문 곁 통행구를 통하여 북쪽을 향한 제사장의 거룩한 방에 들어가시니 그 방 뒤 서쪽에 한 처소가 있더라'),
    (21706, '○그 사람이 손에 줄을 잡고 동쪽으로 나아가며 천 척을 측량한 후에 내게 그 물을 건너게 하시니 물이 발목에 오르더니'),
    (21709, '○그가 내게 이르시되 인자야 네가 이것을 보았느냐 하시고 나를 인도하여 강 가로 돌아가게 하시기로'),
    (21715, '강 좌우 가에는 각종 먹을 과실나무가 자라서 그 잎이 시들지 아니하며 열매가 끊이지 아니하고 달마다 새 열매를 맺으리니 그 물이 성소를 통하여 나옴이라 그 열매는 먹을 만하고 그 잎사귀는 약 재료가 되리라'),
    (21716, '<땅의 경계선과 분배> ○주 여호와께서 이같이 말씀하셨느니라 너희는 이 경계선대로 이스라엘 열두 지파에게 이 땅을 나누어 기업이 되게 하되 요셉에게는 두 몫이니라'),
    (21724, '○그런즉 너희가 이스라엘 모든 지파대로 이 땅을 나누어 차지하라'),
    (21725, '너희는 이 땅을 나누되 제비 뽑아 너희와 너희 가운데에 머물러 사는 타국인 곧 너희 가운데에서 자녀를 낳은 자의 기업이 되게 할지니 너희는 그 타국인을 본토에서 난 이스라엘 족속 같이 여기고 그들도 이스라엘 지파 중에서 너희와 함께 기업을 얻게 하되'),
    (21602, '○성전에서 내게 하는 말을 내가 듣고 있을 때에 어떤 사람이 내 곁에 서 있더라'),
    (21603, '그가 내게 이르시되 인자야 이는 내 보좌의 처소, 내 발을 두는 처소, 내가 이스라엘 족속 가운데에 영원히 있을 곳이라 이스라엘 족속 곧 그들과 그들의 왕들이 음행하며 그 죽은 왕들의 시체로 다시는 내 거룩한 이름을 더럽히지 아니하리라'),
    (21604, '그들이 그 문지방을 내 문지방 곁에 두며 그 문설주를 내 문설주 곁에 두어서 그들과 나 사이에 겨우 한 담이 막히게 하였고 또 그 행하는 가증한 일로 내 거룩한 이름을 더럽혔으므로 내가 노하여 멸망시켰거니와'),
    (21606, '○인자야 너는 이 성전을 이스라엘 족속에게 보여서 그들이 자기의 죄악을 부끄러워하고 그 형상을 측량하게 하라'),
    (21607, '만일 그들이 자기들이 행한 모든 일을 부끄러워하거든 너는 이 성전의 제도와 구조와 그 출입하는 곳과 그 모든 형상을 보이며 또 그 모든 규례와 그 모든 법도와 그 모든 율례를 알게 하고 그 목전에 그것을 써서 그들로 그 모든 법도와 그 모든 규례를 지켜 행하게 하라'),
    (21609, '<번제단의 모양과 크기> ○제단의 크기는 이러하니라 한 자는 팔꿈치에서부터 손가락에 이르고 한 손바닥 넓이가 더한 것이라 제단 밑받침의 높이는 한 척이요 그 사방 가장자리의 너비는 한 척이며 그 가로 둘린 턱의 너비는 한 뼘이니 이는 제단 밑받침이요'),
    (21614, '<번제단의 봉헌> ○그가 내게 이르시되 인자야 주 여호와께서 이같이 말씀하셨느니라 이 제단을 만드는 날에 그 위에 번제를 드리며 피를 뿌리는 규례는 이러하니라'),
    (21655, '<거룩한 구역> 너희는 제비 뽑아 땅을 나누어 기업으로 삼을 때에 한 구역을 거룩한 땅으로 삼아 여호와께 예물로 드릴지니 그 길이는 이만 오천 척이요 너비는 만 척이라 그 구역 안 전부가 거룩하리라'),
    (21661, '드린 거룩한 구역과 성읍의 기지 된 땅의 좌우편 곧 드린 거룩한 구역의 옆과 성읍의 기지 옆의 땅을 왕에게 돌리되 서쪽으로 향하여 서쪽 국경까지와 동쪽으로 향하여 동쪽 국경까지니 그 길이가 구역 하나와 서로 같을지니라'),
    (21663, '<통치자들의 통치 법칙> ○주 여호와께서 이같이 말씀하셨느니라 이스라엘의 통치자들아 너희에게 만족하니라 너희는 포악과 겁탈을 제거하여 버리고 정의와 공의를 행하여 내 백성에게 속여 빼앗는 것을 그칠지니라 주 여호와의 말씀이니라'),
    (21667, '○너희가 마땅히 드릴 예물은 이러하니 밀 한 호멜에서는 육분의 일 에바를 드리고 보리 한 호멜에서도 육분의 일 에바를 드리며'),
    (21671, '군주의 본분은 번제와 소제와 전제를 명절과 초하루와 안식일과 이스라엘 족속의 모든 정한 명절에 갖추는 것이니 이스라엘 족속을 속죄하기 위하여 이 속죄제와 소제와 번제와 감사 제물을 갖출지니라'),
    (21672, '<유월절과 일곱째 달 열다섯째 날> ○여호와께서 이같이 말씀하셨느니라 첫째 달 초하룻날에 흠 없는 수송아지 한 마리를 가져다가 성소를 정결하게 하되'),
    (21675, '○첫째 달 열나흗날에는 유월절을 칠 일 동안 명절로 지키며 누룩 없는 떡을 먹을 것이라'),
    (21677, '또 명절 칠 일 동안에는 그가 나 여호와를 위하여 번제를 준비하되 곧 이레 동안에 매일 흠 없는 수송아지 일곱 마리와 숫양 일곱 마리이며 또 매일 숫염소 한 마리를 갖추어 속죄제를 드릴 것이며'),
    (21627, '<여호와의 영광이 성전에 가득하다> ○그가 또 나를 데리고 북문을 통하여 성전 앞에 이르시기로 내가 보니 여호와의 영광이 여호와의 성전에 가득한지라 내가 얼굴을 땅에 대고 엎드리니'),
    (21630, '너희가 마음과 몸에 할례 받지 아니한 이방인을 데려오고 내 떡과 기름과 피를 드릴 때에 그들로 내 성소 안에 있게 하여 내 성전을 더럽히므로 너희의 모든 가증한 일 외에 그들이 내 언약을 위반하게 하는 것이 되었으며'),
    (21632, '<레위 사람들의 제사장 직분을 박탈하다> ○주 여호와께서 이같이 말씀하셨느니라 이스라엘 족속 중에 있는 이방인 중에 마음과 몸에 할례를 받지 아니한 이방인은 내 성소에 들어오지 못하리라'),
    (21638, '<제사장들> ○이스라엘 족속이 그릇 행하여 나를 떠날 때에 사독의 자손 레위 사람 제사장들은 내 성소의 직분을 지켰은즉 그들은 내게 가까이 나아와 수종을 들되 내 앞에 서서 기름과 피를 내게 드릴지니라 주 여호와의 말씀이니라'),
    (21651, '○그들에게는 기업이 있으리니 내가 곧 그 기업이라 너희는 이스라엘 가운데에서 그들에게 산업을 주지 말라 내가 그 산업이 됨이라'),
    (21769, '○다니엘은 뜻을 정하여 왕의 음식과 그가 마시는 포도주로 자기를 더럽히지 아니하리라 하고 자기를 더럽히지 아니하도록 환관장에게 구하니'),
    (21771, '환관장이 다니엘에게 이르되 내가 내 주 왕을 두려워하노라 그가 너희 먹을 것과 너희 마실 것을 지정하셨거늘 너희의 얼굴이 초췌하여 같은 또래의 소년들만 못한 것을 그가 보게 할 것이 무엇이냐 그렇게 되면 너희 때문에 내 머리가 왕 앞에서 위태롭게 되리라 하니라'),
    (21778, '○하나님이 이 네 소년에게 학문을 주시고 모든 서적을 깨닫게 하시고 지혜를 주셨으니 다니엘은 또 모든 환상과 꿈을 깨달아 알더라'),
    (21839, '<다니엘의 세 친구> ○그 때에 어떤 갈대아 사람들이 나아와 유다 사람들을 참소하니라'),
    (21843, '이제 몇 유다 사람 사드락과 메삭과 아벳느고는 왕이 세워 바벨론 지방을 다스리게 하신 자이거늘 왕이여 이 사람들이 왕을 높이지 아니하며 왕의 신들을 섬기지 아니하며 왕이 세우신 금 신상에게 절하지 아니하나이다'),
    (21844, '○느부갓네살 왕이 노하고 분하여 사드락과 메삭과 아벳느고를 끌어오라 말하매 드디어 그 사람들을 왕의 앞으로 끌어온지라'),
    (21846, '이제라도 너희가 준비하였다가 나팔과 피리와 수금과 삼현금과 양금과 생황과 및 모든 악기 소리를 들을 때 내가 만든 신상 앞에 엎드려 절하면 좋거니와 너희가 만일 절하지 아니하면 즉시 너희를 맹렬히 타는 풀무불 가운데에 던져 넣을 것이니 능히 너희를 내 손에서 건져낼 신이 누구이겠느냐 하니'),
    (21850, '<세 친구를 풀무불에 던지다> ○느부갓네살이 분이 가득하여 사드락과 메삭과 아벳느고를 향하여 얼굴빛을 바꾸고 명령하여 이르되 그 풀무불을 뜨겁게 하기를 평소보다 칠 배나 뜨겁게 하라 하고'),
    (21855, '<왕이 세 친구를 높이다> ○그 때에 느부갓네살 왕이 놀라 급히 일어나서 모사들에게 물어 이르되 우리가 결박하여 불 가운데에 던진 자는 세 사람이 아니었느냐 하니 그들이 왕에게 대답하여 이르되 왕이여 옳소이다 하더라'),
    (21857, '느부갓네살이 맹렬히 타는 풀무불 아귀 가까이 가서 불러 이르되 지극히 높으신 하나님의 종 사드락, 메삭, 아벳느고야 나와서 이리로 오라 하매 사드락과 메삭과 아벳느고가 불 가운데에서 나온지라'),
    (21859, '○느부갓네살이 말하여 이르되 사드락과 메삭과 아벳느고의 하나님을 찬송할지로다 그가 그의 천사를 보내사 자기를 의뢰하고 그들의 몸을 바쳐 왕의 명령을 거역하고 그 하나님 밖에는 다른 신을 섬기지 아니하며 그에게 절하지 아니한 종들을 구원하셨도다'),
    (21860, '그러므로 내가 이제 조서를 내리노니 각 백성과 각 나라와 각 언어를 말하는 자가 모두 사드락과 메삭과 아벳느고의 하나님께 경솔히 말하거든 그 몸을 쪼개고 그 집을 거름터로 삼을지니 이는 이같이 사람을 구원할 다른 신이 없음이니라 하더라'),
    (21791, '너희가 만일 이 꿈을 내게 알게 하지 아니하면 너희를 처치할 법이 오직 하나이니 이는 너희가 거짓말과 망령된 말을 내 앞에서 꾸며 말하여 때가 변하기를 기다리려 함이라 이제 그 꿈을 내게 알게 하라 그리하면 너희가 그 해석도 보일 줄을 내가 알리라 하더라'),
    (21792, '갈대아인들이 왕 앞에 대답하여 이르되 세상에는 왕의 그 일을 보일 자가 한 사람도 없으므로 어떤 크고 권력 있는 왕이라도 이런 것으로 박수에게나 술객에게나 갈대아인들에게 물은 자가 없었나이다'),
    (21796, '<다니엘에게 은밀한 것을 보이시다> ○그 때에 왕의 근위대장 아리옥이 바벨론 지혜자들을 죽이러 나가매 다니엘이 명철하고 슬기로운 말로'),
    (21799, '○이에 다니엘이 자기 집으로 돌아가서 그 친구 하나냐와 미사엘과 아사랴에게 그 일을 알리고'),
    (21805, '나의 조상들의 하나님이여 주께서 이제 내게 지혜와 능력을 주시고 우리가 주께 구한 것을 내게 알게 하셨사오니 내가 주께 감사하고 주를 찬양하나이다 곧 주께서 왕의 그 일을 내게 보이셨나이다 하니라'),
    (21806, '이에 다니엘은 왕이 바벨론 지혜자들을 죽이라 명령한 아리옥에게로 가서 그에게 이같이 이르되 바벨론 지혜자들을 죽이지 말고 나를 왕의 앞으로 인도하라 그리하면 내가 그 해석을 왕께 알려 드리리라 하니'),
    (21807, '<다니엘이 꿈을 해석하다> ○이에 아리옥이 다니엘을 데리고 급히 왕 앞에 들어가서 아뢰되 내가 사로잡혀 온 유다 자손 중에서 한 사람을 찾아내었나이다 그가 그 해석을 왕께 알려 드리리이다 하니라'),
    (21813, '○왕이여 왕이 한 큰 신상을 보셨나이다 그 신상이 왕의 앞에 섰는데 크고 광채가 매우 찬란하며 그 모양이 심히 두려우니'),
    (21818, '○그 꿈이 이러한즉 내가 이제 그 해석을 왕 앞에 아뢰리이다'),
    (21826, '이 여러 왕들의 시대에 하늘의 하나님이 한 나라를 세우시리니 이것은 영원히 망하지도 아니할 것이요 그 국권이 다른 백성에게로 돌아가지도 아니할 것이요 도리어 이 모든 나라를 쳐서 멸망시키고 영원히 설 것이라'),
    (21828, '<왕이 다니엘을 높이다> ○이에 느부갓네살 왕이 엎드려 다니엘에게 절하고 명하여 예물과 향품을 그에게 주게 하니라'),
    (21829, '왕이 대답하여 다니엘에게 이르되 너희 하나님은 참으로 모든 신들의 신이시요 모든 왕의 주재시로다 네가 능히 이 은밀한 것을 나타내었으니 네 하나님은 또 은밀한 것을 나타내시는 이시로다'),
    (21900, '벨사살이 술을 마실 때에 명하여 그의 부친 느부갓네살이 예루살렘 성전에서 탈취하여 온 금, 은 그릇을 가져오라고 명하였으니 이는 왕과 귀족들과 왕후들과 후궁들이 다 그것으로 마시려 함이었더라'),
    (21903, '○그 때에 사람의 손가락들이 나타나서 왕궁 촛대 맞은편 석회벽에 글자를 쓰는데 왕이 그 글자 쓰는 손가락을 본지라'),
    (21905, '왕이 크게 소리 질러 술객과 갈대아 술사와 점쟁이를 불러오게 하고 바벨론의 지혜자들에게 말하되 누구를 막론하고 이 글자를 읽고 그 해석을 내게 보이면 자주색 옷을 입히고 금사슬을 그의 목에 걸어 주리니 그를 나라의 셋째 통치자로 삼으리라 하니라'),
    (21908, '○왕비가 왕과 그 귀족들의 말로 말미암아 잔치하는 궁에 들어왔더니 이에 말하여 이르되 왕이여 만수무강 하옵소서 왕의 생각을 번민하게 하지 말며 얼굴빛을 변할 것도 아니니이다'),
    (21909, '왕의 나라에 거룩한 신들의 영이 있는 사람이 있으니 곧 왕의 부친 때에 있던 자로서 명철과 총명과 지혜가 신들의 지혜와 같은 자니이다 왕의 부친 느부갓네살 왕이 그를 세워 박수와 술객과 갈대아 술사와 점쟁이의 어른을 삼으셨으니'),
    (21910, '왕이 벨드사살이라 이름하는 이 다니엘은 마음이 민첩하고 지식과 총명이 있어 능히 꿈을 해석하며 은밀한 말을 밝히며 의문을 풀 수 있었나이다 이제 다니엘을 부르소서 그리하시면 그가 그 해석을 알려 드리리이다 하니라'),
    (21911, '<다니엘이 글을 해석하다> ○이에 다니엘이 부름을 받아 왕의 앞에 나오매 왕이 다니엘에게 말하되 네가 나의 부왕이 유다에서 사로잡아 온 유다 자손 중의 그 다니엘이냐'),
    (21914, '내가 네게 대하여 들은즉 너는 해석을 잘하고 의문을 푼다 하도다 그런즉 이제 네가 이 글을 읽고 그 해석을 내게 알려 주면 네게 자주색 옷을 입히고 금 사슬을 네 목에 걸어 주어 너를 나라의 셋째 통치자로 삼으리라 하니'),
    (21915, '○다니엘이 왕에게 대답하여 이르되 왕의 예물은 왕이 친히 가지시며 왕의 상급은 다른 사람에게 주옵소서 그럴지라도 내가 왕을 위하여 이 글을 읽으며 그 해석을 아뢰리이다'),
    (21919, '사람 중에서 쫓겨나서 그의 마음이 들짐승의 마음과 같았고 또 들나귀와 함께 살며 또 소처럼 풀을 먹으며 그의 몸이 하늘 이슬에 젖었으며 지극히 높으신 하나님이 사람 나라를 다스리시며 자기의 뜻대로 누구든지 그 자리에 세우시는 줄을 알기에 이르렀나이다'),
    (21921, '도리어 자신을 하늘의 주재보다 높이며 그의 성전 그릇을 왕 앞으로 가져다가 왕과 귀족들과 왕후들과 후궁들이 다 그것으로 술을 마시고 왕이 또 보지도 듣지도 알지도 못하는 금, 은, 구리, 쇠와 나무, 돌로 만든 신상들을 찬양하고 도리어 왕의 호흡을 주장하시고 왕의 모든 길을 작정하시는 하나님께는 영광을 돌리지 아니한지라'),
    (21927, '○이에 벨사살이 명하여 그들이 다니엘에게 자주색 옷을 입히게 하며 금 사슬을 그의 목에 걸어 주고 그를 위하여 조서를 내려 나라의 셋째 통치자로 삼으니라'),
    (21928, '○그 날 밤에 갈대아 왕 벨사살이 죽임을 당하였고'),
    (21865, '○나 느부갓네살이 내 집에 편히 있으며 내 궁에서 평강할 때에'),
    (21878, '이는 순찰자들의 명령대로요 거룩한 자들의 말대로이니 지극히 높으신 이가 사람의 나라를 다스리시며 자기의 뜻대로 그것을 누구에게든지 주시며 또 지극히 천한 자를 그 위에 세우시는 줄을 사람들이 알게 하려 함이라 하였느니라'),
    (21879, '나 느부갓네살 왕이 이 꿈을 꾸었나니 너 벨드사살아 그 해석을 밝히 말하라 내 나라 모든 지혜자가 능히 내게 그 해석을 알게 하지 못하였으나 오직 너는 능히 하리니 이는 거룩한 신들의 영이 네 안에 있음이라'),
    (21880, '<다니엘의 꿈 해석> ○벨드사살이라 이름한 다니엘이 한동안 놀라며 마음으로 번민하는지라 왕이 그에게 말하여 이르기를 벨드사살아 너는 이 꿈과 그 해석으로 말미암아 번민할 것이 아니니라 벨드사살이 대답하여 이르되 내 주여 그 꿈은 왕을 미워하는 자에게 응하며 그 해석은 왕의 대적에게 응하기를 원하나이다'),
    (21884, '왕이 보신즉 한 순찰자, 한 거룩한 자가 하늘에서 내려와서 이르기를 그 나무를 베어 없애라 그러나 그 뿌리의 그루터기는 땅에 남겨 두고 쇠와 놋줄로 동이고 그것을 들 풀 가운데에 두라 그것이 하늘 이슬에 젖고 또 들짐승들과 더불어 제 몫을 얻으며 일곱 때를 지내리라 하였나이다'),
    (21886, '왕이 사람에게서 쫓겨나서 들짐승과 함께 살며 소처럼 풀을 먹으며 하늘 이슬에 젖을 것이요 이와 같이 일곱 때를 지낼 것이라 그 때에 지극히 높으신 이가 사람의 나라를 다스리시며 자기의 뜻대로 그것을 누구에게든지 주시는 줄을 아시리이다'),
    (21889, '○이 모든 일이 다 나 느부갓네살 왕에게 임하였느니라'),
    (21893, '네가 사람에게서 쫓겨나서 들짐승과 함께 살면서 소처럼 풀을 먹을 것이요 이와 같이 일곱 때를 지내서 지극히 높으신 이가 사람의 나라를 다스리시며 자기의 뜻대로 그것을 누구에게든지 주시는 줄을 알기까지 이르리라 하더라'),
    (21895, '<느부갓네살 왕의 하나님 찬양> ○그 기한이 차매 나 느부갓네살이 하늘을 우러러 보았더니 내 총명이 다시 내게로 돌아온지라 이에 내가 지극히 높으신 이에게 감사하며 영생하시는 이를 찬양하고 경배하였나니 그 권세는 영원한 권세요 그 나라는 대대에 이르리로다'),
    (21896, '땅의 모든 사람들을 없는 것 같이 여기시며 하늘의 군대에게든지 땅의 사람에게든지 그는 자기 뜻대로 행하시나니 그의 손을 금하든지 혹시 이르기를 네가 무엇을 하느냐고 할 자가 아무도 없도다'),
    (21897, '그 때에 내 총명이 내게로 돌아왔고 또 내 나라의 영광에 대하여도 내 위엄과 광명이 내게로 돌아왔고 또 나의 모사들과 관원들이 내게 찾아오니 내가 내 나라에서 다시 세움을 받고 또 지극한 위세가 내게 더하였느니라'),
    (21727, '<각 지파의 몫과 거룩한 땅> 모든 지파의 이름은 이와 같으니라 북쪽 끝에서부터 헤들론 길을 거쳐 하맛 어귀를 지나서 다메섹 경계선에 있는 하살에논까지 곧 북쪽으로 하맛 경계선에 미치는 땅 동쪽에서 서쪽까지는 단의 몫이요'),
    (21736, '이 드리는 거룩한 땅은 제사장에게 돌릴지니 북쪽으로 길이가 이만 오천 척이요 서쪽으로 너비는 만 척이요 동쪽으로 너비가 만 척이요 남쪽으로 길이가 이만 오천 척이라 그 중앙에 여호와의 성소가 있게 하고'),
    (21739, '○제사장의 경계선을 따라 레위 사람의 몫을 주되 길이는 이만 오천 척이요 너비는 만 척으로 할지니 이 구역의 길이가 이만 오천 척이요 너비가 각기 만 척이라'),
    (21741, '○이 이만 오천 척 다음으로 너비 오천 척은 속된 땅으로 구분하여 성읍을 세우며 거주하는 곳과 전원을 삼되 성읍이 그 중앙에 있게 할지니'),
    (21744, '예물을 삼아 거룩히 구별할 땅과 연접하여 남아 있는 땅의 길이는 동쪽으로 만 척이요 서쪽으로 만 척이라 곧 예물을 삼아 거룩하게 구별할 땅과 연접하였으며 그 땅의 소산을 성읍에서 일하는 자의 양식을 삼을지라'),
    (21747, '○거룩하게 구별할 땅과 성읍의 기지 좌우편에 남은 땅은 군주에게 돌릴지니 곧 거룩하게 구별할 땅의 동쪽을 향한 그 경계선 앞 이만 오천 척과 서쪽을 향한 그 경계선 앞 이만 오천 척이라 다른 몫들과 연접한 땅이니 이것을 군주에게 돌릴 것이며 거룩하게 구별할 땅과 성전의 성소가 그 중앙에 있으리라'),
    (21749, '<나머지 지파들의 몫> ○그 나머지 모든 지파는 동쪽에서 서쪽까지는 베냐민의 몫이요'),
    (21756, '<예루살렘 성읍의 문들> ○그 성읍의 출입구는 이러하니라 북쪽의 너비가 사천오백 척이라'),
    (21990, '○내가 생각할 때에 한 숫염소가 서쪽에서부터 와서 온 지면에 두루 다니되 땅에 닿지 아니하며 그 염소의 두 눈 사이에는 현저한 뿔이 있더라'),
    (21992, '내가 본즉 그것이 숫양에게로 가까이 나아가서는 더욱 성내어 그 숫양을 쳐서 그 두 뿔을 꺾으나 숫양에게는 그것을 대적할 힘이 없으므로 그것이 숫양을 땅에 엎드러뜨리고 짓밟았으나 숫양을 그 손에서 벗어나게 할 자가 없었더라'),
    (21994, '○그 중 한 뿔에서 또 작은 뿔 하나가 나서 남쪽과 동쪽과 또 영화로운 땅을 향하여 심히 커지더니'),
    (21998, '내가 들은즉 한 거룩한 이가 말하더니 다른 거룩한 이가 그 말하는 이에게 묻되 환상에 나타난 바 매일 드리는 제사와 망하게 하는 죄악에 대한 일과 성소와 백성이 내준 바 되며 짓밟힐 일이 어느 때까지 이를꼬 하매'),
    (22000, '<가브리엘 천사가 환상을 깨닫게 하다> ○나 다니엘이 이 환상을 보고 그 뜻을 알고자 할 때에 사람 모양 같은 것이 내 앞에 섰고'),
    (22010, '그가 꾀를 베풀어 제 손으로 속임수를 행하고 마음에 스스로 큰 체하며 또 평화로운 때에 많은 무리를 멸하며 또 스스로 서서 만왕의 왕을 대적할 것이나 그가 사람의 손으로 말미암지 아니하고 깨지리라'),
    (21961, '첫째는 사자와 같은데 독수리의 날개가 있더니 내가 보는 중에 그 날개가 뽑혔고 또 땅에서 들려서 사람처럼 두 발로 서게 함을 받았으며 또 사람의 마음을 받았더라'),
    (21964, '내가 밤 환상 가운데에 그 다음에 본 넷째 짐승은 무섭고 놀라우며 또 매우 강하며 또 쇠로 된 큰 이가 있어서 먹고 부서뜨리고 그 나머지를 발로 밟았으며 이 짐승은 전의 모든 짐승과 다르고 또 열 뿔이 있더라'),
    (21965, '내가 그 뿔을 유심히 보는 중에 다른 작은 뿔이 그 사이에서 나더니 첫 번째 뿔 중의 셋이 그 앞에서 뿌리까지 뽑혔으며 이 작은 뿔에는 사람의 눈 같은 눈들이 있고 또 입이 있어 큰 말을 하였더라'),
    (21966, '<옛적부터 항상 계신 자> ○내가 보니 왕좌가 놓이고 옛적부터 항상 계신 이가 좌정하셨는데 그의 옷은 희기가 눈 같고 그의 머리털은 깨끗한 양의 털 같고 그의 보좌는 불꽃이요 그의 바퀴는 타오르는 불이며'),
    (21970, '○내가 또 밤 환상 중에 보니 인자 같은 이가 하늘 구름을 타고 와서 옛적부터 항상 계신 이에게 나아가 그 앞으로 인도되매'),
    (21971, '그에게 권세와 영광과 나라를 주고 모든 백성과 나라들과 다른 언어를 말하는 모든 자들이 그를 섬기게 하였으니 그의 권세는 소멸되지 아니하는 영원한 권세요 그의 나라는 멸망하지 아니할 것이니라'),
    (21972, '<환상 해석> ○나 다니엘이 중심에 근심하며 내 머리 속의 환상이 나를 번민하게 한지라'),
    (21980, '○모신 자가 이처럼 이르되 넷째 짐승은 곧 땅의 넷째 나라인데 이는 다른 나라들과는 달라서 온 천하를 삼키고 밟아 부서뜨릴 것이며'),
    (21982, '그가 장차 지극히 높으신 이를 말로 대적하며 또 지극히 높으신 이의 성도를 괴롭게 할 것이며 그가 또 때와 법을 고치고자 할 것이며 성도들은 그의 손에 붙인 바 되어 한 때와 두 때와 반 때를 지내리라'),
    (22040, '<힛데겔 강 가에서 본 환상> 바사 왕 고레스 제삼년에 한 일이 벨드사살이라 이름한 다니엘에게 나타났는데 그 일이 참되니 곧 큰 전쟁에 관한 것이라 다니엘이 그 일을 분명히 알았고 그 환상을 깨달으니라'),
    (22049, '○한 손이 있어 나를 어루만지기로 내가 떨었더니 그가 내 무릎과 손바닥이 땅에 닿게 일으키고'),
    (22057, '○또 사람의 모양 같은 것 하나가 나를 만지며 나를 강건하게 하여'),
    (22062, '<남방 왕과 북방 왕이 싸우리라> ○이제 내가 참된 것을 네게 보이리라 보라 바사에서 또 세 왕들이 일어날 것이요 그 후의 넷째는 그들보다 심히 부요할 것이며 그가 그 부요함으로 강하여진 후에는 모든 사람을 충동하여 헬라 왕국을 칠 것이며'),
    (22064, '그러나 그가 강성할 때에 그의 나라가 갈라져 천하 사방에 나누일 것이나 그의 자손에게로 돌아가지도 아니할 것이요 또 자기가 주장하던 권세대로도 되지 아니하리니 이는 그 나라가 뽑혀서 그 외의 다른 사람들에게로 돌아갈 것임이라'),
    (22065, '○남방의 왕은 강할 것이나 그 군주들 중 하나는 그보다 강하여 권세를 떨치리니 그의 권세가 심히 클 것이요'),
    (22066, '몇 해 후에 그들이 서로 단합하리니 곧 남방 왕의 딸이 북방 왕에게 가서 화친하리라 그러나 그 공주의 힘이 쇠하고 그 왕은 서지도 못하며 권세가 없어질 뿐 아니라 그 공주와 그를 데리고 온 자와 그를 낳은 자와 그 때에 도와 주던 자가 다 버림을 당하리라'),
    (22067, '○그러나 그 공주의 본 족속에게서 난 자 중의 한 사람이 왕위를 이어 권세를 받아 북방 왕의 군대를 치러 와서 그의 성에 들어가서 그들을 쳐서 이기고'),
    (22070, '○그러나 그의 아들들이 전쟁을 준비하고 심히 많은 군대를 모아서 물이 넘침 같이 나아올 것이며 그가 또 와서 남방 왕의 견고한 성까지 칠 것이요'),
    (22080, '<비천한 북방 왕> ○그 왕위를 이을 자가 압제자를 그 나라의 아름다운 곳으로 두루 다니게 할 것이나 그는 분노함이나 싸움이 없이 몇 날이 못 되어 망할 것이요'),
    (22084, '그가 평안한 때에 그 지방의 가장 기름진 곳에 들어와서 그의 조상들과 조상들의 조상이 행하지 못하던 것을 행할 것이요 그는 노략하고 탈취한 재물을 무리에게 흩어 주며 계략을 세워 얼마 동안 산성들을 칠 것인데 때가 이르기까지 그리하리라'),
    (22085, '그가 그의 힘을 떨치며 용기를 다하여 큰 군대를 거느리고 남방 왕을 칠 것이요 남방 왕도 심히 크고 강한 군대를 거느리고 맞아 싸울 것이나 능히 당하지 못하리니 이는 그들이 계략을 세워 그를 침이니라'),
    (22088, '○북방 왕은 많은 재물을 가지고 본국으로 돌아가리니 그는 마음으로 거룩한 언약을 거스르며 자기 마음대로 행하고 본토로 돌아갈 것이며'),
    (22090, '이는 깃딤의 배들이 이르러 그를 칠 것임이라 그가 낙심하고 돌아가면서 맺은 거룩한 언약에 분노하였고 자기 땅에 돌아가서는 맺은 거룩한 언약을 배반하는 자들을 살필 것이며'),
    (22096, '○그 왕은 자기 마음대로 행하며 스스로 높여 모든 신보다 크다 하며 비상한 말로 신들의 신을 대적하며 형통하기를 분노하심이 그칠 때까지 하리니 이는 그 작정된 일을 반드시 이룰 것임이라'),
    (22100, '○마지막 때에 남방 왕이 그와 힘을 겨룰 것이나 북방 왕이 병거와 마병과 많은 배로 회오리바람처럼 그에게로 마주 와서 그 여러 나라에 침공하여 물이 넘침 같이 지나갈 것이요'),
    (21936, '나라의 모든 총리와 지사와 총독과 법관과 관원이 의논하고 왕에게 한 법률을 세우며 한 금령을 정하실 것을 구하나이다 왕이여 그것은 곧 이제부터 삼십일 동안에 누구든지 왕 외의 어떤 신에게나 사람에게 무엇을 구하면 사자 굴에 던져 넣기로 한 것이니이다'),
    (21939, '○다니엘이 이 조서에 왕의 도장이 찍힌 것을 알고도 자기 집에 돌아가서는 윗방에 올라가 예루살렘으로 향한 창문을 열고 전에 하던 대로 하루 세 번씩 무릎을 꿇고 기도하며 그의 하나님께 감사하였더라'),
    (21941, '이에 그들이 나아가서 왕의 금령에 관하여 왕께 아뢰되 왕이여 왕이 이미 금령에 왕의 도장을 찍어서 이제부터 삼십 일 동안에는 누구든지 왕 외의 어떤 신에게나 사람에게 구하면 사자 굴에 던져 넣기로 하지 아니하였나이까 하니 왕이 대답하여 이르되 이 일이 확실하니 메대와 바사의 고치지 못하는 규례니라 하는지라'),
    (21945, '○이에 왕이 명령하매 다니엘을 끌어다가 사자 굴에 던져 넣는지라 왕이 다니엘에게 이르되 네가 항상 섬기는 너의 하나님이 너를 구원하시리라 하니라'),
    (21948, '○이튿날에 왕이 새벽에 일어나 급히 사자 굴로 가서'),
    (21951, '나의 하나님이 이미 그의 천사를 보내어 사자들의 입을 봉하셨으므로 사자들이 나를 상해하지 못하였사오니 이는 나의 무죄함이 그 앞에 명백함이오며 또 왕이여 나는 왕에게도 해를 끼치지 아니하였나이다 하니라'),
    (21953, '○왕이 말하여 다니엘을 참소한 사람들을 끌어오게 하고 그들을 그들의 처자들과 함께 사자 굴에 던져 넣게 하였더니 그들이 굴 바닥에 닿기도 전에 사자들이 곧 그들을 움켜서 그 뼈까지도 부서뜨렸더라'),
    (21954, '○이에 다리오 왕이 온 땅에 있는 모든 백성과 나라들과 언어가 다른 모든 사람들에게 조서를 내려 이르되 원하건대 너희에게 큰 평강이 있을지어다'),
    (21955, '내가 이제 조서를 내리노라 내 나라 관할 아래에 있는 사람들은 다 다니엘의 하나님 앞에서 떨며 두려워할지니 그는 살아 계시는 하나님이시요 영원히 변하지 않으실 이시며 그의 나라는 멸망하지 아니할 것이요 그의 권세는 무궁할 것이며'),
    (21957, '○이 다니엘이 다리오 왕의 시대와 바사 사람 고레스 왕의 시대에 형통하였더라'),
    (22106, '<끝날> 그 때에 네 민족을 호위하는 큰 군주 미가엘이 일어날 것이요 또 환난이 있으리니 이는 개국 이래로 그 때까지 없던 환난일 것이며 그 때에 네 백성 중 책에 기록된 모든 자가 구원을 받을 것이라'),
    (22110, '○나 다니엘이 본즉 다른 두 사람이 있어 하나는 강 이쪽 언덕에 섰고 하나는 강 저쪽 언덕에 섰더니'),
    (22112, '내가 들은즉 그 세마포 옷을 입고 강물 위쪽에 있는 자가 자기의 좌우 손을 들어 하늘을 향하여 영원히 살아 계시는 이를 가리켜 맹세하여 이르되 반드시 한 때 두 때 반 때를 지나서 성도의 권세가 다 깨지기까지이니 그렇게 되면 이 모든 일이 다 끝나리라 하더라'),
    (22015, '○내가 금식하며 베옷을 입고 재를 덮어쓰고 주 하나님께 기도하며 간구하기를 결심하고'),
    (22019, '주여 공의는 주께로 돌아가고 수치는 우리 얼굴로 돌아옴이 오늘과 같아서 유다 사람들과 예루살렘 거민들과 이스라엘이 가까운 곳에 있는 자들이나 먼 곳에 있는 자들이 다 주께서 쫓아내신 각국에서 수치를 당하였사오니 이는 그들이 주께 죄를 범하였음이니이다'),
    (22023, '온 이스라엘이 주의 율법을 범하고 치우쳐 가서 주의 목소리를 듣지 아니하였으므로 이 저주가 우리에게 내렸으되 곧 하나님의 종 모세의 율법에 기록된 맹세대로 되었사오니 이는 우리가 주께 범죄하였음이니이다'),
    (22028, '주여 구하옵나니 주는 주의 공의를 따라 주의 분노를 주의 성 예루살렘, 주의 거룩한 산에서 떠나게 하옵소서 이는 우리의 죄와 우리 조상들의 죄악으로 말미암아 예루살렘과 주의 백성이 사면에 있는 자들에게 수치를 당함이니이다'),
    (22030, '나의 하나님이여 귀를 기울여 들으시며 눈을 떠서 우리의 황폐한 상황과 주의 이름으로 일컫는 성을 보옵소서 우리가 주 앞에 간구하옵는 것은 우리의 공의를 의지하여 하는 것이 아니요 주의 큰 긍휼을 의지하여 함이니이다'),
    (22031, '주여 들으소서 주여 용서하소서 주여 귀를 기울이시고 행하소서 지체하지 마옵소서 나의 하나님이여 주 자신을 위하여 하시옵소서 이는 주의 성과 주의 백성이 주의 이름으로 일컫는 바 됨이니이다'),
    (22032, '<가브리엘이 환상을 설명하다> ○내가 이같이 말하여 기도하며 내 죄와 내 백성 이스라엘의 죄를 자복하고 내 하나님의 거룩한 산을 위하여 내 하나님 여호와 앞에 간구할 때'),
    (22034, '내게 가르치며 내게 말하여 이르되 다니엘아 내가 이제 네게 지혜와 총명을 주려고 왔느니라'),
    (22036, '네 백성과 네 거룩한 성을 위하여 일흔 이레를 기한으로 정하였나니 허물이 그치며 죄가 끝나며 죄악이 용서되며 영원한 의가 드러나며 환상과 예언이 응하며 또 지극히 거룩한 이가 기름 부음을 받으리라'),
    (22037, '그러므로 너는 깨달아 알지니라 예루살렘을 중건하라는 영이 날 때부터 기름 부음을 받은 자 곧 왕이 일어나기까지 일곱 이레와 예순두 이레가 지날 것이요 그 곤란한 동안에 성이 중건되어 광장과 거리가 세워질 것이며'),
    (22038, '예순두 이레 후에 기름 부음을 받은 자가 끊어져 없어질 것이며 장차 한 왕의 백성이 와서 그 성읍과 성소를 무너뜨리려니와 그의 마지막은 홍수에 휩쓸림 같을 것이며 또 끝까지 전쟁이 있으리니 황폐할 것이 작정되었느니라'),
    (22039, '그가 장차 많은 사람들과 더불어 한 이레 동안의 언약을 굳게 맺고 그가 그 이레의 절반에 제사와 예물을 금지할 것이며 또 포악하여 가증한 것이 날개를 의지하여 설 것이며 또 이미 정한 종말까지 진노가 황폐하게 하는 자에게 쏟아지리라 하였느니라 하니라'),
    (22131, '<음란을 제거할지라> ○너희 어머니와 논쟁하고 논쟁하라 그는 내 아내가 아니요 나는 그의 남편이 아니라 그가 그의 얼굴에서 음란을 제하게 하고 그 유방 사이에서 음행을 제하게 하라'),
    (22134, '그들의 어머니는 음행하였고 그들을 임신했던 자는 부끄러운 일을 행하였나니 이는 그가 이르기를 나는 나를 사랑하는 자들을 따르리니 그들이 내 떡과 내 물과 내 양털과 내 삼과 내 기름과 내 술들을 내게 준다 하였음이라'),
    (22136, '그가 그 사랑하는 자를 따라갈지라도 미치지 못하며 그들을 찾을지라도 만나지 못할 것이라 그제야 그가 이르기를 내가 본 남편에게로 돌아가리니 그 때의 내 형편이 지금보다 나았음이라 하리라'),
    (22137, '○곡식과 새 포도주와 기름은 내가 그에게 준 것이요 그들이 바알을 위하여 쓴 은과 금도 내가 그에게 더하여 준 것이거늘 그가 알지 못하도다'),
    (22143, '<백성을 향한 여호와의 사랑> ○그러므로 보라 내가 그를 타일러 거친 들로 데리고 가서 말로 위로하고'),
    (22150, '○여호와께서 이르시되 그 날에 내가 응답하리라 나는 하늘에 응답하고 하늘은 땅에 응답하고'),
    (22152, '내가 나를 위하여 그를 이 땅에 심고 긍휼히 여김을 받지 못하였던 자를 긍휼히 여기며 내 백성 아니었던 자에게 향하여 이르기를 너는 내 백성이라 하리니 그들은 이르기를 주는 내 하나님이시라 하리라 하시니라'),
    (22120, '<호세아의 아내와 자식들> ○여호와께서 처음 호세아에게 말씀하실 때 여호와께서 호세아에게 이르시되 너는 가서 음란한 여자를 맞이하여 음란한 자식들을 낳으라 이 나라가 여호와를 떠나 크게 음란함이니라 하시니'),
    (22128, '<이스라엘이 회복되리라> ○그러나 이스라엘 자손의 수가 바닷가의 모래 같이 되어서 헤아릴 수도 없고 셀 수도 없을 것이며 전에 그들에게 이르기를 너희는 내 백성이 아니라 한 그 곳에서 그들에게 이르기를 너희는 살아 계신 하나님의 아들들이라 할 것이라'),
    (22195, '○에브라임아 내가 네게 어떻게 하랴 유다야 내가 네게 어떻게 하랴 너희의 인애가 아침 구름이나 쉬 없어지는 이슬 같도다'),
    (22153, '<호세아와 음녀가 된 여인> 여호와께서 내게 이르시되 이스라엘 자손이 다른 신을 섬기고 건포도 과자를 즐길지라도 여호와가 그들을 사랑하나니 너는 또 가서 타인의 사랑을 받아 음녀가 된 그 여자를 사랑하라 하시기로'),
    (22177, '<우상 숭배를 경고하다> 제사장들아 이를 들으라 이스라엘 족속들아 깨달으라 왕족들아 귀를 기울이라 너희에게 심판이 있나니 너희가 미스바에 대하여 올무가 되며 다볼 위에 친 그물이 됨이라'),
    (22184, '<유다와 이스라엘 사이의 전쟁> ○너희가 기브아에서 뿔나팔을 불며 라마에서 나팔을 불며 벧아웬에서 외치기를 베냐민아 네 뒤를 쫓는다 할지어다'),
    (22189, '에브라임이 자기의 병을 깨달으며 유다가 자기의 상처를 깨달았고 에브라임은 앗수르로 가서 야렙 왕에게 사람을 보내었으나 그가 능히 너희를 고치지 못하겠고 너희 상처를 낫게 하지 못하리라'),
    (22163, '<여호와께서 백성과 제사장을 심판하시다> ○내 백성이 지식이 없으므로 망하는도다 네가 지식을 버렸으니 나도 너를 버려 내 제사장이 되지 못하게 할 것이요 네가 네 하나님의 율법을 잊었으니 나도 네 자녀들을 잊어버리리라'),
    (22168, '<이교 예배를 책망하시다> ○음행과 묵은 포도주와 새 포도주가 마음을 빼앗느니라'),
    (22170, '그들이 산 꼭대기에서 제사를 드리며 작은 산 위에서 분향하되 참나무와 버드나무와 상수리나무 아래에서 하니 이는 그 나무 그늘이 좋음이라 이러므로 너희 딸들은 음행하며 너희 며느리들은 간음을 행하는도다'),
    (22172, '○이스라엘아 너는 음행하여도 유다는 죄를 범하지 못하게 할 것이라 너희는 길갈로 가지 말며 벧아웬으로 올라가지 말며 여호와의 사심을 두고 맹세하지 말지어다'),
    (22226, '○이스라엘은 이미 삼켜졌은즉 이제 여러 나라 가운데에 있는 것이 즐겨 쓰지 아니하는 그릇 같도다'),
    (22229, '○에브라임은 죄를 위하여 제단을 많이 만들더니 그 제단이 그에게 범죄하게 하는 것이 되었도다'),
    (22210, '<이스라엘과 여러 민족> ○에브라임이 여러 민족 가운데에 혼합되니 그는 곧 뒤집지 않은 전병이로다'),
    (22283, '<거짓 저울을 쓰는 에브라임> ○그는 상인이라 손에 거짓 저울을 가지고 속이기를 좋아하는도다'),
    (22253, '○그들이 헛된 말을 내며 거짓 맹세로 언약을 세우니 그 재판이 밭이랑에 돋는 독초 같으리로다'),
    (22258, '<이스라엘에게 징계를 선언하시다> ○이스라엘아 네가 기브아 시대로부터 범죄하더니 지금까지 죄를 짓는구나 그러니 범죄한 자손들에 대한 전쟁이 어찌 기브아에서 일어나지 않겠느냐'),
    (22261, '○너희가 자기를 위하여 공의를 심고 인애를 거두라 너희 묵은 땅을 기경하라 지금이 곧 여호와를 찾을 때니 마침내 여호와께서 오사 공의를 비처럼 너희에게 내리시리라'),
    (22236, '그들은 여호와께 포도주를 부어 드리지 못하며 여호와께서 기뻐하시는 바도 되지 못할 것이라 그들의 제물은 애곡하는 자의 떡과 같아서 그것을 먹는 자는 더러워지나니 그들의 떡은 자기의 먹기에만 소용될 뿐이라 여호와의 집에 드릴 것이 아님이니라'),
    (22242, '<이스라엘의 죄와 하나님의 심판> ○옛적에 내가 이스라엘을 만나기를 광야에서 포도를 만남 같이 하였으며 너희 조상들을 보기를 무화과나무에서 처음 맺힌 첫 열매를 봄 같이 하였거늘 그들이 바알브올에 가서 부끄러운 우상에게 몸을 드림으로 저희가 사랑하는 우상 같이 가증하여졌도다'),
    (22269, '○그들은 애굽 땅으로 되돌아 가지 못하겠거늘 내게 돌아 오기를 싫어하니 앗수르 사람이 그 임금이 될 것이라'),
    (22272, '○에브라임이여 내가 어찌 너를 놓겠느냐 이스라엘이여 내가 어찌 너를 버리겠느냐 내가 어찌 너를 아드마 같이 놓겠느냐 어찌 너를 스보임 같이 두겠느냐 내 마음이 내 속에서 돌이키어 나의 긍휼이 온전히 불붙듯 하도다'),
    (22273, '내가 나의 맹렬한 진노를 나타내지 아니하며 내가 다시는 에브라임을 멸하지 아니하리니 이는 내가 하나님이요 사람이 아님이라 네 가운데 있는 거룩한 이니 진노함으로 네게 임하지 아니하리라'),
    (22276, '<하나님께로 돌아오라> ○에브라임은 거짓으로, 이스라엘 족속은 속임수로 나를 에워쌌고 유다는 하나님 곧 신실하시고 거룩하신 자에게 대하여 정함이 없도다'),
    (22292, '이제도 그들은 더욱 범죄하여 그 은으로 자기를 위하여 우상을 부어 만들되 자기의 정교함을 따라 우상을 만들었으며 그것은 다 은장색이 만든 것이거늘 그들은 그것에 대하여 말하기를 제사를 드리는 자는 송아지와 입을 맞출 것이라 하도다'),
    (22294, '○그러나 애굽 땅에 있을 때부터 나는 네 하나님 여호와라 나 밖에 네가 다른 신을 알지 말 것이라 나 외에는 구원자가 없느니라'),
    (22298, '내가 새끼 잃은 곰 같이 그들을 만나 그의 염통 꺼풀을 찢고 거기서 암사자 같이 그들을 삼키리라 들짐승이 그들을 찢으리라'),
    (22299, '○이스라엘아 네가 패망하였나니 이는 너를 도와 주는 나를 대적함이니라'),
    (22305, '○그가 비록 형제 중에서 결실하나 동풍이 오리니 곧 광야에서 일어나는 여호와의 바람이라 그의 근원이 마르며 그의 샘이 마르고 그 쌓아 둔 바 모든 보배의 그릇이 약탈되리로다'),
    (22309, '우리가 앗수르의 구원을 의지하지 아니하며 말을 타지 아니하며 다시는 우리의 손으로 만든 것을 향하여 너희는 우리의 신이라 하지 아니하오리니 이는 고아가 주로 말미암아 긍휼을 얻음이니이다 할지니라'),
    (22310, '<여호와의 진노가 떠나다> ○내가 그들의 반역을 고치고 기쁘게 그들을 사랑하리니 나의 진노가 그에게서 떠났음이니라'),
    (22315, '<여호와의 도> ○누가 지혜가 있어 이런 일을 깨달으며 누가 총명이 있어 이런 일을 알겠느냐 여호와의 도는 정직하니 의인은 그 길로 다니거니와 그러나 죄인은 그 길에 걸려 넘어지리라'),
    (22339, '○그의 모양은 말 같고 그 달리는 것은 기병 같으며'),
    (22347, '<여호와께로 돌아올지어다> ○여호와의 말씀에 너희는 이제라도 금식하고 울며 애통하고 마음을 다하여 내게로 돌아오라 하셨나니'),
    (22350, '○너희는 시온에서 나팔을 불어 거룩한 금식일을 정하고 성회를 소집하라'),
    (22352, '여호와를 섬기는 제사장들은 낭실과 제단 사이에서 울며 이르기를 여호와여 주의 백성을 불쌍히 여기소서 주의 기업을 욕되게 하여 나라들로 그들을 관할하지 못하게 하옵소서 어찌하여 이방인으로 그들의 하나님이 어디 있느냐 말하게 하겠나이까 할지어다'),
    (22353, '<이른 비와 늦은 비를 적당하게 주시다> ○그 때에 여호와께서 자기의 땅을 극진히 사랑하시어 그의 백성을 불쌍히 여기실 것이라'),
    (22354, '여호와께서 그들에게 응답하여 이르시기를 내가 너희에게 곡식과 새 포도주와 기름을 주리니 너희가 이로 말미암아 흡족하리라 내가 다시는 너희가 나라들 가운데에서 욕을 당하지 않게 할 것이며'),
    (22355, '내가 북쪽 군대를 너희에게서 멀리 떠나게 하여 메마르고 적막한 땅으로 쫓아내리니 그 앞의 부대는 동해로, 그 뒤의 부대는 서해로 들어갈 것이라 상한 냄새가 일어나고 악취가 오르리니 이는 큰 일을 행하였음이니라 하시리라'),
    (22356, '○땅이여 두려워하지 말고 기뻐하며 즐거워할지어다 여호와께서 큰 일을 행하셨음이로다'),
    (22358, '시온의 자녀들아 너희는 너희 하나님 여호와로 말미암아 기뻐하며 즐거워할지어다 그가 너희를 위하여 비를 내리시되 이른 비를 너희에게 적당하게 주시리니 이른 비와 늦은 비가 예전과 같을 것이라'),
    (22363, '<내 영을 만민에게 부어 주리니> ○그 후에 내가 내 영을 만민에게 부어 주리니 너희 자녀들이 장래 일을 말할 것이며 너희 늙은이는 꿈을 꾸며 너희 젊은이는 이상을 볼 것이며'),
    (22367, '누구든지 여호와의 이름을 부르는 자는 구원을 얻으리니 이는 나 여호와의 말대로 시온 산과 예루살렘에서 피할 자가 있을 것임이요 남은 자 중에 나 여호와의 부름을 받을 자가 있을 것임이니라'),
    (22317, '<농사를 망친 농부들의 애곡> ○늙은 자들아 너희는 이것을 들을지어다 땅의 모든 주민들아 너희는 귀를 기울일지어다 너희의 날에나 너희 조상들의 날에 이런 일이 있었느냐'),
    (22320, '○취하는 자들아 너희는 깨어 울지어다 포도주를 마시는 자들아 너희는 울지어다 이는 단 포도주가 너희 입에서 끊어졌음이니'),
    (22323, '○너희는 처녀가 어렸을 때에 약혼한 남자로 말미암아 굵은 베로 동이고 애곡함 같이 할지어다'),
    (22328, '○제사장들아 너희는 굵은 베로 동이고 슬피 울지어다 제단에 수종드는 자들아 너희는 울지어다 내 하나님께 수종드는 자들아 너희는 와서 굵은 베 옷을 입고 밤이 새도록 누울지어다 이는 소제와 전제를 너희 하나님의 성전에 드리지 못함이로다'),
    (22390, '○그가 이르되 여호와께서 시온에서부터 부르짖으시며 예루살렘에서부터 소리를 내시리니 목자의 초장이 마르고 갈멜 산 꼭대기가 마르리로다'),
    (22391, '<이스라엘 이웃 나라들에 내리신 벌> ○여호와께서 이와 같이 말씀하시되 다메섹의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 철 타작기로 타작하듯 길르앗을 압박하였음이라'),
    (22394, '○여호와께서 이와 같이 말씀하시되 가사의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 모든 사로잡은 자를 끌어 에돔에 넘겼음이라'),
    (22397, '○여호와께서 이와 같이 말씀하시되 두로의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 그 형제의 계약을 기억하지 아니하고 모든 사로잡은 자를 에돔에 넘겼음이라'),
    (22399, '○여호와께서 이와 같이 말씀하시되 에돔의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그가 칼로 그의 형제를 쫓아가며 긍휼을 버리며 항상 맹렬히 화를 내며 분을 끝없이 품었음이라'),
    (22401, '○여호와께서 이와 같이 말씀하시되 암몬 자손의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 자기 지경을 넓히고자 하여 길르앗의 아이 밴 여인의 배를 갈랐음이니라'),
    (22428, '<사마리아에 내리신 벌> ○아스돗의 궁궐들과 애굽 땅의 궁궐들에 선포하여 이르기를 너희는 사마리아 산들에 모여 그 성 중에서 얼마나 큰 요란함과 학대함이 있나 보라 하라'),
    (22432, '○주 여호와 만군의 하나님의 말씀이니라 너희는 듣고 야곱의 족속에게 증언하라'),
    (22369, '내가 만국을 모아 데리고 여호사밧 골짜기에 내려가서 내 백성 곧 내 기업인 이스라엘을 위하여 거기에서 그들을 심문하리니 이는 그들이 이스라엘을 나라들 가운데에 흩어 버리고 나의 땅을 나누었음이며'),
    (22376, '○너희는 모든 민족에게 이렇게 널리 선포할지어다 너희는 전쟁을 준비하고 용사를 격려하고 병사로 다 가까이 나아와서 올라오게 할지어다'),
    (22381, '<여호와께서 백성들에게 복을 주시다> ○사람이 많음이여, 심판의 골짜기에 사람이 많음이여, 심판의 골짜기에 여호와의 날이 가까움이로다'),
    (22385, '○그 날에 산들이 단 포도주를 떨어뜨릴 것이며 작은 산들이 젖을 흘릴 것이며 유다 모든 시내가 물을 흘릴 것이며 여호와의 성전에서 샘이 흘러 나와서 싯딤 골짜기에 대리라'),
    (22407, '<유다에 내리신 벌> ○여호와께서 이와 같이 말씀하시되 유다의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 여호와의 율법을 멸시하며 그 율례를 지키지 아니하고 그의 조상들이 따라가던 거짓 것에 미혹되었음이라'),
    (22409, '<이스라엘에 내리신 벌> ○여호와께서 이와 같이 말씀하시되 이스라엘의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 은을 받고 의인을 팔며 신 한 켤레를 받고 가난한 자를 팔며'),
    (22412, '○내가 아모리 사람을 그들 앞에서 멸하였나니 그 키는 백향목 높이와 같고 강하기는 상수리나무 같으나 내가 그 위의 열매와 그 아래의 뿌리를 진멸하였느니라'),
    (22416, '○보라 곡식 단을 가득히 실은 수레가 흙을 누름 같이 내가 너희를 누르리니'),
    (22438, '<돌아오지 아니하는 백성 이스라엘> ○너희는 벧엘에 가서 범죄하며 길갈에 가서 죄를 더하며 아침마다 너희 희생을, 삼일마다 너희 십일조를 드리며'),
    (22440, '○또 내가 너희 모든 성읍에서 너희 이를 깨끗하게 하며 너희의 각 처소에서 양식이 떨어지게 하였으나 너희가 내게로 돌아오지 아니하였느니라 여호와의 말씀이니라'),
    (22443, '내가 곡식을 마르게 하는 재앙과 깜부기 재앙으로 너희를 쳤으며 팥중이로 너희의 많은 동산과 포도원과 무화과나무와 감람나무를 다 먹게 하였으나 너희가 내게로 돌아오지 아니하였느니라 여호와의 말씀이니라'),
    (22444, '내가 너희 중에 전염병 보내기를 애굽에서 한 것처럼 하였으며 칼로 너희 청년들을 죽였으며 너희 말들을 노략하게 하며 너희 진영의 악취로 코를 찌르게 하였으나 너희가 내게로 돌아오지 아니하였느니라 여호와의 말씀이니라'),
    (22445, '내가 너희 중의 성읍 무너뜨리기를 하나님인 내가 소돔과 고모라를 무너뜨림 같이 하였으므로 너희가 불붙는 가운데서 빼낸 나무 조각 같이 되었으나 너희가 내게로 돌아오지 아니하였느니라 여호와의 말씀이니라'),
    (22446, '○그러므로 이스라엘아 내가 이와 같이 네게 행하리라 내가 이것을 네게 행하리니 이스라엘아 네 하나님 만나기를 준비하라'),
    (22506, '<넷째, 여름 과일 한 광주리,> 주 여호와께서 내게 이와 같이 보이셨느니라 보라 여름 과일 한 광주리이니라'),
    (22507, '그가 말씀하시되 아모스야 네가 무엇을 보느냐 내가 이르되 여름 과일 한 광주리니이다 하매 여호와께서 내게 이르시되 내 백성 이스라엘의 끝이 이르렀은즉 내가 다시는 그를 용서하지 아니하리니'),
    (22509, '○가난한 자를 삼키며 땅의 힘없는 자를 망하게 하려는 자들아 이 말을 들으라'),
    (22515, '너희 절기를 애통으로, 너희 모든 노래를 애곡으로 변하게 하며 모든 사람에게 굵은 베로 허리를 동이게 하며 모든 머리를 대머리가 되게 하며 독자의 죽음으로 말미암아 애통하듯 하게 하며 결국은 곤고한 날과 같게 하리라'),
    (22516, '○주 여호와의 말씀이니라 보라 날이 이를지라 내가 기근을 땅에 보내리니 양식이 없어 주림이 아니며 물이 없어 갈함이 아니요 여호와의 말씀을 듣지 못한 기갈이라'),
    (22519, '사마리아의 죄된 우상을 두고 맹세하여 이르기를 단아 네 신들이 살아 있음을 두고 맹세하노라 하거나 브엘세바가 위하는 것이 살아 있음을 두고 맹세하노라 하는 사람은 엎드러지고 다시 일어나지 못하리라'),
    (22482, '만군의 하나님 여호와의 말씀이니라 주 여호와가 당신을 두고 맹세하셨노라 내가 야곱의 영광을 싫어하며 그 궁궐들을 미워하므로 이 성읍과 거기에 가득한 것을 원수에게 넘기리라 하셨느니라'),
    (22484, '죽은 사람의 친척 곧 그 시체를 불사를 자가 그 뼈를 집 밖으로 가져갈 때에 그 집 깊숙한 곳에 있는 자에게 묻기를 아직 더 있느냐 하면 대답하기를 없다 하리니 그가 또 말하기를 잠잠하라 우리가 여호와의 이름을 부르지 못할 것이라 하리라'),
    (22486, '○말들이 어찌 바위 위에서 달리겠으며 소가 어찌 거기서 밭 갈겠느냐 그런데 너희는 정의를 쓸개로 바꾸며 공의의 열매를 쓴 쑥으로 바꾸며'),
    (22451, '<여호와를 찾으라> ○여호와께서 이스라엘 족속에게 이와 같이 말씀하시기를 너희는 나를 찾으라 그리하면 살리라'),
    (22458, '너희가 힘없는 자를 밟고 그에게서 밀의 부당한 세를 거두었은즉 너희가 비록 다듬은 돌로 집을 건축하였으나 거기 거주하지 못할 것이요 아름다운 포도원을 가꾸었으나 그 포도주를 마시지 못하리라'),
    (22461, '○너희는 살려면 선을 구하고 악을 구하지 말지어다 만군의 하나님 여호와께서 너희의 말과 같이 너희와 함께 하시리라'),
    (22463, '○그러므로 주 만군의 하나님 여호와께서 이와 같이 말씀하시기를 사람이 모든 광장에서 울겠고 모든 거리에서 슬프도다 슬프도다 하겠으며 농부를 불러다가 애곡하게 하며 울음꾼을 불러다가 울게 할 것이며'),
    (22465, '○화 있을진저 여호와의 날을 사모하는 자여 너희가 어찌하여 여호와의 날을 사모하느냐 그 날은 어둠이요 빛이 아니라'),
    (22468, '○내가 너희 절기들을 미워하여 멸시하며 너희 성회들을 기뻐하지 아니하나니'),
    (22520, '<다섯째, 범죄한 나라를 멸하리라,> 내가 보니 주께서 제단 곁에 서서 이르시되 기둥 머리를 쳐서 문지방이 움직이게 하며 그것으로 부서져서 무리의 머리에 떨어지게 하라 내가 그 남은 자를 칼로 죽이리니 그 중에서 한 사람도 도망하지 못하며 그 중에서 한 사람도 피하지 못하리라'),
    (22524, '○주 만군의 여호와는 땅을 만져 녹게 하사 거기 거주하는 자가 애통하게 하시며 그 온 땅이 강의 넘침 같이 솟아 오르며 애굽 강 같이 낮아지게 하시는 이요'),
    (22526, '○여호와의 말씀이니라 이스라엘 자손들아 너희는 내게 구스 족속 같지 아니하냐 내가 이스라엘을 애굽 땅에서, 블레셋 사람을 갑돌에서, 아람 사람을 기르에서 올라오게 하지 아니하였느냐'),
    (22530, '<이스라엘의 회복> ○그 날에 내가 다윗의 무너진 장막을 일으키고 그것들의 틈을 막으며 그 허물어진 것을 일으켜서 옛적과 같이 세우고'),
    (22532, '여호와의 말씀이니라 보라 날이 이를지라 그 때에 파종하는 자가 곡식 추수하는 자의 뒤를 이으며 포도를 밟는 자가 씨 뿌리는 자의 뒤를 이으며 산들은 단 포도주를 흘리며 작은 산들은 녹으리라'),
    (22489, '<첫째, 메뚜기 재앙,> 주 여호와께서 내게 보이신 것이 이러하니라 왕이 풀을 벤 후 풀이 다시 움돋기 시작할 때에 주께서 메뚜기를 지으시매'),
    (22492, '<둘째, 불,> ○주 여호와께서 또 내게 보이신 것이 이러하니라 주 여호와께서 명령하여 불로 징벌하게 하시니 불이 큰 바다를 삼키고 육지까지 먹으려 하는지라'),
    (22495, '<셋째, 다림줄,> ○또 내게 보이신 것이 이러하니라 다림줄을 가지고 쌓은 담 곁에 주께서 손에 다림줄을 잡고 서셨더니'),
    (22498, '<아모스와 아마샤의 대결> ○때에 벧엘의 제사장 아마샤가 이스라엘의 왕 여로보암에게 보내어 이르되 이스라엘 족속 중에 아모스가 왕을 모반하나니 그 모든 말을 이 땅이 견딜 수 없나이다'),
    (22505, '여호와께서 이와 같이 말씀하시기를 네 아내는 성읍 가운데서 창녀가 될 것이요 네 자녀들은 칼에 엎드러지며 네 땅은 측량하여 나누어질 것이며 너는 더러운 땅에서 죽을 것이요 이스라엘은 반드시 사로잡혀 그의 땅에서 떠나리라 하셨느니라'),
    (22535, '<여호와께서 에돔을 심판하시다> 오바댜의 묵시라 ○주 여호와께서 에돔에 대하여 이와 같이 말씀하시니라 우리가 여호와께로 말미암아 소식을 들었나니 곧 사자가 나라들 가운데에 보내심을 받고 이르기를 너희는 일어날지어다 우리가 일어나서 그와 싸우자 하는 것이니라'),
    (22540, '혹시 도둑이 네게 이르렀으며 강도가 밤중에 네게 이르렀을지라도 만족할 만큼 훔치면 그치지 아니하였겠느냐 혹시 포도를 따는 자가 네게 이르렀을지라도 그것을 얼마쯤 남기지 아니하였겠느냐 네가 어찌 그리 망하였는고'),
    (22545, '<에돔의 죄> ○네가 네 형제 야곱에게 행한 포학으로 말미암아 부끄러움을 당하고 영원히 멸절되리라'),
    (22550, '<여호와께서 만국을 벌하실 날> ○여호와께서 만국을 벌할 날이 가까웠나니 네가 행한 대로 너도 받을 것인즉 네가 행한 것이 네 머리로 돌아갈 것이라'),
    (22552, '<여호와께 속할 나라> ○오직 시온 산에서 피할 자가 있으리니 그 산이 거룩할 것이요 야곱 족속은 자기 기업을 누릴 것이며'),
    (22553, '야곱 족속은 불이 될 것이며 요셉 족속은 불꽃이 될 것이요 에서 족속은 지푸라기가 될 것이라 그들이 그들 위에 붙어서 그들을 불사를 것인즉 에서 족속에 남은 자가 없으리니 여호와께서 말씀하셨음이라'),
    (22559, '그러나 요나가 여호와의 얼굴을 피하려고 일어나 다시스로 도망하려 하여 욥바로 내려갔더니 마침 다시스로 가는 배를 만난지라 여호와의 얼굴을 피하여 그들과 함께 다시스로 가려고 배삯을 주고 배에 올랐더라'),
    (22560, '○여호와께서 큰 바람을 바다 위에 내리시매 바다 가운데에 큰 폭풍이 일어나 배가 거의 깨지게 된지라'),
    (22567, '○바다가 점점 흉용한지라 무리가 그에게 이르되 우리가 너를 어떻게 하여야 바다가 우리를 위하여 잔잔하겠느냐 하니'),
    (22570, '무리가 여호와께 부르짖어 이르되 여호와여 구하고 구하오니 이 사람의 생명 때문에 우리를 멸망시키지 마옵소서 무죄한 피를 우리에게 돌리지 마옵소서 주 여호와께서는 주의 뜻대로 행하심이니이다 하고'),
    (22573, '<요나의 기도> ○여호와께서 이미 큰 물고기를 예비하사 요나를 삼키게 하셨으므로 요나가 밤낮 삼 일을 물고기 뱃속에 있으니라'),
    (22583, '○여호와께서 그 물고기에게 말씀하시매 요나를 육지에 토하니라'),
    (22595, '여호와께 기도하여 이르되 여호와여 내가 고국에 있을 때에 이러하겠다고 말씀하지 아니하였나이까 그러므로 내가 빨리 다시스로 도망하였사오니 주께서는 은혜로우시며 자비로우시며 노하기를 더디하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시는 하나님이신 줄을 내가 알았음이니이다'),
    (22599, '하나님 여호와께서 박넝쿨을 예비하사 요나를 가리게 하셨으니 이는 그의 머리를 위하여 그늘이 지게 하며 그의 괴로움을 면하게 하려 하심이었더라 요나가 박넝쿨로 말미암아 크게 기뻐하였더니'),
    (22624, '그 때에 너희를 조롱하는 시를 지으며 슬픈 노래를 불러 이르기를 우리가 온전히 망하게 되었도다 그가 내 백성의 산업을 옮겨 내게서 떠나게 하시며 우리 밭을 나누어 패역자에게 주시는도다 하리니'),
    (22626, '○그들이 말하기를 너희는 예언하지 말라 이것은 예언할 것이 아니거늘 욕하는 말을 그치지 아니한다 하는도다'),
    (22632, '○야곱아 내가 반드시 너희 무리를 다 모으며 내가 반드시 이스라엘의 남은 자를 모으고 그들을 한 처소에 두기를 보스라의 양 떼 같이 하며 초장의 양 떼 같이 하리니 사람들이 크게 떠들 것이며'),
    (22633, '길을 여는 자가 그들 앞에 올라가고 그들은 길을 열어 성문에 이르러서는 그리로 나갈 것이며 그들의 왕이 앞서 가며 여호와께서는 선두로 가시리라'),
    (22606, '<야곱의 허물 이스라엘의 죄> ○백성들아 너희는 다 들을지어다 땅과 거기에 있는 모든 것들아 자세히 들을지어다 주 여호와께서 너희에게 대하여 증언하시되 곧 주께서 성전에서 그리하실 것이니라'),
    (22612, '<상처가 유다와 예루살렘에도 미치다> ○이러므로 내가 애통하며 애곡하고 벌거벗은 몸으로 행하며 들개 같이 애곡하고 타조 같이 애통하리니'),
    (22660, '<베들레헴에서 다스릴 자가 나오리라> ○베들레헴 에브라다야 너는 유다 족속 중에 작을지라도 이스라엘을 다스릴 자가 네게서 내게로 나올 것이라 그의 근본은 상고에, 영원에 있느니라'),
    (22666, '야곱의 남은 자는 여러 나라 가운데와 많은 백성 가운데에 있으리니 그들은 수풀의 짐승들 중의 사자 같고 양 떼 중의 젊은 사자 같아서 만일 그가 지나간즉 밟고 찢으리니 능히 구원할 자가 없을 것이라'),
    (22667, '네 손이 네 대적들 위에 들려서 네 모든 원수를 진멸하기를 바라노라'),
    (22668, '<심판> ○여호와께서 이르시되 그 날에 이르러는 내가 네 군마를 네 가운데에서 멸절하며 네 병거를 부수며'),
    (22638, '○내 백성을 유혹하는 선지자들은 이에 물 것이 있으면 평강을 외치나 그 입에 무엇을 채워 주지 아니하는 자에게는 전쟁을 준비하는도다 이런 선지자에 대하여 여호와께서 이르시되'),
    (22642, '○야곱 족속의 우두머리들과 이스라엘 족속의 통치자들 곧 정의를 미워하고 정직한 것을 굽게 하는 자들아 원하노니 이 말을 들을지어다'),
    (22644, '그들의 우두머리들은 뇌물을 위하여 재판하며 그들의 제사장은 삯을 위하여 교훈하며 그들의 선지자는 돈을 위하여 점을 치면서도 여호와를 의뢰하여 이르기를 여호와께서 우리 중에 계시지 아니하냐 재앙이 우리에게 임하지 아니하리라 하는도다'),
    (22645, '이러므로 너희로 말미암아 시온은 갈아엎은 밭이 되고 예루살렘은 무더기가 되고 성전의 산은 수풀의 높은 곳이 되리라'),
    (22647, '곧 많은 이방 사람들이 가며 이르기를 오라 우리가 여호와의 산에 올라가서 야곱의 하나님의 전에 이르자 그가 그의 도를 가지고 우리에게 가르치실 것이니라 우리가 그의 길로 행하리라 하리니 이는 율법이 시온에서부터 나올 것이요 여호와의 말씀이 예루살렘에서부터 나올 것임이라'),
    (22648, '그가 많은 민족들 사이의 일을 심판하시며 먼 곳 강한 이방 사람을 판결하시리니 무리가 그 칼을 쳐서 보습을 만들고 창을 쳐서 낫을 만들 것이며 이 나라와 저 나라가 다시는 칼을 들고 서로 치지 아니하며 다시는 전쟁을 연습하지 아니하고'),
    (22650, '만민이 각각 자기의 신의 이름을 의지하여 행하되 오직 우리는 우리 하나님 여호와의 이름을 의지하여 영원히 행하리로다'),
    (22651, '<이스라엘이 포로에서 돌아오리라> ○여호와께서 말씀하시되 그 날에는 내가 저는 자를 모으며 쫓겨난 자와 내가 환난 받게 한 자를 모아'),
    (22654, '○이제 네가 어찌하여 부르짖느냐 너희 중에 왕이 없어졌고 네 모사가 죽었으므로 네가 해산하는 여인처럼 고통함이냐'),
    (22655, '딸 시온이여 해산하는 여인처럼 힘들여 낳을지어다 이제 네가 성읍에서 나가서 들에 거주하며 또 바벨론까지 이르러 거기서 구원을 얻으리니 여호와께서 거기서 너를 네 원수들의 손에서 속량하여 내시리라'),
    (22658, '딸 시온이여 일어나서 칠지어다 내가 네 뿔을 무쇠 같게 하며 네 굽을 놋 같게 하리니 네가 여러 백성을 쳐서 깨뜨릴 것이라 네가 그들의 탈취물을 구별하여 여호와께 드리며 그들의 재물을 온 땅의 주께 돌리리라'),
    (22678, '내 백성아 너는 모압 왕 발락이 꾀한 것과 브올의 아들 발람이 그에게 대답한 것을 기억하며 싯딤에서부터 길갈까지의 일을 기억하라 그리하면 나 여호와가 공의롭게 행한 일을 알리라 하실 것이니라'),
    (22679, '<여호와께서 구하시는 것> ○내가 무엇을 가지고 여호와 앞에 나아가며 높으신 하나님께 경배할까 내가 번제물로 일 년 된 송아지를 가지고 그 앞에 나아갈까'),
    (22682, '○여호와께서 성읍을 향하여 외쳐 부르시나니 지혜는 주의 이름을 경외함이니라 너희는 매가 예비되었나니 그것을 정하신 이가 누구인지 들을지니라'),
    (22689, '너희가 오므리의 율례와 아합 집의 모든 예법을 지키고 그들의 전통을 따르니 내가 너희를 황폐하게 하며 그의 주민을 사람의 조소 거리로 만들리라 너희가 내 백성의 수욕을 담당하리라'),
    (22696, '<구원하시는 하나님> ○오직 나는 여호와를 우러러보며 나를 구원하시는 하나님을 바라보나니 나의 하나님이 나에게 귀를 기울이시리로다'),
    (22703, '<기도와 찬양> ○원하건대 주는 주의 지팡이로 주의 백성 곧 갈멜 속 삼림에 홀로 거주하는 주의 기업의 양 떼를 먹이시되 그들을 옛날 같이 바산과 길르앗에서 먹이시옵소서'),
    (22707, '○주와 같은 신이 어디 있으리이까 주께서는 죄악과 그 기업에 남은 자의 허물을 사유하시며 인애를 기뻐하시므로 진노를 오래 품지 아니하시나이다'),
    (22711, '<니느웨에 대한 여호와의 진노> ○여호와는 질투하시며 보복하시는 하나님이시니라 여호와는 보복하시며 진노하시되 자기를 거스르는 자에게 여호와는 보복하시며 자기를 대적하는 자에게 진노를 품으시며'),
    (22718, '○너희는 여호와께 대하여 무엇을 꾀하느냐 그가 온전히 멸하시리니 재난이 다시 일어나지 아니하리라'),
    (22723, '○나 여호와가 네게 대하여 명령하였나니 네 이름이 다시는 전파되지 않을 것이라 내가 네 신들의 집에서 새긴 우상과 부은 우상을 멸절하며 네 무덤을 준비하리니 이는 네가 쓸모 없게 되었음이라'),
    (22724, '○볼지어다 아름다운 소식을 알리고 화평을 전하는 자의 발이 산 위에 있도다 유다야 네 절기를 지키고 네 서원을 갚을지어다 악인이 진멸되었으니 그가 다시는 네 가운데로 통행하지 아니하리로다 하시니라'),
    (22732, '○니느웨는 예로부터 물이 모인 못 같더니 이제 모두 도망하니 서라 서라 하나 돌아보는 자가 없도다'),
    (22737, '만군의 여호와의 말씀에 내가 네 대적이 되어 네 병거들을 불살라 연기가 되게 하고 네 젊은 사자들을 칼로 멸할 것이며 내가 또 네 노략한 것을 땅에서 끊으리니 네 파견자의 목소리가 다시는 들리지 아니하리라 하셨느니라'),
    (22758, '<하박국의 호소> ○여호와여 내가 부르짖어도 주께서 듣지 아니하시니 어느 때까지리이까 내가 강포로 말미암아 외쳐도 주께서 구원하지 아니하시나이다'),
    (22761, '<여호와의 응답> ○여호와께서 이르시되 너희는 여러 나라를 보고 또 보고 놀라고 또 놀랄지어다 너희의 생전에 내가 한 가지 일을 행할 것이라 누가 너희에게 말할지라도 너희가 믿지 아니하리라'),
    (22768, '<하박국이 다시 호소하다> ○선지자가 이르되 여호와 나의 하나님, 나의 거룩한 이시여 주께서는 만세 전부터 계시지 아니하시니이까 우리가 사망에 이르지 아니하리이다 여호와여 주께서 심판하기 위하여 그들을 두셨나이다 반석이시여 주께서 경계하기 위하여 그들을 세우셨나이다'),
    (22745, '○네가 어찌 노아몬보다 낫겠느냐 그는 강들 사이에 있으므로 물이 둘렸으니 바다가 성루가 되었고 바다가 방어벽이 되었으며'),
    (22809, '○내가 들었으므로 내 창자가 흔들렸고 그 목소리로 말미암아 내 입술이 떨렸도다 무리가 우리를 치러 올라오는 환난 날을 내가 기다리므로 썩이는 것이 내 뼈에 들어왔으며 내 몸은 내 처소에서 떨리는도다'),
    (22777, '○보라 그의 마음은 교만하며 그 속에서 정직하지 못하나 의인은 그의 믿음으로 말미암아 살리라'),
    (22779, '그 무리가 다 속담으로 그를 평론하며 조롱하는 시로 그를 풍자하지 않겠느냐 곧 이르기를 화 있을진저 자기 소유 아닌 것을 모으는 자여 언제까지 이르겠느냐 볼모 잡은 것으로 무겁게 짐진 자여'),
    (22782, '○재앙을 피하기 위하여 높은 데 깃들이려 하며 자기 집을 위하여 부당한 이익을 취하는 자에게 화 있을진저'),
    (22785, '○피로 성읍을 건설하며 불의로 성을 건축하는 자에게 화 있을진저'),
    (22788, '○이웃에게 술을 마시게 하되 자기의 분노를 더하여 그에게 취하게 하고 그 하체를 드러내려 하는 자에게 화 있을진저'),
    (22791, '○새긴 우상은 그 새겨 만든 자에게 무엇이 유익하겠느냐 부어 만든 우상은 거짓 스승이라 만든 자가 이 말하지 못하는 우상을 의지하니 무엇이 유익하겠느냐'),
    (22814, '<여호와의 날> ○여호와께서 이르시되 내가 땅 위에서 모든 것을 진멸하리라'),
    (22819, '○주 여호와 앞에서 잠잠할지어다 이는 여호와의 날이 가까웠으므로 여호와께서 희생을 준비하고 그가 청할 자들을 구별하셨음이니라'),
    (22826, '○여호와의 큰 날이 가깝도다 가깝고도 빠르도다 여호와의 날의 소리로다 용사가 거기서 심히 슬피 우는도다'),
    (22834, '<이스라엘 이웃 나라들이 받을 벌> ○가사는 버림을 당하며 아스글론은 폐허가 되며 아스돗은 대낮에 쫓겨나며 에그론은 뽑히리라'),
    (22837, '그 지경은 유다 족속의 남은 자에게로 돌아갈지라 그들이 거기에서 양 떼를 먹이고 저녁에는 아스글론 집들에 누우리니 이는 그들의 하나님 여호와가 그들을 보살피사 그들이 사로잡힘을 돌이킬 것임이라'),
    (22838, '○내가 모압의 비방과 암몬 자손이 조롱하는 말을 들었나니 그들이 내 백성을 비방하고 자기들의 경계에 대하여 교만하였느니라'),
    (22839, '그러므로 만군의 여호와 이스라엘의 하나님이 말하노라 내가 나의 삶을 두고 맹세하노니 장차 모압은 소돔 같으며 암몬 자손은 고모라 같을 것이라 찔레가 나며 소금 구덩이가 되어 영원히 황폐하리니 내 백성의 남은 자들이 그들을 노략하며 나의 남은 백성이 그것을 기업으로 얻을 것이라'),
    (22840, '그들이 이런 일을 당할 것은 그들이 만군의 여호와의 백성을 훼방하고 교만하여졌음이라'),
    (22842, '○구스 사람들아 너희도 내 칼에 죽임을 당하리라'),
    (22845, '이는 기쁜 성이라 염려 없이 거주하며 마음속에 이르기를 오직 나만 있고 나 외에는 다른 이가 없다 하더니 어찌 이와 같이 황폐하여 들짐승이 엎드릴 곳이 되었는고 지나가는 자마다 비웃으며 손을 흔들리로다'),
    (22866, '<성전을 건축하라는 여호와의 말씀> 다리오 왕 제이년 여섯째 달 곧 그 달 초하루에 여호와의 말씀이 선지자 학개로 말미암아 스알디엘의 아들 유다 총독 스룹바벨과 여호사닥의 아들 대제사장 여호수아에게 임하니라 이르시되'),
    (22872, '○만군의 여호와가 말하노니 너희는 자기의 행위를 살필지니라'),
    (22874, '너희가 많은 것을 바랐으나 도리어 적었고 너희가 그것을 집으로 가져갔으나 내가 불어 버렸느니라 나 만군의 여호와가 말하노라 이것이 무슨 까닭이냐 내 집은 황폐하였으되 너희는 각각 자기의 집을 짓기 위하여 빨랐음이라'),
    (22877, '<성전 건축을 격려하다> ○스알디엘의 아들 스룹바벨과 여호사닥의 아들 대제사장 여호수아와 남은 모든 백성이 그들의 하나님 여호와의 목소리와 선지자 학개의 말을 들었으니 이는 그들의 하나님 여호와께서 그를 보내셨음이라 백성이 다 여호와를 경외하매'),
    (22879, '여호와께서 스알디엘의 아들 유다 총독 스룹바벨의 마음과 여호사닥의 아들 대제사장 여호수아의 마음과 남은 모든 백성의 마음을 감동시키시매 그들이 와서 만군의 여호와 그들의 하나님의 전 공사를 하였으니'),
    (22884, '그러나 여호와가 이르노라 스룹바벨아 스스로 굳세게 할지어다 여호사닥의 아들 대제사장 여호수아야 스스로 굳세게 할지어다 여호와의 말이니라 이 땅 모든 백성아 스스로 굳세게 하여 일할지어다 내가 너희와 함께 하노라 만군의 여호와의 말이니라'),
    (22890, '○다리오 왕 제이년 아홉째 달 이십사일에 여호와의 말씀이 선지자 학개에게 임하니라 이르시되'),
    (22892, '사람이 옷자락에 거룩한 고기를 쌌는데 그 옷자락이 만일 떡에나 국에나 포도주에나 기름에나 다른 음식물에 닿았으면 그것이 성물이 되겠느냐 하라 학개가 물으매 제사장들이 대답하여 이르되 아니니라 하는지라'),
    (22900, '○그 달 이십사일에 여호와의 말씀이 다시 학개에게 임하니라 이르시되'),
    (22903, '만군의 여호와가 말하노라 스알디엘의 아들 내 종 스룹바벨아 여호와가 말하노라 그 날에 내가 너를 세우고 너를 인장으로 삼으리니 이는 내가 너를 택하였음이니라 만군의 여호와의 말이니라 하시니라'),
    (22851, '내가 여러 나라를 끊어 버렸으므로 그들의 망대가 파괴되었고 내가 그들의 거리를 비게 하여 지나는 자가 없게 하였으므로 그들의 모든 성읍이 황폐하며 사람이 없으며 거주할 자가 없게 되었느니라'),
    (22852, '내가 이르기를 너는 오직 나를 경외하고 교훈을 받으라 그리하면 내가 형벌을 내리기로 정하기는 하였지만 너의 거처가 끊어지지 아니하리라 하였으나 그들이 부지런히 그들의 모든 행위를 더럽게 하였느니라'),
    (22853, '○나 여호와가 말하노라 그러므로 내가 일어나 벌할 날까지 너희는 나를 기다리라 내가 뜻을 정하고 나의 분노와 모든 진노를 쏟으려고 여러 나라를 소집하며 왕국들을 모으리라 온 땅이 나의 질투의 불에 소멸되리라'),
    (22854, '○그 때에 내가 여러 백성의 입술을 깨끗하게 하여 그들이 다 여호와의 이름을 부르며 한 가지로 나를 섬기게 하리니'),
    (22856, '그 날에 네가 내게 범죄한 모든 행위로 말미암아 수치를 당하지 아니할 것은 그 때에 내가 네 가운데서 교만하여 자랑하는 자들을 제거하여 네가 나의 성산에서 다시는 교만하지 않게 할 것임이라'),
    (22859, '<기뻐하며 부를 노래> ○시온의 딸아 노래할지어다 이스라엘아 기쁘게 부를지어다 예루살렘 딸아 전심으로 기뻐하며 즐거워할지어다'),
    (22862, '너의 하나님 여호와가 너의 가운데에 계시니 그는 구원을 베푸실 전능자이시라 그가 너로 말미암아 기쁨을 이기지 못하시며 너를 잠잠히 사랑하시며 너로 말미암아 즐거이 부르며 기뻐하시리라 하리라'),
    (22943, '○여호와의 천사가 여호수아에게 증언하여 이르되'),
    (22965, '만군의 여호와께서 이르시되 내가 이것을 보냈나니 도둑의 집에도 들어가며 내 이름을 가리켜 망령되이 맹세하는 자의 집에도 들어가서 그의 집에 머무르며 그 집을 나무와 돌과 아울러 사르리라 하셨느니라 하니라'),
    (22966, '<에바 속의 여인> ○내게 말하던 천사가 나아와서 내게 이르되 너는 눈을 들어 나오는 이것이 무엇인가 보라 하기로'),
    (22949, '그가 내게 묻되 네가 무엇을 보느냐 내가 대답하되 내가 보니 순금 등잔대가 있는데 그 위에는 기름 그릇이 있고 또 그 기름 그릇 위에 일곱 등잔이 있으며 그 기름 그릇 위에 있는 등잔을 위해서 일곱 관이 있고'),
    (22958, '○내가 그에게 물어 이르되 등잔대 좌우의 두 감람나무는 무슨 뜻이니이까 하고'),
    (22930, '○오호라 너희는 북방 땅에서 도피할지어다 여호와의 말씀이니라 이는 내가 너희를 하늘 사방에 바람 같이 흩어지게 하였음이니라 여호와의 말씀이니라'),
    (22981, '<면류관을 여호수아의 머리에 씌우다> ○여호와의 말씀이 내게 임하여 이르시되'),
    (22995, '<사로잡혀 가는 까닭> ○여호와의 말씀이 스가랴에게 임하여 이르시되'),
    (22907, '너희 조상들을 본받지 말라 옛적 선지자들이 그들에게 외쳐 이르되 만군의 여호와께서 이같이 말씀하시기를 너희가 악한 길, 악한 행위를 떠나서 돌아오라 하셨다 하나 그들이 듣지 아니하고 내게 귀를 기울이지 아니하였느니라 여호와의 말이니라'),
    (22909, '내가 나의 종 선지자들에게 명령한 내 말과 내 법도들이 어찌 너희 조상들에게 임하지 아니하였느냐 그러므로 그들이 돌이켜 이르기를 만군의 여호와께서 우리 길대로, 우리 행위대로 우리에게 행하시려고 뜻하신 것을 우리에게 행하셨도다 하였느니라'),
    (22910, '<화석류나무 사이에 선 자> ○다리오 왕 제이년 열한째 달 곧 스밧월 이십사일에 잇도의 손자 베레갸의 아들 선지자 스가랴에게 여호와의 말씀이 임하니라'),
    (22911, '내가 밤에 보니 한 사람이 붉은 말을 타고 골짜기 속 화석류나무 사이에 섰고 그 뒤에는 붉은 말과 자줏빛 말과 백마가 있기로'),
    (22921, '<네 뿔과 대장장이 네 명> ○내가 눈을 들어 본즉 네 개의 뿔이 보이기로'),
    (22924, '내가 말하되 그들이 무엇하러 왔나이까 하니 대답하여 이르시되 그 뿔들이 유다를 흩뜨려서 사람들이 능히 머리를 들지 못하게 하니 이 대장장이들이 와서 그것들을 두렵게 하고 이전의 뿔들을 들어 유다 땅을 흩뜨린 여러 나라의 뿔들을 떨어뜨리려 하느니라 하시더라'),
    (23057, '<두 목자> ○여호와 나의 하나님이 이르시되 너는 잡혀 죽을 양 떼를 먹이라'),
    (23059, '여호와가 말하노라 내가 다시는 이 땅 주민을 불쌍히 여기지 아니하고 그 사람들을 각각 그 이웃의 손과 임금의 손에 넘기리니 그들이 이 땅을 칠지라도 내가 그들의 손에서 건져내지 아니하리라 하시기로'),
    (23068, '○여호와께서 내게 이르시되 너는 또 어리석은 목자의 기구들을 빼앗을지니라'),
    (23069, '보라 내가 한 목자를 이 땅에 일으키리니 그가 없어진 자를 마음에 두지 아니하며 흩어진 자를 찾지 아니하며 상한 자를 고치지 아니하며 강건한 자를 먹이지 아니하고 오히려 살진 자의 고기를 먹으며 또 그 굽을 찢으리라'),
    (23010, '○만군의 여호와가 이같이 말하노라 만군의 여호와의 집 곧 성전을 건축하려고 그 지대를 쌓던 날에 있었던 선지자들의 입의 말을 이 날에 듣는 너희는 손을 견고히 할지어다'),
    (23011, '이 날 전에는 사람도 삯을 얻지 못하였고 짐승도 삯을 받지 못하였으며 사람이 원수로 말미암아 평안히 출입하지 못하였으니 내가 모든 사람을 풀어 서로 치게 하였느니라'),
    (23015, '○만군의 여호와가 이같이 말하노라 너희 조상들이 나를 격노하게 하였을 때에 내가 그들에게 재앙을 내리기로 뜻하고 뉘우치지 아니하였으나'),
    (23019, '<금식에 관하여 말씀하시다> ○만군의 여호와의 말씀이 내게 임하여 이르시되'),
    (23020, '만군의 여호와가 이같이 말하노라 넷째 달의 금식과 다섯째 달의 금식과 일곱째 달의 금식과 열째 달의 금식이 변하여 유다 족속에게 기쁨과 즐거움과 희락의 절기들이 되리니 오직 너희는 진리와 화평을 사랑할지니라'),
    (23024, '만군의 여호와가 이와 같이 말하노라 그 날에는 말이 다른 이방 백성 열 명이 유다 사람 하나의 옷자락을 잡을 것이라 곧 잡고 말하기를 하나님이 너희와 함께 하심을 들었나니 우리가 너희와 함께 가려 하노라 하리라 하시니라'),
    (23047, '내가 유다 족속을 견고하게 하며 요셉 족속을 구원할지라 내가 그들을 긍휼히 여김으로 그들이 돌아오게 하리니 그들은 내가 내버린 일이 없었음 같이 되리라 나는 그들의 하나님 여호와라 내가 그들에게 들으리라'),
    (23049, '○내가 그들을 향하여 휘파람을 불어 그들을 모을 것은 내가 그들을 구속하였음이라 그들이 전에 번성하던 것 같이 번성하리라'),
    (23053, '내가 그들로 나 여호와를 의지하여 견고하게 하리니 그들이 내 이름으로 행하리라 나 여호와의 말이니라'),
    (23032, '○내가 내 집을 둘러 진을 쳐서 적군을 막아 거기 왕래하지 못하게 할 것이라 포학한 자가 다시는 그 지경으로 지나가지 못하리니 이는 내가 눈으로 친히 봄이니라'),
    (23033, '<구원을 베풀 왕> ○시온의 딸아 크게 기뻐할지어다 예루살렘의 딸아 즐거이 부를지어다 보라 네 왕이 네게 임하시나니 그는 공의로우시며 구원을 베푸시며 겸손하여서 나귀를 타시나니 나귀의 작은 것 곧 나귀 새끼니라'),
    (23035, '○또 너로 말할진대 네 언약의 피로 말미암아 내가 네 갇힌 자들을 물 없는 구덩이에서 놓았나니'),
    (23039, '만군의 여호와께서 그들을 호위하시리니 그들이 원수를 삼키며 물맷돌을 밟을 것이며 그들이 피를 마시고 즐거이 부르기를 술취한 것 같이 할 것인즉 피가 가득한 동이와도 같고 피 묻은 제단 모퉁이와도 같을 것이라'),
    (23092, '<목자를 치라는 명령> ○만군의 여호와가 말하노라 칼아 깨어서 내 목자, 내 짝 된 자를 치라 목자를 치면 양이 흩어지려니와 작은 자들 위에는 내가 내 손을 드리우리라'),
    (23094, '내가 그 삼분의 일을 불 가운데에 던져 은 같이 연단하며 금 같이 시험할 것이라 그들이 내 이름을 부르리니 내가 들을 것이며 나는 말하기를 이는 내 백성이라 할 것이요 그들은 말하기를 여호와는 내 하나님이시라 하리라'),
    (23117, '<여호와께서 이스라엘을 사랑하시다> ○여호와께서 이르시되 내가 너희를 사랑하였노라 하나 너희는 이르기를 주께서 어떻게 우리를 사랑하셨나이까 하는도다 나 여호와가 말하노라 에서는 야곱의 형이 아니냐 그러나 내가 야곱을 사랑하였고'),
    (23119, '에돔은 말하기를 우리가 무너뜨림을 당하였으나 황폐된 곳을 다시 쌓으리라 하거니와 나 만군의 여호와는 이르노라 그들은 쌓을지라도 나는 헐리라 사람들이 그들을 일컬어 악한 지역이라 할 것이요 여호와의 영원한 진노를 받은 백성이라 할 것이며'),
    (23121, '<제사장과 백성들의 죄> ○내 이름을 멸시하는 제사장들아 나 만군의 여호와가 너희에게 이르기를 아들은 그 아버지를, 종은 그 주인을 공경하나니 내가 아버지일진대 나를 공경함이 어디 있느냐 내가 주인일진대 나를 두려워함이 어디 있느냐 하나 너희는 이르기를 우리가 어떻게 주의 이름을 멸시하였나이까 하는도다'),
    (23123, '만군의 여호와가 이르노라 너희가 눈 먼 희생제물을 바치는 것이 어찌 악하지 아니하며 저는 것, 병든 것을 드리는 것이 어찌 악하지 아니하냐 이제 그것을 너희 총독에게 드려 보라 그가 너를 기뻐하겠으며 너를 받아 주겠느냐'),
    (23125, '만군의 여호와가 이르노라 너희가 내 제단 위에 헛되이 불사르지 못하게 하기 위하여 너희 중에 성전 문을 닫을 자가 있었으면 좋겠도다 내가 너희를 기뻐하지 아니하며 너희가 손으로 드리는 것을 받지도 아니하리라'),
    (23126, '만군의 여호와가 이르노라 해 뜨는 곳에서부터 해 지는 곳까지의 이방 민족 중에서 내 이름이 크게 될 것이라 각처에서 내 이름을 위하여 분향하며 깨끗한 제물을 드리리니 이는 내 이름이 이방 민족 중에서 크게 될 것임이니라'),
    (23128, '만군의 여호와가 이르노라 너희가 또 말하기를 이 일이 얼마나 번거로운고 하며 코웃음치고 훔친 물건과 저는 것, 병든 것을 가져왔느니라 너희가 이같이 봉헌물을 가져오니 내가 그것을 너희 손에서 받겠느냐 이는 여호와의 말이니라'),
    (23129, '짐승 떼 가운데에 수컷이 있거늘 그 서원하는 일에 흠 있는 것으로 속여 내게 드리는 자는 저주를 받으리니 나는 큰 임금이요 내 이름은 이방 민족 중에서 두려워하는 것이 됨이니라 만군의 여호와의 말이니라'),
    (23071, '<예루살렘의 구원> 이스라엘에 관한 여호와의 경고의 말씀이라 ○여호와 곧 하늘을 펴시며 땅의 터를 세우시며 사람 안에 심령을 지으신 이가 이르시되'),
    (23074, '그 날에는 내가 예루살렘을 모든 민족에게 무거운 돌이 되게 하리니 그것을 드는 모든 자는 크게 상할 것이라 천하 만국이 그것을 치려고 모이리라'),
    (23077, '그 날에 내가 유다 지도자들을 나무 가운데에 화로 같게 하며 곡식단 사이에 횃불 같게 하리니 그들이 그 좌우에 에워싼 모든 민족들을 불사를 것이요 예루살렘 사람들은 다시 그 본 곳 예루살렘에 살게 되리라'),
    (23081, '○내가 다윗의 집과 예루살렘 주민에게 은총과 간구하는 심령을 부어 주리니 그들이 그 찌른 바 그를 바라보고 그를 위하여 애통하기를 독자를 위하여 애통하듯 하며 그를 위하여 통곡하기를 장자를 위하여 통곡하듯 하리로다'),
    (23171, '<예수 그리스도의 계보> 아브라함과 다윗의 자손 예수 그리스도의 계보라'),
    (23176, '이새는 다윗 왕을 낳으니라 ○다윗은 우리야의 아내에게서 솔로몬을 낳고'),
    (23183, '○바벨론으로 사로잡혀 간 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고'),
    (23188, '○그런즉 모든 대 수가 아브라함부터 다윗까지 열네 대요 다윗부터 바벨론으로 사로잡혀 갈 때까지 열네 대요 바벨론으로 사로잡혀 간 후부터 그리스도까지 열네 대더라'),
    (23189, '<예수 그리스도의 나심> ○예수 그리스도의 나심은 이러하니라 그의 어머니 마리아가 요셉과 약혼하고 동거하기 전에 성령으로 잉태된 것이 나타났더니'),
    (23165, '<여호와께서 정하신 날> 만군의 여호와가 이르노라 보라 용광로 불 같은 날이 이르리니 교만한 자와 악을 행하는 자는 다 지푸라기 같을 것이라 그 이르는 날에 그들을 살라 그 뿌리와 가지를 남기지 아니할 것이로되'),
    (23168, '○너희는 내가 호렙에서 온 이스라엘을 위하여 내 종 모세에게 명령한 법 곧 율례와 법도를 기억하라'),
    (23096, '내가 이방 나라들을 모아 예루살렘과 싸우게 하리니 성읍이 함락되며 가옥이 약탈되며 부녀가 욕을 당하며 성읍 백성이 절반이나 사로잡혀 가려니와 남은 백성은 성읍에서 끊어지지 아니하리라'),
    (23099, '그 산 골짜기는 아셀까지 이를지라 너희가 그 산 골짜기로 도망하되 유다 왕 웃시야 때에 지진을 피하여 도망하던 것 같이 하리라 나의 하나님 여호와께서 임하실 것이요 모든 거룩한 자들이 주와 함께 하리라'),
    (23103, '○여호와께서 천하의 왕이 되시리니 그 날에는 여호와께서 홀로 한 분이실 것이요 그의 이름이 홀로 하나이실 것이라'),
    (23104, '온 땅이 아라바 같이 되되 게바에서 예루살렘 남쪽 림몬까지 이를 것이며 예루살렘이 높이 들려 그 본처에 있으리니 베냐민 문에서부터 첫 문 자리와 성 모퉁이 문까지 또 하나넬 망대에서부터 왕의 포도주 짜는 곳까지라'),
    (23106, '○예루살렘을 친 모든 백성에게 여호와께서 내리실 재앙은 이러하니 곧 섰을 때에 그들의 살이 썩으며 그들의 눈동자가 눈구멍 속에서 썩으며 그들의 혀가 입 속에서 썩을 것이요'),
    (23110, '○예루살렘을 치러 왔던 이방 나라들 중에 남은 자가 해마다 올라와서 그 왕 만군의 여호와께 경배하며 초막절을 지킬 것이라'),
    (23115, '예루살렘과 유다의 모든 솥이 만군의 여호와의 성물이 될 것인즉 제사 드리는 자가 와서 이 솥을 가져다가 그것으로 고기를 삶으리라 그 날에는 만군의 여호와의 전에 가나안 사람이 다시 있지 아니하리라'),
    (23147, '만군의 여호와가 이르노라 보라 내가 내 사자를 보내리니 그가 내 앞에서 길을 준비할 것이요 또 너희가 구하는 바 주가 갑자기 그의 성전에 임하시리니 곧 너희가 사모하는 바 언약의 사자가 임하실 것이라'),
    (23151, '내가 심판하러 너희에게 임할 것이라 점치는 자에게와 간음하는 자에게와 거짓 맹세하는 자에게와 품꾼의 삯에 대하여 억울하게 하며 과부와 고아를 압제하며 나그네를 억울하게 하며 나를 경외하지 아니하는 자들에게 속히 증언하리라 만군의 여호와가 말하였느니라'),
    (23153, '<십일조> ○만군의 여호와가 이르노라 너희 조상들의 날로부터 너희가 나의 규례를 떠나 지키지 아니하였도다 그런즉 내게로 돌아오라 그리하면 나도 너희에게로 돌아가리라 하였더니 너희가 이르기를 우리가 어떻게 하여야 돌아가리이까 하는도다'),
    (23159, '<여호와를 경외하는 자들> ○여호와가 이르노라 너희가 완악한 말로 나를 대적하고도 이르기를 우리가 무슨 말로 주를 대적하였나이까 하는도다'),
    (23162, '○그 때에 여호와를 경외하는 자들이 피차에 말하매 여호와께서 그것을 분명히 들으시고 여호와를 경외하는 자와 그 이름을 존중히 여기는 자를 위하여 여호와 앞에 있는 기념책에 기록하셨느니라'),
    (23220, '<세례 요한이 천국을 전파하다> 그 때에 세례 요한이 이르러 유대 광야에서 전파하여 말하되'),
    (23230, '나는 너희로 회개하게 하기 위하여 물로 세례를 베풀거니와 내 뒤에 오시는 이는 나보다 능력이 많으시니 나는 그의 신을 들기도 감당하지 못하겠노라 그는 성령과 불로 너희에게 세례를 베푸실 것이요'),
    (23232, '<세례를 받으시다> ○이 때에 예수께서 갈릴리로부터 요단 강에 이르러 요한에게 세례를 받으려 하시니'),
    (23209, '<애굽으로 피하다> ○그들이 떠난 후에 주의 사자가 요셉에게 현몽하여 이르되 헤롯이 아기를 찾아 죽이려 하니 일어나 아기와 그의 어머니를 데리고 애굽으로 피하여 내가 네게 이르기까지 거기 있으라 하시니'),
    (23215, '<애굽에서 이스라엘 땅으로> ○헤롯이 죽은 후에 주의 사자가 애굽에서 요셉에게 현몽하여 이르되'),
    (23131, '만군의 여호와가 이르노라 너희가 만일 듣지 아니하며 마음에 두지 아니하여 내 이름을 영화롭게 하지 아니하면 내가 너희에게 저주를 내려 너희의 복을 저주하리라 내가 이미 저주하였나니 이는 너희가 그것을 마음에 두지 아니하였음이라'),
    (23139, '<거짓을 행하는 유다> ○우리는 한 아버지를 가지지 아니하였느냐 한 하나님께서 지으신 바가 아니냐 어찌하여 우리 각 사람이 자기 형제에게 거짓을 행하여 우리 조상들의 언약을 욕되게 하느냐'),
    (23142, '너희가 이런 일도 행하나니 곧 눈물과 울음과 탄식으로 여호와의 제단을 가리게 하는도다 그러므로 여호와께서 다시는 너희의 봉헌물을 돌아보지도 아니하시며 그것을 너희 손에서 기꺼이 받지도 아니하시거늘'),
    (23143, '너희는 이르기를 어찌 됨이니이까 하는도다 이는 너와 네가 어려서 맞이한 아내 사이에 여호와께서 증인이 되시기 때문이라 그는 네 짝이요 너와 서약한 아내로되 네가 그에게 거짓을 행하였도다'),
    (23144, '그에게는 영이 충만하였으나 오직 하나를 만들지 아니하셨느냐 어찌하여 하나만 만드셨느냐 이는 경건한 자손을 얻고자 하심이라 그러므로 네 심령을 삼가 지켜 어려서 맞이한 아내에게 거짓을 행하지 말지니라'),
    (23146, '<주께서 임하시는 날> ○너희가 말로 여호와를 괴롭게 하고도 이르기를 우리가 어떻게 여호와를 괴롭혀 드렸나이까 하는도다 이는 너희가 말하기를 모든 악을 행하는 자는 여호와의 눈에 좋게 보이며 그에게 기쁨이 된다 하며 또 말하기를 정의의 하나님이 어디 계시냐 함이니라'),
    (23237, '<시험을 받으시다> 그 때에 예수께서 성령에게 이끌리어 마귀에게 시험을 받으러 광야로 가사'),
    (23240, '예수께서 대답하여 이르시되 기록되었으되 사람이 떡으로만 살 것이 아니요 하나님의 입으로부터 나오는 모든 말씀으로 살 것이라  하였느니라 하시니'),
    (23248, '<비로소 천국을 전파하시다> ○예수께서 요한이 잡혔음을 들으시고 갈릴리로 물러가셨다가'),
    (23253, '○이 때부터 예수께서 비로소 전파하여 이르시되 회개하라 천국이 가까이 왔느니라 하시더라'),
    (23254, '<어부들을 부르시다> ○갈릴리 해변에 다니시다가 두 형제 곧 베드로라 하는 시몬과 그의 형제 안드레가 바다에 그물 던지는 것을 보시니 그들은 어부라'),
    (23259, '<가르치시며 전파하시며 고치시다> ○예수께서 온 갈릴리에 두루 다니사 그들의 회당에서 가르치시며 천국 복음을 전파하시며 백성 중의 모든 병과 모든 약한 것을 고치시니'),
    (23262, '<복이 있는 사람> 예수께서 무리를 보시고 산에 올라가 앉으시니 제자들이 나아온지라'),
    (23274, '<소금이요 빛이라> ○너희는 세상의 소금이니 소금이 만일 그 맛을 잃으면 무엇으로 짜게 하리요 후에는 아무 쓸 데 없어 다만 밖에 버려져 사람에게 밟힐 뿐이니라'),
    (23278, '<예수와 율법> ○내가 율법이나 선지자를 폐하러 온 줄로 생각하지 말라 폐하러 온 것이 아니요 완전하게 하려 함이라'),
    (23280, '그러므로 누구든지 이 계명 중의 지극히 작은 것 하나라도 버리고 또 그같이 사람을 가르치는 자는 천국에서 지극히 작다 일컬음을 받을 것이요 누구든지 이를 행하며 가르치는 자는 천국에서 크다 일컬음을 받으리라'),
    (23282, '<노하지 말라> ○옛 사람에게 말한 바 살인하지 말라 누구든지 살인하면 심판을 받게 되리라 하였다는 것을 너희가 들었으나'),
    (23288, '<간음하지 말라> ○또 간음하지 말라 하였다는 것을 너희가 들었으나'),
    (23294, '<맹세하지 말라> ○또 옛 사람에게 말한 바 헛 맹세를 하지 말고 네 맹세한 것을 주께 지키라 하였다는 것을 너희가 들었으나'),
    (23299, '<악한 자를 대적하지 말라> ○또 눈은 눈으로, 이는 이로 갚으라 하였다는 것을 너희가 들었으나'),
    (23304, '<원수를 사랑하라> ○또 네 이웃을 사랑하고 네 원수를 미워하라 하였다는 것을 너희가 들었으나'),
    (23311, '○그러므로 구제할 때에 외식하는 자가 사람에게서 영광을 받으려고 회당과 거리에서 하는 것 같이 너희 앞에 나팔을 불지 말라 진실로 너희에게 이르노니 그들은 자기 상을 이미 받았느니라'),
    (23314, '<너희는 이렇게 기도하라> ○또 너희는 기도할 때에 외식하는 자와 같이 하지 말라 그들은 사람에게 보이려고 회당과 큰 거리 어귀에 서서 기도하기를 좋아하느니라 내가 진실로 너희에게 이르노니 그들은 자기 상을 이미 받았느니라'),
    (23322, '우리를 시험에 들게 하지 마시옵고 다만 악에서 구하시옵소서 (나라와 권세와 영광이 아버지께 영원히 있사옵나이다 아멘)'),
    (23325, '<외식으로 금식하지 말라> ○금식할 때에 너희는 외식하는 자들과 같이 슬픈 기색을 보이지 말라 그들은 금식하는 것을 사람에게 보이려고 얼굴을 흉하게 하느니라 내가 진실로 너희에게 이르노니 그들은 자기 상을 이미 받았느니라'),
    (23328, '<보물을 하늘에 쌓아 두라> ○너희를 위하여 보물을 땅에 쌓아 두지 말라 거기는 좀과 동록이 해하며 도둑이 구멍을 뚫고 도둑질하느니라'),
    (23344, '<비판하지 말라> 비판을 받지 아니하려거든 비판하지 말라'),
    (23349, '○거룩한 것을 개에게 주지 말며 너희 진주를 돼지 앞에 던지지 말라 그들이 그것을 발로 밟고 돌이켜 너희를 찢어 상하게 할까 염려하라'),
    (23350, '<구하라 찾으라 문을 두드리라> ○구하라 그리하면 너희에게 주실 것이요 찾으라 그리하면 찾아낼 것이요 문을 두드리라 그리하면 너희에게 열릴 것이니'),
    (23356, '<좁은 문> ○좁은 문으로 들어가라 멸망으로 인도하는 문은 크고 그 길이 넓어 그리로 들어가는 자가 많고'),
    (23358, '<열매로 그들을 알리라> ○거짓 선지자들을 삼가라 양의 옷을 입고 너희에게 나아오나 속에는 노략질하는 이리라'),
    (23371, '<무리들이 가르치심에 놀라다> ○예수께서 이 말씀을 마치시매 무리들이 그의 가르치심에 놀라니'),
    (23373, '<나병환자를 깨끗하게 하시다> 예수께서 산에서 내려 오시니 수많은 무리가 따르니라'),
    (23377, '<백부장의 하인을 고치시다> ○예수께서 가버나움에 들어가시니 한 백부장이 나아와 간구하여'),
    (23386, '<많은 사람들을 다 고치시다> ○예수께서 베드로의 집에 들어가사 그의 장모가 열병으로 앓아 누운 것을 보시고'),
    (23390, '<나를 따르라> ○예수께서 무리가 자기를 에워싸는 것을 보시고 건너편으로 가기를 명하시니라'),
    (23395, '<바람과 바다를 잔잔하게 하시다> ○배에 오르시매 제자들이 따랐더니'),
    (23400, '<귀신 들린 두 사람을 고치시다> ○또 예수께서 건너편 가다라 지방에 가시매 귀신 들린 자 둘이 무덤 사이에서 나와 예수를 만나니 그들은 몹시 사나워 아무도 그 길로 지나갈 수 없을 지경이더라'),
    (23488, '<세례 요한> ○요한이 옥에서 그리스도께서 하신 일을 듣고 제자들을 보내어'),
    (23506, '<회개하지 아니하는 도시들> ○예수께서 권능을 가장 많이 행하신 고을들이 회개하지 아니하므로 그 때에 책망하시되'),
    (23511, '<짐 진 자들아 내게로 오라> ○그 때에 예수께서 대답하여 이르시되 천지의 주재이신 아버지여 이것을 지혜롭고 슬기 있는 자들에게는 숨기시고 어린 아이들에게는 나타내심을 감사하나이다'),
    (23407, '<중풍병자를 고치시다> 예수께서 배에 오르사 건너가 본 동네에 이르시니'),
    (23415, '<마태를 부르시다> ○예수께서 그 곳을 떠나 지나가시다가 마태라 하는 사람이 세관에 앉아 있는 것을 보시고 이르시되 나를 따르라 하시니 일어나 따르니라'),
    (23420, '<금식 논쟁> ○그 때에 요한의 제자들이 예수께 나아와 이르되 우리와 바리새인들은 금식하는데 어찌하여 당신의 제자들은 금식하지 아니하나이까'),
    (23424, '<한 관리의 딸과 예수의 옷을 만진 여자> ○예수께서 이 말씀을 하실 때에 한 관리가 와서 절하며 이르되 내 딸이 방금 죽었사오나 오셔서 그 몸에 손을 얹어 주소서 그러면 살아나겠나이다 하니'),
    (23433, '<맹인들의 눈을 뜨게 하시다> ○예수께서 거기에서 떠나가실새 두 맹인이 따라오며 소리 질러 이르되 다윗의 자손이여 우리를 불쌍히 여기소서 하더니'),
    (23438, '<말 못하는 사람을 고치시다> ○그들이 나갈 때에 귀신 들려 말 못하는 사람을 예수께 데려오니'),
    (23441, '<무리를 불쌍히 여기시다> ○예수께서 모든 도시와 마을에 두루 다니사 그들의 회당에서 가르치시며 천국 복음을 전파하시며 모든 병과 모든 약한 것을 고치시니라'),
    (23517, '<안식일에 밀 이삭을 자르다> 그 때에 예수께서 안식일에 밀밭 사이로 가실새 제자들이 시장하여 이삭을 잘라 먹으니'),
    (23525, '<안식일에 손 마른 사람을 고치시다> ○거기에서 떠나 그들의 회당에 들어가시니'),
    (23538, '<예수와 바알세불> ○그 때에 귀신 들려 눈 멀고 말 못하는 사람을 데리고 왔거늘 예수께서 고쳐 주시매 그 말 못하는 사람이 말하며 보게 된지라'),
    (23554, '<악한 세대가 표적을 구하나> ○그 때에 서기관과 바리새인 중 몇 사람이 말하되 선생님이여 우리에게 표적 보여주시기를 원하나이다'),
    (23562, '<예수의 어머니와 형제 자매> ○예수께서 무리에게 말씀하실 때에 그의 어머니와 동생들이 예수께 말하려고 밖에 섰더니'),
    (23567, '<네 가지 땅에 떨어진 씨 비유> 그 날 예수께서 집에서 나가사 바닷가에 앉으시매'),
    (23576, '<비유를 설명하시다> ○제자들이 예수께 나아와 이르되 어찌하여 그들에게 비유로 말씀하시나이까'),
    (23590, '○예수께서 그들 앞에 또 비유를 들어 이르시되 천국은 좋은 씨를 제 밭에 뿌린 사람과 같으니'),
    (23597, '<겨자씨와 누룩 비유> ○또 비유를 들어 이르시되 천국은 마치 사람이 자기 밭에 갖다 심은 겨자씨 한 알 같으니'),
    (23599, '○또 비유로 말씀하시되 천국은 마치 여자가 가루 서 말 속에 갖다 넣어 전부 부풀게 한 누룩과 같으니라'),
    (23600, '<비유로 말씀하신 까닭> ○예수께서 이 모든 것을 무리에게 비유로 말씀하시고 비유가 아니면 아무 것도 말씀하지 아니하셨으니'),
    (23602, '<가라지 비유를 설명하시다> ○이에 예수께서 무리를 떠나사 집에 들어가시니 제자들이 나아와 이르되 밭의 가라지의 비유를 우리에게 설명하여 주소서'),
    (23610, '<세 가지 비유> ○천국은 마치 밭에 감추인 보화와 같으니 사람이 이를 발견한 후 숨겨 두고 기뻐하며 돌아가서 자기의 소유를 다 팔아 그 밭을 사느니라'),
    (23611, '○또 천국은 마치 좋은 진주를 구하는 장사와 같으니'),
    (23613, '○또 천국은 마치 바다에 치고 각종 물고기를 모는 그물과 같으니'),
    (23617, '<새것과 옛것> ○이 모든 것을 깨달았느냐 하시니 대답하되 그러하오이다'),
    (23619, '<고향에서 배척을 받으시다> ○예수께서 이 모든 비유를 마치신 후에 그 곳을 떠나서'),
    (23625, '<세례 요한의 죽음> 그 때에 분봉 왕 헤롯이 예수의 소문을 듣고'),
    (23637, '<오천 명을 먹이시다> ○예수께서 들으시고 배를 타고 떠나사 따로 빈 들에 가시니 무리가 듣고 여러 고을로부터 걸어서 따라간지라'),
    (23646, '<물 위로 걸으시다> ○예수께서 즉시 제자들을 재촉하사 자기가 무리를 보내는 동안에 배를 타고 앞서 건너편으로 가게 하시고'),
    (23658, '<게네사렛에서 병자들을 고치시다> ○그들이 건너가 게네사렛 땅에 이르니'),
    (23445, '<열두 제자를 부르시다> 예수께서 그의 열두 제자를 부르사 더러운 귀신을 쫓아내며 모든 병과 모든 약한 것을 고치는 권능을 주시니라'),
    (23446, '<열두 제자에게 명하여 이르시다> ○열두 사도의 이름은 이러하니 베드로라 하는 시몬을 비롯하여 그의 형제 안드레와 세베대의 아들 야고보와 그의 형제 요한,'),
    (23460, '<미움을 받을 것이다> ○보라 내가 너희를 보냄이 양을 이리 가운데로 보냄과 같도다 그러므로 너희는 뱀 같이 지혜롭고 비둘기 같이 순결하라'),
    (23468, '<두려워할 분을 두려워하라> ○제자가 그 선생보다, 또는 종이 그 상전보다 높지 못하나니'),
    (23478, '<검을 주러 왔다> ○내가 세상에 화평을 주러 온 줄로 생각하지 말라 화평이 아니요 검을 주러 왔노라'),
    (23484, '<상을 받을 사람> ○너희를 영접하는 자는 나를 영접하는 것이요 나를 영접하는 자는 나를 보내신 이를 영접하는 것이니라'),
    (23728, '<영광스러운 모습으로 변형되시다> 엿새 후에 예수께서 베드로와 야고보와 그 형제 요한을 데리시고 따로 높은 산에 올라가셨더니'),
    (23731, '베드로가 예수께 여쭈어 이르되 주여 우리가 여기 있는 것이 좋사오니 만일 주께서 원하시면 내가 여기서 초막 셋을 짓되 하나는 주님을 위하여, 하나는 모세를 위하여, 하나는 엘리야를 위하여 하리이다'),
    (23736, '○그들이 산에서 내려올 때에 예수께서 명하여 이르시되 인자가 죽은 자 가운데서 살아나기 전에는 본 것을 아무에게도 이르지 말라 하시니'),
    (23741, '<귀신 들린 아이를 고치시다> ○그들이 무리에게 이르매 한 사람이 예수께 와서 꿇어 엎드려 이르되'),
    (23747, '이르시되 너희 믿음이 작은 까닭이니라 진실로 너희에게 이르노니 만일 너희에게 믿음이 겨자씨 한 알 만큼만 있어도 이 산을 명하여 여기서 저기로 옮겨지라 하면 옮겨질 것이요 또 너희가 못할 것이 없으리라'),
    (23749, '<죽음과 부활을 다시 이르시다> ○갈릴리에 모일 때에 예수께서 제자들에게 이르시되 인자가 장차 사람들의 손에 넘겨져'),
    (23751, '<성전세를 내시다> ○가버나움에 이르니 반 세겔 받는 자들이 베드로에게 나아와 이르되 너의 선생은 반 세겔을 내지 아니하느냐'),
    (23755, '<천국에서 큰 사람> 그 때에 제자들이 예수께 나아와 이르되 천국에서는 누가 크니이까'),
    (23769, '<형제가 죄를 범하거든> ○네 형제가 죄를 범하거든 가서 너와 그 사람과만 상대하여 권고하라 만일 들으면 네가 네 형제를 얻은 것이요'),
    (23775, '<용서할 줄 모르는 종 비유> ○그 때에 베드로가 나아와 이르되 주여 형제가 내게 죄를 범하면 몇 번이나 용서하여 주리이까 일곱 번까지 하오리이까'),
    (23661, '<장로들의 전통> 그 때에 바리새인과 서기관들이 예루살렘으로부터 예수께 나아와 이르되'),
    (23681, '<가나안 여자의 믿음> ○예수께서 거기서 나가사 두로와 시돈 지방으로 들어가시니'),
    (23689, '<많은 사람들을 고치시다> ○예수께서 거기서 떠나사 갈릴리 호숫가에 이르러 산에 올라가 거기 앉으시니'),
    (23692, '<사천 명을 먹이시다> ○예수께서 제자들을 불러 이르시되 내가 무리를 불쌍히 여기노라 그들이 나와 함께 있은 지 이미 사흘이매 먹을 것이 없도다 길에서 기진할까 하여 굶겨 보내지 못하겠노라'),
    (23700, '<악한 세대가 표적을 구하나> 바리새인과 사두개인들이 와서 예수를 시험하여 하늘로부터 오는 표적 보이기를 청하니'),
    (23704, '<바리새인과 사두개인들의 누룩> ○제자들이 건너편으로 갈새 떡 가져가기를 잊었더니'),
    (23712, '<베드로가 예수를 그리스도로 고백하다> ○예수께서 빌립보 가이사랴 지방에 이르러 제자들에게 물어 이르시되 사람들이 인자를 누구라 하느냐'),
    (23720, '<죽음과 부활을 처음으로 이르시다> ○이 때로부터 예수 그리스도께서 자기가 예루살렘에 올라가 장로들과 대제사장들과 서기관들에게 많은 고난을 받고 죽임을 당하고 제삼일에 살아나야 할 것을 제자들에게 비로소 나타내시니'),
    (23836, '<죽음과 부활을 세 번째로 이르시다> ○예수께서 예루살렘으로 올라가려 하실 때에 열두 제자를 따로 데리시고 길에서 이르시되'),
    (23839, '<한 어머니의 요구> ○그 때에 세베대의 아들의 어머니가 그 아들들을 데리고 예수께 와서 절하며 무엇을 구하니'),
    (23848, '<맹인 두 사람을 고치시다> ○그들이 여리고에서 떠나 갈 때에 큰 무리가 예수를 따르더라'),
    (23790, '<이혼에 대하여 가르치시다> 예수께서 이 말씀을 마치시고 갈릴리를 떠나 요단 강 건너 유대 지경에 이르시니'),
    (23792, '○바리새인들이 예수께 나아와 그를 시험하여 이르되 사람이 어떤 이유가 있으면 그 아내를 버리는 것이 옳으니이까'),
    (23802, '<어린 아이들에게 안수하시다> ○그 때에 사람들이 예수께서 안수하고 기도해 주심을 바라고 어린 아이들을 데리고 오매 제자들이 꾸짖거늘'),
    (23805, '<재물이 많은 청년> ○어떤 사람이 주께 와서 이르되 선생님이여 내가 무슨 선한 일을 하여야 영생을 얻으리이까'),
    (23812, '○예수께서 제자들에게 이르시되 내가 진실로 너희에게 이르노니 부자는 천국에 들어가기가 어려우니라'),
    (23946, '<서기관들과 바리새인들을 꾸짖으시다> 이에 예수께서 무리와 제자들에게 말씀하여 이르시되'),
    (23958, '○화 있을진저 외식하는 서기관들과 바리새인들이여 너희는 천국 문을 사람들 앞에서 닫고 너희도 들어가지 않고 들어가려 하는 자도 들어가지 못하게 하는도다'),
    (23960, '○화 있을진저 외식하는 서기관들과 바리새인들이여 너희는 교인 한 사람을 얻기 위하여 바다와 육지를 두루 다니다가 생기면 너희보다 배나 더 지옥 자식이 되게 하는도다'),
    (23961, '○화 있을진저 눈 먼 인도자여 너희가 말하되 누구든지 성전으로 맹세하면 아무 일 없거니와 성전의 금으로 맹세하면 지킬지라 하는도다'),
    (23968, '○화 있을진저 외식하는 서기관들과 바리새인들이여 너희가 박하와 회향과 근채의 십일조는 드리되 율법의 더 중한 바 정의와 긍휼과 믿음은 버렸도다 그러나 이것도 행하고 저것도 버리지 말아야 할지니라'),
    (23970, '○화 있을진저 외식하는 서기관들과 바리새인들이여 잔과 대접의 겉은 깨끗이 하되 그 안에는 탐욕과 방탕으로 가득하게 하는도다'),
    (23972, '○화 있을진저 외식하는 서기관들과 바리새인들이여 회칠한 무덤 같으니 겉으로는 아름답게 보이나 그 안에는 죽은 사람의 뼈와 모든 더러운 것이 가득하도다'),
    (23974, '○화 있을진저 외식하는 서기관들과 바리새인들이여 너희는 선지자들의 무덤을 만들고 의인들의 비석을 꾸미며 이르되'),
    (23979, '그러므로 내가 너희에게 선지자들과 지혜 있는 자들과 서기관들을 보내매 너희가 그 중에서 더러는 죽이거나 십자가에 못 박고 그 중에서 더러는 너희 회당에서 채찍질하고 이 동네에서 저 동네로 따라다니며 박해하리라'),
    (23982, '<예루살렘을 두고 이르시다> ○예루살렘아 예루살렘아 선지자들을 죽이고 네게 파송된 자들을 돌로 치는 자여 암탉이 그 새끼를 날개 아래에 모음 같이 내가 네 자녀를 모으려 한 일이 몇 번이더냐 그러나 너희가 원하지 아니하였도다'),
    (24049, '<달란트 비유> ○또 어떤 사람이 타국에 갈 때 그 종들을 불러 자기 소유를 맡김과 같으니'),
    (24066, '<인자가 모든 천사와 함께 올 때> ○인자가 자기 영광으로 모든 천사와 함께 올 때에 자기 영광의 보좌에 앉으리니'),
    (23854, '<예루살렘에 들어가시다> 그들이 예루살렘에 가까이 가서 감람 산 벳바게에 이르렀을 때에 예수께서 두 제자를 보내시며'),
    (23865, '<성전을 깨끗하게 하시다> ○예수께서 성전에 들어가사 성전 안에서 매매하는 모든 사람들을 내쫓으시며 돈 바꾸는 사람들의 상과 비둘기 파는 사람들의 의자를 둘러 엎으시고'),
    (23871, '<무화과나무가 마르다> ○이른 아침에 성으로 들어오실 때에 시장하신지라'),
    (23874, '예수께서 대답하여 이르시되 내가 진실로 너희에게 이르노니 만일 너희가 믿음이 있고 의심하지 아니하면 이 무화과나무에게 된 이런 일만 할 뿐 아니라 이 산더러 들려 바다에 던져지라 하여도 될 것이요'),
    (23876, '<예수의 권위를 두고 말하다> ○예수께서 성전에 들어가 가르치실새 대제사장들과 백성의 장로들이 나아와 이르되 네가 무슨 권위로 이런 일을 하느냐 또 누가 이 권위를 주었느냐'),
    (23884, '그 둘 중의 누가 아버지의 뜻대로 하였느냐 이르되 둘째 아들이니이다 예수께서 그들에게 이르시되 내가 진실로 너희에게 이르노니 세리들과 창녀들이 너희보다 먼저 하나님의 나라에 들어가리라'),
    (23886, '<포도원 농부 비유> ○다른 한 비유를 들으라 한 집 주인이 포도원을 만들어 산울타리로 두르고 거기에 즙 짜는 틀을 만들고 망대를 짓고 농부들에게 세로 주고 타국에 갔더니'),
    (23900, '<혼인 잔치 비유> 예수께서 다시 비유로 대답하여 이르시되'),
    (23914, '<가이사에게 세금을 바치는 것> ○이에 바리새인들이 가서 어떻게 하면 예수를 말의 올무에 걸리게 할까 상의하고'),
    (23915, '자기 제자들을 헤롯 당원들과 함께 예수께 보내어 말하되 선생님이여 우리가 아노니 당신은 참되시고 진리로 하나님의 도를 가르치시며 아무도 꺼리는 일이 없으시니 이는 사람을 외모로 보지 아니하심이니이다'),
    (23922, '<부활 논쟁> ○부활이 없다 하는 사두개인들이 그 날 예수께 와서 물어 이르되'),
    (23933, '<가장 큰 계명> ○예수께서 사두개인들로 대답할 수 없게 하셨다 함을 바리새인들이 듣고 모였는데'),
    (23940, '<그리스도와 다윗의 자손> ○바리새인들이 모였을 때에 예수께서 그들에게 물으시되'),
    (23985, '<성전이 무너뜨려질 것을 예언하시다> 예수께서 성전에서 나와서 가실 때에 제자들이 성전 건물들을 가리켜 보이려고 나아오니'),
    (23987, '<재난의 징조> ○예수께서 감람 산 위에 앉으셨을 때에 제자들이 조용히 와서 이르되 우리에게 이르소서 어느 때에 이런 일이 있겠사오며 또 주의 임하심과 세상 끝에는 무슨 징조가 있사오리이까'),
    (23999, '<가장 큰 환난> ○그러므로 너희가 선지자 다니엘이 말한 바 멸망의 가증한 것이 거룩한 곳에 선 것을 보거든 (읽는 자는 깨달을진저)'),
    (24013, '<인자가 오는 것을 보리라> ○그 날 환난 후에 즉시 해가 어두워지며 달이 빛을 내지 아니하며 별들이 하늘에서 떨어지며 하늘의 권능들이 흔들리리라'),
    (24016, '<무화과나무에서 배울 교훈> ○무화과나무의 비유를 배우라 그 가지가 연하여지고 잎사귀를 내면 여름이 가까운 줄을 아나니'),
    (24223, '<살아나시다> 안식일이 다 지나고 안식 후 첫날이 되려는 새벽에 막달라 마리아와 다른 마리아가 무덤을 보려고 갔더니'),
    (24233, '<경비병의 보고> ○여자들이 갈 때 경비병 중 몇이 성에 들어가 모든 된 일을 대제사장들에게 알리니'),
    (24238, '<제자들에게 할 일을 분부하시다> ○열한 제자가 갈릴리에 가서 예수께서 지시하신 산에 이르러'),
    (24288, '<중풍병자를 고치시다> 수 일 후에 예수께서 다시 가버나움에 들어가시니 집에 계시다는 소문이 들린지라'),
    (24300, '<레위를 부르시다> ○예수께서 다시 바닷가에 나가시매 큰 무리가 나왔거늘 예수께서 그들을 가르치시니라'),
    (24305, '<금식 논쟁> ○요한의 제자들과 바리새인들이 금식하고 있는지라 사람들이 예수께 와서 말하되 요한의 제자들과 바리새인의 제자들은 금식하는데 어찌하여 당신의 제자들은 금식하지 아니하나이까'),
    (24310, '<안식일에 밀 이삭을 자르다> ○안식일에 예수께서 밀밭 사이로 지나가실새 그의 제자들이 길을 열며 이삭을 자르니'),
    (24243, '<복음을 전파하다> 하나님의 아들 예수 그리스도의 복음의 시작이라'),
    (24251, '<세례를 받으시다> ○그 때에 예수께서 갈릴리 나사렛으로부터 와서 요단 강에서 요한에게 세례를 받으시고'),
    (24254, '<시험을 받으시다> ○성령이 곧 예수를 광야로 몰아내신지라'),
    (24256, '<갈릴리에서 복음을 전파하시다> ○요한이 잡힌 후 예수께서 갈릴리에 오셔서 하나님의 복음을 전파하여'),
    (24258, '<어부들을 부르시다> ○갈릴리 해변으로 지나가시다가 시몬과 그 형제 안드레가 바다에 그물 던지는 것을 보시니 그들은 어부라'),
    (24263, '<더러운 귀신 들린 사람을 고치시다> ○그들이 가버나움에 들어가니라 예수께서 곧 안식일에 회당에 들어가 가르치시매'),
    (24271, '<많은 사람을 고치시다> ○회당에서 나와 곧 야고보와 요한과 함께 시몬과 안드레의 집에 들어가시니'),
    (24274, '○저물어 해 질 때에 모든 병자와 귀신 들린 자를 예수께 데려오니'),
    (24277, '<전도 여행을 떠나시다> ○새벽 아직도 밝기 전에 예수께서 일어나 나가 한적한 곳으로 가사 거기서 기도하시더니'),
    (24282, '<나병환자를 깨끗하게 하시다> ○한 나병환자가 예수께 와서 꿇어 엎드려 간구하여 이르되 원하시면 저를 깨끗하게 하실 수 있나이다'),
    (24287, '그러나 그 사람이 나가서 이 일을 많이 전파하여 널리 퍼지게 하니 그러므로 예수께서 다시는 드러나게 동네에 들어가지 못하시고 오직 바깥 한적한 곳에 계셨으나 사방에서 사람들이 그에게로 나아오더라'),
    (24316, '<안식일에 손 마른 사람을 고치시다> 예수께서 다시 회당에 들어가시니 한쪽 손 마른 사람이 거기 있는지라'),
    (24322, '<많은 무리가 나아오다> ○예수께서 제자들과 함께 바다로 물러가시니 갈릴리에서 큰 무리가 따르며'),
    (24328, '<열두 제자를 세우시다> ○또 산에 오르사 자기가 원하는 자들을 부르시니 나아온지라'),
    (24335, '<예수와 바알세불> ○집에 들어가시니 무리가 다시 모이므로 식사할 겨를도 없는지라'),
    (24346, '<예수의 어머니와 형제 자매> ○그 때에 예수의 어머니와 동생들이 와서 밖에 서서 사람을 보내어 예수를 부르니'),
    (24157, '<예수를 빌라도에게 넘기다> 새벽에 모든 대제사장과 백성의 장로들이 예수를 죽이려고 함께 의논하고'),
    (24159, '<유다가 목매어 죽다> ○그 때에 예수를 판 유다가 그의 정죄됨을 보고 스스로 뉘우쳐 그 은 삼십을 대제사장들과 장로들에게 도로 갖다 주며'),
    (24167, '<십자가에 못 박히게 예수를 넘기다> ○예수께서 총독 앞에 섰으매 총독이 물어 이르되 네가 유대인의 왕이냐 예수께서 대답하시되 네 말이 옳도다 하시고'),
    (24183, '<군병들이 예수를 희롱하다> ○이에 총독의 군병들이 예수를 데리고 관정 안으로 들어가서 온 군대를 그에게로 모으고'),
    (24188, '<십자가에 못 박히시다> ○나가다가 시몬이란 구레네 사람을 만나매 그에게 예수의 십자가를 억지로 지워 가게 하였더라'),
    (24201, '<영혼이 떠나시다> ○제육시로부터 온 땅에 어둠이 임하여 제구시까지 계속되더니'),
    (24205, '그 남은 사람들이 이르되 가만 두라 엘리야가 와서 그를 구원하나 보자 하더라'),
    (24213, '<요셉이 예수의 시체를 무덤에 넣어 두다> ○저물었을 때에 아리마대의 부자 요셉이라 하는 사람이 왔으니 그도 예수의 제자라'),
    (24218, '<경비병이 무덤을 지키다> ○그 이튿날은 준비일 다음 날이라 대제사장들과 바리새인들이 함께 빌라도에게 모여 이르되'),
    (24220, '그러므로 명령하여 그 무덤을 사흘까지 굳게 지키게 하소서 그의 제자들이 와서 시체를 도둑질하여 가고 백성에게 말하되 그가 죽은 자 가운데서 살아났다 하면 후의 속임이 전보다 더 클까 하나이다 하니'),
    (24351, '<네 가지 땅에 떨어진 씨 비유> 예수께서 다시 바닷가에서 가르치시니 큰 무리가 모여들거늘 예수께서 바다에 떠 있는 배에 올라 앉으시고 온 무리는 바닷가 육지에 있더라'),
    (24360, '<비유를 설명하시다> ○예수께서 홀로 계실 때에 함께 한 사람들이 열두 제자와 더불어 그 비유들에 대하여 물으니'),
    (24371, '<등불은 등경 위에> ○또 그들에게 이르시되 사람이 등불을 가져오는 것은 말 아래에나 평상 아래에 두려 함이냐 등경 위에 두려 함이 아니냐'),
    (24376, '<자라나는 씨 비유> ○또 이르시되 하나님의 나라는 사람이 씨를 땅에 뿌림과 같으니'),
    (24380, '<겨자씨 비유> ○또 이르시되 우리가 하나님의 나라를 어떻게 비교하며 또 무슨 비유로 나타낼까'),
    (24383, '<비유로 가르치시다> ○예수께서 이러한 많은 비유로 그들이 알아 들을 수 있는 대로 말씀을 가르치시되'),
    (24385, '<바람과 바다를 잔잔하게 하시다> ○그 날 저물 때에 제자들에게 이르시되 우리가 저편으로 건너가자 하시니'),
    (24082, '<예수를 죽이려고 의논하다> 예수께서 이 말씀을 다 마치시고 제자들에게 이르시되'),
    (24087, '<예수의 머리에 향유를 붓다> ○예수께서 베다니 나병환자 시몬의 집에 계실 때에'),
    (24095, '<유다가 배반하다> ○그 때에 열둘 중의 하나인 가룟 유다라 하는 자가 대제사장들에게 가서 말하되'),
    (24098, '<마지막 만찬> ○무교절의 첫날에 제자들이 예수께 나아와서 이르되 유월절 음식 잡수실 것을 우리가 어디서 준비하기를 원하시나이까'),
    (24111, '○이에 그들이 찬미하고 감람 산으로 나아가니라'),
    (24112, '<베드로가 부인할 것을 예언하시다> ○그 때에 예수께서 제자들에게 이르시되 오늘 밤에 너희가 다 나를 버리리라 기록된 바 내가 목자를 치리니 양의 떼가 흩어지리라 하였느니라'),
    (24117, '<겟세마네에서 기도하시다> ○이에 예수께서 제자들과 함께 겟세마네라 하는 곳에 이르러 제자들에게 이르시되 내가 저기 가서 기도할 동안에 너희는 여기 앉아 있으라 하시고'),
    (24120, '조금 나아가사 얼굴을 땅에 대시고 엎드려 기도하여 이르시되 내 아버지여 만일 할 만하시거든 이 잔을 내게서 지나가게 하옵소서 그러나 나의 원대로 마시옵고 아버지의 원대로 하옵소서 하시고'),
    (24128, '<잡히시다> ○말씀하실 때에 열둘 중의 하나인 유다가 왔는데 대제사장들과 백성의 장로들에게서 파송된 큰 무리가 칼과 몽치를 가지고 그와 함께 하였더라'),
    (24138, '<공회 앞에 서시다> ○예수를 잡은 자들이 그를 끌고 대제사장 가야바에게로 가니 거기 서기관과 장로들이 모여 있더라'),
    (24145, '예수께서 이르시되 네가 말하였느니라 그러나 내가 너희에게 이르노니 이 후에 인자가 권능의 우편에 앉아 있는 것과 하늘 구름을 타고 오는 것을 너희가 보리라 하시니'),
    (24150, '<베드로가 예수를 알지 못한다고 하다> ○베드로가 바깥 뜰에 앉았더니 한 여종이 나아와 이르되 너도 갈릴리 사람 예수와 함께 있었도다 하거늘'),
    (24392, '<귀신 들린 사람을 고치시다> 예수께서 바다 건너편 거라사인의 지방에 이르러'),
    (24394, '그 사람은 무덤 사이에 거처하는데 이제는 아무도 그를 쇠사슬로도 맬 수 없게 되었으니'),
    (24412, '<야이로의 딸과 예수의 옷에 손을 댄 여자> ○예수께서 배를 타시고 다시 맞은편으로 건너가시니 큰 무리가 그에게로 모이거늘 이에 바닷가에 계시더니'),
    (24416, '○열두 해를 혈루증으로 앓아 온 한 여자가 있어'),
    (24426, '○아직 예수께서 말씀하실 때에 회당장의 집에서 사람들이 와서 회당장에게 이르되 당신의 딸이 죽었나이다 어찌하여 선생을 더 괴롭게 하나이까'),
    (24435, '<고향에서 배척을 받으시다> 예수께서 거기를 떠나사 고향으로 가시니 제자들도 따르니라'),
    (24440, '<열두 제자를 부르사 둘씩 보내시다> 그들이 믿지 않음을 이상히 여기셨더라 ○이에 모든 촌에 두루 다니시며 가르치시더라'),
    (24442, '○열두 제자를 부르사 둘씩 둘씩 보내시며 더러운 귀신을 제어하는 권능을 주시고'),
    (24449, '<세례 요한의 죽음> ○이에 예수의 이름이 드러난지라 헤롯 왕이 듣고 이르되 이는 세례 요한이 죽은 자 가운데서 살아났도다 그러므로 이런 능력이 그 속에서 일어나느니라 하고'),
    (24465, '<오천 명을 먹이시다> ○사도들이 예수께 모여 자기들이 행한 것과 가르친 것을 낱낱이 고하니'),
    (24480, '<바다 위로 걸으시다> ○예수께서 즉시 제자들을 재촉하사 자기가 무리를 보내는 동안에 배 타고 앞서 건너편 벳새다로 가게 하시고'),
    (24488, '<게네사렛에서 병자들을 고치시다> ○건너가 게네사렛 땅에 이르러 대고'),
    (24529, '<사천 명을 먹이시다> 그 무렵에 또 큰 무리가 있어 먹을 것이 없는지라 예수께서 제자들을 불러 이르시되'),
    (24539, '<이 세대가 표적을 구하나> ○바리새인들이 나와서 예수를 힐난하며 그를 시험하여 하늘로부터 오는 표적을 구하거늘'),
    (24542, '<바리새인들과 헤롯의 누룩> ○제자들이 떡 가져오기를 잊었으매 배에 떡 한 개밖에 그들에게 없더라'),
    (24550, '<벳새다에서 맹인을 고치시다> ○벳새다에 이르매 사람들이 맹인 한 사람을 데리고 예수께 나아와 손 대시기를 구하거늘'),
    (24555, '<베드로의 고백, 죽음과 부활을 말씀하심,> ○예수와 제자들이 빌립보 가이사랴 여러 마을로 나가실새 길에서 제자들에게 물어 이르시되 사람들이 나를 누구라고 하느냐'),
    (24492, '<장로들의 전통> 바리새인들과 또 서기관 중 몇이 예루살렘에서 와서 예수께 모여들었다가'),
    (24515, '<수로보니게 여자의 믿음> ○예수께서 일어나사 거기를 떠나 두로 지방으로 가서 한 집에 들어가 아무도 모르게 하시려 하나 숨길 수 없더라'),
    (24522, '<귀 먹고 말 더듬는 사람을 고치시다> ○예수께서 다시 두로 지방에서 나와 시돈을 지나고 데가볼리 지방을 통과하여 갈릴리 호수에 이르시매'),
    (24568, '<영광스러운 모습으로 변형되시다> ○엿새 후에 예수께서 베드로와 야고보와 요한을 데리시고 따로 높은 산에 올라가셨더니 그들 앞에서 변형되사'),
    (24575, '○그들이 산에서 내려올 때에 예수께서 경고하시되 인자가 죽은 자 가운데서 살아날 때까지는 본 것을 아무에게도 이르지 말라 하시니'),
    (24580, '<귀신 들린 아이를 고치시다> ○이에 그들이 제자들에게 와서 보니 큰 무리가 그들을 둘러싸고 서기관들이 그들과 더불어 변론하고 있더라'),
    (24596, '<죽음과 부활을 두 번째로 말씀하시다> ○그 곳을 떠나 갈릴리 가운데로 지날새 예수께서 아무에게도 알리고자 아니하시니'),
    (24599, '<누가 크냐> ○가버나움에 이르러 집에 계실새 제자들에게 물으시되 너희가 길에서 서로 토론한 것이 무엇이냐 하시되'),
    (24604, '<우리를 위하는 사람> ○요한이 예수께 여짜오되 선생님 우리를 따르지 않는 어떤 자가 주의 이름으로 귀신을 내쫓는 것을 우리가 보고 우리를 따르지 아니하므로 금하였나이다'),
    (24746, '<성전이 무너뜨려질 것을 이르시다> 예수께서 성전에서 나가실 때에 제자 중 하나가 이르되 선생님이여 보소서 이 돌들이 어떠하며 이 건물들이 어떠하니이까'),
    (24748, '<재난의 징조> ○예수께서 감람 산에서 성전을 마주 대하여 앉으셨을 때에 베드로와 야고보와 요한과 안드레가 조용히 묻되'),
    (24754, '○너희는 스스로 조심하라 사람들이 너희를 공회에 넘겨 주겠고 너희를 회당에서 매질하겠으며 나로 말미암아 너희가 권력자들과 임금들 앞에 서리니 이는 그들에게 증거가 되려 함이라'),
    (24759, '<가장 큰 환난> ○멸망의 가증한 것이 서지 못할 곳에 선 것을 보거든 (읽는 자는 깨달을진저) 그 때에 유대에 있는 자들은 산으로 도망할지어다'),
    (24769, '<인자가 오는 것을 보리라> ○그 때에 그 환난 후 해가 어두워지며 달이 빛을 내지 아니하며'),
    (24773, '<무화과나무 비유에서 배울 교훈> ○무화과나무의 비유를 배우라 그 가지가 연하여지고 잎사귀를 내면 여름이 가까운 줄 아나니'),
    (24617, '<이혼에 대하여 가르치시다> 예수께서 거기서 떠나 유대 지경과 요단 강 건너편으로 가시니 무리가 다시 모여들거늘 예수께서 다시 전례대로 가르치시더니'),
    (24629, '<어린 아이들을 축복하시다> ○사람들이 예수께서 만져 주심을 바라고 어린 아이들을 데리고 오매 제자들이 꾸짖거늘'),
    (24633, '<재물이 많은 사람> ○예수께서 길에 나가실새 한 사람이 달려와서 꿇어 앉아 묻자오되 선한 선생님이여 내가 무엇을 하여야 영생을 얻으리이까'),
    (24637, '예수께서 그를 보시고 사랑하사 이르시되 네게 아직도 한 가지 부족한 것이 있으니 가서 네게 있는 것을 다 팔아 가난한 자들에게 주라 그리하면 하늘에서 보화가 네게 있으리라 그리고 와서 나를 따르라 하시니'),
    (24639, '○예수께서 둘러 보시고 제자들에게 이르시되 재물이 있는 자는 하나님의 나라에 들어가기가 심히 어렵도다 하시니'),
    (24648, '<죽음과 부활을 세 번째로 이르시다> ○예루살렘으로 올라가는 길에 예수께서 그들 앞에 서서 가시는데 그들이 놀라고 따르는 자들은 두려워하더라 이에 다시 열두 제자를 데리시고 자기가 당할 일을 말씀하여 이르시되'),
    (24651, '<야고보와 요한이 구하는 것> ○세베대의 아들 야고보와 요한이 주께 나아와 여짜오되 선생님이여 무엇이든지 우리가 구하는 바를 우리에게 하여 주시기를 원하옵나이다'),
    (24662, '<맹인 바디매오가 고침을 받다> ○그들이 여리고에 이르렀더니 예수께서 제자들과 허다한 무리와 함께 여리고에서 나가실 때에 디매오의 아들인 맹인 거지 바디매오가 길 가에 앉았다가'),
    (24669, '<예루살렘에 들어가시다> 그들이 예루살렘에 가까이 와서 감람 산 벳바게와 베다니에 이르렀을 때에 예수께서 제자 중 둘을 보내시며'),
    (24679, '○예수께서 예루살렘에 이르러 성전에 들어가사 모든 것을 둘러 보시고 때가 이미 저물매 열두 제자를 데리시고 베다니에 나가시니라'),
    (24680, '<무화과나무에게 이르시다> ○이튿날 그들이 베다니에서 나왔을 때에 예수께서 시장하신지라'),
    (24683, '<성전을 깨끗하게 하시다> ○그들이 예루살렘에 들어가니라 예수께서 성전에 들어가사 성전 안에서 매매하는 자들을 내쫓으시며 돈 바꾸는 자들의 상과 비둘기 파는 자들의 의자를 둘러 엎으시며'),
    (24687, '○그리고 날이 저물매 그들이 성 밖으로 나가더라'),
    (24688, '<무화과나무가 마르다> ○그들이 아침에 지나갈 때에 무화과나무가 뿌리째 마른 것을 보고'),
    (24695, '<예수의 권위를 두고 말하다> ○그들이 다시 예루살렘에 들어가니라 예수께서 성전에서 거니실 때에 대제사장들과 서기관들과 장로들이 나아와'),
    (24702, '<포도원 농부 비유> 예수께서 비유로 그들에게 말씀하시되 한 사람이 포도원을 만들어 산울타리로 두르고 즙 짜는 틀을 만들고 망대를 지어서 농부들에게 세로 주고 타국에 갔더니'),
    (24714, '<가이사에게 세금을 바치는 것> ○그들이 예수의 말씀을 책잡으려 하여 바리새인과 헤롯당 중에서 사람을 보내매'),
    (24715, '와서 이르되 선생님이여 우리가 아노니 당신은 참되시고 아무도 꺼리는 일이 없으시니 이는 사람을 외모로 보지 않고 오직 진리로써 하나님의 도를 가르치심이니이다 가이사에게 세금을 바치는 것이 옳으니이까 옳지 아니하니이까'),
    (24719, '<부활 논쟁> ○부활이 없다 하는 사두개인들이 예수께 와서 물어 이르되'),
    (24727, '죽은 자가 살아난다는 것을 말할진대 너희가 모세의 책 중 가시나무 떨기에 관한 글에 하나님께서 모세에게 이르시되 나는 아브라함의 하나님이요 이삭의 하나님이요 야곱의 하나님이로라 하신 말씀을 읽어보지 못하였느냐'),
    (24729, '<가장 큰 계명> ○서기관 중 한 사람이 그들이 변론하는 것을 듣고 예수께서 잘 대답하신 줄을 알고 나아와 묻되 모든 계명 중에 첫째가 무엇이니이까'),
    (24736, '<그리스도와 다윗의 자손> ○예수께서 성전에서 가르치실새 대답하여 이르시되 어찌하여 서기관들이 그리스도를 다윗의 자손이라 하느냐'),
    (24739, '<서기관들을 삼가라> ○예수께서 가르치실 때에 이르시되 긴 옷을 입고 다니는 것과 시장에서 문안 받는 것과'),
    (24742, '<가난한 과부의 헌금> ○예수께서 헌금함을 대하여 앉으사 무리가 어떻게 헌금함에 돈 넣는가를 보실새 여러 부자는 많이 넣는데'),
    (24855, '<빌라도가 예수께 묻다> 새벽에 대제사장들이 즉시 장로들과 서기관들 곧 온 공회와 더불어 의논하고 예수를 결박하여 끌고 가서 빌라도에게 넘겨 주니'),
    (24860, '<십자가에 못 박히게 예수를 넘기다> ○명절이 되면 백성들이 요구하는 대로 죄수 한 사람을 놓아 주는 전례가 있더니'),
    (24870, '<군인들이 예수를 희롱하다> ○군인들이 예수를 끌고 브라이도리온이라는 뜰 안으로 들어가서 온 군대를 모으고'),
    (24875, '<십자가에 못 박히시다> ○마침 알렉산더와 루포의 아버지인 구레네 사람 시몬이 시골로부터 와서 지나가는데 그들이 그를 억지로 같이 가게 하여 예수의 십자가를 지우고'),
    (24887, '<숨지시다> ○제육시가 되매 온 땅에 어둠이 임하여 제구시까지 계속하더니'),
    (24896, '<요셉이 예수의 시체를 무덤에 넣어 두다> ○이 날은 준비일 곧 안식일 전날이므로 저물었을 때에'),
    (24783, '<예수를 죽일 방도를 찾다> 이틀이 지나면 유월절과 무교절이라 대제사장들과 서기관들이 예수를 흉계로 잡아 죽일 방도를 구하며'),
    (24785, '<예수의 머리에 향유를 붓다> ○예수께서 베다니 나병환자 시몬의 집에서 식사하실 때에 한 여자가 매우 값진 향유 곧 순전한 나드 한 옥합을 가지고 와서 그 옥합을 깨뜨려 예수의 머리에 부으니'),
    (24792, '<유다가 배반하다> ○열둘 중의 하나인 가룟 유다가 예수를 넘겨 주려고 대제사장들에게 가매'),
    (24794, '<제자들과 함께 유월절을 지키시다> ○무교절의 첫날 곧 유월절 양 잡는 날에 제자들이 예수께 여짜오되 우리가 어디로 가서 선생님께서 유월절 음식을 잡수시게 준비하기를 원하시나이까 하매'),
    (24799, '○저물매 그 열둘을 데리시고 가서'),
    (24804, '<마지막 만찬> ○그들이 먹을 때에 예수께서 떡을 가지사 축복하시고 떼어 제자들에게 주시며 이르시되 받으라 이것은 내 몸이니라 하시고'),
    (24808, '○이에 그들이 찬미하고 감람 산으로 가니라'),
    (24809, '<베드로가 부인할 것을 예언하시다> ○예수께서 제자들에게 이르시되 너희가 다 나를 버리리라 이는 기록된 바 내가 목자를 치리니 양들이 흩어지리라 하였음이니라'),
    (24814, '<겟세마네에서 기도하시다> ○그들이 겟세마네라 하는 곳에 이르매 예수께서 제자들에게 이르시되 내가 기도할 동안에 너희는 여기 앉아 있으라 하시고'),
    (24825, '<잡히시다> ○예수께서 말씀하실 때에 곧 열둘 중의 하나인 유다가 왔는데 대제사장들과 서기관들과 장로들에게서 파송된 무리가 검과 몽치를 가지고 그와 함께 하였더라'),
    (24833, '<한 청년이 벗은 몸으로 도망하다> ○한 청년이 벗은 몸에 베 홑이불을 두르고 예수를 따라가다가 무리에게 잡히매'),
    (24835, '<공회 앞에 서시다> ○그들이 예수를 끌고 대제사장에게로 가니 대제사장들과 장로들과 서기관들이 다 모이더라'),
    (24848, '<베드로가 예수를 알지 못한다고 하다> ○베드로는 아랫뜰에 있더니 대제사장의 여종 하나가 와서'),
    (24850, '베드로가 부인하여 이르되 나는 네가 말하는 것이 무엇인지 알지도 못하고 깨닫지도 못하겠노라 하며 앞뜰로 나갈새'),
    (24902, '<살아나시다> 안식일이 지나매 막달라 마리아와 야고보의 어머니 마리아와 또 살로메가 가서 예수께 바르기 위하여 향품을 사다 두었다가'),
    (24910, '<막달라 마리아에게 보이시다> [예수께서 안식 후 첫날 이른 아침에 살아나신 후 전에 일곱 귀신을 쫓아내어 주신 막달라 마리아에게 먼저 보이시니'),
    (24913, '<두 제자에게 나타나시다> ○그 후에 그들 중 두 사람이 걸어서 시골로 갈 때에 예수께서 다른 모양으로 그들에게 나타나시니'),
    (24915, '<만민에게 복음을 전파하라> ○그 후에 열한 제자가 음식 먹을 때에 예수께서 그들에게 나타나사 그들의 믿음 없는 것과 마음이 완악한 것을 꾸짖으시니 이는 자기가 살아난 것을 본 자들의 말을 믿지 아니함일러라'),
    (24920, '<하늘로 올려지시다> ○주 예수께서 말씀을 마치신 후에 하늘로 올려지사 하나님 우편에 앉으시니라'),
    (25054, '<세례 요한의 전파> 디베료 황제가 통치한 지 열다섯 해 곧 본디오 빌라도가 유대의 총독으로, 헤롯이 갈릴리의 분봉 왕으로, 그 동생 빌립이 이두래와 드라고닛 지방의 분봉 왕으로, 루사니아가 아빌레네의 분봉 왕으로,'),
    (25060, '○요한이 세례 받으러 나아오는 무리에게 이르되 독사의 자식들아 누가 너희에게 일러 장차 올 진노를 피하라 하더냐'),
    (25068, '○백성들이 바라고 기다리므로 모든 사람들이 요한을 혹 그리스도신가 심중에 생각하니'),
    (25069, '요한이 모든 사람에게 대답하여 이르되 나는 물로 너희에게 세례를 베풀거니와 나보다 능력이 많으신 이가 오시나니 나는 그의 신발끈을 풀기도 감당하지 못하겠노라 그는 성령과 불로 너희에게 세례를 베푸실 것이요'),
    (25071, '○또 그밖에 여러 가지로 권하여 백성에게 좋은 소식을 전하였으나'),
    (25074, '<세례를 받으시다> ○백성이 다 세례를 받을새 예수도 세례를 받으시고 기도하실 때에 하늘이 열리며'),
    (25076, '<예수의 족보> ○예수께서 가르치심을 시작하실 때에 삼십 세쯤 되시니라 사람들이 아는 대로는 요셉의 아들이니 요셉의 위는 헬리요'),
    (25092, '<시험을 받으시다> 예수께서 성령의 충만함을 입어 요단 강에서 돌아오사 광야에서 사십 일 동안 성령에게 이끌리시며'),
    (25105, '<갈릴리 여러 회당에서 가르치시다> ○예수께서 성령의 능력으로 갈릴리에 돌아가시니 그 소문이 사방에 퍼졌고'),
    (25107, '<나사렛에서 배척을 받으시다> ○예수께서 그 자라나신 곳 나사렛에 이르사 안식일에 늘 하시던 대로 회당에 들어가사 성경을 읽으려고 서시매'),
    (25109, '주의 성령이 내게 임하셨으니 이는 가난한 자에게 복음을 전하게 하시려고 내게 기름을 부으시고 나를 보내사 포로 된 자에게 자유를, 눈 먼 자에게 다시 보게 함을 전파하며 눌린 자를 자유롭게 하고'),
    (25119, '회당에 있는 자들이 이것을 듣고 다 크게 화가 나서'),
    (25122, '<더러운 귀신 들린 사람을 고치시다> ○갈릴리의 가버나움 동네에 내려오사 안식일에 가르치시매'),
    (25129, '<온갖 병자들을 고치시다> ○예수께서 일어나 회당에서 나가사 시몬의 집에 들어가시니 시몬의 장모가 중한 열병을 앓고 있는지라 사람들이 그를 위하여 예수께 구하니'),
    (25131, '○해 질 무렵에 사람들이 온갖 병자들을 데리고 나아오매 예수께서 일일이 그 위에 손을 얹으사 고치시니'),
    (25133, '<복음을 전하러 떠나시다> ○날이 밝으매 예수께서 나오사 한적한 곳에 가시니 무리가 찾다가 만나서 자기들에게서 떠나시지 못하게 만류하려 하매'),
    (25136, '<어부들이 예수를 따르다> 무리가 몰려와서 하나님의 말씀을 들을새 예수는 게네사렛 호숫가에 서서'),
    (25147, '<나병 들린 사람을 깨끗하게 하시다> ○예수께서 한 동네에 계실 때에 온 몸에 나병 들린 사람이 있어 예수를 보고 엎드려 구하여 이르되 주여 원하시면 나를 깨끗하게 하실 수 있나이다 하니'),
    (25152, '<중풍병자를 고치시다> ○하루는 가르치실 때에 갈릴리의 각 마을과 유대와 예루살렘에서 온 바리새인과 율법교사들이 앉았는데 병을 고치는 주의 능력이 예수와 함께 하더라'),
    (25162, '<레위가 예수를 따르다> ○그 후에 예수께서 나가사 레위라 하는 세리가 세관에 앉아 있는 것을 보시고 나를 따르라 하시니'),
    (24926, '<세례 요한의 출생을 예고하다> ○유대 왕 헤롯 때에 아비야 반열에 제사장 한 사람이 있었으니 이름은 사가랴요 그의 아내는 아론의 자손이니 이름은 엘리사벳이라'),
    (24929, '○마침 사가랴가 그 반열의 차례대로 하나님 앞에서 제사장의 직무를 행할새'),
    (24945, '○이 후에 그의 아내 엘리사벳이 잉태하고 다섯 달 동안 숨어 있으며 이르되'),
    (24947, '<예수의 나심을 예고하다> ○여섯째 달에 천사 가브리엘이 하나님의 보내심을 받아 갈릴리 나사렛이란 동네에 가서'),
    (24960, '<마리아가 엘리사벳을 방문하다> ○이 때에 마리아가 일어나 빨리 산골로 가서 유대 한 동네에 이르러'),
    (24978, '<세례 요한의 출생> ○엘리사벳이 해산할 기한이 차서 아들을 낳으니'),
    (24988, '<사가랴의 예언> ○그 부친 사가랴가 성령의 충만함을 받아 예언하여 이르되'),
    (25224, '<백부장의 종을 고치시다> 예수께서 모든 말씀을 백성에게 들려 주시기를 마치신 후에 가버나움으로 들어가시니라'),
    (25225, '○어떤 백부장의 사랑하는 종이 병들어 죽게 되었더니'),
    (25234, '<과부의 아들을 살리시다> ○그 후에 예수께서 나인이란 성으로 가실새 제자와 많은 무리가 동행하더니'),
    (25241, '<세례 요한의 제자들에게 대답하시다> ○요한의 제자들이 이 모든 일을 그에게 알리니'),
    (25245, '예수께서 대답하여 이르시되 너희가 가서 보고 들은 것을 요한에게 알리되 맹인이 보며 못 걷는 사람이 걸으며 나병환자가 깨끗함을 받으며 귀먹은 사람이 들으며 죽은 자가 살아나며 가난한 자에게 복음이 전파된다 하라'),
    (25247, '○요한이 보낸 자가 떠난 후에 예수께서 무리에게 요한에 대하여 말씀하시되 너희가 무엇을 보려고 광야에 나갔더냐 바람에 흔들리는 갈대냐'),
    (25259, '<한 여자가 예수께 향유를 붓다> ○한 바리새인이 예수께 자기와 함께 잡수시기를 청하니 이에 바리새인의 집에 들어가 앉으셨을 때에'),
    (25175, '<안식일에 밀 이삭을 자르다> 안식일에 예수께서 밀밭 사이로 지나가실새 제자들이 이삭을 잘라 손으로 비비어 먹으니'),
    (25180, '<안식일에 손 마른 사람을 고치시다> ○또 다른 안식일에 예수께서 회당에 들어가사 가르치실새 거기 오른손 마른 사람이 있는지라'),
    (25186, '<열두 제자를 사도로 택하시다> ○이 때에 예수께서 기도하시러 산으로 가사 밤이 새도록 하나님께 기도하시고'),
    (25194, '<복과 화를 선포하시다> ○예수께서 눈을 들어 제자들을 보시고 이르시되 너희 가난한 자는 복이 있나니 하나님의 나라가 너희 것임이요'),
    (25201, '<원수를 사랑하라> ○그러나 너희 듣는 자에게 내가 이르노니 너희 원수를 사랑하며 너희를 미워하는 자를 선대하며'),
    (25209, '오직 너희는 원수를 사랑하고 선대하며 아무 것도 바라지 말고 꾸어 주라 그리하면 너희 상이 클 것이요 또 지극히 높으신 이의 아들이 되리니 그는 은혜를 모르는 자와 악한 자에게도 인자하시니라'),
    (25213, '<네 눈 속에 있는 들보> ○또 비유로 말씀하시되 맹인이 맹인을 인도할 수 있느냐 둘이 다 구덩이에 빠지지 아니하겠느냐'),
    (25216, '너는 네 눈 속에 있는 들보를 보지 못하면서 어찌하여 형제에게 말하기를 형제여 나로 네 눈 속에 있는 티를 빼게 하라 할 수 있느냐 외식하는 자여 먼저 네 눈 속에서 들보를 빼라 그 후에야 네가 밝히 보고 형제의 눈 속에 있는 티를 빼리라'),
    (25220, '<듣고 행하는 자와 행하지 아니하는 자> ○너희는 나를 불러 주여 주여 하면서도 어찌하여 내가 말하는 것을 행하지 아니하느냐'),
    (25002, '<예수의 나심> 그 때에 가이사 아구스도가 영을 내려 천하로 다 호적하라 하였으니'),
    (25009, '<목자들이 예수 탄생 소식을 듣다> ○그 지역에 목자들이 밤에 밖에서 자기 양 떼를 지키더니'),
    (25016, '○천사들이 떠나 하늘로 올라가니 목자가 서로 말하되 이제 베들레헴으로 가서 주께서 우리에게 알리신 바 이 이루어진 일을 보자 하고'),
    (25022, '○할례할 팔 일이 되매 그 이름을 예수라 하니 곧 잉태하기 전에 천사가 일컬은 바러라'),
    (25023, '<아기 예수의 정결예식> ○모세의 법대로 정결예식의 날이 차매 아기를 데리고 예루살렘에 올라가니'),
    (25041, '○아기가 자라며 강하여지고 지혜가 충만하며 하나님의 은혜가 그의 위에 있더라'),
    (25042, '<열두 살 시절의 예수> ○그의 부모가 해마다 유월절이 되면 예루살렘으로 가더니'),
    (25053, '○예수는 지혜와 키가 자라가며 하나님과 사람에게 더욱 사랑스러워 가시더라'),
    (25277, '<네 가지 땅에 떨어진 씨 비유> ○각 동네 사람들이 예수께로 나아와 큰 무리를 이루니 예수께서 비유로 말씀하시되'),
    (25282, '<비유를 설명하시다> ○제자들이 이 비유의 뜻을 물으니'),
    (25289, '<등불은 등경 위에> ○누구든지 등불을 켜서 그릇으로 덮거나 평상 아래에 두지 아니하고 등경 위에 두나니 이는 들어가는 자들로 그 빛을 보게 하려 함이라'),
    (25292, '<예수의 어머니와 동생들> ○예수의 어머니와 그 동생들이 왔으나 무리로 인하여 가까이 하지 못하니'),
    (25295, '<바람과 물결을 잔잔하게 하시다> ○하루는 제자들과 함께 배에 오르사 그들에게 이르시되 호수 저편으로 건너가자 하시매 이에 떠나'),
    (25299, '<귀신 들린 사람을 고치시다> ○그들이 갈릴리 맞은편 거라사인의 땅에 이르러'),
    (25302, '이는 예수께서 이미 더러운 귀신을 명하사 그 사람에게서 나오라 하셨음이라 (귀신이 가끔 그 사람을 붙잡으므로 그를 쇠사슬과 고랑에 매어 지켰으되 그 맨 것을 끊고 귀신에게 몰려 광야로 나갔더라)'),
    (25313, '<야이로의 딸과 예수의 옷에 손 댄 여자> ○예수께서 돌아오시매 무리가 환영하니 이는 다 기다렸음이러라'),
    (25315, '이는 자기에게 열두 살 된 외딸이 있어 죽어감이러라 ○예수께서 가실 때에 무리가 밀려들더라'),
    (25323, '○아직 말씀하실 때에 회당장의 집에서 사람이 와서 말하되 당신의 딸이 죽었나이다 선생님을 더 괴롭게 하지 마소서 하거늘'),
    (25490, '<바리새인들의 외식을 주의하라> 그 동안에 무리 수만 명이 모여 서로 밟힐 만큼 되었더니 예수께서 먼저 제자들에게 말씀하여 이르시되 바리새인들의 누룩 곧 외식을 주의하라'),
    (25502, '<한 부자 비유> ○무리 중에 한 사람이 이르되 선생님 내 형을 명하여 유산을 나와 나누게 하소서 하니'),
    (25511, '<목숨과 몸을 위하여 염려하지 말라> ○또 제자들에게 이르시되 그러므로 내가 너희에게 이르노니 너희 목숨을 위하여 무엇을 먹을까 몸을 위하여 무엇을 입을까 염려하지 말라'),
    (25524, '<깨어 준비하고 있으라> ○허리에 띠를 띠고 등불을 켜고 서 있으라'),
    (25530, '○베드로가 여짜오되 주께서 이 비유를 우리에게 하심이니이까 모든 사람에게 하심이니이까'),
    (25538, '<불을 던지러, 분쟁을 일으키러 왔다,> ○내가 불을 땅에 던지러 왔노니 이 불이 이미 붙었으면 내가 무엇을 원하리요'),
    (25541, '이 후부터 한 집에 다섯 사람이 있어 분쟁하되 셋이 둘과, 둘이 셋과 하리니'),
    (25543, '<시대를 분간하고, 화해하기를 힘쓰라,> ○또 무리에게 이르시되 너희가 구름이 서쪽에서 이는 것을 보면 곧 말하기를 소나기가 오리라 하나니 과연 그러하고'),
    (25394, '<칠십 인을 세워서 보내시다> 그 후에 주께서 따로 칠십 인을 세우사 친히 가시려는 각 동네와 각 지역으로 둘씩 앞서 보내시며'),
    (25410, '<칠십 인이 돌아오다> ○칠십 인이 기뻐하며 돌아와 이르되 주여 주의 이름이면 귀신들도 우리에게 항복하더이다'),
    (25414, '<예수의 감사 기도> ○그 때에 예수께서 성령으로 기뻐하시며 이르시되 천지의 주재이신 아버지여 이것을 지혜롭고 슬기 있는 자들에게는 숨기시고 어린 아이들에게는 나타내심을 감사하나이다 옳소이다 이렇게 된 것이 아버지의 뜻이니이다'),
    (25418, '<자비를 베푼 사마리아 사람> ○어떤 율법교사가 일어나 예수를 시험하여 이르되 선생님 내가 무엇을 하여야 영생을 얻으리이까'),
    (25431, '<마르다와 마리아> ○그들이 길 갈 때에 예수께서 한 마을에 들어가시매 마르다라 이름하는 한 여자가 자기 집으로 영접하더라'),
    (25331, '<열두 제자를 내보내시다> 예수께서 열두 제자를 불러 모으사 모든 귀신을 제어하며 병을 고치는 능력과 권위를 주시고'),
    (25337, '<헤롯이 듣고 심히 당황하다> ○분봉 왕 헤롯이 이 모든 일을 듣고 심히 당황하니 이는 어떤 사람은 요한이 죽은 자 가운데서 살아났다고도 하며'),
    (25340, '<오천 명을 먹이시다> ○사도들이 돌아와 자기들이 행한 모든 것을 예수께 여쭈니 데리시고 따로 벳새다라는 고을로 떠나 가셨으나'),
    (25348, '<베드로의 고백, 죽음과 부활 예고,> ○예수께서 따로 기도하실 때에 제자들이 주와 함께 있더니 물어 이르시되 무리가 나를 누구라고 하느냐'),
    (25358, '<영광스러운 모습으로 변화되시다> ○이 말씀을 하신 후 팔 일쯤 되어 예수께서 베드로와 요한과 야고보를 데리고 기도하시러 산에 올라가사'),
    (25363, '두 사람이 떠날 때에 베드로가 예수께 여짜오되 주여 우리가 여기 있는 것이 좋사오니 우리가 초막 셋을 짓되 하나는 주를 위하여, 하나는 모세를 위하여, 하나는 엘리야를 위하여 하사이다 하되 자기가 하는 말을 자기도 알지 못하더라'),
    (25367, '<귀신 들린 아이를 낫게 하시다> ○이튿날 산에서 내려오시니 큰 무리가 맞을새'),
    (25373, '<인자가 사람들의 손에 넘겨지리라> 사람들이 다 하나님의 위엄에 놀라니라 ○그들이 다 그 행하시는 모든 일을 놀랍게 여길새 예수께서 제자들에게 이르시되'),
    (25377, '<누가 크냐> ○제자 중에서 누가 크냐 하는 변론이 일어나니'),
    (25379, '그들에게 이르시되 누구든지 내 이름으로 이런 어린 아이를 영접하면 곧 나를 영접함이요 또 누구든지 나를 영접하면 곧 나를 보내신 이를 영접함이라 너희 모든 사람 중에 가장 작은 그가 큰 자니라'),
    (25380, '<너희를 위하는 사람> ○요한이 여짜오되 주여 어떤 사람이 주의 이름으로 귀신을 내쫓는 것을 우리가 보고 우리와 함께 따르지 아니하므로 금하였나이다'),
    (25382, '<사마리아의 마을에서 예수를 받아들이지 않다> ○예수께서 승천하실 기약이 차가매 예루살렘을 향하여 올라가기로 굳게 결심하시고'),
    (25386, '예수께서 돌아보시며 꾸짖으시고'),
    (25388, '<나를 따르라> ○길 가실 때에 어떤 사람이 여짜오되 어디로 가시든지 나는 따르리이다'),
    (25436, '<기도를 가르치시다> 예수께서 한 곳에서 기도하시고 마치시매 제자 중 하나가 여짜오되 주여 요한이 자기 제자들에게 기도를 가르친 것과 같이 우리에게도 가르쳐 주옵소서'),
    (25440, '○또 이르시되 너희 중에 누가 벗이 있는데 밤중에 그에게 가서 말하기를 벗이여 떡 세 덩이를 내게 꾸어 달라'),
    (25449, '<예수와 바알세불> ○예수께서 한 말 못하게 하는 귀신을 쫓아내시니 귀신이 나가매 말 못하는 사람이 말하는지라 무리들이 놀랍게 여겼으나'),
    (25462, '<복이 있는 자> ○이 말씀을 하실 때에 무리 중에서 한 여자가 음성을 높여 이르되 당신을 밴 태와 당신을 먹인 젖이 복이 있나이다 하니'),
    (25464, '<악한 세대가 표적을 구하나> ○무리가 모였을 때에 예수께서 말씀하시되 이 세대는 악한 세대라 표적을 구하되 요나의 표적 밖에는 보일 표적이 없나니'),
    (25468, '<눈은 몸의 등불> ○누구든지 등불을 켜서 움 속에나 말 아래에 두지 아니하고 등경 위에 두나니 이는 들어가는 자로 그 빛을 보게 하려 함이라'),
    (25472, '<바리새인과 율법교사> ○예수께서 말씀하실 때에 한 바리새인이 자기와 함께 점심 잡수시기를 청하므로 들어가 앉으셨더니'),
    (25477, '○화 있을진저 너희 바리새인이여 너희가 박하와 운향과 모든 채소의 십일조는 드리되 공의와 하나님께 대한 사랑은 버리는도다 그러나 이것도 행하고 저것도 버리지 말아야 할지니라'),
    (25480, '○한 율법교사가 예수께 대답하여 이르되 선생님 이렇게 말씀하시니 우리까지 모욕하심이니이다'),
    (25488, '○거기서 나오실 때에 서기관과 바리새인들이 거세게 달려들어 여러 가지 일을 따져 묻고'),
    (25554, '<열매 맺지 못하는 무화과나무 비유> ○이에 비유로 말씀하시되 한 사람이 포도원에 무화과나무를 심은 것이 있더니 와서 그 열매를 구하였으나 얻지 못한지라'),
    (25557, '이 후에 만일 열매가 열면 좋거니와 그렇지 않으면 찍어버리소서 하였다 하시니라'),
    (25558, '<안식일에 꼬부라진 여자를 고치시다> ○예수께서 안식일에 한 회당에서 가르치실 때에'),
    (25566, '<겨자씨와 누룩 비유> ○그러므로 예수께서 이르시되 하나님의 나라가 무엇과 같을까 내가 무엇으로 비교할까'),
    (25570, '<좁은 문으로 들어가기를 힘쓰라> ○예수께서 각 성 각 마을로 다니사 가르치시며 예루살렘으로 여행하시더니'),
    (25574, '그 때에 너희가 말하되 우리는 주 앞에서 먹고 마셨으며 주는 또한 우리의 길거리에서 가르치셨나이다 하나'),
    (25579, '<선지자들을 죽이는 예루살렘아> ○곧 그 때에 어떤 바리새인들이 나아와서 이르되 나가서 여기를 떠나소서 헤롯이 당신을 죽이고자 하나이다'),
    (25582, '예루살렘아 예루살렘아 선지자들을 죽이고 네게 파송된 자들을 돌로 치는 자여 암탉이 제 새끼를 날개 아래에 모음 같이 내가 너희의 자녀를 모으려 한 일이 몇 번이냐 그러나 너희가 원하지 아니하였도다'),
    (25590, '<끝자리에 앉으라> ○청함을 받은 사람들이 높은 자리 택함을 보시고 그들에게 비유로 말씀하여 이르시되'),
    (25595, '○또 자기를 청한 자에게 이르시되 네가 점심이나 저녁이나 베풀거든 벗이나 형제나 친척이나 부한 이웃을 청하지 말라 두렵건대 그 사람들이 너를 도로 청하여 네게 갚음이 될까 하노라'),
    (25598, '<큰 잔치 비유> ○함께 먹는 사람 중의 하나가 이 말을 듣고 이르되 무릇 하나님의 나라에서 떡을 먹는 자는 복되도다 하니'),
    (25608, '<제자가 되는 길> ○수많은 무리가 함께 갈새 예수께서 돌이키사 이르시되'),
    (25619, '<잃은 양을 찾은 목자 비유> 모든 세리와 죄인들이 말씀을 들으러 가까이 나아오니'),
    (25621, '○예수께서 그들에게 이 비유로 이르시되'),
    (25626, '<잃은 드라크마를 찾은 여인 비유> ○어떤 여자가 열 드라크마가 있는데 하나를 잃으면 등불을 켜고 집을 쓸며 찾아내기까지 부지런히 찾지 아니하겠느냐'),
    (25629, '<잃은 아들을 되찾은 아버지 비유> ○또 이르시되 어떤 사람에게 두 아들이 있는데'),
    (25664, '<율법과 하나님 나라의 복음> ○바리새인들은 돈을 좋아하는 자들이라 이 모든 것을 듣고 비웃거늘'),
    (25669, '<부자와 거지> ○한 부자가 있어 자색 옷과 고운 베옷을 입고 날마다 호화롭게 즐기더라'),
    (25682, '<용서, 믿음, 종이 할 일> 예수께서 제자들에게 이르시되 실족하게 하는 것이 없을 수는 없으나 그렇게 하게 하는 자에게는 화로다'),
    (25686, '○사도들이 주께 여짜오되 우리에게 믿음을 더하소서 하니'),
    (25692, '<나병환자 열 명이 깨끗함을 받다> ○예수께서 예루살렘으로 가실 때에 사마리아와 갈릴리 사이로 지나가시다가'),
    (25701, '<하나님의 나라는 너희 안에 있다> ○바리새인들이 하나님의 나라가 어느 때에 임하나이까 묻거늘 예수께서 대답하여 이르시되 하나님의 나라는 볼 수 있게 임하는 것이 아니요'),
    (25703, '○또 제자들에게 이르시되 때가 이르리니 너희가 인자의 날 하루를 보고자 하되 보지 못하리라'),
    (25772, '<은 열 므나 비유> ○그들이 이 말씀을 듣고 있을 때에 비유를 더하여 말씀하시니 이는 자기가 예루살렘에 가까이 오셨고 그들은 하나님의 나라가 당장에 나타날 줄로 생각함이더라'),
    (25789, '<예루살렘을 향하여 가시다> ○예수께서 이 말씀을 하시고 예루살렘을 향하여 앞서서 가시더라'),
    (25802, '○가까이 오사 성을 보시고 우시며'),
    (25805, '또 너와 및 그 가운데 있는 네 자식들을 땅에 메어치며 돌 하나도 돌 위에 남기지 아니하리니 이는 네가 보살핌 받는 날을 알지 못함을 인함이니라 하시니라'),
    (25806, '<성전에 들어가신 예수> ○성전에 들어가사 장사하는 자들을 내쫓으시며'),
    (25808, '○예수께서 날마다 성전에서 가르치시니 대제사장들과 서기관들과 백성의 지도자들이 그를 죽이려고 꾀하되'),
    (25857, '<가난한 과부의 헌금> 예수께서 눈을 들어 부자들이 헌금함에 헌금 넣는 것을 보시고'),
    (25861, '<성전이 무너뜨려질 것을 이르시다> ○어떤 사람들이 성전을 가리켜 그 아름다운 돌과 헌물로 꾸민 것을 말하매 예수께서 이르시되'),
    (25866, '<환난의 징조> ○또 이르시되 민족이 민족을, 나라가 나라를 대적하여 일어나겠고'),
    (25876, '<예루살렘의 환난과 인자의 오심> ○너희가 예루살렘이 군대들에게 에워싸이는 것을 보거든 그 멸망이 가까운 줄을 알라'),
    (25885, '<무화과나무에서 배울 교훈> ○이에 비유로 이르시되 무화과나무와 모든 나무를 보라'),
    (25890, '<항상 기도하며 깨어 있으라> ○너희는 스스로 조심하라 그렇지 않으면 방탕함과 술취함과 생활의 염려로 마음이 둔하여지고 뜻밖에 그 날이 덫과 같이 너희에게 임하리라'),
    (25893, '○예수께서 낮에는 성전에서 가르치시고 밤에는 나가 감람원이라 하는 산에서 쉬시니'),
    (25727, '<바리새인과 세리 비유> ○또 자기를 의롭다고 믿고 다른 사람을 멸시하는 자들에게 이 비유로 말씀하시되'),
    (25733, '<어린 아이들을 금하지 말라> ○사람들이 예수께서 만져 주심을 바라고 자기 어린 아기를 데리고 오매 제자들이 보고 꾸짖거늘'),
    (25736, '<부자 관리> ○어떤 관리가 물어 이르되 선한 선생님이여 내가 무엇을 하여야 영생을 얻으리이까'),
    (25740, '예수께서 이 말을 들으시고 이르시되 네게 아직도 한 가지 부족한 것이 있으니 네게 있는 것을 다 팔아 가난한 자들에게 나눠 주라 그리하면 하늘에서 네게 보화가 있으리라 그리고 와서 나를 따르라 하시니'),
    (25749, '<죽음과 부활을 다시 이르시다> ○예수께서 열두 제자를 데리시고 이르시되 보라 우리가 예루살렘으로 올라가노니 선지자들을 통하여 기록된 모든 것이 인자에게 응하리라'),
    (25753, '<맹인을 고치시다> ○여리고에 가까이 가셨을 때에 한 맹인이 길 가에 앉아 구걸하다가'),
    (25810, '<예수의 권위를 두고 말하다> 하루는 예수께서 성전에서 백성을 가르치시며 복음을 전하실새 대제사장들과 서기관들이 장로들과 함께 가까이 와서'),
    (25818, '<포도원 농부 비유> ○그가 또 이 비유로 백성에게 말씀하시기 시작하시니라 한 사람이 포도원을 만들어 농부들에게 세로 주고 타국에 가서 오래 있다가'),
    (25828, '<가이사에게 세를 바치는 것> ○서기관들과 대제사장들이 예수의 이 비유는 자기들을 가리켜 말씀하심인 줄 알고 즉시 잡고자 하되 백성을 두려워하더라'),
    (25836, '<부활 논쟁> ○부활이 없다고 주장하는 사두개인 중 어떤 이들이 와서'),
    (25850, '<그리스도와 다윗의 자손> ○예수께서 그들에게 이르시되 사람들이 어찌하여 그리스도를 다윗의 자손이라 하느냐'),
    (25851, '시편에 다윗이 친히 말하였으되 주께서 내 주께 이르시되'),
    (25854, '<서기관들을 삼가라> ○모든 백성이 들을 때에 예수께서 그 제자들에게 이르시되'),
    (25966, '<빌라도가 예수께 묻다> 무리가 다 일어나 예수를 빌라도에게 끌고 가서'),
    (25973, '<헤롯 앞에 서시다> ○헤롯이 예수를 보고 매우 기뻐하니 이는 그의 소문을 들었으므로 보고자 한 지 오래였고 또한 무엇이나 이적 행하심을 볼까 바랐던 연고러라'),
    (25978, '<십자가에 못 박히게 예수를 넘기다> ○빌라도가 대제사장들과 관리들과 백성을 불러 모으고'),
    (25991, '<십자가에 못 박히시다> ○그들이 예수를 끌고 갈 때에 시몬이라는 구레네 사람이 시골에서 오는 것을 붙들어 그에게 십자가를 지워 예수를 따르게 하더라'),
    (26004, '○달린 행악자 중 하나는 비방하여 이르되 네가 그리스도가 아니냐 너와 우리를 구원하라 하되'),
    (26009, '<숨지시다> ○때가 제육시쯤 되어 해가 빛을 잃고 온 땅에 어둠이 임하여 제구시까지 계속하며'),
    (26015, '<요셉이 예수의 시체를 무덤에 넣어 두다> ○공회 의원으로 선하고 의로운 요셉이라 하는 사람이 있으니'),
    (26021, '<살아나시다> 돌아가 향품과 향유를 준비하더라 ○계명을 따라 안식일에 쉬더라'),
    (25895, '<유다가 배반하다> 유월절이라 하는 무교절이 다가오매'),
    (25897, '○열둘 중의 하나인 가룟인이라 부르는 유다에게 사탄이 들어가니'),
    (25901, '<유월절을 준비하다> ○유월절 양을 잡을 무교절날이 이른지라'),
    (25908, '<마지막 만찬> ○때가 이르매 예수께서 사도들과 함께 앉으사'),
    (25918, '<베드로가 부인할 것을 이르시다> ○또 그들 사이에 그 중 누가 크냐 하는 다툼이 난지라'),
    (25929, '<전대와 배낭과 검> ○그들에게 이르시되 내가 너희를 전대와 배낭과 신발도 없이 보내었을 때에 부족한 것이 있더냐 이르되 없었나이다'),
    (25933, '<감람 산에서 기도하시다> ○예수께서 나가사 습관을 따라 감람 산에 가시매 제자들도 따라갔더니'),
    (25941, '<잡히시다> ○말씀하실 때에 한 무리가 오는데 열둘 중의 하나인 유다라 하는 자가 그들을 앞장서 와서'),
    (25948, '<베드로가 예수를 모른다고 하다> ○예수를 잡아 끌고 대제사장의 집으로 들어갈새 베드로가 멀찍이 따라가니라'),
    (25957, '<예수를 희롱하고 때리다> ○지키는 사람들이 예수를 희롱하고 때리며'),
    (25960, '<공회 앞에 서시다> ○날이 새매 백성의 장로들 곧 대제사장들과 서기관들이 모여서 예수를 그 공회로 끌어들여'),
    (26167, '○하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 그를 믿는 자마다 멸망하지 않고 영생을 얻게 하려 하심이라'),
    (26173, '<그는 흥하고 나는 쇠하여야 하리라> ○그 후에 예수께서 제자들과 유대 땅으로 가서 거기 함께 유하시며 세례를 베푸시더라'),
    (26182, '<하늘로부터 오시는 이> ○위로부터 오시는 이는 만물 위에 계시고 땅에서 난 이는 땅에 속하여 땅에 속한 것을 말하느니라 하늘로부터 오시는 이는 만물 위에 계시나니'),
    (26094, '<세례 요한의 증언> ○유대인들이 예루살렘에서 제사장들과 레위인들을 요한에게 보내어 네가 누구냐 물을 때에 요한의 증언이 이러하니라'),
    (26104, '<하나님의 어린 양을 보라> ○이튿날 요한이 예수께서 자기에게 나아오심을 보고 이르되 보라 세상 죄를 지고 가는 하나님의 어린 양이로다'),
    (26108, '나도 그를 알지 못하였으나 나를 보내어 물로 세례를 베풀라 하신 그이가 나에게 말씀하시되 성령이 내려서 누구 위에든지 머무는 것을 보거든 그가 곧 성령으로 세례를 베푸는 이인 줄 알라 하셨기에'),
    (26110, '<요한의 두 제자> ○또 이튿날 요한이 자기 제자 중 두 사람과 함께 섰다가'),
    (26118, '<빌립과 나다나엘을 부르시다> ○이튿날 예수께서 갈릴리로 나가려 하시다가 빌립을 만나 이르시되 나를 따르라 하시니'),
    (26035, '<엠마오 길에서 제자들에게 나타나시다> ○그 날에 그들 중 둘이 예루살렘에서 이십오 리 되는 엠마오라 하는 마을로 가면서'),
    (26058, '<열한 제자에게 나타나시다> ○이 말을 할 때에 예수께서 친히 그들 가운데 서서 이르시되 너희에게 평강이 있을지어다 하시니'),
    (26066, '○또 이르시되 내가 너희와 함께 있을 때에 너희에게 말한 바 곧 모세의 율법과 선지자의 글과 시편에 나를 가리켜 기록된 모든 것이 이루어져야 하리라 한 말이 이것이라 하시고'),
    (26072, '<하늘로 올려지시다> ○예수께서 그들을 데리고 베다니 앞까지 나가사 손을 들어 그들에게 축복하시더니'),
    (26138, '○그 후에 예수께서 그 어머니와 형제들과 제자들과 함께 가버나움으로 내려가셨으나 거기에 여러 날 계시지는 아니하시니라'),
    (26139, '<성전을 깨끗하게 하시다> ○유대인의 유월절이 가까운지라 예수께서 예루살렘으로 올라가셨더니'),
    (26149, '<예수는 사람의 마음속을 아신다> ○유월절에 예수께서 예루살렘에 계시니 많은 사람이 그의 행하시는 표적을 보고 그의 이름을 믿었으나'),
    (26214, '○이 때에 제자들이 돌아와서 예수께서 여자와 말씀하시는 것을 이상히 여겼으나 무엇을 구하시나이까 어찌하여 그와 말씀하시나이까 묻는 자가 없더라'),
    (26226, '○여자의 말이 내가 행한 모든 것을 그가 내게 말하였다 증언하므로 그 동네 중에 많은 사마리아인이 예수를 믿는지라'),
    (26230, '<왕의 신하의 아들을 고치시다> ○이틀이 지나매 예수께서 거기를 떠나 갈릴리로 가시며'),
    (26233, '○예수께서 다시 갈릴리 가나에 이르시니 전에 물로 포도주를 만드신 곳이라 왕의 신하가 있어 그의 아들이 가버나움에서 병들었더니'),
    (26243, '○예루살렘에 있는 양문 곁에 히브리 말로 베데스다라 하는 못이 있는데 거기 행각 다섯이 있고'),
    (26250, '그 사람이 곧 나아서 자리를 들고 걸어가니라 ○이 날은 안식일이니'),
    (26261, '<아들의 권한> ○그러므로 예수께서 그들에게 이르시되 내가 진실로 진실로 너희에게 이르노니 아들이 아버지께서 하시는 일을 보지 않고는 아무 것도 스스로 할 수 없나니 아버지께서 행하시는 그것을 아들도 그와 같이 행하느니라'),
    (26272, '<예수를 믿게 하는 증언> ○내가 아무 것도 스스로 할 수 없노라 듣는 대로 심판하노니 나는 나의 뜻대로 하려 하지 않고 나를 보내신 이의 뜻대로 하려 하므로 내 심판은 의로우니라'),
    (26485, '<보게 된 맹인과 바리새인들> ○그들이 전에 맹인이었던 사람을 데리고 바리새인들에게 갔더라'),
    (26488, '바리새인 중에 어떤 사람은 말하되 이 사람이 안식일을 지키지 아니하니 하나님께로부터 온 자가 아니라 하며 어떤 사람은 말하되 죄인으로서 어떻게 이러한 표적을 행하겠느냐 하여 그들 중에 분쟁이 있었더니'),
    (26507, '<맹인이 되었더라면 죄가 없으려니와> ○예수께서 그들이 그 사람을 쫓아냈다 하는 말을 들으셨더니 그를 만나사 이르시되 네가 인자를 믿느냐'),
    (26520, '<선한 목자> ○그러므로 예수께서 다시 이르시되 내가 진실로 진실로 너희에게 말하노니 나는 양의 문이라'),
    (26532, '○이 말씀으로 말미암아 유대인 중에 다시 분쟁이 일어나니'),
    (26535, '<유대인들이 예수를 돌로 치려 하다> ○예루살렘에 수전절이 이르니 때는 겨울이라'),
    (26553, '○다시 요단 강 저편 요한이 처음으로 세례 베풀던 곳에 가사 거기 거하시니'),
    (26370, '<명절을 지키러 올라가시다> ○그 형제들이 명절에 올라간 후에 자기도 올라가시되 나타내지 않고 은밀히 가시니라'),
    (26371, '명절 중에 유대인들이 예수를 찾으면서 그가 어디 있느냐 하고'),
    (26374, '○이미 명절의 중간이 되어 예수께서 성전에 올라가사 가르치시니'),
    (26385, '<예수를 잡고자 하나> ○예루살렘 사람 중에서 어떤 사람이 말하되 이는 그들이 죽이고자 하는 그 사람이 아니냐'),
    (26397, '<배에서 생수의 강이 흘러나오리라> ○명절 끝날 곧 큰 날에 예수께서 서서 외쳐 이르시되 누구든지 목마르거든 내게로 와서 마시라'),
    (26405, '<대제사장들과 바리새인들은 믿지 않다> ○아랫사람들이 대제사장들과 바리새인들에게로 오니 그들이 묻되 어찌하여 잡아오지 아니하였느냐'),
    (26425, '<나는 세상의 빛> ○예수께서 또 말씀하여 이르시되 나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라'),
    (26434, '<내가 가는 곳> ○다시 이르시되 내가 가리니 너희가 나를 찾다가 너희 죄 가운데서 죽겠고 내가 가는 곳에는 너희가 오지 못하리라'),
    (26444, '<진리가 너희를 자유롭게 하리라> ○그러므로 예수께서 자기를 믿은 유대인들에게 이르시되 너희가 내 말에 거하면 참으로 내 제자가 되고'),
    (26457, '너희는 너희 아비 마귀에게서 났으니 너희 아비의 욕심대로 너희도 행하고자 하느니라 그는 처음부터 살인한 자요 진리가 그 속에 없으므로 진리에 서지 못하고 거짓을 말할 때마다 제 것으로 말하나니 이는 그가 거짓말쟁이요 거짓의 아비가 되었음이라'),
    (26290, '<오천 명을 먹이시다> 그 후에 예수께서 디베랴의 갈릴리 바다 건너편으로 가시매'),
    (26305, '<바다 위로 걸어오시다> ○저물매 제자들이 바다에 내려가서'),
    (26311, '<생명의 떡> ○이튿날 바다 건너편에 서 있던 무리가 배 한 척 외에 다른 배가 거기 없는 것과 또 어제 예수께서 제자들과 함께 그 배에 오르지 아니하시고 제자들만 가는 것을 보았더니'),
    (26330, '○자기가 하늘에서 내려온 떡이라 하시므로 유대인들이 예수에 대하여 수군거려'),
    (26341, '○그러므로 유대인들이 서로 다투어 이르되 이 사람이 어찌 능히 자기 살을 우리에게 주어 먹게 하겠느냐'),
    (26349, '<영생의 말씀> ○제자 중 여럿이 듣고 말하되 이 말씀은 어렵도다 누가 들을 수 있느냐 한대'),
    (26355, '○그 때부터 그의 제자 중에서 많은 사람이 떠나가고 다시 그와 함께 다니지 아니하더라'),
    (26572, '<나는 부활이요 생명이니> ○예수께서 와서 보시니 나사로가 무덤에 있은 지 이미 나흘이라'),
    (26600, '<예수를 죽이려고 모의하다> ○마리아에게 와서 예수께서 하신 일을 본 많은 유대인이 그를 믿었으나'),
    (26602, '○이에 대제사장들과 바리새인들이 공회를 모으고 이르되 이 사람이 많은 표적을 행하니 우리가 어떻게 하겠느냐'),
    (26609, '○그러므로 예수께서 다시 유대인 가운데 드러나게 다니지 아니하시고 거기를 떠나 빈 들 가까운 곳인 에브라임이라는 동네에 가서 제자들과 함께 거기 머무르시니라'),
    (26670, '예수께서 대답하여 이르시되 내가 하는 것을 네가 지금은 알지 못하나 이 후에는 알리라'),
    (26675, '○그들의 발을 씻으신 후에 옷을 입으시고 다시 앉아 그들에게 이르시되 내가 너희에게 행한 것을 너희가 아느냐'),
    (26684, '<너희 중 하나가 나를 팔리라> ○예수께서 이 말씀을 하시고 심령이 괴로워 증언하여 이르시되 내가 진실로 진실로 너희에게 이르노니 너희 중 하나가 나를 팔리라 하시니'),
    (26694, '<새 계명> ○그가 나간 후에 예수께서 이르시되 지금 인자가 영광을 받았고 하나님도 인자로 말미암아 영광을 받으셨도다'),
    (26699, '<베드로가 부인할 것을 이르시다> ○시몬 베드로가 이르되 주여 어디로 가시나이까 예수께서 대답하시되 내가 가는 곳에 네가 지금은 따라올 수 없으나 후에는 따라오리라'),
    (26726, '<보혜사> ○내가 아직 너희와 함께 있어서 이 말을 너희에게 하였거니와'),
    (26731, '이 후에는 내가 너희와 말을 많이 하지 아니하리니 이 세상의 임금이 오겠음이라 그러나 그는 내게 관계할 것이 없으니'),
    (26784, '<내가 세상을 이기었다> ○이것을 비유로 너희에게 일렀거니와 때가 이르면 다시는 비유로 너희에게 이르지 않고 아버지에 대한 것을 밝히 이르리라'),
    (26803, '나는 세상에 더 있지 아니하오나 그들은 세상에 있사옵고 나는 아버지께로 가옵나니 거룩하신 아버지여 내게 주신 아버지의 이름으로 그들을 보전하사 우리와 같이 그들도 하나가 되게 하옵소서'),
    (26815, '곧 내가 그들 안에 있고 아버지께서 내 안에 계시어 그들로 온전함을 이루어 하나가 되게 하려 함은 아버지께서 나를 보내신 것과 또 나를 사랑하심 같이 그들도 사랑하신 것을 세상으로 알게 하려 함이로소이다'),
    (26613, '<예수의 발에 향유를 붓다> 유월절 엿새 전에 예수께서 베다니에 이르시니 이 곳은 예수께서 죽은 자 가운데서 살리신 나사로가 있는 곳이라'),
    (26621, '<나사로까지 죽이려고 모의하다> ○유대인의 큰 무리가 예수께서 여기 계신 줄을 알고 오니 이는 예수만 보기 위함이 아니요 죽은 자 가운데서 살리신 나사로도 보려 함이러라'),
    (26624, '<예루살렘으로 가시다> ○그 이튿날에는 명절에 온 큰 무리가 예수께서 예루살렘으로 오신다는 것을 듣고'),
    (26632, '<인자가 들려야 하리라> ○명절에 예배하러 올라온 사람 중에 헬라인 몇이 있는데'),
    (26648, '<그들이 예수를 믿지 아니하다> 너희에게 아직 빛이 있을 동안에 빛을 믿으라 그리하면 빛의 아들이 되리라 ○예수께서 이 말씀을 하시고 그들을 떠나가서 숨으시니라'),
    (26657, '<마지막 날과 심판> ○예수께서 외쳐 이르시되 나를 믿는 자는 나를 믿는 것이 아니요 나를 보내신 이를 믿는 것이며'),
    (26902, '<살아나시다> 안식 후 첫날 일찍이 아직 어두울 때에 막달라 마리아가 무덤에 와서 돌이 무덤에서 옮겨진 것을 보고'),
    (26912, '<막달라 마리아에게 나타나시다> ○마리아는 무덤 밖에 서서 울고 있더니 울면서 구부려 무덤 안을 들여다보니'),
    (26918, '예수께서 이르시되 나를 붙들지 말라 내가 아직 아버지께로 올라가지 아니하였노라 너는 내 형제들에게 가서 이르되 내가 내 아버지 곧 너희 아버지, 내 하나님 곧 너희 하나님께로 올라간다 하라 하시니'),
    (26920, '<제자들에게 나타나시다> ○이 날 곧 안식 후 첫날 저녁 때에 제자들이 유대인들을 두려워하여 모인 곳의 문들을 닫았더니 예수께서 오사 가운데 서서 이르시되 너희에게 평강이 있을지어다'),
    (26925, '<도마가 의심하다> ○열두 제자 중의 하나로서 디두모라 불리는 도마는 예수께서 오셨을 때에 함께 있지 아니한지라'),
    (26926, '다른 제자들이 그에게 이르되 우리가 주를 보았노라 하니 도마가 이르되 내가 그의 손의 못 자국을 보며 내 손가락을 그 못 자국에 넣으며 내 손을 그 옆구리에 넣어 보지 않고는 믿지 아니하겠노라 하니라'),
    (26927, '○여드레를 지나서 제자들이 다시 집 안에 있을 때에 도마도 함께 있고 문들이 닫혔는데 예수께서 오사 가운데 서서 이르시되 너희에게 평강이 있을지어다 하시고'),
    (26931, '<이 책을 기록한 목적> ○예수께서 제자들 앞에서 이 책에 기록되지 아니한 다른 표적도 많이 행하셨으나'),
    (26947, '<내 양을 먹이라> ○그들이 조반 먹은 후에 예수께서 시몬 베드로에게 이르시되 요한의 아들 시몬아 네가 이 사람들보다 나를 더 사랑하느냐 하시니 이르되 주님 그러하나이다 내가 주님을 사랑하는 줄 주님께서 아시나이다 이르시되 내 어린 양을 먹이라 하시고'),
    (26949, '세 번째 이르시되 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 주께서 세 번째 네가 나를 사랑하느냐 하시므로 베드로가 근심하여 이르되 주님 모든 것을 아시오매 내가 주님을 사랑하는 줄을 주님께서 아시나이다 예수께서 이르시되 내 양을 먹이라'),
    (26955, '이 말씀이 형제들에게 나가서 그 제자는 죽지 아니하겠다 하였으나 예수의 말씀은 그가 죽지 않겠다 하신 것이 아니라 내가 올 때까지 그를 머물게 하고자 할지라도 네게 무슨 상관이냐 하신 것이러라'),
    (26956, '○이 일들을 증언하고 이 일들을 기록한 제자가 이 사람이라 우리는 그의 증언이 참된 줄 아노라'),
    (26957, '○예수께서 행하신 일이 이 외에도 많으니 만일 낱낱이 기록된다면 이 세상이라도 이 기록된 책을 두기에 부족할 줄 아노라'),
    (26865, '대제사장들과 아랫사람들이 예수를 보고 소리 질러 이르되 십자가에 못 박으소서 십자가에 못 박으소서 하는지라 빌라도가 이르되 너희가 친히 데려다가 십자가에 못 박으라 나는 그에게서 죄를 찾지 못하였노라'),
    (26874, '그들이 소리 지르되 없이 하소서 없이 하소서 그를 십자가에 못 박게 하소서 빌라도가 이르되 내가 너희 왕을 십자가에 못 박으랴 대제사장들이 대답하되 가이사 외에는 우리에게 왕이 없나이다 하니'),
    (26876, '<십자가에 못 박히시다> ○그들이 예수를 맡으매 예수께서 자기의 십자가를 지시고 해골(히브리 말로 골고다)이라 하는 곳에 나가시니'),
    (26882, '○군인들이 예수를 십자가에 못 박고 그의 옷을 취하여 네 깃에 나눠 각각 한 깃씩 얻고 속옷도 취하니 이 속옷은 호지 아니하고 위에서부터 통으로 짠 것이라'),
    (26887, '<영혼이 떠나가시다> ○그 후에 예수께서 모든 일이 이미 이루어진 줄 아시고 성경을 응하게 하려 하사 이르시되 내가 목마르다 하시니'),
    (26890, '<창으로 옆구리를 찌르다> ○이 날은 준비일이라 유대인들은 그 안식일이 큰 날이므로 그 안식일에 시체들을 십자가에 두지 아니하려 하여 빌라도에게 그들의 다리를 꺾어 시체를 치워 달라 하니'),
    (26897, '<새 무덤에 예수를 두다> ○아리마대 사람 요셉은 예수의 제자이나 유대인이 두려워 그것을 숨기더니 이 일 후에 빌라도에게 예수의 시체를 가져가기를 구하매 빌라도가 허락하는지라 이에 가서 예수의 시체를 가져가니라'),
    (26901, '이 날은 유대인의 준비일이요 또 무덤이 가까운 고로 예수를 거기 두니라'),
    (26819, '<잡히시다> 예수께서 이 말씀을 하시고 제자들과 함께 기드론 시내 건너편으로 나가시니 그 곳에 동산이 있는데 제자들과 함께 들어가시니라'),
    (26830, '<안나스에게로 끌고 가다> ○이에 군대와 천부장과 유대인의 아랫사람들이 예수를 잡아 결박하여'),
    (26833, '<베드로가 제자가 아니라고 하다> ○시몬 베드로와 또 다른 제자 한 사람이 예수를 따르니 이 제자는 대제사장과 아는 사람이라 예수와 함께 대제사장의 집 뜰에 들어가고'),
    (26837, '<대제사장이 예수에게 묻다> ○대제사장이 예수에게 그의 제자들과 그의 교훈에 대하여 물으니'),
    (26843, '<베드로가 다시 제자가 아니라고 하다> ○시몬 베드로가 서서 불을 쬐더니 사람들이 묻되 너도 그 제자 중 하나가 아니냐 베드로가 부인하여 이르되 나는 아니라 하니'),
    (26846, '<빌라도 앞에 서시다> ○그들이 예수를 가야바에게서 관정으로 끌고 가니 새벽이라 그들은 더럽힘을 받지 아니하고 유월절 잔치를 먹고자 하여 관정에 들어가지 아니하더라'),
    (26851, '○이에 빌라도가 다시 관정에 들어가 예수를 불러 이르되 네가 유대인의 왕이냐'),
    (26854, '예수께서 대답하시되 내 나라는 이 세상에 속한 것이 아니니라 만일 내 나라가 이 세상에 속한 것이었더라면 내 종들이 싸워 나로 유대인들에게 넘겨지지 않게 하였으리라 이제 내 나라는 여기에 속한 것이 아니니라'),
    (26855, '빌라도가 이르되 그러면 네가 왕이 아니냐 예수께서 대답하시되 네 말과 같이 내가 왕이니라 내가 이를 위하여 태어났으며 이를 위하여 세상에 왔나니 곧 진리에 대하여 증언하려 함이로라 무릇 진리에 속한 자는 내 음성을 듣느니라 하신대'),
    (26856, '<십자가에 못 박도록 예수를 넘겨 주다> 빌라도가 이르되 진리가 무엇이냐 하더라 ○이 말을 하고 다시 유대인들에게 나가서 이르되 나는 그에게서 아무 죄도 찾지 못하였노라'),
    (27041, '<베드로가 솔로몬의 행각에서 설교하다> ○나은 사람이 베드로와 요한을 붙잡으니 모든 백성이 크게 놀라며 달려 나아가 솔로몬의 행각이라 불리우는 행각에 모이거늘'),
    (26963, '<예수께서 하늘로 올려지시다> ○그들이 모였을 때에 예수께 여쭈어 이르되 주께서 이스라엘 나라를 회복하심이 이 때니이까 하니'),
    (26969, '<유다 대신에 맛디아를 세우다> ○제자들이 감람원이라 하는 산으로부터 예루살렘에 돌아오니 이 산은 예루살렘에서 가까워 안식일에 가기 알맞은 길이라'),
    (26972, '○모인 무리의 수가 약 백이십 명이나 되더라 그 때에 베드로가 그 형제들 가운데 일어서서 이르되'),
    (27142, '○하나님의 말씀이 점점 왕성하여 예루살렘에 있는 제자의 수가 더 심히 많아지고 허다한 제사장의 무리도 이 도에 복종하니라'),
    (27143, '<스데반이 잡히다> ○스데반이 은혜와 권능이 충만하여 큰 기사와 표적을 민간에 행하니'),
    (27100, '○세 시간쯤 지나 그의 아내가 그 일어난 일을 알지 못하고 들어오니'),
    (27105, '<사도들이 표적을 일으키다> ○사도들의 손을 통하여 민간에 표적과 기사가 많이 일어나매 믿는 사람이 다 마음을 같이하여 솔로몬 행각에 모이고'),
    (27110, '<사도들이 능욕을 받다> ○대제사장과 그와 함께 있는 사람 즉 사두개인의 당파가 다 마음에 시기가 가득하여 일어나서'),
    (27126, '○그들이 듣고 크게 노하여 사도들을 없이하고자 할새'),
    (27129, '이 전에 드다가 일어나 스스로 선전하매 사람이 약 사백 명이나 따르더니 그가 죽임을 당하매 따르던 모든 사람들이 흩어져 없어졌고'),
    (26988, '○그 때에 경건한 유대인들이 천하 각국으로부터 와서 예루살렘에 머물러 있더니'),
    (26997, '<베드로의 오순절 설교> ○베드로가 열한 사도와 함께 서서 소리를 높여 이르되 유대인들과 예루살렘에 사는 모든 사람들아 이 일을 너희로 알게 할 것이니 내 말에 귀를 기울이라'),
    (27020, '○그들이 이 말을 듣고 마음에 찔려 베드로와 다른 사도들에게 물어 이르되 형제들아 우리가 어찌할꼬 하거늘'),
    (27026, '<믿는 사람이 모든 물건을 통용하다> ○사람마다 두려워하는데 사도들로 말미암아 기사와 표적이 많이 나타나니'),
    (27028, '또 재산과 소유를 팔아 각 사람의 필요를 따라 나눠 주며'),
    (27061, '○이튿날 관리들과 장로들과 서기관들이 예루살렘에 모였는데'),
    (27069, '○그들이 베드로와 요한이 담대하게 말함을 보고 그들을 본래 학문 없는 범인으로 알았다가 이상히 여기며 또 전에 예수와 함께 있던 줄도 알고'),
    (27073, '이것이 민간에 더 퍼지지 못하게 그들을 위협하여 이 후에는 이 이름으로 아무에게도 말하지 말게 하자 하고'),
    (27079, '<한마음으로 하나님께 기도하다> ○사도들이 놓이매 그 동료에게 가서 제사장들과 장로들의 말을 다 알리니'),
    (27088, '<물건을 서로 통용하다> ○믿는 무리가 한마음과 한 뜻이 되어 모든 물건을 서로 통용하고 자기 재물을 조금이라도 자기 것이라 하는 이가 하나도 없더라'),
    (27092, '○구브로에서 난 레위족 사람이 있으니 이름은 요셉이라 사도들이 일컬어 바나바라(번역하면 위로의 아들이라) 하니'),
    (27204, '<스데반이 순교하다> ○그들이 이 말을 듣고 마음에 찔려 그를 향하여 이를 갈거늘'),
    (27304, '○이튿날 그들이 길을 가다가 그 성에 가까이 갔을 그 때에 베드로가 기도하려고 지붕에 올라가니 그 시각은 제 육 시더라'),
    (27312, '○베드로가 본 바 환상이 무슨 뜻인지 속으로 의아해 하더니 마침 고넬료가 보낸 사람들이 시몬의 집을 찾아 문 밖에 서서'),
    (27318, '<베드로가 고넬료의 집에서 설교하다> 베드로가 불러 들여 유숙하게 하니라 ○이튿날 일어나 그들과 함께 갈새 욥바에서 온 어떤 형제들도 함께 가니라'),
    (27340, '<이방인들도 성령을 받다> ○베드로가 이 말을 할 때에 성령이 말씀 듣는 모든 사람에게 내려오시니'),
    (27211, '<사울이 교회를 박해하다> 사울은 그가 죽임 당함을 마땅히 여기더라 ○그 날에 예루살렘에 있는 교회에 큰 박해가 있어 사도 외에는 다 유대와 사마리아 모든 땅으로 흩어지니라'),
    (27215, '<사마리아에 복음을 전하다> ○그 흩어진 사람들이 두루 다니며 복음의 말씀을 전할새'),
    (27220, '○그 성에 시몬이라 하는 사람이 전부터 있어 마술을 행하여 사마리아 백성을 놀라게 하며 자칭 큰 자라 하니'),
    (27225, '○예루살렘에 있는 사도들이 사마리아도 하나님의 말씀을 받았다 함을 듣고 베드로와 요한을 보내매'),
    (27236, '○두 사도가 주의 말씀을 증언하여 말한 후 예루살렘으로 돌아갈새 사마리아인의 여러 마을에서 복음을 전하니라'),
    (27237, '<빌립과 에디오피아 내시> ○주의 사자가 빌립에게 말하여 이르되 일어나서 남쪽으로 향하여 예루살렘에서 가사로 내려가는 길까지 가라 하니 그 길은 광야라'),
    (27244, '그가 굴욕을 당했을 때 공정한 재판도 받지 못하였으니 누가 그의 세대를 말하리요 그의 생명이 땅에서 빼앗김이로다 하였거늘'),
    (27394, '<헤롯이 죽다> ○헤롯이 두로와 시돈 사람들을 대단히 노여워하니 그들의 지방이 왕국에서 나는 양식을 먹는 까닭에 한마음으로 그에게 나아와 왕의 침소 맡은 신하 블라스도를 설득하여 화목하기를 청한지라'),
    (27398, '○하나님의 말씀은 흥왕하여 더하더라'),
    (27399, '○바나바와 사울이 부조하는 일을 마치고 마가라 하는 요한을 데리고 예루살렘에서 돌아오니라'),
    (27252, '<사울이 회개하다> 사울이 주의 제자들에 대하여 여전히 위협과 살기가 등등하여 대제사장에게 가서'),
    (27261, '○그 때에 다메섹에 아나니아라 하는 제자가 있더니 주께서 환상 중에 불러 이르시되 아나니아야 하시거늘 대답하되 주여 내가 여기 있나이다 하니'),
    (27270, '<사울이 다메섹에서 전도하다> 음식을 먹으매 강건하여지니라 ○사울이 다메섹에 있는 제자들과 함께 며칠 있을새'),
    (27275, '<사울이 피신하다> ○여러 날이 지나매 유대인들이 사울 죽이기를 공모하더니'),
    (27278, '<사울이 예루살렘에 가다> ○사울이 예루살렘에 가서 제자들을 사귀고자 하나 다 두려워하여 그가 제자 됨을 믿지 아니하니'),
    (27283, '○그리하여 온 유대와 갈릴리와 사마리아 교회가 평안하여 든든히 서 가고 주를 경외함과 성령의 위로로 진행하여 수가 더 많아지니라'),
    (27284, '<베드로가 중풍병자를 고치다> ○그 때에 베드로가 사방으로 두루 다니다가 룻다에 사는 성도들에게도 내려갔더니'),
    (27288, '<베드로가 도르가를 살리다> ○욥바에 다비다라 하는 여제자가 있으니 그 이름을 번역하면 도르가라 선행과 구제하는 일이 심히 많더니'),
    (27363, '<안디옥 교회> ○그 때에 스데반의 일로 일어난 환난으로 말미암아 흩어진 자들이 베니게와 구브로와 안디옥까지 이르러 유대인에게만 말씀을 전하는데'),
    (27371, '○그 때에 선지자들이 예루살렘에서 안디옥에 이르니'),
    (27459, '<바울과 바나바가 루스드라에서 전도하다> ○루스드라에 발을 쓰지 못하는 한 사람이 앉아 있는데 나면서 걷지 못하게 되어 걸어 본 적이 없는 자라'),
    (27466, '이르되 여러분이여 어찌하여 이러한 일을 하느냐 우리도 여러분과 같은 성정을 가진 사람이라 여러분에게 복음을 전하는 것은 이런 헛된 일을 버리고 천지와 바다와 그 가운데 만물을 지으시고 살아 계신 하나님께로 돌아오게 함이라'),
    (27470, '○유대인들이 안디옥과 이고니온에서 와서 무리를 충동하니 그들이 돌로 바울을 쳐서 죽은 줄로 알고 시외로 끌어 내치니라'),
    (27481, '바울 및 바나바와 그들 사이에 적지 아니한 다툼과 변론이 일어난지라 형제들이 이 문제에 대하여 바울과 바나바와 및 그 중의 몇 사람을 예루살렘에 있는 사도와 장로들에게 보내기로 작정하니라'),
    (27485, '○사도와 장로들이 이 일을 의논하러 모여'),
    (27491, '○온 무리가 가만히 있어 바나바와 바울이 하나님께서 자기들로 말미암아 이방인 중에서 행하신 표적과 기사에 관하여 말하는 것을 듣더니'),
    (27495, '이 후에 내가 돌아와서 다윗의 무너진 장막을 다시 지으며 또 그 허물어진 것을 다시 지어 일으키리니'),
    (27501, '<이방인 신자들에게 보내는 편지> ○이에 사도와 장로와 온 교회가 그 중에서 사람들을 택하여 바울과 바나바와 함께 안디옥으로 보내기를 결정하니 곧 형제 중에 인도자인 바사바라 하는 유다와 실라더라'),
    (27504, '사람을 택하여 우리 주 예수 그리스도의 이름을 위하여 생명을 아끼지 아니하는 자인 우리가 사랑하는 바나바와 바울과 함께 너희에게 보내기를 만장일치로 결정하였노라'),
    (27508, '○그들이 작별하고 안디옥에 내려가 무리를 모은 후에 편지를 전하니'),
    (27514, '<바울과 바나바가 갈라서다> ○며칠 후에 바울이 바나바더러 말하되 우리가 주의 말씀을 전한 각 성으로 다시 가서 형제들이 어떠한가 방문하자 하고'),
    (27403, '<바나바와 사울이 구브로에서 전도하다> ○두 사람이 성령의 보내심을 받아 실루기아에 내려가 거기서 배 타고 구브로에 가서'),
    (27412, '<바울과 바나바가 비시디아 안디옥에서 전도하다> ○바울과 및 동행하는 사람들이 바보에서 배 타고 밤빌리아에 있는 버가에 이르니 요한은 그들에게서 떠나 예루살렘으로 돌아가고'),
    (27441, '○그들이 나갈새 사람들이 청하되 다음 안식일에도 이 말씀을 하라 하더라'),
    (27442, '회당의 모임이 끝난 후에 유대인과 유대교에 입교한 경건한 사람들이 많이 바울과 바나바를 따르니 두 사도가 더불어 말하고 항상 하나님의 은혜 가운데 있으라 권하니라'),
    (27443, '○그 다음 안식일에는 온 시민이 거의 다 하나님의 말씀을 듣고자 하여 모이니'),
    (27445, '바울과 바나바가 담대히 말하여 이르되 하나님의 말씀을 마땅히 먼저 너희에게 전할 것이로되 너희가 그것을 버리고 영생을 얻기에 합당하지 않은 자로 자처하기로 우리가 이방인에게로 향하노라'),
    (27569, '<베뢰아 사람들이 말씀을 받다> ○밤에 형제들이 곧 바울과 실라를 베뢰아로 보내니 그들이 이르러 유대인의 회당에 들어가니라'),
    (27575, '<바울이 아덴에서 전도하다> ○바울이 아덴에서 그들을 기다리다가 그 성에 우상이 가득한 것을 보고 마음에 격분하여'),
    (27577, '어떤 에피쿠로스와 스토아 철학자들도 바울과 쟁론할새 어떤 사람은 이르되 이 말쟁이가 무슨 말을 하고자 하느냐 하고 어떤 사람은 이르되 이방 신들을 전하는 사람인가보다 하니 이는 바울이 예수와 부활을 전하기 때문이러라'),
    (27591, '○그들이 죽은 자의 부활을 듣고 어떤 사람은 조롱도 하고 어떤 사람은 이 일에 대하여 네 말을 다시 듣겠다 하니'),
    (27595, '아굴라라 하는 본도에서 난 유대인 한 사람을 만나니 글라우디오가 모든 유대인을 명하여 로마에서 떠나라 한 고로 그가 그 아내 브리스길라와 함께 이달리야로부터 새로 온지라 바울이 그들에게 가매'),
    (27598, '○실라와 디모데가 마게도냐로부터 내려오매 바울이 하나님의 말씀에 붙잡혀 유대인들에게 예수는 그리스도라 밝히 증언하니'),
    (27599, '그들이 대적하여 비방하거늘 바울이 옷을 털면서 이르되 너희 피가 너희 머리로 돌아갈 것이요 나는 깨끗하니라 이 후에는 이방인에게로 가리라 하고'),
    (27605, '○갈리오가 아가야 총독 되었을 때에 유대인이 일제히 일어나 바울을 대적하여 법정으로 데리고 가서'),
    (27611, '<바울이 안디옥으로 내려가다> ○바울은 더 여러 날 머물다가 형제들과 작별하고 배 타고 수리아로 떠나갈새 브리스길라와 아굴라도 함께 하더라 바울이 일찍이 서원이 있었으므로 겐그레아에서 머리를 깎았더라'),
    (27617, '<아볼로가 담대히 전도하다> ○알렉산드리아에서 난 아볼로라 하는 유대인이 에베소에 이르니 이 사람은 언변이 좋고 성경에 능통한 자라'),
    (27525, '<바울이 환상을 보다> ○성령이 아시아에서 말씀을 전하지 못하게 하시거늘 그들이 브루기아와 갈라디아 땅으로 다녀가'),
    (27530, '<루디아가 믿다> ○우리가 드로아에서 배로 떠나 사모드라게로 직행하여 이튿날 네압볼리로 가고'),
    (27535, '<바울과 실라가 갇히다> ○우리가 기도하는 곳에 가다가 점치는 귀신 들린 여종 하나를 만나니 점으로 그 주인들에게 큰 이익을 주는 자라'),
    (27538, '○여종의 주인들은 자기 수익의 소망이 끊어진 것을 보고 바울과 실라를 붙잡아 장터로 관리들에게 끌어 갔다가'),
    (27554, '○날이 새매 상관들이 부하를 보내어 이 사람들을 놓으라 하니'),
    (27669, '<유두고를 살리다> ○그 주간의 첫날에 우리가 떡을 떼려 하여 모였더니 바울이 이튿날 떠나고자 하여 그들에게 강론할새 말을 밤중까지 계속하매'),
    (27675, '<드로아에서 밀레도까지 항해하다> ○우리는 앞서 배를 타고 앗소에서 바울을 태우려고 그리로 가니 이는 바울이 걸어서 가고자 하여 그렇게 정하여 준 것이라'),
    (27679, '<에베소 장로들에게 고별 설교를 하다> ○바울이 밀레도에서 사람을 에베소로 보내어 교회 장로들을 청하니'),
    (27698, '○이 말을 한 후 무릎을 꿇고 그 모든 사람들과 함께 기도하니'),
    (27629, '○바울이 회당에 들어가 석 달 동안 담대히 하나님 나라에 관하여 강론하며 권면하되'),
    (27642, '<에베소에서 일어난 소동> ○이 일이 있은 후에 바울이 마게도냐와 아가야를 거쳐 예루살렘에 가기로 작정하여 이르되 내가 거기 갔다가 후에 로마도 보아야 하리라 하고'),
    (27644, '○그 때쯤 되어 이 도로 말미암아 적지 않은 소동이 있었으니'),
    (27811, '그가 또 성전을 더럽게 하려 하므로 우리가 잡았사오니'),
    (27814, '<바울이 변명하다> ○총독이 바울에게 머리로 표시하여 말하라 하니 그가 대답하되 당신이 여러 해 전부터 이 민족의 재판장 된 것을 내가 알고 내 사건에 대하여 기꺼이 변명하나이다'),
    (27828, '<바울이 감옥에 갇혀 지내다> ○수일 후에 벨릭스가 그 아내 유대 여자 드루실라와 함께 와서 바울을 불러 그리스도 예수 믿는 도를 듣거늘'),
    (27742, '<바울이 변명하다> ○그들이 그가 히브리 말로 말함을 듣고 더욱 조용한지라 이어 이르되'),
    (27770, '<바울이 공회 앞에서 증언하다> ○이튿날 천부장은 유대인들이 무슨 일로 그를 고발하는지 진상을 알고자 하여 그 결박을 풀고 명하여 제사장들과 온 공회를 모으고 바울을 데리고 내려가서 그들 앞에 세우니라'),
    (27776, '바울이 그 중 일부는 사두개인이요 다른 일부는 바리새인인 줄 알고 공회에서 외쳐 이르되 여러분 형제들아 나는 바리새인이요 또 바리새인의 아들이라 죽은 자의 소망 곧 부활로 말미암아 내가 심문을 받노라'),
    (27781, '○그 날 밤에 주께서 바울 곁에 서서 이르시되 담대하라 네가 예루살렘에서 나의 일을 증언한 것 같이 로마에서도 증언하여야 하리라 하시니라'),
    (27782, '<바울을 죽이려는 간계> ○날이 새매 유대인들이 당을 지어 맹세하되 바울을 죽이기 전에는 먹지도 아니하고 마시지도 아니하겠다 하고'),
    (27785, '이제 너희는 그의 사실을 더 자세히 물어보려는 척하면서 공회와 함께 천부장에게 청하여 바울을 너희에게로 데리고 내려오게 하라 우리는 그가 가까이 오기 전에 죽이기로 준비하였노라 하더니'),
    (27791, '당신은 그들의 청함을 따르지 마옵소서 그들 중에서 바울을 죽이기 전에는 먹지도 않고 마시지도 않기로 맹세한 자 사십여 명이 그를 죽이려고 숨어서 지금 다 준비하고 당신의 허락만 기다리나이다 하니'),
    (27797, '이 사람이 유대인들에게 잡혀 죽게 된 것을 내가 로마 사람인 줄 들어 알고 군대를 거느리고 가서 구원하였다가'),
    (27801, '<바울을 벨릭스 총독 앞에 세우다> ○보병이 명을 받은 대로 밤에 바울을 데리고 안디바드리에 이르러'),
    (27707, '○두로를 떠나 항해를 다 마치고 돌레마이에 이르러 형제들에게 안부를 묻고 그들과 함께 하루를 있다가'),
    (27715, '○이 여러 날 후에 여장을 꾸려 예루살렘으로 올라갈새'),
    (27717, '<바울이 야고보를 방문하다> ○예루살렘에 이르니 형제들이 우리를 기꺼이 영접하거늘'),
    (27727, '<바울이 잡히다> ○그 이레가 거의 차매 아시아로부터 온 유대인들이 성전에서 바울을 보고 모든 무리를 충동하여 그를 붙들고'),
    (27728, '외치되 이스라엘 사람들아 도우라 이 사람은 각처에서 우리 백성과 율법과 이 곳을 비방하여 모든 사람을 가르치는 그 자인데 또 헬라인을 데리고 성전에 들어가서 이 거룩한 곳을 더럽혔다 하니'),
    (27737, '<바울이 백성에게 말하다> ○바울을 데리고 영내로 들어가려 할 그 때에 바울이 천부장에게 이르되 내가 당신에게 말할 수 있느냐 이르되 네가 헬라 말을 아느냐'),
    (27859, '<바울이 변명하다> 아그립바가 바울에게 이르되 너를 위하여 말하기를 네게 허락하노라 하니 이에 바울이 손을 들어 변명하되'),
    (27882, '<바울이 아그립바 왕에게 전도하다> ○바울이 이같이 변명하매 베스도가 크게 소리 내어 이르되 바울아 네가 미쳤도다 네 많은 학문이 너를 미치게 한다 하니'),
    (27888, '○왕과 총독과 버니게와 그 함께 앉은 사람들이 다 일어나서'),
    (27837, '○베스도가 그들 가운데서 팔 일 혹은 십 일을 지낸 후 가이사랴로 내려가서 이튿날 재판 자리에 앉고 바울을 데려오라 명하니'),
    (27842, '만일 내가 불의를 행하여 무슨 죽을 죄를 지었으면 죽기를 사양하지 아니할 것이나 만일 이 사람들이 나를 고발하는 것이 다 사실이 아니면 아무도 나를 그들에게 내줄 수 없나이다 내가 가이사께 상소하노라 한대'),
    (27844, '<바울이 아그립바 왕과 버니게 앞에 서다> ○수일 후에 아그립바 왕과 버니게가 베스도에게 문안하러 가이사랴에 와서'),
    (27854, '○이튿날 아그립바와 버니게가 크게 위엄을 갖추고 와서 천부장들과 시중의 높은 사람들과 함께 접견 장소에 들어오고 베스도의 명으로 바울을 데려오니'),
    (27855, '베스도가 말하되 아그립바 왕과 여기 같이 있는 여러분이여 당신들이 보는 이 사람은 유대의 모든 무리가 크게 외치되 살려 두지 못할 사람이라고 하여 예루살렘에서와 여기서도 내게 청원하였으나'),
    (27899, '○여러 날이 걸려 금식하는 절기가 이미 지났으므로 항해하기가 위태한지라 바울이 그들을 권하여'),
    (27917, '<풍랑으로 배가 깨어지다> ○열나흘째 되는 날 밤에 우리가 아드리아 바다에서 이리 저리 쫓겨가다가 자정쯤 되어 사공들이 어느 육지에 가까워지는 줄을 짐작하고'),
    (27941, '○이 섬에서 가장 높은 사람 보블리오라 하는 이가 그 근처에 토지가 있는지라 그가 우리를 영접하여 사흘이나 친절히 머물게 하더니'),
    (27945, '<바울이 로마로 가다> ○석 달 후에 우리가 그 섬에서 겨울을 난 알렉산드리아 배를 타고 떠나니 그 배의 머리 장식은 디오스구로라'),
    (27950, '<바울이 로마에서 전도하다> ○우리가 로마에 들어가니 바울에게는 자기를 지키는 한 군인과 함께 따로 있게 허락하더라'),
    (27951, '사흘 후에 바울이 유대인 중 높은 사람들을 청하여 그들이 모인 후에 이르되 여러분 형제들아 내가 이스라엘 백성이나 우리 조상의 관습을 배척한 일이 없는데 예루살렘에서 로마인의 손에 죄수로 내준 바 되었으니'),
    (27957, '○그들이 날짜를 정하고 그가 유숙하는 집에 많이 오니 바울이 아침부터 저녁까지 강론하여 하나님의 나라를 증언하고 모세의 율법과 선지자의 말을 가지고 예수에 대하여 권하더라'),
    (27964, '○바울이 온 이태를 자기 셋집에 머물면서 자기에게 오는 사람을 다 영접하고'),
    (28031, '그러나 우리 불의가 하나님의 의를 드러나게 하면 무슨 말 하리요 (내가 사람의 말하는 대로 말하노니) 진노를 내리시는 하나님이 불의하시냐'),
    (28035, '<다 죄 아래에 있다> ○그러면 어떠하냐 우리는 나으냐 결코 아니라 유대인이나 헬라인이나 다 죄 아래에 있다고 우리가 이미 선언하였느니라'),
    (28045, '<하나님의 의> ○우리가 알거니와 무릇 율법이 말하는 바는 율법 아래에 있는 자들에게 말하는 것이니 이는 모든 입을 막고 온 세상으로 하나님의 심판 아래에 있게 하려 함이라'),
    (28073, '그러므로 상속자가 되는 그것이 은혜에 속하기 위하여 믿음으로 되나니 이는 그 약속을 그 모든 후손에게 굳게 하려 하심이라 율법에 속한 자에게뿐만 아니라 아브라함의 믿음에 속한 자에게도 그러하니 아브라함은 우리 모든 사람의 조상이라'),
    (27973, '<바울의 로마 방문 계획> ○먼저 내가 예수 그리스도로 말미암아 너희 모든 사람에 관하여 내 하나님께 감사함은 너희 믿음이 온 세상에 전파됨이로다'),
    (27983, '<모든 경건하지 않음과 불의> ○하나님의 진노가 불의로 진리를 막는 사람들의 모든 경건하지 않음과 불의에 대하여 하늘로부터 나타나나니'),
    (27989, '○그러므로 하나님께서 그들을 마음의 정욕대로 더러움에 내버려 두사 그들의 몸을 서로 욕되게 하게 하셨으니'),
    (27991, '○이 때문에 하나님께서 그들을 부끄러운 욕심에 내버려 두셨으니 곧 그들의 여자들도 순리대로 쓸 것을 바꾸어 역리로 쓰며'),
    (27993, '○또한 그들이 마음에 하나님 두기를 싫어하매 하나님께서 그들을 그 상실한 마음대로 내버려 두사 합당하지 못한 일을 하게 하셨으니'),
    (28009, '○무릇 율법 없이 범죄한 자는 또한 율법 없이 망하고 무릇 율법이 있고 범죄한 자는 율법으로 말미암아 심판을 받으리라'),
    (28014, '<유대인과 율법> ○유대인이라 불리는 네가 율법을 의지하며 하나님을 자랑하며'),
    (28094, '<아담과 그리스도> ○그러므로 한 사람으로 말미암아 죄가 세상에 들어오고 죄로 말미암아 사망이 들어왔나니 이와 같이 모든 사람이 죄를 지었으므로 사망이 모든 사람에게 이르렀느니라'),
    (28097, '그러나 이 은사는 그 범죄와 같지 아니하니 곧 한 사람의 범죄를 인하여 많은 사람이 죽었은즉 더욱 하나님의 은혜와 또한 한 사람 예수 그리스도의 은혜로 말미암은 선물은 많은 사람에게 넘쳤느니라'),
    (28107, '그러므로 우리가 그의 죽으심과 합하여 세례를 받음으로 그와 함께 장사되었나니 이는 아버지의 영광으로 말미암아 그리스도를 죽은 자 가운데서 살리심과 같이 우리로 또한 새 생명 가운데서 행하게 하려 함이라'),
    (28115, '○그러므로 너희는 죄가 너희 죽을 몸을 지배하지 못하게 하여 몸의 사욕에 순종하지 말고'),
    (28118, '<의의 종> ○그런즉 어찌하리요 우리가 법 아래에 있지 아니하고 은혜 아래에 있으니 죄를 지으리요 그럴 수 없느니라'),
    (28130, '그러므로 내 형제들아 너희도 그리스도의 몸으로 말미암아 율법에 대하여 죽임을 당하였으니 이는 다른 이 곧 죽은 자 가운데서 살아나신 이에게 가서 우리가 하나님을 위하여 열매를 맺게 하려 함이라'),
    (28133, '그런즉 우리가 무슨 말을 하리요 율법이 죄냐 그럴 수 없느니라 율법으로 말미암지 않고는 내가 죄를 알지 못하였으니 곧 율법이 탐내지 말라 하지 아니하였더라면 내가 탐심을 알지 못하였으리라'),
    (28139, '그런즉 선한 것이 내게 사망이 되었느냐 그럴 수 없느니라 오직 죄가 죄로 드러나기 위하여 선한 그것으로 말미암아 나를 죽게 만들었으니 이는 계명으로 말미암아 죄로 심히 죄 되게 하려 함이라'),
    (28163, '○그러므로 형제들아 우리가 빚진 자로되 육신에게 져서 육신대로 살 것이 아니니라'),
    (28169, '<모든 피조물이 구원을 고대하다> ○생각하건대 현재의 고난은 장차 우리에게 나타날 영광과  비교할 수 없도다'),
    (28177, '○이와 같이 성령도 우리의 연약함을 도우시나니 우리는 마땅히 기도할 바를 알지 못하나 오직 성령이 말할 수 없는 탄식으로 우리를 위하여 친히 간구하시느니라'),
    (28182, '<그리스도의 사랑 하나님의 사랑> ○그런즉 이 일에 대하여 우리가 무슨 말 하리요 만일 하나님이 우리를 위하시면 누가 우리를 대적하리요'),
    (28238, '<믿음과 들음과 그리스도의 말씀> ○그러나 그들이 다 복음을 순종하지 아니하였도다 이사야가 이르되 주여 우리가 전한 것을 누가 믿었나이까 하였으니'),
    (28191, '<약속의 자녀 약속의 말씀> 내가 그리스도 안에서 참말을 하고 거짓말을 아니하노라 나에게 큰 근심이 있는 것과 마음에 그치지 않는 고통이 있는 것을 내 양심이 성령 안에서 나와 더불어 증언하노니'),
    (28203, '○그런즉 우리가 무슨 말을 하리요 하나님께 불의가 있느냐 그럴 수 없느니라'),
    (28208, '<하나님의 진노와 긍휼> ○혹 네가 내게 말하기를 그러면 하나님이 어찌하여 허물하시느냐 누가 그 뜻을 대적하느냐 하리니'),
    (28219, '<믿음에서 난 의> ○그런즉 우리가 무슨 말을 하리요 의를 따르지 아니한 이방인들이 의를 얻었으니 곧 믿음에서 난 의요'),
    (28256, '<이방인의 구원> ○내가 이방인인 너희에게 말하노라 내가 이방인의 사도인 만큼 내 직분을 영광스럽게 여기노니'),
    (28265, '그러므로 하나님의 인자하심과 준엄하심을 보라 넘어지는 자들에게는 준엄하심이 있으니 너희가 만일 하나님의 인자하심에 머물러 있으면 그 인자가 너희에게 있으리라 그렇지 않으면 너도 찍히는 바 되리라'),
    (28268, '<이스라엘의 구원> ○형제들아 너희가 스스로 지혜 있다 하면서 이 신비를 너희가 모르기를 내가 원하지 아니하노니 이 신비는 이방인의 충만한 수가 들어오기까지 이스라엘의 더러는 우둔하게 된 것이라'),
    (28276, '○깊도다 하나님의 지혜와 지식의 풍성함이여, 그의 판단은 헤아리지 못할 것이며 그의 길은 찾지 못할 것이로다'),
    (28277, '○누가 주의 마음을 알았느냐 누가 그의 모사가 되었느냐'),
    (28278, '○누가 주께 먼저 드려서 갚으심을 받겠느냐'),
    (28279, '○이는 만물이 주에게서 나오고 주로 말미암고 주에게로 돌아감이라 그에게 영광이 세세에 있을지어다 아멘'),
    (28304, '그는 하나님의 사역자가 되어 네게 선을 베푸는 자니라 그러나 네가 악을 행하거든 두려워하라 그가 공연히 칼을 가지지 아니하였으니 곧 하나님의 사역자가 되어 악을 행하는 자에게 진노하심을 따라 보응하는 자니라'),
    (28308, '<사랑은 율법의 완성> ○피차 사랑의 빚 외에는 아무에게든지 아무 빚도 지지 말라 남을 사랑하는 자는 율법을 다 이루었느니라'),
    (28311, '<구원의 때가 가까워졌다> ○또한 너희가 이 시기를 알거니와 자다가 깰 때가 벌써 되었으니 이는 이제 우리의 구원이 처음 믿을 때보다 가까웠음이라'),
    (28280, '<하나님의 뜻을 분별하는 새 생활> 그러므로 형제들아 내가 하나님의 모든 자비하심으로 너희를 권하노니 너희 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리라 이는 너희가 드릴 영적 예배니라'),
    (28282, '○내게 주신 은혜로 말미암아 너희 각 사람에게 말하노니 마땅히 생각할 그 이상의 생각을 품지 말고 오직 하나님께서 각 사람에게 나누어 주신 믿음의 분량대로 지혜롭게 생각하라'),
    (28293, '<그리스도인의 생활> ○너희를 박해하는 자를 축복하라 축복하고 저주하지 말라'),
    (28327, '<형제로 거리끼게 하지 말라> ○그런즉 우리가 다시는 서로 비판하지 말고 도리어 부딪칠 것이나 거칠 것을 형제 앞에 두지 아니하도록 주의하라'),
    (28351, '<하나님의 복음의 제사장 직분> ○내 형제들아 너희가 스스로 선함이 가득하고 모든 지식이 차서 능히 서로 권하는 자임을 나도 확신하노라'),
    (28353, '이 은혜는 곧 나로 이방인을 위하여 그리스도 예수의 일꾼이 되어 하나님의 복음의 제사장 직분을 하게 하사 이방인을 제물로 드리는 것이 성령 안에서 거룩하게 되어 받으실 만하게 하려 하심이라'),
    (28359, '<바울의 로마 방문 계획> ○그러므로 또한 내가 너희에게 가려 하던 것이 여러 번 막혔더니'),
    (28367, '○형제들아 내가 우리 주 예수 그리스도와 성령의 사랑으로 말미암아 너희를 권하노니 너희 기도에 나와 힘을 같이하여 나를 위하여 하나님께 빌어'),
    (28455, '○내게 주신 하나님의 은혜를 따라 내가 지혜로운 건축자와 같이 터를 닦아 두매 다른 이가 그 위에 세우나 그러나 각각 어떻게 그 위에 세울까를 조심할지니라'),
    (28461, '○너희는 너희가 하나님의 성전인 것과 하나님의 성령이 너희 안에 계시는 것을 알지 못하느냐'),
    (28463, '○아무도 자신을 속이지 말라 너희 중에 누구든지 이 세상에서 지혜 있는 줄로 생각하거든 어리석은 자가 되라 그리하여야 지혜로운 자가 되리라'),
    (28435, '<성령으로 보이셨다> ○그러나 우리가 온전한 자들 중에서는 지혜를 말하노니 이는 이 세상의 지혜가 아니요 또 이 세상에서 없어질 통치자들의 지혜도 아니요'),
    (28498, '○내가 너희에게 쓴 편지에 음행하는 자들을 사귀지 말라 하였거니와'),
    (28499, '이 말은 이 세상의 음행하는 자들이나 탐하는 자들이나 속여 빼앗는 자들이나 우상 숭배하는 자들을 도무지 사귀지 말라 하는 것이 아니니 만일 그리하려면 너희가 세상 밖으로 나가야 할 것이라'),
    (28500, '이제 내가 너희에게 쓴 것은 만일 어떤 형제라 일컫는 자가 음행하거나 탐욕을 부리거나 우상 숭배를 하거나 모욕하거나 술 취하거나 속여 빼앗거든 사귀지도 말고 그런 자와는 함께 먹지도 말라 함이라'),
    (28400, '고린도에 있는 하나님의 교회 곧 그리스도 예수 안에서 거룩하여지고 성도라 부르심을 받은 자들과 또 각처에서 우리의 주 곧 그들과 우리의 주 되신 예수 그리스도의 이름을 부르는 모든 자들에게'),
    (28402, '○그리스도 예수 안에서 너희에게 주신 하나님의 은혜로 말미암아 내가 너희를 위하여 항상 하나님께 감사하노니'),
    (28408, '<고린도 교회의 분쟁> ○형제들아 내가 우리 주 예수 그리스도의 이름으로 너희를 권하노니 모두가 같은 말을 하고 너희 가운데 분쟁이 없이 같은 마음과 같은 뜻으로 온전히 합하라'),
    (28416, '<하나님의 능력과 지혜이신 그리스도> ○십자가의 도가 멸망하는 자들에게는 미련한 것이요 구원을 받는 우리에게는 하나님의 능력이라'),
    (28424, '○형제들아 너희를 부르심을 보라 육체를 따라 지혜로운 자가 많지 아니하며 능한 자가 많지 아니하며 문벌 좋은 자가 많지 아니하도다'),
    (28473, '그러므로 때가 이르기 전 곧 주께서 오시기까지 아무 것도 판단하지 말라 그가 어둠에 감추인 것들을 드러내고 마음의 뜻을 나타내시리니 그 때에 각 사람에게 하나님으로부터 칭찬이 있으리라'),
    (28474, '○형제들아 내가 너희를 위하여 이 일에 나와 아볼로를 들어서 본을 보였으니 이는 너희로 하여금 기록된 말씀 밖으로 넘어가지 말라 한 것을 우리에게서 배워 서로 대적하여 교만한 마음을 가지지 말게 하려 함이라'),
    (28482, '○내가 너희를 부끄럽게 하려고 이것을 쓰는 것이 아니라 오직 너희를 내 사랑하는 자녀 같이 권하려 하는 것이라'),
    (28485, '이로 말미암아 내가 주 안에서 내 사랑하고 신실한 아들 디모데를 너희에게 보내었으니 그가 너희로 하여금 그리스도 예수 안에서 나의 행사 곧 내가 각처 각 교회에서 가르치는 것을 생각나게 하리라'),
    (28373, '○너희는 그리스도 예수 안에서 나의 동역자들인 브리스가와 아굴라에게 문안하라'),
    (28387, '○형제들아 내가 너희를 권하노니 너희가 배운 교훈을 거슬러 분쟁을 일으키거나 거치게 하는 자들을 살피고 그들에게서 떠나라'),
    (28390, '평강의 하나님께서 속히 사탄을 너희 발 아래에서 상하게 하시리라 ○우리 주 예수의 은혜가 너희에게 있을지어다'),
    (28392, '<문안과 찬양> ○나의 동역자 디모데와 나의 친척 누기오와 야손과 소시바더가 너희에게 문안하느니라'),
    (28397, '이제는 나타내신 바 되었으며 영원하신 하나님의 명을 따라 선지자들의 글로 말미암아 모든 민족이 믿어 순종하게 하시려고 알게 하신 바 그 신비의 계시를 따라 된 것이니 이 복음으로 너희를 능히 견고하게 하실'),
    (28514, '<몸으로 하나님께 영광을 돌리라> ○모든 것이 내게 가하나 다 유익한 것이 아니요 모든 것이 내게 가하나 내가 무엇에든지 얽매이지 아니하리라'),
    (28530, '○내가 결혼하지 아니한 자들과 과부들에게 이르노니 나와 같이 그냥 지내는 것이 좋으니라'),
    (28547, '<처녀와 과부에게 주는 권면> ○처녀에 대하여는 내가 주께 받은 계명이 없으되 주의 자비하심을 받아서 충성스러운 자가 된 내가 의견을 말하노니'),
    (28551, '형제들아 내가 이 말을 하노니 그 때가 단축하여진 고로 이 후부터 아내 있는 자들은 없는 자 같이 하며'),
    (28558, '그러므로 만일 누가 자기의 약혼녀에 대한 행동이 합당하지 못한 줄로 생각할 때에 그 약혼녀의 혼기도 지나고 그같이 할 필요가 있거든 원하는 대로 하라 그것은 죄 짓는 것이 아니니 그들로 결혼하게 하라'),
    (28588, '성전의 일을 하는 이들은 성전에서 나는 것을 먹으며 제단에서 섬기는 이들은 제단과 함께 나누는 것을 너희가 알지 못하느냐'),
    (28595, '유대인들에게 내가 유대인과 같이 된 것은 유대인들을 얻고자 함이요 율법 아래에 있는 자들에게는 내가 율법 아래에 있지 아니하나 율법 아래에 있는 자 같이 된 것은 율법 아래에 있는 자들을 얻고자 함이요'),
    (28637, '<여자가 머리를 가리는 것> ○너희가 모든 일에 나를 기억하고 또 내가 너희에게 전하여 준 대로 그 전통을 너희가 지키므로 너희를 칭찬하노라'),
    (28652, '<성만찬의 제정> 내가 명하는 이 일에 너희를 칭찬하지 아니하나니 이는 너희의 모임이 유익이 못되고 도리어 해로움이라'),
    (28673, '○은사는 여러 가지나 성령은 같고'),
    (28681, '<하나의 몸과 많은 지체> ○몸은 하나인데 많은 지체가 있고 몸의 지체가 많으나 한 몸임과 같이 그리스도도 그러하니라'),
    (28697, '하나님이 교회 중에 몇을 세우셨으니 첫째는 사도요 둘째는 선지자요 셋째는 교사요 그 다음은 능력을 행하는 자요 그 다음은 병 고치는 은사와 서로 돕는 것과 다스리는 것과 각종 방언을 말하는 것이라'),
    (28615, '사람이 감당할 시험 밖에는 너희가 당한 것이 없나니 오직 하나님은 미쁘사 너희가 감당하지 못할 시험 당함을 허락하지 아니하시고 시험 당할 즈음에 또한 피할 길을 내사 너희로 능히 감당하게 하시느니라'),
    (28616, '○그런즉 내 사랑하는 자들아 우상 숭배하는 일을 피하라'),
    (28625, '<다 하나님의 영광을 위하여 하라> ○모든 것이 가하나 모든 것이 유익한 것은 아니요 모든 것이 가하나 모든 것이 덕을 세우는 것은 아니니'),
    (28842, '우리가 환난 당하는 것도 너희가 위로와 구원을 받게 하려는 것이요 우리가 위로를 받는 것도 너희가 위로를 받게 하려는 것이니 이 위로가 너희 속에 역사하여 우리가 받는 것 같은 고난을 너희도 견디게 하느니라'),
    (28846, '그가 이같이 큰 사망에서 우리를 건지셨고 또 건지실 것이며 이 후에도 건지시기를 그에게 바라노라'),
    (28848, '<고린도 교회 방문을 연기하다> ○우리가 세상에서 특별히 너희에 대하여 하나님의 거룩함과 진실함으로 행하되 육체의 지혜로 하지 아니하고 하나님의 은혜로 행함은 우리 양심이 증언하는 바니 이것이 우리의 자랑이라'),
    (28851, '○내가 이 확신을 가지고 너희로 두 번 은혜를 얻게 하기 위하여 먼저 너희에게 이르렀다가'),
    (28859, '○내가 내 목숨을 걸고 하나님을 불러 증언하시게 하노니 내가 다시 고린도에 가지 아니한 것은 너희를 아끼려 함이라'),
    (28822, '○디모데가 이르거든 너희는 조심하여 그로 두려움이 없이 너희 가운데 있게 하라 이는 그도 나와 같이 주의 일을 힘쓰는 자임이라'),
    (28825, '<권면과 끝 인사> ○깨어 믿음에 굳게 서서 남자답게 강건하라'),
    (28827, '○형제들아 스데바나의 집은 곧 아가야의 첫 열매요 또 성도 섬기기로 작정한 줄을 너희가 아는지라 내가 너희를 권하노니'),
    (28831, '○아시아의 교회들이 너희에게 문안하고 아굴라와 브리스가와 그 집에 있는 교회가 주 안에서 너희에게 간절히 문안하고'),
    (28833, '○나 바울은 친필로 너희에게 문안하노니'),
    (28865, '<근심하게 한 사람을 용서하라> ○근심하게 한 자가 있었을지라도 나를 근심하게 한 것이 아니요 어느 정도 너희 모두를 근심하게 한 것이니 어느 정도라 함은 내가 너무 지나치게 말하지 아니하려 함이라'),
    (28872, '<그리스도의 향기> ○내가 그리스도의 복음을 위하여 드로아에 이르매 주 안에서 문이 내게 열렸으되'),
    (28889, '○우리가 이같은 소망이 있으므로 담대히 말하노니'),
    (28733, '○형제들아 지혜에는 아이가 되지 말고 악에는 어린 아이가 되라 지혜에는 장성한 사람이 되라'),
    (28739, '<차례를 따라 하라> ○그런즉 형제들아 어찌할까 너희가 모일 때에 각각 찬송시도 있으며 가르치는 말씀도 있으며 계시도 있으며 방언도 있으며 통역함도 있나니 모든 것을 덕을 세우기 위하여 하라'),
    (28746, '하나님은 무질서의 하나님이 아니시요 오직 화평의 하나님이시니라 ○모든 성도가 교회에서 함과 같이'),
    (28751, '○만일 누구든지 자기를 선지자나 혹은 신령한 자로 생각하거든 내가 너희에게 편지하는 이 글이 주의 명령인 줄 알라'),
    (28753, '○그런즉 내 형제들아 예언하기를 사모하며 방언 말하기를 금하지 말라'),
    (28754, '모든 것을 품위 있게 하고 질서 있게 하라'),
    (28902, '○우리가 이 보배를 질그릇에 가졌으니 이는 심히 큰 능력은 하나님께 있고 우리에게 있지 아니함을 알게 하려 함이라'),
    (28903, '우리가 사방으로 욱여쌈을 당하여도 싸이지 아니하며 답답한 일을 당하여도 낙심하지 아니하며'),
    (28911, '<겉사람과 속사람> ○그러므로 우리가 낙심하지 아니하노니 우리의 겉사람은 낡아지나 우리의 속사람은 날로 새로워지도다'),
    (28921, '○우리가 담대하여 원하는 바는 차라리 몸을 떠나 주와 함께 있는 그것이라'),
    (28924, '<화목하게 하는 직분> ○우리는 주의 두려우심을 알므로 사람들을 권면하거니와 우리가 하나님 앞에 알리어졌으니 또 너희의 양심에도 알리어지기를 바라노라'),
    (28933, '○그러므로 우리가 그리스도를 대신하여 사신이 되어 하나님이 우리를 통하여 너희를 권면하시는 것 같이 그리스도를 대신하여 간청하노니 너희는 하나님과 화목하라'),
    (28945, '○고린도인들이여 너희를 향하여 우리의 입이 열리고 우리의 마음이 넓어졌으니'),
    (28948, '<우리는 살아 계신 하나님의 성전> ○너희는 믿지 않는 자와 멍에를 함께 메지 말라 의와 불법이 어찌 함께 하며 빛과 어둠이 어찌 사귀며'),
    (28950, '하나님의 성전과 우상이 어찌 일치가 되리요 우리는 살아 계신 하나님의 성전이라 이와 같이 하나님께서 이르시되 내가 그들 가운데 거하며 두루 행하여 나는 그들의 하나님이 되고 그들은 나의 백성이 되리라'),
    (28764, '그러나 내가 나 된 것은 하나님의 은혜로 된 것이니 내게 주신 그의 은혜가 헛되지 아니하여 내가 모든 사도보다 더 많이 수고하였으나 내가 한 것이 아니요 오직 나와 함께 하신 하나님의 은혜로라'),
    (28766, '<죽은 사람의 부활> ○그리스도께서 죽은 자 가운데서 다시 살아나셨다 전파되었거늘 너희 중에서 어떤 사람들은 어찌하여 죽은 자 가운데서 부활이 없다 하느냐'),
    (28769, '또 우리가 하나님의 거짓 증인으로 발견되리니 우리가 하나님이 그리스도를 다시 살리셨다고 증언하였음이라 만일 죽은 자가 다시 살아나는 일이 없으면 하나님이 그리스도를 다시 살리지 아니하셨으리라'),
    (28774, '○그러나 이제 그리스도께서 죽은 자 가운데서 다시 살아나사 잠자는 자들의 첫 열매가 되셨도다'),
    (28783, '○만일 죽은 자들이 도무지 다시 살아나지 못하면 죽은 자들을 위하여 세례를 받는 자들이 무엇을 하겠느냐 어찌하여 그들을 위하여 세례를 받느냐'),
    (28789, '<몸의 부활> ○누가 묻기를 죽은 자들이 어떻게 다시 살아나며 어떠한 몸으로 오느냐 하리니'),
    (28804, '○형제들아 내가 이것을 말하노니 혈과 육은 하나님 나라를 이어 받을 수 없고 또한 썩는 것은 썩지 아니하는 것을 유업으로 받지 못하느니라'),
    (28994, '이는 내가 너희의 원함을 앎이라 내가 너희를 위하여 마게도냐인들에게 아가야에서는 일 년 전부터 준비하였다는 것을 자랑하였는데 과연 너희의 열심이 퍽 많은 사람들을 분발하게 하였느니라'),
    (28998, '○이것이 곧 적게 심는 자는 적게 거두고 많이 심는 자는 많이 거둔다 하는 말이로다'),
    (28954, '<고린도 교회의 회개를 기뻐하다> ○마음으로 우리를 영접하라 우리는 아무에게도 불의를 행하지 않고 아무에게도 해롭게 하지 않고 아무에게서도 속여 빼앗은 일이 없노라'),
    (28957, '○우리가 마게도냐에 이르렀을 때에도 우리 육체가 편하지 못하였고 사방으로 환난을 당하여 밖으로는 다툼이요 안으로는 두려움이었노라'),
    (28961, '내가 지금 기뻐함은 너희로 근심하게 한 까닭이 아니요 도리어 너희가 근심함으로 회개함에 이른 까닭이라 너희가 하나님의 뜻대로 근심하게 된 것은 우리에게서 아무 해도 받지 않게 하려 함이라'),
    (28963, '보라 하나님의 뜻대로 하게 된 이 근심이 너희로 얼마나 간절하게 하며 얼마나 변증하게 하며 얼마나 분하게 하며 얼마나 두렵게 하며 얼마나 사모하게 하며 얼마나 열심 있게 하며 얼마나 벌하게 하였는가 너희가 그 일에 대하여 일체 너희 자신의 깨끗함을 나타내었느니라'),
    (28964, '그런즉 내가 너희에게 쓴 것은 그 불의를 행한 자를 위한 것도 아니요 그 불의를 당한 자를 위한 것도 아니요 오직 우리를 위한 너희의 간절함이 하나님 앞에서 너희에게 나타나게 하려 함이로라'),
    (28984, '<디도와 그의 동역자> ○너희를 위하여 같은 간절함을 디도의 마음에도 주시는 하나님께 감사하노니'),
    (29067, '나에게 이르시기를 내 은혜가 네게 족하도다 이는 내 능력이 약한 데서 온전하여짐이라 하신지라 그러므로 도리어 크게 기뻐함으로 나의 여러 약한 것들에 대하여 자랑하리니 이는 그리스도의 능력이 내게 머물게 하려 함이라'),
    (29069, '<고린도 교회의 일을 염려하다> ○내가 어리석은 자가 되었으나 너희가 억지로 시킨 것이니 나는 너희에게 칭찬을 받아야 마땅하도다 내가 아무 것도 아니나 지극히 크다는 사도들보다 조금도 부족하지 아니하니라'),
    (29072, '○보라 내가 이제 세 번째 너희에게 가기를 준비하였으나 너희에게 폐를 끼치지 아니하리라 내가 구하는 것은 너희의 재물이 아니요 오직 너희니라 어린 아이가 부모를 위하여 재물을 저축하는 것이 아니요 부모가 어린 아이를 위하여 하느니라'),
    (29078, '내가 갈 때에 너희를 내가 원하는 것과 같이 보지 못하고 또 내가 너희에게 너희가 원하지 않는 것과 같이 보일까 두려워하며 또 다툼과 시기와 분냄과 당 짓는 것과 비방과 수군거림과 거만함과 혼란이 있을까 두려워하고'),
    (29079, '또 내가 다시 갈 때에 내 하나님이 나를 너희 앞에서 낮추실까 두려워하고 또 내가 전에 죄를 지은 여러 사람의 그 행한 바 더러움과 음란함과 호색함을 회개하지 아니함 때문에 슬퍼할까 두려워하노라'),
    (29029, '만일 누가 가서 우리가 전파하지 아니한 다른 예수를 전파하거나 혹은 너희가 받지 아니한 다른 영을 받게 하거나 혹은 너희가 받지 아니한 다른 복음을 받게 할 때에는 너희가 잘 용납하는구나'),
    (29034, '또 내가 너희와 함께 있을 때 비용이 부족하였으되 아무에게도 누를 끼치지 아니하였음은 마게도냐에서 온 형제들이 나의 부족한 것을 보충하였음이라 내가 모든 일에 너희에게 폐를 끼치지 않기 위하여 스스로 조심하였고 또 조심하리라'),
    (29041, '<바울의 참된 자랑> ○내가 다시 말하노니 누구든지 나를 어리석은 자로 여기지 말라 만일 그러하더라도 내가 조금 자랑할 수 있도록 어리석은 자로 받으라'),
    (29086, '우리가 하나님께서 너희로 악을 조금도 행하지 않게 하시기를 구하노니 이는 우리가 옳은 자임을 나타내고자 함이 아니라 오직 우리는 버림 받은 자 같을지라도 너희는 선을 행하게 하고자 함이라'),
    (29090, '○마지막으로 말하노니 형제들아 기뻐하라 온전하게 되며 위로를 받으며 마음을 같이하며 평안할지어다 또 사랑과 평강의 하나님이 너희와 함께 계시리라 거룩하게 입맞춤으로 서로 문안하라'),
    (29092, '○주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다'),
    (29127, '<믿음으로 의롭게 되다> ○게바가 안디옥에 이르렀을 때에 책망 받을 일이 있기로 내가 그를 대면하여 책망하였노라'),
    (29130, '그러므로 나는 그들이 복음의 진리를 따라 바르게 행하지 아니함을 보고 모든 자 앞에서 게바에게 이르되 네가 유대인으로서 이방인을 따르고 유대인답게 살지 아니하면서 어찌하여 억지로 이방인을 유대인답게 살게 하려느냐 하였노라'),
    (29132, '사람이 의롭게 되는 것은 율법의 행위로 말미암음이 아니요 오직 예수 그리스도를 믿음으로 말미암는 줄 알므로 우리도 그리스도 예수를 믿나니 이는 우리가 율법의 행위로써가 아니고 그리스도를 믿음으로써 의롭다 함을 얻으려 함이라 율법의 행위로써는 의롭다 함을 얻을 육체가 없느니라'),
    (29136, '내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라'),
    (29098, '<다른 복음은 없다> ○그리스도의 은혜로 너희를 부르신 이를 이같이 속히 떠나 다른 복음을 따르는 것을 내가 이상하게 여기노라'),
    (29103, '<바울이 사도가 된 내력> ○형제들아 내가 너희에게 알게 하노니 내가 전한 복음은 사람의 뜻을 따라 된 것이 아니니라'),
    (29106, '내가 내 동족 중 여러 연갑자보다 유대교를 지나치게 믿어 내 조상의 전통에 대하여 더욱 열심이 있었으나'),
    (29110, '○그 후 삼 년 만에 내가 게바를 방문하려고 예루살렘에 올라가서 그와 함께 십오 일을 머무는 동안'),
    (29152, '<율법과 약속> ○형제들아 내가 사람의 예대로 말하노니 사람의 언약이라도 정한 후에는 아무도 폐하거나 더하거나 하지 못하느니라'),
    (29160, '<하나님의 아들> ○믿음이 오기 전에 우리는 율법 아래에 매인 바 되고 계시될 믿음의 때까지 갇혔느니라'),
    (29229, '○가르침을 받는 자는 말씀을 가르치는 자와 모든 좋은 것을 함께 하라'),
    (29234, '<할례와 그리스도의 십자가> ○내 손으로 너희에게 이렇게 큰 글자로 쓴 것을 보라'),
    (29240, '○이 후로는 누구든지 나를 괴롭게 하지 말라 내가 내 몸에 예수의 흔적을 지니고 있노라'),
    (29241, '○형제들아 우리 주 예수 그리스도의 은혜가 너희 심령에 있을지어다 아멘'),
    (29173, '그러므로 네가 이 후로는 종이 아니요 아들이니 아들이면 하나님으로 말미암아 유업을 받을 자니라'),
    (29174, '<바울이 갈라디아 교회를 염려하다> ○그러나 너희가 그 때에는 하나님을 알지 못하여 본질상 하나님이 아닌 자들에게 종 노릇 하였더니'),
    (29178, '○형제들아 내가 너희와 같이 되었은즉 너희도 나와 같이 되기를 구하노라 너희가 내게 해롭게 하지 아니하였느니라'),
    (29187, '<하갈과 사라> ○내게 말하라 율법 아래에 있고자 하는 자들아 율법을 듣지 못하였느냐'),
    (29199, '<그리스도인의 자유와 사랑> ○보라 나 바울은 너희에게 말하노니 너희가 만일 할례를 받으면 그리스도께서 너희에게 아무 유익이 없으리라'),
    (29210, '○형제들아 너희가 자유를 위하여 부르심을 입었으나 그러나 그 자유로 육체의 기회를 삼지 말고 오직 사랑으로 서로 종 노릇 하라'),
    (29213, '<육체의 일과 성령의 열매> ○내가 이르노니 너희는 성령을 따라 행하라 그리하면 육체의 욕심을 이루지 아니하리라'),
    (29222, '○만일 우리가 성령으로 살면 또한 성령으로 행할지니'),
    (29300, '<그리스도의 사랑을 알게 하시기를> ○이러므로 내가 하늘과 땅에 있는 각 족속에게'),
    (29306, '○우리 가운데서 역사하시는 능력대로 우리가 구하거나 생각하는 모든 것에 더 넘치도록 능히 하실 이에게'),
    (29244, '<하늘에 속한 신령한 복> ○찬송하리로다 하나님 곧 우리 주 예수 그리스도의 아버지께서 그리스도 안에서 하늘에 속한 모든 신령한 복을 우리에게 주시되'),
    (29256, '<바울의 기도> ○이로 말미암아 주 예수 안에서 너희 믿음과 모든 성도를 향한 사랑을 나도 듣고'),
    (29275, '<십자가로 화목하게 하시다> ○그러므로 생각하라 너희는 그 때에 육체로는 이방인이요 손으로 육체에 행한 할례를 받은 무리라 칭하는 자들로부터 할례를 받지 않은 무리라 칭함을 받는 자들이라'),
    (29315, '그러므로 이르기를 그가 위로 올라가실 때에 사로잡혔던 자들을 사로잡으시고 사람들에게 선물을 주셨다 하였도다'),
    (29324, '<옛 사람과 새 사람> ○그러므로 내가 이것을 말하며 주 안에서 증언하노니 이제부터 너희는 이방인이 그 마음의 허망한 것으로 행함 같이 행하지 말라'),
    (29332, '<하나님을 본받는 생활> ○그런즉 거짓을 버리고 각각 그 이웃과 더불어 참된 것을 말하라 이는 우리가 서로 지체가 됨이라'),
    (29354, '<그리스도의 이름으로 감사하라> ○그런즉 너희가 어떻게 행할지를 자세히 주의하여 지혜 없는 자 같이 하지 말고 오직 지혜 있는 자 같이 하여'),
    (29361, '<아내와 남편> ○아내들이여 자기 남편에게 복종하기를 주께 하듯 하라'),
    (29377, '<종과 상전> ○종들아 두려워하고 떨며 성실한 마음으로 육체의 상전에게 순종하기를 그리스도께 하듯 하라'),
    (29382, '<마귀를 대적하는 싸움> ○끝으로 너희가 주 안에서와 그 힘의 능력으로 강건하여지고'),
    (29393, '<끝 인사> ○나의 사정 곧 내가 무엇을 하는지 너희에게도 알리려 하노니 사랑을 받은 형제요 주 안에서 진실한 일꾼인 두기고가 모든 일을 너희에게 알리리라'),
    (29395, '○아버지 하나님과 주 예수 그리스도께로부터 평안과 믿음을 겸한 사랑이 형제들에게 있을지어다'),
    (29399, '<빌립보 성도들을 생각하며 간구하다> ○내가 너희를 생각할 때마다 나의 하나님께 감사하며'),
    (29408, '<바울의 매임과 복음 전파> ○형제들아 내가 당한 일이 도리어 복음 전파에 진전이 된 줄을 너희가 알기를 원하노라'),
    (29473, '<우리의 시민권은 하늘에> ○형제들아 너희는 함께 나를 본받으라 그리고 너희가 우리를 본받은 것처럼 그와 같이 행하는 자들을 눈여겨 보라'),
    (29438, '<하나님의 흠 없는 자녀로 살라> ○그러므로 나의 사랑하는 자들아 너희가 나 있을 때뿐 아니라 더욱 지금 나 없을 때에도 항상 복종하여 두렵고 떨림으로 너희 구원을 이루라'),
    (29444, '이와 같이 너희도 기뻐하고 나와 함께 기뻐하라'),
    (29445, '<디모데와 에바브로디도> ○내가 디모데를 속히 너희에게 보내기를 주 안에서 바람은 너희의 사정을 앎으로 안위를 받으려 함이니'),
    (29535, '<그리스도 안에서 행하라> ○그러므로 너희가 그리스도 예수를 주로 받았으니 그 안에서 행하되'),
    (29537, '○누가 철학과 헛된 속임수로 너희를 사로잡을까 주의하라 이것은 사람의 전통과 세상의 초등학문을 따름이요 그리스도를 따름이 아니니라'),
    (29545, '○그러므로 먹고 마시는 것과 절기나 초하루나 안식일을 이유로 누구든지 너희를 비판하지 못하게 하라'),
    (29549, '<그리스도와 함께 하는 새 사람> ○너희가 세상의 초등학문에서 그리스도와 함께 죽었거든 어찌하여 세상에 사는 것과 같이 규례에 순종하느냐'),
    (29503, '<하나님께 감사를 드리다> ○우리가 너희를 위하여 기도할 때마다 하나님 곧 우리 주 예수 그리스도의 아버지께 감사하노라'),
    (29509, '<하나님의 형상이시요 교회의 머리시라> ○이로써 우리도 듣던 날부터 너희를 위하여 기도하기를 그치지 아니하고 구하노니 너희로 하여금 모든 신령한 지혜와 총명에 하나님의 뜻을 아는 것으로 채우게 하시고'),
    (29524, '<교회를 위하여 바울이 하는 일> ○나는 이제 너희를 위하여 받는 괴로움을 기뻐하고 그리스도의 남은 고난을 그의 몸된 교회를 위하여 내 육체에 채우노라'),
    (29479, '<권면> ○내가 유오디아를 권하고 순두게를 권하노니 주 안에서 같은 마음을 품으라'),
    (29481, '○주 안에서 항상 기뻐하라 내가 다시 말하노니 기뻐하라'),
    (29485, '○끝으로 형제들아 무엇에든지 참되며 무엇에든지 경건하며 무엇에든지 옳으며 무엇에든지 정결하며 무엇에든지 사랑 받을 만하며 무엇에든지 칭찬 받을 만하며 무슨 덕이 있든지 무슨 기림이 있든지 이것들을 생각하라'),
    (29487, '<빌립보 사람들의 선물> ○내가 주 안에서 크게 기뻐함은 너희가 나를 생각하던 것이 이제 다시 싹이 남이니 너희가 또한 이를 위하여 생각은 하였으나 기회가 없었느니라'),
    (29498, '<끝 인사> ○그리스도 예수 안에 있는 성도에게 각각 문안하라 나와 함께 있는 형제들이 너희에게 문안하고'),
    (29500, '○주 예수 그리스도의 은혜가 너희 심령에 있을지어다'),
    (29597, '<데살로니가 교인들의 믿음의 본> ○우리가 너희 모두로 말미암아 항상 하나님께 감사하며 기도할 때에 너희를 기억함은'),
    (29579, '<권면> ○기도를 계속하고 기도에 감사함으로 깨어 있으라'),
    (29584, '<끝 인사> ○두기고가 내 사정을 다 너희에게 알려 주리니 그는 사랑 받는 형제요 신실한 일꾼이요 주 안에서 함께 종이 된 자니라'),
    (29587, '○나와 함께 갇힌 아리스다고와 바나바의 생질 마가와 (이 마가에 대하여 너희가 명을 받았으매 그가 이르거든 영접하라)'),
    (29595, '○나 바울은 친필로 문안하노니 내가 매인 것을 생각하라 은혜가 너희에게 있을지어다'),
    (29557, '○그러므로 땅에 있는 지체를 죽이라 곧 음란과 부정과 사욕과 악한 정욕과 탐심이니 탐심은 우상 숭배니라'),
    (29564, '○그러므로 너희는 하나님이 택하사 거룩하고 사랑 받는 자처럼 긍휼과 자비와 겸손과 온유와 오래 참음을 옷 입고'),
    (29570, '<주께 하듯 하라> ○아내들아 남편에게 복종하라 이는 주 안에서 마땅하니라'),
    (29639, '<하나님을 기쁘시게 하는 생활> 그러므로 형제들아 우리가 끝으로 주 예수 안에서 너희에게 구하고 권면하노니 너희가 마땅히 어떻게 행하며 하나님을 기쁘시게 할 수 있는지를 우리에게 배웠으니 곧 너희가 행하는 바라 더욱 많이 힘쓰라'),
    (29647, '○형제 사랑에 관하여는 너희에게 쓸 것이 없음은 너희들 자신이 하나님의 가르치심을 받아 서로 사랑함이라'),
    (29651, '<주의 강림과 죽은 자들의 부활> ○형제들아 자는 자들에 관하여는 너희가 알지 못함을 우리가 원하지 아니하노니 이는 소망 없는 다른 이와 같이 슬퍼하지 않게 하려 함이라'),
    (29631, '지금은 디모데가 너희에게로부터 와서 너희 믿음과 사랑의 기쁜 소식을 우리에게 전하고 또 너희가 항상 우리를 잘 생각하여 우리가 너희를 간절히 보고자 함과 같이 너희도 우리를 간절히 보고자 한다 하니'),
    (29636, '○하나님 우리 아버지와 우리 주 예수는 우리 길을 너희에게로 갈 수 있게 하시오며'),
    (29668, '<권면과 끝 인사> ○형제들아 우리가 너희에게 구하노니 너희 가운데서 수고하고 주 안에서 너희를 다스리며 권하는 자들을 너희가 알고'),
    (29679, '○평강의 하나님이 친히 너희를 온전히 거룩하게 하시고 또 너희의 온 영과 혼과 몸이 우리 주 예수 그리스도께서 강림하실 때에 흠 없게 보전되기를 원하노라'),
    (29681, '○형제들아 우리를 위하여 기도하라'),
    (29682, '○거룩하게 입맞춤으로 모든 형제에게 문안하라'),
    (29684, '○우리 주 예수 그리스도의 은혜가 너희에게 있을지어다'),
    (29618, '○이러므로 우리가 하나님께 끊임없이 감사함은 너희가 우리에게 들은 바 하나님의 말씀을 받을 때에 사람의 말로 받지 아니하고 하나님의 말씀으로 받음이니 진실로 그러하도다 이 말씀이 또한 너희 믿는 자 가운데에서 역사하느니라'),
    (29622, '<바울이 데살로니가에 다시 가기를 원하다> ○형제들아 우리가 잠시 너희를 떠난 것은 얼굴이요 마음은 아니니 너희 얼굴 보기를 열정으로 더욱 힘썼노라'),
    (29687, '<하나님의 공의로운 심판의 표> ○형제들아 우리가 너희를 위하여 항상 하나님께 감사할지니 이것이 당연함은 너희의 믿음이 더욱 자라고 너희가 다 각기 서로 사랑함이 풍성함이니'),
    (29709, '<가르침을 받은 전통을 지키라> ○주께서 사랑하시는 형제들아 우리가 항상 너희에 관하여 마땅히 하나님께 감사할 것은 하나님이 처음부터 너희를 택하사 성령의 거룩하게 하심과 진리를 믿음으로 구원을 받게 하심이니'),
    (29712, '○우리 주 예수 그리스도와 우리를 사랑하시고 영원한 위로와 좋은 소망을 은혜로 주신 하나님 우리 아버지께서'),
    (29789, '<그리스도 예수의 좋은 일꾼> ○네가 이것으로 형제를 깨우치면 그리스도 예수의 좋은 일꾼이 되어 믿음의 말씀과 네가 따르는 좋은 교훈으로 양육을 받으리라'),
    (29719, '<게으름을 경계하다> ○형제들아 우리 주 예수 그리스도의 이름으로 너희를 명하노니 게으르게 행하고 우리에게서 받은 전통대로 행하지 아니하는 모든 형제에게서 떠나라'),
    (29729, '<축복> ○평강의 주께서 친히 때마다 일마다 너희에게 평강을 주시고 주께서 너희 모든 사람과 함께 하시기를 원하노라'),
    (29730, '○나 바울은 친필로 문안하노니 이는 편지마다 표시로서 이렇게 쓰노라'),
    (29780, '<경건의 비밀> ○내가 속히 네게 가기를 바라나 이것을 네게 쓰는 것은'),
    (29782, '크도다 경건의 비밀이여, 그렇지 않다 하는 이 없도다 ○그는 육신으로 나타난 바 되시고 영으로 의롭다 하심을 받으시고 천사들에게 보이시고 만국에서 전파되시고 세상에서 믿은 바 되시고 영광 가운데서 올려지셨느니라'),
    (29759, '○그러므로 각처에서 남자들이 분노와 다툼이 없이 거룩한 손을 들어 기도하기를 원하노라'),
    (29816, '○잘 다스리는 장로들은 배나 존경할 자로 알되 말씀과 가르침에 수고하는 이들에게는 더욱 그리할 것이니라'),
    (29817, '성경에 일렀으되  곡식을 밟아 떠는 소의 입에 망을 씌우지 말라 하였고 또 일꾼이 그 삯을 받는 것은 마땅하다 하였느니라'),
    (29734, '<다른 교훈을 가르치지 말라> ○내가 마게도냐로 갈 때에 너를 권하여 에베소에 머물라 한 것은 어떤 사람들을 명하여 다른 교훈을 가르치지 말며'),
    (29735, '신화와 끝없는 족보에 몰두하지 말게 하려 함이라 이런 것은 믿음 안에 있는 하나님의 경륜을 이룸보다 도리어 변론을 내는 것이라'),
    (29740, '알 것은 이것이니 율법은 옳은 사람을 위하여 세운 것이 아니요 오직 불법한 자와 복종하지 아니하는 자와 경건하지 아니한 자와 죄인과 거룩하지 아니한 자와 망령된 자와 아버지를 죽이는 자와 어머니를 죽이는 자와 살인하는 자며'),
    (29743, '<은혜를 감사하다> ○나를 능하게 하신 그리스도 예수 우리 주께 내가 감사함은 나를 충성되이 여겨 내게 직분을 맡기심이니'),
    (29749, '○아들 디모데야 내가 네게 이 교훈으로써 명하노니 전에 너를 지도한 예언을 따라 그것으로 선한 싸움을 싸우며'),
    (29827, '<말씀과 경건에 관한 교훈> ○누구든지 다른 교훈을 하며 바른 말 곧 우리 주 예수 그리스도의 말씀과 경건에 관한 교훈을 따르지 아니하면'),
    (29835, '<믿음의 선한 싸움> ○오직 너 하나님의 사람아 이것들을 피하고 의와 경건과 믿음과 사랑과 인내와 온유를 따르며'),
    (29841, '○네가 이 세대에서 부한 자들을 명하여 마음을 높이지 말고 정함이 없는 재물에 소망을 두지 말고 오직 우리에게 모든 것을 후히 주사 누리게 하시는 하나님께 두며'),
    (29844, '○디모데야 망령되고 헛된 말과 거짓된 지식의 반론을 피함으로 네게 부탁한 것을 지키라'),
    (29933, '<그레데에서 해야 할 디도의 사역> ○내가 너를 그레데에 남겨 둔 이유는 남은 일을 정리하고 내가 명한 대로 각 성에 장로들을 세우게 하려 함이니'),
    (29938, '○불순종하고 헛된 말을 하며 속이는 자가 많은 중 할례파 가운데 특히 그러하니'),
    (29848, '<복음과 함께 고난을 받으라> ○내가 밤낮 간구하는 가운데 쉬지 않고 너를 생각하여 청결한 양심으로 조상적부터 섬겨 오는 하나님께 감사하고'),
    (29860, '○아시아에 있는 모든 사람이 나를 버린 이 일을 네가 아나니 그 중에는 부겔로와 허모게네도 있느니라'),
    (29915, '<사사로운 부탁> ○너는 어서 속히 내게로 오라'),
    (29925, '<끝 인사> ○브리스가와 아굴라와 및 오네시보로의 집에 문안하라'),
    (29928, '○나는 주께서 네 심령에 함께 계시기를 바라노니 은혜가 너희와 함께 있을지어다'),
    (29877, '<인정 받는 일꾼> ○너는 그들로 이 일을 기억하게 하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라 이는 유익이 하나도 없고 도리어 듣는 자들을 망하게 함이라'),
    (29959, '<선한 일을 가르치라> ○너는 이것을 말하고 권면하며 모든 권위로 책망하여 누구에게서든지 업신여김을 받지 말라'),
    (29971, '<부탁과 끝 인사> ○내가 아데마나 두기고를 네게 보내리니 그 때에 네가 급히 니고볼리로 내게 오라 내가 거기서 겨울을 지내기로 작정하였노라'),
    (29974, '○나와 함께 있는 자가 다 네게 문안하니 믿음 안에서 우리를 사랑하는 자들에게 너도 문안하라 ○은혜가 너희 무리에게 있을지어다'),
    (30053, '이미 믿는 우리들은 저 안식에 들어가는도다 그가 말씀하신 바와 같으니 내가 노하여 맹세한 바와 같이 그들이 내 안식에 들어오지 못하리라 하셨다 하였으나 세상을 창조할 때부터 그 일이 이루어졌느니라'),
    (30064, '<큰 대제사장이신 예수> ○그러므로 우리에게 큰 대제사장이 계시니 승천하신 이 곧 하나님의 아들 예수시라 우리가 믿는 도리를 굳게 잡을지어다'),
    (30015, '천사들을 통하여 하신 말씀이 견고하게 되어 모든 범죄함과 순종하지 아니함이 공정한 보응을 받았거든'),
    (30018, '<구원의 창시자> ○하나님이 우리가 말하는 바 장차 올 세상을 천사들에게 복종하게 하심이 아니니라'),
    (30020, '그를 잠시 동안 천사보다 못하게 하시며 영광과 존귀로 관을 씌우시며'),
    (30021, '만물을 그 발 아래에 복종하게 하셨느니라 하였으니 만물로 그에게 복종하게 하셨은즉 복종하지 않은 것이 하나도 없어야 하겠으나 지금 우리가 만물이 아직 그에게 복종하고 있는 것을 보지 못하고'),
    (30022, '오직 우리가 천사들보다 잠시 동안 못하게 하심을 입은 자 곧 죽음의 고난 받으심으로 말미암아 영광과 존귀로 관을 쓰신 예수를 보니 이를 행하심은 하나님의 은혜로 말미암아 모든 사람을 위하여 죽음을 맛보려 하심이라'),
    (29978, '<빌레몬의 믿음과 사랑> ○내가 항상 내 하나님께 감사하고 기도할 때에 너를 말함은'),
    (29982, '<오네시모를 위하여 간구하다> ○이러므로 내가 그리스도 안에서 아주 담대하게 네게 마땅한 일로 명할 수도 있으나'),
    (29986, '네게 그를 돌려 보내노니 그는 내 심복이라'),
    (29990, '이 후로는 종과 같이 대하지 아니하고 종 이상으로 곧 사랑 받는 형제로 둘 자라 내게 특별히 그러하거든 하물며 육신과 주 안에서 상관된 네게랴'),
    (29997, '<끝 인사> ○그리스도 예수 안에서 나와 함께 갇힌 자 에바브라와'),
    (29999, '○우리 주 예수 그리스도의 은혜가 너희 심령과 함께 있을지어다'),
    (30077, '<변절을 경계하시다> ○멜기세덱에 관하여는 우리가 할 말이 많으나 너희가 듣는 것이 둔하므로 설명하기 어려우니라'),
    (30078, '때가 오래 되었으므로 너희가 마땅히 선생이 되었을 터인데 너희가 다시 하나님의 말씀의 초보에 대하여 누구에게서 가르침을 받아야 할 처지이니 단단한 음식은 못 먹고 젖이나 먹어야 할 자가 되었도다'),
    (30089, '○사랑하는 자들아 우리가 이같이 말하나 너희에게는 이보다 더 좋은 것 곧 구원에 속한 것이 있음을 확신하노라'),
    (30093, '<하나님의 확실한 약속> ○하나님이 아브라함에게 약속하실 때에 가리켜 맹세할 자가 자기보다 더 큰 이가 없으므로 자기를 가리켜 맹세하여'),
    (30137, '또 주께서 이르시기를 이 언약은 내가 그들의 열조의 손을 잡고 애굽 땅에서 인도하여 내던 날에 그들과 맺은 언약과 같지 아니하도다 그들은 내 언약 안에 머물러 있지 아니하므로 내가 그들을 돌보지 아니하였노라'),
    (30138, '또 주께서 이르시되 그 날 후에 내가 이스라엘 집과 맺을 언약은 이것이니 내 법을 그들의 생각에 두고 그들의 마음에 이것을 기록하리라 나는 그들에게 하나님이 되고 그들은 내게 백성이 되리라'),
    (30104, '○이 사람이 얼마나 높은가를 생각해 보라 조상 아브라함도 노략물 중 십분의 일을 그에게 주었느니라'),
    (30111, '○레위 계통의 제사 직분으로 말미암아 온전함을 얻을 수 있었으면 (백성이 그 아래에서 율법을 받았으니) 어찌하여 아론의 반차를 따르지 않고 멜기세덱의 반차를 따르는 다른 한 제사장을 세울 필요가 있느냐'),
    (30126, '○이러한 대제사장은 우리에게 합당하니 거룩하고 악이 없고 더러움이 없고 죄인에게서 떠나 계시고 하늘보다 높이 되신 이라'),
    (30152, '○그리스도께서는 장래 좋은 일의 대제사장으로 오사 손으로 짓지 아니한 것 곧 이 창조에 속하지 아니한 더 크고 온전한 장막으로 말미암아'),
    (30164, '<그리스도의 희생으로 이루어진 속죄> ○그러므로 하늘에 있는 것들의 모형은 이런 것들로써 정결하게 할 필요가 있었으나 하늘에 있는 그것들은 이런 것들보다 더 좋은 제물로 할지니라'),
    (30188, '<소망을 굳게 잡으라> ○그러므로 형제들아 우리가 예수의 피를 힘입어 성소에 들어갈 담력을 얻었나니'),
    (30195, '○우리가 진리를 아는 지식을 받은 후 짐짓 죄를 범한즉 다시 속죄하는 제사가 없고'),
    (30201, '○전날에 너희가 빛을 받은 후에 고난의 큰 싸움을 견디어 낸 것을 생각하라'),
    (30221, '○이 사람들은 다 믿음을 따라 죽었으며 약속을 받지 못하였으되 그것들을 멀리서 보고 환영하며 또 땅에서는 외국인과 나그네임을 증언하였으니'),
    (30225, '○아브라함은 시험을 받을 때에 믿음으로 이삭을 드렸으니 그는 약속들을 받은 자로되 그 외아들을 드렸느니라'),
    (30262, '<하나님의 은혜를 거역한 자들에게 주는 경고> ○모든 사람과 더불어 화평함과 거룩함을 따르라 이것이 없이는 아무도 주를 보지 못하리라'),
    (30266, '○너희는 만질 수 있고 불이 붙는 산과 침침함과 흑암과 폭풍과'),
    (30278, '형제 사랑하기를 계속하고'),
    (30294, '너희를 인도하는 자들에게 순종하고 복종하라 그들은 너희 영혼을 위하여 경성하기를 자신들이 청산할 자인 것 같이 하느니라 그들로 하여금 즐거움으로 이것을 하게 하고 근심으로 하게 하지 말라 그렇지 않으면 너희에게 유익이 없느니라'),
    (30295, '○우리를 위하여 기도하라 우리가 모든 일에 선하게 행하려 하므로 우리에게 선한 양심이 있는 줄을 확신하노니'),
    (30297, '○양들의 큰 목자이신 우리 주 예수를 영원한 언약의 피로 죽은 자 가운데서 이끌어 내신 평강의 하나님이'),
    (30298, '모든 선한 일에 너희를 온전하게 하사 자기 뜻을 행하게 하시고 그 앞에 즐거운 것을 예수 그리스도로 말미암아 우리 가운데서 이루시기를 원하노라 영광이 그에게 세세무궁토록 있을지어다 아멘'),
    (30299, '○형제들아 내가 너희를 권하노니 권면의 말을 용납하라 내가 간단히 너희에게 썼느니라'),
    (30301, '○너희를 인도하는 자들과 및 모든 성도들에게 문안하라 이달리야에서 온 자들도 너희에게 문안하느니라'),
    (30302, '○은혜가 너희 모든 사람에게 있을지어다'),
    (30384, '<서로 비방하지 말라> ○형제들아 서로 비방하지 말라 형제를 비방하는 자나 형제를 판단하는 자는 곧 율법을 비방하고 율법을 판단하는 것이라 네가 만일 율법을 판단하면 율법의 준행자가 아니요 재판관이로다'),
    (30386, '<허탄한 생각을 경고하다> ○들으라 너희 중에 말하기를 오늘이나 내일이나 우리가 어떤 도시에 가서 거기서 일 년을 머물며 장사하여 이익을 보리라 하는 자들아'),
    (30343, '<행함이 없는 믿음은 죽은 것> ○내 형제들아 만일 사람이 믿음이 있노라 하고 행함이 없으면 무슨 유익이 있으리요 그 믿음이 능히 자기를 구원하겠느냐'),
    (30397, '<인내와 기도> ○그러므로 형제들아 주께서 강림하시기까지 길이 참으라 보라 농부가 땅에서 나는 귀한 열매를 바라고 길이 참아 이른 비와 늦은 비를 기다리나니'),
    (30402, '○내 형제들아 무엇보다도 맹세하지 말지니 하늘로나 땅으로나 아무 다른 것으로도 맹세하지 말고 오직 너희가 그렇다고 생각하는 것은 그렇다 하고 아니라고 생각하는 것은 아니라 하여 정죄 받음을 면하라'),
    (30403, '○너희 중에 고난 당하는 자가 있느냐 그는 기도할 것이요 즐거워하는 자가 있느냐 그는 찬송할지니라'),
    (30409, '○내 형제들아 너희 중에 미혹되어 진리를 떠난 자를 누가 돌아서게 하면'),
    (30304, '<믿음과 지혜> ○내 형제들아 너희가 여러 가지 시험을 당하거든 온전히 기쁘게 여기라'),
    (30307, '○너희 중에 누구든지 지혜가 부족하거든 모든 사람에게 후히 주시고 꾸짖지 아니하시는 하나님께 구하라 그리하면 주시리라'),
    (30311, '<낮은 형제, 부한 자,> ○낮은 형제는 자기의 높음을 자랑하고'),
    (30314, '<시험에 견디어 낸 자> ○시험을 참는 자는 복이 있나니 이는 시련을 견디어 낸 자가 주께서 자기를 사랑하는 자들에게 약속하신 생명의 면류관을 얻을 것이기 때문이라'),
    (30321, '<말씀을 들음과 행함> ○내 사랑하는 형제들아 너희가 알지니 사람마다 듣기는 속히 하고 말하기는 더디 하며 성내기도 더디 하라'),
    (30412, '곧 하나님 아버지의 미리 아심을 따라 성령이 거룩하게 하심으로 순종함과 예수 그리스도의 피 뿌림을 얻기 위하여 택하심을 받은 자들에게 편지하노니 은혜와 평강이 너희에게 더욱 많을지어다'),
    (30413, '<산 소망> ○우리 주 예수 그리스도의 아버지 하나님을 찬송하리로다 그의 많으신 긍휼대로 예수 그리스도를 죽은 자 가운데서 부활하게 하심으로 말미암아 우리를 거듭나게 하사 산 소망이 있게 하시며'),
    (30422, '이 섬긴 바가 자기를 위한 것이 아니요 너희를 위한 것임이 계시로 알게 되었으니 이것은 하늘로부터 보내신 성령을 힘입어 복음을 전하는 자들로 이제 너희에게 알린 것이요 천사들도 살펴 보기를 원하는 것이니라'),
    (30423, '<모든 행실에 거룩한 자가 되라> ○그러므로 너희 마음의 허리를 동이고 근신하여 예수 그리스도께서 나타나실 때에 너희에게 가져다 주실 은혜를 온전히 바랄지어다'),
    (30368, '<위로부터 난 지혜> ○너희 중에 지혜와 총명이 있는 자가 누구냐 그는 선행으로 말미암아 지혜의 온유함으로 그 행함을 보일지니라'),
    (30444, '그러나 너희는 택하신 족속이요 왕 같은 제사장들이요 거룩한 나라요 그의 소유가 된 백성이니 이는 너희를 어두운 데서 불러 내어 그의 기이한 빛에 들어가게 하신 이의 아름다운 덕을 선포하게 하려 하심이라'),
    (30446, '<하나님의 종과 같이 하라> ○사랑하는 자들아 거류민과 나그네 같은 너희를 권하노니 영혼을 거슬러 싸우는 육체의 정욕을 제어하라'),
    (30448, '○인간의 모든 제도를 주를 위하여 순종하되 혹은 위에 있는 왕이나'),
    (30453, '<그리스도의 고난> ○사환들아 범사에 두려워함으로 주인들에게 순종하되 선하고 관용하는 자들에게만 아니라 또한 까다로운 자들에게도 그리하라'),
    (30511, '모든 은혜의 하나님 곧 그리스도 안에서 너희를 부르사 자기의 영원한 영광에 들어가게 하신 이가 잠깐 고난을 당한 너희를 친히 온전하게 하시며 굳건하게 하시며 강하게 하시며 터를 견고하게 하시리라'),
    (30513, '<끝 인사> ○내가 신실한 형제로 아는 실루아노로 말미암아 너희에게 간단히 써서 권하고 이것이 하나님의 참된 은혜임을 증언하노니 너희는 이 은혜에 굳게 서라'),
    (30515, '너희는 사랑의 입맞춤으로 서로 문안하라 ○그리스도 안에 있는 너희 모든 이에게 평강이 있을지어다'),
    (30467, '○남편들아 이와 같이 지식을 따라 너희 아내와 동거하고 그를 더 연약한 그릇이요 또 생명의 은혜를 함께 이어받을 자로 알아 귀히 여기라 이는 너희 기도가 막히지 아니하게 하려 함이라'),
    (30468, '<선을 위한 고난> ○마지막으로 말하노니 너희가 다 마음을 같이하여 동정하며 형제를 사랑하며 불쌍히 여기며 겸손하며'),
    (30473, '○또 너희가 열심으로 선을 행하면 누가 너희를 해하리요'),
    (30489, '○만물의 마지막이 가까이 왔으니 그러므로 너희는 정신을 차리고 근신하여 기도하라'),
    (30493, '만일 누가 말하려면 하나님의 말씀을 하는 것 같이 하고 누가 봉사하려면 하나님이 공급하시는 힘으로 하는 것 같이 하라 이는 범사에 예수 그리스도로 말미암아 하나님이 영광을 받으시게 하려 함이니 그에게 영광과 권능이 세세에 무궁하도록 있느니라 아멘'),
    (30494, '<그리스도인이 받을 고난> ○사랑하는 자들아 너희를 연단하려고 오는 불 시험을 이상한 일 당하는 것 같이 이상히 여기지 말고'),
    (30527, '<그리스도의 영광과 성경의 예언> ○그러므로 너희가 이것을 알고 이미 있는 진리에 서 있으나 내가 항상 너희에게 생각나게 하려 하노라'),
    (30537, '<거짓 선지자들과 거짓 선생들> 그러나 백성 가운데 또한 거짓 선지자들이 일어났었나니 이와 같이 너희 중에도 거짓 선생들이 있으리라 그들은 멸망하게 할 이단을 가만히 끌어들여 자기들을 사신 주를 부인하고 임박한 멸망을 스스로 취하는 자들이라'),
    (30581, '<하나님은 빛이시다> ○우리가 그에게서 듣고 너희에게 전하는 소식은 이것이니 곧 하나님은 빛이시라 그에게는 어둠이 조금도 없으시다는 것이니라'),
    (30566, '○사랑하는 자들아 주께는 하루가 천 년 같고 천 년이 하루 같다는 이 한 가지를 잊지 말라'),
    (30572, '○그러므로 사랑하는 자들아 너희가 이것을 바라보나니 주 앞에서 점도 없고 흠도 없이 평강 가운데서 나타나기를 힘쓰라'),
    (30574, '또 그 모든 편지에도 이런 일에 관하여 말하였으되 그 중에 알기 어려운 것이 더러 있으니 무식한 자들과 굳세지 못한 자들이 다른 성경과 같이 그것도 억지로 풀다가 스스로 멸망에 이르느니라'),
    (30576, '오직 우리 주 곧 구주 예수 그리스도의 은혜와 그를 아는 지식에서 자라 가라 영광이 이제와 영원한 날까지 그에게 있을지어다'),
    (30617, '사랑하는 자들아 우리가 지금은 하나님의 자녀라 장래에 어떻게 될지는 아직 나타나지 아니하였으나 그가 나타나시면 우리가 그와 같을 줄을 아는 것은 그의 참모습 그대로 볼 것이기 때문이니'),
    (30628, '<행함과 진실함으로 사랑하자> ○형제들아 세상이 너희를 미워하여도 이상히 여기지 말라'),
    (30587, '<대언자이신 예수 그리스도> 나의 자녀들아 내가 이것을 너희에게 씀은 너희로 죄를 범하지 않게 하려 함이라 만일 누가 죄를 범하여도 아버지 앞에서 우리에게 대언자가 있으니 곧 의로우신 예수 그리스도시라'),
    (30593, '<옛 계명과 새 계명> ○사랑하는 자들아 내가 새 계명을 너희에게 쓰는 것이 아니라 너희가 처음부터 가진 옛 계명이니 이 옛 계명은 너희가 들은 바 말씀이거니와'),
    (30598, '○자녀들아 내가 너희에게 쓰는 것은 너희 죄가 그의 이름으로 말미암아 사함을 받았음이요'),
    (30600, '아이들아 내가 너희에게 쓴 것은 너희가 아버지를 알았음이요 아비들아 내가 너희에게 쓴 것은 너희가 태초부터 계신 이를 알았음이요 청년들아 내가 너희에게 쓴 것은 너희가 강하고 하나님의 말씀이 너희 안에 거하시며 너희가 흉악한 자를 이기었음이라'),
    (30604, '<적그리스도와 하나님의 자녀> ○아이들아 지금은 마지막 때라 적그리스도가 오리라는 말을 너희가 들은 것과 같이 지금도 많은 적그리스도가 일어났으니 그러므로 우리가 마지막 때인 줄 아노라'),
    (30613, '너희는 주께 받은 바 기름 부음이 너희 안에 거하나니 아무도 너희를 가르칠 필요가 없고 오직 그의 기름 부음이 모든 것을 너희에게 가르치며 또 참되고 거짓이 없으니 너희를 가르치신 그대로 주 안에 거하라'),
    (30646, '<하나님은 사랑이시다> ○사랑하는 자들아 우리가 서로 사랑하자 사랑은 하나님께 속한 것이니 사랑하는 자마다 하나님으로부터 나서 하나님을 알고'),
    (30673, '<영생을 알게 하려 함이라> ○내가 하나님의 아들의 이름을 믿는 너희에게 이것을 쓰는 것은 너희로 하여금 너희에게 영생이 있음을 알게 하려 함이라'),
    (30676, '누구든지 형제가 사망에 이르지 아니하는 죄 범하는 것을 보거든 구하라 그리하면 사망에 이르지 아니하는 범죄자들을 위하여 그에게 생명을 주시리라 사망에 이르는 죄가 있으니 이에 관하여 나는 구하라 하지 않노라'),
    (30678, '○하나님께로부터 난 자는 다 범죄하지 아니하는 줄을 우리가 아노라 하나님께로부터 나신 자가 그를 지키시매 악한 자가 그를 만지지도 못하느니라'),
    (30680, '또 아는 것은 하나님의 아들이 이르러 우리에게 지각을 주사 우리로 참된 자를 알게 하신 것과 또한 우리가 참된 자 곧 그의 아들 예수 그리스도 안에 있는 것이니 그는 참 하나님이시요 영생이시라'),
    (30685, '<진리와 사랑> ○너의 자녀들 중에 우리가 아버지께 받은 계명대로 진리를 행하는 자를 내가 보니 심히 기쁘도다'),
    (30693, '<끝 인사> ○내가 너희에게 쓸 것이 많으나 종이와 먹으로 쓰기를 원하지 아니하고 오히려 너희에게 가서 대면하여 말하려 하니 이는 너희 기쁨을 충만하게 하려 함이라'),
    (30696, '○사랑하는 자여 네 영혼이 잘됨 같이 네가 범사에 잘되고 강건하기를 내가 간구하노라'),
    (30699, '<영접함과 내쫓음> ○사랑하는 자여 네가 무엇이든지 형제 곧 나그네 된 자들에게 행하는 것은 신실한 일이니'),
    (30703, '○내가 두어 자를 교회에 썼으나 그들 중에 으뜸되기를 좋아하는 디오드레베가 우리를 맞아들이지 아니하니'),
    (30707, '<끝 인사> ○내가 네게 쓸 것이 많으나 먹과 붓으로 쓰기를 원하지 아니하고'),
    (30738, '○요한은 아시아에 있는 일곱 교회에 편지하노니 이제도 계시고 전에도 계셨고 장차 오실 이와 그의 보좌 앞에 있는 일곱 영과'),
    (30739, '또 충성된 증인으로 죽은 자들 가운데에서 먼저 나시고 땅의 임금들의 머리가 되신 예수 그리스도로 말미암아 은혜와 평강이 너희에게 있기를 원하노라 우리를 사랑하사 그의 피로 우리 죄에서 우리를 해방하시고'),
    (30742, '○주 하나님이 이르시되 나는 알파와 오메가라 이제도 있고 전에도 있었고 장차 올 자요 전능한 자라 하시더라'),
    (30743, '<그리스도의 명령> ○나 요한은 너희 형제요 예수의 환난과 나라와 참음에 동참하는 자라 하나님의 말씀과 예수를 증언하였음으로 말미암아 밧모라 하는 섬에 있었더니'),
    (30712, '<거짓 교사들에게 내릴 심판> ○사랑하는 자들아 우리가 일반으로 받은 구원에 관하여 내가 너희에게 편지하려는 생각이 간절하던 차에 성도에게 단번에 주신 믿음의 도를 위하여 힘써 싸우라는 편지로 너희를 권하여야 할 필요를 느꼈노니'),
    (30713, '이는 가만히 들어온 사람 몇이 있음이라 그들은 옛적부터 이 판결을 받기로 미리 기록된 자니 경건하지 아니하여 우리 하나님의 은혜를 도리어 방탕한 것으로 바꾸고 홀로 하나이신 주재 곧 우리 주 예수 그리스도를 부인하는 자니라'),
    (30714, '○너희가 본래 모든 사실을 알고 있으나 내가 너희로 다시 생각나게 하고자 하노라 주께서 백성을 애굽에서 구원하여 내시고 후에 믿지 아니하는 자들을 멸하셨으며'),
    (30724, '이는 뭇 사람을 심판하사 모든 경건하지 않은 자가 경건하지 않게 행한 모든 경건하지 않은 일과 또 경건하지 않은 죄인들이 주를 거슬러 한 모든 완악한 말로 말미암아 그들을 정죄하려 하심이라 하였느니라'),
    (30726, '<훈계와 권면> ○사랑하는 자들아 너희는 우리 주 예수 그리스도의 사도들이 미리 한 말을 기억하라'),
    (30733, '<축복> ○능히 너희를 보호하사 거침이 없게 하시고 너희로 그 영광 앞에 흠이 없이 기쁨으로 서게 하실 이'),
    (30806, '<하늘의 예배> 이 일 후에 내가 보니 하늘에 열린 문이 있는데 내가 들은 바 처음에 내게 말하던 나팔 소리 같은 그 음성이 이르되 이리로 올라오라 이 후에 마땅히 일어날 일들을 내가 네게 보이리라 하시더라'),
    (30813, '네 생물은 각각 여섯 날개를 가졌고 그 안과 주위에는 눈들이 가득하더라 그들이 밤낮 쉬지 않고 이르기를 거룩하다 거룩하다 거룩하다 주 하나님 곧 전능하신 이여 전에도 계셨고 이제도 계시고 장차 오실 이시라 하고'),
    (30762, '<서머나 교회에 보내는 말씀> ○서머나 교회의 사자에게 편지하라 처음이며 마지막이요 죽었다가 살아나신 이가 이르시되'),
    (30764, '너는 장차 받을 고난을 두려워하지 말라 볼지어다 마귀가 장차 너희 가운데에서 몇 사람을 옥에 던져 시험을 받게 하리니 너희가 십 일 동안 환난을 받으리라 네가 죽도록 충성하라 그리하면 내가 생명의 관을 네게 주리라'),
    (30766, '<버가모 교회에 보내는 말씀> ○버가모 교회의 사자에게 편지하라 좌우에 날선 검을 가지신 이가 이르시되'),
    (30767, '네가 어디에 사는지를 내가 아노니 거기는 사탄의 권좌가 있는 데라 네가 내 이름을 굳게 잡아서 내 충성된 증인 안디바가 너희 가운데 곧 사탄이 사는 곳에서 죽임을 당할 때에도 나를 믿는 믿음을 저버리지 아니하였도다'),
    (30768, '그러나 네게 두어 가지 책망할 것이 있나니 거기 네게 발람의 교훈을 지키는 자들이 있도다 발람이 발락을 가르쳐 이스라엘 자손 앞에 걸림돌을 놓아 우상의 제물을 먹게 하였고 또 행음하게 하였느니라'),
    (30771, '귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 그에게는 내가 감추었던 만나를 주고 또 흰 돌을 줄 터인데 그 돌 위에 새 이름을 기록한 것이 있나니 받는 자 밖에는 그 이름을 알 사람이 없느니라'),
    (30772, '<두아디라 교회에 보내는 말씀> ○두아디라 교회의 사자에게 편지하라 그 눈이 불꽃 같고 그 발이 빛난 주석과 같은 하나님의 아들이 이르시되'),
    (30783, '귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다'),
    (30822, '내가 또 보니 보좌와 네 생물과 장로들 사이에 한 어린 양이 서 있는데 일찍이 죽임을 당한 것 같더라 그에게 일곱 뿔과 일곱 눈이 있으니 이 눈들은 온 땅에 보내심을 받은 하나님의 일곱 영이더라'),
    (30790, '<빌라델비아 교회에 보내는 말씀> ○빌라델비아 교회의 사자에게 편지하라 거룩하고 진실하사 다윗의 열쇠를 가지신 이 곧 열면 닫을 사람이 없고 닫으면 열 사람이 없는 그가 이르시되'),
    (30795, '이기는 자는 내 하나님 성전에 기둥이 되게 하리니 그가 결코 다시 나가지 아니하리라 내가 하나님의 이름과 하나님의 성 곧 하늘에서 내 하나님께로부터 내려오는 새 예루살렘의 이름과 나의 새 이름을 그이 위에 기록하리라'),
    (30797, '<라오디게아 교회에 보내는 말씀> ○라오디게아 교회의 사자에게 편지하라 아멘이시요 충성되고 참된 증인이시요 하나님의 창조의 근본이신 이가 이르시되'),
    (30833, '○둘째 인을 떼실 때에 내가 들으니 둘째 생물이 말하되 오라 하니'),
    (30835, '○셋째 인을 떼실 때에 내가 들으니 셋째 생물이 말하되 오라 하기로 내가 보니 검은 말이 나오는데 그 탄 자가 손에 저울을 가졌더라'),
    (30837, '○넷째 인을 떼실 때에 내가 넷째 생물의 음성을 들으니 말하되 오라 하기로'),
    (30839, '○다섯째 인을 떼실 때에 내가 보니 하나님의 말씀과 그들이 가진 증거로 말미암아 죽임을 당한 영혼들이 제단 아래에 있어'),
    (30842, '○내가 보니 여섯째 인을 떼실 때에 큰 지진이 나며 해가 검은 털로 짠 상복 같이 검어지고 달은 온통 피 같이 되며'),
    (30867, '○또 다른 천사가 와서 제단 곁에 서서 금 향로를 가지고 많은 향을 받았으니 이는 모든 성도의 기도와 합하여 보좌 앞 금 제단에 드리고자 함이라'),
    (30870, '<나팔 소리> ○일곱 나팔을 가진 일곱 천사가 나팔 불기를 준비하더라'),
    (30871, '○첫째 천사가 나팔을 부니 피 섞인 우박과 불이 나와서 땅에 쏟아지매 땅의 삼분의 일이 타 버리고 수목의 삼분의 일도 타 버리고 각종 푸른 풀도 타 버렸더라'),
    (30872, '○둘째 천사가 나팔을 부니 불 붙는 큰 산과 같은 것이 바다에 던져지매 바다의 삼분의 일이 피가 되고'),
    (30874, '○셋째 천사가 나팔을 부니 횃불 같이 타는 큰 별이 하늘에서 떨어져 강들의 삼분의 일과 여러 물샘에 떨어지니'),
    (30875, '이 별 이름은 쓴 쑥이라 물의 삼분의 일이 쓴 쑥이 되매 그 물이 쓴물이 되므로 많은 사람이 죽더라'),
    (30876, '○넷째 천사가 나팔을 부니 해 삼분의 일과 달 삼분의 일과 별들의 삼분의 일이 타격을 받아 그 삼분의 일이 어두워지니 낮 삼분의 일은 비추임이 없고 밤도 그러하더라'),
    (30877, '○내가 또 보고 들으니 공중에 날아가는 독수리가 큰 소리로 이르되 땅에 사는 자들에게 화, 화, 화가 있으리니 이는 세 천사들이 불어야 할 나팔 소리가 남아 있음이로다 하더라'),
    (30852, '<각 나라에서 온 무리> ○유다 지파 중에 인침을 받은 자가 일만 이천이요 르우벤 지파 중에 일만 이천이요 갓 지파 중에 일만 이천이요'),
    (30889, '○첫째 화는 지나갔으나 보라 아직도 이 후에 화 둘이 이르리로다'),
    (30890, '○여섯째 천사가 나팔을 불매 내가 들으니 하나님 앞 금 제단 네 뿔에서 한 음성이 나서'),
    (30923, '○둘째 화는 지나갔으나 보라 셋째 화가 속히 이르는도다'),
    (30924, '<일곱째 나팔 소리> ○일곱째 천사가 나팔을 불매 하늘에 큰 음성들이 나서 이르되 세상 나라가 우리 주와 그의 그리스도의 나라가 되어 그가 세세토록 왕 노릇 하시리로다 하니'),
    (30927, '이방들이 분노하매 주의 진노가 내려 죽은 자를 심판하시며 종 선지자들과 성도들과 또 작은 자든지 큰 자든지 주의 이름을 경외하는 자들에게 상 주시며 또 땅을 망하게 하는 자들을 멸망시키실 때로소이다 하더라'),
    (30928, '○이에 하늘에 있는 하나님의 성전이 열리니 성전 안에 하나님의 언약궤가 보이며 또 번개와 음성들과 우레와 지진과 큰 우박이 있더라'),
    (30935, '○하늘에 전쟁이 있으니 미가엘과 그의 사자들이 용과 더불어 싸울새 용과 그의 사자들도 싸우나'),
    (30938, '내가 또 들으니 하늘에 큰 음성이 있어 이르되 이제 우리 하나님의 구원과 능력과 나라와 또 그의 그리스도의 권세가 나타났으니 우리 형제들을 참소하던 자 곧 우리 하나님 앞에서 밤낮 참소하던 자가 쫓겨났고'),
    (30941, '○용이 자기가 땅으로 내쫓긴 것을 보고 남자를 낳은 여자를 박해하는지라'),
    (30956, '○내가 보매 또 다른 짐승이 땅에서 올라오니 어린 양 같이 두 뿔이 있고 용처럼 말을 하더라'),
    (30993, '○첫째 천사가 가서 그 대접을 땅에 쏟으매 짐승의 표를 받은 사람들과 그 우상에게 경배하는 자들에게 악하고 독한 종기가 나더라'),
    (30994, '○둘째 천사가 그 대접을 바다에 쏟으매 바다가 곧 죽은 자의 피 같이 되니 바다 가운데 모든 생물이 죽더라'),
    (30995, '○셋째 천사가 그 대접을 강과 물 근원에 쏟으매 피가 되더라'),
    (30999, '○넷째 천사가 그 대접을 해에 쏟으매 해가 권세를 받아 불로 사람들을 태우니'),
    (31001, '○또 다섯째 천사가 그 대접을 짐승의 왕좌에 쏟으니 그 나라가 곧 어두워지며 사람들이 아파서 자기 혀를 깨물고'),
    (31003, '○또 여섯째 천사가 그 대접을 큰 강 유브라데에 쏟으매 강물이 말라서 동방에서 오는 왕들의 길이 예비되었더라'),
    (31008, '○일곱째 천사가 그 대접을 공중에 쏟으매 큰 음성이 성전에서 보좌로부터 나서 이르되 되었다 하시니'),
    (30967, '이 사람들은 여자와 더불어 더럽히지 아니하고 순결한 자라 어린 양이 어디로 인도하든지 따라가는 자며 사람 가운데에서 속량함을 받아 처음 익은 열매로 하나님과 어린 양에게 속한 자들이니'),
    (30969, '<세 천사가 전하는 말> ○또 보니 다른 천사가 공중에 날아가는데 땅에 거주하는 자들 곧 모든 민족과 종족과 방언과 백성에게 전할 영원한 복음을 가졌더라'),
    (30971, '○또 다른 천사 곧 둘째가 그 뒤를 따라 말하되 무너졌도다 무너졌도다 큰 성 바벨론이여 모든 나라에게 그의 음행으로 말미암아 진노의 포도주를 먹이던 자로다 하더라'),
    (30972, '○또 다른 천사 곧 셋째가 그 뒤를 따라 큰 음성으로 이르되 만일 누구든지 짐승과 그의 우상에게 경배하고 이마에나 손에 표를 받으면'),
    (30976, '○또 내가 들으니 하늘에서 음성이 나서 이르되 기록하라 지금 이후로 주 안에서 죽는 자들은 복이 있도다 하시매 성령이 이르시되 그러하다 그들이 수고를 그치고 쉬리니 이는 그들의 행한 일이 따름이라 하시더라'),
    (30977, '<마지막 수확> ○또 내가 보니 흰 구름이 있고 구름 위에 인자와 같은 이가 앉으셨는데 그 머리에는 금 면류관이 있고 그 손에는 예리한 낫을 가졌더라'),
    (30980, '<마지막 재난을 가지고 온 천사> ○또 다른 천사가 하늘에 있는 성전에서 나오는데 역시 예리한 낫을 가졌더라'),
    (30985, '○또 내가 보니 불이 섞인 유리 바다 같은 것이 있고 짐승과 그의 우상과 그의 이름의 수를 이기고 벗어난 자들이 유리 바다 가에 서서 하나님의 거문고를 가지고'),
    (30988, '○또 이 일 후에 내가 보니 하늘에 증거 장막의 성전이 열리며'),
    (31034, '○또 내가 들으니 하늘로부터 다른 음성이 나서 이르되 내 백성아, 거기서 나와 그의 죄에 참여하지 말고 그가 받을 재앙들을 받지 말라'),
    (31037, '그가 얼마나 자기를 영화롭게 하였으며 사치하였든지 그만큼 고통과 애통함으로 갚아 주라 그가 마음에 말하기를 나는 여왕으로 앉은 자요 과부가 아니라 결단코 애통함을 당하지 아니하리라 하니'),
    (31051, '○이에 한 힘 센 천사가 큰 맷돌 같은 돌을 들어 바다에 던져 이르되 큰 성 바벨론이 이같이 비참하게 던져져 결코 다시 보이지 아니하리로다'),
    (31052, '또 거문고 타는 자와 풍류하는 자와 퉁소 부는 자와 나팔 부는 자들의 소리가 결코 다시 네 안에서 들리지 아니하고 어떠한 세공업자든지 결코 다시 네 안에서 보이지 아니하고 또 맷돌 소리가 결코 다시 네 안에서 들리지 아니하고'),
    (31020, '네가 본 짐승은 전에 있었다가 지금은 없으나 장차 무저갱으로부터 올라와 멸망으로 들어갈 자니 땅에 사는 자들로서 창세 이후로 그 이름이 생명책에 기록되지 못한 자들이 이전에 있었다가 지금은 없으나 장차 나올 짐승을 보고 놀랍게 여기리라'),
    (31064, '내가 그 발 앞에 엎드려 경배하려 하니 그가 나에게 말하기를 나는 너와 및 예수의 증언을 받은 네 형제들과 같이 된 종이니 삼가 그리하지 말고 오직 하나님께 경배하라 예수의 증언은 예언의 영이라 하더라'),
    (31065, '<백마를 탄 자> ○또 내가 하늘이 열린 것을 보니 보라 백마와 그것을 탄 자가 있으니 그 이름은 충신과 진실이라 그가 공의로 심판하며 싸우더라'),
    (31071, '○또 내가 보니 한 천사가 태양 안에 서서 공중에 나는 모든 새를 향하여 큰 음성으로 외쳐 이르되 와서 하나님의 큰 잔치에 모여'),
    (31073, '○또 내가 보매 그 짐승과 땅의 임금들과 그들의 군대들이 모여 그 말 탄 자와 그의 군대와 더불어 전쟁을 일으키다가'),
    (31074, '짐승이 잡히고 그 앞에서 표적을 행하던 거짓 선지자도 함께 잡혔으니 이는 짐승의 표를 받고 그의 우상에게 경배하던 자들을 표적으로 미혹하던 자라 이 둘이 산 채로 유황불 붙는 못에 던져지고'),
    (31079, '○또 내가 보좌들을 보니 거기에 앉은 자들이 있어 심판하는 권세를 받았더라 또 내가 보니 예수를 증언함과 하나님의 말씀 때문에 목 베임을 당한 자들의 영혼들과 또 짐승과 그의 우상에게 경배하지 아니하고 그들의 이마와 손에 그의 표를 받지 아니한 자들이 살아서 그리스도와 더불어 천 년 동안 왕 노릇 하니'),
    (31081, '이 첫째 부활에 참여하는 자들은 복이 있고 거룩하도다 둘째 사망이 그들을 다스리는 권세가 없고 도리어 그들이 하나님과 그리스도의 제사장이 되어 천 년 동안 그리스도와 더불어 왕 노릇 하리라'),
    (31082, '<사탄의 패망> ○천 년이 차매 사탄이 그 옥에서 놓여'),
    (31086, '<크고 흰 보좌에서 심판을 내리시다> ○또 내가 크고 흰 보좌와 그 위에 앉으신 이를 보니 땅과 하늘이 그 앞에서 피하여 간 데 없더라'),
    (31123, '<주 예수여 오시옵소서> ○또 그가 내게 말하기를 이 말은 신실하고 참된지라 주 곧 선지자들의 영의 하나님이 그의 종들에게 반드시 속히 되어질 일을 보이시려고 그의 천사를 보내셨도다'),
    (31125, '○이것들을 보고 들은 자는 나 요한이니 내가 듣고 볼 때에 이 일을 내게 보이던 천사의 발 앞에 경배하려고 엎드렸더니'),
    (31127, '○또 내게 말하되 이 두루마리의 예언의 말씀을 인봉하지 말라 때가 가까우니라'),
    (31133, '○나 예수는 교회들을 위하여 내 사자를 보내어 이것들을 너희에게 증언하게 하였노라 나는 다윗의 뿌리요 자손이니 곧 광명한 새벽 별이라 하시더라'),
    (31134, '○성령과 신부가 말씀하시기를 오라 하시는도다 듣는 자도 오라 할 것이요 목마른 자도 올 것이요 또 원하는 자는 값없이 생명수를 받으라 하시더라'),
    (31135, '○내가 이 두루마리의 예언의 말씀을 듣는 모든 사람에게 증언하노니 만일 누구든지 이것들 외에 더하면 하나님이 이 두루마리에 기록된 재앙들을 그에게 더하실 것이요'),
    (31136, '○만일 누구든지 이 두루마리의 예언의 말씀에서 제하여 버리면 하나님이 이 두루마리에 기록된 생명나무와 및 거룩한 성에 참여함을 제하여 버리시리라'),
    (31137, '○이것들을 증언하신 이가 이르시되 내가 진실로 속히 오리라 하시거늘 아멘 주 예수여 오시옵소서'),
    (31138, '○주 예수의 은혜가 모든 자들에게 있을지어다 아멘'),
    (31098, '그러나 두려워하는 자들과 믿지 아니하는 자들과 흉악한 자들과 살인자들과 음행하는 자들과 점술가들과 우상 숭배자들과 거짓말하는 모든 자들은 불과 유황으로 타는 못에 던져지리니 이것이 둘째 사망이라'),
    (31099, '<새 예루살렘> ○일곱 대접을 가지고 마지막 일곱 재앙을 담은 일곱 천사 중 하나가 나아와서 내게 말하여 이르되 이리 오라 내가 신부 곧 어린 양의 아내를 네게 보이리라 하고')
) as v(id, sentence)
where b."id" = v.id;

-- 2) 책 이름 깨짐 교정 1행
update "public"."bible" set "long_label" = '누가복음', "short_label" = '눅' where "id" = 25146;

-- 3) 원본에는 있으나 DB에 없던 절 14행 추가
--    "(18절과 동일)"·"(상동)"·"내용 없음" 같은 표기도 원본 그대로 넣는다 (구절 픽커에서 빈 화면 방지)
-- 빈 테이블(로컬 db reset 직후)에서는 넣지 않는다 — 그 경우 seed 가 전량을 적재하므로
-- 여기서 먼저 넣으면 seed 의 같은 id 와 충돌한다. 원격은 데이터가 있으므로 정상 실행된다.
insert into "public"."bible" ("id", "cate", "book", "chapter", "paragraph", "sentence", "testament", "long_label", "short_label")
select v.* from (values
    (31139::bigint, 1::bigint, 5::bigint, 6::bigint, 19::bigint, '(18절과 동일)', '구', '신명기', '신'),
    (31140, 1, 5, 15, 5, '네 하나님 여호와께서 네게 기업으로 주신 땅에서 네가 반드시 복을 받으리니 너희 중에 가난한 자가 없으리라', '구', '신명기', '신'),
    (31141, 1, 5, 30, 10, '(9절과 동일)', '구', '신명기', '신'),
    (31142, 1, 13, 16, 13, '(12절과 동일)', '구', '역대상', '대상'),
    (31143, 1, 19, 92, 2, '주의 이름을 찬양하고 아침마다 주의 인자하심을 알리며', '구', '시편', '시'),
    (31144, 1, 19, 92, 3, '밤마다 주의 성실하심을 베풂이 좋으니이다', '구', '시편', '시'),
    (31145, 1, 19, 105, 6, '그가 행하신 기적과 그의 이적과 그의 입의 판단을 기억할지어다', '구', '시편', '시'),
    (31146, 1, 24, 32, 4, '입이 입을 대하여 말하고 눈이 서로 볼 것이며 그가 시드기야를 바벨론으로 끌어 가리니 시드기야는 내가 돌볼 때까지 거기에 있으리라', '구', '예레미야', '렘'),
    (31147, 1, 24, 32, 5, '여호와께서 이와 같이 말씀하시니라 너희가 갈대아인과 싸울지라도 승리하지 못하리라 하셨다 하였더니 유다 왕 시드기야가 이르되 네가 어찌하여 이같이 예언하였느냐 하고 그를 가두었음이었더라', '구', '예레미야', '렘'),
    (31148, 1, 24, 33, 11, '(10절과 동일)', '구', '예레미야', '렘'),
    (31149, 1, 26, 24, 5, '그 뼈를 위하여 가마 밑에 나무를 쌓아 넣고 잘 삶되 가마 속의 뼈가 무르도록 삶을지어다', '구', '에스겔', '겔'),
    (31150, 2, 44, 15, 26, '(상동)', '신', '사도행전', '행'),
    (31151, 2, 44, 24, 7, '(6하반-8상반 없음)', '신', '사도행전', '행'),
    (31152, 2, 45, 9, 2, '내용 없음', '신', '로마서', '롬')
) as v("id", "cate", "book", "chapter", "paragraph", "sentence", "testament", "long_label", "short_label")
where exists (select 1 from "public"."bible")
on conflict ("id") do nothing;

-- 4) paragraph=0 행 50행 삭제
--    45행은 구역 제목으로 쪼개진 하반절 조각으로, 교정된 정상 절에 전문이 이미 포함된다
--    5행은 시편 권 구분 표시("시1:제일권" 등)로 원본에 없는 정보다
delete from "public"."bible" where "id" in (
    1035, 7298, 7501, 8055, 8304, 8523, 8569, 9634, 10229, 11193, 12305, 13948, 14565, 15031, 15390, 15709, 16668, 17114, 17649, 17659, 17976, 18000, 18022, 18054, 18065, 18068, 18074, 18100, 18246, 18819, 18840, 19050, 19520, 20304, 22536, 23072, 23177, 24441, 25316, 25374, 26022, 26251, 26649, 26857, 27212, 27271, 27319, 28391, 28747, 29783
);
